P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe bittet Euch, die leuchtenden Ritualkreise unter Sonnengrund zu zerschlagen. Das Licht macht ihn krank, und er fürchtet Chogg'Zacs Zorn, wenn er allein handelt.",h="Clubtoe bittet Euch, die leuchtenden Ritualkreise unter Sonnengrund zu zerschlagen.",kw={"höhlen","chogg'zac","clubtoe","licht","glänzende bilder","krank machende lichter","sonnengrund","zwielicht-ritualkreise"},sec={{t="Ein krank machendes Leuchten",b="Clubtoe arbeitet in den Höhlen unter Sonnengrund und zerschlägt Gestein für Chogg'Zac. Er entdeckt leuchtende Lichter im Stein, und die anderen malen Bilder damit. Das Leuchten macht Clubtoe krank, doch er fürchtet, Chogg'Zac werde ihn bestrafen, wenn er die Bilder zerstört. Ihr sollt die Twilight Ritual Circles zerstören, und Clubtoe hofft, dass ihn das Licht dann nicht mehr plagt."}},faq={{q="Wer bittet mich, die Kreise zu zerstören?",a="Clubtoe bittet Euch, die Twilight Ritual Circles unter Sonnengrund zu zerstören.",al={"wer ist clubtoe","clubtoe-quest","wer will die lichter zerschlagen"}},{q="Warum will Clubtoe die Lichter zerschlagen?",a="Das Licht macht Clubtoe krank, und er will die leuchtenden Bilder zerschlagen.",al={"warum die lichter zerschlagen","lichter machen clubtoe krank","clubtoe hasst licht"}},{q="Wer ist Chogg'Zac?",a="Chogg'Zac ist Clubtoes Boss, und Clubtoe fürchtet, er werde wütend, wenn die Kreise zerstört werden.",al={"chogg zac","clubtoes boss","großer boss"}},{q="Was sind die glänzenden Bilder?",a="Es sind Twilight Ritual Circles, die überall in den Höhlen unter Sonnengrund zu finden sind. Clubtoe nennt sie leuchtende Bilder.",al={"glänzende bilder","zwielichtkreise","was sind die lichter"}},{q="Was tut Clubtoe in den Höhlen?",a="Clubtoe zerschlägt Gestein für Chogg'Zac und hat leuchtendes Licht im Stein entdeckt.",al={"clubtoes arbeit","gestein zerschlagen","was macht clubtoe"}},{q="Geht es Clubtoe besser, nachdem die Kreise zerschlagen sind?",a="Nachdem Ihr die Kreise zerschlagen habt, sagt Clubtoe, dass es ihm schon besser geht.",al={"clubtoe abschließen","hat das zerschlagen geholfen","lichter machen ihn gesund"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Ein Trupp Soldaten der Kul Tiraner durchsucht das Tal, und sein Ziel ist unbekannt. Sie haben nahe einer zerstörten Karawane im Süden ihr Lager aufgeschlagen und damit die Aufmerksamkeit örtlicher Späher erregt.",h="Ein Trupp Soldaten der Kul Tiraner durchsucht das Tal, und sein Ziel ist unbekannt.",kw={"karawane","kul tiras","soldaten","trouble in the valley","tal","zerstörte karawane"},ang={["race:Human"]="Als Mensch erkennt Ihr vielleicht das Meergrün und die Ankerfarben von Kul Tiras. Soldaten aus dieser zurückgezogen lebenden Seefahrernation sind im Tal ein seltener und unerwarteter Anblick."},sec={{t="Verdächtige Aktivitäten im Tal",b="Ein Schütze, der das Tiefland beobachtete, entdeckte menschliche Soldaten, die den Talboden durchsuchten. Durch sein Zielfernrohr erkannte er die Wappen und Uniformen von Kul Tiras. Bewaffnete Fremde gehen hier selten so offen vor, und ihre Anwesenheit hat Alarm ausgelöst."},{t="Die zerstörte Karawane",b="Die Soldaten haben nahe einer zerstörten Karawane im Süden ihr Lager aufgeschlagen. Was sie zwischen den Trümmern suchen, bleibt unbekannt. Örtliche Beobachter betrachten ihre bewaffnete Anwesenheit als unmittelbare Bedrohung, weshalb Ermittler entsandt werden, um sie auszuschalten und den Zweck ihrer Suche aufzudecken."}},faq={{q="Was machen Soldaten der Kul Tiraner im Tal?",a="Ein Scharfschütze entdeckte Soldaten der Kul Tiraner, die das Tal unter ihm durchsuchten. Sie schlugen nahe einer zerstörten Karawane im Süden ihr Lager auf, und örtliche Späher werden entsandt, um ihr Ziel zu ergründen.",al={"warum kul tiraner hier","soldaten von kul tiras im tal","was machen kul tiraner"}},{q="Wo befindet sich das Lager der Kul Tiraner?",a="Die Soldaten der Kul Tiraner lagern nahe einer zerstörten Karawane südlich des Aussichtspunkts über dem Tal.",al={"standort der zerstörten karawane","wo ist das lager von kul tiras","standort der karawane"}},{q="Wie wurde die Anwesenheit der Kul Tiraner entdeckt?",a="Ein Späher, der das Tal beobachtete, betrachtete die Menschengruppe durch ein Gewehrzielfernrohr und erkannte Kul Tiras an ihren Uniformen und Abzeichen.",al={"wie wurden sie identifiziert","uniformen von kul tiras"}},{q="Was ist das Ziel der Untersuchung des Lagers?",a="Ihr werdet nach Süden zur zerstörten Karawane geschickt, um die Soldaten der Kul Tiraner zu stellen und herauszufinden, weshalb sie das Gebiet durchsuchen.",al={"was ist das ziel","trouble in the valley ziele"}},{q="Warum werden die Soldaten der Kul Tiraner als Feinde behandelt?",a="Die Soldaten sind bewaffnete Fremde, die ohne Erklärung das Land um eine zerstörte Karawane durchsuchen. Späher sehen in ihnen eine Bedrohung, die bezwungen werden muss, damit ihre Absichten aufgedeckt werden können.",al={"warum gegen kul tiras kämpfen","sind kul tiraner feindselig"}},{q="Wer entdeckte die Soldaten im Tal?",a="Walton, der einsiedlerische Gerber, der das Tal beobachtet, entdeckte die Soldaten durch sein Gewehrzielfernrohr. Er heuerte einen Abenteurer an, um sie auszuschalten und herauszufinden, warum sie dort waren.",al={"wer entdeckte die soldaten","wer gab die quest"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel der Sumpfhüter spürt Verderbnis, die durch eine Bergschlucht ins Süßwasser des Sumpflands fließt. Er schickt Euch zu den Ausgrabungsstätten im Hochland, um den Root Core eines Highland Horrors zu holen, und warnt dann, dass die Grabungen eine uralte Energie aufrütteln und die ganze Region gefährden.",h="Rethiel der Sumpfhüter spürt Verderbnis, die durch eine Bergschlucht ins Süßwasser des Sumpflands fließt.",kw={"verderbnis","ausgrabungsstätten","highland horror","horrors in the highland","rethiel","rethiel der sumpfhüter","root core","sumpfland"},ang={["class:Druid"]="Als Druide könnt Ihr spüren, wie sich das natürliche Gleichgewicht durch Wurzeln und Wasserläufe hindurch verschiebt. Ihr erkennt womöglich, wie plötzlich uralte Verderbnis das Leben im Süßwasser bedroht.",["faction:Alliance"]="Als Forscher der Allianz wisst Ihr, dass die Erzsucher an den Ausgrabungsstätten in den Bergen Gefahr laufen, uralte Kräfte unter der Erde aufzurütteln.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Grabungen im Hochland mehr als nur uralte Relikte aufgestört haben. Rethiel drängt die Ausgräber, aufzuhören, bevor schlimmere Übel erwachen."},sec={{t="Verderbnis in der Schlucht",b="Rethiel der Sumpfhüter spürt tief im Sumpfland, wie sich das Land verändert. Durch eine Bergschlucht gelangt üble Verderbnis ins Hochland und befällt die dortigen Süßwasserkreaturen. Das Leben im Tiefland wurde vom Brackwasser geprägt, doch diese Kreaturen haben das schützende Salz des Meeres nie kennengelernt. Rethiel fürchtet, dass sie dem sich ausbreitenden Übel nicht standhalten können. Er bittet Euch, zu den Ausgrabungsstätten hinaufzusteigen, einen Highland Horror zu erschlagen und seinen Root Core zurückzubringen."},{t="Eine uralte Regung",b="Als Ihr Rethiel den Root Core des Highland Horrors bringt, bestätigt er seine Befürchtungen: Eine uralte Energie hat begonnen, sich zu regen. Die Kreaturen des Hochlands leiden an keiner gewöhnlichen Krankheit. Die jüngsten Grabungen haben das Leiden ausgelöst. Rethiel warnt die Ausgräber, sofort aufzuhören. Ihre Neugier könnte etwas weit Schlimmeres auf das Sumpfland loslassen und alle in der Region gefährden."}},faq={{q="Wer bietet die Quest Horrors in the Highland an?",a="Rethiel der Sumpfhüter, ein uralter Beschützer des Sumpflands, bietet die Aufgabe an, nachdem er Verderbnis gespürt hat, die durch eine nahe Bergschlucht sickert.",al={"wer vergibt horrors in the highland","horrors in the highland questgeber","rethiel quest"}},{q="Wo sind Highland Horrors zu finden?",a="Highland Horrors leben an den Ausgrabungsstätten im höher gelegenen Gelände oberhalb des Tieflands, nahe der Bergschlucht, durch die Verderbnis sickert.",al={"wo sind highland horrors","highland horror fundort","wo highland horror finden"}},{q="Warum sind die Kreaturen des Hochlands so anfällig für Verderbnis?",a="Die Süßwasserkreaturen des Hochlands haben das schützende Salz des Meeres nie kennengelernt und sind der sich ausbreitenden Verderbnis daher wehrlos ausgeliefert.",al={"warum sind die kreaturen verderbt","warum sind hochlandkreaturen verderbt","ungesalzenes wasser verderbnis"}},{q="Was ist der Root Core eines Highland Horrors?",a="Der Root Core eines Highland Horrors ist das Herz der verderbten Kreatur. Rethiel braucht ihn, um die unnatürliche Macht zu untersuchen, die sich durch die Wasserläufe ausbreitet, und das Wesen der Verderbnis zu ergründen.",al={"was ist der root core","highland horror root core","warum den root core mitnehmen"}},{q="Was entdeckt Rethiel, wenn Ihr den Root Core zurückbringt?",a="Als Ihr den Root Core zurückbringt, entdeckt Rethiel, dass sich tief in der Erde eine uralte Energie zu regen beginnt, vermutlich durch die Grabungen an den Ausgrabungsstätten aufgerüttelt.",al={"was entdeckt rethiel","uralte energie sumpfland","gefahr durch ausgrabungen"}},{q="Warum will Rethiel, dass die Ausgräber ihre Grabungen einstellen?",a="Rethiel warnt die Ausgräber, zu ihrer eigenen Sicherheit sofort mit den Grabungen aufzuhören. Ihre Arbeit droht gefährliche uralte Kräfte freizusetzen.",al={"grabungen einstellen rethiel","was sollen die ausgräber tun","zwerg ausgrabungsstätte warnung"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="Ardin Grassman wird nahe einer Ausgrabungsstätte vermisst, nachdem er Berichten über hoch aufragende Gräser gefolgt war. Seine Frau, eine Alchemistin, bittet Reisende, ihn zu finden, da gefährliche Wildtiere die Mannschaft angegriffen haben.",h="Ardin Grassman wird nahe einer Ausgrabungsstätte vermisst, nachdem er Berichten über hoch aufragende Gräser...",kw={"alchemie","ardin","ardin grassman","ausgrabungsstätten","kräuterkunde","lost in the thicket things","spinnen","hoch aufragende gräser"},ang={["class:Druid"]="Als Druide erkennt Ihr vielleicht Ardins Gabe, Pflanzen zu erspüren. Die Wildtiere nahe den Ausgrabungsstätten sind in Aufruhr geraten und stören das Gleichgewicht der Wildnis.",["profession:Herbalism"]="Als Kräuterkundiger erkennt Ihr vielleicht Ardin Grassmans Gabe, Pflanzen und Kräuter zu erspüren. Er klettert oft durch schwieriges Gelände, um seltene Pflanzen für die Alchemie zu sammeln."},sec={{t="Die Berufung eines Sammlers",b="Ardin Grassmans Frau, eine Alchemistin, bittet Euch, ihren vermissten Mann zu finden. Er hat ein feines Gespür für die Natur und wagt sich oft an Klippen und in entlegene Wildnis, um Kräuter und Pflanzen für ihre Arbeit zu sammeln. Als eine Ausgrabungsmannschaft von hoch aufragenden Gräsern berichtete, wie sie noch niemand von ihnen gesehen hatte, zog Ardins Neugier ihn zur Ausgrabungsstätte."},{t="Hinterhalt an der Ausgrabungsstätte",b="Ardin erreichte die Ausgrabungsstätte und fand die Mannschaft in Gefahr vor. Das umliegende Land hatte die heimischen Wildtiere in Aufruhr versetzt, und feindselige Spinnen fielen in Scharen über die Ausgrabungsmannschaft her. Ardin und die Mannschaft waren von den angreifenden Bestien eingeschlossen, bis Reisende ihnen zu Hilfe kamen."}},faq={{q="Wer ist Ardin Grassman?",a="Ardin Grassman sammelt Kräuter und besitzt ein seltenes Gespür für Pflanzen. Er sucht oft an Klippen und auf Gipfeln nach Wildpflanzen, um seine Frau für ihre Alchemie zu versorgen. Gerüchte über hoch aufragende Gräser zogen ihn zu einer Ausgrabungsstätte.",al={"wer ist ardin","ardin grassman geschichte","wer ist ardin grassman"}},{q="Warum zog Ardin in die Wildnis?",a="Ardin hörte eine Ausgrabungsmannschaft hoch aufragende Gräser beschreiben, wie sie noch niemand von ihnen gesehen hatte. Sein Gespür für ungewöhnliche Pflanzen trieb ihn hinaus, um sie zu sehen, und er kehrte nicht nach Hause zurück.",al={"warum ging ardin fort","warum wird ardin vermisst","wonach suchte ardin"}},{q="Wohin ging Ardin?",a="Ardin machte sich zu den nahe gelegenen Excavation Sites auf, nachdem er den Bericht einer vorbeiziehenden Mannschaft gehört hatte. Durchsucht die Ausgrabungsstätten, an denen die Mannschaft ihr Lager aufgeschlagen hat.",al={"wo ist ardin","ardin aufenthaltsort","wo ist ardin grassman zu finden"}},{q="Was geschah mit Ardin an der Ausgrabungsstätte?",a="Ardin erreichte das Ausgrabungslager, als die heimischen Wildtiere aggressiv wurden. Riesige Spinnen und andere Bestien überfielen die Mannschaft und schlossen Ardin mit ihr ein, bis Reisende eintrafen, um zu helfen.",al={"was geschah mit ardin","ist ardin tot","was griff ardin an"}},{q="Wer sucht nach Ardin?",a="Ardins Frau, eine Alchemistin, sucht nach ihm. Er sammelte Kräuter für ihre Vorräte, kehrte aber nicht zurück, nachdem er Berichten über seltsames Gras nachgegangen war. Also bat sie Reisende, ihn zu finden.",al={"wer vergibt lost in the thicket things","wer hat diese quest begonnen","ardins frau"}},{q="Warum griffen die Wildtiere die Ausgrabungsmannschaft an?",a="Die Ursache für die plötzliche Unruhe der Wildtiere nahe den Ausgrabungsstätten ist unbekannt. Aggressive Kreaturen, besonders Spinnen, fielen in Scharen über die Ausgrabungsmannschaft her und überwältigten sie.",al={"warum greifen spinnen an","was hat die tiere aufgebracht","warum sind die bestien wütend"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="Die Todespirscher suchen genauere Kunde über die Magie der Dragonmaw, von der im Sumpfland Gerüchte umgehen. Ihr werdet entsandt, um ihre Agentin in den Hügeln oberhalb des Clanlagers zu treffen.",h="Die Todespirscher suchen genauere Kunde über die Magie der Dragonmaw, von der im Sumpfland Gerüchte umgehen.",kw={"zerbrochene symbole","deathstalker agentin","deathstalkers","drachenbindung","dragonmaw","lager der dragonmaw","gerüchte über dragonmaw","sumpfland"},sec={{t="Gerüchte im Sumpfland",b="Ein Deathstalker im Sumpfland braucht Eure Hilfe, während sich Gerüchte um den Clan der Dragonmaw mehren. Sie sollen über Magie gebieten, die Drachen bindet, und angeblich bereiten sie eine Vorführung dieser Macht vor. Zerbrochene Symbole lieferten keine eindeutigen Beweise, also werdet Ihr entsandt, um eine Agentin in den Hügeln oberhalb ihres Lagers zu treffen."}},faq={{q="Was haben die Dragonmaw den Gerüchten zufolge vor?",a="Dem Gerücht zufolge bereiten die Dragonmaw eine Vorführung von Magie vor, die mächtig genug ist, Drachen zum Dienen zu zwingen.",al={"gerüchte über dragonmaw","was planen die dragonmaw","magie der dragonmaw"}},{q="Warum brauchen die Todespirscher Hilfe?",a="Die Todespirscher haben nur zerbrochene Symbole und vage Gerüchte über die Dragonmaw, daher braucht eine Agentin in den Hügeln oberhalb des Clanlagers Unterstützung.",al={"deathstalker braucht hilfe","warum den deathstalkers helfen","was brauchen sie"}},{q="Wo ist die Agentin der Todespirscher?",a="Die Agentin befindet sich in den Hügeln oberhalb des Lagers der Dragonmaw im Sumpfland.",al={"aufenthaltsort der agentin","wo die agentin treffen","deathstalker agentin hügel"}},{q="Was verrieten die zerbrochenen Symbole?",a="Die zerbrochenen Symbole lieferten nur vage Hinweise auf eine angeblich geplante Magievorführung der Dragonmaw.",al={"zerbrochene symbole","was die symbole zeigten","symbole dragonmaw"}},{q="Was geschieht, wenn Ihr die Agentin trefft?",a="Die Agentin der Todespirscher wird Euch die nächsten Schritte offenbaren, wenn Ihr sie in den Hügeln oberhalb des Lagers der Dragonmaw trefft.",al={"die agentin treffen","nächste schritte","was sagt die agentin"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="Ein seltsames Relikt der Titanen streut Licht wie ein lebendes Prisma, doch seine Natur bleibt ungewiss. Ihr bringt es zur Anhöhe der Ältesten in Donnerfels, um jemanden zu suchen, der seine uralte Macht erklären kann.",h="Ein seltsames Relikt der Titanen streut Licht wie ein lebendes Prisma, doch seine Natur bleibt ungewiss.",kw={"uralte macht","zusammengesetzter splitter","elder knowledge","die anhöhe der ältesten","lebendes prisma","donnerfels","relikt der titanen"},sec={{t="Ein Splitter aus Licht",b="Der ungewöhnliche zusammengesetzte Splitter in Eurem Besitz streut Licht wie ein lebendes Prisma. Seine Natur ist ungewiss, doch seine Macht wirkt uralt. Ihr bringt das Relikt der Titanen zur Anhöhe der Ältesten in Donnerfels und sucht jemanden, der Euch mehr darüber erzählen kann."}},faq={{q="Was ist das Relikt der Titanen?",a="Es ist ein ungewöhnlicher zusammengesetzter Splitter, der Licht wie ein lebendes Prisma streut. Seine Natur ist ungewiss, doch seine Macht wirkt uralt.",al={"relikt der titanen","was ist das relikt","prismensplitter"}},{q="Wohin bringe ich das Relikt der Titanen?",a="Bringt das Relikt der Titanen zur Anhöhe der Ältesten in Donnerfels und sucht jemanden, der es erklären kann.",al={"wohin mit dem relikt","anhöhe der ältesten relikt","donnerfels splitter"}},{q="Warum trage ich den Splitter bei mir?",a="Ihr sucht auf der Anhöhe der Ältesten jemanden, der Euch mehr über das Relikt der Titanen erzählen kann.",al={"warum dieses relikt","was mit dem splitter tun","elder knowledge quest"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="Ein Deathstalker Agent bittet Euch, die Dragonmaw aus den Excavation Sites zu vertreiben und alles Bemerkenswerte zurückzubringen. Der Klan sucht womöglich einen Weg zurück zur Macht.",h="Ein Deathstalker Agent bittet Euch, die Dragonmaw aus den Excavation Sites zu vertreiben und alles...",kw={"dark lady","deathstalker agent","dragonmaw","excavation site","verlassene","orkische kritzelei","rend"},sec={{t="Ein unauffälliges Vorgehen",b="Ein Deathstalker Agent außerhalb der Excavation Site will die Streitkräfte der Dragonmaw vertreiben lassen. Die Überreste des Klans, der einst Drachen bändigte, glauben, etwas gefunden zu haben, das ihre frühere Macht wiederherstellen könnte. Ihr zusammengewürfelter Haufen muss verschwinden, damit die Todespirscher unbemerkt eindringen können. Bringt alles Bemerkenswerte zurück, das Ihr findet, und behaltet die Angelegenheit zwischen dem Agenten und der königlichen Führung."},{t="Die geborgene Kritzelei",b="Der Deathstalker Agent erkennt die orkische Schrift unter den geborgenen Gegenständen. Sie zeigt, dass die Dragonmaw hoffen, Rend, ihren falschen Kriegshäuptling, zu besänftigen. Der Agent nennt das Unterfangen aussichtslos, doch das Wissen ist für die Dark Lady wertvoll. Der Agent überlässt Euch die geborgenen Gegenstände und warnt Euch, nichts über die Mission zu sagen."}},faq={{q="Wer hat mich zur Excavation Site geschickt?",a="Ein Deathstalker Agent außerhalb der Excavation Site bittet Euch, die Dragonmaw zu vertreiben und alles Bemerkenswerte zurückzubringen.",al={"wer will die dragonmaw vertreiben","auftrag des deathstalker agent","wer hat mich geschickt"}},{q="Was hoffen die Dragonmaw zu erreichen?",a="Die Überreste der Dragonmaw glauben, etwas gefunden zu haben, das ihre frühere Macht wiederherstellen könnte.",al={"plan der dragonmaw","warum sind die dragonmaw hier","dragonmaw zurück zur macht"}},{q="Warum wollen die Todespirscher das Gelände räumen lassen?",a="Sie wollen unbemerkt in die Excavation Site eindringen.",al={"warum excavation site räumen","deathstalkers rücken ein","was brauchen sie"}},{q="Was soll ich zurückbringen?",a="Bringt dem Deathstalker Agent alles Bemerkenswerte, das Ihr bei den Dragonmaw findet.",al={"was bergen","gegenstände der dragonmaw","was will der agent"}},{q="Wer ist die Dark Lady?",a="Der Agent verwendet diesen Titel für Sylvanas, die die Verlassenen anführt.",al={"bedeutung von dark lady","wer ist die dark lady","sylvanas titel"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Ein neues Gericht bei Borstan's Firepit könnte Reisende nach Orgrimmar locken. Zamjas Rat und Geschichten über riesige Raptorkrallen bringen Borstan dazu, Dickichtraptorfleisch aus dem Sumpfland jenseits des Meeres zu suchen.",h="Ein neues Gericht bei Borstan's Firepit könnte Reisende nach Orgrimmar locken.",kw={"borstan","borstan's firepit","changing tastes","ausgrabungsstätten","orgrimmar","dickichtraptor","dickichtraptorfleisch","sumpfland","zamja"},ang={["faction:Horde"]="Wer Borstan's Firepit beliefert, muss über das Meer ins umkämpfte Sumpfland reisen, um exotisches Fleisch nach Orgrimmar zurückzubringen.",["profession:Cooking"]="Borstan hofft, rustikale Mahlzeiten für die Hauptstadt der Horde zu veredeln, während sich Geschmack und Wirtshausspeisekarten über die üblichen Dorfgerichte hinausentwickeln."},sec={{t="Gehobene Küche der Hauptstadt",b="Borstan's Firepit in Orgrimmar möchte seine Speisekarte erweitern. Zamja empfiehlt Raptorgerichte nach Hausmacherart für Reisende, die die vertrauten Mahlzeiten ihrer Heimatdörfer vermissen. Borstan gefällt der Gedanke, mit Raptorfleisch neue Gäste anzulocken, doch einfache Dorfkost erscheint ihm für die große Hauptstadt der Horde zu bescheiden. Er möchte eine gewagtere Variante des altbekannten Grundgerichts."},{t="Die Jagd im Sumpfland",b="Ein Jäger kehrt mit einer gewaltigen Kralle eines Dickichtraptors von den Ausgrabungsstätten im Sumpfland nach Orgrimmar zurück. Die Größe und Qualität des Tieres wecken Borstans Interesse. Er lässt Abenteurer über das Meer in die Östlichen Königreiche reisen, den Gefahren der Ausgrabungsstätten trotzen und erstklassiges Dickichtraptorfleisch für seine Feuer zurückbringen."}},faq={{q="Was ist die Quest Changing Tastes?",a="Changing Tastes ist eine kulinarische Aufgabe in Orgrimmar. Borstan, der Besitzer von Borstan's Firepit, sucht Dickichtraptorfleisch aus dem fernen Sumpfland, um seine Speisekarte über einfache Dorfküche hinauszuheben.",al={"was ist changing tastes","changing tastes quest"}},{q="Wer ist Zamja?",a="Zamja ist eine Bekannte und Berufskollegin, die Raptorgerichte nach Hausmacherart für Borstan's Firepit vorschlägt und damit Gäste anlocken möchte, die sonst nicht dort einkehren.",al={"wer ist zamja","zamja kochen"}},{q="Was ist Borstan's Firepit?",a="Borstan's Firepit ist eine Gaststätte in Orgrimmar, der Hauptstadt der Horde. Sie serviert Einheimischen wie Reisenden gleichermaßen herzhafte Fleischgerichte.",al={"borstan's firepit","wo ist borstan"}},{q="Warum möchte Borstan Dickichtraptorfleisch?",a="Borstan möchte vertraute Aromen auf großartigere Weise darbieten als mit Zamjas Raptorgerichten nach Hausmacherart. Die Erzählung eines Jägers über riesige Krallen bringt ihn dazu, Dickichtraptorfleisch aus dem Sumpfland zu suchen.",al={"warum raptorfleisch","warum dickichtraptor"}},{q="Wo leben die Dickichtraptoren?",a="Dickichtraptoren leben an Ausgrabungsstätten im Sumpfland, einer der Allianz zugeneigten Region jenseits des großen Meeres in den Östlichen Königreichen.",al={"wo gibt es dickichtraptoren","sumpfland ausgrabungsstätten raptor"}},{q="Wer vergibt die Quest Changing Tastes?",a="Borstan, der Wirt von Borstan's Firepit in Orgrimmar, bietet Changing Tastes an, nachdem Zamjas Rat und die mitgebrachte Trophäe eines abenteuerlustigen Jägers ihn inspirieren.",al={"wer vergibt changing tastes","borstan questgeber"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="In Bashal'Aran ist Asterions Geist noch immer durch ein uraltes Siegel gebunden. Ihr tragt das Siegel nach Süden nach Ameth'Aran, wo eine alte Flamme seine Fesseln brechen könnte.",h="In Bashal'Aran ist Asterions Geist noch immer durch ein uraltes Siegel gebunden.",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","dunkelküste","hochgeborene","mondsteinsiegel"},ang={["class:Mage"]="Als Magier erahnt Ihr die rohe arkane Macht der uralten Zauberer der Highborne in den Verzauberungen, die Asterion binden, und den Flammen, die in Ameth'Aran fortbestehen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, uralte Flüche in der Dunkelküste zu bannen und die Grenzen für neue Nachtelfensiedlungen zu sichern, die sich von Auberdine aus ausbreiten.",["race:NightElf"]="Für die Nachtelfen des modernen Kalimdor ist die Befreiung Asterions eine ernüchternde Begegnung mit der Vergangenheit ihres Volkes vor der Zerschlagung und dem fortwirkenden Verderben des Adels der Hochgeborenen von Königin Azshara."},sec={{t="Ein Kerker uralter Zauberei",b="Das Alte Mondsteinsiegel wurde vor der Zerschlagung von Zauberern der Hochgeborenen geschmiedet, und keine gewöhnliche Kraft kann seine Macht brechen."},{t="Zwillingsruinen der Dunkelküste",b="Bashal'Aran und Ameth'Aran waren Schwestersiedlungen der kaldorei unter Königin Azshara, als der Brunnen der Ewigkeit ihrem Reich Halt gab. Heute sind beide überwucherte, heimgesuchte Ruinen, in denen Geister verweilen und arkane Macht unberechenbar bleibt. In Ameth'Aran brennt ein mystisches Kohlenbecken mit cyanblauem Feuer in einem steinernen Pavillon; dies ist die einzige Flamme, die das Alte Mondsteinsiegel verzehren kann."},{t="Die Rache erwacht",b="Nachdem das Siegel zerstört ist, ist Asterion endlich befreit und blickt auf ein zerschlagenes Kalimdor, das sich gegenüber dem goldenen Zeitalter seiner Erinnerung grundlegend gewandelt hat. Doch seine Freiheit bringt ihm keinen Frieden. Als er spürt, dass sein einstiger Meister und Kerkermeister, der Hochgeborene Athrikus, noch immer fortbesteht, wandelt sich Asterions uralte Verzweiflung rasch in einen kalten, brennenden Hunger nach Rache."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein Nachtelfengeist, der in den Ruinen von Bashal'Aran gefangen ist. Seine Geschichte reicht zehntausend Jahre bis in die Herrschaft von Königin Azshara zurück, und er ist durch ein Siegel an die Ruinen gebunden, das von einem der mächtigsten der Hochgeborenen gefertigt wurde.",al={"asterion","wer ist der geist","nsc asterion"}},{q="Wo zerstöre ich das Alte Mondsteinsiegel?",a="Das Siegel muss nach Süden nach Ameth'Aran gebracht werden, der Zwillingsruine von Bashal'Aran. Haltet Ausschau nach einem steinernen Pavillon, der eine große kubische Feuerschale beherbergt, in der ein uraltes, grünlich-blaues magisches Feuer brennt.",al={"wo ist die flamme","standort der uralten flamme","siegel zerstoeren"}},{q="In welcher Beziehung stehen Bashal'Aran und Ameth'Aran zueinander?",a="Sie waren Schwesterstädte des uralten Nachtelfenreiches vor der Zerschlagung. Beide fielen vor zehntausend Jahren der Verwüstung anheim und hinterließen heimgesuchte Steinsäulen, arkane Restenergien und rastlose Geister.",al={"zwillingsruinen","verbindung zu ametharan","bashalaran ametharan"}},{q="Wer kerkerte Asterion ein?",a="Asterion berichtet, dass einer der mächtigsten Hochgeborenen das Siegel schuf, das ihn bindet. Mehr über seinen einstigen Meister wird im Verlauf der Questreihe enthüllt.",al={"wer kerkerte asterion ein","wer ist athrikus","meister von asterion"}},{q="An welches Zeitalter erinnert sich Asterion?",a="Asterion wandelte zuletzt auf der Welt, als der ursprüngliche Brunnen der Ewigkeit noch existierte, Königin Azshara das Reich regierte und der Adel der Hochgeborenen vor der Zerschlagung seine majestätischen Höfe abhielt.",al={"vergangenheit von asterion","aera des brunnens der ewigkeit","wie alt ist asterion"}},{q="Findet Asterions Geist durch seine Befreiung Ruhe?",a="Die Zerstörung des Siegels soll Asterions Gefängnis aufheben. Seine Reaktion auf die Freiheit offenbart sich, wenn Ihr zu ihm zurückkehrt.",al={"findet asterion frieden","was geschieht mit asterion","asterion nach der befreiung"}}},fx={["8275c861"]={q="Warum möchte Asterion, dass das Alte Mondsteinsiegel zerstört wird?",a="Das Alte Mondsteinsiegel ist der Anker, der Asterions Geist in den Ruinen von Bashal'Aran in Qualen bindet. Vor Jahrtausenden durch mächtige Hochgeborenen-Zauberei erschaffen, hält es ihn gefangen und blind für die Welt da draußen. Es im mystischen alten Feuer von Ameth'Aran zu zerstören, ist der einzige Weg, seine ätherischen Ketten zu sprengen, was ihm Freiheit und die Klarheit gewährt, zu sehen, was aus Kalimdor geworden ist.",al={"warum mondsteinsiegel zerstören","asterion beweggrund","warum will asterion das siegel brechen"}},["51df5ddd"]={q="Warum benötigt Asterion Euch, um das Siegel nach Ameth'Aran zu bringen?",a="Gebunden durch die alte Hochgeborenen-Magie, die ihn an Bashal'Aran verankert, kann Asterion die unmittelbaren Ruinen nicht verlassen, geschweige denn nach Süden nach Ameth'Aran reisen. Er benötigt einen Reisenden, der das Siegel in das alte Feuer trägt.",al={"warum kann asterion das siegel nicht selbst zerstören","warum braucht asterion mich","warum einen abenteurer zur zerstörung des siegels schicken"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="Eine Alchemistin wartet auf Nachricht über ein seltenes Gras. Sie bittet Euch, Caitlin Grassman im Hafen von Menethil zu finden, deren Mann sich von einer Ausgrabung noch nicht zurückgemeldet hat.",h="Eine Alchemistin wartet auf Nachricht über ein seltenes Gras.",kw={"alchemistin","caitlin grassman","ausgrabung","grassamen","hafen von menethil","urgras","seeking caitlin","sumpfland"},ang={["profession:Herbalism"]="Als Kräuterkundiger werdet Ihr gebeten, nach Caitlin zu sehen, nachdem das Team ihres Mannes Spuren eines seltenen Urgrases gefunden hat."},sec={{t="Ein ausstehender Bericht",b="Die Alchemistin hat von Caitlin erfahren, dass das Ausgrabungsteam ihres Mannes Spuren eines Urgrases gefunden hat. Caitlin weiß nicht, wie viel sie gefunden haben oder ob es erreichbar ist.\n\nNun bittet Euch die Alchemistin, mit Caitlin im Hafen von Menethil zu sprechen. Beide Frauen warten darauf zu erfahren, was aus den versprochenen Samen geworden ist."}},faq={{q="Wer ist Caitlin Grassman?",a="Caitlin Grassman ist eine Alchemistin im Hafen von Menethil. Ihr Mann schloss sich einem Ausgrabungsteam an, das Spuren eines Urgrases gefunden hat.",al={"caitlin","wer ist caitlin","caitlin grassman"}},{q="Was soll ich für die Alchemistin tun?",a="Die Alchemistin bittet Euch, mit Caitlin Grassman im Hafen von Menethil zu sprechen.",al={"caitlin finden","mit caitlin sprechen","caitlins quest"}},{q="Was hat das Ausgrabungsteam gefunden?",a="Das Team hat Spuren eines lange verschollenen Urgrases gefunden. Wie viel davon vorhanden ist und ob es erreichbar ist, bleibt unbekannt.",al={"urgras","seltenes gras","ausgrabungsfund"}},{q="Warum sind sie besorgt?",a="Caitlin versprach der Alchemistin, dass ihr Mann Grassamen mitbringen würde, doch bislang sind keine eingetroffen. Beide Frauen vermuten Schwierigkeiten an der Ausgrabungsstätte.",al={"wo sind die samen","fehlende grassamen","warum besorgt"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="Ein Trollgelehrter sucht eine Abreibung einer uralten Tafel nördlich des Finsteren Riffs. Ihre Legende könnte die Größe des verlorenen I'lalai verdeutlichen.",h="Ein Trollgelehrter sucht eine Abreibung einer uralten Tafel nördlich des Finsteren Riffs.",kw={"uralte ruine","gurubashi","i'lalai","legende","abreibung","tafel","troll","das finstere riff"},ang={["race:Troll"]="Als Troll werdet Ihr gebeten, einem Gelehrten beim Studium von Legenden über eine verlorene Trollstadt zu helfen."},sec={{t="Eine Tafel an der Küste",b="Der Gelehrte vergleicht ein Tafelfragment, das Ihr gebracht habt, mit den Ruinen vor dem Finsteren Riff. Diese Ruinen wirken zu klein für die weitläufige Zivilisation, die der Text beschreibt. Deshalb bittet Euch der Gelehrte, eine Abreibung einer Tafel in einer uralten Trollruine auf den Küstenhügeln im Norden anzufertigen."},{t="Eine alte Erinnerung",b="Der Gelehrte nimmt die Abreibung erfreut entgegen und sagt, die Tafel sei ihm aus seiner Jugend vertraut. Viele Monde sind vergangen, seit er sie zuletzt gelesen hat, und seine Erinnerung ist verblasst."}},faq={{q="Was möchte der Gelehrte?",a="Der Gelehrte möchte eine Abreibung einer Tafel mit Legenden über die verlorene Trollstadt I'lalai.",al={"tafelabreibung","was braucht er","bitte um abreibung"}},{q="Wo ist die Tafel?",a="Sie befindet sich in einer uralten Trollruine auf den Küstenhügeln nördlich des Finsteren Riffs.",al={"fundort der tafel","wo ist die tafel","nördlich des riffs"}},{q="Warum möchte der Gelehrte eine Abreibung?",a="Ein Tafelfragment, das Ihr gebracht habt, beschreibt I'lalai als weitläufige Zivilisation, während die Ruinen vor dem Finsteren Riff dafür zu klein wirken.",al={"warum eine abreibung","i'lalai tafel","legende der verlorenen stadt"}},{q="Was ist I'lalai?",a="I'lalai wird im Tafelfragment als verlorene Trollstadt und weitläufige Zivilisation beschrieben.",al={"i'lalai stadt","verlorene trollstadt","ilalai"}},{q="Was sagt der Gelehrte über die Tafel?",a="Der Gelehrte hat die Tafel schon in seiner Jugend gelesen, sagt aber, dass viele Monde vergangen seien und seine Erinnerung verblasst sei.",al={"erinnerung des gelehrten","tafel schon einmal gelesen","alte trolllegende"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="Kin'weelay bittet Euch, im Finsteren Riff nach einer Höhle zu suchen, die mit der verlorenen Stadt verbunden ist. Die Naga, die sich dort sammeln, könnten etwas gefunden haben, das eine Untersuchung wert ist.",h="Kin'weelay bittet Euch, im Finsteren Riff nach einer Höhle zu suchen, die mit der verlorenen Stadt verbunden...",kw={"höhle","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","naga","das finstere riff"},sec={{t="Eine Höhle im Riff",b="Kin'weelay erinnert sich daran, zwischen den Ruinen des Finsteren Riffs getaucht zu sein, bevor sich dort Murlocs niederließen. Er erinnert sich an eine Höhle und bittet Euch, das Riff nach ihrem Eingang abzusuchen. Nun sammeln sich Naga in der Gegend, und er möchte wissen, was sie dorthin gelockt hat."},{t="Eine mögliche Entdeckung",b="Als Ihr zurückkehrt, hört sich Kin'weelay an, was Ihr gesehen habt. Die Naga gehen in der Höhlenruine ein und aus, doch ihre Absichten bleiben unklar. Er fragt sich, ob sie mit I'lalai und der Lost City zusammenhängt, die unter Trollen lange als Mythos galt. Nun möchte er der Sache nachgehen."}},faq={{q="Wer bittet mich, das Finstere Riff abzusuchen?",a="Kin'weelay bittet Euch, das Finstere Riff zu erkunden und nach einem Höhleneingang zu suchen.",al={"wer hat mich geschickt","kin weelays bitte","wer will das"}},{q="Warum suche ich nach einer Höhle?",a="Kin'weelay erinnert sich an eine Höhle zwischen den Ruinen des Finsteren Riffs und vermutet, dass sie helfen könnte, die Lost City zu finden.",al={"warum höhle","hinweis auf lost city","wonach suche ich"}},{q="Warum sammeln sich die Naga dort?",a="Kin'weelay hat gehört, dass sich Naga in der Gegend sammeln, doch der Grund dafür ist unbekannt.",al={"naga am riff","warum naga","grund für naga"}},{q="Was ist mit den Ruinen des Finsteren Riffs geschehen?",a="Murlocs ließen sich zwischen den Ruinen des Finsteren Riffs nieder, nachdem Kin'weelay in seinen jüngeren Jahren dort getaucht war.",al={"ruinen des finsteren riffs","murlocs dort","wer besiedelte das riff"}},{q="Wo ist der Höhleneingang?",a="Der Höhleneingang liegt im Finsteren Riff. Kin'weelay bittet Euch, das Riff danach abzusuchen.",al={"lage der höhle","eingang finden","wo ist die höhle"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="Dorin Songblade wartet auf Nachricht von seinem Bruder Daewyn im Sumpfland. Daewyn schloss sich einem archäologischen Trupp aus Loch Modan an, um in unerforschten Hügeln zu graben, doch sein Schweigen ist untypisch.",h="Dorin Songblade wartet auf Nachricht von seinem Bruder Daewyn im Sumpfland.",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Als Reisender der Allianz kommt Ihr auf dem Weg zwischen Loch Modan und dem Hafen von Menethil womöglich an Ausgrabungsstätten vorbei. Dort könnt Ihr festsitzenden zwergischen Prospektoren und Handwerkern helfen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Expeditionstrupps und archäologische Ausgrabungen in ganz Khaz Modan üblich sind. Das Sumpfland jenseits von Loch Modan ist gefährlich, und Reisen dorthin bringen Angehörige in Gefahr."},sec={{t="Die Sorge eines Bruders",b="Dorin Songblade arbeitet in seiner Werkstatt, überhäuft mit Aufträgen zum Ändern von Gürteln. Sein Bruder Daewyn ist mit einem zwergischen Ausgrabungstrupp aus Loch Modan nach Norden gezogen. Die Hügel im Sumpfland, die sie aufsuchen wollen, hat noch nie eine zwergische Spitzhacke berührt. Daewyn schreibt gewöhnlich gleich nach seiner Ankunft, doch Dorin hat keine Nachricht erhalten, und das Schweigen beunruhigt ihn."},{t="Die Ausgrabung im Sumpfland",b="Daewyn Songblade gräbt an Whelgars Ausgrabungsstätte im Sumpfland. Er sieht seinem Bruder Dorin sehr ähnlich und trägt ein Gewehr, in dessen Holzschaft DLS eingeritzt ist. An diesen Initialen lässt sich Daewyn im abgelegenen Ausgrabungslager in den Marschen erkennen."}},faq={{q="Wer vergibt die Quest Songblade Search?",a="Dorin Songblade bittet Reisende, nach seinem Bruder zu sehen. Der Handwerker hat mit dem Ändern von Gürteln alle Hände voll zu tun, weshalb er sich Daewyns archäologischer Ausgrabung nicht anschließen konnte.",al={"wer vergibt songblade search","songblade search questgeber","dorin songblade"}},{q="Wer ist Daewyn Songblade?",a="Daewyn Songblade ist der Bruder von Dorin Songblade. Er brach mit einem Ausgrabungstrupp aus Loch Modan zu den Hügeln des Sumpflands auf, hat aber nicht wie üblich Nachricht geschickt.",al={"wer ist dorins bruder","vermisster songblade-zwerg","daewyn songblade"}},{q="Wo ist Daewyn zu finden?",a="Daewyn ist an Whelgars Ausgrabungsstätte im Sumpfland. Er ist an seiner Ähnlichkeit mit Dorin und den in den Holzschaft seines Gewehrs eingeritzten Initialen DLS zu erkennen.",al={"wo ist daewyn","wo ist daewyn songblade zu finden","songblade search ort"}},{q="Warum reiste Daewyn ins Sumpfland?",a="Daewyn reiste mit einer zwergischen Ausgrabungsexpedition aus Loch Modan ins Sumpfland, um in unerforschten Hügeln zu graben.",al={"warum ging daewyn ins sumpfland","zweck von whelgars ausgrabungsstätte","warum gingen die zwerge ins sumpfland"}},{q="Was bedeuten die eingeritzten Initialen am Gewehr?",a="Die in den Gewehrschaft eingeritzten Initialen DLS gehören zu Daewyn Songblade. Sie weisen den Zwerg an der Ausgrabungsstätte als Dorins vermissten Bruder aus.",al={"wofür steht dls","dls eingeritzt am gewehr","dls initialen"}},{q="Warum sorgte sich Dorin um seinen Bruder?",a="Dorin sorgt sich, weil Daewyn gewöhnlich kurz nach seinem Aufbruch schreibt. Seit Daewyn ins Sumpfland aufgebrochen ist, sind keine Briefe eingetroffen, und Dorin fürchtet, dass etwas schiefgegangen ist.",al={"warum ist dorin besorgt","warum nach daewyn suchen","songblade search grund"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="Naga sammeln sich bei alten Trollruinen vor der Küste, während Angriffe auf ihre Karawanen die Horde bereits bedrängen. Ihr sollt dieser Bedrohung entgegentreten und zeigen, dass Ihr Euch bewährt.",h="Naga sammeln sich bei alten Trollruinen vor der Küste, während Angriffe auf ihre Karawanen die Horde bereits...",kw={"bloodscalp","brinescale","feinde im wasser","grom'gol","horde","naga","oger","dreizacke","trollruinen"},ang={["faction:Horde"]="Die Horde will ihre Karawanen schützen und zugleich nach einem möglichen Angriff vom Meer Ausschau halten."},sec={{t="Berichte von der Küste",b="Die Horde hat Berichte erhalten, dass sich Naga bei alten Trollruinen unter dem Meer sammeln. Angriffe der Bloodscalp und der Oger beanspruchen ihre Verteidigung bereits stark, sodass eine Bedrohung aus dem Wasser kaum Aufschub duldet. Ihr sollt Euch den Plänklern der Brinescale stellen und ihre Dreizacke als Beweis zurückbringen."},{t="Eine Botschaft bei Grom’gol",b="Die Dreizacke, die Ihr zurückbringt, sollen vor den Toren von Grom’gol aufgestellt werden. Sie sollen als Warnung dienen, dass mit der Horde nicht zu spaßen ist, und Eure Arbeit bringt Euch das Lob des Kommandanten ein."}},faq={{q="Warum sind die Naga nahe der Küste?",a="Berichten zufolge sammeln sich die Naga um alte Trollruinen unter dem Meer.",al={"naga küste","naga im wasser","warum naga hier"}},{q="Wer sind die Feinde hier?",a="Die Bedrohung geht von den Plänklern der Brinescale aus, einer Gruppe von Naga, die nahe der Küste gemeldet wurde.",al={"feinde im wasser","wer sind die naga","brinescale"}},{q="Warum will die Horde gegen die Naga vorgehen?",a="Die Verteidigung ihrer Karawanen gegen Angriffe der Bloodscalp und der Oger bringt die Horde bereits an ihre Grenzen, und sie fürchtet einen Überraschungsangriff vom Meer.",al={"warum naga töten","horde naga problem","angriff vom meer"}},{q="Welcher Beweis wird verlangt?",a="Ihr sollt Dreizacke der Brinescale als Beweis für Euren Erfolg zurückbringen.",al={"dreizack als beweis","was zurückbringen","dreizacke der brinescale"}},{q="Was geschieht mit den Dreizacken?",a="Sie werden vor den Toren von Grom’gol aufgestellt, als Warnung, dass mit der Horde nicht zu spaßen ist.",al={"botschaft der dreizacke","dreizacke aufstellen","gromgol dreizacke"}},{q="Wie beweise ich damit meinen Wert?",a="Der Kommandant lobt Eure Arbeit und sagt, dass Ihr Euch bei der Horde rasch bewährt.",al={"wert beweisen","anerkennung der horde","warum bin ich hier"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="Mankrik trauert um Olgra und bereitet ein Denkmal vor, um ihren Namen lebendig zu halten. Er bittet Euch, bei den nahegelegenen Razormane-Räubern nach ihren verschwundenen Knochenverzierungen zu suchen.",h="Mankrik trauert um Olgra und bereitet ein Denkmal vor, um ihren Namen lebendig zu halten.",kw={"verzierungen","mankrik","denkmal","olgra","polierter knochen","stacheleber","razormane-räuber"},sec={{t="Die Gefallenen ehren",b="Ein Heiler rettete Mankrik, doch Olgra erlag auf dem Schlachtfeld ihren Wunden. In seiner Trauer bereitet Mankrik eine dauerhafte Ehrung vor, damit ihr Name und ihr Opfer in Erinnerung bleiben."},{t="Verlorene Andenken",b="Olgra trug geliebte Schmuckstücke aus poliertem Knochen, doch sie fehlen an ihrer Ruhestätte. Mankrik bittet Euch, sie von den nahegelegenen Razormane-Räubern zurückzuholen, damit sie neben dem Denkmal ruhen können, das er für sie errichtet."}},faq={{q="Wer ist Olgra?",a="Olgra fiel im Kampf gegen die Stacheleber. Der Heiler, der Mankrik rettete, konnte sie nicht retten, und Mankrik will ihr Andenken für immer ehren.",al={"wer ist olgra","mankriks frau","wer ist gestorben"}},{q="Was sind Olgras Verzierungen?",a="Olgras Verzierungen sind geliebte Schmuckstücke aus poliertem Knochen. Sie trug sie, bevor sie getötet wurde.",al={"was sind olgras verzierungen","olgras schmuck","woraus bestehen die verzierungen"}},{q="Warum werden die Razormane-Räuber gejagt?",a="Die Razormane-Räuber haben Olgras Schmuckstücke. Mankrik schickt Euch los, um sie von den Räubern nahe dem Ort zurückzuholen, an dem sie starb.",al={"warum razormane-räuber töten","wer hat olgras verzierungen gestohlen","wo sind die verzierungen"}},{q="Was wird Mankrik mit den zurückgeholten Verzierungen tun?",a="Mankrik plant, den zurückgeholten Knochenschmuck neben das Denkmal zu legen, das er für Olgra errichtet, damit ihr Andenken fortbesteht.",al={"mankriks denkmal","was wird mankrik mit den verzierungen tun","warum will mankrik die verzierungen"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="Eine gelehrte Person bittet Euch, von Naga bewachte Ruinen zu untersuchen und die Ritzungen ihrer Tafeln abzuzeichnen. Die Stadt könnte I’lalai sein, reich an verlorener Geschichte.",h="Eine gelehrte Person bittet Euch, von Naga bewachte Ruinen zu untersuchen und die Ritzungen ihrer Tafeln...",kw={"holzkohle","versunkene stadt","fell","i'lalai","verlorene geschichte","naga","abreibungen","ruinen","tafeln"},sec={{t="Jenseits der Höhle",b="Die gelehrte Person ist zu alt, um die Ruinen zu betreten, und bittet Euch deshalb, an ihrer Stelle hineinzugehen. Jenseits der von Naga bewachten Höhle vermutet sie die Ruinen von I’lalai. Die verlorene Stadt könnte einen reichen Schatz an historischem Wissen bergen. Fertigt Abreibungen aller Tafeln an, die Ihr findet, und bringt sie zurück."}},faq={{q="Was ist die Drowned City?",a="Laut der gelehrten Person, die Euch geschickt hat, könnten die Ruinen die verlorene Stadt I’lalai sein.",al={"versunkene stadt","um welche stadt geht es","ruinen von i'lalai"}},{q="Wer möchte, dass ich die Ruinen erkunde?",a="Eine gelehrte Person bittet Euch, die Ruinen zu erkunden, weil sie selbst zu alt dafür ist.",al={"wer hat mich geschickt","wer möchte abreibungen","auftrag der gelehrten person"}},{q="Warum werde ich dorthin geschickt?",a="Die gelehrte Person hofft, dass die Ruinen einen großen Schatz an verlorenem historischem Wissen bergen.",al={"warum erkunden","warum tafeln","verlorene geschichte"}},{q="Was soll ich zurückbringen?",a="Fertigt mit Fell und Holzkohle Abreibungen aller Tafeln an, die Ihr findet, und kehrt dann zur gelehrten Person zurück.",al={"was zurückbringen","tafelabreibungen","auftrag für abreibungen"}},{q="Wo befinden sich die Ruinen?",a="Die Ruinen liegen auf der anderen Seite der von Naga bewachten Höhle.",al={"wo liegt die versunkene stadt","naga-höhle","lage der ruinen"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="Naga in den Küstengewässern lassen eine größere Bedrohung befürchten. Ihr sollt ihren Anführer in der Drowned City finden.",h="Naga in den Küstengewässern lassen eine größere Bedrohung befürchten.",kw={"brinescale","küste","drowned city","infiltration","kin'weelay","naga","var'taka"},sec={{t="Eine Gefahr vor der Küste",b="Die Naga an der Küste sind erschlagen, doch ihre Zahl deutet auf eine größere Gefahr hin. Kin'weelay glaubt, dass die Brinescale-Naga in die Ruinen der Drowned City eindringen. Ihre Anwesenheit dort lässt vermuten, dass sie etwas suchen, das die Küste gefährden könnte. Ihr sollt ihren Anführer Var'Taka erschlagen."},{t="Die Rückkehr",b="Als Ihr zurückkehrt, nimmt Euer Auftraggeber Eure Ankunft als Zeichen dafür, dass Var'Taka tot ist. Ohne den Anführer der Naga droht der Küste eine Gefahr weniger."}},faq={{q="Warum sind die Brinescale-Naga in der Drowned City?",a="Kin'weelay glaubt, dass die Brinescale-Naga in der Drowned City nach etwas suchen, doch was sie suchen, ist unbekannt.",al={"warum sind naga dort","ziel der brinescale","wonach suchen die naga"}},{q="Wer ist Kin'weelay?",a="Kin'weelay glaubt, dass die Brinescale-Naga in die Drowned City eindringen.",al={"kin'weelay","wer ist kin'weelay","kin"}},{q="Wer ist Var'Taka?",a="Var'Taka ist der Anführer der Brinescale-Naga in der Drowned City.",al={"var taka","naga anführer","brinescale anführer"}},{q="Was soll ich tun?",a="Ihr sollt Var'Taka in der Drowned City erschlagen.",al={"was soll ich tun","was ist der auftrag","wen töten"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95787"] = {n="Take Two With Water",s="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln, wo er die versunkene Trollstadt I’lalai vermutet. Die Tafeln könnten auf einen Loa hinweisen, der seiner Forschung unbekannt ist.",h="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln, wo er die versunkene...",kw={"drowned city","i’lalai","loa","meister der lehren dibbs","tafelabriebe","gezeiten","trolllegenden","zandali"},sec={{t="Dibbs’ Entdeckung",b="Meister der Lehren Dibbs hat einen Kundschafterbericht und Trolllegenden gelesen, die darauf hindeuten, dass I’lalai, eine verlorene Trollstadt, vor der Küste des Schlingendorntals wieder aufgetaucht ist. Er bittet Euch, Legenden aus der Drowned City mitzubringen. Diese Entdeckung könnte das Wissen über die uralten Ruinen verändern."},{t="Die Tafeln",b="Dibbs heißt Euch aus den Trollruinen willkommen und möchte unbedingt erfahren, was Ihr gefunden habt. Vier Tafeln offenbaren neue Legenden, doch sein uraltes Zandali ist eingerostet. Er glaubt, ihre Worte könnten einen unbekannten Loa nennen, der mit den Gezeiten verbunden ist."}},faq={{q="Wer bittet um diese Legenden?",a="Meister der Lehren Dibbs bittet Euch, Legenden aus der Drowned City zu sammeln.",al={"wer ist dibbs","meister der lehren dibbs","dibbs’ bitte"}},{q="Was ist die Drowned City?",a="Dibbs glaubt, sie könnte die verlorene Trollstadt I’lalai sein, die vor der Küste des Schlingendorntals wieder aufgetaucht ist.",al={"drowned city","welche stadt","unterwasser-trollstadt"}},{q="Was soll ich Dibbs mitbringen?",a="Er bittet Euch, Kohleabriebe von Tafeln aus der Drowned City anzufertigen und die Legenden mitzubringen.",al={"was soll ich sammeln","tafelabriebe","auftrag in der drowned city"}},{q="Warum möchte Dibbs die Legenden?",a="Er glaubt, dass der Kundschafterbericht und die Trolllegenden auf die verlorene Stadt I’lalai hindeuten könnten.",al={"warum legenden","dibbs’ forschung","was erforscht er"}},{q="Wo könnte I’lalai liegen?",a="Dibbs glaubt, I’lalai sei direkt vor der Küste des Schlingendorntals wieder aufgetaucht.",al={"wo liegt ilalai","ilalai ort","verlorene trollstadt"}}},fp="19,184,19.263.0,11.226.1,32.67.0,25.93.0,38.102.0,32.90.0,25.71.0"}
P.entries["quest:95788"] = {n="Magics of the Drowned City",s="Ein Gelehrter bittet Euch, Trollfetische aus I'lalai zum Studium zu bringen. Ihr seltsames Design könnte mit der Magie zusammenhängen, die die versunkene Stadt emporhob.",h="Ein Gelehrter bittet Euch, Trollfetische aus I'lalai zum Studium zu bringen.",kw={"bruder nimetz","dunkle magie","versunkene stadt","fetische","i'lalai","naga","piraten","seeschlange","troll","untoter"},sec={{t="Fetische zum Studium",b="Der Gelehrte, der Bruder Nimetz' Schädelspalter-Fetische untersucht hat, bittet Euch, weitere aus I'lalai zu sammeln. Gerüchten zufolge ist die verlorene Trollstadt unter dem Wasser emporgehoben worden, und dunkle Magie könnte dabei eine Rolle gespielt haben. Der Gelehrte möchte ihre Fetische mit den bereits untersuchten vergleichen."},{t="Viele Arten von Magie",b="Nach Eurer Rückkehr stellt der Gelehrte fest, dass sich die Fetische aus I'lalai deutlich unterscheiden: Sie sind kunstvoll und zugleich schlicht gearbeitet und zeigen eine gewaltige Seeschlange. Euer Bericht beschreibt Untote, Piraten, Blutrituale und Naga, die sich in den Ruinen versammeln. Die Stadt zieht nun viele Arten von Magie an, und der Gelehrte sieht Anlass für weitere Studien."}},faq={{q="Wer bittet um die Fetische?",a="Der Gelehrte, der Bruder Nimetz' Schädelspalter-Fetische untersucht hat, bittet Euch, Trollfetische aus I'lalai zu bringen.",al={"wer will fetische","gelehrter fetische"}},{q="Warum werden die Fetische gesammelt?",a="Der Gelehrte möchte untersuchen, ob I'lalais Fetische mit der dunklen Magie zusammenhängen, die die Stadt Gerüchten zufolge emporgehoben hat.",al={"warum fetische sammeln","fetische studieren"}},{q="Was ist I'lalai?",a="I'lalai ist eine verlorene Trollstadt, die Gerüchten zufolge unter dem Wasser emporgehoben wurde.",al={"versunkene stadt","trollstadt"}},{q="Was fällt an den Fetischen aus I'lalai auf?",a="Sie zeigen eine gewaltige Seeschlange. Ihre Machart ist in mancher Hinsicht kunstvoller und in anderer schlichter als die der zuvor untersuchten Fetische.",al={"fetisch-design","seeschlangenfetisch"}},{q="Welche Mächte versammeln sich in I'lalai?",a="Euer Bericht beschreibt umherstreifende Untote, einfallende Piraten, Blutrituale und Naga in den Ruinen.",al={"wer ist in ilalai","untote piraten naga"}}},fp="26,142,18.273.0,11.331.1,26.111.0,36.115.0,16.74.0,43.148.0,38.104.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="Eine Kontaktperson von Baron Revilgaz schickt Euch auf der Suche nach den Saltseers in die Drowned City, Piraten, die magische Artefakte sammeln. Ihre gestohlenen Waren haben Aufmerksamkeit erregt, seit die versunkene Trollruine wieder aufgetaucht ist.",h="Eine Kontaktperson von Baron Revilgaz schickt Euch auf der Suche nach den Saltseers in die Drowned City...",kw={"baron revilgaz","drowned city","magische artefakte","piraten","saltseers","shady saltseers","trollruine","voodoo infused artifacts"},sec={{t="Die Bitte eines Barons",b="Eine Kontaktperson von Baron Revilgaz bittet Euch, Artefakte von den Saltseers in der Drowned City zurückzuholen. Die Piraten sammeln magische Gegenstände, und seit die Ruine wieder aufgetaucht ist, gibt es dort Waren zu holen. Ihre gestohlenen Artefakte sind es, die Revilgaz’ Kontaktperson sucht."}},faq={{q="Wer will die Artefakte der Saltseers?",a="Eine Kontaktperson von Baron Revilgaz bittet Euch, die Artefakte zurückzuholen.",al={"wer hat mich geschickt","kontaktperson von baron revilgaz","wer will artefakte"}},{q="Wer sind die Saltseers?",a="Die Saltseers sind Piraten, die magische Artefakte sammeln.",al={"saltseer-piraten","wer sind saltseers","saltseers"}},{q="Wo sind die Saltseers?",a="Sie sind in der Drowned City, einer versunkenen Trollruine, die wieder aufgetaucht ist.",al={"wo ist drowned city","aufenthaltsort der saltseers","drowned city"}},{q="Nach welchen Artefakten suche ich?",a="Ihr sollt Voodoo Infused Artifacts zurückholen, die von den Saltseers gestohlen wurden.",al={"was sammeln","voodoo-artefakte","gestohlene waren"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="Ein rivalisierender Jäger will Captain Dreadrise und seine Saltseer Coroners aus der Drowned City loswerden. Ihre Mannschaft sammelt ständig die magischen Artefakte, die er sucht.",h="Ein rivalisierender Jäger will Captain Dreadrise und seine Saltseer Coroners aus der Drowned City loswerden.",kw={"captain dreadrise","drowned city","magische artefakte","piraten","saltseer","saltseer coroners"},sec={{t="Ein Rivale in der Stadt",b="Ein rivalisierender Jäger sucht Eure Hilfe in der Drowned City, wo ihm die Saltseer-Piraten ein Dorn im Auge sind. Captain Dreadrise und seine Saltseer Coroners sammeln die magischen Artefakte, die er haben will. Er bittet Euch, den Kapitän und drei seiner Mannschaftsmitglieder aus dem Weg zu räumen."}},faq={{q="Wer ist Captain Dreadrise?",a="Captain Dreadrise führt die Saltseer-Piraten in der Drowned City an.",al={"dreadrise","saltseer-kapitän","kapitän typ"}},{q="Wer sind die Saltseer Coroners?",a="Die Saltseer Coroners sind Mannschaftsmitglieder, mit denen Captain Dreadrise beim Sammeln magischer Artefakte zusammenarbeitet.",al={"saltseer-mannschaft","coroners","dreadrises mannschaft"}},{q="Warum will der Auftraggeber Dreadrise loswerden?",a="Captain Dreadrise und seine Mannschaft sammeln ständig magische Artefakte, nach denen der Auftraggeber sucht, und er hat die Konkurrenz satt.",al={"warum dreadrise töten","warum kapitän beseitigen","dreadrises rivale"}},{q="Wo sind Captain Dreadrise und die Saltseers?",a="Captain Dreadrise und die Saltseer-Piraten sind in der Drowned City.",al={"wo ist dreadrise","saltseer aufenthaltsort","piraten der drowned city"}},{q="Was soll ich für den Auftraggeber tun?",a="Der Auftraggeber bittet Euch, Captain Dreadrise und drei Saltseer Coroners in der Drowned City zu töten.",al={"was ist zu tun","dreadrise quest","saltseer aufgabe"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Bei der Ausgrabung hinterlässt ein gefallener Zwerg eine düstere Nachricht für seinen Bruder in Seenhain. Dorin Songblade erfährt, was seinem Bruder widerfahren ist, und steht vor den Geschenken, die er nicht rechtzeitig vollenden konnte.",h="Bei der Ausgrabung hinterlässt ein gefallener Zwerg eine düstere Nachricht für seinen Bruder in Seenhain.",kw={"schmied","dorin","dorin songblade","zwerg","ausgrabung","ausgrabungsstätten","fallen in the fen","seenhain","songblade"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr einem trauernden Handwerker im Rotkammgebirge Trost spenden. Ein Bewohner der Stadt sucht in unruhigen Zeiten für das Königreich nach Gewissheit.",["profession:Blacksmithing"]="Als Schmied versteht Ihr, mit welcher Sorgfalt Dorin die Waffen fertigte, die seinen Bruder überraschen sollten. Nun erinnert die Ausrüstung an den frühen Tod seines Bruders.",["race:Dwarf"]="Als Zwerg kennt Ihr die Trauer, einen Bruder an uralte Ausgrabungsstätten und ungezähmte Wildnis zu verlieren. Ihr wisst, dass geschmiedetes Metall die Hand überdauern kann, die es halten sollte."},sec={{t="Tragödie bei der Ausgrabung",b="An den Ausgrabungsstätten liegt ein abenteuerlustiger Zwerg tot am Boden. Ihr bedeckt seine sterblichen Überreste mit seinem eigenen Umhang, bringt dann die düstere Nachricht nach Seenhain und sucht seine Angehörigen auf."},{t="Die Trauer eines Bruders",b="Dorin Songblade ist ein zwergischer Handwerker in Seenhain. Als er vom Schicksal seines Bruders erfährt, überwältigt ihn die Trauer. Wochenlang arbeitete er an seiner Schmiede an einer Ausrüstung als Überraschung, doch vor der Expedition seines Bruders wurde sie nicht fertig. Er bereut, ihn nicht begleitet zu haben.\n\nDorin bringt es nicht über das Herz, das mit eigenen Händen Geschaffene umzuschmieden, zu verkaufen oder zu behalten. Also gibt er die fertigen Stücke demjenigen, der ihm Gewissheit gebracht hat."}},faq={{q="Was ist Fallen in the Fen?",a="An den Ausgrabungsstätten findet Ihr einen gefallenen Zwerg und bedeckt seinen Leichnam mit seinem eigenen Umhang. Dann überbringt Ihr seinem trauernden Bruder, Dorin Songblade, in Seenhain die Nachricht von seinem Schicksal.",al={"was ist fallen in the fen","fallen in the fen quest"}},{q="Wer ist Dorin Songblade?",a="Dorin Songblade ist ein zwergischer Schmied in Seenhain. Er hatte an einer Ausrüstung als Überraschung für seinen Bruder geschmiedet, als er von dessen Tod an den Ausgrabungsstätten erfuhr.",al={"wer ist dorin songblade","dorin in seenhain","dorin songblade rolle"}},{q="Wer ist der gefallene Zwerg, der bei der Ausgrabung gefunden wurde?",a="Der gefallene Zwerg war Dorin Songblades Bruder. Vor seiner Expedition kam er durch Seenhain, um Vorräte zu beschaffen, und fand dann draußen den Tod.",al={"wer starb im morast","toter zwerg ausgrabung","wessen leichnam liegt in der ausgrabung"}},{q="Wo ist Dorin Songblade zu finden?",a="Dorin Songblade lebt in Seenhain, der wichtigsten Siedlung im Rotkammgebirge. Er arbeitet dort an der Schmiede.",al={"wo ist dorin songblade","dorin songblade aufenthaltsort"}},{q="Was schmiedete Dorin für seinen Bruder?",a="Dorin schmiedete Ausrüstung als Überraschungsgeschenk für seinen Bruder. Die Arbeit war noch nicht vollendet, als sein Bruder zu seiner Expedition aufbrach. Dorin bringt es nicht über das Herz, die Ausrüstung zu behalten, umzuschmieden oder zu verkaufen.",al={"was schmiedete dorin","dorin überraschungsgeschenk"}},{q="Warum verschenkt Dorin die Gegenstände, die er gefertigt hat?",a="Dorin bereut, seinen Bruder nicht begleitet zu haben, und bringt es nicht über das Herz, seine geschmiedeten Waffen zu behalten, umzuschmieden oder zu verkaufen. Er gibt die fertigen Stücke dem Reisenden, der ihm Nachricht von seinem Bruder gebracht hat.",al={"warum verschenkte dorin die ausrüstung","warum erhält man von dorin ausrüstung"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95799"] = {n="Findings for the Explorer's League",s="Meister der Lehren Dibbs bittet Euch, seine Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in Eisenschmiede zu bringen. Karnik sieht die Entdeckung als Grund, ein Team in Richtung der verlorenen Stadt zu schicken.",h="Meister der Lehren Dibbs bittet Euch, seine Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in...",kw={"explorer's league","funde für die explorer's league","historiker karnik","i'lalai","eisenschmiede","meister der lehren dibbs","tafeln","übersetzungen","trolle"},sec={{t="Ein Brief nach Eisenschmiede",b="Historiker Karnik in Eisenschmiede wartet auf Nachricht von Meister der Lehren Dibbs, Eurem Kollegen. Dibbs hat eine Entdeckung gemacht, die er für geschichtlich bedeutsam hält, und bittet Euch, seinen Brief und eine Abschrift seiner Übersetzungen der I'lalai-Tafeln zu Karnik zu bringen."},{t="Karniks Antwort",b="Karnik begrüßt Dibbs' Übersetzungen und sagt, er werde ein Team zusammenstellen, um die verlorene Stadt I'lalai zu suchen. Seine eigenen Studien betreffen andere Themen, doch er respektiert Dibbs' Interesse an Trollen."}},faq={{q="Wer bittet mich, den Brief zu überbringen?",a="Meister der Lehren Dibbs bittet Euch, seinen Brief und eine Abschrift seiner Übersetzungen der I'lalai-Tafeln zu Historiker Karnik in Eisenschmiede zu bringen.",al={"wer hat mir das gegeben","dibbs brief","wer ist meister der lehren dibbs"}},{q="Wer ist Historiker Karnik?",a="Historiker Karnik ist der Kollege von Meister der Lehren Dibbs bei der Explorer's League in Eisenschmiede, der Dibbs' Brief und Übersetzungen entgegennimmt.",al={"wer ist karnik","karnik eisenschmiede","historiker"}},{q="Was sind die I'lalai-Übersetzungen?",a="Es sind Meister der Lehren Dibbs' Übersetzungen von Tafeln, die mit I'lalai in Verbindung stehen.",al={"ilalai-übersetzungen","tafeln übersetzungen","dibbs tafeln"}},{q="Warum möchte Dibbs, dass ich den Brief überbringe?",a="Dibbs sagt, die Entdeckung sei von großer geschichtlicher Bedeutung, und möchte, dass sein Kollege in Eisenschmiede umgehend davon erfährt.",al={"warum den brief überbringen","warum eisenschmiede","was braucht dibbs"}}},fp="34,175,21.245.0,17.183.1,37.124.0,24.120.0,34.72.0,42.114.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha schickt Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen. Die Übergabe soll den Verlassenen zeigen, dass Euer Volk sich ihrem Wohlergehen verschrieben hat.",h="Danitha schickt Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",kw={"a token of good faith","danitha","dark lady","verlassene","licht","rudolph gelhardt","sylvanas windläufer","unterstadt"},sec={{t="Ein Zeichen der Treue",b="Danitha sagt, Sylvanas misstraue Eurem Volk und verunglimpfe es offen. Sie bittet Euch, Rudolph Gelhardts Kopf als Beweis zu bringen, dass Ihr vor der eigenen Haustür kehrt und an der Seite der Verlassenen steht."},{t="Die Antwort der Dark Lady",b="Sylvanas bezweifelt, dass Danithas Orden verhindern kann, dass weitere seiner Mitglieder das Licht gegen ihr eigenes Volk wenden. Sie warnt, dass sie den Orden vielleicht nicht länger dulden wird, wenn er nicht mehr den Interessen der Verlassenen dient. Der Orden wird beobachtet werden."}},faq={{q="Wer bittet mich, Rudolph Gelhardts Kopf zu Sylvanas zu bringen?",a="Danitha bittet Euch, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",al={"wer schickt mich zu sylvanas","danitha kopfübergabe","kopf zur dark lady"}},{q="Warum will Danitha, dass ich den Kopf zu Sylvanas bringe?",a="Danitha will mit der Übergabe Sylvanas zeigen, dass Euer Volk vor der eigenen Haustür kehrt und sich dem Wohlergehen der Verlassenen verschrieben hat.",al={"warum rudolphs kopf bringen","wozu dient diese übergabe","treue beweisen"}},{q="Warum misstraut Sylvanas Danithas Volk?",a="Danitha sagt, Sylvanas misstraue Eurem Volk zutiefst und verunglimpfe es beinahe offen.",al={"warum sylvanas uns misstraut","misstrauen der dark lady","warum verunglimpft sie uns"}},{q="Wohin bringe ich Rudolph Gelhardts Kopf?",a="Ihr werdet gebeten, Rudolph Gelhardts Kopf zu Sylvanas Windläufer in die Unterstadt zu bringen.",al={"wo ist sylvanas","ort der kopfübergabe","in die unterstadt bringen"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Auf der Hochwolkenebene werden An'she und Mu'sha als Augen der Erdenmutter geehrt. Ihr tragt glimmendes Räucherwerk zu einem Schrein in den südöstlichen Hügeln, wo sein Rauch zu Sonne und Mond aufsteigt, die den Ebenen Wärme, Leben und Orientierung schenken.",h="Auf der Hochwolkenebene werden An'she und Mu'sha als Augen der Erdenmutter geehrt.",kw={"an'she","erdenmutter","mond","mu'sha","mulgore","die hochwolkenebene","schrein","glimmendes räucherwerk","sonne","tauren"},ang={["class:Druid"]="Als Druide der Tauren seht Ihr im ewigen Tanz von Sonne und Mond das ursprüngliche Gleichgewicht der Natur, das Euer Verständnis ihrer kosmischen Rhythmen leitet.",["class:Shaman"]="Als Schamane der Tauren sprecht Ihr mit den Geistern von Erde, Feuer, Wasser und Luft und ehrt gleichermaßen die himmlischen Zwillinge, deren Licht die Lebensenergie erhält.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr die heiligen Riten auf der Hochwolkenebene und die naturverbundenen Bräuche, die die nomadischen Tauren ihren Verbündeten nahebringen.",["race:Tauren"]="Als Tauren lernt Ihr, dass das Leben Euch dazu aufruft, An'she und Mu'sha ebenso treu wie die Erdenmutter zu ehren. Ihre Verehrung bildet den Kern der spirituellen Identität der Tauren und erinnert junge Krieger an ihre Pflicht."},sec={{t="Die Augen der Erdenmutter",b="Die Tauren ehren An'she und Mu'sha als Sonne und Mond, die Zwillingsaugen der Erdenmutter. Elementargeister wohnen in Azeroths Steinen, Winden und Gewässern, während die himmlischen Zwillinge aus den Höhen des Himmels wachen. Auf ihrem Weg über den Himmel bestimmen sie Tag und Nacht und schenken Lebewesen Wärme, Orientierung und Hoffnung. Für die Tauren ist es eine spirituelle Pflicht, sie zu ehren. Das Gleichgewicht verlangt Ehrfurcht vor dem Land unter Euren Füßen und dem Licht darüber."},{t="Eine Opfergabe auf den Höhen",b="Tragt glimmendes Räucherwerk in die südöstlichen Hügel mit Blick auf die Hochwolkenebene, unmittelbar südlich der stacheligen Borstennackengebiete. Legt den Weg zügig und achtsam zurück. Haltet die Glut trocken und erreicht den Schrein, bevor sie zu kalter Asche verglimmt. Werft sie am hoch gelegenen Schrein in das Sacred Fire. Ihr duftender Rauch trägt Eure Ehrerbietung himmelwärts, zu Sonne und Mond."}},faq={{q="Wer sind An'she und Mu'sha?",a="Im Glauben der Tauren sind An'she und Mu'sha Sonne und Mond und werden als Zwillingsaugen der Erdenmutter geehrt. Sie leuchten von oben, anders als die Geister, die in Azeroths Erde, Luft, Feuer und Wasser wohnen. An'she bringt Wärme und Leben, während Mu'sha durch die Nacht hindurch Orientierung und Trost spendet.",al={"wer sind anshe und musha","geschichte von anshe und musha","sonnen- und mondgötter der tauren"}},{q="Warum bringen die Tauren Sonne und Mond Opfergaben dar?",a="Die Lehren der Tauren besagen, dass Gleichgewicht für das Dasein unerlässlich ist. An'she und Mu'sha schenken Lebewesen Kraft, Sehkraft und Hoffnung. Indem Tauren an einem hoch gelegenen Ort Räucherwerk darbringen, erweisen sie beiden Himmelslichtern Respekt, von deren beständigem Wohlwollen das Leben der Sterblichen abhängt.",al={"warum sonne und mond verehren","verehrung der himmelslichter bei den tauren","warum anshe und musha ehren"}},{q="Wo befindet sich der Schrein von An'she und Mu'sha?",a="Der Schrein liegt in den hohen Hügeln südöstlich der Hochwolkenebene, mit Blick auf die Ebenen und unmittelbar südlich der dornigen Borstennackengebiete. Seine Höhe bietet einen klaren, ungehinderten Blick auf den offenen Himmel, zu dem der Rauch aufsteigen kann.",al={"wo ist der schrein von anshe","standort des schreins in mulgore","wie den räucherwerkschrein finden"}},{q="Welche Bedeutung hat das glimmende Räucherwerk?",a="Glimmendes Räucherwerk trägt das Gebet und die Ehrerbietung eines Reisenden zu Sonne und Mond. Sein duftender Rauch steigt aus der brennenden Glut auf. Werft sie in das Feuer des Schreins, um den Ritus zu vollenden und dem Pilger ein friedvolles Gefühl spiritueller Erfüllung zu schenken.",al={"was bewirkt das räucherwerk","bedeutung des räucheropfers","warum glimmendes räucherwerk verbrennen"}},{q="Warum muss das Räucherwerk schnell überbracht und trocken gehalten werden?",a="Das Räucherwerk muss noch glimmen, wenn es das Feuer des Schreins erreicht, daher verlangt der Weg Wachsamkeit, Schnelligkeit und Sorgfalt. Erreicht das Ziel, bevor die Glut zu kalter Asche verglimmt, und schützt sie vor Wasser, das sie löschen und die Opfergabe verderben würde.",al={"warum zeitlimit beim räucherwerk","vor nässe schützen","räucherwerk verglimmt"}},{q="Bedrohen die Borstennacken die Pilgerreise zum Schrein?",a="Borstennackenstämme besetzen befestigte Dornenbaue in den Hügeln unmittelbar nördlich des Schreins. Der Schrein liegt an einem ruhigen Aussichtspunkt südlich ihrer Gebiete, doch Reisende müssen die Dornengestrüppe der Borstennacken meiden, wo ein Angriff die Reise verzögern oder unterbrechen könnte.",al={"borstennacken nahe dem schrein","bedrohen borstennacken die pilger","borstennacken südlich der hochebene"}},{q="Wie unterscheidet sich Mu'sha von den Mondvorstellungen anderer Kulturen?",a="Die Tauren nennen den Mond Mu'sha, das liebevolle linke Auge der Erdenmutter, das auf das Leben der Sterblichen herabblickt. Nachtelfen verehren denselben leuchtend weißen Mond als Elune, während die Tradition der Tauren Mu'sha mit ihrem Sonnenzwilling An'she verbindet.",al={"ist musha elune","mond der tauren und elune im vergleich","musha und die nachtelfen"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Im Sumpfland hat Ardin Grassman die Gefahren der Marschen überlebt und schickt Nachricht zum Hafen von Menethil. Ein Reisender bringt Caitlin Grassman ein Schilfherz.",h="Im Sumpfland hat Ardin Grassman die Gefahren der Marschen überlebt und schickt Nachricht zum Hafen von...",kw={"caitlin grassman","grassman","heartwoven","hafen von menethil","schilfherz","schilf","sumpfland"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr helfen, die gefährlichen Sumpfwege rund um den Hafen von Menethil für die Zivilisten zu sichern, die auf sie angewiesen sind.",["profession:Cooking"]="Als Caitlin erfährt, dass ihr Partner überlebt hat, macht sie sich daran, eine warme, herzhafte Mahlzeit vorzubereiten, um ihn zu Hause willkommen zu heißen."},sec={{t="Ein Zeichen aus den Marschen",b="Ardin Grassman wollte die seltsamen Gräser an den Ausgrabungsstätten im Sumpfland sehen, saß dann aber inmitten der Gefahren der Marschen fest. Ihr bahnt einen Weg durch die Wildnis und verschafft ihm so Zeit, sich auszuruhen und seine Ernte einzubringen. Müde, aber entschlossen bereitet Ardin sich darauf vor, in die Sicherheit des Hafens zurückzukehren."},{t="Zeichen für Menethil",b="Bevor Ardin den Heimweg antritt, nimmt er Sumpfschilf aus seinem Rucksack und flicht daraus ein Herz. Er gibt Euch dieses Zeichen, damit Ihr es Caitlin Grassman im Hafen von Menethil bringt. Sie wartet voller Sorge. Die Nachricht, dass Ardin überlebt hat und bald zurückkehrt, bringt Erleichterung, zusammen mit dem Schilfherz und dem Versprechen einer warmen Mahlzeit."}},faq={{q="Was ist die Quest Heartwoven?",a="Ein Reisender hilft Ardin Grassman, nachdem dieser an den Ausgrabungsstätten im Sumpfland gestrandet ist. Ardin fertigt ein Schilfherz an, um Caitlin Grassman, die im Hafen von Menethil wartet, von seinem Überleben und seiner Zuneigung zu künden.",al={"heartwoven quest","was ist heartwoven","sumpfland heartwoven"}},{q="Wer ist Caitlin Grassman?",a="Caitlin Grassman wartet im Hafen von Menethil voller Sorge auf ihren Mann Ardin. Seit er zu den Ausgrabungsstätten im Sumpfland aufgebrochen ist, fürchtet sie um sein Leben und ist erleichtert, als Ihr ihr von seinem Überleben berichtet.",al={"wer ist caitlin grassman","caitlin hafen von menethil","caitlin grassman"}},{q="Was ist das aus Schilf geflochtene Herz?",a="Das aus Schilf geflochtene Herz ist ein Zeichen, das Ardin aus dem Sumpfschilf in seinem Rucksack anfertigt. Er gibt es Euch mit, um Caitlin zu versichern, dass er lebt und bald nach Hause zurückkehrt.",al={"was ist das schilfherz","herz aus schilf geflochten","schilfgeflochtenes herz"}},{q="Wo wird Heartwoven abgegeben?",a="Ihr bringt Caitlin Grassman das Schilfherz im Hafen von Menethil, der Hafenstadt der Allianz an der Westküste des Sumpflands.",al={"wo heartwoven abgeben","heartwoven abgabeort","wo ist caitlin grassman"}},{q="Wer gibt Euch die Quest Heartwoven?",a="Ardin Grassman gibt Euch das Herz, damit Ihr es seiner Frau Caitlin bringt. Nachdem Ihr einen sicheren Weg durch das Sumpfland gebahnt habt, ruht er sich aus, sammelt seine Bündel ein und schickt Euch mit dem Zeichen voraus.",al={"wer vergibt heartwoven","wer fertigt das herz","der überlebende heartwoven"}},{q="Was ist dem gestrandeten Sammler widerfahren?",a="Ardin ging zu den Ausgrabungsstätten, um seltsame, hoch aufragende Gräser zu sehen, doch aufgescheuchte Wildtiere, vor allem Spinnen, überwältigten das Ausgrabungsteam. Ihr bahnt einen Weg durch die Gefahren ringsum, sodass Ardin überleben, seine Bündel einsammeln und zum Hafen von Menethil zurückkehren kann.",al={"was ist dem sammler widerfahren","lebt er noch","heartwoven überlebender"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Ihr tragt ein zerbrochenes Felsmech-Relikt durch das Sumpfland zu Ausgrabungsleiter Whelgar. Sein seltsames Material erregt die Aufmerksamkeit zwergischer Forscher.",h="Ihr tragt ein zerbrochenes Felsmech-Relikt durch das Sumpfland zu Ausgrabungsleiter Whelgar.",kw={"automat","ausgrabungsstätte","explorers league","lost relic carry","ausgrabungsleiter whelgar","felsmech","relikt der titanen","sumpfland"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie das Verbundmaterial und die komplexe Bauweise des Felsmechs auf mechanische Prinzipien hinweisen, die über die übliche Ingenieurskunst der Sterblichen hinausgehen.",["race:Dwarf"]="Als Zwerg teilt Ihr den Drang Eures Volkes, uralte Relikte seiner Schöpfer auszugraben. Dieses Bruchstück ist ein geschätzter Fund für das zwergische Erbe."},sec={{t="Ein Bruchstück uralter Handwerkskunst",b="Ein Felsmech hat ein zerbrochenes Stück seiner uralten Handwerkskunst hinterlassen. Sein unbekanntes Verbundmaterial weist es als Teil eines ausgeklügelten Mechanismus aus, der mit den Titanen verbunden ist."},{t="Lieferung zur Ausgrabung",b="Ausgrabungsleiter Whelgar untersucht uralte Überreste an der Ausgrabungsstätte im Sumpfland. Bringt ihm das Relikt sicher, und zwergische Gelehrte erhalten handfeste Beweise für ihre Erforschung ihres uralten Erbes."}},faq={{q="Was ist das Relikt der Titanen?",a="Das Relikt der Titanen ist ein zerbrochenes Stück eines uralten Felsmech-Automaten. Sein unbekanntes Verbundmaterial war Teil einer komplexen mechanischen Vorrichtung.",al={"was ist das relikt","was ist der gegenstand","felsmech-bauteil"}},{q="Wer ist Ausgrabungsleiter Whelgar?",a="Ausgrabungsleiter Whelgar ist ein zwergischer Forscher, der die Ausgrabungsstätte im Sumpfland leitet. Er untersucht uralte irdene Überreste und Relikte, die überall in der Region freigelegt werden.",al={"wer ist whelgar","whelgars geschichte","ausgrabungsleiter"}},{q="Wohin muss das Relikt gebracht werden?",a="Bringt das Relikt zu Ausgrabungsleiter Whelgar an seiner Ausgrabungsstätte im Sumpfland. Dort untersuchen zwergische Ausgräber uralte Ruinen.",al={"wohin bringen","wo abgeben","whelgars standort"}},{q="Was hat den Felsmech-Automaten erschaffen?",a="Das Bruchstück wird als Relikt der Titanen identifiziert. Zwergische Überlieferungen verbinden uralte mechanische Konstrukte und steinerne Automaten mit den rätselhaften Titanen, die die Welt formten.",al={"wer hat den felsmech erschaffen","ursprung des automaten","verbindung zu den titanen"}},{q="Warum behandelt Ausgrabungsleiter Whelgar das Relikt mit Ehrfurcht?",a="Whelgar weiß um die Gefahren des Weges in die Tiefen, in denen diese Automaten liegen. Er sagt, wer den Abstieg überlebt und mit einem unversehrten Stück zurückkehrt, verdient aufrichtigen Respekt.",al={"warum ist whelgar beeindruckt","gefährlicher abstieg"}},{q="Was ist am Material des Automaten ungewöhnlich?",a="Das Material des Automaten ist ein unbekannter Verbundstoff, der sich von gewöhnlichem Stein oder geschmiedetem Metall unterscheidet. Es zeugt von der ausgefeilten Handwerkskunst uralter Titanenkonstrukte.",al={"was ist das material","seltsamer verbundstoff"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
P.entries["quest:95882"] = {n="WANTED: Scoutmaster Vargas",s="Neza Bloodsnout will Scoutmaster Vargas aufhalten lassen, nachdem seine Kundschafterei die Horde behindert hat. Sein Auge soll beweisen, dass er fort ist.",h="Neza Bloodsnout will Scoutmaster Vargas aufhalten lassen, nachdem seine Kundschafterei die Horde behindert...",kw={"kundschafter der allianz","neza bloodsnout","flusslande","rog'mar","kundschaftergruppe","scoutmaster vargas","auge des spähermeisters"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr Neza, einen Kundschaftermeister der Allianz auszuschalten, dessen Spähgänge die Bewegungen der Horde behindert haben."},sec={{t="Nezas Jagd",b="Neza Bloodsnout hat Scoutmaster Vargas bereits ein Auge genommen, doch der Mensch konnte entkommen. Seine Kundschafterei erschwert es der Horde, die Bewegungen der Allianz zu verfolgen. Nun bittet Neza Euch, Vargas’ anderes Auge zurückzubringen, als Beweis, dass der Spähermeister nicht mehr ist."},{t="Der Bericht",b="Neza hört, dass Vargas tot ist, und sagt, die Flusslande seien nun sicherer für die Horde. Sie bedauert, dass er nach allem, was er gesehen hat, nicht blind weitergelebt hat."}},faq={{q="Wer ist Scoutmaster Vargas?",a="Scoutmaster Vargas ist ein Mensch, der eine Kundschaftergruppe der Allianz auf einer kleinen Insel nordöstlich von Rog'mar anführt.",al={"vargas","wer ist vargas"}},{q="Warum will Neza Vargas tot sehen?",a="Vargas’ Kundschafterei hat es der Horde erschwert, die Bewegungen des Feindes zu verfolgen, und Neza sagt, er wisse, dass sie ihn jagt.",al={"warum vargas töten","neza vargas"}},{q="Wo wurde Vargas gesichtet?",a="Eine von Vargas angeführte Kundschaftergruppe der Allianz wurde auf einer kleinen Insel nordöstlich von Rog'mar gesichtet.",al={"vargas insel","wo ist der spähermeister"}},{q="Was soll ich Neza zurückbringen?",a="Neza bittet Euch, ihr Scoutmaster Vargas’ anderes Auge als Beweis dafür zurückzubringen, dass er fort ist.",al={"vargas auge","welcher beweis"}},{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist in Rog'mar und will einen Beweis, dass Scoutmaster Vargas nicht mehr ist.",al={"neza","wer will vargas töten"}},{q="Was sagt Neza nach Vargas’ Tod?",a="Neza nimmt Vargas’ Tod hin und sagt, die Flusslande seien nun sicherer für die Horde.",al={"vargas ende","was geschieht danach"}}},fp="26,137,14.255.0,10.142.1,26.104.0,31.119.0,22.89.0,36.83.0,23.81.0,37.82.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="Bei Berens List im Silberwald wartet ein dunkler Ritus auf seine Vollendung. Eine zurückgelassene Notiz nennt die letzten benötigten Opfergaben: Blut und eine von Leid gezeichnete Seele.",h="Bei Berens List im Silberwald wartet ein dunkler Ritus auf seine Vollendung.",kw={"berens list","üble energie","blutopfer","opferstein","ritual","silberwald","die gequälte seele"},ang={["class:Priest"]="Der Ritus schöpft üble Energie aus leidenden Geistern und steht damit im scharfen Gegensatz zu den heilenden Grundsätzen des Heiligen Lichts.",["class:Warlock"]="Das Kanalisieren gepeinigter Seelen und das Vorbereiten dunkler Riten an uralten Opfersteinen spiegeln das finstere, manipulative Wesen dämonischer Magie und von Shadow Magic wider.",["race:Undead"]="Der Silberwald ist das Gebiet der Verlassenen, wo dunkle Magie und anhaltendes Leid die Grenzen Lordaerons bedrohen."},sec={{t="Ein hastiger Ritus",b="Bei Berens List im Silberwald birgt ein Altar die Überreste eines hastig vorbereiteten dunklen Ritus. Zwischen den verstreuten Materialien liegt eine gekritzelte Notiz. Die meisten Zutaten sind bereits beisammen, doch der Ritus verlangt noch nach Blut und einer Gequälten Seele."},{t="Unheilvolle Energien entfesselt",b="Die Kreaturen zwischen den zerklüfteten Felsen von Berens List erleiden große Qualen und eignen sich daher als Quellen der benötigten Essenz. Bringt diese Seele zum unheilvollen Opferstein, und üble magische Energie strömt daraus hervor. Der Ritus rückt seiner Vollendung näher."}},faq={{q="Was ist die Gequälte Seele?",a="Die Gequälte Seele erzählt von einem unvollendeten dunklen Ritus bei Berens List im Silberwald. Ein Opferstein wartet auf Blut und die Seele einer gepeinigten Kreatur.",al={"was ist die quest die gequälte seele","gequälte seele silberwald","berens list quest"}},{q="Wo findet dieses Ritual statt?",a="Der Ritualaltar und sein Opferstein befinden sich bei Berens List, einer gefährlichen Gebirgsenklave im Silberwald.",al={"wo ist das ritual","wo ist berens list","opferstein standort"}},{q="Welche Bestandteile werden für das Ritual benötigt?",a="Ein Notizzettel am Altar besagt, dass fast alle Materialien beisammen sind. Es fehlen nur noch Blut und eine Gequälte Seele.",al={"was wird für das ritual benötigt","ritualbestandteile berens list"}},{q="Wo findet Ihr die Gequälte Seele?",a="Die Kreaturen in den nahen Felsen von Berens List erleiden genug Qualen, um die vom Opferstein benötigte Essenz zu liefern.",al={"woher bekommt man die gequälte seele","wer hat die seele"}},{q="Was geschieht, wenn die Gequälte Seele zum Altar gebracht wird?",a="Die gequälte Seele zum Opferstein zu bringen, setzt üble Energie frei und bringt den dunklen Ritus seiner Vollendung näher.",al={"was geschieht beim bringen der seele","gequälte seele abgeben"}},{q="Wer hat das Ritual bei Berens List erschaffen?",a="Es wird kein Urheber genannt. Die Notiz und die eilig gesammelten Materialien deuten darauf hin, dass jemand den Altar hastig zwischen den feindseligen Bewohnern von Berens List errichtete.",al={"wer hat das ritual erschaffen","wer hat die notiz geschrieben"}}},fp="17,163,12.253.0,23.250.1,26.158.0,34.114.0,44.129.0,36.120.0,60.116.0,40.147.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="In Berens List wird am Offering Stone eine rituelle Opfergabe vorbereitet. Fragmente einer verwitterten Notiz weisen Reisenden den Weg zum Altar im Silberwald.",h="In Berens List wird am Offering Stone eine rituelle Opfergabe vorbereitet.",kw={"berens list","gerätschaften","offering stone","ritual","notizfetzen","silberwald","the offering stone"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr die finsteren Gerätschaften auf dem Opferstein als Zeichen ritueller Praktiken deuten, die ein eingehendes Studium lohnen.",["faction:Horde"]="Als Abenteurer der Horde im Silberwald solltet Ihr in den schattigen Felsklüften von Berens List nach verdächtigen Ritualen und Kultistenaktivitäten Ausschau halten."},sec={{t="Eine Zerfledderte Notiz",b="Ein verwitterter Papierfetzen aus dem Silberwald enthält Bruchstücke über ein Ritual und einen Opferstein in der Nähe. Zeit und Feuchtigkeit haben die meisten seiner Worte unleserlich gemacht. Folgt Ihr den Hinweisen nach Berens List, könnt Ihr den groben Altar in der Wildnis finden."},{t="Die Ritualstätte",b="In Berens List liegen seltsame Gerätschaften und bizarre Gegenstände über den rauen Stein verstreut. Jemand hat die Stätte genutzt, um fernab neugieriger Blicke eine Opfergabe oder einen finsteren Ritus vorzubereiten."}},faq={{q="Was ist der Offering Stone?",a="Der Offering Stone ist ein grober Altar in Berens List im Silberwald. Seltsame Gerätschaften und Gegenstände, die darauf verstreut liegen, deuten auf Vorbereitungen für eine Opfergabe oder einen finsteren Ritus hin.",al={"was ist der offering stone","offering stone silberwald","was ist dieser stein"}},{q="Wo ist der Offering Stone zu finden?",a="Ihr findet den Offering Stone in Berens List im südlichen Silberwald.",al={"wo ist der offering stone","offering stone standort","offering stone finden"}},{q="Wer hat den Offering Stone geschaffen oder nutzt ihn?",a="Die beschädigte Notiz nennt die Ritualisten nicht beim Namen. Auf dem Stein zurückgelassene Werkzeuge und Gegenstände zeigen, dass jemand in der Nähe eine Opfergabe oder einen finsteren Ritus vorbereitete.",al={"wer hat den offering stone geschaffen","wer nutzt den offering stone","wer vollzieht das ritual"}},{q="Was steht in der geheimnisvollen Notiz?",a="Der größte Teil der Notiz ist verwittert und unleserlich. Die erhaltenen Fragmente erwähnen Vorbereitungen für ein Ritual und weisen auf einen Opferstein in der Nähe hin.",al={"welche notiz","notizfetzen silberwald","was steht in der notiz"}},{q="Was liegt auf dem Offering Stone?",a="Seltsame Werkzeuge, Ritualgerätschaften und andere Gegenstände liegen über den rauen Stein verstreut, bestimmt für eine Opfergabe.",al={"welche gegenstände liegen auf dem stein","welche gerätschaften liegen auf dem stein","offering stone gegenstände"}},{q="Was für ein Ritual wird hier vollzogen?",a="Die Notiz beschreibt den Ritus nicht vollständig. Der Stein ist als Altar hergerichtet, auf dem Gegenstände oder Opfer für ein Ritual ausgelegt werden.",al={"welches ritual am offering stone","warum ein opferstein","welche opfergabe im silberwald"}}},fp="18,157,15.246.0,15.183.0,27.173.0,38.80.0,39.145.0,34.141.0,36.110.0,44.129.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="In Berens List verlangt der Zettelfetzen nach Blut am Offering Stone. Ihr bringt eine Gequälte Seele, um der Aufforderung zu folgen.",h="In Berens List verlangt der Zettelfetzen nach Blut am Offering Stone.",kw={"berens list","blutritual","offering of blood","offering stone","opfer","silberwald","the offering of blood","gequälte seele"},ang={["class:Priest"]="Als Priester mag Euch der Einsatz einer gequälten Seele in einem unheilvollen Blutritus beunruhigen, welches Schicksal sie auch erwartet.",["class:Warlock"]="Als Hexenmeister kennt Ihr dunkle Riten und den Handel mit Seelen. Selbst ein erfahrener Anwender der Teufelsmagie mag erschaudern, wenn er einem uralten, unbekannten Stein Blut darbietet."},sec={{t="Der letzte Ritus",b="Tief in Berens List wartet der Offering Stone auf eine letzte Opfergabe. Notizfetzen verlangen nach einem willigen Opfer und führen Euch dazu, Blut zum Altar zu bringen. Als Ihr Euch mit der ruhelosen Essenz nähert, ergreift Euch Grauen."},{t="Der Stein zerbricht",b="Die Gequälte Seele entzieht dem Stein seine verbliebene Macht. Der Ritus zehrt die Macht des uralten Monuments auf, statt einen größeren Schrecken zu wecken. Seine raue Oberfläche bekommt Risse, dann zerfällt es zu Schutt. Etwas Glitzerndes liegt zwischen den zerborstenen Bruchstücken."}},faq={{q="Wo findet dieses Ritual statt?",a="Der Ritus findet am Offering Stone in Berens List im Silberwald statt. Gefahren und finstere Magie suchen die Gegend heim.",al={"wo ist diese quest","wo ist offering of blood","berens list quest"}},{q="Was ist der Offering Stone?",a="Der Offering Stone ist ein uraltes Monument in Berens List. Er verlangt nach dem Blut eines willigen Opfers, um die Macht in seinem Inneren freizusetzen oder aufzuzehren.",al={"was ist der offering stone","offering stone berens list","altar in berens list"}},{q="Wofür wird die Gequälte Seele verwendet?",a="Eine Gequälte Seele wird am Offering Stone dargebracht, um der Forderung des Zettelfetzens nach einem willigen Opfer nachzukommen.",al={"wer ist die gequälte seele","was ist die gequälte seele","welches opfer wird benötigt"}},{q="Was geschieht, wenn die Opfergabe dargebracht ist?",a="Der Ritus zehrt die Macht auf, die den Offering Stone belebt. Der raue Stein bekommt Risse und zerbröckelt, wobei etwas Glitzerndes zwischen seinen Überresten zurückbleibt.",al={"was geschieht mit dem stein","zerbricht der stein","was geschieht nach dem ritual"}},{q="Wer hat den Stein erschaffen und warum?",a="Niemand weiß, wer den Offering Stone erschaffen hat oder warum. Der Ritus zehrt seine Macht auf und zerstört ihn, doch die Absicht seines Schöpfers bleibt unbekannt.",al={"wer hat den offering stone errichtet","zweck von offering of blood","warum wurde der stein erschaffen"}},{q="Was ist Berens List?",a="Berens List ist eine felsige Landmarke im Silberwald, wo wilde Tiere und verborgene Gefahren lauern. Auch dunkle Riten und ruhelose Seelen haben dort ihre Spuren hinterlassen.",al={"was ist berens list","berens list hintergrundgeschichte","warum heißt es berens list"}}},fp="21,114,14.216.0,18.241.1,34.127.0,27.140.0,35.106.0,44.144.0,30.132.0,22.161.0"}
P.entries["quest:959"] = {n="Ärger auf den Docks",s="In Ratschet gefährdet eine gestohlene Flasche Bigglefuzz' Arbeitsplatz. Mad Magglish floh mit einem 99 Jahre alten Portwein, einem Geschenk von Baron Revilgaz an Gazlowe, landeinwärts und versteckt sich nun in den Höhlen des Wehklagens.",h="In Ratschet gefährdet eine gestohlene Flasche Bigglefuzz' Arbeitsplatz.",kw={"bigglefuzz","beutebucht","gazlowe","magglish","portwein","ratschet","revilgaz","die höhlen des wehklagens"},ang={["class:Rogue"]="Als Schurke könnt Ihr Mad Magglishs nachlässige Tarnung in den Höhlennischen durchschauen, wo der Dieb sich mit einfachen Mitteln tarnt, um unbemerkt zu bleiben.",["faction:Alliance"]="Als Mitglied der Allianz reist Ihr tief ins von der Horde beherrschte Brachland, wo gute Beziehungen zu den Hafenbetreibern von Steamwheedle zur sicheren Durchfahrt durch neutrale Gewässer beitragen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr Ratschets Hafenarbeitern, den reibungslosen Betrieb des wichtigsten neutralen Hafens zwischen Kalimdor und den Östlichen Königreichen zu gewährleisten."},sec={{t="Ein ungeschicktes Missgeschick",b="Über Ratschets Docks läuft der Seehandel mit Beutebucht über das große Meer. Eines Morgens traf eine gewaltige Lieferung ein, und Kranführer Moppelfuzz überlud seinen Kran, um sie schneller zu entladen. Der Kran ließ die gesamte Ladung über die Docks fallen. Im Durcheinander schnappte sich Mad Magglish, ein örtlicher Unruhestifter, eine wertvolle Flasche Alkohol und floh landeinwärts."},{t="Ein diplomatischer Jahrgang",b="Die Flasche enthält einen 99 Jahre alten Portwein, ein persönliches diplomatisches Geschenk von Baron Revilgaz, Beutebuchts Herrscher, an Gazlowe, Ratschets Chefingenieur und Vorsteher. Ihr Verlust könnte Bigglefuzz demütigen und beide Handelsoberhäupter erzürnen. Aus Angst um seinen Arbeitsplatz oder vor Schlimmerem folgte Bigglefuzz dem Dieb bis zum Eingang der Höhlen des Wehklagens. Doch die Furcht hielt ihn davon ab, hineinzugehen."},{t="Das Höhlenversteck",b="Mad Magglish versteckt sich in feuchten Naturtunneln außerhalb des inneren Zugangs der Höhlen des Wehklagens, nicht tief in der verdorbenen Traumwelt. Der Dieb verlässt sich auf ungeschickte Tarnung und dunkle Nischen und hofft, dass seine Verfolger aufgeben. Findet Magglish in den äußeren Höhlen, bevor der Portwein entkorkt oder zerstört wird."}},faq={{q="Warum ist diese Flasche Portwein so wichtig?",a="Der 99 Jahre alte Portwein ist ein kostbares persönliches Geschenk von Baron Revilgaz aus Beutebucht an Gazlowe, Ratschets Oberhaupt. Sein Verlust könnte Ratschets Führung erzürnen und Kranführer Moppelfuzz seine Lebensgrundlage kosten.",al={"warum ist bigglefuzz das wichtig","was ist der 99 jahre alte portwein","warum ist der wein wichtig"}},{q="Wer ist Mad Magglish?",a="Mad Magglish ist ein Dieb und Unruhestifter, der sich in Ratschet herumtreibt. Als Bigglefuzz eine gewaltige Frachtladung auf die Docks fallen ließ, schnappte sich Magglish den seltenen Portwein und floh in die nahe gelegenen Höhlen des Wehklagens.",al={"wer ist magglish","wer hat den portwein gestohlen","mad magglish geschichte"}},{q="Muss ich den Dungeon der Höhlen des Wehklagens betreten, um den Dieb zu finden?",a="Nein. Mad Magglish versteckt sich in den gewundenen Höhlengängen außerhalb des Instanzportals und tarnt sich schlecht in den oberen Seitentunneln oder nahe den überfluteten Kammern am Haupteingang.",al={"ist magglish in der instanz","wo ist mad magglish","magglish finden"}},{q="Wie kam es zu dem Missgeschick mit der Fracht?",a="Eine gewaltige Frachtlieferung aus Beutebucht traf ein, und Kranführer Moppelfuzz versuchte, mehr Kisten auf einmal zu entladen, als seine Ausrüstung bewältigen konnte. Der überladene Kran ließ die Ladung über Ratschets Docks fallen.",al={"warum fielen die kisten herunter","was hat bigglefuzz getan","kranmissgeschick ratschet"}},{q="Welche Beziehung besteht zwischen Ratschet und Beutebucht?",a="Ratschet und Beutebucht sind Hafenstädte des Steamwheedle Cartel, verbunden durch Handel und Freibeuterflotten. Regelmäßige Lieferungen und förmliche Höflichkeiten zwischen Baron Revilgaz im Süden und Gazlowe im Brachland erhalten ihr gemeinsames Handelsimperium aufrecht.",al={"verbindung zwischen ratschet und beutebucht","steamwheedle häfen","revilgaz und gazlowe"}},{q="Warum hat Bigglefuzz die Flasche nicht selbst zurückgeholt?",a="Bigglefuzz folgte dem Dieb bis zum Eingang der Höhlen des Wehklagens, doch der unheimliche Ruf des unterirdischen Labyrinths und seine monströsen Bewohner ließen ihn an der Schwelle haltmachen.",al={"warum hat der goblin ihn nicht geholt","warum gab bigglefuzz die verfolgung auf"}}},fx={b908c2b9={q="Warum braucht Kranführer Moppelfuzz diesen Hafen zurück?",a="Moppelfuzz' Arbeit steht auf dem Spiel. Als er versuchte, mehr Kisten abzuladen, als sein Kran bewältigen konnte, stürzte die gesamte morgendliche Lieferung aus Beutebucht ab. In dem Chaos ging die wertvolle Flasche mit neunundneunzigjährigem Hafenwein verloren, und der Hafenmeister sitzt ihm seither im Nacken. Da der Jahrgang ein persönliches Geschenk für Ratschets Chefingenieur, Gazlowe, war, bedeutet das Versäumnis, ihn wiederzubekommen, dass Moppelfuzz kurz vor der Entlassung steht.",al={"warum will moppelfuzz den hafenwein","moppelfuzz motiv","warum moppelfuzz helfen"}}},fp="20,185,15.333.0,18.354.0,18.284.0,40.201.0,20.201.0,65.176.0,31.206.0,55.245.0,50.185.0"}
P.entries["quest:95912"] = {n="WANTED: Blademaster Kaijo",s="Ember Bladewhisper sucht Blademaster Kaijo in einem Ausbildungslager nördlich des Außenpostens der Horde. Sein Banner soll die Moral der Orcs schwächen und den Kampfeswillen von Embers Auszubildenden stärken.",h="Ember Bladewhisper sucht Blademaster Kaijo in einem Ausbildungslager nördlich des Außenpostens der Horde.",kw={"blademaster kaijo","blademaster’s banner","ember bladewhisper","burg farholde","außenposten der horde","kaijo","orc-auszubildende","ausbildungslager"},sec={{t="Ein Kampf gerät ins Wanken",b="Ember Bladewhisper fürchtet, dass jeder gefallene Orc durch einen fähigeren Soldaten ersetzt wird. Sie glaubt, ein Blademaster bilde sie aus, und sagt, Kaijo halte sich wahrscheinlich im Ausbildungslager nördlich des Außenpostens der Horde auf. Ihr sollt sein Banner zur Burg Farholde bringen."},{t="Der Zweck eines Banners",b="Ember sagt, die Bedrohung durch die Orcs scheine endlos, und der Kampfeswille ihrer Soldaten schwinde. Sie hofft, Kaijos Banner werde ihren Auszubildenden zeigen, dass die Horde nichts zu fürchten ist."}},faq={{q="Wer ist Blademaster Kaijo?",a="Ember Bladewhisper beschreibt Kaijo als Blademaster, der wahrscheinlich Orcs in einem Ausbildungslager nördlich des Außenpostens der Horde ausbildet.",al={"wer ist kaijo","kaijos hintergrund"}},{q="Warum will Ember Kaijo finden?",a="Ember glaubt, Kaijo bilde eine neue Generation fähiger Orc-Soldaten aus, und fürchtet, ihre Zahl werde wieder anwachsen.",al={"warum kaijo finden","grund für kaijos gesuchtmeldung"}},{q="Wo glaubt Ember, dass Kaijo ist?",a="Ember sagt, Kaijo halte sich wahrscheinlich im Ausbildungslager nördlich des Außenpostens der Horde auf.",al={"wo ist kaijo","kaijos aufenthaltsort"}},{q="Was soll zur Burg Farholde gebracht werden?",a="Ember bittet Euch, ihr das Blademaster’s Banner zur Burg Farholde zu bringen.",al={"kaijos banner","was nach farholde bringen"}},{q="Warum will Ember das Banner?",a="Ember hofft, das Banner werde die Moral der Orcs schwächen und ihren Auszubildenden versichern, dass die Horde nichts zu fürchten ist.",al={"zweck des banners","warum kaijos banner holen"}},{q="Was beunruhigt Ember am Kampf?",a="Ember fürchtet, die Bedrohung durch die Orcs sei endlos und der Kampfeswille ihrer Soldaten schwinde.",al={"ember ist besorgt","bedrohung durch orcs"}}},fp="25,187,17.254.0,18.164.0,25.126.0,32.111.0,32.74.0,46.75.0,31.106.0,35.84.0"}
P.entries["quest:95951"] = {n="Fetch 'n' Fletch",s="Tan’jani bietet Euch an, beizubringen, wie Ihr Speere für die Kopfjäger der Horde herstellt. Ihr sollt Holz im Turner's Logging Camp holen, um daraus Speere zu schnitzen.",h="Tan’jani bietet Euch an, beizubringen, wie Ihr Speere für die Kopfjäger der Horde herstellt.",kw={"fetch 'n' fletch","kopfjäger","horde","behelfsmäßige speere","tan’jani","turner's logging camp","holzbündel"},sec={{t="Holz für Speere",b="Tan’jani, ein Kopfjäger, bittet Euch, Holz im Turner's Logging Camp zu sammeln, dem Menschenlager im Westen. Mit einem Messer könnt Ihr das Holz zu Speeren zuspitzen, um Menschen aufzuspießen, bevor sie Euch kommen sehen. Tan’jani möchte, dass Ihr die Speere zurückbringt."}},faq={{q="Wer ist Tan’jani?",a="Tan’jani ist ein Kopfjäger, der Euch anbietet, beizubringen, Speere herzustellen.",al={"tan’jani wer","wer ist tanjani"}},{q="Was möchte Tan’jani, dass ich hole?",a="Tan’jani bittet Euch, Holz von den Holzstapeln der Bauern im Turner's Logging Camp zu sammeln und daraus behelfsmäßige Speere herzustellen.",al={"welches holz","speere holen"}},{q="Wo ist das Holz?",a="Das Holz liegt auf den Holzstapeln der Bauern im Turner's Logging Camp, dem Menschenlager im Westen.",al={"fundort des holzes","wo ist das holz"}},{q="Warum möchte Tan’jani Speere?",a="Tan’jani sagt, Kopfjäger verwenden Speere, um Menschen zu treffen, bevor sie sie kommen sehen.",al={"warum speere","speere der kopfjäger"}}},fp="16,149,15.251.0,18.66.0,36.118.0,18.86.0,32.84.0"}
P.entries["quest:95955"] = {n="Stick 'Em",s="Tran'jani in Rog'mar bringt Euch in den Flusslanden das Speerwerfen bei. Freshwater Crocolisks dienen ihm als Ziele, und er hofft, Euch so zu einem Kopfjäger auszubilden.",h="Tran'jani in Rog'mar bringt Euch in den Flusslanden das Speerwerfen bei.",kw={"freshwater crocolisk","kopfjäger","flusslande","rog'mar","speerwerfen","speere","spieß sie auf","tran'jani"},sec={{t="Ein Crocolisk als Ziel",b="Tran'jani in Rog'mar hat Speere für Euch und möchte, dass Ihr lernt, sie zu werfen. In den Flusslanden gibt es viele Freshwater Crocolisks, die er gefährlich nennt. Er stellt sie als Ziele für Euer Training auf."},{t="Das Versprechen eines Kopfjägers",b="Nach Eurem Training lobt Tran'jani Eure Arbeit und sagt, Ihr hättet das Zeug zu einem echten Kopfjäger. Er bittet Euch, an ihn zu denken, wenn Ihr berühmt werdet."}},faq={{q="Wer ist Tran'jani?",a="Tran'jani gibt Euch in Rog'mar Speere und bringt Euch bei, sie zu werfen.",al={"tran'jani","wer ist tran'jani","alter troll"}},{q="Warum schickt Tran'jani mich zu den Crocolisks?",a="Tran'jani verwendet die Freshwater Crocolisks der Flusslande als Ziele für das Speerwurftraining.",al={"warum crocolisks","crocolisk-training","krokos aufspießen"}},{q="Was möchte Tran'jani von mir?",a="Tran'jani möchte, dass Ihr in den Flusslanden das Werfen von Speeren auf Freshwater Crocolisks übt.",al={"was soll ich tun","spieß sie auf","speerwurfziele"}},{q="Wo geschieht das?",a="Tran'jani gibt Euch in Rog'mar die Speere und weist Euch für das Training den Weg zu den Flusslanden.",al={"wo ist tran'jani","quest in den flusslanden","rog'mar"}},{q="Was sagt Tran'jani über die Crocolisks?",a="Tran'jani warnt, dass die Freshwater Crocolisks gefährlich sind und Euch schnappen können, wenn Ihr nicht schnell seid.",al={"sind krokos gefährlich","gefahr durch crocolisks","dich schnappen"}}},fp="9,180,18.200.0,22.154.1,17.83.0,44.99.0,34.92.0,24.93.0,45.102.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Schattenpriester Allister schickt die Verlassenen gegen Patrouillen der Kirin Tor nahe Mühlenbern. Seit Dalarans Barriere gefallen ist, bewachen ihre Zauberer und Wachposten die Straßen in den Silberwald und bringen dabei magische Güter ins Gebiet der Verlassenen.",h="Schattenpriester Allister schickt die Verlassenen gegen Patrouillen der Kirin Tor nahe Mühlenbern.",kw={"mühlenbern","dalaran watcher","dalaran wizard","kirin tor","anhänger","relikte","das grabmal","schattenpriester allister","silberwald","watching the roads"},ang={["class:Mage"]="Als Magier steht Ihr Dalarans Zauberern und Wachposten gegenüber, die mit magischen Relikten und Patrouillen die Wege sichern. Ihre Arbeit macht sie zu Zielen rivalisierender Zauberwirker.",["class:Priest"]="Als Priester seht Ihr, wie Schattenpriester Allister die Offensive vom Grabmal aus leitet, wo Geistliche der Verlassenen aktiv an der Grenzverteidigung mitwirken.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Dalarans Versorgungslinien nahe Mühlenbern zu unterbrechen und die Region gegen feindliche Enklaven der Menschen zu halten.",["race:Undead"]="Als Untoter helft Ihr, die Straßen des Silberwalds zu sichern und die Grenzen der Verlassenen gegen Dalarans magische Vorstöße zu verteidigen."},sec={{t="Spannungen an der Straße nach Mühlenbern",b="Nahe Mühlenbern überwachen Zauberer und Wachen der Kirin Tor die Straßen in den Silberwald. Seit die Barriere um Dalaran gefallen ist, haben sie ihre Kontrolle über den Grenzverkehr verschärft. Vom Grabmal aus sehen die Verlassenen, wie die menschlichen Magier diese Straßen nutzen, um gefährliche Relikte und verzauberte Anhänger in umkämpfte Gebiete zu bringen."},{t="Die Versorgungslinie durchtrennen",b="Schattenpriester Allister will den Zustrom magischer Güter aus Dalaran an der Quelle stoppen. Er schickt Agenten gegen die Begleittruppen der Kirin Tor auf den Straßen nahe Mühlenbern. Durch Angriffe auf Dalaran Wizards und Dalaran Watchers wollen die Verlassenen die Kontrolle der Kirin Tor über den regionalen Reiseverkehr brechen und ihre Ostgrenze vor arkaner Einmischung von außen schützen."}},faq={{q="Wer vergibt die Quest Watching the Roads?",a="Schattenpriester Allister erteilt den Auftrag vom Grabmal im Silberwald aus. Er schickt Streiter gegen Patrouillen der Kirin Tor auf den örtlichen Straßen.",al={"wer vergibt watching the roads","questgeber watching the roads","wo watching the roads abgeben"}},{q="Warum greifen die Verlassenen Dalarans Patrouillen nahe Mühlenbern an?",a="Schattenpriester Allister will verhindern, dass magische Relikte und Anhänger aus Dalaran in den Silberwald gelangen. Angriffe auf die Zauberer und Wachposten nahe Mühlenbern unterbinden ihren Weg über die Grenzen der Verlassenen.",al={"warum dalaran wizards töten","warum straßen um mühlenbern angreifen","absichten der kirin tor im silberwald"}},{q="Wie steht es um die Barriere um Dalaran?",a="Die Barriere um Dalaran ist gefallen. Die Kirin Tor haben ihre Überwachung der nahen Straßen verstärkt und patrouillieren misstrauisch in der Gegend um Mühlenbern.",al={"was geschah mit dalarans barriere","dalarans kuppel gefallen","barriere gefallen dalaran"}},{q="Wo sind die Zauberer und Wächter von Dalaran zu finden?",a="Dalaran Wizards und Dalaran Watchers patrouillieren auf den Straßen rund um Mühlenbern im Silberwald. Sie überwachen den Reiseverkehr und bewachen Angehörige der Kirin Tor sowie verzauberte Gegenstände.",al={"wo sind dalaran watchers","patrouillenstandorte mühlenbern","wo dalaran wizards finden"}},{q="Welche Gegenstände transportiert Dalaran auf diesen Straßen?",a="Die Kirin Tor bringen verzauberte Anhänger und andere magische Relikte aus Dalaran in den Silberwald. Allister will sie aufhalten, bevor sich die Artefakte weiter im Gebiet verbreiten.",al={"welche relikte transportiert dalaran","was sind die anhänger","anhänger mühlenbern"}},{q="Warum sind die Kirin Tor auf den Straßen um Mühlenbern so wachsam?",a="Die Kirin Tor überwachen die Straßen in den Silberwald genau, seit Dalarans magische Barriere gefallen ist. Allister sieht ihr Misstrauen und ihre Wachsamkeit, doch die Verlassenen im Grabmal kennen ihre genauen Beweggründe nicht.",al={"warum sind die kirin tor paranoid","warum patrouillieren dalarans wachen","straßenkontrolle der kirin tor"}}},fp="18,228,33.326.0,24.339.0,39.144.0,62.207.0,54.143.0,52.161.0,57.187.0,60.210.0"}
P.entries["quest:95982"] = {n="Not My Circus",s="Jasper Geartoggle bittet Euch, verlassene Tiere im Hafen von Powderfuse mit Futter zu versorgen. Er braucht Briny Seafood Stew, bevor die hungrigen Tiere Ärger machen.",h="Jasper Geartoggle bittet Euch, verlassene Tiere im Hafen von Powderfuse mit Futter zu versorgen.",kw={"briny seafood stew","pferde","hungrige tiere","jasper geartoggle","nicht mein zirkus","hafen von powderfuse","wölfe"},sec={{t="Hungrige Tiere",b="Im Hafen von Powderfuse bittet Jasper Geartoggle Euch um Hilfe mit den Tieren, die man ihm anvertraut hat. Ihre Besitzer geben ihm die Schuld, wenn ein Pferd, ein Wolf oder ein anderes Tier stirbt oder davonläuft. Er braucht Briny Seafood Stew, um sie im Zaum zu halten, bevor der Hunger sie zu einer Stampede treibt."}},faq={{q="Wer bittet um Hilfe?",a="Jasper Geartoggle bittet Euch, die Tiere zu füttern, die man seiner Obhut überlassen hat.",al={"wer braucht hilfe","wer ist jasper","jasper geartoggle"}},{q="Was braucht Jasper?",a="Jasper braucht Briny Seafood Stew für die Tiere in seiner Obhut.",al={"welches futter will er","welcher eintopf","briny stew"}},{q="Warum braucht Jasper Eintopf?",a="Jasper sagt, die Tiere seien hungrig und er brauche Futter, um sie im Zaum zu halten.",al={"warum eintopf","hungrige tiere","tiere in not"}},{q="Wohin soll ich den Eintopf bringen?",a="Bringt den Briny Seafood Stew zu Jasper Geartoggle in den Hafen von Powderfuse.",al={"wo ist jasper","wohin eintopf bringen","hafen von powderfuse"}},{q="Warum werden Tiere bei Jasper gelassen?",a="Die Leute lassen Jasper immer wieder ihre Pferde, Wölfe und anderen Tiere da.",al={"verlassene tiere","wer hat die tiere dagelassen","warum sind die tiere hier"}}},fp="13,149,13.261.0,23.69.0,22.60.0,26.75.0,30.69.0,39.72.0"}
P.entries["quest:95991"] = {n="WANTED: Ghostmaw",s="Wheatley fürchtet, dass ein Phantom-Krokilisk namens Ghostmaw seine preisgekrönten Ponys an den Flüssen reißt. Er wartet auf Burg Farholde, bis ihm jemand den Fang der Bestie bringt.",h="Wheatley fürchtet, dass ein Phantom-Krokilisk namens Ghostmaw seine preisgekrönten Ponys an den Flüssen reißt.",kw={"krokilisk","fang","burg farholde","ghostmaw","lichtungen","ponys","flüsse","wheatley"},sec={{t="Wheatleys Sorge",b="Wheatley lässt seine Pferde wegen Berichten über Ghostmaw an den Flüssen nicht mehr durch die Lichtungen treiben. Der Krokilisk soll dreimal so groß und doppelt so bösartig wie ein gewöhnlicher sein. Bringt Wheatley Ghostmaws Fang, damit er weiß, dass die Reise wieder sicher ist."}},faq={{q="Wer ist Ghostmaw?",a="Ghostmaw ist ein geheimnisvoller Phantom-Krokilisk, von dem an den Flüssen berichtet wird. Er soll viel größer und bösartiger als ein gewöhnlicher Krokilisk sein.",al={"ghostmaw","ghostmaw krokilisk","phantom-krokilisk"}},{q="Warum lässt Wheatley seine Pferde nicht mehr weiterziehen?",a="Wheatley fürchtet, dass Ghostmaw seine preisgekrönten Ponys verschlingt, und bleibt deshalb, wo er ist, bis die Bestie erledigt ist.",al={"warum wheatley aufgehört hat","pferde ziehen nicht weiter","wheatley hat angst"}},{q="Was möchte Wheatley gebracht bekommen?",a="Wheatley bittet um Ghostmaws Fang als Beweis dafür, dass der Krokilisk keine Gefahr mehr für Reisende darstellt.",al={"ghostmaws fang","was wheatley bringen","fang"}},{q="Wohin soll ich Ghostmaws Fang bringen?",a="Bringt Ghostmaws Fang zu Wheatley auf Burg Farholde.",al={"wo ist wheatley","burg farholde","fundort des fangs"}}},fp="16,167,20.269.0,16.130.0,43.106.0,39.96.0,39.53.0"}
P.entries["quest:95992"] = {n="WANTED: Ghostmaw",s="Tan'jani veranstaltet einen Wettkampf um Ghostmaw, einen weißen Krokilisk, der die Flüsse heimsucht. Bringt seinen Fang zu Rog'mar und sichert Euch den Preis.",h="Tan'jani veranstaltet einen Wettkampf um Ghostmaw, einen weißen Krokilisk, der die Flüsse heimsucht.",kw={"krokilisk","fang","ghostmaw","kopfjäger","flüsse","rog'mar","tan'jani"},sec={{t="Wettkampf am Fluss",b="Tan'jani in Rog'mar veranstaltet einen Wettkampf für Euch. Ein weißer Krokilisk namens Ghostmaw heimsucht die Flüsse, und selbst die Kopfjäger haben ihn noch nicht gefangen. Bringt Ghostmaw's Fang zu Tan'jani. Der Gewinner erhält den Preis."}},faq={{q="Wer ist Ghostmaw?",a="Ghostmaw ist ein weißer Krokilisk, der die Flüsse heimsucht.",al={"ghostmaw","weißer krokilisk","ghostmaw-krokilisk"}},{q="Wer will Ghostmaw's Fang?",a="Tan'jani in Rog'mar bittet Euch, Ghostmaw's Fang zu bringen.",al={"tan'janis fang","wer will den fang","fang für wen"}},{q="Was soll ich Tan'jani bringen?",a="Tan'jani möchte Ghostmaw's Fang.",al={"ghostmaw's fang","was soll ich bringen","fang"}},{q="Worum geht es bei dem Wettkampf?",a="Tan'jani sagt, dass der Gewinner des Wettkampfs, Ghostmaw zu fangen, den Preis erhält.",al={"tan'janis wettkampf","der preis","warum ghostmaw fangen"}}},fp="16,136,17.206.0,16.53.0,26.54.0,36.31.0,30.77.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="An Sams Feuer lernen Reisende, zu rasten und die Strapazen des Weges zu überstehen. Dann können sie sich Handwerksberufen und der Arbeit in der Wildnis widmen.",h="An Sams Feuer lernen Reisende, zu rasten und die Strapazen des Weges zu überstehen.",kw={"einfaches lagerfeuer","boosted rest","lagervorrichtung","lagerfertigkeiten","wildniskundiger","sam","the great outdoors","handwerksberuf"},ang={["class:Hunter"]="Als Jäger seid Ihr vielleicht damit vertraut, Euch aus der Natur zu versorgen und an einem offenen Feuer zu rasten. Selbst erfahrene Späher profitieren davon, die Kunst des Lagerlebens zu erlernen.",["profession:Cooking"]="Als Koch schafft Ihr Euch mit dem Erlernen des Lagerbaus eine Grundlage für die Zubereitung von Mahlzeiten unter freiem Himmel."},sec={{t="Lektionen am Feuer",b="Sam heißt rastlose Reisende willkommen, die Azeroth auf der Suche nach Glück, Gefahr und Ruhm durchqueren. Ehrgeiz allein kann einen Neuling weder wärmen noch die Mühen des Weges lindern. An seinem Feuer lernt Ihr, wann Ihr rasten solltet, wie Ihr ein Feuer entfacht und wie Ihr Kraft für die Reise sammelt."},{t="Wildnisfertigkeiten und Handwerk",b="Ein Lagerfeuer spendet Wärme gegen die nächtliche Kälte und bietet Gelegenheit zu erholsamerer Rast. Wer die Wildnis kennt, weiß, dass Ausdauer durch Ruhe zwischen den Reisen entsteht. Sobald Ihr diese Grundlagen erlernt habt, könnt Ihr Euch Handwerksberufen widmen. Handwerker und Sammler können lernen, Lagervorrichtungen herzustellen, die sich für ihre Arbeit im Gelände eignen."}},faq={{q="Wer ist Sam?",a="Sam ist ein erfahrener Wildniskundiger und Reisender, der Neulingen beibringt, in der Wildnis zu bestehen. Er lädt sie ein, an seinem Feuer zu sitzen und praktische Wege zu erlernen, die Strapazen der Reise zu meistern.",al={"wer ist sam","sam lagerfeuerquest","questgeber"}},{q="Wozu dient das Sitzen am Lagerfeuer?",a="Boosted Rest ist die Erholung, die das Rasten an einem richtigen Lagerfeuer in der Wildnis bietet. Seine Wärme und Behaglichkeit helfen müden Reisenden, sich zu erholen und ihre Reise fortzusetzen.",al={"was ist boosted rest","boosted rest verstärkung","am feuer rasten"}},{q="Warum sind Wildnisfertigkeiten für Abenteurer wichtig?",a="Wildnisfertigkeiten helfen Reisenden, den Gefahren und langen Wegstrecken jenseits der Siedlungsmauern standzuhalten. Mit diesen Fertigkeiten können sie sich selbst versorgen, ohne der Erschöpfung zu erliegen.",al={"warum wildnisfertigkeiten lernen","warum in der wildnis gedeihen","überlebensfertigkeiten"}},{q="Was haben Handwerksberufe mit dem Lagern in der Wildnis zu tun?",a="Nachdem Ihr gelernt habt, ein einfaches Lager zu errichten, können Berufslehrer Euch beibringen, Lagervorrichtungen herzustellen, die sich für Eure Arbeit im Gelände eignen.",al={"handwerksberufe und lagern","lagervorrichtungen","berufe danach"}},{q="Was sollte ein Abenteurer nach Abschluss dieser Lektion tun?",a="Nachdem Ihr an Sams Feuer gerastet und die Grundlagen des Lagerlebens erlernt habt, könnt Ihr Berufslehrer aufsuchen. Ein praktisches Handwerk ermöglicht es Euch, Arbeitsstationen im Gelände zu errichten, die zu Eurem Beruf passen.",al={"nächste schritte","was nach great outdoors","nach der lagerfeuerquest"}},{q="Wer kann The Great Outdoors angehen?",a="Jeder Reisende, der in die weite Welt aufbricht, kann diese Lektionen erlernen, unabhängig von Herkunft oder Zugehörigkeit.",al={"kann das jeder machen","wer kann great outdoors annehmen","ist diese quest allgemein"}}},fp="18,117,19.257.0,20.322.0,11.166.0,47.169.0,52.162.0,48.128.0,58.167.0,37.111.0"}
P.entries["quest:95999"] = {n="WANTED: Incinerator Gar'im",s="In Seenhain setzt Magistrat Solomon ein Kopfgeld auf Verbrenner Gar'im aus, dessen Truppen die Stadt bedrohen. Der feindliche Orkkommandant hält Renders Tal mit Schattenzauberern und soll mit dem Schwarzfelsklan auf Burg Steinwacht zusammenarbeiten.",h="In Seenhain setzt Magistrat Solomon ein Kopfgeld auf Verbrenner Gar'im aus, dessen Truppen die Stadt bedrohen.",kw={"schwarzfels","kopfgeld","gar'im","verbrenner","seenhain","renders tal","schattenzauberer","solomon"},ang={["class:Mage"]="Als Magier stellt Ihr Euch Gar'im und seinen Schattenzauberern, die eine verderbte Form von offensiver Arkanmagie und Shadow Magic wirken. Antwortet ihnen rasch mit Gegenzaubern.",["faction:Alliance"]="Als Kämpfer der Allianz schützt Ihr Seenhains verwundbare Bürger vor dem Anführer eines orkischen Einfalls und seinen gefährlichen Schattenzauberern, wenn Ihr Verbrenner Gar'im besiegt."},sec={{t="Ein Feuer in Renders Tal",b="Schwarzfelsorcs rücken aus ihren Gebirgsfestungen vor und machen das Rotkammgebirge gefährlicher. In Renders Tal führt Gar'im mit treuen Schattenzauberern und dunkler Magie einen Einfall an. Seenhains Wache ist überlastet, und die Armeen der Krone sind weitgehend abwesend. Deshalb ruft Magistrat Solomon unabhängige Kämpfer dazu auf, Gar'im auszuschalten, der mit den Schwarzfelsorcs auf Burg Steinwacht zusammenarbeiten soll."},{t="Beweise des Ablebens",b="Gar'im ist für zerstörerische Magie und seinen Befehl über schattenwebende Zauberer bekannt. Um die Belohnung der Stadt zu erhalten, dringen Jäger in feindlich besetztes Gebiet ein und besiegen ihn. Sie müssen seinen zertrümmerten Stab zum Rathaus von Seenhain zurückbringen, als Beweis dafür, dass die Bedrohung beendet ist."}},faq={{q="Wer ist Verbrenner Gar'im?",a="Verbrenner Gar'im ist ein orkischer Kriegsherr und Zauberwirker, der einen Einfall in Renders Tal anführt. Er soll mit den Schwarzfelsorcs von Burg Steinwacht zusammenarbeiten und befehligt gefährliche Schattenzauberer.",al={"wer ist gar'im","garim","verbrenner garim"}},{q="Wo ist Verbrenner Gar'im zu finden?",a="Gar'im lagert unter feindlichen Orktruppen in Renders Tal im südöstlichen Rotkammgebirge.",al={"gar'im fundort","wo ist garim","renders tal lage"}},{q="Wer hat das Kopfgeld auf Gar'im ausgesetzt?",a="Magistrat Solomon setzt das Kopfgeld im Namen Seenhains aus, um die orkischen Vorstöße gegen die umkämpfte Stadt einzudämmen.",al={"wer hat das kopfgeld ausgesetzt","solomon kopfgeld"}},{q="Welcher Beweis ist nötig, um das Kopfgeld zu erhalten?",a="Magistrat Solomon verlangt den Zerbrochenen Stab von Verbrenner Gar'im als Beweis für den Tod des Zauberwirkers, bevor er die Belohnung auszahlt.",al={"garim beweis","zerbrochener stab questgegenstand"}},{q="Welche Bedrohung geht von Gar'im und seinen Anhängern aus?",a="Gar'im wirkt tödliche zerstörerische Magie und wird von Schattenzauberern flankiert. Gemeinsam festigen sie die Kontrolle des Schwarzfelsklans im Rotkammgebirge und drohen Seenhain zu überrennen, wenn ihnen niemand Einhalt gebietet.",al={"gar'im fähigkeiten","schattenzauberer rotkammgebirge"}},{q="Warum verlässt sich Seenhain auf Kopfgelder statt auf die Armee von Sturmwind?",a="Angesichts politischer Zwistigkeiten und Truppenmangels hat Sturmwind das Rotkammgebirge bei seiner Verteidigung weitgehend sich selbst überlassen. Magistrat Solomon musste bereitwillige Kämpfer anheuern, um feindliche Anführer zu töten.",al={"warum kopfgelder seenhain","wo ist die armee von sturmwind"}}},fp="26,235,25.404.0,15.259.0,26.193.0,38.97.0,33.128.0,43.128.0,45.190.0,68.170.0"}
P.entries["quest:96"] = {n="Ruf des Wassers",s="Ihr bringt Islen Wasserdeuter den Wassersplitter an die Küste des Brachlands. Diese Rückkehr zeigt Euren Einklang mit wiederherstellenden Energien und bringt Euch ein Wassertotem ein.",h="Ihr bringt Islen Wasserdeuter den Wassersplitter an die Küste des Brachlands.",kw={"ruf des wassers","islen wasserdeuter","schwache wassermanifestation","wassersplitter","silberwald","brachland","wassertotem"},ang={["class:Shaman"]="Als Schamane erhaltet Ihr Euer Wassertotem und gewinnt Zugang zu wiederherstellenden Quellen und reinigenden Brunnen, die für Eure Rolle als spiritueller Heiler entscheidend sind.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr Mitverantwortung für die Geister des Landes. Junge Schamanen werden dazu aufgerufen, verseuchte Gebiete in Kalimdor und den Östlichen Königreichen zu reinigen."},sec={{t="Ein langer Heimweg",b="Ihr tragt ein Geschenk der Schwachen Wassermanifestation über das Meer zurück. Um es zu verdienen, habt Ihr Kontinente überquert und seid an den verseuchten Ufern des Silberwalds der Verderbnis entgegengetreten. Wasser spendet Leben, passt sich an und heilt, doch seine nachgiebige Natur macht es anfällig für Verseuchung und dunkle Magie.\n\nVor der Schwachen Wassermanifestation habt Ihr reinen elementaren Willen erlebt und den Wassersplitter erhalten. Nun kehrt Ihr ins sonnenverbrannte Brachland zurück, wo Euch der Splitter daran erinnert, dass Wasser ferne Winkel der Welt verbindet."},{t="Das Wassertotem",b="Wenn Ihr Islen Wasserdeuter den Splitter übergebt, beurteilt sie mehr als den Beweis Eurer Reise. Sie prüft, ob Ihr das Gleichgewicht zwischen Bewahrung und Erneuerung erlernt habt. Die sich ausbreitende Fäulnis Lordaerons kann kleine Siege verbergen, doch selbst die Reinigung einer einzigen Quelle bedeutet den Geistern viel. Islen nimmt Eure Gabe an und gibt Euch ein Wassertotem. Durch dieses könnt Ihr reinigende, heilende und manawiederherstellende Ströme in die Welt der Sterblichen leiten, was Euch an die Gezeiten bindet."}},faq={{q="Was ist der Wassersplitter?",a="Der Wassersplitter ist ein elementares Überbleibsel, das Euch die Schwache Wassermanifestation überreicht hat. Er zeigt, dass Ihr die lebensspendende Kraft des Wassers versteht und Euch der Verderbnis entgegengestellt habt, die elementare Ströme bedroht.",al={"wassersplitter","was ist der splitter"}},{q="Wohin bringe ich den Wassersplitter?",a="Bringt den Wassersplitter zu Islen Wasserdeuter in ihrem abgelegenen Lager an der Ostküste des Brachlands, südlich von Ratschet.",al={"wo abgeben","wer bekommt den splitter","abgabeort"}},{q="Was erhalte ich für den Abschluss dieser Prüfung?",a="Ihr erhaltet ein Wassertotem, einen Fokus, den Schamanen benötigen, um elementare Wassertotems für Heilung und wiederherstellende Magie zu rufen.",al={"questbelohnung","totembelohnung","was bekomme ich"}},{q="Warum fand die Prüfung im Silberwald statt?",a="Die Gewässer des Silberwalds sind durch Seuche und Shadow Magic stark verdorben. Dort habt Ihr die Verletzlichkeit des Wassers erlebt und seine natürliche Reinheit gegen den Verfall verteidigt.",al={"warum silberwald","warum östliche königreiche","wasser im silberwald"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Taurenschamanin an der Ostküste des Brachlands. Sie leitet die schamanischen Wasserprüfungen und lehrt Initiaten, mit fließenden Geistern Zwiesprache zu halten und wiederherstellende Künste zu meistern.",al={"islen","wer ist islen wasserdeuter"}}},fx={["352084e3"]={q="Warum schickt Euch die Schwache Wassermanifestation zurück zu Islen?",a="Die elementare Manifestation dient als lebendige Stimme des reinen Wassers, geprüft und beschworen durch Eure Rituale. Indem sie Euch den Wassersplitter gewährt, vertraut sie Euch die grundlegende Wahrheit ihres Wesens an: Wasser bringt Leben, während Verderbnis es auslöscht. Sie schickt Euch zurück zu Islen Wasserdeuter, damit der Schamane Eure Verbindung mit den Geistern bestätigen, Euren Erfolg bei der Konfrontation mit der Verderbnis anerkennen und Euch das Wassertotem gewähren kann, das zu führen Ihr Euch als würdig erwiesen habt.",al={"motiv der wassermanifestation","warum den splitter zu islen bringen","warum will die wassermanifestation das"}}},fp="13,155,19.504.0,15.455.0,27.198.0,35.113.0,44.121.0,43.166.0,23.188.0"}
P.entries["quest:960"] = {n="Onu meditiert",s="An der Meistergleve im Süden der Dunkelküste fällt Onu in tiefe Trance, während eine Bedrohung wächst. Der Uralte der Lehren sinnt über das Bündnis und die Beweggründe des Schattenhammerkults und der Naga nach. Falls Ihr Eure Wahrsagephiole verliert, sprecht mit ihm, um eine neue zu erhalten.",h="An der Meistergleve im Süden der Dunkelküste fällt Onu in tiefe Trance, während eine Bedrohung wächst.",kw={"dunkelküste","der hain der uralten","die meistergleve","meditieren","onu","wahrsagephiole","wahrsageschale","schattenhammer"},ang={["class:Druid"]="Als Druide teilt Ihr eine tiefe Verbundenheit mit der Natur und den Uralten der Lehren. Wahrsagerituale spiegeln die Art wider, wie der Zirkel des Cenarius verdorbenes Land aus der Ferne erkundet.",["faction:Alliance"]="Als Reisender der Allianz ist es für Euch auf dem Weg zwischen Teldrassil und dem Eschental wichtig, die Dunkelküste vor Kultisten und Eindringlingen aus dem Wasser zu sichern.",["race:NightElf"]="Als Nachtelf verehrt Ihr Uralte der Lehren wie Onu, die das Gleichgewicht Kalimdors hüten. Ihre zeitlose Weisheit hilft Euch, Störungen in der Wildnis der Dunkelküste zu verstehen."},sec={{t="Ein Geist in tiefer Betrachtung",b="Im Hain der Uralten bewahrt Onu die Geschichte Kalimdors in seinem uralten Gedächtnis. Unheilvolle Berichte über finstere Ausgrabungen an der Meistergleve lenken sein gewaltiges Bewusstsein nach innen. Er sinnt darüber nach, was die fanatischen Kultisten des Schattenhammers und die Naga zu den versteinerten Überresten eines uralten Ungetüms führt. Während Ihr seine Erkundung durchführt, bleibt Onu erreichbar und kann eine in der Wildnis verlorene Wahrsagephiole ersetzen."},{t="Ein Blick in die Tiefe",b="Onu nutzt naturverbundene Weissagung, um die Ruinen zu beobachten, ohne sich körperlich dorthin zu wagen. Er vertraut Euch eine Wahrsagephiole an, die an der Ausgrabungsstätte eine Wahrsageschale herbeiruft und ihm ermöglicht, aus der Ferne mit Euch zu kommunizieren. Die Reise nach Süden durch die Dunkelküste ist wegen feindseliger Wildtiere und Kultistenpatrouillen gefährlich, sodass Missgeschicke geschehen können.\n\nOnus Trance ist eine aufmerksame Wache, kein ununterbrochener Schlaf. Er bietet bereitwillig eine weitere Phiole mit heiligem Wasser an, damit Ihr die Untersuchung der Meistergleve fortsetzen könnt."}},faq={{q="Warum meditiert Onu?",a="Onu meditiert über die beunruhigende Anwesenheit des Schattenhammerkults und der Naga an der Meistergleve. Er versucht, ihre Beweggründe zu ergründen und Euch bei der Untersuchung des Ortes anzuleiten.",al={"warum meditiert onu","onu trance","was macht onu"}},{q="Welchen Zweck hat diese Interaktion?",a="Diese Interaktion ist eine Absicherung für Abenteurer an der Meistergleve. Falls Ihr Eure Wahrsagephiole verliert, erhaltet Ihr im Gespräch mit Onu Ersatz, damit Ihr das Ritual abschließen könnt.",al={"wahrsagephiole verloren","neue phiole erhalten","onu ersatzquest"}},{q="Wo befindet sich Onu?",a="Onu ist im Hain der Uralten im mittleren Süden der Dunkelküste verwurzelt, gleich neben der Hauptstraße.",al={"onu standort","wo ist onu zu finden"}},{q="Was mache ich mit der Wahrsagephiole?",a="Bringt die Phiole zur Meistergleve und benutzt sie, um eine Wahrsageschale zu erschaffen. Onu kann dann durch die Schale mit Euch sprechen.",al={"wie wird die wahrsagephiole benutzt","wahrsageschale dunkelküste","wahrsagephiole zweck"}},{q="Was ist die Meistergleve?",a="Die Meistergleve ist eine uralte Ausgrabungsstätte im Süden der Dunkelküste. Dort liegt der gewaltige versteinerte Schädel eines vergessenen Wesens, durchbohrt von einer gigantischen Klinge. Kultisten und Naga haben sich dort zu unbekannten, finsteren Zwecken versammelt.",al={"was ist die meistergleve","monument im süden der dunkelküste"}},{q="Können Spieler der Horde hier mit Onu interagieren?",a="Onu ist ausschließlich mit den Nachtelfen und der Allianz verbündet. Abenteurer der Horde werden nahe dem Hain der Uralten feststellen, dass er und seine Beschützer feindselig oder wenig hilfsbereit sind.",al={"ist onu nur für die allianz","horde onu meditiert"}}},fx={["72a6a09e"]={q="Warum braucht Onu Eure Hilfe, anstatt selbst zu ermitteln?",a="Onu bleibt im Grove of the Ancients, um über den Schattenhammer und die Naga zu meditieren. Er verlässt sich auf Reisende, um den The Master's Glaive zu untersuchen und ihn durch eine Schale des Schauens zu kontaktieren.",al={"warum mich schicken","warum geht onu nicht selbst","warum braucht onu euch"}}},fp="17,243,28.421.0,18.499.0,22.187.0,40.184.0,21.97.0,39.127.0,28.238.0,41.169.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="In einem Lager in der Wildnis nutzen Lederverarbeiter gegerbte Bälge und fertigen ihren eigenen Unterschlupf. Ein guter Lagerplatz braucht ein aufgeschlagenes Zelt und ein Feuer, dessen Entzünden Kochkunstlehrer vermitteln.",h="In einem Lager in der Wildnis nutzen Lederverarbeiter gegerbte Bälge und fertigen ihren eigenen Unterschlupf.",kw={"lagerzelt","lagerfeuer","zelten","kochkunst","lederverarbeitung","unterschlupf","zelt","wildnis"},ang={["profession:Cooking"]="Ein Lagerfeuer ist das Herz eines Lagerplatzes in der Wildnis. Die Grundlagen der Kochkunst lehren Euch, eine Flamme zu entzünden und ein Lager in der Wildnis zu unterhalten."},sec={{t="Unterschlupf in der Wildnis",b="Für Handwerker, die mit Bälgen und Leder arbeiten, ist die Herstellung eines eigenen Unterschlupfs ein wesentlicher Meilenstein. Ein stabiles Lederzelt schützt Reisende auf offenem Gelände vor rauem Wetter, Wind und der Kälte der Nacht. Stadtbewohner sehen Zelte auf belebten Straßen oder Marktplätzen ungern, also müsst Ihr durch die Stadttore hinaus in die Wildnis ziehen, um ein Lager aufzuschlagen."},{t="Die Wärme eines Lagerfeuers",b="Ein aufgeschlagenes Zelt ist nur ein halbes Lager. Ein ordentliches Feuer hält Dunkelheit und kalte Winde fern und bietet Euch eine Feuerstelle in gefährlichen Landen. Da das Kochen im Freien mit dem Entfachen und Unterhalten eines Feuers beginnt, sucht Unterweisung bei Meistern der Kochkunst und Kochkunstlehrern. Sie lehren Euch, ein Lagerfeuer zu entzünden, bevor Ihr ein Lager errichtet."}},faq={{q="Wo könnt Ihr ein Lagerzelt aufschlagen?",a="Stadtbewohner sehen Zelte auf Straßen oder Stadtplätzen ungern, also bringt Euer Zelt durch die Stadttore hinaus in die Wildnis.",al={"lagerzelt verwenden","wo zelt aufschlagen","zelten in der stadt erlaubt"}},{q="Was braucht Ihr außer einem Zelt, um ein Lager aufzuschlagen?",a="Ein Zelt allein ist noch kein vollständiges Lager. Daneben muss auch ein Lagerfeuer brennen.",al={"feuer fürs lager nötig","voraussetzungen fürs lager","wie ein lager aufschlagen"}},{q="Wo lernen Abenteurer, ein Lagerfeuer zu entfachen?",a="Meister der Kochkunst und Kochkunstlehrer lehren Euch im Rahmen der Speisenzubereitung, ein Lagerfeuer zu entzünden. Sucht einen Kochkunstlehrer auf, um die Grundlagen zu erlernen.",al={"lagerfeuer erlernen","wer lehrt lagerfeuer","kochfeuer"}},{q="Wie hängt Lederverarbeitung mit der Herstellung von Lagerzelten zusammen?",a="Lederverarbeiter verbinden gegerbte Bälge und Felle mit festen Nähten zu Zeltplanen, die den rauen Bedingungen der Wildnis standhalten. Dieses Handwerk verschafft Wanderern einen verlässlichen Unterschlupf aus Tierhäuten.",al={"camping 101 leatherworking","lagerzelt aus leder","zeltherstellung lederverarbeitung"}},{q="Warum errichten Abenteurer Lager in der Wildnis?",a="Lager in der Wildnis bieten Reisenden einen sicheren Zufluchtsort zum Ausruhen und Erholen, wenn sie fern von bewohnten Außenposten, Gasthäusern und Siedlungen sind. Ein tragbarer Unterschlupf und ein warmes Feuer helfen gegen die Unbilden der Natur und die Gefahren des Geländes.",al={"warum draußen lagern","zweck des zeltens","überleben in der wildnis lager"}},{q="Warum lehnen Stadtbewohner das Aufstellen von Zelten innerhalb der Stadt ab?",a="Stadtbewohner lehnen Zelte auf öffentlichen Straßen ab, weil sie Verkehrswege versperren und für Unruhe sorgen. Siedlungen haben Gasthäuser und private Unterkünfte für Reisende, daher erwarten die Einheimischen, dass Lager in der Wildnis bleiben.",al={"regeln fürs zelten in der stadt","keine zelte in der stadt","warum kein zelt in der stadt aufschlagen"}}},fp="27,193,28.361.0,24.324.0,32.125.0,53.76.0,47.139.0,54.205.0,53.213.0,56.202.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Schmiede, die in die Wildnis aufbrechen, werden nach Kharanos geschickt, um von Tognus Flintfire zu lernen. Er lehrt sie, einen tragbaren Schleifstein herzustellen, mit dem sie Waffen im Lager scharf halten können.",h="Schmiede, die in die Wildnis aufbrechen, werden nach Kharanos geschickt, um von Tognus Flintfire zu lernen.",kw={"schmiedekunst","klingen","lager","camping 101","dun morogh","kharanos","schleifstein","tognus flintfire","waffen"},ang={["class:Rogue"]="Ein scharfer Dolch ist für Euer Handwerk unerlässlich, daher ist ein Schleifstein im Lager zwischen Aufträgen in der Wildnis willkommen.",["class:Warrior"]="Scharfe Waffen sind im Kampf wichtig, und ein Schleifstein im Lager hilft Euch, sie auf einer Expedition scharf zu halten.",["profession:Blacksmithing"]="Ihr könnt lernen, Werkzeuge für unterwegs wie den Schleifstein herzustellen, und Euer Handwerk fern der Stadtschmieden einsetzen, um Verbündeten in der Wildnis zu helfen.",["race:Dwarf"]="Als Zwerg findet Ihr Kharanos in den verschneiten Ausläufern der Berge von Dun Morogh. Seine Schmiede halten kalten Stahl für die Reise scharf."},sec={{t="Waffenpflege auf Reisen",b="Ihr werdet nach Kharanos geschickt, um zu lernen, wie ein Schmied fern einer Stadtschmiede helfen kann. Dort verwandeln geschickte Hände rohes Metall in Werkzeuge fürs Lager. Eine scharf gehaltene Klinge ist für den langen Weg bereit."},{t="Der Meister von Kharanos",b="In Kharanos lehrt Tognus Flintfire fähige Schmiede, einen Schleifstein herzustellen. Stellt einen neben Eurem Lagerplatz auf, damit Krieger und Schurken vor dem nächsten Marsch Scharten aus ihren Waffen schleifen und stumpfe Schneiden schärfen können."}},faq={{q="Wer ist Tognus Flintfire?",a="Tognus Flintfire lehrt Schmiedekunst in Kharanos, in Dun Morogh. Er bildet Schmiede aus, die ihr handwerkliches Können bewiesen haben, und lehrt sie, Ausrüstung für Lagerplätze herzustellen.",al={"wer ist tognus flintfire","wo ist tognus","tognus flintfire standort"}},{q="Was ist ein Schleifstein?",a="Ein Schleifstein ist ein tragbares Werkzeug, das von Schmieden hergestellt wird. Im Lager bietet er Kriegern, Schurken und anderen Waffenträgern eine Möglichkeit, ihre Klingen unterwegs zu schärfen.",al={"was bewirkt der schleifstein","schleifstein lager","schleifstein zweck"}},{q="Warum ist der Schleifstein für Krieger und Schurken wichtig?",a="Krieger und Schurken sind im Kampf auf scharfe Waffen angewiesen. Mit einem Schleifstein können sie ihre Klingen, Äxte und Dolche pflegen, während sie fern der Stadtschmieden unterwegs sind.",al={"wer braucht einen schleifstein","krieger schleifstein","schurken schleifstein"}},{q="Wo liegt Kharanos?",a="Kharanos liegt südwestlich von Eisenschmiede in den verschneiten Gipfeln von Dun Morogh. Reisende, Bergleute und Handwerker nutzen die Siedlung als Rastplatz, wenn sie die Gebirgspässe überqueren.",al={"wo liegt kharanos","kharanos lage","kharanos finden"}},{q="Was ist erforderlich, um die Herstellung dieses Lagergegenstands zu erlernen?",a="Beweist grundlegendes Geschick am Amboss, und Tognus Flintfire lehrt Euch, Ausrüstung für Lagerplätze herzustellen. Dann könnt Ihr lernen, den tragbaren Schleifstein zu schmieden.",al={"camping 101 blacksmithing voraussetzung","wann ist schleifstein erlernbar","schmiedekunst lagerausbildung"}},{q="Warum stellen Schmiede Lagergegenstände her?",a="Schmiede fertigen Lagerwerkzeuge, um Abenteurergruppen fern der Ortschaften zu unterstützen. Mit einem tragbaren Schleifstein können Gefährten ihre Waffen unter freiem Himmel pflegen, ohne zu einer Stadtschmiede zurückzukehren.",al={"warum lagergegenstände herstellen","schmiedekunst lagergegenstände","nutzen der schmiedekunst in der wildnis"}}},fp="26,170,35.181.0,22.211.0,24.162.0,27.161.0,59.157.0,18.177.0,44.137.0,39.202.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="In Eisenschmiede zeigt Vosur Brakthel Alchemisten, wie sie sich auf Reisen vorbereiten. Mit einem Manabrunnen können sie Zauberkundigen und Heilern unterwegs einen Ort zur Erholung bieten.",h="In Eisenschmiede zeigt Vosur Brakthel Alchemisten, wie sie sich auf Reisen vorbereiten.",kw={"alchemie","lagerfeuer","lagern","camping 101: alchemy","eisenschmiede","manabrunnen","vosur brakthel"},ang={["faction:Alliance"]="In Eisenschmiede können Alchemisten bei Vosur Brakthel Rat suchen, um erholsame Mixturen für ihre Reisen zuzubereiten.",["profession:Cooking"]="Ein Lagerplatz braucht ein Lagerfeuer, und Kochkunstlehrer in allen Reichen vermitteln die praktische Fertigkeit, eines zu entfachen."},sec={{t="Brauen für die Reise",b="Vosur Brakthel lehrt Alchemisten in Eisenschmiede, ihr Handwerk auch jenseits der Stadt auszuüben. Phiolen in einem ruhigen Labor zu brauen, ist nur ein Teil der Arbeit. In Azeroths Wildnis können Alchemisten mit ihrem Wissen einen Manabrunnen für ein Lager erschaffen, der Gefährten hilft, die Reise durchzustehen."},{t="Lager in der Wildnis",b="Ein Manabrunnen kann Heiler und Zauberkundige erfrischen, doch er gehört in ein Lager in der Wildnis, nicht auf eine Straße in Eisenschmiede. Stadtbewohner sehen es ungern, wenn innerhalb ihrer Mauern Zelte aufgeschlagen werden. Ein richtiges Lager braucht auch ein Feuer, also sucht Rat bei einem Kochkunstlehrer, bevor Ihr in die Wildnis aufbrecht."}},faq={{q="Wer ist Vosur Brakthel?",a="Vosur Brakthel ist ein Alchemielehrer in Eisenschmiede. Er lehrt Alchemisten, mit ihrem Handwerk einen Manabrunnen für Gefährten im Feld zu erschaffen.",al={"wer lehrt camping 101: alchemy","vosur brakthels aufgabe","wer ist vosur brakthel"}},{q="Was ist ein Manabrunnen?",a="Ein Manabrunnen ist eine alchemistische Einrichtung für ein Lager in der Wildnis. Er hilft Zauberkundigen und Heilern, sich unterwegs zu erholen.",al={"was bewirkt ein manabrunnen","zweck des manabrunnens","warum einen manabrunnen erschaffen"}},{q="Könnt Ihr innerhalb von Eisenschmiede ein Lager aufschlagen?",a="Nein. Stadtbewohner sehen Lager in Eisenschmiedes Straßen ungern, also bringt Euren Manabrunnen aus der Stadt hinaus in die Wildnis.",al={"lagern in eisenschmiede erlaubt","lagern in der stadt","wo manabrunnen aufstellen"}},{q="Was braucht Ihr noch, um ein Lager aufzuschlagen?",a="Ein Lager braucht auch ein Lagerfeuer. Wenn Ihr nicht wisst, wie Ihr eines entfacht, sucht vor dem Aufbruch einen Kochkunstlehrer auf.",al={"lagerfeuer als voraussetzung","kochkunst zum lagern nötig","wie ein lager aufschlagen"}},{q="Wann kann ein Alchemist lernen, einen Manabrunnen zu erschaffen?",a="Vosur Brakthel unterrichtet Alchemisten, die den Beruf ergriffen und bereits etwas Fertigkeit darin bewiesen haben. Mit dieser Erfahrung können sie lernen, einen Manabrunnen zu erschaffen.",al={"wann manabrunnen erlernen","voraussetzungen für manabrunnen","voraussetzungen für camping 101"}},{q="Wer profitiert am meisten von einem Manabrunnen im Lager?",a="Zauberkundige und Heiler profitieren am meisten von einem Manabrunnen. Er hilft ihnen, ihr Mana aufzufüllen, wenn sie fern von städtischen Gasthäusern und Ruhesteinen unterwegs sind.",al={"wer profitiert vom manabrunnen","klassen für manabrunnen","wer nutzt manabrunnen"}}},fp="20,167,20.280.0,20.267.0,22.140.0,20.117.0,39.118.0,37.108.0,48.152.0,43.146.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Fern der bewachten Straßen lernen Bergleute, einen Lodestein für ein Lager in der Wildnis herzustellen. Dazu braucht es Wissen über Gestein und die Feuerkunst, die das Leben im Freien erfordert.",h="Fern der bewachten Straßen lernen Bergleute, einen Lodestein für ein Lager in der Wildnis herzustellen.",kw={"lagerfeuer","camping","camping 101: mining","lagerplatz","kochkunst","magnetstein","bergbau","wildnis"},ang={["profession:Cooking"]="Als Koch lernt Ihr bei Kochlehrern die Feuerkunst, die ein Lager braucht.",["profession:Mining"]="Als Bergmann lernt Ihr, Erde und Erz zu einem Lodestein zu formen, der einem Lager in der Wildnis Halt gibt."},sec={{t="Feldfertigkeiten für Bergleute",b="Fern der bewachten Straßen muss ein Bergmann sich auf sein Wissen über das Leben im Freien verlassen. Mineralienkenntnis ermöglicht es Euch, einen Lodestein zu formen, der einem Lager in der Wildnis Halt gibt."},{t="Regeln der Wildnis",b="Ein Lager gehört außerhalb der Stadtgrenzen, wo Reisende ihre Unterkünfte aufschlagen können, ohne die Bewohner zu stören. Wählt einen Platz in der offenen Wildnis. Ein Lager braucht auch ein Feuer, das die nächtliche Kälte vertreibt. Zu lernen, wie man eines entfacht, gehört ebenso zum Wissen über das Leben im Freien wie die Arbeit mit Gestein."}},faq={{q="Wozu wird ein Magnetstein verwendet?",a="Ein Lodestein gibt einem Lager in der Wildnis Halt.",al={"verwendungszweck des magnetsteins","wozu dient ein magnetstein","warum magnetstein herstellen"}},{q="Kann ich in einer Ortschaft oder Stadt ein Lager aufschlagen?",a="Die Stadtbewohner und die Behörden missbilligen Zelte auf öffentlichen Plätzen und Straßen. Schlagt Euer Lager außerhalb der Stadtgrenzen auf.",al={"kann ich in einer stadt zelten","zelten in der stadt","lager innerhalb einer siedlung"}},{q="Was ist erforderlich, bevor man ein Lager aufschlägt?",a="Zu einem Lager gehört ein warmes, nahes Feuer.",al={"brauche ich ein lagerfeuer","wie man ein lager aufschlaegt","voraussetzungen fuer ein lager"}},{q="Wo lerne ich, wie man ein Lagerfeuer macht?",a="Kochlehrer und Köche überall in Azeroth vermitteln die grundlegenden Fertigkeiten zum Entfachen eines Kochfeuers.",al={"wo lagerfeuer lernen","wer lehrt lagerfeuer","lagerfeuer-lehrer"}},{q="Wie hängt Bergbau mit der Herstellung eines Magnetsteins zusammen?",a="Beim Bergbau lernt Ihr, die Mineralien und das Gestein zu bearbeiten, die Ihr für einen Lodestein benötigt.",al={"warum bergleute zelten","bergbau verbindung zu magnetstein","magnetstein herstellen"}},{q="Wohin sollte ich gehen, um mein neues Lager zu testen?",a="Geht durch die Stadttore hinaus in die offene Wildnis, wo Ihr fern der Stadtbewohner Platz zum Lagern findet.",al={"wo lager testen","magnetstein testen","im freien lagern"}}},fp="19,163,21.153.0,17.270.0,29.49.0,40.120.0,42.40.0,41.98.0,48.77.0,38.103.0"}
P.entries["quest:96047"] = {n="Camping 101: First Aid",s="In Kharanos lehrt Euch Thamner Pol, Verbandtaschen für Lager in Dun Morogh zusammenzustellen. Mit diesen Vorräten können Reisende im Feld am Leben bleiben.",h="In Kharanos lehrt Euch Thamner Pol, Verbandtaschen für Lager in Dun Morogh zusammenzustellen.",kw={"verbände","grundlagen des zeltens","dun morogh","erste hilfe","verbandtasche","kharanos","überleben","thamner pol"},ang={["faction:Alliance"]="Als Rekrut der Allianz, der im eisigen Herzen von Khaz Modan ausgebildet wird, lernt Ihr, dass Eigenständigkeit und Feldmedizin für Militärverbände und Forschergruppen wichtig sind.",["race:Dwarf"]="Als Zwerg verlasst Ihr Euch auf robuste, praktische Ausrüstung, während Ihr auf den hohen, verschneiten Pässen von Dun Morogh patrouilliert. Eine Verbandtasche fürs Lager ist ein nützlicher Teil Eurer Vorräte.",["race:Gnome"]="Als geflüchteter oder umherziehender Gnom in Kharanos könnt Ihr Euch auf Feldmedizin verlassen, während Ihr außerhalb der verlorenen Hallen von Gnomeregan überlebt."},sec={{t="Wundversorgung in der Wildnis",b="Ihr könnt Eure grundlegenden Fertigkeiten im Verbinden von Wunden erweitern, indem Ihr lernt, Vorräte für einen Rastplatz zusammenzustellen. Thamner Pol zeigt Euch, wie aus medizinischen Grundmaterialien vollständige Taschen werden, einsatzbereit im Lager, wenn Reisende fernab jeder Zuflucht Versorgung benötigen."},{t="Die Lehren von Kharanos",b="Thamner Pol lehrt Euch praktische Methoden, um Expeditionslager mit Notfallvorräten auszustatten. Mit einer ordentlichen Verbandtasche kann eine Gruppe gemeinsam am Feuer Wunden verbinden und neue Kraft schöpfen, bevor sie wieder in die Kälte aufbricht."}},faq={{q="Welchen Zweck hat diese Aufgabe?",a="Frisch ausgebildete Sanitäter suchen Thamner Pol in Kharanos auf, um zu lernen, wie man Verbandtaschen für die Lagerplätze von Abenteurern herstellt.",al={"warum grundlagen des zeltens erste hilfe","was bewirkt diese quest","grundlagen des zeltens ziel"}},{q="Wer ist Thamner Pol?",a="Thamner Pol bildet in Kharanos in Dun Morogh Leute darin aus, Ausrüstung für Lager in der Wildnis herzustellen.",al={"wer ist thamner pol","thamner pol standort","wo ist thamner pol"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung findet in Kharanos statt, der wichtigsten Siedlung im Zentrum von Dun Morogh, südlich von Eisenschmiede.",al={"wohin gehen","grundlagen des zeltens standort","kharanos erste hilfe"}},{q="Warum ist eine Verbandtasche im Lager wichtig?",a="Eine Verbandtasche im Lager versorgt verletzte Reisende mit Vorräten, um ihre Wunden zu verbinden und sich zwischen Kämpfen sicher zu erholen.",al={"was bewirkt eine verbandtasche","warum eine verbandtasche herstellen","nutzen von erster hilfe im lager"}},{q="Braucht Ihr medizinische Vorkenntnisse, bevor Ihr Thamner Pol aufsucht?",a="Ja. Abenteurer sollten die Grundlagen der Ersten Hilfe kennen und etwas Geschick beweisen, bevor Thamner Pol ihnen fortgeschrittene Rezepte für die Lagerausstattung beibringt.",al={"voraussetzungen für grundlagen des zeltens","erforderliche fertigkeit in erster hilfe","erste hilfe als voraussetzung"}},{q="Steht diese Tätigkeit jedem Abenteurer offen?",a="Jeder Abenteurer kann Erste Hilfe erlernen, unabhängig von seiner Berufung, was sie zu einer nützlichen Fertigkeit für Reisende in Dun Morogh macht.",al={"kann das jeder machen","klassenvoraussetzungen","wer kann erste hilfe fürs lager erlernen"}}},fp="22,147,26.230.0,23.212.0,33.112.0,19.85.0,36.100.0,38.110.0,62.130.0,39.113.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Ihr bereitet Euch mit einem Fischglas und einem Lagerfeuer auf das Angeln in der Wildnis vor. Lernt, wo Ihr Euer Lager aufschlagen könnt und was einen Rastplatz behaglich macht.",h="Ihr bereitet Euch mit einem Fischglas und einem Lagerfeuer auf das Angeln in der Wildnis vor.",kw={"lager","lagerfeuer","lagern","kochkunst","fischglas","angeln","wildnis"},ang={["profession:Cooking"]="Lernt die Grundlagen der Kochkunst, bevor Ihr Euer Lager aufschlagt. Kochkunstlehrer bringen Reisenden bei, das Lagerfeuer zu entfachen, das ein Lagerplatz braucht."},sec={{t="Benimmregeln in der Wildnis",b="Reisen durch Azeroth erfordern ein wenig Wissen über die Wildnis. Wenn Ihr einen Rastplatz braucht, haltet Euer Zelt und Eure Ausrüstung außerhalb der Stadtgrenzen. Stadtbewohner und Wachen sehen es ungern, wenn Reisende ihre Habseligkeiten in Siedlungen ausbreiten. Bringt Eure Vorräte stattdessen in die offene Wildnis."},{t="Die Annehmlichkeiten des Lagers",b="Ein ordentlicher Lagerplatz braucht ein paar Annehmlichkeiten. Beginnt mit einem wärmenden Lagerfeuer; ein Kochkunstlehrer kann Euch beibringen, wie Ihr eines entfacht. Sobald das Feuer bereit ist, stellt ein handgefertigtes Fischglas auf. Dann ist Euer Rastplatz für einen Angler geeignet."}},faq={{q="Was lernt Ihr in Camping 101: Fishing?",a="Ihr lernt, ein Fischglas herzustellen und einen Rastplatz zum Angeln in der Wildnis vorzubereiten. Schlagt Euer Lager abseits von Siedlungen auf.",al={"was lehrt diese quest","fischglas herstellen","lagern angeln belohnung"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Schlagt Euer Lager in der Wildnis außerhalb der Stadtgrenzen auf. Stadtbewohner nehmen Anstoß daran, wenn Reisende ihre Ausrüstung auf öffentlichen Durchgangswegen ausbreiten.",al={"wo lager aufschlagen","lagern in der stadt erlaubt","regeln für lagerplätze"}},{q="Was braucht Ihr, bevor Ihr ein Lager aufschlagt?",a="Haltet ein Lagerfeuer bereit, das Euch wärmt. Ein Lagerplatz braucht eines, um vollständig zu sein.",al={"wie lager errichten","ist ein lagerfeuer nötig","voraussetzungen fürs lager"}},{q="Wie lernt Ihr, ein Lagerfeuer zu entfachen?",a="Kochkunstlehrer bringen Euch bei, wie Ihr ein Lagerfeuer entfacht. Wenn Ihr die Grundlagen der Kochkunst noch nicht gelernt habt, sucht einen Koch auf, der Euch unterweist.",al={"wie lagerfeuer entfachen","wo lagerfeuer lernen","wer lehrt feuermachen"}},{q="Wozu dient das Fischglas?",a="Das Fischglas schmückt einen Lagerplatz im Freien und passt zu einem Angler, der am Wasser rastet.",al={"wozu dient das fischglas","fischglas im lager verwenden","fischglas hintergrund"}},{q="Warum erhalten Abenteurer Unterricht im Lagern?",a="Lehrmeister der Wildnis vermitteln praktische Fertigkeiten für das Grenzland, darunter das Feuermachen und das Achten von Siedlungsgrenzen, bevor Ihr in die Wildnis aufbrecht.",al={"wer bietet camping 101 an","warum unterricht im lagern","überlebensratgeber fürs lagern"}}},fp="20,140,20.280.0,20.210.0,44.111.0,28.126.0,40.70.0,37.126.0,37.85.0,46.142.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="In Eisenschmiede können Kräuterkundige lernen, Räucherkerzen für das Lagerleben herzustellen. Reyna Stonebranch lehrt das Handwerk Sammlern, die bereit sind, wilde Kräuter praktisch zu nutzen.",h="In Eisenschmiede können Kräuterkundige lernen, Räucherkerzen für das Lagerleben herzustellen.",kw={"lager","camping 101","kräuterkunde","kräuter","räucherkerze","eisenschmiede","reyna stonebranch"},ang={["faction:Alliance"]="Als Kräuterkundiger der Allianz könnt Ihr Reyna Stonebranch in Eisenschmiede aufsuchen und Unterricht in der Feldkunde erhalten.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr aus gesammelten wilden Kräutern Räucherkerzen herstellen, um Zauberwirkern im Lager zu helfen.",["race:Dwarf"]="Als Zwerg findet Ihr die Kräuterkundelehrerin Reyna Stonebranch in Eisenschmiede, wo sie lehrt, Räucherkerzen herzustellen."},sec={{t="Praktische Feldbotanik",b="Das Sammeln wilder Kräuter kann einem Lager ebenso dienen wie einer Reisegruppe. Mit Geschick machen Kräuterkundige aus ihrer Ernte nützliche Hilfsmittel für das Leben im Freien."},{t="Aromastoffe für das Lagerfeuer",b="In Eisenschmiede können erfahrene Kräuterkundige bei Reyna Stonebranch Unterricht suchen. Sobald sie ihr Können bewiesen haben, lehrt sie sie, eine Räucherkerze herzustellen. Ihr beruhigender Duft hebt im Lager die Stimmung und schenkt Zauberwirkern und Heilern auf langen Expeditionen Ruhe."}},faq={{q="Was ist Camping 101: Herbalism?",a="Kräuterkundige lernen, wilde Pflanzen im Lager praktisch zu nutzen. Reyna Stonebranch lehrt das Handwerk in Eisenschmiede.",al={"was ist camping 101 herbalism","kräuterkunde camping quest","kräuterkunde lager guide"}},{q="Wer ist Reyna Stonebranch?",a="Reyna Stonebranch lehrt erfahrene Kräuterkundige in Eisenschmiede, wie sie Räucherkerzen für das Lager herstellen.",al={"wer lehrt räucherkerze","wo ist reyna stonebranch","reyna stonebranch aufenthaltsort"}},{q="Was bewirkt eine Räucherkerze?",a="Eine Räucherkerze erfüllt das Lager mit beruhigendem Duft und hebt die Stimmung der Reisenden.",al={"was macht eine räucherkerze","räucherkerze camping","räucherkerze zweck"}},{q="Warum sind Räucherkerzen für Zauberwirker nützlich?",a="Ihr beruhigender Duft hilft Zauberwirkern und Heilern, auf langen Expeditionen zur Ruhe zu kommen.",al={"wer profitiert von räucherkerze","ist die räucherkerze für zauberwirker"}},{q="Wohin müssen Kräuterkundige für diese Unterweisung reisen?",a="Kräuterkundige reisen nach Eisenschmiede, um Reyna Stonebranch aufzusuchen, nachdem sie ihr Können beim Kräutersammeln bewiesen haben.",al={"wohin für camping kräuterkunde","welche stadt für camping 101 herbalism"}},{q="Was ist erforderlich, bevor man das Herstellen der Kerze erlernen kann?",a="Kräuterkundige müssen ihr Können beim Kräutersammeln beweisen, bevor Reyna Stonebranch ihnen beibringt, Räucherkerzen herzustellen.",al={"wann kann man räucherkerze lernen","kräuterkunde camping voraussetzung"}}},fp="22,167,22.148.0,24.263.0,31.111.0,25.98.0,31.85.0,47.94.0,50.102.0,53.115.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="In Eisenschmiede lernen geübte Kürschner, aus Tierhäuten einen Lagerstuhl herzustellen. Balthus Stoneflayer lehrt sie das Handwerk, nachdem sie ihr Können bewiesen haben.",h="In Eisenschmiede lernen geübte Kürschner, aus Tierhäuten einen Lagerstuhl herzustellen.",kw={"balthus stoneflayer","lagerstuhl","camping","camping 101: skinning","bälge","eisenschmiede","kürschnerei"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Beute in der Wildnis häuten und einen Lagerstuhl herstellen, um Euch zwischen langen Fährtensuchen auszuruhen.",["faction:Alliance"]="Euer Weg zur Herstellung eines Lagerstuhls führt nach Eisenschmiede, der Bergstadt der Zwerge und Hauptstadt der Allianz.",["race:Dwarf"]="Als Zwerg könnt Ihr Balthus Stoneflayer in Eisenschmiede finden und lernen, wie geübte Kürschner aus Häuten Annehmlichkeiten fürs Lager herstellen."},sec={{t="Die Ausbeute der Wildnis",b="Das Häuten erlegter Wildtiere liefert Rüstungsschmieden und Handwerkern Leder für ihre Arbeit. Häute von Katzen, Bären und anderen Wildtieren sind auch unterwegs von Nutzen. Ihr werdet ausgesandt, diese Materialien in etwas Nützliches fürs Lager zu verwandeln, statt sie zu verkaufen."},{t="Der Handwerker von Eisenschmiede",b="Balthus Stoneflayer lehrt Kürschner in Eisenschmiede, aus vorbereiteten Pelzen einen Lagerstuhl herzustellen. Zuerst müsst Ihr ihm zeigen, dass Ihr Wildtiere häuten könnt. Erst dann wird er seine Herstellungsmethoden mit Euch teilen."},{t="Rast und Bereitschaft",b="Ein Lagerstuhl bietet Euch auf Reisen einen Platz, um am Feuer zu sitzen und auszuspannen. Ruht Euch dort aus, und Ihr könnt der nächsten Gefahr mit wachen Sinnen und neuer Kraft begegnen."}},faq={{q="Was ist Camping 101: Skinning?",a="Geübte Kürschner reisen nach Eisenschmiede, um zu lernen, wie man aus Tierhäuten einen Lagerstuhl herstellt.",al={"was ist camping 101 skinning","quest-zweck","camping 101 skinning quest"}},{q="Wer bringt Euch bei, den Campinggegenstand herzustellen?",a="Balthus Stoneflayer lehrt Euch in Eisenschmiede, einen Lagerstuhl herzustellen. Zeigt ihm zuerst, dass Ihr Wildtiere häuten könnt.",al={"mit wem sprechen","wer lehrt lagerstuhl","wer ist balthus stoneflayer"}},{q="Wohin müsst Ihr reisen, um diese Quest abzuschließen?",a="Begebt Euch nach Eisenschmiede, der Zwergenhauptstadt in den verschneiten Gipfeln von Dun Morogh. Balthus Stoneflayer unterrichtet dort Kürschner, die ihr Können beweisen.",al={"wohin gehen","standort von balthus","lehrer in eisenschmiede"}},{q="Welchen Gegenstand lernen Kürschner für ihr Lager herzustellen?",a="Ihr lernt, aus Tierhäuten einen Lagerstuhl herzustellen, der Euch unterwegs zwischen den Gefahren einen Platz zum Ausruhen bietet.",al={"was stellt man her","zweck des lagerstuhls","kürschner-lagerhandwerk"}},{q="Warum ist die Herstellung eines Lagerstuhls für einen Abenteurer nützlich?",a="Ein Lagerstuhl bietet Euch auf langen Wanderungen durch die Wildnis einen Platz zum Ausruhen, um Eure Konzentration wiederzufinden, bevor Euch die Gefahr ereilt.",al={"warum einen stuhl herstellen","was bringt lagerstuhl","vorteil von lagerstuhl"}},{q="Welche Fertigkeit ist erforderlich, bevor Balthus Euch unterrichtet?",a="Balthus Stoneflayer unterrichtet Euch, nachdem Ihr Euer Können beim Häuten von Wildtieren bewiesen habt.",al={"anforderungen","wann kann ich lernen","benötigte fertigkeit"}}},fp="21,144,20.234.0,24.194.0,18.173.0,30.85.0,42.103.0,47.136.0,52.106.0,54.111.0,59.78.0"}
P.entries["quest:96057"] = {n="Camping 101: Tailoring",s="Ein Schneider kann bei Uthrar Threx in Eisenschmiede lernen, wie man ein Rallying Banner für ein Lager herstellt. Das Banner soll die Moral stärken, und ein Lagerfeuer wird benötigt, um ein Lager aufzuschlagen.",h="Ein Schneider kann bei Uthrar Threx in Eisenschmiede lernen, wie man ein Rallying Banner für ein Lager...",kw={"lager","lagerfeuer","camping 101","eisenschmiede","moral","rallying banner","schneiderei","uthrar threx"},ang={["profession:Cooking"]="Ein Koch kann Euch beibringen, das Lagerfeuer zu entzünden, das Ihr braucht, bevor Ihr Euer Lager aufschlagt.",["profession:Tailoring"]="Als Schneider könnt Ihr lernen, ein Rallying Banner für Euer Lager herzustellen, sobald Ihr Euer Können in Eurem Handwerk bewiesen habt."},sec={{t="Ein Banner fürs Lager",b="Ein Lehrer in Eisenschmiede kann Euch zeigen, wie Ihr ein Banner für Euer Lager herstellt, sobald Ihr Euer Können in der Schneiderei bewiesen habt. Das Banner heißt Rallying Banner. Es kann Euch helfen, voller Tatkraft zu bleiben, und Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt."}},faq={{q="Wer lehrt Schneiderei fürs Lagerleben?",a="Uthrar Threx in Eisenschmiede kann Euch beibringen, einen Gegenstand fürs Lagerleben herzustellen, sobald Ihr Euer Können in der Schneiderei bewiesen habt.",al={"wer lehrt das","schneidereilehrer","uthrar threx"}},{q="Was kann ich mit Schneiderei herstellen?",a="Ihr könnt lernen, ein Rallying Banner für Euer Lager herzustellen.",al={"lagergegenstand aus schneiderei","welches banner","banner herstellen"}},{q="Was bewirkt das Rallying Banner?",a="Ein ermutigendes Banner kann Euch helfen, voller Tatkraft zu bleiben, und Moral ist wichtig für den Erfolg auf dem Schlachtfeld.",al={"zweck des banners","warum ein banner","rally banner"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Ein Koch kann Euch beibringen, eines zu entzünden.",al={"lagerfeuer benötigt","wie lager aufschlagen","voraussetzungen fürs lager"}}},fp="22,172,17.238.0,34.109.0,31.55.0,33.105.0,38.77.0"}
P.entries["quest:96058"] = {n="Camping 101: Engineering",s="Ein Ingenieur in Kharanos kann lernen, einen Reagent Bot für ein Lager herzustellen. Der Bot hilft, Euch mit Materialien für Zauber zu versorgen.",h="Ein Ingenieur in Kharanos kann lernen, einen Reagent Bot für ein Lager herzustellen.",kw={"bronk guzzlegear","lager","lagerfeuer","camping 101","ingenieurskunst","kharanos","reagent bot","zaubermaterialien"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, das für ein Lager benötigte Lagerfeuer zu entfachen.",["profession:Engineering"]="Als Ingenieur könnt Ihr bei Bronk Guzzlegear lernen, einen Reagent Bot für Euer Lager herzustellen."},sec={{t="Vorräte für ein Lager",b="Ein Ingenieur kann bei Bronk Guzzlegear in Kharanos lernen, wie man einen Reagent Bot herstellt. Ihr müsst Euer Können in der Ingenieurskunst beweisen, bevor er Euch unterrichtet. Der Bot hilft, Euch und Eure Verbündeten mit Materialien zu versorgen, die Ihr für Zauber benötigt."},{t="Bereit für die Wildnis",b="Ihr könnt jetzt einen Reagent Bot herstellen. Um ihn zu testen, verlasst den Ort und begebt Euch in die Wildnis, wo Ihr ein Lager aufschlagen könnt. Bringt auch ein Lagerfeuer mit; Köche können Euch beibringen, wie man eines entfacht."}},faq={{q="Wer bringt mir bei, einen Reagent Bot herzustellen?",a="Bronk Guzzlegear in Kharanos kann Euch beibringen, einen Reagent Bot herzustellen, sobald Ihr Euer Können in der Ingenieurskunst beweist.",al={"bronk bot unterricht","wer ist bronk guzzlegear","reagent bot lehrer"}},{q="Was macht ein Reagent Bot?",a="Ein Reagent Bot hilft, Euch und Eure Verbündeten mit Materialien zu versorgen, die für Zauber benötigt werden.",al={"wozu dient reagent bot","bot zaubermaterialien","lager bot"}},{q="Was brauche ich, bevor ich das lernen kann?",a="Ihr müsst Euer Können in der Ingenieurskunst beweisen, bevor Bronk Guzzlegear Euch beibringt, einen Reagent Bot herzustellen.",al={"können in der ingenieurskunst","wie reagent bot erlernen","camping 101 ingenieurskunst"}},{q="Wo kann ich den Reagent Bot ausprobieren?",a="Ihr könnt den Reagent Bot in der Wildnis testen, da die meisten Leute keine Lager mitten im Ort haben wollen.",al={"wo bot testen","lagerplatz","reagent bot wildnis"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Ein Lager braucht ein Lagerfeuer, und die meisten Köche können Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","wie lagerfeuer entfachen","kochen im lager"}}},fp="24,127,17.233.0,19.175.1,37.107.0,27.87.0,39.114.0,36.111.0,21.71.0"}
P.entries["quest:96059"] = {n="Camping 101: Enchanting",s="Ein Verzauberer in Eisenschmiede kann nach einem Fertigkeitsnachweis lernen, eine Verzauberte Laute fürs Lager herzustellen. Ihre Magie sorgt bei Rastpausen unterwegs für Unterhaltung.",h="Ein Verzauberer in Eisenschmiede kann nach einem Fertigkeitsnachweis lernen, eine Verzauberte Laute fürs...",kw={"lagergegenstand","camping für anfänger","verzauberte laute","verzauberkunst","eisenschmiede","thonys pillarstone"},ang={["profession:Engineering"]="Als Verzauberer könnt Ihr von Thonys Pillarstone lernen, eine Verzauberte Laute fürs Lager herzustellen, sobald Ihr Euer Können bewiesen habt."},sec={{t="Eine Laute fürs Lager",b="Eure nächste Lektion handelt von einer Melodie für unterwegs. In Eisenschmiede kann Thonys Pillarstone Euch beibringen, eine Verzauberte Laute herzustellen, sobald Ihr Euer Können in der Verzauberkunst bewiesen habt. Die Magie bietet Euch Unterhaltung in Ruhepausen, bevor Ihr Euch wieder auf den Weg macht."}},faq={{q="Wer kann mir beibringen, eine Verzauberte Laute herzustellen?",a="Thonys Pillarstone in Eisenschmiede kann Euch beibringen, eine Verzauberte Laute herzustellen, nachdem Ihr Euer Können in der Verzauberkunst bewiesen habt.",al={"thonys pillarstone","wer lehrt verzauberkunst-lagergegenstand"}},{q="Wozu dient die Verzauberte Laute?",a="Die Verzauberte Laute ist ein Lagergegenstand, der in Ruhepausen für Unterhaltung sorgen soll.",al={"zweck der laute","verzauberte laute lager"}},{q="Warum brauche ich Fertigkeit in der Verzauberkunst?",a="Ihr könnt lernen, den Lagergegenstand herzustellen, sobald Ihr Euer Können in der Verzauberkunst bewiesen habt.",al={"können in der verzauberkunst","laute herstellen lernen"}}},fp="23,149,15.267.0,43.114.0,31.84.0,31.86.0"}
P.entries["quest:96063"] = {n="Gaseous Gold",s="Sleebo Fizzlespout möchte Sumpfgas aus den Teichen südwestlich von hier. Er hofft, damit einen neuen Motor anzutreiben.",h="Sleebo Fizzlespout möchte Sumpfgas aus den Teichen südwestlich von hier.",kw={"motor","gasphiolen","gasförmiges gold","industrie","sumpfgas","wissenschaft","sleebo fizzlespout","öffnungen"},sec={{t="Ein neuer Treibstoff",b="Sleebo Fizzlespout sieht Gas aus Öffnungen nahe dem Wasser in den sumpfigen Teichen im Südwesten aufsteigen. Er entwickelt einen Motor, der mit dem Gas läuft, und bittet Euch, Sumpfgasphiolen für ihn zu sammeln. Diese Arbeit könnte helfen, den Treibstoff in Wissenschaft und Industrie einzusetzen."}},faq={{q="Wer bittet um Sumpfgas?",a="Sleebo Fizzlespout bittet Euch, Sumpfgasphiolen für ihn zu sammeln.",al={"wer möchte gas","sleebo fizzlespout"}},{q="Warum möchte Sleebo das Gas?",a="Sleebo entwickelt eine neue Art von Motor, der mit Sumpfgas läuft.",al={"wofür ist das gas","gasmotor"}},{q="Woher kommt das Sumpfgas?",a="Das Gas steigt aus Öffnungen nahe dem Wasser in sumpfigen Teichen südwestlich von Sleebo auf.",al={"wo ist das gas","gasöffnungen"}},{q="Wofür wird Sumpfgas verwendet?",a="Sleebo hofft, Sumpfgas als Treibstoff für seinen neuen Motor zu verwenden.",al={"verwendung von sumpfgas","gastreibstoff"}}},fp="12,109,10.260.0,28.62.0,29.65.0,35.76.0,27.57.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="Raan heißt neue Wanderer willkommen und zeigt ihnen, wie sie in der Wildnis bestehen. Ruht Euch an seinem einfachen Lagerfeuer aus, um Boosted Rest zu erhalten, und besucht dann nahegelegene Berufslehrer, um praktische Berufe zu erlernen.",h="Raan heißt neue Wanderer willkommen und zeigt ihnen, wie sie in der Wildnis bestehen.",kw={"einfaches lagerfeuer","boosted rest","lagereinrichtung","lagerfeuer","raan","the great outdoors","beruf","überleben in der wildnis"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Lagerfertigkeiten für Fährtenleser und Waldläufer, die unter freiem Himmel leben, unerlässlich sind.",["profession:Cooking"]="Als Koch wisst Ihr, dass ein einfaches Lagerfeuer einer Reisegruppe hilft, in der Wildnis zu ruhen und sich zu erholen."},sec={{t="Lehren der Wildnis",b="Raan hat die Wildnis bereist und lehrt andere, wie sie jenseits der Siedlungsmauern überleben. Ehrgeiz und Stahl allein bringen Euch nicht durch raues Wetter; praktische Lagerfertigkeiten sind entscheidend. Er heißt jene willkommen, die Glück und Ruhm suchen, und bietet allen Anleitung, die bereit sind zu lernen."},{t="Die Wärme des Herdfeuers",b="Raan bittet Euch, Euch an sein einfaches Lagerfeuer zu setzen und zu ruhen, bis Ihr Boosted Rest erhaltet. In Azeroths Wildnis kann das Wissen, wann man innehält, ein Lager aufschlägt und sich erholt, den Unterschied zwischen Leben und Tod bedeuten.\n\nNach der Lektion schickt Raan Euch zu nahegelegenen Dorflehrern. Dort könnt Ihr einen Beruf erlernen und spezialisierte Einrichtungen für Euer Lager herstellen."}},faq={{q="Wer vergibt die Quest The Great Outdoors?",a="Raan, ein erfahrener Reisender, lehrt umherziehende Abenteurer, wie sie in der offenen Wildnis überleben.",al={"wer bietet the great outdoors an","questgeber the great outdoors","raan lagerfeuerquest"}},{q="Was ist der Zweck von The Great Outdoors?",a="Die Lektion vermittelt das Überleben in der Wildnis. Ruht Euch vor gefährlichen Reisen an einem einfachen Lagerfeuer aus, um Boosted Rest zu erhalten.",al={"was lehrt the great outdoors","the great outdoors zweck","was lernt man von raan"}},{q="Wie wird die Quest abgeschlossen?",a="Setzt Euch an Raans einfaches Lagerfeuer und ruht Euch aus, bis Ihr Boosted Rest erhaltet.",al={"wie the great outdoors abschließen","raan lagerfeuer questziel","boosted rest questziel"}},{q="Was empfiehlt Raan nach Abschluss der Quest?",a="Nach der Lektion am Lagerfeuer ermutigt Raan Euch, nahegelegene Dorflehrer zu besuchen und einen praktischen Beruf zu erlernen. Handwerker können Lagereinrichtungen herstellen, die zu ihrem Handwerk passen.",al={"was rät raan als nächstes","wohin nach the great outdoors","nach abschluss von the great outdoors"}},{q="Was ist Boosted Rest?",a="Boosted Rest ist ein erholsamer Effekt, den man durch das Ausruhen an einem eingerichteten Lagerfeuer erhält. Er hilft Reisenden, sich zu erholen, während sie den Elementen trotzen.",al={"was ist boosted rest","lagerfeuer boosted rest stärkungszauber"}},{q="Können Abenteurer mithilfe von Berufen Lagereinrichtungen herstellen?",a="Ja. Örtliche Berufslehrer können Euch beibringen, nützliche Lagereinrichtungen passend zu Eurem Handwerk herzustellen, damit Ihr im Freien ein spezialisiertes Lager unterhalten könnt.",al={"können berufe lagerfeuer herstellen","berufe lagereinrichtungen","handwerk lagergegenstände"}}},fp="18,180,19.275.0,24.350.0,39.99.0,42.116.0,27.70.0,56.166.0,21.141.0,60.144.0"}
P.entries["quest:96102"] = {n="Camping 101: Tailoring",s="In der Schneidereiausbildung lernt Ihr, ein Aufmarschbanner herzustellen. Sein Test gehört in die Wildnis, wo ein Lager ein Lagerfeuer braucht.",h="In der Schneidereiausbildung lernt Ihr, ein Aufmarschbanner herzustellen.",kw={"lagerfeuer","lagern","kochkunst","aufmarschbanner","schneiderei","wildnis"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, ein Lagerfeuer zu machen.",["profession:Tailoring"]="Als Schneider könnt Ihr ein Aufmarschbanner für ein Lager herstellen."},sec={{t="Zuerst ein Lagerfeuer",b="Ihr könnt jetzt ein Aufmarschbanner herstellen, und der Abschlusshinweis verlangt einen Test in der Wildnis. Ein Lager braucht ein Lagerfeuer, bevor Ihr es aufschlagt. Die meisten Köche können Euch beibringen, eines zu machen, also fragt einen Kochlehrer nach den Grundlagen, falls Ihr sie noch nicht gelernt habt."}},faq={{q="Was kann ich danach herstellen?",a="In der Schneidereiausbildung lernt Ihr, Euer eigenes Aufmarschbanner herzustellen.",al={"was stelle ich her","bannerrezept","schneiderei banner"}},{q="Wo sollte ich das Banner testen?",a="Testet Euer Aufmarschbanner in der Wildnis. Laut Abschlusshinweis halten Stadtbewohner im Allgemeinen wenig von Lagern mitten in der Stadt.",al={"wo testen","wo lagern","banner testen"}},{q="Was braucht ein Lager?",a="Bevor Ihr ein Lager aufschlagt, braucht Ihr ein Lagerfeuer.",al={"was braucht ein lager","lagerfeuer benötigt","grundlagen des lagerns"}},{q="Wer kann mir beibringen, ein Lagerfeuer zu machen?",a="Die meisten Köche können Euch beibringen, ein Feuer zu machen. Ein Kochlehrer kann Euch die Grundlagen beibringen.",al={"lagerfeuer lehrer","wer lehrt feuermachen","kochfeuer"}}},fp="22,124,16.243.0,27.65.0,31.134.0,22.46.0,36.84.0"}
P.entries["quest:96103"] = {n="A Feast for Buzzards",s="Ein zerschlagenes Skelett in den Ebenen trägt Spuren, die einem Jäger verraten könnten, was geschehen ist. Ihr bringt seinen Schädel zu Neza Bloodsnout nach Rog'mar, damit sie ihr Urteil fällt.",h="Ein zerschlagenes Skelett in den Ebenen trägt Spuren, die einem Jäger verraten könnten, was geschehen ist.",kw={"ein festmahl für aasgeier","klauenspuren","angenagter schädel","neza bloodsnout","rog'mar","skelett","zahnspuren"},sec={{t="Ein Schädel in den Ebenen",b="Die Knochen liegen zerschlagen unter der Sonne, ihre blasse Oberfläche von Formen wie Zähnen und Klauen gezeichnet. Die Schäden lassen das Opfer unbekannt. Ihr bringt den Schädel zu Neza Bloodsnout nach Rog'mar, wo eine Jägerin vielleicht erkennt, was die Spuren offenbaren."}},faq={{q="Was ist mit dem Skelett geschehen?",a="Seine Gliedmaßen tragen Spuren, die Zähnen und Klauen ähneln, doch der Angreifer bleibt unklar.",al={"skelett in den ebenen","woran es starb"}},{q="Warum bringt Ihr den Schädel zu Neza?",a="Neza ist eine Jägerin in Rog'mar, die vielleicht erkennt, was die Spuren bedeuten.",al={"warum der schädel zu neza","neza bloodsnout"}},{q="Wer war das Opfer?",a="Das Skelett ist schwer beschädigt, und seine Identität ist unbekannt, bevor Neza den Schädel untersucht.",al={"wessen skelett","wer ist der tote"}},{q="Wo befindet sich Neza Bloodsnout?",a="Neza Bloodsnout befindet sich in Rog'mar.",al={"nezas aufenthaltsort","wo liegt rog'mar"}}},fp="20,151,21.235.0,30.82.0,28.69.0,19.90.0,25.30.0"}
P.entries["quest:96104"] = {n="Song of the Strider",s="Neza Bloodsnout entdeckt nahe Rog'mar die Spuren eines großen Löwen und bietet an, ihn herauszulocken. Ihr bringt ihr einen tallstrider-Schnabel, damit sie daraus eine Jagdpfeife fertigen kann.",h="Neza Bloodsnout entdeckt nahe Rog'mar die Spuren eines großen Löwen und bietet an, ihn herauszulocken.",kw={"schnabel","löwe","neza bloodsnout","rog'mar","lied des tallstriders","tallstrider","pfeife"},sec={{t="Eine Jagdpfeife",b="Bei Rog'mar deutet Neza Bloodsnout die Spuren als die eines Löwen, wahrscheinlich des Anführers eines Rudels in der Nähe. Sie überlässt Euch die erste Beute und hilft dabei, das Tier herauszulocken. Dafür braucht sie einen tallstrider-Schnabel, um eine Pfeife zu fertigen, die wie der Ruf eines verwundeten tallstrider klingt."}},faq={{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist eine Jägerin bei Rog'mar, die Pfeifen und Tierlaute herstellen kann.",al={"neza","wer ist neza","neza bloodsnout"}},{q="Was glaubt Neza, hat die Markierungen verursacht?",a="Neza glaubt, dass die Markierungen von einem Löwen stammen, wahrscheinlich dem Anführer eines Rudels in der Nähe.",al={"was verursachte diese markierungen","löwenspuren","markierungen bei rog'mar"}},{q="Warum braucht Neza einen tallstrider-Schnabel?",a="Neza braucht einen tallstrider-Schnabel, um eine Pfeife zu fertigen, die den Ruf eines verwundeten tallstrider nachahmt.",al={"wofür der schnabel","wofür tallstrider-schnabel","schnabel für pfeife"}},{q="Wozu dient die Pfeife?",a="Die Pfeife soll den Löwen herauslocken, indem sie wie der Ruf eines verwundeten tallstrider klingt.",al={"was bewirkt die pfeife","löwen herauslocken","löwenpfeife"}},{q="Wohin bittet Neza Euch, den Schnabel zu bringen?",a="Bringt den unversehrten tallstrider-Schnabel zu Neza Bloodsnout bei Rog'mar.",al={"wohin den schnabel bringen","nezas ort","schnabel abgeben"}}},fp="19,157,18.271.0,23.78.0,39.79.0,38.90.0,24.81.0,42.64.0"}
P.entries["quest:96105"] = {n="King of the Wild Plains",s="Neza Bloodsnout bei Rog'mar schickt Euch auf die Jagd nach dem Anführer eines Löwenrudels. Ein Tallstrider Call wird das Tier auf einem Hügel südlich der Löwen herbeirufen.",h="Neza Bloodsnout bei Rog'mar schickt Euch auf die Jagd nach dem Anführer eines Löwenrudels.",kw={"fell","hügel","könig der wilden ebenen","anführer","löwenrudel","neza bloodsnout","rog'mar","tallstrider call"},sec={{t="Der Ruf",b="Neza Bloodsnout bei Rog'mar hat einen Tallstrider Call für Euch bereit. Bringt ihn zum Hügel südlich der Löwen und benutzt ihn, sobald Ihr bereit seid, Euch dem Anführer des Rudels zu stellen. Neza bittet Euch, das Fell des Tieres zurückzubringen. Die Jagd wird Eure Stärke auf diesen Ebenen auf die Probe stellen."}},faq={{q="Wer will das Löwenfell?",a="Neza Bloodsnout bei Rog'mar bittet Euch, das Fell des Anführers des Löwenrudels zurückzubringen.",al={"wer hat mich geschickt","neza bloodsnout","fell für neza"}},{q="Was bewirkt der Tallstrider Call?",a="Der Tallstrider Call ruft bei Benutzung den Anführer des Löwenrudels herbei.",al={"wozu ist die pfeife","rufpfeife","löwen herbeirufen"}},{q="Wo soll ich den Tallstrider Call benutzen?",a="Benutzt den Tallstrider Call auf dem Hügel südlich des Gebiets, in dem die Löwen leben.",al={"wo ist der hügel","löwenhügel","wo soll ich es rufen"}},{q="Was jage ich?",a="Ihr jagt den Anführer des Löwenrudels.",al={"welches tier","könig der wilden ebenen","löwenanführer"}}},fp="23,141,8.266.0,26.86.0,34.68.0,40.68.0,18.45.0"}
P.entries["quest:96107"] = {n="Feathers for Fletching",s="Neza Bloodsnout in Rog'mar stellt ihre Pfeile selbst her und bittet um Plains Buzzard Feathers. Ihre grobe Struktur macht sie für die Befiederung nützlich.",h="Neza Bloodsnout in Rog'mar stellt ihre Pfeile selbst her und bittet um Plains Buzzard Feathers.",kw={"pfeile","federn","befiederung","jäger","neza bloodsnout","plains buzzard","rog'mar"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Ihr regelmäßig Pfeile braucht. Neza stellt ihre selbst her und vertraut auf ihr handwerkliches Können."},sec={{t="Nezas Pfeile",b="In Rog'mar bittet Neza Bloodsnout Euch, Federn von den Bussarden in der Nähe zu sammeln. Sie fertigt ihre Pfeile von Hand und vertraut auf ihre eigene Arbeit. Die groben Federn eignen sich zur Befiederung, den Federn, die einem Pfeil zu einem geraden Flug verhelfen."}},faq={{q="Warum möchte Neza Bussardfedern?",a="Neza verwendet die groben Plains Buzzard Feathers zur Befiederung der Pfeile, die sie von Hand herstellt.",al={"grund für bussardfedern","warum federn","neza federn"}},{q="Wer ist Neza Bloodsnout?",a="Neza Bloodsnout ist eine Pfeilmacherin in Rog'mar, die ihre Pfeile am liebsten von Hand herstellt.",al={"wer ist neza","neza bloodsnout","neza in rog'mar"}},{q="Wo finde ich Neza?",a="Neza Bloodsnout ist in Rog'mar.",al={"wo ist neza","nezas standort","rog'mar neza"}}},fp="22,139,13.215.0,36.91.0,23.84.0,22.30.0"}
P.entries["quest:96108"] = {n="Poison Tips",s="Neza Bloodsnout möchte das Gift der Glade Vipers aus den Tümpeln südlich von Rog'mar. Sie will Pfeile damit bestreichen, obwohl das Gift das Fleisch verdirbt.",h="Neza Bloodsnout möchte das Gift der Glade Vipers aus den Tümpeln südlich von Rog'mar.",kw={"glade viper","neza bloodsnout","giftpfeile","giftspitzen","rog'mar","vipergift"},sec={{t="Ein tödlicher Überzug",b="Gift kann einen Pfeil wirksamer machen, doch es verdirbt das Fleisch. Neza Bloodsnout bei Rog'mar glaubt, dass Ihr das Gift der Vipern an den Tümpeln im Süden sammeln könnt. Ihr Gift ist gefährlich im Umgang, daher ist beim Sammeln Vorsicht geboten."}},faq={{q="Wer möchte das Vipergift?",a="Neza Bloodsnout bei Rog'mar möchte das Gift der Glade Vipers.",al={"wer bat um gift","neza bloodsnout gift","wer ist neza"}},{q="Wofür ist das Gift gedacht?",a="Neza will das Gift als Überzug für Pfeile verwenden.",al={"wozu das gift","giftpfeile","wofür wird es verwendet"}},{q="Woher stammt das Gift?",a="Die Glade Vipers an den Tümpeln im Süden erzeugen das Gift.",al={"wo sind die vipern","fundort des vipergifts","vipern an den tümpeln"}},{q="Warum Pfeile mit Gift bestreichen?",a="Giftüberzüge machen Pfeile gegen Beute wirksamer, verderben aber das Fleisch.",al={"warum giftpfeile","warum giftspitzen","pfeile verstärken"}},{q="Ist das Sammeln des Gifts der Glade Vipers gefährlich?",a="Ja. Neza warnt, dass Ihr beim Sammeln dem Gift der Vipern erliegen könntet.",al={"kann mich das gift verletzen","gefahr durch vipergift","giftwarnung"}}},fp="11,140,16.235.0,26.51.0,22.59.0,31.61.0,28.72.0,41.79.0"}
P.entries["quest:96109"] = {n="A Hunter's Quiver",s="Neza Bloodsnout bei Rog'mar braucht Löwenfelle für einen Jägerköcher. Ihr sammelt Felle von den Löwen auf dem südlichen Hügel.",h="Neza Bloodsnout bei Rog'mar braucht Löwenfelle für einen Jägerköcher.",kw={"pfeile","jäger","jägerköcher","löwenfelle","löwen","neza bloodsnout","begehrte löwenfelle","rog'mar"},ang={["class:Hunter"]="Als Jäger braucht Ihr einen Köcher, der viele Pfeile fasst, ohne Euch zu behindern."},sec={{t="Ausrüstung eines Jägers",b="Die Waffen eines Jägers brauchen einen Köcher, der viele Pfeile fasst, ohne seinen Träger zu behindern. Neza Bloodsnout bei Rog'mar bittet Euch, dafür begehrte Löwenfelle zu sammeln. Die Löwen jagen in Rudeln, daher warnt Neza Euch davor, Euch umzingeln zu lassen."}},faq={{q="Wer braucht die Löwenfelle?",a="Neza Bloodsnout bei Rog'mar braucht begehrte Löwenfelle für einen Jägerköcher.",al={"wer die felle möchte","neza bloodsnout felle"}},{q="Wofür sind die Felle?",a="Die Löwenfelle sind das Material für einen robusten Köcher, der eng anliegt und viele Pfeile fasst, ohne seinen Träger zu behindern.",al={"wofür löwenfelle","köcherfelle"}},{q="Wo sind die Löwen?",a="Die Löwen halten sich auf einem Hügel im Süden auf, der von Rog'mar aus zu sehen ist.",al={"löwenhügel","wo löwen"}},{q="Warum möchte Neza Löwenfelle?",a="Neza sagt, Löwenfelle eignen sich gut für das Leben als Jäger in der Steppe.",al={"warum löwenfelle","löwen für köcher"}},{q="Wovor warnt Neza?",a="Neza warnt, dass die Löwen in Rudeln jagen und Euch umzingeln könnten.",al={"warnung vor löwen","rudel"}}},fp="17,120,15.230.0,25.73.0,23.118.0,20.62.0,30.71.0,28.61.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Nahe den Baumbeständen westlich des Stonebullsees bedroht Chakuyak Reisende, die Mulgore durchqueren. Die einheimischen Stammesangehörigen haben die wilde Wölfin zur Jagd freigegeben, und ihr Balg wird in Ehren gehalten werden.",h="Nahe den Baumbeständen westlich des Stonebullsees bedroht Chakuyak Reisende, die Mulgore durchqueren.",kw={"chakuyak","mulgore","präriewolf","stonebullsee","taurenjagd","reisende","wolfsbalg"},ang={["class:Hunter"]="Als Jäger braucht Ihr Geduld und scharfe Sinne, um einen wilden, einzelgängerischen Alphawolf durch bewaldete Hügel zu verfolgen. Begegnet dem Raubtier mit Respekt.",["race:Tauren"]="Als Tauren kennt Ihr das Gleichgewicht zwischen der Ehrfurcht vor der Natur und der Pflicht, Euren Stamm zu schützen. Den Balg eines erlegten Tieres zu nutzen, ehrt es."},sec={{t="Der Schatten des Stonebullsees",b="Chakuyak durchstreift die Baumbestände westlich des Stonebullsees, wo Präriewölfe über Mulgores grasbewachsene Hochebenen und sanfte Hügel ziehen. Dieses wilde Alphaweibchen ist zur Gefahr für Reisende aus der Ferne geworden, weshalb einheimische Jäger sie zum Abschuss freigegeben haben, bevor weitere Wanderer zu Schaden kommen."},{t="Ehrfurcht und Notwendigkeit",b="Für die einheimischen Stämme verlangt das Töten Chakuyaks nach ernster Ehrfurcht, nicht nach Prahlerei. Sie sehen es als notwendig an, um Reisende und Dorfbewohner zu schützen. Ihr dichter Balg wird gegerbt und genutzt, um die Wölfin zu ehren und sicherzustellen, dass ihr Opfer nicht vergebens ist."}},faq={{q="Wer oder was ist Chakuyak?",a="Chakuyak ist eine große, ungewöhnlich aggressive Präriewölfin, die Reisende in Mulgore bedroht.",al={"was ist chakuyak","wer ist chakuyak","ist chakuyak ein wolf"}},{q="Wo befindet sich Chakuyak?",a="Chakuyak durchstreift die Baumbestände westlich des Stonebullsees, inmitten der bewaldeten Hügel.",al={"wo chakuyak finden","chakuyak fundort","wo streift chakuyak umher"}},{q="Warum muss Chakuyak zur Strecke gebracht werden?",a="Chakuyak ist kühn und aggressiv geworden und stellt damit eine Gefahr für Reisende aus der Ferne dar.",al={"warum chakuyak töten","chakuyak bedrohung"}},{q="Was geschieht nach der Jagd mit Chakuyaks Balg?",a="Ihr Balg wird haltbar gemacht und genutzt, damit nichts verschwendet wird.",al={"was geschieht mit chakuyaks balg","chakuyaks fell"}},{q="Brauche ich eine Gruppe, um Chakuyak zu jagen?",a="Chakuyak ist außergewöhnlich wild. Reisende schließen sich oft zu kleinen Jagdgruppen zusammen, um sie sicher aufzuspüren und zu erlegen.",al={"gruppe für chakuyak sinnvoll","ist chakuyak allein schwer zu besiegen"}},{q="Wer würdigt Euren Sieg über Chakuyak?",a="Der Jäger, der die Jagd ausgerufen hat, verspricht, Eure Tat vor dem Stammeshäuptling zu preisen, wenn Ihr mit Chakuyaks Balg zurückkehrt.",al={"wer belohnt die jagd auf chakuyak","chakuyak häuptling"}}},fp="8,179,28.287.0,23.239.0,24.90.0,26.79.0,33.94.0,47.59.0,35.112.0,44.119.0"}
P.entries["quest:96137"] = {n="Ira's Dagger",s="Sirra Von'Indi bittet Euch, mehr über Iras Dolch und die Worgs herauszufinden, die noch immer Reisenden zusetzen. Iras Geist hat im Wald womöglich noch etwas zu erledigen.",h="Sirra Von'Indi bittet Euch, mehr über Iras Dolch und die Worgs herauszufinden, die noch immer Reisenden...",kw={"black ravager","dunkelhain","ira","iras dolch","waldläuferin","sirra von'indi","geist","worg","young black ravager"},sec={{t="Der Dolch einer Waldläuferin",b="Sirra Von'Indi in Dunkelhain bittet Euch, Euch um die Worgs zu kümmern, die im Wald weiterhin Opfer fordern. Ira war eine selbst ernannte Waldläuferin, die den Wald sicherte, indem sie Bestien davon abhielt, Reisende anzugreifen. Ihr Geist wandert noch immer dort umher, und der Dolch gehörte ihr. Sirra sucht weitere Informationen über die Klinge."}},faq={{q="Wer war Ira?",a="Ira war eine selbst ernannte Waldläuferin, die den Wald sicherte, indem sie Bestien davon abhielt, Reisende anzugreifen.",al={"iras hintergrundgeschichte","wer ist ira"}},{q="Warum wandert Iras Geist durch den Wald?",a="Iras Geist wandert noch immer durch den Wald, und womöglich hat sie dort noch etwas zu erledigen.",al={"iras geist warum","warum ist ira ein geist"}},{q="Was ist Iras Dolch?",a="Es ist ein kleiner Dolch, der Ira gehörte.",al={"iras dolch","geschichte des dolchs"}},{q="Warum kümmert Ihr Euch um die Worgs?",a="Die Worgs fordern weiterhin im ganzen Wald Opfer, und womöglich besteht Iras unerledigte Aufgabe darin, sie zu vertreiben.",al={"worgs im wald","ira worg quest"}},{q="Wer erkundigt sich nach dem Dolch?",a="Sirra Von'Indi in Dunkelhain bittet Euch, mit dem Dolch zu ihr zurückzukehren, um mehr zu erfahren.",al={"sirra dolch","wer will iras dolch"}}},fp="12,145,17.316.0,12.103.0,40.81.0,21.42.0,31.114.0,26.91.0"}
P.entries["quest:96138"] = {n="Merrick's Bow",s="Sirra Von'Indi bittet Euch, den Ogern nachzugehen, die Merrick Valors Geist nahe Rabenflucht beunruhigen. Merricks Bogen könnte helfen, die Geschichte des Ortes zu erhellen.",h="Sirra Von'Indi bittet Euch, den Ogern nachzugehen, die Merrick Valors Geist nahe Rabenflucht beunruhigen.",kw={"dunkelhain","merrick valor","merricks bogen","oger","rabenflucht","sirra von'indi","splinter fist","wächter"},sec={{t="Die Sorge eines Geistes",b="Nahe Rabenflucht wandert Merrick Valors Geist noch immer über die Straßen. Ihr habt einen Bogen, den er zurückgelassen hat, und seine unerledigten Angelegenheiten könnten mit den Ogern südlich des Ortes zusammenhängen. Sirra Von'Indi in Dunkelhain kann Euch mehr über den Bogen und Merricks Vergangenheit erzählen."},{t="Merricks Vergangenheit",b="Sirra Von'Indi sagt, Merrick habe sich immer beweisen wollen und ihm und seiner Familie sei etwas zugestoßen. Sie dankt Euch dafür, dass Ihr den Bogen gebracht habt, und hofft, dass er mehr Licht auf Rabenfluchts Geschichte werfen wird."}},faq={{q="Wer war Merrick Valor?",a="Merrick Valor war ein berühmter Wächter, der stolz darauf war, die Straßen vor vordringenden Feinden zu schützen.",al={"merrick","merrick valor"}},{q="Warum wandert Merricks Geist umher?",a="Merricks Geist wandert noch immer über die Straßen. Seine unerledigten Angelegenheiten könnten mit den Ogern südlich von Rabenflucht zusammenhängen.",al={"merricks geist","warum wandert der geist umher"}},{q="Was hat Merricks Bogen mit Rabenflucht zu tun?",a="Sirra Von'Indi hofft, dass Merricks Bogen mehr Licht auf Rabenfluchts Geschichte werfen kann.",al={"merricks bogen","bogen rabenflucht"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist in Dunkelhain und kann Euch mehr über Merricks Bogen erzählen.",al={"sirra","sirra von indi"}},{q="Was ist Merrick und seiner Familie zugestoßen?",a="Sirra Von'Indi sagt, Merrick und seiner Familie sei etwas zugestoßen, nennt aber keine weiteren Einzelheiten.",al={"merricks familie","was geschah mit merrick"}}},fp="13,154,18.240.0,14.205.1,22.96.0,34.111.0,51.79.0,22.73.0,40.95.0"}
P.entries["quest:96139"] = {n="The Valor Family",s="In Dunkelhain sucht Sirra Von'Indi Aufzeichnungen über die verschollenen Bewohner von Rabenflucht. Das Dorf erinnert sich an ihren Mut, doch ihre Bibliothek bewahrt nur wenig von Rabenfluchts Geschichte.",h="In Dunkelhain sucht Sirra Von'Indi Aufzeichnungen über die verschollenen Bewohner von Rabenflucht.",kw={"dunkelhain","dämmerwald","geschichte","lady althea","rabenflucht","sirra von'indi","foliant","familie valor"},sec={{t="Eine verlorene Geschichte",b="Sirra Von'Indi sagt, mutige Menschen hätten Dunkelhain geholfen, zu bestehen. Lady Althea gehörte zu ihnen, ebenso wie jene, die in Rabenflucht starben. Ihr werdet gebeten, nach allem zu suchen, was die Erinnerung an sie bewahren könnte."},{t="Der Foliant",b="Das Buch, das Ihr zurückbringt, erzählt von der Familie Valor. Sirra bietet an, es abzuschreiben, und freut sich über jedes weitere Material über sie."}},faq={{q="Wer bittet mich, Rabenflucht zu durchsuchen?",a="Sirra Von'Indi, deren Bibliothek in Dunkelhain liegt, bittet Euch, Rabenflucht nach Material über seine Bewohner zu durchsuchen.",al={"wer will das buch","sirra rabenflucht","wer ist sirra"}},{q="Warum will Sirra Aufzeichnungen aus Rabenflucht?",a="Sirra möchte, dass Rabenfluchts Geschichte in Erinnerung bleibt. Sie ging mit den Menschen verloren, die dort lebten.",al={"warum rabenflucht durchsuchen","rabenfluchts geschichte","erinnerung an rabenflucht"}},{q="Wer half laut Sirra dabei, Dunkelhain zu erhalten?",a="Sirra nennt Lady Althea und jene, die in Rabenflucht ihr Leben verloren, als mutige Menschen, deren Taten Dunkelhain halfen, zu bestehen.",al={"dunkelhains helden","lady althea","wer rettete dunkelhain"}},{q="Wie steht es um Rabenfluchts Geschichte?",a="Sirra sagt, Rabenfluchts Geschichte sei mit seinen Bewohnern verloren gegangen. Ihre Bibliothek enthält nur wenig darüber.",al={"was geschah mit rabenflucht","rabenfluchts vergangenheit","rabenflucht verloren"}}},fp="16,162,14.194.0,8.118.1,38.107.0,44.95.0,50.123.0,34.98.0"}
P.entries["quest:962"] = {n="Schlangenflaum",s="Tief in den Höhlen des Wehklagens weckt Schlangenflaum die Aufmerksamkeit von Apothekerin Zamah. Sie sucht weitere Exemplare für die Forschung der Königlichen Apothekervereinigung und die Verlassenen.",h="Tief in den Höhlen des Wehklagens weckt Schlangenflaum die Aufmerksamkeit von Apothekerin Zamah.",kw={"apotheker","brachland","königliche apothekervereinigung","schlangenflaum","die anhöhe der geister","donnerfels","unterstadt","die höhlen des wehklagens","zamah"},ang={["faction:Horde"]="Diese Arbeit stärkt das frühe Bündnis zwischen Unterstadt und den Stämmen Kalimdors. Sie teilen Ressourcen und seltene Reagenzien über den Ozean hinweg.",["profession:Herbalism"]="Die entstellten Höhlen des Wehklagens lassen Pflanzen gedeihen, die nirgendwo sonst auf der sonnenverbrannten Oberfläche des Brachlands zu finden sind.",["race:Tauren"]="Als Tauren seht Ihr die Gastfreundschaft der Horde im Empfang der Apotheker der Verlassenen unter der Anhöhe der Geister. Ihre tödlichen Mixturen stehen im Gegensatz zur traditionellen Heilung durch die Erde.",["race:Undead"]="Das Sammeln von Schlangenflaum unterstützt die alchemistische Arbeit der Königlichen Apothekervereinigung in Lordaeron im Auftrag der Dark Lady."},sec={{t="Die Augen der Apothekerin",b="Apothekerin Zamah wacht über die Teiche der Visionen unter der Anhöhe der Geister in Donnerfels. Sie kam als Gesandte der Königlichen Apothekervereinigung aus Unterstadt. Ihre Gastgeber, die Tauren, kümmern sich um das spirituelle Gleichgewicht und das verwundete Land, während Zamah seltene und virulente Stoffe untersucht. Sie hat eine Probe Schlangenflaum isoliert und sucht weitere für Fürstin Sylvanas Windläufer und die Forschung der Verlassenen."},{t="Die Tiefen der Höhlen",b="Schlangenflaum wächst in den feuchten, verwinkelten Grotten der Höhlen des Wehklagens, fern der offenen Sonne des Brachlands. Die verdorbenen Druiden des Giftzahns haben diese feuchten Tiefen entstellt, in denen schlangenartige Bewohner die Pflanze bewachen. Viele von Zamah entsandte Späher kehrten nicht zurück. Nun sucht sie zähe Abenteurer, die mehr davon sammeln."}},faq={{q="Wer ist Apothekerin Zamah?",a="Apothekerin Zamah ist eine Forscherin und Gesandte der Königlichen Apothekervereinigung aus Unterstadt. Sie wacht über die Teiche der Visionen unter der Anhöhe der Geister in Donnerfels und verbindet die Alchemisten der Verlassenen mit dem übrigen Kalimdor.",al={"zamah","apothecary zamah hintergrund","wer vergibt schlangenflaum"}},{q="Warum will die Königliche Apothekervereinigung Schlangenflaum?",a="Zamah glaubt, dass Schlangenflaum chemisches Potenzial birgt, wenn er in großen Mengen veredelt wird. Die Vereinigung sucht in ganz Kalimdor nach seltenen, wirkungskräftigen Pflanzen, um die alchemistischen Experimente der Verlassenen zu unterstützen.",al={"warum schlangenflaum","kräuterforschung der verlassenen","zweck von schlangenflaum"}},{q="Wo wächst Schlangenflaum?",a="Schlangenflaum wächst in feuchten Höhlen unter dem nördlichen Brachland, in den felsigen Gängen und Passagen der Höhlen des Wehklagens.",al={"wo ist schlangenflaum","schlangenflaum fundort"}},{q="Warum sind frühere Späher nicht zurückgekehrt?",a="Die Höhlen des Wehklagens werden von zurückentwickelten Bestien, Raptoren und den verdorbenen Druiden des Giftzahns überrannt. Unerfahrene Sammler wurden in den gewundenen Tunneln rasch von Raubtieren und giftigen Verteidigern überwältigt.",al={"vermisste späher","zamahs späher","sind die höhlen des wehklagens gefährlich"}},{q="Billigen die Tauren Zamahs Forschung?",a="Die Tauren von Donnerfels gewährten den Verlassenen aus Mitgefühl und dem Wunsch, sie zu heilen, Zuflucht. Die Alchemie der Königlichen Apothekervereinigung kann an unnatürliche Experimente grenzen, was traditionelle Schamanen und Druiden beunruhigt.",al={"reaktion der tauren","apotheker auf der anhöhe der geister"}},{q="Braucht man Kräuterkundekenntnisse, um Schlangenflaum zu ernten?",a="Nein. Jeder Abenteurer, der sich in die Höhlen des Wehklagens wagt, kann Schlangenflaum ohne Ausbildung in Kräuterkunde vom Höhlenboden pflücken.",al={"ist kräuterkunde nötig","schlangenflaum sammeln beruf"}}},fx={["962715c8"]={q="Warum möchte Apothekerin Zamah, dass Schlangenflaum gesammelt wird?",a="Apothekerin Zamah wurde von der Königlichen Apothekervereinigung mit einem speziellen Auftrag nach Donnerfels entsandt, um die Interessen der Verlassenen und der Dunklen Fürstin, Fürstin Sylvanas Windläufer, zu fördern. Nachdem sie eine seltene Probe von Schlangenflaum analysiert hat, sieht Zamah ein enormes Potenzial in dessen Eigenschaften, wenn er in beträchtlichen Mengen beschafft wird. Die Sicherung von genügend Exemplaren ermöglicht es ihrer Forschung, die wissenschaftlichen und alchemistischen Ambitionen der Unterstadt voranzutreiben.",al={"apothecary zamah motiv","warum braucht zamah schlangenflaum","warum schlangenflaum sammeln"}},["92b49307"]={q="Warum schickt Apothekerin Zamah einen Abenteurer, anstatt Schlangenflaum selbst zu sammeln?",a="Zamah kann ihren Posten in Donnerfels nicht ohne Weiteres verlassen, und das Ernten des Krauts erfordert das Vordringen in die tückischen, verdorbenen Tiefen der Höhlen des Wehklagens. Sie hat bereits mehrere Späher und Agenten in ihr Höhlensystem entsandt, aber keiner von ihnen kehrte lebend zurück. Sie braucht erfahrene, fähige Abenteurer, die bereit sind, jenen dunklen Winkeln zu trotzen, an denen gewöhnliche Späher gescheitert sind.",al={"warum mich für schlangenflaum schicken","warum besorgt zamah den schlangenflaum nicht","warum abenteurer für schlangenflaum"}}},fp="12,168,22.387.0,25.307.0,24.232.0,56.188.0,29.123.0,37.206.0,42.221.0,54.126.0"}
P.entries["quest:96204"] = {n="The Windshaper's Wrath",s="Lumina Windsinger bittet Euch, ihr bei der Flucht aus Burg Fenris zu helfen. Eure Hilfe gibt ihr Grund, Paladinen zu vertrauen.",h="Lumina Windsinger bittet Euch, ihr bei der Flucht aus Burg Fenris zu helfen.",kw={"flucht","burg fenris","lumina windsinger","paladin","trevan","windformer"},ang={["class:Paladin"]="Lumina hat Unfreundliches über Euresgleichen als Paladine gehört, doch Eure Hilfe gibt ihr Anlass, Euch als Freund willkommen zu heißen."},sec={{t="Ein Weg hinaus",b="Lumina Windsinger ist innerhalb von Burg Fenris frei, doch sie will mit Euch fortgehen. Die Kreaturen, die sie gefangen hielten, sollen bereuen, sich mit einer Windformerin angelegt zu haben. Bleibt bei ihr, während sie flieht."},{t="Ein neuer Freund",b="In Burg Fenris erzählt Euch Lumina, dass sie Trevan getroffen und erfahren hat, dass er Euch geschickt hat, um sie zu finden. Sie hat Unfreundliches über Paladine gehört, doch Eure Hilfe hat ihre Ansicht geändert. Die Windformer zählen Euch und Euresgleichen zu ihren Freunden."}},faq={{q="Wer ist Lumina Windsinger?",a="Lumina Windsinger ist eine Windformerin, die in Burg Fenris gefangen gehalten wurde und Eure Hilfe bei der Flucht sucht.",al={"lumina","wer ist lumina","windsinger"}},{q="Von wo versucht Lumina zu fliehen?",a="Lumina Windsinger versucht, aus Burg Fenris zu fliehen.",al={"lumina flucht","burg fenris","lumina herausholen"}},{q="Wer hat mich geschickt, um Lumina zu finden?",a="Lumina sagt, Trevan habe Euch auf ihre Spur geschickt.",al={"wer hat mich geschickt","trevan","luminas spur"}},{q="Warum erwähnt Lumina Paladine?",a="Lumina hat Unfreundliches über Paladine gehört, sagt aber, dass sich diese Behauptungen nach Eurer Hilfe als unbegründet erwiesen haben.",al={"paladinsache","lumina paladine","vertraut sie paladinen"}},{q="Was hält Lumina von mir?",a="Lumina sagt, Ihr und Euresgleichen habt eine Freundin unter den Windformern.",al={"lumina mag mich","windformer freund","was sagt lumina"}}},fp="22,103,9.192.0,12.220.1,25.91.0,38.50.0,27.44.0,33.102.0,29.66.0"}
P.entries["quest:96241"] = {n="Talkin' bout Toxins, Mon",s="Mazu'kon möchte, dass Ihr Giftproben von den Gnawed Corpses auf der Düsteranhöhe sammelt. Die seltsamen Giftstoffe haben seine Neugier geweckt.",h="Mazu'kon möchte, dass Ihr Giftproben von den Gnawed Corpses auf der Düsteranhöhe sammelt.",kw={"extraktor","düsteranhöhe","düsteranhöhe giftproben","gnawed corpses","mazu'kon","toxin","gift"},sec={{t="Auf der Düsteranhöhe",b="Mazu'kon hat von seltsamen neuen Kreaturen gehört, die auf der Düsteranhöhe umherkriechen. Ihr Gift könnte ungewöhnliche Eigenschaften haben, weshalb er Euch bittet, mit seinem Extraktor Proben von den Gnawed Corpses zu sammeln. Er möchte herausfinden, was dieses Gift anders macht."},{t="Die Proben",b="Mazu'kon dankt Euch dafür, dass Ihr die Giftproben von der Düsteranhöhe gebracht habt. Er sagt, die ungewöhnlichen Eigenschaften des Gifts seien kein Scherz gewesen, und stellt fest, dass Ihr unversehrt zu sein scheint."}},faq={{q="Wer bittet um die Toxinproben?",a="Mazu'kon bittet Euch, Giftproben von den Gnawed Corpses auf der Düsteranhöhe zu sammeln.",al={"wer will toxine","mazu'kon toxin"}},{q="Warum möchte Mazu'kon das Gift haben?",a="Er hat gehört, dass das Gift der Kreaturen ungewöhnliche Eigenschaften haben könnte, und das hat seine Neugier geweckt.",al={"warum toxine","worauf ist er neugierig"}},{q="Wo bekomme ich die Proben?",a="Die Proben stammen von den Gnawed Corpses auf der Düsteranhöhe.",al={"toxinproben wo","düsteranhöhe leichen"}},{q="Was gibt Euch Mazu'kon?",a="Mazu'kon gibt Euch einen Extraktor, um das Gift zu sammeln.",al={"extraktor","wie toxin sammeln"}},{q="Wie viele Toxinproben braucht er?",a="Mazu'kon bittet um fünf Gloomrise Toxin Samples.",al={"probenanzahl","wie viele toxine"}}},fp="24,127,12.244.0,11.153.1,36.80.0,33.91.0,27.50.0,28.52.0,36.47.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Im Coldridgetal schickt Call of Earth einen Initianden zu Teo Hammerstorm nach Ambossar. Dort beginnt die Zwiesprache eines Schamanen mit den Geistern des Steins.",h="Im Coldridgetal schickt Call of Earth einen Initianden zu Teo Hammerstorm nach Ambossar.",kw={"ambossar","call of earth","das coldridgetal","dun morogh","erdtotem","elemente","schamane","teo hammerstorm"},ang={["class:Shaman"]="Als Schamane beginnt Euer Weg damit, dem Ruf der Erde zu folgen, der Euch an tiefes Gestein und die standhaften Geister des Landes bindet.",["faction:Alliance"]="Als Schamane der Allianz in Dun Morogh beginnt Ihr Eure Reise mit den Elementen in Ambossar, der altehrwürdigen Zwergenfeste.",["race:Dwarf"]="Als Zwerg kann Eure Verbindung zu Stein und Erde die Zwiesprache mit diesen Geistern in den tiefen Gewölben von Dun Morogh natürlich erscheinen lassen."},sec={{t="Die Stimme des Steins",b="Die erste Zwiesprache eines Initianden mit den Elementen beginnt, wenn die Erde ruft. Andere elementare Energien mögen sich bereits regen, doch das Gespräch mit dem Stein bringt Gleichgewicht. Die Erde lehrt den Initianden, eine Kraft zu finden, die nicht nachgibt. Fester Halt entsteht unter seinen Stiefeln und in seinem Geist."},{t="Die Feste Ambossar",b="In den verschneiten Weiten von Dun Morogh finden Initianden in Ambossar Schutz und Unterweisung. Die Feste liegt im Coldridgetal, geschmiedet durch Hammer, Feuer und Willenskraft. Teo Hammerstorm wartet im Inneren und lehrt angehende Schamanen, auf die grollende Erde zu hören und ihre elementaren Pflichten aufzunehmen."}},faq={{q="Was ist Call of Earth?",a="Call of Earth ruft einen angehenden Schamanen dazu auf, die Zwiesprache mit den Erdgeistern zu beginnen. Die Aufforderung weist den Initianden an, Führung zu suchen und in der Kraft des lebendigen Steins Halt zu finden.",al={"was ist call of earth","call of earth quest","was ist diese quest"}},{q="Wer ist Teo Hammerstorm?",a="Teo Hammerstorm unterweist Initianden in Ambossar, der Zwergenfeste im Coldridgetal. Er leitet sie dabei an, Zwiesprache mit der Erde zu halten und ihre beständige Kraft kennenzulernen.",al={"wer ist teo hammerstorm","wo ist teo hammerstorm","teo hammerstorm standort"}},{q="Was ist Ambossar?",a="Ambossar ist eine Zwergenfeste im Coldridgetal, in den verschneiten Weiten von Dun Morogh. Geschmiedet durch Hammer, Feuer und Willenskraft, ist sie ein Bollwerk, in dem junge Helden ausgebildet werden.",al={"wo ist ambossar","was ist ambossar","ambossar standort"}},{q="Warum muss ein Schamane dem Ruf der Erde folgen?",a="Ein Schamane folgt dem Ruf der Erde, um seinen Geist zu erden und festen Halt unter seinen Sohlen zu finden. Die Zwiesprache mit dem Stein macht dessen beständige Kraft zugänglich.",al={"warum mit der erde sprechen","zweck von call of earth","verbindung zwischen schamane und erde"}},{q="Wer folgt dieser Aufforderung?",a="Die Aufforderung richtet sich an Schamanen, die ihren Weg in Dun Morogh beginnen. Sie weist ihnen den Weg zu erfahrenen Lehrern der Elemente, die ihre Verbindung zu den Geistern lenken können.",al={"wer erteilt call of earth","wer nimmt call of earth an","wer macht diese quest"}},{q="Wohin führt diese Quest?",a="Die Reise führt nach Ambossar im Coldridgetal, im verschneiten Dun Morogh. Initianden betreten die Feste, um ihren Mentor zu finden.",al={"wo findet call of earth statt","call of earth gebiet","wohin gehen"}}},fp="13,156,18.294.0,24.275.0,22.177.0,23.171.0,17.163.0,41.157.0,28.155.0,27.130.0"}
P.entries["quest:96259"] = {n="Defending the Dead",s="Bei Gloomrise bedrohen Spinnen die Bewohner Mulg ores und eine uralte Begräbnisstätte der Tauren. Ihr werdet gebeten, den Befall einzudämmen.",h="Bei Gloomrise bedrohen Spinnen die Bewohner Mulg ores und eine uralte Begräbnisstätte der Tauren.",kw={"defending the dead","gloomrise","jungtiere","mulgore","soldaten","spinnen","begräbnisstätte der tauren"},ang={["race:Tauren"]="Für Euch als Tauren ist Gloomrise eine bedeutende uralte Begräbnisstätte, die vielen Eures Volkes heilig ist."},sec={{t="Die Begräbnisstätte",b="Ein Lager bittet Euch, Gloomrise zu schützen, eine uralte Begräbnisstätte der Tauren nordwestlich des Lagers. Bösartige Spinnen haben den Ort befallen, bedrohen die Bewohner Mulg ores und beschädigen eine Stätte, die vielen Tauren heilig ist."},{t="Ein erster Stützpunkt",b="Eure Bemühungen helfen den Bewohnern Mulg ores, einen Stützpunkt gegen die Spinnen zu errichten. Den Befall vollständig zu beseitigen, könnte Zeit brauchen, weshalb die Begräbnisstätte weiterhin gefährdet ist."}},faq={{q="Was ist Gloomrise?",a="Gloomrise ist eine uralte Begräbnisstätte der Tauren nordwestlich des Lagers.",al={"gloomrise begräbnisstätte","wo ist gloomrise"}},{q="Warum ist Gloomrise in Gefahr?",a="Bösartige Spinnen haben Gloomrise befallen, bedrohen die Bewohner Mulg ores und beschädigen die heilige Begräbnisstätte.",al={"spinnen bei gloomrise","warum die toten verteidigen"}},{q="Warum ist die Begräbnisstätte heilig?",a="Viele Tauren betrachten Gloomrise als heilig.",al={"heilige stätte der tauren","warum begräbnisstätte der tauren"}},{q="Wer bittet um Hilfe?",a="Ein Lager bittet Euch, Gloomrise vor dem Spinnenbefall zu schützen.",al={"wer braucht hilfe","wer hat das gegeben"}},{q="Wurde der Befall beseitigt?",a="Nein. Eure Bemühungen schaffen einen Stützpunkt, doch den Befall vollständig zu beseitigen, könnte Zeit brauchen.",al={"sind die spinnen weg","gloomrise befall"}}},fp="18,133,17.202.0,10.170.1,18.67.0,27.103.0,32.38.0,18.70.0,33.90.0"}
P.entries["quest:96260"] = {n="Stronger than Steel",s="Auf der Düsteranhöhe sucht ein Forscher kristalline Seide von den sich ausbreitenden Riesenspinnen. Aus der Seide könnte ein leichter Stoff entstehen, der starken Schutz bietet.",h="Auf der Düsteranhöhe sucht ein Forscher kristalline Seide von den sich ausbreitenden Riesenspinnen.",kw={"umhang","stoff","kristalline seide","düsteranhöhe","spinnen","stärker als stahl","gift"},sec={{t="Seide für die Forschung",b="Ein Forscher bittet Euch um mehr kristalline Seide, nachdem ein Späher von der Düsteranhöhe zurückkehrte und über und über damit bedeckt war. Riesenspinnen haben sich auf dem Gräberfeld ausgebreitet, und ihr Gift soll die Toten erwecken. Die Widerstandsfähigkeit der Seide könnte sie für Stoff mit schützenden Eigenschaften nützlich machen."},{t="Ein neues Gewebe",b="Die Proben reichen für die Bedürfnisse des Forschers aus. Euch wird ein Umhang aus bereits vorhandener Seide angeboten, in der Hoffnung, dass er Euch auf Euren Reisen hilft."}},faq={{q="Was möchte der Forscher?",a="Der Forscher möchte mehr kristalline Seide von den Spinnen der Düsteranhöhe, um sie zu untersuchen.",al={"seidenproben","kristalline seide","welche seide"}},{q="Wo findet man die Seide?",a="Die kristalline Seide stammt von Riesenspinnen auf der Düsteranhöhe.",al={"wo seide","düsteranhöhe seide","spinnenseide fundort"}},{q="Warum wird die Seide untersucht?",a="Aus der Seide könnte leichter, strapazierfähiger Stoff mit schützenden Eigenschaften hergestellt werden.",al={"seide verwendung","was kann seide","warum seide"}},{q="Was erzählt man sich über das Gift der Spinnen?",a="Das Gift der Spinnen soll stark genug sein, um die Toten zu erwecken.",al={"spinnengift","tote erwecken","gift gerücht"}},{q="Was brachte der Späher mit zurück?",a="Ein Späher kehrte von der Erkundung der Düsteranhöhe zurück und war über und über mit widerstandsfähiger, kristalliner Spinnenseide bedeckt.",al={"späherbericht","späher seide","was geschah dem späher"}}},fp="19,138,14.273.0,11.152.1,30.80.0,24.59.0,19.79.0,41.67.0,30.94.0"}
P.entries["quest:96261"] = {n="The Broodmother",s="Auf der Düsteranhöhe bittet Euch der Irdene Ring, die Spinnenplage aufzuhalten, indem Ihr Euch ihrer Brutmutter stellt. Die Bedrohung gefährdet die Bewohner Mulg ores.",h="Auf der Düsteranhöhe bittet Euch der Irdene Ring, die Spinnenplage aufzuhalten, indem Ihr Euch ihrer...",kw={"brutmutter","der irdene ring","düsteranhöhe","plage","mulgore","nachtelfische gestalt","spinnen","valraxx"},sec={{t="Das Nest der Düsteranhöhe",b="Der Irdene Ring glaubt, dass eine mächtige Matriarchin die Spinnenplage auf der Düsteranhöhe vorantreibt. Ihr sollt Broodmother Valraxx aufspüren und vernichten. Die Spinnen scheinen keine gewöhnlichen Spinnen zu sein, also warnt Euch der Ring, auf alles gefasst zu sein."},{t="Beunruhigende Zeichen",b="Danach berichtet der Irdene Ring von wiederbelebten Toten und einer Brutmutter mit nachtelfischer Gestalt. Diese Entdeckungen beunruhigen seine Mitglieder, doch sie lassen die Frage nach deren Bedeutung vorerst ruhen. Sie danken Euch, dass Ihr dem Ring und den Bewohnern Mulg ores geholfen habt."}},faq={{q="Was geschieht auf der Düsteranhöhe?",a="Auf der Düsteranhöhe breitet sich eine Spinnenplage aus, und der Irdene Ring glaubt, dass eine mächtige Matriarchin sie anführt.",al={"düsteranhöhe spinnen","spinnenplage","was ist auf der düsteranhöhe"}},{q="Wer ist Broodmother Valraxx?",a="Broodmother Valraxx ist die Brutmutter auf der Düsteranhöhe, die Ihr im Auftrag des Irdenen Rings vernichten sollt.",al={"valraxx","brutmutter","spinnenmatriarchin"}},{q="Warum will der Irdene Ring die Brutmutter beseitigen?",a="Der Ring glaubt, dass die Brutmutter die Ausbreitung der feindseligen Spinnen vorantreibt.",al={"warum brutmutter töten","warum valraxx","spinnen aufhalten"}},{q="Wo ist die Brutmutter?",a="Broodmother Valraxx befindet sich auf der Düsteranhöhe.",al={"valraxx aufenthaltsort","wo ist die brutmutter","wo liegt die düsteranhöhe"}},{q="Was sagt der Irdene Ring über diese Spinnen?",a="Der Irdene Ring sagt, dass dies keine gewöhnlichen Spinnen zu sein scheinen.",al={"seltsame spinnen","gewöhnliche spinnen","spinnen seltsam"}}},fp="15,149,18.247.0,15.238.1,31.113.0,27.94.0,52.85.0,25.36.0,51.59.0"}
P.entries["quest:96264"] = {n="Elemental Aid",s="Ein Schamane soll die Versammlung der Stacheleber im Kral der Klingenhauer untersuchen. Die Erde warnt vor einem Ritual, und die Elemente brauchen Hilfe gegen jene, die ihre Macht missbrauchen.",h="Ein Schamane soll die Versammlung der Stacheleber im Kral der Klingenhauer untersuchen.",kw={"charlga klingenflanke","erde","elementare hilfe","elemente","stacheleber","kral der klingenhauer","ritual","schamane"},ang={["class:Shaman"]="Als Schamane beherrscht Ihr die Elemente, und diese Bitte fordert Euch auf, ihre Hilfe zu erwidern."},sec={{t="Die Warnung der Erde",b="Die Erde überbringt einem Schamanen eine Warnung: Die Stacheleber versammeln sich im Kral der Klingenhauer zu einem Ritual von schrecklicher Macht. Eure Aufgabe ist es, ihren Kral zu erkunden und mit Informationen über ihre Pläne zurückzukehren. Die Elemente gewähren Euch ihre Hilfe, und nun brauchen sie Eure."}},faq={{q="Wovor warnt die Erde?",a="Die Erde warnt davor, dass die Stacheleber sich für ein Ritual von schrecklicher Macht versammeln.",al={"warnung der erde","was grollt","ritual der stacheleber"}},{q="Wo versammeln sich die Stacheleber?",a="Die Stacheleber versammeln sich im Kral der Klingenhauer.",al={"wo nachforschen","aufenthaltsort der stacheleber","lage des krals"}},{q="Warum muss der Schamane den Elementen helfen?",a="Die Elemente helfen dem Schamanen, und er soll diese Hilfe erwidern, indem er ihnen gegen jene beisteht, die ihre Macht missbrauchen.",al={"den elementen helfen","elemental aid grund","warum den elementen helfen"}},{q="Welche Informationen werden benötigt?",a="Ihr sollt den Kral der Klingenhauer untersuchen und Informationen über die Pläne der Stacheleber zurückbringen.",al={"was finden","pläne der stacheleber","benötigte informationen"}},{q="Von wem stammt die Bitte?",a="Die Bitte stammt von jemandem, der Euch als Schamanen anspricht und sagt, dass die Elemente Hilfe brauchen.",al={"wer bittet","questgeber","wer braucht hilfe"}}},fp="13,166,21.259.0,31.79.0,33.45.0,46.124.0,27.95.0,22.88.0"}
P.entries["quest:96294"] = {n="A Darker Truth",s="Muln Earthfury bittet Euch, ihm einen auf der Düsteranhöhe gefundenen Brief zu bringen. Er könnte Aufschluss über die dortigen Spinnen geben.",h="Muln Earthfury bittet Euch, ihm einen auf der Düsteranhöhe gefundenen Brief zu bringen.",kw={"a darker truth","broodmother valraxx","zirkel des cenarius","düsteranhöhe","muln earthfury","nachtelfendruide","pact","himmelsschauerplateau","spinnen","wild king"},sec={{t="Ein Brief auf der Düsteranhöhe",b="Auf der Düsteranhöhe habt Ihr herausgefunden, dass die Broodmother eine Nachtelfendruidin in einer entstellten Tiergestalt war. Fragen über die Spinnen und ihren Zweck bleiben offen. Eine Notiz aus ihrer Robe könnte Antworten enthalten, also bringt Ihr sie zu Muln Earthfury auf dem Himmelsschauerplateau."},{t="Mulns Sorge",b="Muln Earthfury findet den Brief beunruhigend. Er spricht von einem „Wild King“ und einem „Pact“, doch Muln weiß nicht, wer oder was sie sind. Er will den Zirkel des Cenarius zu Rate ziehen, findet aber Trost darin, dass diejenige, die die Spinnen kontrollierte, verschwunden ist."}},faq={{q="Wer war die Broodmother?",a="Die Broodmother war eine Nachtelfendruidin, die eine entstellte Tiergestalt angenommen hatte.",al={"broodmother identität","wer ist valraxx","spinne elfe?"}},{q="Was bringe ich Muln Earthfury?",a="Ihr bringt Muln Earthfury den Brief, der aus der Robe von Broodmother Valraxx geborgen wurde.",al={"welcher brief","muln brief","was bringen?"}},{q="Wohin bringe ich den Brief?",a="Ihr bringt den Brief zu Muln Earthfury auf dem Himmelsschauerplateau.",al={"muln aufenthaltsort","wo ist das himmelsschauerplateau","brief ziel"}},{q="Was hält Muln von dem Brief?",a="Muln findet ihn beunruhigend und fragt sich, was die Erwähnungen eines „Wild King“ und eines „Pact“ bedeuten.",al={"mulns reaktion","warum beunruhigend","was steht im brief"}},{q="Wen wird Muln zu Rate ziehen?",a="Muln will mit den Druiden des Zirkels des Cenarius sprechen.",al={"zirkel des cenarius brief","wen wird er fragen","druidenrat?"}}},fp="14,109,21.247.0,14.246.1,24.74.0,34.78.0,27.60.0,34.96.0,22.59.0"}
P.entries["quest:963"] = {n="In ewiger Liebe",s="In Auberdine bittet Cerellean Weißklaue Euch, Anaya Dawnrunners Qualen in Ameth'Aran zu lindern. Seine Trauer währt seit dem Fall der Stadt.",h="In Auberdine bittet Cerellean Weißklaue Euch, Anaya Dawnrunners Qualen in Ameth'Aran zu lindern.",kw={"ameth'aran","anaya dawnrunner","anayas anhänger","auberdine","cerellean weißklaue","dunkelküste","in ewiger liebe","sundering"},ang={["class:Druid"]="Als Druide seht Ihr, welchen persönlichen Preis jene zahlten, die Jahrtausende an der Seite von Shan'do Sturmgrimm schliefen. Cerellean erwachte in einer Welt, die noch immer von uralten Verlusten gezeichnet war.",["faction:Alliance"]="Als Held der Allianz seht Ihr, wie Eure nachtelfischen Verbündeten ihre Trauer über Jahrtausende hinweg tragen, während sie sich an die wache Welt gewöhnen.",["race:NightElf"]="Als Nachtelf der Dunkelküste seht Ihr in Cerelleans Geschichte die bleibenden Narben des Great Sundering und des Falls Eurer uralten Städte."},sec={{t="Ein Schlummer voller Trauer",b="Vor zehntausend Jahren riss der Krieg der Ahnen Kalimdor rund um den Brunnen der Ewigkeit auseinander. Ameth'Aran fiel, und Anaya Dawnrunner ging Cerellean Weißklaue verloren. Von Trauer überwältigt, schloss sich Cerellean Shan'do Malfurion Sturmgrimm im langen Winterschlaf der Druiden an. Er hoffte, die Zeitalter im Smaragdgrünen Traum würden sein Herz beruhigen, doch seine Trauer blieb."},{t="Der Geist von Ameth'Aran",b="Als er erwachte, wanderte Cerellean wie betäubt durch die Dunkelküste. Schließlich gelangte er zu den schwermütigen Ruinen von Ameth'Aran, wo er Anayas gequälten Geist sah. Er kann keine Waffe gegen die Frau erheben, die er liebte. Deshalb bittet er vorbeiziehende Reisende, ihre gepeinigte Gestalt zu vernichten, ihren Anhänger zu bergen und ihrer ruhelosen Seele Frieden zu bringen."},{t="Abschied jenseits des Schleiers",b="Als Anayas Anhänger Auberdine erreicht, erscheint ihr geisterhafter Überrest ein letztes Mal vor Cerellean. Befreit von der Pein, die sie an die Ruinen band, verabschiedet sich Anaya kurz von ihm und verblasst. Am Meer weint der trauernde Druide, findet jedoch bittersüßen Trost."}},faq={{q="Wer ist Cerellean Weißklaue?",a="Cerellean Weißklaue ist ein Nachtelfendruide, der in Auberdine ruht. Nachdem er Anaya vor zehntausend Jahren beim Sundering verloren hatte, begab er sich mit Shan'do Malfurion Sturmgrimm in den langen Winterschlaf der Druiden. Seine Trauer überdauerte die Zeitalter.",al={"cerellean weißklaue","wer vergibt in ewiger liebe","cerelleans geschichte"}},{q="Wer war Anaya Dawnrunner?",a="Anaya Dawnrunner war eine Nachtelfe, die vor dem Great Sundering in Ameth'Aran lebte. Sie starb, als die Stadt nach dem Krieg der Ahnen fiel. Ihr Geist bleibt in den Ruinen gefangen.",al={"anaya dawnrunner","wer ist anaya","anaya dunkelküste"}},{q="Wo befindet sich Anayas Geist?",a="Anayas Geist wandert durch die uralten, von Geistern heimgesuchten Ruinen von Ameth'Aran im Süden der Dunkelküste, östlich der Hauptstraße.",al={"anayas standort","wo ist anaya dawnrunner","anayas anhänger fundort"}},{q="Warum konnte Cerellean Anaya nicht selbst befreien?",a="Cerellean erträgt es nicht, seine Hand gegen Anayas Erscheinung zu erheben oder einen Zauber gegen sie zu wirken. Zehntausend Jahre sind vergangen, doch er kann sie nicht angreifen, während sie leidet.",al={"warum tötet cerellean anaya nicht","warum bittet cerellean um hilfe"}},{q="Was geschah mit Ameth'Aran?",a="Ameth'Aran war eine uralte Siedlung der Nachtelfen, die beim Sundering nach dem Krieg der Ahnen zerstört wurde. In ihren Ruinen an der Dunkelküste verweilen noch immer Geister und arkane Echos.",al={"ameth'arans geschichte","fall von ameth'aran","was ist ameth'aran"}},{q="Was geschieht, wenn Ihr Anayas Anhänger zurückbringt?",a="Ihr bringt Anayas Anhänger zu Cerellean in Auberdine, nachdem Ihr ihren ruhelosen Geist befreit habt. Was darauf folgt, offenbart sich bei Eurer Rückkehr.",al={"anaya quest abgeben","cerelleans ende","in ewiger liebe ende"}}},fx={dc23d6a3={q="Warum möchte Cerellean Weißklaue Anayas Geist befreit wissen?",a="Cerellean glaubte, seine Liebe, Anaya, sei vor Jahrtausenden umgekommen, als Ameth'Aran während des Großen Bruchs zerstört wurde. Die Entdeckung ihres ruhelosen, gequälten Geistes, der durch die Ruinen wandert, brach ihm das Herz. Da er weiß, dass sie an dieses Reich gebunden leidet, erträgt er den Gedanken nicht, dass sie in Qual bleibt, doch er bringt es nicht über sich, selbst Hand an sie zu legen.",al={"warum möchte cerellean das erledigt haben","cerellean motiv","warum anayas geist vernichten"}},ed60ea9d={q="Wozu dient Anayas Anhänger?",a="Anayas Anhänger ist das Andenken, das Cerellean Euch bittet zurückzubringen, nachdem Ihr ihren gequälten Geist in Ameth'Aran befreit habt.",al={"verwendung von anayas anhänger","was bewirkt anayas anhänger","zweck von anayas anhänger"}}},fp="16,134,23.358.0,23.321.0,23.274.1,27.233.0,25.183.0,32.116.0,42.162.0,28.184.0,45.128.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Eisenschmiede Air Rifle",s="Ein an Euch adressiertes Paket wartete bei einem Verwalter, bis Ihr kamt, um es abzuholen. Darin lag eine Replik des Eisenschmiede-Luftgewehrs, hinterlassen von einem Boten, dessen Name unbekannt ist.",h="Ein an Euch adressiertes Paket wartete bei einem Verwalter, bis Ihr kamt, um es abzuholen.",kw={"luftgewehr","eisenschmiede","luftgewehr aus eisenschmiede","vermächtnisbelohnung","geheimnisvolles paket","replik des ironforge-luftgewehrs"},ang={["profession:Engineering"]="Tüftler und Büchsenmacher dürften das aufwendig gearbeitete Schusswaffenmodell zu schätzen wissen. Ein gleichgültiger Bote brachte es, und beinahe wäre es auf dem Meeresgrund gelandet.",["race:Dwarf"]="Das Paket enthält die Replik eines Luftgewehrs aus Eisenschmiede, die den berühmten Schusswaffen und der mechanischen Handwerkskunst von Khaz Modan Ehre erweist."},sec={{t="Ein Paket wartet auf Abholung",b="Der Verwalter lagerte nichts ein und wollte das Paket nicht aufbewahren. Der Bote bestand darauf, dass Ihr es abholen würdet, und eilte davon, bevor der Verwalter ablehnen konnte. Ihr traft kurz bevor die Kiste mit dem Unrat des Abends ins Meer geworfen werden sollte ein."},{t="Zwergische Ingenieurskunst im Kleinformat",b="Im Paket liegt eine Replik des Eisenschmiede-Luftgewehrs, eine Würdigung der Schusswaffenkunst der Zwergenhauptstadt. Zwergische Gebirgsjäger und Scharfschützen tragen tödliche Waffen durch Dun Morogh. Repliken wie diese erinnern an die kunstvoll gearbeiteten Läufe und pneumatischen Mechanismen, die Handwerker aus Eisenschmiede perfektioniert haben."}},faq={{q="Wer hat dieses Paket geschickt?",a="Weder der Bote noch der ursprüngliche Absender hinterließen einen Namen oder eine Erklärung. Laut dem Verwalter hinterließ jemand ein an Euch adressiertes Paket, bestand darauf, dass Ihr es abholen würdet, und verschwand, bevor Fragen gestellt werden konnten.",al={"wer hat das paket geschickt","absender des luftgewehrs","wer hat das gewehr hinterlassen"}},{q="Was wäre beinahe mit dem Paket geschehen?",a="Das Paket wäre beinahe mit dem nächtlichen Müll ins Meer geworfen worden. Der Verwalter sagte, dass er nichts einlagert und unerwünschten Kram regelmäßig ins Meer wirft.",al={"was sollte mit dem paket geschehen","müll im meer","paket weggeworfen"}},{q="Was befindet sich im Paket?",a="Das Paket enthält eine Replik des Eisenschmiede-Luftgewehrs, die für Euch als Würdigung zwergischer Schusswaffenkonstruktion hinterlassen wurde.",al={"was ist im paket","gewehrreplik paketinhalt","paketbelohnung"}},{q="Warum bewahrte der Verwalter das Paket auf?",a="Der Verwalter bewahrt weder Post noch Pakete auf. Der Bote eilte davon, bevor sich eine Gelegenheit bot, die Annahme zu verweigern.",al={"warum wurde es aufbewahrt","post aufbewahren","werden hier pakete aufbewahrt"}},{q="Warum gilt dies als Vermächtnisbelohnung?",a="Ein geheimnisvoller Wohltäter hinterließ an einem Außenposten ein besonderes Paket für einen erfahrenen Abenteurer, wo es bis zu dessen Ankunft auf Abholung wartete.",al={"warum heißt es vermächtnisbelohnung","geschichte der vermächtnisbelohnung","was bedeutet vermächtnis hier"}},{q="Ist die Gewehrreplik eine funktionsfähige Waffe?",a="Das Gewehr ist eine Replik eines Luftgewehrs aus Eisenschmiede, nach dem Vorbild ausgefeilter zwergischer Fernkampfwaffen und weniger eines Kampfgewehrs für die Front.",al={"ist das gewehr eine echte waffe","kann man damit schießen","funktion der replik"}}},fp="42,168,29.255.0,32.291.0,22.195.0,36.168.0,26.103.0,42.125.0,39.132.0,41.142.0"}
P.entries["quest:96390"] = {n="Nip 'Em in the Bud",s="Dunkeleisenspione durchstreifen Dun Morogh, und Erdseher Farsen ruft um Hilfe. Nahe Eisenbands Truppenlager bedroht ihre Anwesenheit die Heimat der Bronzebärte.",h="Dunkeleisenspione durchstreifen Dun Morogh, und Erdseher Farsen ruft um Hilfe.",kw={"dunkeleisenkarte","dunkeleisenspion","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","nip 'em in the bud","underground map"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr beim Aufhalten feindlicher Späher in Dun Morogh, Eisenschmiedes Versorgungslinien und nahe Außenposten vor Sabotage zu schützen.",["race:Dwarf"]="Als Zwerg der Bronzebärte verteidigt Ihr Eure Heimat und begegnet alten Clanfehden, indem Ihr Dunkeleisenspione aus den Bergen Eurer Ahnen vertreibt."},sec={{t="Augen in der Kälte",b="Dunkeleisenspione haben die hohen Pässe und verschneiten Klippen von Dun Morogh überquert. Sie verstecken sich nahe Siedlungen und Ausgrabungen, wo schon wenige Beobachter einen Angriff ankündigen könnten. Erdseher Farsen erkennt die Gefahr und ruft Verteidiger der Allianz auf, sie aufzuspüren, bevor ihre Pläne voranschreiten."},{t="Bedrohung nahe Eisenbands Truppenlager",b="Die Spione sammeln sich nahe Eisenbands Truppenlager im östlichen Dun Morogh. Erdseher Farsen kennt ihre Absichten zunächst nicht. Beim Durchsuchen der Späher findet sich eine Underground Map, die beweist, dass sie mehr vorbereiten als die Beobachtung des Gebiets. Ihre Pläne erstrecken sich auf uralte Geheimnisse unter der Erde, darunter die Halle der Thanen."}},faq={{q="Wer vergibt die Quest Nip 'Em in the Bud?",a="Nachdem Ihr Farsen's Watch abgeschlossen habt, bittet Erdseher Farsen um Hilfe gegen Eindringlinge in Dun Morogh.",al={"questgeber nip 'em in the bud","wer startet nip 'em in the bud","farsen quest"}},{q="Warum sind Dunkeleisenspione in Dun Morogh?",a="Der Dunkeleisenclan schmiedet Pläne gegen seine Vettern, die Bronzebärte. Seine Spione beobachten Siedlungen im östlichen Dun Morogh und graben oder erkunden möglicherweise verschüttete Durchgänge nahe Eisenbands Truppenlager.",al={"warum dunkeleisenspione hier","was machen dunkeleisenzwerge in dun morogh","eisenband dunkeleisenspione"}},{q="Wo befinden sich die Dunkeleisenspione?",a="Die Spione sammeln sich nahe Eisenbands Truppenlager im östlichen Dun Morogh und beobachten es vom verschneiten Randgebiet aus.",al={"standort der spione","wo sind dunkeleisenspione","wo spione finden"}},{q="Was führt zu dieser Aufgabe?",a="Ihr kommt hierher, nachdem Ihr Euch für Farsen's Watch gemeldet habt. Die Verteidigung geht von der Ausschau nach Eindringlingen zur Jagd auf sie über.",al={"vorausgesetzte quest","was kommt vor nip 'em in the bud","nip 'em in the bud vorquest"}},{q="Was wird bei der Jagd auf diese Spione aufgedeckt?",a="Die gefallenen Spione tragen eine Dunkeleisenkarte bei sich. Sie zeigt, dass ihre Pläne unter die Erde reichen, zu Geheimnissen, die mit der Halle der Thanen verbunden sind.",al={"was hinterlassen spione","dunkeleisenkarte beute","folgequest nach nip 'em in the bud"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Zwerg in Dun Morogh, der ungewöhnliche seismische Aktivitäten und Bewegungen feindlicher Clans in den Bergen beobachtet.",al={"wer ist farsen","erdseher farsen hintergrundgeschichte"}}},fx={bdd12e65={q="Warum möchte Erdenrufer Farsen, dass sich um die Dunkeleisenspione gekümmert wird?",a="Erdenrufer Farsen weiß, dass jeder Stützpunkt der Dunkeleisenzwerge in Dun Morogh Gefahr für Eisenschmiede und die umliegenden Lande bedeutet. Obwohl ihre genauen Motive für ihn unklar bleiben, lädt das ungehinderte Agieren von Infiltratoren zu größerer Sabotage oder einem offenen Angriff ein. Er will ihre Präsenz sofort zerschlagen, bevor irgendein Plan, den sie vorbereiten, Fuß fassen kann.",al={"warum will farsen die spione tot sehen","erdenrufer farsen motiv","warum im keim ersticken"}}},fp="18,154,16.267.0,31.310.1,40.98.0,38.177.0,38.99.0,26.113.0,44.122.1,24.127.0"}
P.entries["quest:96391"] = {n="Underground Map",s="Nahe Eisenbands Truppenlager weist die Underground Map auf Kammern unter Eisenschmiede hin. Die von Dunkeleisenspionen erbeutete Karte zeigt mit ihren Runen einen verborgenen Weg, der zu uralten Hallen unter dem Berg vordringt. Ihr bringt sie zu Erdseher Farsen, um zu erkunden, was darunter liegt.",h="Nahe Eisenbands Truppenlager weist die Underground Map auf Kammern unter Eisenschmiede hin.",kw={"dunkeleisenkarte","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","eisenschmiede","underground map"},ang={["class:Shaman"]="Als Schamane könnt Ihr den Windstoß, der Euch zu Erdseher Farsen führt, als Warnung der Elementargeister vernehmen. Sie spüren unnatürliche Grabungen unter Dun Morogh.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass dieser unterirdische Weg unterbunden werden muss, um Eisenschmiede und den nördlichen Stützpfeiler der Allianz zu sichern.",["race:Dwarf"]="Als Zwerg der Bronzebeärte wisst Ihr, dass Dunkeleisentunnel direkt zum Fundament von Eisenschmiede eine schwerwiegende Verletzung der Grenzen der Hauptstadt darstellen."},sec={{t="Ein Plan zur Infiltration",b="Ihr findet das Pergament nahe Eisenbands Truppenlager, nachdem Ihr Euch um die Dunkeleisenspione gekümmert habt. Seine Zeichnungen zeigen ein verschlungenes Labyrinth von Straßen unter der Erde. Raue, gezackte Runen markieren Gänge, die tief unter der Erde verlaufen und unter Eisenschmiede zusammenlaufen. Ihr Verlauf deutet auf eine mögliche Bedrohung unter der Hauptstadt der Bronzebeärte hin, doch die Dunkeleisen-Anmerkungen bleiben unklar."},{t="Flüstern im Wind",b="Als Ihr die grobe Karte studiert, trägt ein unnatürlicher Windstoß das leise Murmeln einer Zwergenstimme heran. Sie drängt zu raschem Handeln und weist Euch zu Erdseher Farsen. Ihr überbringt ihm diese Warnung, wo sie frühe Bewegungen zu uralten, tief unter der Stadt versiegelten Hallen aufdecken und die Zuflucht des Bergkönigreichs bedrohen könnte."}},faq={{q="Woher stammt diese unterirdische Karte?",a="Dunkeleisenspione trugen die Karte bei sich, während sie die Umgebung von Eisenbands Truppenlager in Dun Morogh auskundschafteten. Ihr findet sie bei ihren Spähern in den Ausläufern der Berge.",al={"kartenbeute","wo karte finden","wie underground map erhalten"}},{q="Was zeigt die Karte?",a="Die Karte zeigt ein komplexes Netz unterirdischer Hauptstraßen und Tunnel, die sich durch die Erde schlängeln. Sie laufen unter Eisenschmiede zusammen.",al={"was zeigt die karte","kartendetails","zweck der dunkeleisenkarte"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein zwergischer Erdseher vom Nistgipfel, der mit dem tiefen Gestein und den Berggeistern verbunden ist. Er spürt unnatürliche Bewegungen unter der Erde und braucht die Karte, um den Durchbruch unter Eisenschmiede einzuschätzen.",al={"wo ist farsen","wer ist farsen","erdseher"}},{q="Warum graben die Dunkeleisenzwerge Tunnel unter Eisenschmiede?",a="Die Karte deutet auf einen möglichen Weg unter Eisenschmiede hin, doch ihre Dunkeleisen-Anmerkungen sind noch nicht entziffert. Erdseher Farsen muss sie untersuchen, bevor sich ihr Plan ermitteln lässt.",al={"warum graben dunkeleisenzwerge tunnel","dunkeleisenkomplott dun morogh"}},{q="Wozu führt diese Quest?",a="Die Übergabe der Karte an Erdseher Farsen setzt die Erkundung der Tiefen unter der Stadt in Gang. Sie führt zur Old Eisenschmiede Incursion und öffnet einen Weg zur Halle der Thanen.",al={"fortsetzung von underground map","nächste quest nach underground map"}},{q="In welcher Sprache sind die Runen der Karte verfasst?",a="Die Karte trägt die gezackte Runenschrift der Dunkeleisenzwerge. Wer sie findet, kann nicht sicher sein, was die Anmerkungen besagen.",al={"kartenrunen","sprache der dunkeleisenzwerge"}}},fx={["1c73103d"]={q="Warum muss die Dunkeleisenkarte zu Erdenrufer Farsen gebracht werden?",a="Die Karte zeigt ein alarmierendes Netzwerk von unterirdischen Tunneln und Wegen, die alle direkt unter Eisenschmiede zusammenlaufen. Ihre gezackten Dunkeleisenrunen erfordern eine Übersetzung, und die unheimliche Zwergenstimme, die auf dem Wind getragen wird, macht deutlich, dass Erdenrufer Farsen die mögliche unterirdische Bedrohung sofort untersuchen muss, um das Bergkönigreich vor der Gefahr aus dem Untergrund zu warnen.",al={"warum die karte zu farsen bringen","motiv der dunkeleisenkarte","warum die karte überbringen"}}},fp="15,270,27.360.0,20.309.1,41.148.0,23.127.0,24.205.0,49.168.0,29.182.1,45.115.0"}
P.entries["quest:96392"] = {n="Farsen's Watch",s="Nahe dem Steinbruch Gol'Bolar hält Erdseher Farsen nach Dunkeleisenbewegungen bei Eisenschmiede Ausschau. Der Wildhammer-Schamane leiht Euch seine Weitsicht und offenbart eine Bedrohung, die rasches Handeln erfordert.",h="Nahe dem Steinbruch Gol'Bolar hält Erdseher Farsen nach Dunkeleisenbewegungen bei Eisenschmiede Ausschau.",kw={"nistgipfel","dunkeleisen","dun morogh","erdseher","farsen","weitsicht","gol'bolar","die halle der thanen","wildhammer"},ang={["class:Shaman"]="Als Schamane erlebt Ihr die erdverbundene und spirituelle Sichtweise der Wildhammer-Tradition, die in den zerklüfteten Höhen von Nistgipfel wurzelt.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Dunkeleisenpläne in Dun Morogh aufzudecken und Eisenschmiede sowie die umliegenden Gebirgspässe zu schützen.",["race:Dwarf"]="Als Verteidiger der Bronzebeard hört Ihr eine Warnung von einem Vetter aus Nistgipfel. Sie zeigt, wie unverhohlen die Dunkeleisenzwerge inzwischen in Eurer Heimat auftreten."},sec={{t="Blick über den Kamm",b="Von seinem Posten über dem Steinbruch Gol'Bolar aus beobachtet Farsen die tieferen Lagen von Dun Morogh. Er kam von den zerklüfteten Höhen von Nistgipfel nach Süden und brachte das spirituelle Gespür eines Wildhammers mit. Die alten Künste seines Clans lassen ihn unterirdische Erschütterungen spüren und plötzliche Bewegungen an den Berghängen erkennen."},{t="Eine geliehene Vision",b="Farsen leiht Euch seine Weitsicht, eine schamanische Gabe, die den Blick über große Entfernungen trägt. Durch sie erkennt Ihr Gefahren jenseits von Troggs und wilden Bestien. Dunkeleisenzwerge sind nahe an das Industriezentrum von Eisenschmiede herangerückt und verschanzen sich dort. Ihrem Brückenkopf muss Einhalt geboten werden, bevor er sich festigt."}},faq={{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Wildhammer-Zwerg aus Nistgipfel im Hinterland, der Dun Morogh besucht. Seine schamanische Gabe lässt ihn Störungen im Land spüren und Bedrohungen aus der Ferne beobachten.",al={"erdseher farsen","wer ist farsen","farsen wildhammer"}},{q="Wo findet diese Wache statt?",a="Farsen hält oberhalb des Steinbruchs Gol'Bolar Wache, einer Bergbau-Ausgrabungsstätte der Bronzebeard im Osten von Dun Morogh.",al={"farsen standort","wo ist farsen","aussichtspunkt über dem steinbruch"}},{q="Welche Bedrohung enthüllt Farsen?",a="Farsens Weitsicht enthüllt einen nahen Brückenkopf feindlicher Dunkeleisenzwerge, eine akute Gefahr für die Region.",al={"was zeigt die weitsicht","dunkeleisenbedrohung","farsens vision"}},{q="Wie hängt dies mit der Halle der Thanen zusammen?",a="Die Untersuchung der Dunkeleisenpräsenz, die während Farsens Wache sichtbar wird, beginnt die Aufgabenreihe für jene, die Einlass in die Halle der Thanen suchen.",al={"zugang zur halle der thanen","questreihe der halle der thanen"}},{q="Warum beteiligt sich ein Wildhammer-Zwerg an der Verteidigung von Dun Morogh?",a="Die Wildhammer sind im Hinterland beheimatet, doch Verwandtschaft und ihre gemeinsame Feindschaft gegenüber den Dunkeleisenzwergen führen Reisende wie Farsen bisweilen in die angestammten Bronzebeard-Lande von Dun Morogh.",al={"warum ist ein wildhammer hier","nistgipfel zwerg dun morogh"}},{q="Was folgt unmittelbar auf den Abschluss von Farsen's Watch?",a="Nachdem Ihr durch Farsens Vision die Infiltration der Dunkeleisenzwerge gesehen habt, drängt er Euch mit 'Nip 'Em in the Bud', den vorrückenden Feind zurückzuschlagen.",al={"nächste quest","was folgt auf farsen's watch","nip em in the bud"}}},fx={["73fc96dc"]={q="Warum möchte Erdenrufer Farsen, dass dies getan wird?",a="Während er von Nistgipfel durch Dun Morogh reiste, entdeckte Erdenrufer Farsen Anzeichen von Aggressionen der Dunkeleisenzwerge, die nahe dem Steinbruch Gol'Bolar überhandnahmen. Bevor er handelt oder Alarm schlägt, möchte der Schamane, dass Ihr die aufkeimende Gefahr aus erster Hand durch seine hellseherische Magie miterlebt, um sicherzustellen, dass die Verteidiger von Eisenschmiede das wahre Ausmaß der feindlichen Infiltration erfassen, bevor sie außer Kontrolle gerät.",al={"warum farsens wache","farsens motiv","warum will farsen, dass ich nachsehe"}}},fp="14,184,21.288.0,17.291.0,24.181.0,33.98.0,31.105.0,44.136.0,59.184.0,52.143.0"}
P.entries["quest:96393"] = {n="Old Eisenschmiede Incursion",s="Unter Eisenschmiede schickt Euch Earthseer Farsen zum letzten Teil der Untersuchung in die Halle der Thanen. Dort stellt Ihr Euch der Bedrohung durch die Dunkeleisen und erstattet König Magni Bronzebart Bericht.",h="Unter Eisenschmiede schickt Euch Earthseer Farsen zum letzten Teil der Untersuchung in die Halle der Thanen.",kw={"dunkeleisen","dirgehammer","farsen","vorstoß","eisenschmiede","kharanos","magni","thanen"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, einen Vorstoß aufzuhalten, der einen verheerenden Überraschungsangriff auf die wichtigste Festung Eurer Fraktion in den Östlichen Königreichen androht.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Dunkeleiseneindringlinge in den vergessenen Gewölben unter dem High Seat in Eure angestammte Festung eingedrungen sind."},sec={{t="Vorstoß in die Gewölbe",b="Die unterirdische Karte offenbart die Bewegungen der Dunkeleisen, und Earthseer Farsen erkennt den Drahtzieher hinter dem Eindringen. Der Eingang zur Halle der Thanen liegt tief in den uralten steinernen Hallen der Altstadt von Eisenschmiede. Während sich die Oberstadt um Angelegenheiten an der Oberfläche kümmert, schleichen Truppen der Dunkeleisen in ruhende Höhlen unter dem Königreich."},{t="Befehlshaber Durgen Dirgehammer",b="Earthseer Farsen übersetzt erbeutete Dokumente der Dunkeleisen und nennt den Befehlshaber: Durgen Dirgehammer. Tief in den unteren Gewölben bedroht Durgen das Herz des Bergkönigreichs der Bronzebeard. Erreicht ihn, streckt ihn nieder und bringt seinen abgetrennten Kopf hinauf zu König Magni Bronzebart."},{t="Audienz beim König",b="Durgen Dirgehammers Kopf bestätigt König Magni Bronzebart die Bedrohung durch die Dunkeleisen unter den uralten Wurzeln der Stadt. Ihr bringt einen Beweis des Sieges und einen persönlichen Gruß von Farsen, Magnis altem Freund. Die Untersuchung endet damit, dass Magni weiß, was in der Tiefe lauert."}},faq={{q="Was ist Old Eisenschmiede Incursion?",a="Earthseer Farsen schickt Euch in die Halle der Thanen unter der Altstadt von Eisenschmiede, um Euch dem Dunkeleisenbefehlshaber Durgen Dirgehammer zu stellen. Dies ist der letzte Abschnitt einer Untersuchung der Aktivitäten der Dunkeleisen unter Dun Morogh.",al={"old ironforge incursion quest","durgen dirgehammer quest"}},{q="Wo findet diese Quest statt?",a="Ihr betretet die Halle der Thanen, eine uralte Kammer tief im Grundgestein unter der Altstadt von Eisenschmiede und der Berghauptstadt.",al={"wo ist die halle der thanen","halle der thanen standort"}},{q="Wer ist Durgen Dirgehammer?",a="Durgen Dirgehammer befehligt den Vorstoß der Dunkeleisen in die Halle der Thanen unter der Altstadt von Eisenschmiede. Earthseer Farsen erfuhr seinen Namen aus geborgenen Dokumenten der Dunkeleisen.",al={"wer ist dirgehammer","durgen dirgehammer"}},{q="Wer vergibt die Quest, und bei wem wird sie abgegeben?",a="Nachdem Ihr die Underground Map geborgen habt, schickt Euch Earthseer Farsen zu König Magni Bronzebart in Eisenschmiede.",al={"questgeber old ironforge incursion","wer gibt old ironforge incursion ab"}},{q="Wie beginne ich die Questreihe, die hierherführt?",a="Beginnt mit A Visitor to Dun Morogh, angeboten von Beldin Stahlrost außerhalb von Kharanos in Dun Morogh.",al={"wie beginnt die quest zur halle der thanen","visitor to dun morogh start"}},{q="Welche Verbindung besteht zwischen Earthseer Farsen und König Magni?",a="Earthseer Farsen betrachtet sich als alten Freund von König Magni Bronzebart. Er bittet Euch, seine persönlichen Grüße auszurichten, wenn Ihr Durgen Dirgehammers Kopf im Thronsaal vorzeigt.",al={"farsen und magni","earthseer farsen hintergrundgeschichte"}}},fx={bdae81a8={q="Warum möchte Erdenrufer Farsen, dass Durgen Dirgehammer getötet wird?",a="Farsen deckte feindliche Bewegungen unter dem Berg auf und entschlüsselte Befehle, die Durgen Dirgehammer als den Kommandanten auswiesen, der den Einfall in die Altstadt von Eisenschmiede anführt. Die Präsenz der Dunkeleisen in der Halle der Thanen bedroht die Zwergenhauptstadt direkt von unten. Indem er Euch schickt, um ihren Anführer niederzustrecken, zielt Farsen darauf ab, den Angriff zu zerschlagen, bevor die Dunkeleisen sich verschanzen können, während er gleichzeitig einen unbestreitbaren Beweis für die Bedrohung direkt an König Magni Bronzebart sendet.",al={"farsens motiv","warum durgen dirgehammer töten","warum schickt euch farsen"}},["664606f0"]={q="Wozu dient Durgen Dirgehammers Kopf?",a="Ihr benötigt Durgen Dirgehammers Kopf als absoluten Beweis für König Magni Bronzebart, dass der Kommandant des unterirdischen Angriffs unschädlich gemacht wurde. Die direkte Übergabe der grausamen Trophäe an den Thronsaal bestätigt, dass die feindliche Dunkeleisen-Angriffstruppe in der Halle der Thanen ihren Anführer verloren hat, und überbringt Erdenrufer Farsens persönliche Warnung an den König.",al={"nutzen von durgen dirgehammers kopf","warum durgens kopf mitnehmen","kopf von durgen dirgehammer"}}},fp="23,182,20.333.0,18.279.1,22.260.1,32.210.0,33.116.0,26.168.0,41.105.0,50.96.0,63.179.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="Unter der Halle der Thanen beunruhigen rastlose Geister die Krypten, in denen Generationen verstorbener Zwerge ruhen. Die Pfleger fürchten sich, die Gewölbe zu betreten, und die Unruhe hat den Geist von Ambossar erreicht.",h="Unter der Halle der Thanen beunruhigen rastlose Geister die Krypten, in denen Generationen verstorbener...",kw={"ambossar","zwergengräber","zwergengeister","enraged apparitions","geister","die halle der thanen","geist von ambossar","the restless dead","tormented souls"},ang={["class:Priest"]="Als Priester seid Ihr dazu berufen, mit Seelen Zwiesprache zu halten und rastlose Tote zu friedlicher Ruhe zu führen, wenn Geister in Qual oder Zorn verharren.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Ahnengruften unter Eisenschmiede zu sichern, damit die Pfleger ihre heiligen Pflichten ohne Furcht vor rachsüchtigen Erscheinungen erfüllen können.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass in der Halle der Thanen die geehrten Toten und Ahnen Eures Volkes ruhen. Ihr plötzliches und heftiges Erwachen erschüttert das Herz des zwergischen Erbes."},sec={{t="Unruhe in den tiefen Gewölben",b="Generationen geehrter Zwerge ruhen in den Ahnengruften unter der Halle der Thanen. Ihre Geister schlafen gewöhnlich friedlich, doch etwas Unsichtbares hat sie heftig aufgewühlt. Seltsame Geräusche steigen aus den unteren Gewölben auf und verängstigen die Pfleger. Sie weigern sich, diese Kammern zu betreten oder ihren Pflichten nachzukommen, bis die Ordnung wiederhergestellt ist. Nun werden Abenteurer gerufen, um die aufgewühlten Seelen zu besänftigen."},{t="Die Ahnen besänftigen",b="Die Geister in der Halle der Thanen haben einen leichten Schlaf. Was auch immer die unteren Grüfte störte, weckte Enraged Apparitions und Tormented Souls und verwandelte heiligen Boden in einen gefährlichen Spukort. Auch der verehrte Geist von Ambossar ist erwacht. Eine respektvolle, doch feste Hand muss den Zorn der Ahnen bezwingen und den Frieden in den Katakomben wiederherstellen."}},faq={{q="Worum geht es in der Quest The Restless Dead?",a="Eine unbekannte Störung hat die Geister in den Krypten unter der Halle der Thanen aufgewühlt. Die Pfleger fürchten sich, sie zu betreten, solange die Erscheinungen aufgebracht sind.",al={"was ist the restless dead","was ist diese quest","questüberblick restless dead"}},{q="Warum sind die Geister erwacht?",a="Eine unbekannte Störung in den tiefen Gewölben hat die dort bestatteten Toten geweckt. Die Geister in der Halle der Thanen haben einen leichten Schlaf, und was auch immer in den Grüften geschah, versetzte sie in Zorn und Qual.",al={"warum sind die geister zornig","wer hat die grüfte gestört","warum sind die erscheinungen wach"}},{q="Wo ereignet sich diese Störung?",a="Die Störung ereignet sich in den Krypten und Gewölben unter der Halle der Thanen in Eisenschmiede, einer Ruhestätte der Ahnen, in der uralte Zwergengeister bestattet sind.",al={"wo ist die halle der thanen","wo erscheinen ruhelose tote","halle der thanen standort"}},{q="Wer ist der Geist von Ambossar?",a="Ambossar ist ein uralter und bedeutender Geist, der in den tiefen Grüften der Halle der Thanen ruht. Dieser große Geist erwachte zusammen mit geringeren Erscheinungen und muss zu friedlicher Ruhe zurückfinden.",al={"wer ist der geist von ambossar","geist von ambossar hintergrundgeschichte","wer ist ambossars geist"}},{q="Warum brauchen die Pfleger die Hilfe eines Abenteurers?",a="Die Pfleger kümmern sich um die Krypten und verrichten ihre regelmäßigen Pflichten in der Halle der Thanen. Zornige Geister durchstreifen die Hallen, weshalb die Pfleger sich weigern, die unteren Gewölbe zu betreten, bis die Gefahr vorüber ist.",al={"wer sind die pfleger","warum brauchen die pfleger hilfe","pfleger halle der thanen"}},{q="Welche Geister suchen die Halle der Thanen heim?",a="Enraged Apparitions, Tormented Souls und der große Geist von Ambossar suchen die aufgewühlten Gewölbe heim. Sie alle wurden aufgeschreckt und halten nun angriffslustig Wache in den Grabkammern.",al={"welche arten von geistern sind dort unten","erscheinungen in der halle der thanen","arten ruheloser toter"}}},fp="17,207,30.381.0,22.328.1,38.153.0,30.187.0,39.152.0,30.182.0,45.190.0,38.169.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="In der Halle der Thanen wird Faldrim Ambossars Geist noch immer von einem alten Groll geplagt. Sein geisterhafter Diener bittet Reisende, ihm Frieden zu bringen.",h="In der Halle der Thanen wird Faldrim Ambossars Geist noch immer von einem alten Groll geplagt.",kw={"an ancient grudge","ambossar","zwergengeist","faldrim anvilmar","geisterhafter diener","die halle der thanen","rastloser geist","thane"},ang={["class:Paladin"]="Als Paladin übernehmt Ihr die ernste Pflicht, den leidenden Toten Frieden zu bringen.",["class:Priest"]="Als Priester wisst Ihr, dass anhaltender Groll und ungesühnter Kummer einen Geist an die stoffliche Welt binden können, lange nachdem der Körper zu Staub zerfallen ist.",["race:Dwarf"]="Als Zwerg seht Ihr eine ernüchternde Mahnung, dass ein uralter Groll selbst den Tod überdauern kann."},sec={{t="Eine Bitte aus dem Grab",b="Ein geisterhafter Diener verweilt in der Halle der Thanen, wo Faldrim Anvilmar einst herrschte. Der Geist kann kaum durch den Schleier zwischen den Lebenden und den Toten sprechen. Er bittet Euch, den rastlosen Geist seines Herrn zu besänftigen. Er sucht Frieden für ihn, nicht Freiheit für sich selbst."},{t="Die Last der Vergangenheit",b="Faldrim Anvilmar bleibt durch einen uralten Groll an die stoffliche Welt gebunden. Sein Geist ist aufgewühlt und feindselig. Er kann keine Ruhe finden, bis ihm jemand gewaltsam Erlösung verschafft."}},faq={{q="Wer ist Faldrim Anvilmar?",a="Faldrim Anvilmar war ein Zwergenthane, dessen rastloser Geist die Halle der Thanen heimsucht. Sein Geisterhafter Diener sagt, ein uralter Groll verzehre ihn und lasse ihn keine Ruhe finden.",al={"faldrim anvilmar hintergrund","wer ist faldrim","thane ambossar"}},{q="Wo befindet sich die Halle der Thanen?",a="Die Halle der Thanen liegt in Höhlen unter der Altstadt von Eisenschmiede, innerhalb der Zwergenhauptstadt Eisenschmiede.",al={"halle der thanen standort","wo ist die halle der thanen","halle der thanen eingang"}},{q="Warum ist der Geist von Faldrim Anvilmar feindselig?",a="Faldrim Ambossars Geist ist feindselig, weil ihn ein uralter Groll verzehrt. Der Geisterhafte Diener sagt, dieser Groll lasse den ehemaligen Thanen keine Ruhe finden.",al={"warum ist faldrim zornig","warum greift der thane an","an ancient grudge erklärung"}},{q="Wer vergibt die Quest An Ancient Grudge?",a="Ein Geisterhafter Diener in der Halle der Thanen bittet Euch, seinem ehemaligen Herrn Frieden zu bringen.",al={"wer startet an ancient grudge","geisterhafter diener quest","questgeber"}},{q="Was müsst Ihr tun, um die Quest abzuschließen?",a="Ihr stellt Euch Faldrim Ambossars Geist in der Halle der Thanen und besiegt ihn im Kampf, um ihn von seinen Qualen zu erlösen. Dann erstattet Ihr dem Geisterhaften Diener Bericht.",al={"wie an ancient grudge abschließen","faldrim zur ruhe betten","an ancient grudge questziel"}},{q="Hat Faldrim eine Verbindung zum Ort Ambossar?",a="Niemand weiß, ob Faldrim Anvilmar eine Verbindung zum Ort Ambossar im Coldridgetal hat. Sie teilen einen Namen, doch seine Familie und jede Verbindung zum Ort sind unbekannt.",al={"stammt faldrim aus ambossar","ambossar coldridgetal verbindung","familie ambossar"}}},fp="17,147,21.261.0,22.169.1,24.167.0,36.98.0,45.151.0,38.91.0,39.160.0,43.164.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="In der Halle der Thanen dringen Dunkeleisenzwerge in die Gewölbe ein, während Thom darin festsitzt. Der nervöse Gnom bittet Euch, die verstreuten zwergischen Relikte zu sammeln, bevor die Eindringlinge sie erreichen.",h="In der Halle der Thanen dringen Dunkeleisenzwerge in die Gewölbe ein, während Thom darin festsitzt.",kw={"dunkeleisen","dwarven heirlooms","gnom","die halle der thanen","important heirlooms","maulwurfmaschine","thom","gewölbe"},ang={["class:Rogue"]="Als Schurke könnt Ihr Thoms Behauptung durchschauen, er sei in den Gewölben auf Patrouille gewesen. Er ist ein Plünderer, den eine unterirdische Invasion überrascht hat.",["race:Dwarf"]="Als Zwerg zweifelt Ihr vielleicht an Thoms plötzlichem Interesse an den Relikten der Ahnen, wenn er sich ständig verplappert und von Beute und Wertschätzungen spricht.",["race:Gnome"]="Für Euch als Gnom zeigt Thoms plumpe Ausrede, wie Neugier sich auf wertvolle Relikte richten kann."},sec={{t="Ärger in den Gewölben",b="Thom ist ein Gnom, der in der Halle der Thanen festsitzt, als Dunkeleisenzwerge sich in Maulwurfmaschinen nach oben graben. Er kann die Gewölbe nicht allein sichern und bittet deshalb vorbeikommende Abenteurer, die von Feinden besetzte Ausgrabungsstätte zu betreten. Die zwergischen Relikte liegen verstreut in den Kammern. Die Eindringlinge könnten sie an sich reißen oder zerstören."},{t="Kulturerhalt oder lukrative Plünderung?",b="Thom sagt, er sei auf Patrouille gewesen und wolle die Relikte zu ihrer Bewahrung katalogisieren. Doch dabei verplappert er sich und spricht von unschätzbarer Beute und davon, den Fang zu schätzen. Er bezahlt Euch gut dafür, dass Ihr Euch der Gefahr stellt, doch ob die Schätze ein Museum oder eine Auktion erreichen, bleibt unklar."}},faq={{q="Wer ist Thom?",a="Thom ist ein nervöser Gnom nahe den Gewölben, der um Hilfe bei der Bergung von Relikten bittet. Seine Versprecher über Beute und Wertschätzungen lassen vermuten, dass ihm Plündergut wichtiger ist als die Sicherheit der Gewölbe.",al={"wer ist der questgeber","wer ist thom","questgeber"}},{q="Was ist die Halle der Thanen?",a="Die Halle der Thanen ist ein unterirdisches zwergisches Gewölbe, in dem uralte kulturelle Relikte und Erbstücke lagern. Streitkräfte der Dunkeleisenzwerge sind dort eingedrungen.",al={"was ist die halle der thanen","wo ist die halle der thanen"}},{q="Warum sind Dunkeleisenzwerge in den Gewölben?",a="Dunkeleisenzwerge haben sich in Maulwurfmaschinen von unten in die Gewölbe gegraben. Ihr Ziel ist unbekannt.",al={"warum sind dunkeleisenzwerge dort","maulwurfmaschinen der dunkeleisenzwerge"}},{q="Gibt Thom die Erbstücke wirklich zurück?",a="Thom sagt, er werde die Relikte an Ehrenplätze zurückbringen, doch seine Worte wecken Zweifel. Er nennt Herumlungern Patrouillieren und Katalogisieren Wertschätzung und spricht von Beute und einem Fang.",al={"lügt thom","stiehlt thom","thom vertrauenswürdig"}},{q="Was sind die Dwarven Heirlooms?",a="Die Dwarven Heirlooms sind uralte kulturelle Relikte, die in der Halle der Thanen aufbewahrt werden. Historiker schätzen sie, während Opportunisten wie Thom darin wertvolle Beute sehen.",al={"was sind die erbstücke","dwarven heirlooms hintergrund"}},{q="Warum kann Thom die Erbstücke nicht selbst bergen?",a="Maulwurfmaschinen der Dunkeleisenzwerge überraschten Thom, als er in den Gewölben herumlungerte. Ohne den Schutz eines Abenteurers kann er die Relikte nicht gefahrlos einsammeln.",al={"warum braucht thom hilfe","warum thom helfen"}}},fp="19,189,21.287.0,43.264.1,12.166.0,27.132.0,40.97.0,39.165.0,31.151.0,46.152.0"}
P.entries["quest:96408"] = {n="A Visitor to Dun Morogh",s="Beldin Stahlrost schickt Euch, um herauszufinden, wer über dem Steinbruch Gol'Bolar ein Feuer entzündet hat. Das Lager überblickt die Ausgrabung, und die Zwerge fürchten, sein Besucher könnte ihnen schaden wollen.",h="Beldin Stahlrost schickt Euch, um herauszufinden, wer über dem Steinbruch Gol'Bolar ein Feuer entzündet hat.",kw={"beldin stahlrost","dun morogh","earthseer farsen","farsen's watch","steinbruch gol'bolar","die halle der thanen","kharanos","besucher"},ang={["class:Shaman"]="Als Schamane begegnet Ihr Earthseer Farsen, dessen Zwiesprache mit den Steinen der Berge in Dun Moroghs verschneitem Hochland selten ist.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr den Gebirgsjägern vor Kharanos, die Nachschubwege und Steinbrucharbeiter vor unvorhergesehenen Bedrohungen zu schützen.",["race:Dwarf"]="Als Bronzebeard-Zwerg wisst Ihr, warum die Gebirgsjäger Fremde über großen Abbaustätten wie Gol'Bolar beobachten. Sie bewachen die Grenzen von Khaz Modan."},sec={{t="Eine Rauchsäule auf den Höhen",b="Hoch auf den verschneiten Bergkämmen östlich von Kharanos brennt über dem Steinbruch das Lagerfeuer eines Fremden. Das unbekannte Feuer beunruhigt die Bewohner von Kharanos. Dort halten die Gebirgsjäger auf den Höhen nach Gefahren Ausschau."},{t="Begegnung mit dem Earthseer",b="Earthseer Farsen hat auf den Höhen über dem Steinbruch Gol'Bolar sein Lager aufgeschlagen. Er ist ein Mystiker mit einer tiefen Bindung zur Erde, kein plündernder Trogg oder feindlicher Spion. Seine Wacht führt ihn zu Unruhen unter Khaz Modan und zum Geheimnis der Halle der Thanen."}},faq={{q="Wer schickt Euch, den Besucher zu erkunden?",a="Beldin Stahlrost vor Kharanos bittet Euch, der Sache nachzugehen, nachdem Gebirgsjäger ein unbekanntes Feuer in den Hügeln gemeldet haben.",al={"wer vergibt diese quest","questgeber","beldin stahlrost quest"}},{q="Wo liegt das geheimnisvolle Lager?",a="Das Lagerfeuer brennt hoch auf den verschneiten Bergkämmen östlich von Kharanos, über dem Steinbruch Gol'Bolar.",al={"lagerstandort","wo ist der besucher","aufenthaltsort des besuchers"}},{q="Wer ist der Besucher über dem Steinbruch?",a="Earthseer Farsen ist der Besucher, der auf den Höhen über dem Steinbruch lagert und über ihn wacht.",al={"wer ist farsen","wer ist der besucher","earthseer farsen"}},{q="Warum misstrauten die Zwerge dem Lagerfeuer?",a="Die Zwerge misstrauen dem unbekannten Lager, weil es den Steinbruch Gol'Bolar überblickt, einen wichtigen Betrieb, der bereits durch örtliche Troggs unter Druck steht. Sie fürchten, dass Späher oder feindliche Streitkräfte ihre Bewegungen beobachten könnten.",al={"warum misstrauisch","warum nachforschen","warum werde ich geschickt"}},{q="Wozu führt diese Quest?",a="Ein Gespräch mit Earthseer Farsen führt zu Farsen's Watch und beginnt die Zugangsquestreihe für die Halle der Thanen.",al={"what comes next","folgequest","halle der thanen einstieg"}},{q="Müsst Ihr den Fremden im Lager bekämpfen?",a="Nein. Beldin Stahlrost warnt Euch, auf Gewalt vorbereitet zu sein, doch Earthseer Farsen ist ein friedlicher Beobachter, der bereit ist, mit Euch zu sprechen.",al={"ist der besucher feindselig","muss ich den besucher töten","kampf gegen den besucher"}}},fx={["3b0d76fb"]={q="Warum bittet Beldin Stahlrost einen Abenteurer und nicht die Gebirgsjäger?",a="Die lokalen Gebirgsjäger entdeckten das Lagerfeuer am Hang aus der Ferne, aber ihre Reihen sind ausgedünnt, da sie Straßen, Siedlungen und Steinbruchbetriebe vor Troggs und wilden Bestien schützen müssen. Da das Feuer wahrscheinlich harmlos ist, verlässt sich Beldin auf einen fähigen Reisenden, der Kharanos passiert, um schnell den Grat zu erkunden, anstatt Wachen vom aktiven Dienst abzuziehen.",al={"warum mich schicken","warum keine wachen schicken","beldin stahlrost warum ich"}}},fp="23,167,28.196.0,21.242.1,41.119.0,41.85.0,42.89.1,48.207.0,31.102.1,46.135.1"}
P.entries["quest:965"] = {n="Der Turm von Althalaxx",s="Nördlich von Auberdine fürchtet Schildwache Elissa Sternenhauch Unheil bei einer uralten Ruine. Sie schickte Balthule Schattenhieb, um den Turm von Althalaxx zu beobachten, doch sein Bericht ist ausgeblieben.",h="Nördlich von Auberdine fürchtet Schildwache Elissa Sternenhauch Unheil bei einer uralten Ruine.",kw={"althalaxx","auberdine","balthule schattenhieb","dunkelküste","elissa sternenhauch","späher","schildwache","turm"},ang={["faction:Alliance"]="Als Reisender der Allianz seid Ihr auf Auberdine als wichtigsten Zugang der Allianz zum nördlichen Kalimdor angewiesen. Die umliegenden Straßen und Grenzen müssen geschützt werden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Ruinen von Althalaxx an die gefallenen highborne des alten Kalimdor erinnern. Verderbnis schwärt in ihren Steinen, und Auberdine davor zu schützen, ist eine unerlässliche Pflicht der Schildwachen."},sec={{t="Ein vermisster Späher",b="Schildwache Elissa Sternenhauch hält nach Gefahren rund um Auberdine Ausschau. Verdächtige Aktivitäten nahe dem Turm von Althalaxx im Norden der Dunkelküste erregten ihre Aufmerksamkeit, also schickte sie Balthule Schattenhieb, um die uralte Ruine zu beobachten. Tage sind ohne Nachricht vergangen. Elissa bittet Euch, nach Norden zu reisen, Balthule zu finden und sicherzustellen, dass er kein vorzeitiges Ende gefunden hat."},{t="Die Ruine im Blick",b="Die Straße von Auberdine nach Norden führt an uralten Kaldorei-Ruinen vorbei und überquert den Klippenquell, bevor sie den Turm erreicht. Balthule hat seinen ersten Beobachtungsposten überlebt, konnte jedoch keine Nachricht nach Auberdine schicken. Ihr findet ihn in den umliegenden Wäldern. Dort bestätigt er Elissas Befürchtungen: Im Inneren des bröckelnden Steinturms gehen düstere und beunruhigende Dinge vor sich."}},faq={{q="Wer ist Schildwache Elissa Sternenhauch?",a="Schildwache Elissa Sternenhauch ist eine nachtelﬁsche Schildwache, die in Auberdine stationiert ist. Sie schützt die Siedlung vor Gefahren aus der gesamten Dunkelküste und hält nach Bedrohungen wie dem Turm von Althalaxx Ausschau.",al={"elissa sternenhauch","wer vergibt die quest","questgeber auberdine"}},{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist der Späher, den Schildwache Elissa Sternenhauch aussandte, um seltsame Aktivitäten rund um den Turm von Althalaxx zu beobachten. Er hält außerhalb der Ruine nach Anzeichen feindlicher Kräfte Ausschau.",al={"balthule","wer ist der späher","schattenhieb"}},{q="Wo befindet sich der Turm von Althalaxx?",a="Der Turm von Althalaxx steht im Nordosten der Dunkelküste. Geht von Auberdine aus nach Osten und folgt der Straße nach Norden an Bashal'Aran vorbei, dann überquert die Brücke über den Klippenquell, bis der Turm in Sicht kommt.",al={"standort turm von althalaxx","wo ist der turm","wie althalaxx finden"}},{q="Warum wurde überhaupt ein Späher zum Turm geschickt?",a="Elissa schickte Balthule, um seltsame Aktivitäten rund um den Turm von Althalaxx zu beobachten und damit ihrer Pflicht nachzukommen, Auberdine zu schützen.",al={"warum den turm beobachten","was stimmt bei althalaxx nicht","warum wurde balthule geschickt"}},{q="Warum ist Balthule nicht nach Auberdine zurückgekehrt?",a="Elissa hat Balthules Bericht nicht erhalten und bittet Euch deshalb, nach ihm zu sehen. Balthule kann seine Lage erklären, wenn Ihr ihn findet.",al={"warum wird balthule vermisst","ist balthule gefangen","warum blieb balthule"}},{q="Geht diese Questreihe weiter?",a="Ja. Wenn Ihr Balthule Schattenhieb findet, beginnt eine mehrteilige Untersuchung der dunklen Mächte, die den Turm von Althalaxx besetzen, und ihrer Absichten in der Dunkelküste.",al={"ist das eine questreihe","welche quest kommt als nächstes","althalaxx questreihe"}}},fx={["895f5562"]={q="Warum möchte Schildwache Elissa Sternenhauch, dass dies getan wird?",a="Als eine Schildwache, die mit der Verteidigung von Auberdine betraut ist, ist Elissa Sternenhauch dafür verantwortlich, die Dunkelküste vor eindringenden Bedrohungen zu schützen. Sie sandte Balthule Schattenhieb aus, um verdächtige Vorfälle nahe dem Turm von Althalaxx zu untersuchen, aber er ist längst überfällig. Da sie fürchtet, dass er in unerwartete Gefahr geraten ist, braucht sie jemanden, der ihn aufspürt und seine Sicherheit bestätigt.",al={"warum balthule finden","elissa sternenhauch motiv","warum mich zum turm von althalaxx schicken"}}},fp="22,173,23.345.0,18.352.1,34.188.0,29.184.0,40.211.0,53.118.0,42.129.0,31.156.0"}
P.entries["quest:966"] = {n="Der Turm von Althalaxx",s="Hexenmeister versammeln sich am Turm von Althalaxx im Norden der Dunkelküste und ziehen Balthule Schattenhiebs wachsamen Blick auf sich. Er bittet Reisende, Pergamentfetzen von den Fanatikern zu beschaffen, die vor den Ruinen lagern, um herauszufinden, wer sie sind und wonach sie suchen.",h="Hexenmeister versammeln sich am Turm von Althalaxx im Norden der Dunkelküste und ziehen Balthule...",kw={"althalaxx","auberdine","balthule","dunkler strang","dunkelküste","delgren","fanatiker","pergament","läuterer","schattenhieb","hexenmeister"},ang={["class:Paladin"]="Als Paladin könnt Ihr Delgren den Läuterer bei seinem Kreuzzug gegen Teufelsmagie und dämonische Verderbnis unterstützen, indem Ihr helft, einen finsteren Kult im Norden der Dunkelküste aufzudecken.",["class:Warlock"]="Als Hexenmeister könnt Ihr sehen, wie Zirkel außerhalb der Kontrolle von Allianz und Horde uralte Ruinen für ihre Beschwörungen in Besitz nehmen.",["race:NightElf"]="Als Nachtelf seht Ihr in der Entweihung des Turms von Althalaxx durch die finsteren Kultisten eine weitere Schändung des uralten elfischen Erbes an Kalimdors Küsten."},sec={{t="Augen im seichten Wasser",b="Balthule Schattenhieb wacht über die neblige Küste im Norden der Dunkelküste und behält den uralten Turm von Althalaxx im Blick. Auberdine hat ihn entsandt, um die Ruine zu beobachten und Delgren den Läuterer zu warnen, falls die Gefahr wächst. Doch wenn er seinen Posten für einen Bericht verlässt, könnten ihm die finsteren Zauberwirker zwischen den Steinen aus dem Blick geraten. Deshalb bittet Balthule vorbeiziehende Reisende, die Lager rund um den Turm auszukundschaften."},{t="Dem Kult auf der Spur",b="Die niederen Anhänger auf dem Ruinengelände tragen Fetzen von Schriftrollen und Notizen bei sich. Mehrere abgenutzte Pergamente verraten Balthule ihren Namen: der Kult des dunklen Strangs. Er hat noch nie von der Sekte gehört und weiß nun, dass hier mehr als eine Bande abtrünniger Hexenmeister am Werk ist. Delgren muss sofort gewarnt werden."}},faq={{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist ein Späher der Allianz, der an der Straße nahe dem Turm von Althalaxx im Norden der Dunkelküste stationiert ist. Die Anführer von Auberdine haben ihn entsandt, um die verdächtigen Zusammenkünfte zu beobachten und Delgren dem Läuterer Bericht zu erstatten.",al={"balthule schattenhieb hintergrund","wer ist balthule","balthule dunkelküste"}},{q="Was ist der Turm von Althalaxx?",a="Der Turm von Althalaxx ist eine uralte Elfenruine im Norden der Dunkelküste. Finstere Hexenmeister und ihre hörigen Kultisten haben das Gelände ringsum und das Innere besetzt und vollziehen dort dunkle Rituale, fern von Auberdines wachsamen Blicken.",al={"turm von althalaxx","was ist althalaxx","dunkelküste verfallener turm"}},{q="Wer sind die Kultisten rund um den Turm?",a="Die Kultisten rund um den Turm gehören zum Kult des dunklen Strangs, einer verschwiegenen Schar von Hexenmeistern und Eiferern, die sich an den uralten Elfenruinen versammelt hat, um dunkle Beschwörungsrituale zu vollziehen.",al={"wer sind die hexenmeister","kult des dunklen strangs","fanatiker des dunklen strangs"}},{q="Warum warnt Balthule davor, den Turm zu betreten?",a="Balthule warnt, dass die Hexenmeister im oberen Teil des Turms weitaus mächtiger und gefährlicher sind als die Fanatiker, die zwischen den Ruinen lagern. Er rät dazu, zunächst am Rand des Geländes Informationen zu sammeln, bevor man versucht, die Festung zu stürmen.",al={"ist der turm zugänglich","hexenmeister im turm gefährlich","im turm"}},{q="Was verraten die abgenutzten Pergamente?",a="Fetzen, die die Fanatiker des Kults bei sich tragen, verraten den Namen der Gruppe: der Kult des dunklen Strangs. Balthule erfährt, dass die Besetzer eine organisierte Sekte sind, deren Anwesenheit die Region bedroht.",al={"was steht auf den pergamenten","abgenutztes pergament hintergrund","kultnotizen"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Paladin der Allianz, der in Maestras Posten im Eschental stationiert ist und daran arbeitet, dämonische und verderbende Einflüsse zu tilgen. Er vermutet, dass am Turm von Althalaxx finstere Machenschaften Fuß fassen, und verlässt sich auf Späher wie Balthule, um Informationen zu erhalten.",al={"delgren","wer ist delgren","delgren der läuterer"}}},fx={bc625320={q="Warum möchte Balthule Schattenhieb, dass dies getan wird?",a="Balthule Schattenhieb befürchtet, dass sich dunkle Mächte im Geheimen direkt an den Grenzen der Dunkelküste versammeln. Während Delgren vermutete, dass sich Hexenmeister in den alten Ruinen versammelten, weiß keiner von ihnen, wer sie sind oder welches niederträchtige Ritual sie zu vollziehen gedenken. Balthule benötigt genügend schriftliche Beweise, um ihre Identität und ihre Motive zusammenzusetzen, bevor er entscheidende Maßnahmen zum Schutz der Region ergreift.",al={"warum will balthule pergamente","balthule motiv","warum althalaxx untersuchen"}},["151da73d"]={q="Warum schickt Euch Balthule Schattenhieb, anstatt selbst zu gehen?",a="Balthule ist auf einer einsamen Aufklärungswache außerhalb der Ruinen stationiert. Er kann seinen Posten nicht verlassen, um die umliegenden Kultistenlager zu durchkämmen oder nach Auberdine zurückzukehren, um Bericht zu erstatten, in der Angst, dass jede Abwesenheit dazu führen könnte, dass er kritische feindliche Bewegungen verpasst. Indem er Euch die äußeren Kultisten konfrontieren und ihre Schriften bergen lässt, kann er die ständige Überwachung des Turms aufrechterhalten.",al={"warum braucht balthule hilfe","warum nicht balthule selbst","warum bittet balthule euch"}}},fp="22,252,20.370.0,20.280.1,29.215.0,31.218.0,43.179.0,50.225.0,35.185.0,28.262.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="Brakk heißt Reisende an seinem einfachen Lagerfeuer willkommen und lehrt sie, in der Wildnis zu rasten. Danach wenden sie sich praktischen Handwerksfertigkeiten zu.",h="Brakk heißt Reisende an seinem einfachen Lagerfeuer willkommen und lehrt sie, in der Wildnis zu rasten.",kw={"boosted rest","brakk","lageraufbau","lagerfeuer","the great outdoors","handwerksfertigkeit","überleben in der wildnis"},ang={["faction:Horde"]="Ein traditionelles orkisches „Lok-tar“ begrüßt neue Abenteurer der Horde, während sie die Grundlagen des Überlebens erlernen, bevor sie in tückische Gebiete aufbrechen."},sec={{t="Lehren der Wildnis",b="Brakk begrüßt angehende Abenteurer mit einem herzlichen „Lok-tar“ und heißt jene willkommen, die nach Glück und Ruhm streben. Der Weg durch Azeroths Wildnis verlangt mehr als Waffengeschick; Reisende müssen auch den Elementen trotzen. Zu lernen, ein Lager aufzuschlagen und neue Kraft zu schöpfen, ist ein erster Schritt, um dort draußen zu überleben."},{t="Vom Feuer zum Handwerk",b="Die Rast an Brakks einfachem Lagerfeuer bietet eine erholsame Pause unter freiem Himmel und lehrt Reisende, wie sie neue Kraft schöpfen. Sobald sie diese Grundlagen beherrschen, können angehende Abenteurer Handwerker in einem nahe gelegenen Dorf aufsuchen. Dort können sie Handwerksfertigkeiten erlernen und erfahren, wie sie Lageraufbauten errichten, die zu ihrem gewählten Handwerk passen."}},faq={{q="Was ist The Great Outdoors?",a="Brakks Unterweisung lehrt neue Abenteurer, an einem Lagerfeuer zu rasten, bevor sie einen Beruf erlernen.",al={"was ist the great outdoors","the great outdoors quest"}},{q="Wer ist Brakk?",a="Brakk heißt rastlose Reisende willkommen, die nach Glück und Ruhm streben, und lehrt praktische Wege, in der Wildnis zu überleben und am Lagerfeuer zu rasten.",al={"wer ist brakk","questgeber"}},{q="Was ist der Stärkungseffekt Boosted Rest?",a="Die Rast an Brakks einfachem Lagerfeuer gewährt den Stärkungseffekt Boosted Rest und zeigt, wie ein offenes Feuer einem Abenteurer hilft, sich in der Wildnis zu erholen.",al={"boosted rest stärk效ungseffekt","lagerfeuer stärk效ungseffekt"}},{q="Was solltet Ihr nach Abschluss der Quest tun?",a="Nachdem Ihr gelernt habt, in der Wildnis zu rasten, besucht Lehrer im nahe gelegenen Dorf, um eine Handwerksfertigkeit und den Bau passender Lageraufbauten zu erlernen.",al={"nächster schritt nach der quest","was tun nach dem lagerfeuer"}},{q="Was sind Lageraufbauten?",a="Lageraufbauten sind Einrichtungen für Lagerplätze, deren Bau Berufslehrer in nahe gelegenen Dörfern lehren. Damit können Reisende ihre Lager anpassen, um ihre gewählten Handwerksfertigkeiten zu unterstützen.",al={"lageraufbauten","was sind lageraufbauten"}},{q="Für wen ist diese Unterweisung gedacht?",a="Diese Unterweisung richtet sich an rastlose Seelen, die in der Wildnis nach Glück und Ruhm streben, besonders an jene, die ihre Reise gerade erst beginnen und sich auf die Wahl eines Handwerks vorbereiten.",al={"wer sollte diese quest machen","ist das für die horde"}}},fp="18,131,19.303.0,20.303.0,27.97.0,13.133.0,30.138.0,46.153.0,23.164.0,34.151.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="In Kagas Wildnislager lernen Neulinge, wie sie rasten und sich erholen. Vom Lagerfeuer aus gehen sie zu Handwerkern in der Nähe, um Berufsfertigkeiten und die Herstellung von Lagereinrichtungen zu erlernen.",h="In Kagas Wildnislager lernen Neulinge, wie sie rasten und sich erholen.",kw={"boosted rest","lagereinrichtung","lagerfeuer","kaga","überleben","the great outdoors","berufsfertigkeit","wildnis"},ang={["profession:Cooking"]="Lagerfeuer und das Überleben in der Wildnis bilden die Grundlage für das Kochen unterwegs. Die Kunst des Lagerlebens zu erlernen, ergänzt Eure Kochkunst auf natürliche Weise."},sec={{t="Lehren der Wildnis",b="Kaga zeigt Neulingen, wie sie in der Wildnis jenseits der Zivilisation bestehen können. Mut allein kann Euch dort nicht schützen. Ihr müsst auch wissen, wie Ihr ein Lager aufschlagt und den Elementen im Freien trotzt."},{t="Herdfeuer und Handwerk",b="Kagas Lagerfeuer bietet müden Reisenden einen Ort zum Rasten. Setzt Euch daneben, um den Stärkungszauber Boosted Rest zu erhalten. Sobald Ihr wisst, wie Ihr in der Wildnis rastet, legt Kaga Euch nahe, Handwerker in einer nahen Siedlung aufzusuchen. Sie können Euch Berufsfertigkeiten und die Herstellung von Lagereinrichtungen beibringen."}},faq={{q="Was ist The Great Outdoors?",a="Kaga lehrt Neulinge, wie sie in der Wildnis überleben. Sie zeigt ihnen, wie sie an einem Lagerfeuer rasten und sich darauf vorbereiten, Berufe zu erlernen.",al={"was ist the great outdoors","the great outdoors quest"}},{q="Wer bietet diese Quest an?",a="Kaga ist eine Reisende, die Neulingen die Grundlagen des Überlebens in der Wildnis beibringt. An ihrem Lagerfeuer können sie lernen, zu rasten und sich zu erholen.",al={"wer ist kaga","kaga questgeberin"}},{q="Was ist der Stärkungszauber Boosted Rest?",a="Boosted Rest ist der Zustand, den Ihr erlangt, wenn Ihr neben Kagas einfachem Lagerfeuer sitzt. Er spiegelt die erholsame Wirkung einer Rast in einem Wildnislager wider.",al={"boosted rest","was ist der stärkungszauber boosted rest"}},{q="Was sind Lagereinrichtungen?",a="Nachdem Ihr die Grundlagen der Rast in der Wildnis erlernt habt, könnt Ihr bei Handwerkern in nahen Siedlungen lernen, spezialisierte Lagereinrichtungen herzustellen.",al={"hintergrund der lagereinrichtungen","berufsspezifische lagereinrichtungen"}},{q="Warum lässt Kaga Euch am Lagerfeuer sitzen?",a="Zu lernen, ein Lager aufzuschlagen und Eure Ausdauer wiederherzustellen, hilft Euch, jenseits zivilisierter Städte zu überleben. Wenn Ihr an Kagas Lagerfeuer sitzt, könnt Ihr Euch zwischen Euren Reisen durch Rast erholen.",al={"warum am lagerfeuer rasten","am lagerfeuer rasten"}},{q="Was solltet Ihr nach Abschluss dieser Lektion tun?",a="Nachdem Ihr gelernt habt, in der Wildnis zu rasten, sucht Berufslehrer im nahen Dorf auf. Sie können Euch einen Beruf und Rezepte für berufsspezifische Lagereinrichtungen beibringen.",al={"was kommt nach great outdoors","nach kagas quest"}}},fp="18,162,19.184.0,24.259.0,27.126.0,22.128.0,30.141.0,23.140.0,43.158.0,48.161.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="An Lyreenas Lagerfeuer lernen Jäger, sich vor Reisen durch die Wildnis auszuruhen. Dort können sie den Stärkungszauber Boosted Rest erhalten.",h="An Lyreenas Lagerfeuer lernen Jäger, sich vor Reisen durch die Wildnis auszuruhen.",kw={"abenteurer","boosted rest","lagerfeuer","jäger","lyreena","überleben","the great outdoors","wildnis"},ang={["class:Hunter"]="Als Jäger lernt Ihr, warum Überlebenstechniken und Lagerbau wichtig sind, während Ihr durch die Wildnis streift."},sec={{t="Lehren der Wildnis",b="Lyreena ist eine erfahrene Kundschafterin, die Jäger jenseits der Grenzen der Zivilisation führt. Sie lädt Euch ein, zwischen den Jagden an ihrem Lagerfeuer zu rasten. In Azeroths Wildnis ist es ebenso wichtig, ein Lager aufzuschlagen und wieder zu Kräften zu kommen, wie Beute aufzuspüren."},{t="Rast am Lagerfeuer",b="Ein Lagerfeuer spendet Wärme und bietet eine ruhige Rast auf Reisen. Setzt Euch nahe an die Flammen, um Boosted Rest zu erhalten und Kraft für die bevorstehende Reise zu schöpfen. Ruhe hilft Euch, in der Wildnis zu überleben."}},faq={{q="Wer ist Lyreena?",a="Lyreena ist eine erfahrene Kundschafterin, die Jäger durch die Wildnis führt. An ihrem Lagerfeuer gibt sie praktische Ratschläge.",al={"wer ist lyreena","lyreena lagerfeuer","questgeber"}},{q="Was ist The Great Outdoors?",a="An Lyreenas Lagerfeuer lernen Jäger, sich vor Reisen durch die Wildnis auszuruhen.",al={"was ist the great outdoors","was ist diese quest","the great outdoors quest"}},{q="Was ist Boosted Rest?",a="Boosted Rest ist ein wohltuender Effekt, den Ihr erhaltet, wenn Ihr nahe an einem Lagerfeuer sitzt. Er hilft Euch, Euch von Reisen zu erholen und auf die bevorstehende Reise vorzubereiten.",al={"boosted rest stärkungszauber","boosted rest lagerfeuer","wie erhält man boosted rest"}},{q="Warum müsst Ihr Euch an einem Lagerfeuer ausruhen?",a="Eine Rast am Lagerfeuer spendet Euch Wärme und gibt Euch Zeit, Euch zu erholen. Sie hilft Euch, Euch auf gefährliche Reisen durch die Wildnis vorzubereiten.",al={"zweck des lagerfeuers","warum am feuer sitzen","am lagerfeuer ausruhen"}},{q="Warum ist das Überleben in der Wildnis für Jäger so wichtig?",a="Jäger durchstreifen abgelegene Wildnis, wo Gasthäuser und sichere Städte weit entfernt sein können. Grundkenntnisse im Lagerbau helfen Euch, raue Bedingungen ohne Erschöpfung zu überstehen.",al={"überlebensfertigkeiten für jäger","überleben in der wildnis","warum jägerquest"}},{q="Was müsst Ihr tun, um die Aufgabe abzuschließen?",a="Setzt Euch nahe an Lyreenas Lagerfeuer und wartet kurz, um den Stärkungszauber Boosted Rest zu erhalten.",al={"questziel","wie schließt man the great outdoors ab","great outdoors ziele"}}},fp="18,127,19.247.0,16.179.0,15.123.0,27.80.0,21.130.0,38.127.0,44.153.0,38.75.0"}
P.entries["quest:96607"] = {n="The Great Outdoors",s="Jenseits der Stadtmauern lehrt Euch The Great Outdoors den achtsamen Umgang mit der Wildnis. Erfahrene Reisende beginnen mit einem Lagerfeuer und Gewohnheiten, die jede Reise sicherer machen.",h="Jenseits der Stadtmauern lehrt Euch The Great Outdoors den achtsamen Umgang mit der Wildnis.",kw={"adventurer","boosted rest","lagerfeuer","lagern","eleanor shackleton","wald von elwynn","sam sarsaparilla","überleben","handwerksfertigkeit"},ang={["faction:Alliance"]="Im Wald von Elwynn lernen menschliche Reisende von erfahrenen Wanderern die Grundlagen des Überlebens, bevor sie sich größeren Gefahren in Westfall und im Rotkammgebirge stellen.",["faction:Horde"]="Auf den dürren Ebenen Durotars und den windgepeitschten Tafelbergen M ul gores lehren Überlebenskundige der Horde junge Krieger den Umgang mit Feuer und Disziplin im Freien.",["profession:Cooking"]="Jedes Lager in der Wildnis beginnt mit Feuer, deshalb gehört Kochen zum Überleben im Freien. Nach dieser Lektion verweisen Euch Eure Ausbilder auf Kochlektionen entlang des Weges."},sec={{t="Lehren des Weges",b="Eine scharfe Klinge oder mächtige Magie wird Euch nicht retten, wenn Ihr die Grundlagen vernachlässigt. Nahe Lichtungen am Wegesrand lehren erfahrene Wanderer Reisende, die ihre Heimattäler verlassen, am Lagerfeuer zu rasten. Seine Wärme lindert den Schmerz in den Stiefeln, beruhigt den Geist und bereitet Euch auf den beschwerlichen Weg vor. Rast und Vorbereitung erhöhen Eure Chance, lange genug zu überleben, um Reichtum und Ruhm zu finden."},{t="Ein Zuhause unterwegs",b="Eure Ausbilder schicken Euch auch zu den Handwerkern der Stadt, denn ein Feldlager braucht mehr als Glut und eine Schlafrolle. Ihr könnt Ersatznieten schmieden, Wegzehrung kochen oder zerrissene Ausrüstung unter dem Sternenhimmel flicken. Jeder Beruf bietet Lagereinrichtungen, die helfen, einen kahlen Berghang in einen autarken Außenposten zu verwandeln."}},faq={{q="Wer bietet neuen Wanderern diese Lektion an?",a="Erfahrene Reisende erteilen diese Lektion, doch der Ausbilder hängt davon ab, wo Ihr seid. Im Wald von Elwynn lehrt sie Sam Sarsaparilla; andernorts gehören Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof und Raan Wildwind zu den Ausbildern.",al={"wer vergibt the great outdoors","wer startet the great outdoors","questgeber great outdoors"}},{q="Welchen Zweck hat es, am Lagerfeuer zu sitzen?",a="Wenn Ihr an einem Lagerfeuer rastet, könnt Ihr verschnaufen und erhaltet den Effekt Boosted Rest. Wer sich unterwegs Zeit zur Rast nimmt, bewahrt seine Kräfte auf langen Reisen durch die Wildnis.",al={"warum am feuer sitzen","was bewirkt ein lagerfeuer","boosted rest stärkungszauber"}},{q="Wohin führt diese Ausbildung als Nächstes?",a="Nachdem Ihr am Feuer gerastet habt, schickt Euch Euer Mentor in nahe gelegene Siedlungen, um praktische Handwerksfertigkeiten zu erlernen. Danach könnt Ihr Camping 101: Cooking und Lektionen zum Feldlager erlernen, die zu Eurem gewählten Beruf passen.",al={"was kommt nach great outdoors","great outdoors nächste quest","lagerquests"}},{q="Können auch Abenteurer der Horde diese Lektion absolvieren?",a="Ja. Überleben ist für Abenteurer beider Fraktionen wichtig. Ausbilder der Allianz und der Horde, darunter Brakk, Eleanor Shackleton und Kaga Wildhoof, vermitteln ihren Neulingen dieselben Grundlagen des Lagerlebens.",al={"nur für die allianz","horde great outdoors","können orcs diese quest machen"}},{q="Warum schicken Euch die Ausbilder zu Berufslehrern?",a="Zum Überleben gehört mehr, als am Feuer zu sitzen; Ihr müsst Euch auch selbst versorgen können. Berufslehrer zeigen Euch, wie Ihr Lagereinrichtungen für Euer Handwerk herstellt, ob Ihr unter freiem Himmel Wegzehrung kocht, Rüstungen flickt oder Heilmittel braut.",al={"warum berufe lernen","lagereinrichtungen berufslehrer","verbindung zwischen beruf und lager"}},{q="Welche Vorkenntnisse werden für diese Quest erwartet?",a="Ihr erhaltet diese Lektion gewöhnlich nach 'The Adventurer', sobald Ihr grundlegenden Ehrgeiz gezeigt und Euer Startgebiet in Richtung der weiteren Umgebung verlassen habt.",al={"voraussetzungen für the great outdoors","great outdoors freischalten","vor great outdoors"}}},fp="18,163,20.367.0,21.304.0,40.260.0,47.178.0,35.203.0,52.194.0,61.225.0,59.144.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="Eric wartet an seinem Lagerfeuer, um Reisenden zu zeigen, wie sie in der Wildnis rasten können.",h="Eric wartet an seinem Lagerfeuer, um Reisenden zu zeigen, wie sie in der Wildnis rasten können.",kw={"boosted rest","camp fixture","lagerfeuer","eric","überleben","the great outdoors","fertigkeit","wildnis"},ang={["class:Priest"]="Als Priester findet Ihr Eure Berufung vielleicht in heiligen Stätten und Kapellen. Doch das Leben auf Reisen verlangt neben Gebeten und Segen auch praktische Überlebensfertigkeiten."},sec={{t="Lektionen der Wildnis",b="Abseits bewohnter Orte reichen Ehrgeiz und eine Waffe oder ein heiliges Symbol nicht aus. Ihr müsst wissen, wie Ihr inmitten der Elemente rasten könnt. Eric ist weit gereist und heißt Euch an seinem Lagerfeuer willkommen. Dort erklärt er, warum richtige Rast wichtig ist, bevor Ihr Euch der Wildnis stellt."},{t="Vom Lagerfeuer zum Handwerk",b="Ein Lagerfeuer ist der Anfang eines nützlichen Lagers für eine lange Reise. Sobald Ihr gelernt habt, Euch in der Wildnis zu erholen, sucht Berufslehrer in nahe gelegenen Siedlungen auf. Sie können Euch beibringen, Lagereinrichtungen für Euer Handwerk herzustellen. So kann Euer Handwerk Euch auf Euren Reisen unterstützen, wohin der Weg Euch auch führt."}},faq={{q="Wer ist Eric?",a="Eric ist ein erfahrener Reisender, der Neulingen beibringt, in der Wildnis zu überleben. Er heißt Euch an seinem Lagerfeuer willkommen und gibt Euch Ratschläge für das Leben jenseits der Stadtmauern.",al={"wer vergibt diese quest","wer ist eric","wer lehrt the great outdoors"}},{q="Was ist der Boosted-Rest-Stärkungszauber?",a="Wenn Ihr an Erics Lagerfeuer rastet, erhaltet Ihr den Effekt Boosted Rest. Er hilft Euch, Euch vor den Elementen geschützt zu erholen und auf die bevorstehenden Prüfungen vorzubereiten.",al={"was ist boosted rest","wie hilft das lagerfeuer","erholungsstärkung im lager"}},{q="Was sind Lagervorrichtungen?",a="Lagereinrichtungen sind praktische Bauten oder Werkzeuge für bestimmte Berufe, die Ihr in der Wildnis aufstellen könnt. Lehrer in nahe gelegenen Siedlungen erklären Euch, wie Ihr mit Eurem Beruf ein Lager zum Arbeiten einrichten könnt.",al={"was sind camp fixtures","berufsvorrichtungen","fertigkeiten lagergegenstand"}},{q="Warum müsst Ihr in der Nähe von Erics Lagerfeuer sitzen?",a="An Erics Lagerfeuer zu sitzen gibt Euch Zeit, innezuhalten, Euch aufzuwärmen und seinen Ratschlägen zum Überleben in der Wildnis zu lauschen. Wenn Ihr dort rastet, könnt Ihr den Schutz unter freiem Himmel voll ausnutzen.",al={"warum am feuer sitzen","am lagerfeuer sitzen","lagerfeuer ziel"}},{q="Wohin sollte ein Abenteurer nach Abschluss dieser Lektion gehen?",a="Nachdem Ihr gelernt habt, im Lager zu rasten, empfiehlt Eric Euch einen Besuch im nahe gelegenen Dorf. Die örtlichen Lehrer können Euch einen Beruf beibringen und Euch dann zeigen, wie Ihr passende Lagereinrichtungen für Euer Handwerk herstellt.",al={"was danach zu tun ist","wohin als nächstes","nach the great outdoors"}},{q="Für wen ist diese Überlebenslektion gedacht?",a="Eric heißt vorbeiziehende Abenteurer willkommen, die ein rastloser Geist und die Bereitschaft antreiben, in aller Welt nach Glück und Ruhm zu suchen. Seine Ratschläge zum Leben in der Wildnis können Euch helfen, die Sicherheit hinter Euch zu lassen und Euch in die offene Wildnis zu wagen.",al={"wer kann diese quest annehmen","nur priester","ist das für abenteurer"}}},fp="18,70,19.256.0,22.277.0,12.165.0,30.144.0,23.199.0,44.176.0,59.179.0,41.199.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="In Goldhain zeigt Cook Tomas neuen Reisenden, wie die Kochkunst ein Lagerfeuer entfacht. Mit diesem Feuer können sie in der Wildnis ein einfaches Lager errichten.",h="In Goldhain zeigt Cook Tomas neuen Reisenden, wie die Kochkunst ein Lagerfeuer entfacht.",kw={"lagerfeuer","camping","camping 101: cooking","lagerplatz","kochen","ausstattung","goldhain","tomas"},ang={["faction:Alliance"]="Als Abenteurer der Allianz, der neu im Wald von Elwynn ist, werdet Ihr zu Cook Tomas im Gasthaus \"Zur Höhle des Löwen\" in Goldhain geschickt, um das Kochen und das Entfachen von Lagerfeuern zu erlernen.",["profession:Cooking"]="Die Kochkunst lehrt Euch, einfache Lagerfeuer im Herzen Eurer Lager in der Wildnis zu entfachen."},sec={{t="Die Feuerstelle in der Wildnis",b="Ein Lagerfeuer bietet Euch einen Ort, um Essen zuzubereiten und in Azeroths Wildnis ein Lager aufzuschlagen. Lernt Ihr kochen, lernt Ihr auch, dieses Feuer zu entfachen. Dann kann ein offener Landstrich in der Wildnis zu einem Lagerplatz werden."},{t="Unterweisung in Goldhain",b="Im Wald von Elwynn finden neue Reisende Cook Tomas in Goldhain und erlernen das Handwerk. Sein Unterricht verleiht Euch die Fähigkeit, in der Wildnis ein einfaches Lager zu errichten. Anfangs bietet Euer Lager nur wenigen Einrichtungsgegenständen Platz. Mit größerem Können in der Kochkunst könnt Ihr größere Feuer entfachen, während Euch andere Handwerksberufe mehr Möglichkeiten geben, Euren Lagerplatz einzurichten und zu gestalten."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Die Kochkunst lehrt Euch, ein einfaches Lagerfeuer für einen Lagerplatz in der Wildnis zu entfachen.",al={"was ist camping 101 cooking","was lehrt camping 101","zweck von camping 101"}},{q="Wer ist Tomas und wo ist er zu finden?",a="Tomas lehrt die Kochkunst in Goldhain im Wald von Elwynn. Ihr findet ihn im Gasthaus \"Zur Höhle des Löwen\", wo er die Grundlagen des Kochens und des Entfachens eines Lagerfeuers vermittelt.",al={"wer ist tomas","wo ist tomas","tomas goldhain"}},{q="Warum ist Kochen erforderlich, um einen Lagerplatz zu errichten?",a="Die Kochkunst lehrt Euch, das Lagerfeuer im Herzen eines Lagers in der Wildnis zu entfachen, wo Ihr Euch ausruhen und Einrichtungsgegenstände aufstellen könnt.",al={"warum brauche ich kochen zum campen","ist kochen zum campen erforderlich","beziehung zwischen kochen und lagerfeuer"}},{q="Kann man mit steigender Fertigkeit größere Lagerfeuer errichten?",a="Mit größerem Können in der Kochkunst könnt Ihr größere, beständigere Feuer für Euer Lager in der Wildnis entfachen.",al={"wie man ein lagerfeuer aufwertet","kann ich größere lagerfeuer errichten","größere feuer durch kochen"}},{q="Wie erhält man Ausstattung für seinen Lagerplatz?",a="Andere Berufslehrer zeigen Euch, wie Ihr Einrichtungsgegenstände für Euren Lagerplatz herstellen könnt. Verschiedene Handwerksberufe ermöglichen Euch, Gegenstände herzustellen, um ein Lager in der Wildnis zu schmücken und zu verbessern.",al={"wie man lagerausstattung hinzufügt","woher lagerausstattung stammt","lagergegenstände herstellen"}},{q="Wo kann ein Abenteurer ein Lager aufschlagen?",a="Sobald Ihr kochen und ein Lagerfeuer entfachen könnt, könnt Ihr in der offenen Wildnis ein Lager aufschlagen. Eure ersten Lagerplätze sind bescheiden und bieten nur wenigen Einrichtungsgegenständen Platz, bis Ihr Eure Fertigkeiten erweitert.",al={"kann ich überall mein lager aufschlagen","regeln fürs campen in der wildnis","grenzen für lagerplatzierung"}}},fp="20,133,22.193.0,24.328.0,39.73.0,39.151.0,48.120.0,53.86.0,49.161.0,36.183.0"}
P.entries["quest:96627"] = {n="The Adventurer",s="Vom Nordhaintal aus schickt Marschall McBride Euch nach Goldhain, um Sam Sarsaparilla zu finden. Ihr habt Euer Können bei der Verteidigung der Abtei bewiesen, und nun sollt Ihr einen Neuankömmling unter die Lupe nehmen.",h="Vom Nordhaintal aus schickt Marschall McBride Euch nach Goldhain, um Sam Sarsaparilla zu finden.",kw={"wald von elwynn","goldhain","marschall mcbride","nordhain","sam sarsaparilla","the adventurer"},ang={["faction:Alliance"]="Für Euch als neue Rekruten der Allianz, die ihren Dienst in Nordhain beenden, ist dies der erste offizielle Schritt in die weitere Welt des Waldes von Elwynn.",["race:Human"]="Als menschlicher Verteidiger, der die Abtei von Nordhain verlässt, macht Ihr Eure ersten Schritte in Richtung Goldhain, dem Herzen von Elwynn."},sec={{t="Aufbruch aus dem Tal",b="Da die Bedrohung durch Defias und Ungeziefer nachlässt, richtet McBride seine Aufmerksamkeit auf die Straße jenseits des Tals. Seine Garnison braucht vielversprechende Kämpfer, um Reisende und Wanderer in den umliegenden Wäldern im Auge zu behalten."},{t="Ein rätselhafter Neuankömmling",b="Marschall McBride bittet Euch, nach Sam Sarsaparilla zu sehen, der nahe Goldhain gesichtet wurde. Dies ist weder ein militärischer Befehl noch eine Kopfgeldjagd. Der Neuankömmling führt Euch aus Nordhains abgeschiedenem Tal in die weite Wildnis von Elwynn."}},faq={{q="Wer schickt mich auf diese Aufgabe?",a="Marschall McBride, Kommandant der Garnison von Sturmwind im Nordhaintal, schickt Euch, nachdem Ihr Euch bei der Verteidigung der Abtei bewährt habt.",al={"questgeber","wer vergibt the adventurer","marschall mcbride quest"}},{q="Wer ist Sam Sarsaparilla?",a="Sam Sarsaparilla ist ein Abenteurer nahe der Straße bei Goldhain. Marschall McBride hört von seiner Anwesenheit und bittet Euch herauszufinden, was er dort tut.",al={"sam sarsaparilla","wer ist sam","goldhain abenteurer"}},{q="Wo finde ich Sam Sarsaparilla?",a="Sam Sarsaparilla hält sich an der Hauptstraße auf, die von Nordhain nach Süden in Richtung Goldhain im Wald von Elwynn führt.",al={"sam sarsaparilla aufenthaltsort","wo ist sam","sam sarsaparilla finden"}},{q="Warum interessiert sich Marschall McBride für irgendeinen Abenteurer?",a="Nordhain bleibt wegen Banditen und Eindringlingen in Alarmbereitschaft. McBride behält fremde Söldner und Wanderer im Auge, die hier durchkommen, und vertraut darauf, dass verlässliche Einheimische den ersten Kontakt aufnehmen.",al={"warum werde ich geschickt","mcbrides beweggründe","warum sam suchen"}},{q="Muss ich das Nordhaintal verlassen, um diese Aufgabe abzuschließen?",a="Ja. Verlasst das Nordhaintal durch seine südlichen Tore und folgt der Waldstraße in Richtung Goldhain.",al={"außerhalb von nordhain","führt dies aus nordhain hinaus","nach goldhain gehen"}},{q="Gehört dies zur üblichen militärischen Befehlskette von Sturmwind?",a="Marschall McBride ist ein Offizier von Sturmwind, doch er bezeichnet dies als ungewöhnlichen Auftrag und nicht als gewöhnlichen Wachdienst. Er verlässt sich auf Euer Urteilsvermögen als unabhängiger Beschützer außerhalb des förmlichen Militärprotokolls.",al={"sturmwinds militär","ist dies gewöhnlicher dienst","offizieller auftrag"}}},fx={dd262048={q="Warum wählt Marschall McBride mich aus, um Sam zu untersuchen?",a="Marschall McBride betrachtet dies eher als ungewöhnliche Aufgabe denn als Standardwachdienst. Nachdem er beobachtet hat, wie Ihr mit den lokalen Bedrohungen von Nordhain umgegangen seid, betrachtet er Euch als fähigen Beschützer, der diskret außerhalb der Abteitore agieren kann. Da seine eigene Garnison mit lokalen Problemen überlastet ist, macht es weit mehr Sinn, einen vertrauenswürdigen Rekruten zu schicken, der Gerüchten die Straße hinunter nachgeht, als reguläre Wachen zu entsenden.",al={"warum ich marschall mcbride","warum schickt mich mcbride","warum keine wache zu sam schicken"}}},fp="14,186,18.198.0,18.232.0,26.131.0,24.138.0,33.96.0,56.182.0,52.100.0,63.202.0"}
P.entries["quest:96628"] = {n="The Adventurer",s="Am Südtor von Dun Morogh trägt der Adventurer Vorräte nach Kharanos. Gebirgsjäger Thalos bittet Reisende, Eric Brighthammer Proviant zu bringen, einem Neuankömmling, der direkt vor dem Dorf lagert.",h="Am Südtor von Dun Morogh trägt der Adventurer Vorräte nach Kharanos.",kw={"eisklamm","dun morogh","eric brighthammer","kharanos","gebirgsjäger thalos","vorratsbündel","the adventurer"},ang={["faction:Alliance"]="Als Reisender der Allianz tragt Ihr Vorräte über die vereisten Straßen zu Verbündeten, die vor Kharanos lagern.",["race:Dwarf"]="Als Zwerg, der das Coldridgetal verlässt, bringt Ihr Eric Brighthammer Proviant und helft den Gebirgsjägern in Dun Morogh."},sec={{t="Ein Gefallen für die Gebirgsjäger",b="Gebirgsjäger Thalos hält am Südtor von Dun Morogh Wache, wo der Pfad das Coldridgetal verlässt. Die Bewachung der hohen Pässe und Tunnel hält die Gebirgsjäger auf Trab. Thalos hält auch nach Gefahren und Reisenden auf der Straße Ausschau. Als ein einsamer Abenteurer nahe Kharanos eintrifft, bittet er vertrauenswürdige Reisende, Vorräte weiterzutragen. Das Bündel soll Neuankömmlingen helfen, die sich in die gefrorenen Felsklüfte wagen."},{t="Vorräte für Kharanos",b="Die Straße vom südlichen Pass schlängelt sich hinab nach Kharanos, einem Zentrum für Zwergenhandwerk und Reisen im Herzen von Dun Morogh. Eric Brighthammer hat vor Kurzem direkt vor dem Dorf sein Lager aufgeschlagen. Wer ihm den Proviant der Gebirgsjäger bringt, verbindet die Wachen auf dem Bergkamm mit jenen, die durch die Wildnis ziehen."}},faq={{q="Wer vergibt die Quest The Adventurer?",a="Gebirgsjäger Thalos bittet Reisende an seinem Posten am Tor des Gebirgspasses um Hilfe, wo der Pfad aus dem Coldridgetal nach Dun Morogh führt.",al={"questgeber","wer vergibt the adventurer","thalos quest"}},{q="Wer ist Eric Brighthammer?",a="Eric Brighthammer ist ein Abenteurer, der vor Kurzem vor Kharanos eingetroffen ist. Gebirgsjäger Thalos bittet Reisende, ihm ein Bündel mit Vorräten zu bringen.",al={"wo ist eric brighthammer","wer ist der adventurer","brighthammer"}},{q="Wohin führt diese Lieferung?",a="Die Lieferung geht an Eric Brighthammers Lager direkt vor Kharanos in Dun Morogh. Es liegt nördlich des Tunnels der Eisklamm, wo Gebirgsjäger Thalos stationiert ist.",al={"wo vorräte abliefern","eric brighthammer standort","vorratsbündel abgeben"}},{q="Warum schickt Gebirgsjäger Thalos Vorräte?",a="Die Gebirgsjäger wachen über Reisende in ganz Dun Morogh. Als Thalos hört, dass ein Abenteurer nahe Kharanos lagert, lässt er ihm Proviant bringen, um ihn in der Kälte zu unterstützen.",al={"warum vorräte schicken","thalos absicht","grund für das bündel"}},{q="Welchen Gegenstand tragt Ihr?",a="Ihr bringt ein Vorratsbündel von Gebirgsjäger Thalos zu Eric Brighthammer.",al={"welche vorräte","vorratsbündel gegenstand"}},{q="Ist diese Quest für Spieler der Horde verfügbar?",a="Nein. Gebirgsjäger Thalos ist eine zwergische Wache im Dienst der Allianz, daher ist die Aufgabe für Reisende der Allianz bestimmt.",al={"kann die horde das machen","nur für die allianz","horde the adventurer quest"}}},fx={["95095969"]={q="Warum bittet Euch Gebirgsjäger Thalos, die Vorräte zu liefern?",a="Gebirgsjäger Thalos und seine Patrouille sind am Pass stationiert, mit der Aufgabe, die Straße zu bewachen und den Tunnel vor lokalen Gefahren zu sichern. Da Ihr ohnehin durch den Pass weiter Richtung Kharanos reist, bittet er Euch, die Lieferung auf Eurer Route mitzunehmen, anstatt seine Gebirgsjäger von ihren Wachposten abzuziehen.",al={"warum ich der abenteurer","warum braucht thalos mich","warum spieler zu eric brighthammer schicken"}}},fp="14,201,28.398.0,21.296.0,36.135.0,25.142.0,36.164.0,43.175.0,27.71.0,41.107.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="In Dun Morogh lernen Reisende, für die Wildnis zu kochen und Feuer zu machen. Gremlock Pilsnor unterrichtet unerfahrene Abenteurer in Kharanos. Kochen sorgt für Reiseproviant und hilft Reisenden, an Lagerplätzen in der Wildnis Lagerfeuer zu entzünden.",h="In Dun Morogh lernen Reisende, für die Wildnis zu kochen und Feuer zu machen.",kw={"lagerfeuer","lagern","kochen","dun morogh","einrichtungsgegenstände","gremlock pilsnor","kharanos","wildnis"},ang={["class:Priest"]="Als Priester braucht Ihr grundlegende Überlebensfertigkeiten wie das Entfachen eines Feuers, wenn Ihr fern von Tempeln und Siedlungen reist.",["faction:Alliance"]="Als Abenteurer der Allianz nahe Dun Morogh lernt Ihr bei den zwergischen Lehrern in Kharanos das Kochen und Fertigkeiten für die Wildnis.",["profession:Cooking"]="Beim Kochen lernt Ihr, das Lagerfeuer zu entfachen, das für einen Lagerplatz in der Wildnis und dessen Einrichtung benötigt wird."},sec={{t="Die Feuerstelle in der Wildnis",b="Euer erstes Lager in Dun Morogh beginnt mit einem Feuer. In Kharanos lehrt Gremlock Pilsnor unerfahrene Abenteurer das Kochen. Diese Fertigkeit sorgt für Reiseproviant. Ein beständiges Lagerfeuer bildet den Mittelpunkt eines Lagers unter freiem Himmel."},{t="Den Lagerplatz erweitern",b="Sobald Ihr ein Lagerfeuer entfachen könnt, könnt Ihr in der offenen Wildnis ein bescheidenes Lager aufschlagen. Ein einfaches Feuer bietet nur Platz für wenige Einrichtungsgegenstände, doch mit größerer Kochfertigkeit könnt Ihr größere Feuer entfachen. Handwerker, die andere Handwerke erlernt haben, können Einrichtungsgegenstände herstellen und so einen einfachen Rastplatz in ein voll ausgestattetes Lager verwandeln."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Ihr lernt, zu kochen und Lagerfeuer zu entfachen, die ersten Schritte zum Errichten eines Lagers in der Wildnis.",al={"was ist camping 101: cooking","zweck der quest","grundlagen des lagerns und kochens"}},{q="Wer ist Gremlock Pilsnor?",a="Gremlock Pilsnor lehrt unerfahrene Abenteurer in Kharanos in Dun Morogh das Kochen.",al={"wer lehrt kochen in kharanos","gremlock pilsnor fundort","kochlehrer dun morogh"}},{q="Warum ist Kochen zum Lagern notwendig?",a="Beim Kochen lernt Ihr, ein Lagerfeuer zu entfachen, das die Grundlage für ein Lager in der Wildnis und dessen Einrichtung bildet.",al={"warum kochen zum lagern nötig ist","zweck des lagerfeuers","kochen und lager"}},{q="Wo lässt sich ein Lagerplatz errichten?",a="Sobald Ihr wisst, wie man ein Feuer entfacht, könnt Ihr einen einfachen Lagerplatz in der Wildnis errichten und dort auf Euren Reisen rasten.",al={"wo lässt sich ein lager errichten","regeln für lagerplätze","lager aufschlagen"}},{q="Wie verbessert oder erweitert Ihr einen Lagerplatz?",a="Mit größerer Kochfertigkeit könnt Ihr größere Lagerfeuer entfachen, während andere Handwerksberufe Euch ermöglichen, weitere Einrichtungsgegenstände für Euren Lagerplatz herzustellen.",al={"wie lässt sich ein lagerplatz verbessern","größere feuer","mehr lagerdekorationen"}},{q="Können andere Berufe zum Lagern beitragen?",a="Andere Handwerksberufe können Euren Lagerplatz um Einrichtungsgegenstände bereichern, sobald Ihr die Fertigkeiten zu deren Herstellung erlernt habt.",al={"wer bietet lagereinrichtung an","lagergegenstände aus handwerksberufen","weitere lehrer fürs lagern"}}},fp="20,225,22.208.0,22.298.0,39.91.0,24.79.0,37.91.0,36.115.0,40.122.0,44.105.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="In Teldrassil findet Ihr nahe Dolanaar ein verlorenes Tagebuch, das für Lyreena Duskblade bestimmt ist. Seine Seiten erzählen von den stillen Reisen und Zeltausflügen eines unbekannten Reisenden.",h="In Teldrassil findet Ihr nahe Dolanaar ein verlorenes Tagebuch, das für Lyreena Duskblade bestimmt ist.",kw={"zelten","dolanaar","tagebuch","verlorenes tagebuch","lyreena duskblade","teldrassil","the adventurer"},ang={["faction:Alliance"]="Als Neuling der Allianz unter dem Weltbaum helft Ihr, die Haine in Ordnung zu halten, indem Ihr Mitreisenden verlorene Habseligkeiten zurückbringt.",["race:NightElf"]="Als junger Nachtelf auf Patrouille in Teldrassil könnt Ihr Spuren von Reisenden finden und verlorene Andenken zu Wanderern wie Lyreena Duskblade bringen."},sec={{t="Das Tagebuch eines Wanderers",b="Zwischen Teldrassils Ästen und Wurzeln findet Ihr ein zurückgelassenes Tagebuch. Sein namenloser Verfasser erzählt von bescheidenen Wanderungen und der einfachen Freude am Zelten unter dem dämmrigen Blätterdach."},{t="Übergabe in Dolanaar",b="Ihr könnt das Tagebuch nach Dolanaar tragen, statt es in der Wildnis zurückzulassen. Lyreena Duskblade wartet nahe der Nachtelfensiedlung darauf, seine verlorenen Seiten entgegenzunehmen."}},faq={{q="Was ist das für ein Tagebuch, das in der Quest erwähnt wird?",a="Das Tagebuch ist ein schlichtes Notizbuch, das in Teldrassils Wildnis gefunden wird. Seine Einträge erzählen von den stillen Reisen eines unbekannten Reisenden und seiner Vorliebe für das Zelten im Freien.",al={"verlorenes tagebuch","was ist das buch","the adventurer tagebuch"}},{q="Wer ist Lyreena Duskblade?",a="Lyreena Duskblade ist eine Nachtelfe, die nahe Dolanaar darauf wartet, das verlorene Tagebuch entgegenzunehmen.",al={"lyreena","wo ist lyreena duskblade","abgabe-npc"}},{q="Wo spielt diese Quest?",a="Die Geschichte spielt in Teldrassils Wildnis rund um Dolanaar.",al={"wo ist die quest the adventurer","questgebiet"}},{q="Beschreibt das Tagebuch gefährliche Monster oder Schlachten?",a="Nein. Das Tagebuch erzählt von den gewöhnlichen Wanderungen einer unbekannten Person und ihrer Freude am Zelten, nicht von gefährlichen Monstern oder Schlachten.",al={"tagebuchgeschichte","was steht im tagebuch","was steht darin"}},{q="Wer kann diese Aufgabe abschließen?",a="Mitglieder der Allianz, die Teldrassil erkunden, können das Tagebuch zurückbringen, besonders unerfahrene Nachtelfen nahe Dolanaar.",al={"kann die horde das machen","allianzquest"}},{q="Warum das Tagebuch in Dolanaar abgeben?",a="Dolanaar ist ein zentraler Treffpunkt und Verkehrsknotenpunkt in diesem Teil von Teldrassil. Lyreena Duskblade wartet in der Nähe darauf, das Tagebuch entgegenzunehmen.",al={"warum dolanaar","warum lyreena"}}},fp="14,156,20.179.0,20.163.0,43.152.0,25.83.0,33.65.0,56.125.0,27.106.0,36.135.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="In der Wildnis beginnt Ihr mit Kochen und einem Feuer, und Lehrer wie Zarrin in Dolanaar können Euch das Handwerk beibringen. Ein Lagerfeuer bildet den Mittelpunkt Eures Lagers und eröffnet Euch den Weg zum Überleben im Freien.",h="In der Wildnis beginnt Ihr mit Kochen und einem Feuer, und Lehrer wie Zarrin in Dolanaar können Euch das...",kw={"lagerfeuer","camping 101","lagerplatz","kochen","dolanaar","einrichtungsgegenstände","überleben in der wildnis","zarrin"},ang={["profession:Cooking"]="Die Kochkunst gibt Euch das Lagerfeuer, das den Mittelpunkt eines Lagerplatzes im Freien bildet. Mit wachsender Kochfertigkeit könnt Ihr lernen, größere, beständigere Feuer zu errichten.",["race:NightElf"]="Als Nachtelf könnt Ihr bei Zarrin in Dolanaar lernen, Euch in der Wildnis zurechtzufinden und Feuer zu machen, bevor Ihr tiefer in Teldrassils Wildnis vordringt."},sec={{t="Die Feuerstelle der Wildnis",b="Wenn Ihr durch die Wildnis reist, bietet Euch ein Lagerfeuer einen Ausgangspunkt. Lasst Euch zuerst in der Kochkunst ausbilden. Kochen lässt Euch Mahlzeiten aus Wildbret zubereiten und lehrt Euch, ein einfaches Lagerfeuer zu entzünden. Dieses Feuer bildet den Mittelpunkt eines Lagers im Freien. Ohne ein Feuer, das die Kälte vertreibt und die Dunkelheit fernhält, könnt Ihr in der Wildnis keinen verlässlichen Lagerplatz errichten."},{t="Den Lagerplatz erweitern",b="Mit einem einfachen Lagerfeuer könnt Ihr ein bescheidenes Lager in der Wildnis errichten. Es bietet nur Platz für wenige einfache Einrichtungsgegenstände, doch mit wachsenden Fertigkeiten könnt Ihr Euer Lager erweitern. Eine weiterführende Ausbildung in der Kochkunst lehrt Euch, größere, beständigere Feuer zu entfachen. Lehrer anderer Berufe können Euch beibringen, Einrichtungsgegenstände herzustellen und Euer Lager zu verbessern."}},faq={{q="Wozu dient Camping 101: Cooking?",a="Die Ausbildung in der Kochkunst führt Euch in das Überleben in der Wildnis ein. Ein Lagerfeuer bildet den Mittelpunkt Eures Lagerplatzes in der Wildnis.",al={"was bewirkt diese quest","camping 101 cooking zweck","warum camping 101 machen"}},{q="Wer ist Zarrin?",a="Zarrin lehrt Kochkunst in Dolanaar auf Teldrassil. Er bringt Anfängern die Grundlagen des Kochens bei und zeigt ihnen, wie sie ein einfaches Lagerfeuer errichten.",al={"wer ist zarrin","zarrin dolanaar","wo ist der kochkunstlehrer in dolanaar"}},{q="Wie errichtet Ihr einen Lagerplatz in der Wildnis?",a="Lernt zunächst im Rahmen einer Ausbildung in der Kochkunst, ein einfaches Lagerfeuer zu errichten. Die Grundausbildung ermöglicht Euch ein bescheidenes Lager in der Wildnis, während eine weiterführende Ausbildung Euch größere Feuer und Verbesserungen für den Lagerplatz lehrt.",al={"wie ein lager errichten","wie funktioniert campen","einen lagerplatz errichten"}},{q="Könnt Ihr Euren Lagerplatz mit Einrichtungsgegenständen ausstatten?",a="Ja. Die Kochkunst gibt Eurem Lager das Feuer als Mittelpunkt, und Lehrer anderer Berufe zeigen kundigen Handwerkern, wie sie Einrichtungsgegenstände und Verbesserungen für ihre Lager herstellen.",al={"lagerplatz einrichten","lagerdekoration","lagerplatzeinrichtung andere berufe"}},{q="Warum ist Kochen zum Campen erforderlich?",a="Kochen lehrt Euch, in der Wildnis ein Lagerfeuer zu errichten und zu unterhalten. Da Feuer den Mittelpunkt eines Lagers im Freien bildet, ist das Erlernen der Kochkunst der erste Schritt zum Campen in der Wildnis.",al={"warum kochen zum campen nötig","zusammenhang zwischen kochen und campen"}},{q="Könnt Ihr größere Lagerfeuer errichten?",a="Ja. Eine weiterführende Ausbildung in der Kochkunst lehrt Euch, größere Feuer für Eure Lager in der Wildnis zu errichten.",al={"größere lagerfeuer errichten","wie lagerfeuer verbessern"}}},fp="20,180,22.333.0,22.297.0,44.101.0,14.121.0,44.196.0,41.154.0,36.163.0,30.87.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="Auf der Insel Zephras verlässt The Adventurer den Thendalhain und folgt der Straße nach Shen'dar. Aetheen of the Gales schickt frisch erprobte Wanderer nach Südwesten zu Raan Wildwind, einem erfahrenen Lagernden, der die Wildnis kennt.",h="Auf der Insel Zephras verlässt The Adventurer den Thendalhain und folgt der Straße nach Shen'dar.",kw={"aetheen of the gales","raan wildwind","shen'dar","the adventurer","thendalhain","insel zephras"},ang={["race:Skyborne"]="Als junger Skyborne verlasst Ihr das schützende Blätterdach des Thendalhains und trefft Raan Wildwind als ersten Schritt in die weitere Wildnis Eurer Heimatinsel."},sec={{t="Abschied vom Hain",b="Der Thendalhain bietet Schutz, doch die Insel Zephras jenseits seiner Grenzen bleibt wild und gefährlich. Aetheen of the Gales wacht über die Initianden und weiß, wann ein Reisender bereit ist, vertrautes Gelände zu verlassen. Wer Ruhm, Reichtum oder Bestimmung sucht, ist den geschützten Grenzen des Hains entwachsen."},{t="Ein Wegweiser am Straßenrand",b="Raan Wildwind hat südwestlich des Thendalhains an der Straße nach Shen'dar sein Lager aufgeschlagen. Er hat sich eine Zeit lang den Gefahren jenseits der sicheren Zuflucht gestellt. Wanderern, die vom Hain aufbrechen, gibt Raan praktische Ratschläge zum Überleben auf den offenen Straßen."}},faq={{q="Wer schickt Euch auf die Suche nach Raan Wildwind?",a="Aetheen of the Gales schickt Euch vom Thendalhain aus auf die Suche nach Raan Wildwind. Nachdem Ihr Euch in den umliegenden Wäldern bewährt habt, weist sie Euch zu jemandem, der die weitere Insel aus eigener Erfahrung kennt.",al={"wer vergibt the adventurer","wer startet die quest the adventurer","aetheen quest"}},{q="Wo befindet sich Raan Wildwind?",a="Raan Wildwind hat südwestlich des Thendalhains an der Hauptstraße nach Shen'dar sein Lager aufgeschlagen.",al={"raan wildwind standort","wo ist raan","wie raan wildwind finden"}},{q="Was ist der Zweck dieser Aufgabe?",a="Ihr verlasst die sichere Zuflucht des Thendalhains und trefft einen Wegweiser für die Herausforderungen in den entfernteren Gebieten der Insel Zephras.",al={"warum the adventurer abschließen","zweck der quest the adventurer","was lehrt raan"}},{q="Welche Voraussetzung muss erfüllt sein, bevor diese Quest verfügbar wird?",a="Bevor Aetheen of the Gales Euch zu Raan Wildwind schickt, müsst Ihr die Aufgabe zur Foul Matriarch abschließen.",al={"the adventurer voraussetzung","voraussetzungen für the adventurer"}},{q="Ist Shen'dar für Reisende sicher?",a="Shen'dar liegt hinter Raans Lager, am Ende der Straße, die vom Thendalhain nach Südwesten führt. Es ist eine bedeutende Siedlung, doch seid auf den Straßen und in der umliegenden Wildnis vorsichtig.",al={"ist shendar sicher","was ist shen'dar"}},{q="Wer ist Raan Wildwind?",a="Raan Wildwind ist ein Wanderer, der über den Thendalhain hinausgereist ist und vor Shen'dar sein Lager aufgeschlagen hat. Er bietet Neuankömmlingen, die der Straße folgen, praktische Ratschläge und Aufgaben.",al={"raan hintergrundgeschichte","wer ist raan wildwind"}}},fx={dc12ab9c={q="Warum schickt Euch Aetheen of the Gales los, um Raan Wildwind zu finden?",a="Aetheen erkennt, dass mehr Wanderer die Sicherheit des Thendalhain verlassen, auf der Suche nach Ruhm und Reichtum. Da er weiß, dass die Wildnis für Unerfahrene große Gefahren birgt, möchte Aetheen, dass Ihr Raan Wildwind aufsucht – einen Mitreisenden, der nahe Shen'dar lagert –, um praktische Weisheit und Überlebenslektionen zu lernen, die Euch auf Euren Reisen über die Insel am Leben halten.",al={"warum schickt euch aetheen","aetheen of the gales motiv","warum raan wildwind treffen"}}},fp="14,209,17.275.0,19.252.0,36.189.0,31.96.0,33.100.0,64.113.0,39.179.0,21.174.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="In Shen'dar zeigt Euch Zerril Softbreeze, wie Ihr ein Lagerfeuer entfacht. Camping 101: Cooking lehrt Euch, ein Feuer zu entfachen und einen Lagerplatz in der Wildnis einzurichten.",h="In Shen'dar zeigt Euch Zerril Softbreeze, wie Ihr ein Lagerfeuer entfacht.",kw={"lagerfeuer","camping","lagerplatz","kochkunst","einrichtungsgegenstände","shen'dar","zerril softbreeze"},ang={["profession:Cooking"]="Als Koch lernt Ihr, ein Lagerfeuer im Herzen eines Lagerplatzes in der Wildnis zu entfachen."},sec={{t="Die Feuerstelle der Wildnis",b="Ein Lagerfeuer bietet Euch einen Rastplatz in ungezähmten Landen. Das Erlernen der Kochkunst beginnt damit, dieses Feuer zu entfachen. Es ist der erste Schritt, um einen sicheren Lagerplatz einzurichten."},{t="Grundlagen des Lagerplatzes",b="Sprecht mit Zerril Softbreeze in Shen'dar, um die Grundlagen der Kochkunst zu erlernen. Sobald Ihr wisst, wie Ihr ein Lagerfeuer entfacht, könnt Ihr einen kleinen Lagerplatz in der Wildnis einrichten. Ein einfaches Lager hat nur wenige Einrichtungsgegenstände. Mit zunehmender Kochkunstfertigkeit könnt Ihr größere Feuer entfachen. Andere Handwerksfertigkeiten helfen dabei, den Platz auszustatten."}},faq={{q="Was ist Camping 101: Cooking?",a="Camping 101: Cooking lehrt Euch, ein Lagerfeuer zu entfachen und einen Lagerplatz in der Wildnis einzurichten.",al={"was ist camping 101: cooking","camping kochkunst quest"}},{q="Wer ist Zerril Softbreeze?",a="Zerril Softbreeze lehrt in Shen'dar die Kochkunst und das Entfachen von Lagerfeuern.",al={"wer ist zerril softbreeze","kochkunstlehrer shen'dar"}},{q="Warum ist Kochkunst erforderlich, um ein Lager aufzuschlagen?",a="Die Kochkunst lehrt Euch, das Lagerfeuer im Herzen eines Lagerplatzes in der Wildnis zu entfachen.",al={"warum kochkunst fürs camping lernen","warum kochkunst fürs lager nötig"}},{q="Wo befindet sich Zerril Softbreeze?",a="Zerril Softbreeze ist in Shen'dar.",al={"wo ist zerril softbreeze","shen'dar standort"}},{q="Wie lassen sich Lagerplätze ausstatten?",a="Ein einfaches Lager hat wenige Einrichtungsgegenstände. Andere Handwerksfertigkeiten ermöglichen es Euch, weitere herzustellen und aufzustellen.",al={"lagerplatzausstattung","wie lager ausstatten"}},{q="Können Lagerfeuer verbessert werden?",a="Mit zunehmender Kochkunstfertigkeit könnt Ihr größere Lagerfeuer entfachen.",al={"größere lagerfeuer","lager verbessern"}}},fp="20,166,22.159.0,27.323.0,29.97.0,25.74.0,41.81.0,35.41.0,31.82.0,26.64.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="Im roten Ödland Durotars findet der Adventurer ein verlorenes Tagebuch, das für Brakk nahe Klingenhügel bestimmt ist. Seine Seiten erzählen von stillen Reisen und Nächten unter den Sternen.",h="Im roten Ödland Durotars findet der Adventurer ein verlorenes Tagebuch, das für Brakk nahe Klingenhügel...",kw={"abenteurer","brakk","lagern","durotar","tagebuch","verlorenes tagebuch","klingenhügel"},ang={["class:Hunter"]="Als Jäger wisst Ihr, wie Ihr von dem lebt, was die Natur bietet. Die liebevollen Notizen des Tagebuchs über das Lagern in der Wildnis mögen Euch vertraut vorkommen.",["faction:Horde"]="Viele neue Rekruten ziehen über Durotars trockene Pfade. Verlorene Habseligkeiten zu Wanderern wie Brakk nahe Klingenhügel zu bringen, hilft, entlang der zentralen Grenze für Ordnung zu sorgen."},sec={{t="Notizen eines Wanderers",b="Ein verlorenes Tagebuch liegt im roten Staub Durotars, fern der Schlachten und Feldzüge, die das Land prägen. Ein unbekannter Reisender füllt seine Seiten mit täglichen Reisen und der Freude daran, unter freiem Himmel zu lagern. Das Tagebuch gewährt einen stillen Einblick in das Leben unterwegs in einem rauen Land."},{t="Übergabe an Brakk",b="Das Tagebuch ist für Brakk bestimmt, einen Abenteurer, der nahe Klingenhügel lagert. Seine Seiten verbinden einen unbekannten Reisenden mit jemandem, der über die staubigen Straßen wacht. Es zu Brakk zu bringen, könnte die Erinnerung an die Reisen des Verfassers bewahren."}},faq={{q="Was steht im verlorenen Tagebuch?",a="Das Tagebuch enthält tägliche Einträge über die Reisen eines wenig bekannten Abenteurers, mit liebevollen Notizen über das Lagern in der Wildnis.",al={"was steht im tagebuch","inhalt des verlorenen tagebuchs","tagebuchtext"}},{q="Wer hat das Tagebuch geschrieben?",a="Die wiedergefundenen Seiten nennen ihren Verfasser nicht. Sie beschreiben das Leben und die Reisen eines unbekannten Abenteurers.",al={"wer ist der abenteurer","verfasser des verlorenen tagebuchs","wer hat dieses buch geschrieben"}},{q="Wer ist Brakk?",a="Brakk ist ein Abenteurer, der nahe Klingenhügel im Zentrum Durotars lagert, und das Tagebuch ist für ihn bestimmt.",al={"brakk klingenhügel","wer ist brakk","wo ist brakk"}},{q="Wo wird das Tagebuch gefunden?",a="Das Tagebuch liegt verlassen im roten Staub Durotars, wo ein vorbeiziehender Reisender der Horde es finden kann.",al={"wo ist das tagebuch zu finden","fundort des verlorenen tagebuchs","abenteurer queststart"}},{q="Warum liegt Brakk etwas an diesem Tagebuch?",a="Das Tagebuch nennt keinen Grund dafür, warum Brakk etwas daran liegen sollte. Er ist ein Abenteurer, der direkt vor Klingenhügel lagert und Neuankömmlingen die Grundlagen des Lagerns beibringt, und das Tagebuch erzählt vom Lagern.",al={"warum zu brakk bringen","brakks aufgabe","brakk tagebuch"}},{q="Ist der Abenteurer, der es geschrieben hat, in Gefahr?",a="Die Seiten liefern keine Hinweise auf ein Verbrechen und erzählen mit Freude vom Lagern. Der Verfasser könnte das Tagebuch versehentlich verloren haben oder unerwartet weitergezogen sein.",al={"lebt der verfasser","ist der abenteurer gestorben","status des verschollenen abenteurers"}}},fp="14,158,18.287.0,17.206.0,32.121.0,22.106.0,13.99.0,27.95.0,39.185.0,41.136.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="In Klingenhügel zeigt Cook Torka Reisenden, wie sie kochen und ein Lagerfeuer entfachen. Mit diesen Fertigkeiten können sie Lager in der Wildnis errichten.",h="In Klingenhügel zeigt Cook Torka Reisenden, wie sie kochen und ein Lagerfeuer entfachen.",kw={"lagerfeuer","camping 101","camping 101: cooking","lagerplatz","cook torka","kochkunst","durotar","einrichtungsgegenstände","klingenhügel"},ang={["faction:Horde"]="Als Abenteurer der Horde, der in Durotar beginnt, könnt Ihr Cook Torka in Klingenhügel aufsuchen, um die Grundlagen des Kochens zu erlernen.",["profession:Cooking"]="Kochkunst wird benötigt, um ein einfaches Lagerfeuer zu entfachen, die Grundlage für das Überleben in der Wildnis und das Einrichten eines Lagerplatzes."},sec={{t="Die Feuerstelle der Wildnis",b="Jenseits der Tore einer Siedlung braucht es zum Überleben in der Wildnis mehr als scharfen Stahl und eine robuste Rüstung. In Klingenhügel lehrt Cook Torka angehende Abenteurer das Kochen. In Durotar und darüber hinaus bedeutet Kochen mehr als die Zubereitung einer warmen Mahlzeit. Es lehrt Reisende auch, ein zuverlässiges Lagerfeuer zu entfachen, das Herzstück jedes Lagerplatzes."},{t="Ein Lager errichten und ausstatten",b="Sobald Reisende die Grundlagen beherrschen, können sie fast überall im Grenzland ein bescheidenes Lager aufschlagen. Das Lagerfeuer eines Anfängers reicht nur für wenige grundlegende Einrichtungsgegenstände aus. Größere Kochfertigkeit erlaubt es Reisenden, größere Feuer zu entfachen. Andere Handwerke lehren sie, die nötigen Dinge herzustellen, um ein Lager auszustatten und zu einem zuverlässigen Schutz vor der Wildnis auszubauen."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Camping 101: Cooking vermittelt Abenteurern die Grundlagen des Überlebens in der Wildnis. Wenn sie kochen und ein Lagerfeuer entfachen lernen, können sie Lager in der Wildnis errichten.",al={"was ist camping 101 cooking","camping 101 cooking quest","was bewirkt diese quest"}},{q="Wer ist Cook Torka?",a="Cook Torka ist der Kochkunstlehrer der Horde in Klingenhügel in Durotar. Er vermittelt angehenden Abenteurern die Grundlagen des Kochens und zeigt ihnen, wie sie ein Lagerfeuer entfachen.",al={"wer lehrt kochkunst in klingenhügel","wer ist cook torka","wo ist cook torka"}},{q="Warum braucht man zum Lagern Kochkunst?",a="Kochkunst lehrt Reisende, das Lagerfeuer zu entfachen, das den Mittelpunkt eines Lagerplatzes bildet. Ohne Feuer können sie keinen richtigen Lagerplatz in der Wildnis unterhalten.",al={"warum braucht man kochkunst zum lagern","zusammenhang zwischen kochkunst und lagerfeuer","braucht man kochkunst zum lagern"}},{q="Wo kann ein Abenteurer einen Lagerplatz einrichten?",a="Sobald Ihr die Grundlagen des Kochens und des Entfachens eines Lagerfeuers beherrscht, könnt Ihr fast überall in der offenen Wildnis einen kleinen Lagerplatz einrichten. Anfangs bietet er nur Platz für wenige Einrichtungsgegenstände.",al={"wo kann man lagern","wie funktioniert das lagern","lagerplatz einrichten"}},{q="Wie verbessert Ihr Euer Lagerfeuer?",a="Wenn Ihr Eure Kochfertigkeit verbessert, könnt Ihr lernen, größere, länger brennende Lagerfeuer zu entfachen und Euren Lagerplatz um weitere Möglichkeiten zu erweitern.",al={"größere lagerfeuer","lagerfeuer verbessern","wie verbessert man den lagerplatz"}},{q="Wie erhält man Einrichtungsgegenstände für einen Lagerplatz?",a="Kochkunst liefert mit dem Lagerfeuer die Grundlage, während andere Handwerkslehrer überall auf der Welt Abenteurern beibringen, Einrichtungsgegenstände für ihre Lagerplätze herzustellen und aufzustellen.",al={"lagerplatzdekoration","lager ausstatten","lehrer für lagereinrichtung"}}},fp="20,131,22.315.0,30.329.0,39.148.0,18.139.0,36.149.0,42.177.0,33.133.0,45.155.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="Nahe Todesend wird The Adventurer entsandt, um eine Fremde an der Straße nach Brill zu überprüfen. Kreuzfahrer des Scharlachroten Kreuzzugs bedrohen die Region, doch die Fremde ist Eleanor Shackleton, eine reisende Verlassene, die Überlebensfertigkeiten für die Wildnis lehren kann.",h="Nahe Todesend wird The Adventurer entsandt, um eine Fremde an der Straße nach Brill zu überprüfen.",kw={"brill","lagern","todesend","eleanor shackleton","exekutor arren","scharlachroter kreuzzug","the adventurer","the great outdoors","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr von umherziehenden Reisenden praktische Überlebensfertigkeiten lernen, während Exekutor Arren die noch jungen Grenzen des Reichs der Verlassenen bewacht.",["race:Undead"]="Als neuer Verlassener nahe Todesend zeigt Euch die Begegnung mit Eleanor, einer Mitabenteurerin, dass eine Fremde nahe Brill keine Spionin des Scharlachroten Kreuzzugs sein muss."},sec={{t="Ein misstrauischer Wächter",b="Exekutor Arren wacht über Todesend und die umliegenden Straßen. Kreuzfahrer des Scharlachroten Kreuzzugs spähen die Region aus und infiltrieren das nördliche Lordaeron, weshalb eine unbekannte Gestalt nahe Brill seinen Verdacht erregt. Ihr habt Eure Hingabe bewiesen, indem Ihr gegen Bedrohungen durch die Kreuzfahrer entlang der Grenze vorgegangen seid. Nun bittet Arren Euch, die Fremde unauffällig zu überprüfen und herauszufinden, ob sie die Verlassenen bedroht."},{t="Eine Reisende im Wald",b="Am Straßenrand nahe Brill findet Ihr Eleanor Shackleton. Sie ist eine reisende Verlassene, die vor ihrer nächsten Reise in die Wildnis rastet. Sie führt weder Ränke des Kreuzzugs noch Nekromantie der Geißel im Schilde. Eleanor erkennt in Euch, die Ihr zu ihrer Überprüfung entsandt wurdet, einen Mitabenteurer und bietet an, Euch das Überleben im offenen Gelände und das Lageraufschlagen beizubringen."}},faq={{q="Warum will Exekutor Arren Eleanor überprüfen lassen?",a="Eindringlinge des Scharlachroten Kreuzzugs und feindliche Spione bedrohen Todesend und Brill. Arren misstraut allen Unbekannten auf der Landstraße, bis ihre Absichten klar sind.",al={"warum eleanor überprüfen","wer schickt zu eleanor","arren eleanor auftrag"}},{q="Wer ist Eleanor Shackleton?",a="Eleanor Shackleton ist eine Abenteurerin der Verlassenen, die an der Straße nahe Brill lagert. Sie erkundet die Wildnis und vermittelt Mitreisenden praktische Überlebensfertigkeiten.",al={"wer ist eleanor","eleanor shackleton hintergrundgeschichte","wer ist der npc the adventurer"}},{q="Steht Eleanor mit dem Scharlachroten Kreuzzug in Verbindung?",a="Nein. Eleanor hat keine Verbindungen zum Scharlachroten Kreuzzug, dessen Fanatiker Tirisfal bedrohen.",al={"gehört eleanor zum scharlachroten kreuzzug","eleanor feindin","ist eleanor eine spionin"}},{q="Wohin führt diese Aufgabe?",a="Das Gespräch mit Eleanor führt zu The Great Outdoors. Dort beginnt sie, Euch das Überleben in der Wildnis und das Lageraufschlagen beizubringen.",al={"was kommt nach the adventurer","nächste aufgabe nach adventurer","eleanor shackleton folgeaufgabe"}},{q="Wo ist Eleanor Shackleton zu finden?",a="Eleanor lagert in Tirisfal unweit der Hauptstraße, die nach Osten in Richtung Brill führt.",al={"eleanor standort","wo ist eleanor shackleton","eleanor lager tirisfal"}},{q="Warum hat Exekutor Arren Euch für diese Mission ausgewählt?",a="Ihr habt Arrens Vertrauen gewonnen, indem Ihr Agenten und Boten des Scharlachroten Kreuzzugs nahe Todesend aufgespürt und ausgeschaltet habt. Diese Arbeit hat gezeigt, dass Ihr heikle Erkundungsaufträge bewältigen könnt.",al={"warum ausgewählt","arren vertrauen","warum exekutor arren jemanden entsendet"}}},fp="14,219,18.368.0,23.319.0,50.157.0,26.158.0,44.87.0,27.123.0,38.74.0,51.154.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="Wenn Ihr kochen lernt, bietet Euch ein einfaches Lagerfeuer eine Feuerstelle für Euer Lager jenseits befestigter Mauern. In den Landen der Allianz und der Horde zeigen Kochlehrer neuen Abenteurern, wie sie eines entzünden und sich auf das Leben in der Wildnis vorbereiten.",h="Wenn Ihr kochen lernt, bietet Euch ein einfaches Lagerfeuer eine Feuerstelle für Euer Lager jenseits...",kw={"lagerfeuer","camping 101","kochen","goldhain","shackleton","tomas","wildnis","zarrin"},ang={["faction:Alliance"]="Wenn Ihr als Abenteurer der Allianz Nordhain, Dun Morogh oder Teldrassil verlasst, werdet Ihr zu Orten wie Goldhain, Kharanos und Dolanaar geführt. Dort lernt Ihr, Euch selbst zu versorgen, bevor Ihr Euch in die Wildnis wagt.",["faction:Horde"]="Als junger Kämpfer der Horde in Durotar, Mulgore oder Tirisfal werdet Ihr zu Lagerfeuern in Klingenhügel, im Dorf der Bluthufe oder in Brill geführt.",["profession:Cooking"]="Die Kochkunst liefert Nahrung, die Eure Kräfte wiederherstellt, und ein einfaches Lagerfeuer als Herzstück eines Lagers im Freien."},sec={{t="Die Feuerstelle der Wildnis",b="Jenseits befestigter Mauern bringt ein Lagerfeuer Wasser zum Kochen und brät Fleisch. Seine Flammen bieten Euch eine Feuerstelle, wenn Ihr durch unbekanntes Land reist und Euer Lager aufschlagt."},{t="Von Glut zu Lagern",b="Kochlehrlinge entzünden kleine Feuer mit wenig Ausstattung ringsum. Mit wachsender Kochkunst könnt Ihr größere Feuer für aufwendigere Lagerplätze entzünden. Andere praktische Handwerke lehren Euch, nützliche Einrichtungsgegenstände herzustellen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Neue Abenteurer besuchen einen Kochlehrer in einer nahe gelegenen Siedlung, um die Grundlagen des Kochens zu erlernen und ein einfaches Lagerfeuer für ein Lager im Freien zu entzünden.",al={"warum camping 101 machen","camping 101 kochen zweck","was bringt diese quest"}},{q="Wer bietet Reisenden diese Quest an?",a="Erfahrene Wildnisführer und Abenteurer bieten diese Ausbildung bei beiden Fraktionen an. Zu ihnen zählen Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof und Raan Wildwind.",al={"wer vergibt camping 101","lagerquest questgeber"}},{q="Wo geben Spieler der Allianz diese Quest ab?",a="Abenteurer der Allianz melden sich bei Lehrern in ihren Heimatgebieten, etwa bei Tomas in Goldhain, Gremlock Pilsnor in Kharanos oder Zarrin in Dolanaar.",al={"wo abgeben allianz","allianz kochlehrer"}},{q="Wo geben Spieler der Horde diese Quest ab?",a="Abenteurer der Horde können bei Cook Torka in Klingenhügel, William Pickman in Brill oder Pyall Silentstride im Dorf der Bluthufe lernen.",al={"horde kochlehrer","wo abgeben horde"}},{q="Lässt sich der Lagerplatz später vergrößern?",a="Ja. Mit größerem Können in der Kochkunst lernt Ihr, größere Feuer zu entzünden, die mehr Einrichtungsgegenstände für Euer Lager in der Wildnis ermöglichen.",al={"größeres lagerfeuer","lager verbessern"}},{q="Können andere Berufe zum Lagerbau beitragen?",a="Ja. Die Kochkunst liefert das einfache Lagerfeuer, während andere Handwerke Euch lehren, praktische Einrichtungsgegenstände herzustellen, sofern Ihr Euch darin geübt habt.",al={"berufe für den lagerbau","lagereinrichtung"}}},fp="20,216,28.150.0,26.199.0,34.137.0,35.217.0,39.147.0,36.128.0,36.109.0,44.129.0"}
P.entries["quest:96659"] = {n="The Adventurer",s="Von der Hochwolkenebene schickt Häuptling Falkenwind junge Reisende mit Vorräten zu Kaga Wildhoof nahe dem Dorf der Bluthufe. Sie half ihm vor langer Zeit, und er will ihre Güte vergelten.",h="Von der Hochwolkenebene schickt Häuptling Falkenwind junge Reisende mit Vorräten zu Kaga Wildhoof nahe dem...",kw={"dorf der bluthufe","camp narache","häuptling falkenwind","kaga wildhoof","mulgore","die hochwolkenebene","vorratsbündel","the adventurer"},ang={["faction:Horde"]="Als Reisender der Horde verlasst Ihr die Hochwolkenebene und bringt Vorräte zu Kaga Wildhoof, einer erfahrenen Wanderin nahe dem Dorf der Bluthufe.",["race:Tauren"]="Als junger Tauren bringt Ihr Falkenwinds Vorräte zu Kaga Wildhoof, über Camp Narache hinaus in die Ebenen von Mulgore."},sec={{t="Die Schuld eines Häuptlings",b="Häuptling Falkenwind bittet Euch, Kaga Wildhoof nahe dem Dorf der Bluthufe Vorräte zu bringen. Vor langer Zeit half sie ihm in der Not, und er erinnert sich an ihre Güte. Nun hat sie vor dem Dorf ihr Lager aufgeschlagen. Daher vertraut Falkenwind jungen Reisenden, die die Hochebene verlassen, Vorräte für seine einstige Wohltäterin an."},{t="Aufbruch von der Hochebene",b="Der Pfad führt von der Hochwolkenebene zum Dorf der Bluthufe, über die Ebenen von Mulgore. Mit Falkenwinds Bündel reist Ihr über Camp Narache hinaus, wo junge Tauren ausgebildet wurden. Der Weg führt in die weiten Lande der Vereinigten Taurenstämme."}},faq={{q="Wer ist Kaga Wildhoof?",a="Kaga Wildhoof ist eine erfahrene Taurenabenteurerin, die direkt vor dem Dorf der Bluthufe lagert. Sie half Häuptling Falkenwind in der Vergangenheit.",al={"kaga wildhoof","wer ist wildhoof","wo ist kaga"}},{q="Warum schickt Häuptling Falkenwind diese Vorräte?",a="Häuptling Falkenwind schickt die Vorräte, um Kaga Wildhoof die Hilfe zu vergelten, die sie ihm vor langer Zeit leistete.",al={"falkenwinds schuld","warum vorräte schicken","zweck des vorratsbündels"}},{q="Wo liegt Kaga Wildhoofs Lager?",a="Kaga Wildhoofs Lager liegt direkt vor dem Dorf der Bluthufe, den Pfad von der Hochwolkenebene hinab ins Zentrum von Mulgore.",al={"kagas lagerstandort","kaga finden","lager beim dorf der bluthufe"}},{q="Wann wird diese Quest verfügbar?",a="Häuptling Falkenwind bietet Euch diese Aufgabe an, wenn Ihr Euch auf der Hochwolkenebene bewährt habt und bereit seid, nach Mulgore aufzubrechen.",al={"wann ist the adventurer verfügbar","wann falkenwinds quest","quest zum verlassen der hochebene"}},{q="Führt Euch diese Quest von Camp Narache fort?",a="Ja. Ihr tragt die Vorräte von Camp Narache den Pfad hinab zum Dorf der Bluthufe.",al={"hoch wolkenebene verlassen","reise zu den bluthufen"}},{q="Was enthält das Vorratsbündel?",a="Das Vorratsbündel enthält lebenswichtige Vorräte für einen Abenteurer, der jenseits der Siedlungen unterwegs ist.",al={"was sind die vorräte","inhalt des vorratsbündels"}}},fx={["2c6e5885"]={q="Warum bittet Euch Häuptling Falkenwind, die Vorräte zu liefern?",a="Ihr habt Eure anfänglichen Riten in Die Hochwolkenebene abgeschlossen und bereitet Euch darauf vor, Camp Narache zu verlassen, um in die weiteren Ebenen von Mulgore vorzustoßen. Da Eure Abreise Euch ohnehin am Dorf der Bluthufe vorbeiführt, betraut Euch Häuptling Falkenwind mit diesem Botengang, anstatt tapfere Krieger zu entsenden, die benötigt werden, um die Ebene zu bewachen und die jungen Tauren zu schützen, die dort trainieren.",al={"warum ich falkenwind","warum mich mit vorräten schicken","warum wählt mich falkenwind"}}},fp="14,173,23.296.0,16.244.0,21.122.0,44.92.0,38.111.0,38.117.0,48.86.0,43.94.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="Im Dorf der Bluthufe beginnt Pyall Silentstride, Euch im Kochen und im Entfachen von Lagerfeuern zu unterweisen. In ganz Kalimdor helfen Euch diese Fertigkeiten, ein Lager aufzuschlagen und Mahlzeiten aus erlegtem Wild zuzubereiten.",h="Im Dorf der Bluthufe beginnt Pyall Silentstride, Euch im Kochen und im Entfachen von Lagerfeuern zu...",kw={"dorf der bluthufe","lagerfeuer","camping 101","lagerplatz","kochen","einrichtung","pyall leisetreter","wildnis"},ang={["faction:Horde"]="Als Reisender der Horde in Mulgore beginnt Ihr Eure Überlebensausbildung im Dorf der Bluthufe, wo Euch Handwerker und Köche der Tauren anleiten können.",["profession:Cooking"]="Als Koch lernt Ihr, das Lagerfeuer im Herzen eines Lagerplatzes zu entfachen und Nahrung für die Wildnis zuzubereiten."},sec={{t="Der Herd der Wildnis",b="Wenn die Nacht hereinbricht, bietet Euch ein Lagerfeuer einen Ort, an den Ihr zurückkehren könnt. In ganz Kalimdor lernt Ihr mit den Grundlagen des Kochens, in der Wildnis ein Feuer zu entfachen. Ihr lernt auch, nahrhafte Mahlzeiten aus erlegtem Wild zuzubereiten, wodurch das Kochen zum Überleben im Freien beiträgt."},{t="Das Errichten des Lagers",b="Im Dorf der Bluthufe in Mulgore lehrt Euch Pyall Silentstride die Grundlagen des Kochens. Mit dieser Ausbildung könnt Ihr ein Lagerfeuer entfachen und ein einfaches Lager in der Wildnis aufschlagen. Mit zunehmender Kochfertigkeit lernt Ihr, größere Feuer zu entfachen. Andere Handwerke können Euren Außenposten mit Einrichtung versorgen."}},faq={{q="Was ist Camping 101: Cooking?",a="Beim Kochen lernt Ihr, ein Lagerfeuer zu entfachen und einen Lagerplatz in der Wildnis einzurichten.",al={"was ist camping 101 cooking","camping kochquest","camping grundlagen kochen"}},{q="Wer ist Pyall Silentstride?",a="Pyall Silentstride lehrt im Dorf der Bluthufe in Mulgore das Kochen. Er zeigt unerfahrenen Abenteurern, wie sie kochen und einfache Lagerfeuer entfachen.",al={"wer ist pyall leisetreter","pyall leisetreter aufenthaltsort","bluthufe kochlehrer"}},{q="Warum ist Kochen notwendig, um das Campen zu erlernen?",a="Beim Kochen lernt Ihr, ein Lagerfeuer als praktisches Herzstück eines Lagerplatzes zu entfachen und Mahlzeiten zuzubereiten.",al={"warum kochen für camping nötig ist","warum kochen lernen fürs campen","lagerfeuer camping verbindung"}},{q="Könnt Ihr größere Lagerfeuer entfachen, wenn sich Eure Fertigkeit verbessert?",a="Mit zunehmender Kochfertigkeit lernt Ihr, größere Feuer für umfangreichere Lager zu entfachen.",al={"kann ich lagerfeuer aufwerten","größere lagerfeuer","wie man größere feuer macht"}},{q="Wie richtet Ihr einen Lagerplatz ein?",a="Andere Handwerke können Einrichtungsgegenstände für Euren Lagerplatz liefern. Ihr könnt sie herstellen, wenn Ihr diese Handwerke erlernt habt.",al={"wie lagerplatz einrichtung funktioniert","lagerplatz dekorationen","lagerplätze einrichten berufe"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Sobald Ihr beim Kochen gelernt habt, ein Lagerfeuer zu entfachen, könnt Ihr auf Euren Reisen überall in der offenen Wildnis ein einfaches Lager aufschlagen.",al={"wo lager aufschlagen","kann ich überall campen","lagerplatz einschränkungen"}}},fp="20,177,22.243.0,17.274.0,29.84.0,26.132.0,42.95.0,53.95.0,30.107.0,28.125.0"}
P.entries["quest:967"] = {n="Der Turm von Althalaxx",s="Am Turm von Althalaxx sammeln sich Kultisten des Dunklen Strands, und Balthule Schattenhieb braucht Hilfe. Er schickt mit einem Kurier der Allianz eine Warnung an seinen Mentor, Delgren den Läuterer, zu Maestras Posten in Eschental.",h="Am Turm von Althalaxx sammeln sich Kultisten des Dunklen Strands, und Balthule Schattenhieb braucht Hilfe.",kw={"eschental","balthule schattenhieb","dunkler strand","dunkelküste","delgren der läuterer","heiliges licht","maestras posten","turm von althalaxx"},ang={["class:Paladin"]="Als Paladin könnt Ihr Euch Delgren als Vorbild für Eure heilige Berufung in fremden Landen nehmen. Der menschliche Kreuzfahrer wirkt mit dem Licht und hat das Vertrauen der zurückgezogen lebenden Nachtelfen Kalimdors gewonnen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie Balthule in Dunkelküste und Delgren in Eschental die verstreuten Garnisonen der Allianz im nördlichen Kalimdor miteinander in Verbindung halten.",["race:NightElf"]="Als Nachtelf könnt Ihr sehen, wie Eure Schildwachen eine zweckmäßige Partnerschaft mit Verbündeten aus dem Osten aufbauen, die dämonische Überreste aus Euren Wäldern tilgen wollen."},sec={{t="Eine Bitte um Verstärkung",b="Balthule Schattenhieb erkennt, dass ein einzelner Späher der Bedrohung durch den Dunklen Strand nicht allein begegnen kann. Nach Zusammenstößen mit Kultisten nahe dem Turm von Althalaxx schreibt er einen Bericht für seinen Meister, Delgren den Läuterer, und übergibt ihn einem Boten der Allianz. Die Beschwörer des Kults werden dreister. Balthule braucht erfahrene Anführer, die eine Gegenwehr leiten können."},{t="Der Weg nach Eschental",b="Balthules Depesche führt Euch auf der Küstenstraße von Dunkelküste nach Süden und dann über die bewaldete Grenze nach Eschental. Delgren der Läuterer ist an Maestras Posten neben der westlichen Straße stationiert. Der menschliche Paladin arbeitet daran, das Waldland von Dämonen und Untoten zu säubern. Die Bräuche der Nachtelfen erschienen ihm einst fremd, doch als unverzichtbarer Verbündeter hat er sich den tiefen Respekt der Schildwachen verdient."},{t="Ein heiliger Krieger erwacht",b="Delgren der Läuterer empfängt Balthules dringlichen Brief und liest ihn mit grimmiger Entschlossenheit. Dem Heiligen Licht ergeben, sieht er in dunklen Kultisten, verderbten Seelen und dämonischen Unholden in den uralten Wäldern eine unerträgliche Plage. Der Brief berichtet vom fest etablierten Stützpunkt des Dunklen Strands im verfallenen Turm der Hochgeborenen. Delgren bereitet sich darauf vor, die Führung zu übernehmen und zurückzuschlagen."}},faq={{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein menschlicher Paladin, der an Maestras Posten in Eschental stationiert ist. Dem Heiligen Licht ergeben, unterstützt er mit kämpferischem und geistlichem Können die Schildwachen der Nachtelfen im Kampf gegen Dämonen und Untote in ihren angestammten Wäldern.",al={"delgren der läuterer","wer ist delgren","delgrens geschichte"}},{q="Warum schickt Balthule Schattenhieb einen Boten nach Eschental?",a="Balthule Schattenhieb ist ein Späher vor dem Turm von Althalaxx, wo er den Kult des Dunklen Strands erforscht. Da dessen dunkle Rituale und Mitgliederzahl zunehmen, schickt er seine Erkenntnisse an seinen Mentor Delgren, damit sie einen Angriff organisieren können.",al={"warum einen brief an delgren schicken","grund für balthules brief"}},{q="In welcher Beziehung stehen Balthule und Delgren zueinander?",a="Delgren ist Balthules Meister. Der menschliche Paladin unterwies den Nachtelfen in der Kampfkunst und den Lehren des Heiligen Lichts. Trotz ihrer kulturellen Unterschiede verbindet sie ein enges Band.",al={"balthule und delgren","woher kennen sich balthule und delgren"}},{q="Wo liegt Maestras Posten?",a="Maestras Posten ist ein Außenposten der Allianz im westlichen Eschental, neben der Hauptstraße, die von Dunkelküste nach Süden führt. Reisende kommen auf ihrem Weg in den Wald daran vorbei.",al={"maestras posten lage","wo liegt maestras posten"}},{q="Was tut der Kult des Dunklen Strands am Turm von Althalaxx?",a="Der Kult des Dunklen Strands operiert vom verfallenen Turm von Althalaxx aus, einem Bau der Hochgeborenen im Norden von Dunkelküste. Seine Mitglieder üben dunkle Künste aus und verkehren mit dämonischen Mächten. Sie drohen, Verderbnis entlang der Küste zu verbreiten.",al={"kult des dunklen strands althalaxx","turm von althalaxx kultisten"}},{q="Wie sieht Delgren sein Bündnis mit den Nachtelfen?",a="Als Delgren in Kalimdor ankam, waren ihm die Sitten und Gebräuche der Nachtelfen fremd. Der gemeinsame Kampf gegen das Böse hat den Schildwachen seinen tiefen Respekt eingebracht.",al={"delgren nachtelfen","menschlicher paladin nachtelfen"}}},fx={["4ad41352"]={q="Warum wählt Balthule Schattenhieb Euch als seinen Boten, anstatt selbst zu gehen?",a="Balthule muss in der Nähe von The Tower of Althalaxx stationiert bleiben, um ein wachsames Auge auf die Kultisten von Dark Strand zu haben und ihre eskalierende Bedrohung zu überwachen. Da sich die Reise über die gesamte Länge der Dunkelküste bis ins Eschental erstreckt, benötigt er einen fähigen und gut bewaffneten Reisenden, der auf den gefährlichen Straßen überleben und garantieren kann, dass die dringende Warnung sicher Delgrens Hände erreicht.",al={"warum schickt ihr mich zu delgren","warum balthule bote","warum kann balthule den brief nicht überbringen"}}},fp="22,206,25.325.0,21.382.0,23.356.1,28.234.0,62.216.0,54.179.0,24.149.0,61.217.0,56.159.0"}
P.entries["quest:96773"] = {n="The Coldbringer's Eye",s="Die Kirin Tor suchen das Coldbringer’s Eye, eine Spähkugel, die ein Diener des Lich King in den Hügeln der Klingenhauer nutzt. Ihr werdet gebeten, sie zu bergen, damit das Artefakt untersucht werden kann.",h="Die Kirin Tor suchen das Coldbringer’s Eye, eine Spähkugel, die ein Diener des Lich King in den Hügeln der...",kw={"coldbringer","coldbringer's eye","kirin tor","lich king","stacheleber","hügel der klingenhauer","spähkugel","diener"},sec={{t="Eine Bitte der Kirin Tor",b="Ein Diener des Lich King haust in den Hügeln der Klingenhauer, wo ihm der Bau der Stacheleber Schutz bietet. Die Kirin Tor sagen, er nutze das Coldbringer’s Eye, um niedere Diener andernorts zu lenken. Ihr werdet gebeten, die Kugel für ihre Untersuchungen zu beschaffen."}},faq={{q="Was ist das Coldbringer’s Eye?",a="Das Coldbringer’s Eye ist eine Spähkugel, die ein Diener des Lich King in den Hügeln der Klingenhauer nutzt.",al={"coldbringer auge","was ist das auge","spähkugel"}},{q="Wer will das Coldbringer’s Eye?",a="Die Kirin Tor wollen das Coldbringer’s Eye, um das Artefakt zu untersuchen und seine Funktionsweise zu verstehen.",al={"wer will die kugel","kirin tor auge","wer hat darum gebeten"}},{q="Wo ist das Coldbringer’s Eye?",a="Das Coldbringer’s Eye befindet sich in den Hügeln der Klingenhauer.",al={"wo ist das auge","hügel der klingenhauer kugel","auge fundort"}},{q="Wer nutzt die Kugel?",a="Ein Diener des Lich King in den Hügeln der Klingenhauer nutzt die Kugel, um niedere Diener andernorts zu lenken.",al={"wer hat das auge","diener des lich king","coldbringer nutzer"}}},fp="21,172,19.228.0,32.94.0,34.101.0,33.45.0,17.93.0"}
P.entries["quest:96781"] = {n="What's the Big Idea?",s="Myrokos Silentform im Rabenholdtanwesen bittet Euch herauszufinden, was das Syndikat in den Ruinen von Alterac sucht. Barton trägt die Spähberichte bei sich, die ihre Absichten enthüllen könnten.",h="Myrokos Silentform im Rabenholdtanwesen bittet Euch herauszufinden, was das Syndikat in den Ruinen von...",kw={"barton","myrokos silentform","rabenholdtanwesen","die ruinen von alterac","spähbericht","strahnbrad","syndikat"},ang={["class:Rogue"]="Als Schurke sollt Ihr Bartons Bericht an Euch nehmen, ohne ihn zu töten."},sec={{t="Bartons Bericht",b="Im Rabenholdtanwesen benötigt Myrokos Silentform Bartons Spähbericht. Eine vom Syndikat entsandte Gruppe unter Bartons Führung durchstreift die Ruinen von Alterac und sucht nach etwas. Ihr sollt ihm den Bericht abnehmen, ohne ihn zu töten, damit das Syndikat nicht erfährt, dass seine Pläne bemerkt wurden."}},faq={{q="Wer ist Barton?",a="Barton führt eine Spähergruppe des Syndikats an, die in den Ruinen von Alterac umherstreift.",al={"barton","wer ist barton","späher des syndikats"}},{q="Wonach sucht das Syndikat?",a="Die Gruppe des Syndikats sucht in den Ruinen von Alterac nach etwas, doch Myrokos benötigt Bartons Spähbericht, um herauszufinden, wonach.",al={"wonach sucht das syndikat","wonach suchen sie","suche des syndikats"}},{q="Warum will Myrokos den Bericht?",a="Myrokos Silentform will mit dem Bericht herausfinden, wonach das Syndikat sucht.",al={"warum den bericht holen","bartons bericht","die große idee"}},{q="Warum Barton nicht töten?",a="Stirbt Barton, erkennt das Syndikat, dass es beobachtet wird, und könnte seine Spuren verwischen.",al={"barton nicht töten","barton bestehlen","warum den bericht stehlen"}},{q="Wo ist Barton zu finden?",a="Barton hält sich vermutlich bei den Mitgliedern des Syndikats in Strahnbrad auf.",al={"wo ist barton","barton finden","späher in strahnbrad"}},{q="Wohin soll der Bericht gebracht werden?",a="Bartons Spähbericht ist für Myrokos Silentform im Rabenholdtanwesen bestimmt.",al={"wer bekommt den bericht","wohin den bericht bringen","myrokos"}}},fp="20,173,17.280.0,14.77.0,36.129.0,33.81.0,20.107.0,26.56.0,25.77.0"}
P.entries["quest:96783"] = {n="A Way In",s="Ein Handel des Syndikats führt Euch zur Burg Stromgarde im Arathihochland. Ihr braucht eine Verkleidung vom Nordhof, um unverdächtig hineinzukommen.",h="Ein Handel des Syndikats führt Euch zur Burg Stromgarde im Arathihochland.",kw={"ein weg hinein","arathihochland","nordhof","burg stromgarde","syndikat","handel","uniform"},sec={{t="Ein geheimer Handel",b="Eine Kontaktperson schickt Euch zur Burg Stromgarde im Arathihochland, wo das Syndikat hinter den Mauern wichtige Geschäfte abwickelt. Die Kontaktperson hat von einem Handel zwischen Mitgliedern des Syndikats erfahren, dessen Einzelheiten sich in der Burg finden könnten. Um keinen Verdacht zu erregen, braucht Ihr eine Uniform des Syndikats vom Nordhof."}},faq={{q="Was geschieht in der Burg Stromgarde?",a="Das Syndikat nutzt die Burg Stromgarde als eine seiner größten Festungen, und irgendwo im Arathihochland findet ein Handel zwischen seinen Mitgliedern statt.",al={"stromgarde handel","was ist in stromgarde","syndikat burg"}},{q="Warum gehe ich zum Nordhof?",a="Ihr sucht auf dem Nordhof nach einer Uniform des Syndikats, um Euch vor dem Betreten der Burg Stromgarde zu verkleiden.",al={"nordhof","warum nordhof","verkleidung besorgen"}},{q="Was brauche ich, um in die Burg zu gelangen?",a="Ihr braucht eine Uniform des Syndikats vom Nordhof, um die Burg Stromgarde zu betreten, ohne Verdacht zu erregen.",al={"uniform","syndikat verkleidung","zugang zu stromgarde"}},{q="Worum geht es bei dem Handel des Syndikats?",a="Der Handel findet zwischen Mitgliedern des Syndikats irgendwo im Arathihochland statt. Seine Einzelheiten könnten in der Burg Stromgarde zu finden sein.",al={"syndikat geschäft","welcher handel","einzelheiten des handels"}}},fp="8,144,14.314.0,37.152.0,34.112.0,33.102.0,34.122.0"}
P.entries["quest:968"] = {n="Werkzeuge der Hochgeborenen",s="Thundris Windwirker schickt Euch von Auberdine nach Ameth'Aran. Geister der Hochgeborenen suchen noch immer die Ruinen heim, mit verzauberten Relikten in den Händen, die er ihnen abnehmen lassen will.",h="Thundris Windwirker schickt Euch von Auberdine nach Ameth'Aran.",kw={"ameth'aran","auberdine","dunkelküste","hochgeborene","relikte","zerschlagung der welt","thundris windweaver"},ang={["class:Druid"]="Als Druide helft Ihr, verderbte arkane Überreste aus Ameth'Aran zu beseitigen und die spirituellen Wunden zu lindern, die die natürliche Ruhe der Dunkelküste stören.",["class:Mage"]="Als Magier erkennt Ihr in den Relikten vielleicht seltene, makellose Beispiele der Handwerkskunst der Hochgeborenen aus der Zeit vor der Zerschlagung der Welt. Dennoch wollen die Kaldorei sie vernichten.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr den Nachtelfen, ihre heimgesuchten Lande zu sichern, und stärkt die Präsenz und den Zusammenhalt der Allianz in den uralten Wäldern des nördlichen Kalimdor.",["race:NightElf"]="Als Kaldorei erinnern Euch die Geister von Ameth'Aran an die Hybris Eurer Vorfahren und die Zerschlagung der Welt, die ihr Reich zertrümmerte."},sec={{t="Echos in den Ruinen",b="Ameth'Aran liegt südlich von Auberdine und östlich der Küstenstraße. Seine Steinfundamente sind überwuchert. Vor zehntausend Jahren war es eine Hochburg der Hochgeborenen, der privilegierten Aristokratie des uralten Nachtelfenreichs.\n\nIhre ungezügelte arkane Magie trug zur Zerschlagung der Welt bei, die die Siedlung zerstörte. Doch ihre Bewohner sind nie wahrhaft fortgegangen. Schildwachen, die an der Dunkelküste patrouillieren, berichten von Geistern der Hochgeborenen auf den versunkenen Plätzen, die noch immer ihre verzauberten Werkzeuge und Schmuckstücke aus Lebzeiten umklammern."},{t="Die arkane Vergangenheit tilgen",b="Für die Kaldorei erinnert arkane Magie an eine Gefahr, die das Leben auf Azeroth beinahe vernichtet hätte. Thundris Windwirker fürchtet, dass die Gerätschaften der Hochgeborenen Verderbnis heraufbeschwören könnten, wenn sie in Geisterhänden bleiben. Deshalb schickt er Euch los, um den rastlosen Geistern die Relikte zu entreißen. Er will sie vernichten lassen, bevor ihre verderbte Magie eine weitere Katastrophe befeuern kann."}},faq={{q="Wo finde ich die Relikte der Hochgeborenen?",a="Die Relikte befinden sich in Ameth'Aran, südlich von Auberdine und östlich des Hauptwegs der Dunkelküste. Umherwandernde Geister tragen sie durch die verfallenen steinernen Innenhöfe.",al={"wo sind die relikte","lage von ameth'aran","wo relikte finden"}},{q="Wer ist Thundris Windwirker?",a="Thundris Windwirker ist ein Gelehrter und Ältester der Nachtelfen, der in Auberdine lebt. Gemeinsam mit den örtlichen Schildwachen schützt er die Dunkelküste vor anhaltender magischer Verderbnis und uralten Flüchen, die seit der Zerschlagung der Welt fortbestehen.",al={"thundris windweaver","wer vergibt werkzeuge der hochgeborenen"}},{q="Warum will Thundris diese Relikte vernichten lassen?",a="Thundris fürchtet, dass die arkane Macht der Relikte schlummerndes Unheil wecken könnte. Die Gesellschaft der Nachtelfen lehnt arkane Magie ab, weil die rücksichtslose Zauberei der Hochgeborenen die große Zerschlagung der Welt verursachte.",al={"warum die relikte vernichten","zweck von werkzeuge der hochgeborenen"}},{q="Was für Geister suchen Ameth'Aran heim?",a="Die Geister sind Aristokraten der Hochgeborenen, die während des War of the Ancients starben. Sie klammern sich noch immer an ihren Stolz, ihre Macht und ihre magischen Artefakte und spielen zwischen den Ruinen ihr verblasstes Leben nach.",al={"geister in ameth'aran","was sind die geister"}},{q="Warum sind die Hochgeborenen noch immer an die Ruinen gebunden?",a="Thundris weiß nicht, warum die Hochgeborenen an Ameth'Aran gebunden bleiben. Die Schildwachen haben ihm nur berichtet, dass die Geister zwischen den Ruinen verweilen und noch immer ihre uralten magischen Gerätschaften führen.",al={"warum sind sie geister","fluch der hochgeborenen"}},{q="Was geschieht mit den Relikten, nachdem Ihr sie abgegeben habt?",a="Thundris Windwirker nimmt die Relikte in Verwahrung und plant, sie zu zerlegen und zu vernichten. Er will sicherstellen, dass ihre schlummernde arkane Verderbnis niemals wieder genutzt oder freigesetzt werden kann.",al={"was macht thundris mit den relikten","schicksal der relikte"}}},fx={df86da6d={q="Was sind die Hochgeborenenrelikte?",a="Diese Relikte sind uralte magische Artefakte, die aus der Zeit vor der Großen Zerschlagung erhalten geblieben sind und einst von den Elite-Zauberern des Hofes von Königin Azshara geführt wurden. Selbst nach zehntausend Jahren bewahren sie noch immer den verbleibenden Makel des leichtsinnigen arkanen Spiels, das das alte Kalimdor zerriss. In den Händen verweilender Geister hinterlassen, bleiben sie Kanäle für ruhende, gefährliche Macht.",al={"was sind hochgeborenenrelikte","was ist ein hochgeborenenrelikt","lore zu hochgeborenenrelikten"}}},fp="22,167,19.507.0,23.350.0,37.149.0,27.204.0,46.169.0,38.187.0,47.192.0,50.176.0"}
P.entries["quest:96800"] = {n="Past Due",s="Ein Gelehrter braucht einen vermissten Folianten aus dem Scharlachroten Kloster, um Grim Batols uralte Wildhammer-Runenmeister zu erforschen.",h="Ein Gelehrter braucht einen vermissten Folianten aus dem Scharlachroten Kloster, um Grim Batols uralte...",kw={"arkanist doan","bibliothek von dalaran","grim batol","past due","das scharlachrote kloster","die verlorene magie der runenmeister","wildhammer-runenmeister"},sec={{t="Ein überfälliges Buch",b="Die Leihbücher der alten Bibliothek von Dalaran zeigen, dass Arkanist Doan den Folianten vor dem Dritten Krieg auslieh und nie zurückgab."}},faq={{q="Wer braucht das Buch?",a="Ein Gelehrter, der eine Abhandlung über die uralten Wildhammer-Runenmeister von Grim Batol schreibt, braucht das Buch für diese Forschung.",al={"wer will den folianten","forschung des gelehrten"}},{q="Welches Buch wurde ausgeliehen?",a="Das ausgeliehene Buch heißt Die verlorene Magie der Runenmeister.",al={"welcher foliant","verlorenes runenmeisterbuch"}},{q="Wer hat das Buch ausgeliehen?",a="Laut den Leihbüchern der alten Bibliothek von Dalaran lieh ein Magier namens Doan das Buch vor dem Dritten Krieg aus.",al={"wer hat es ausgeliehen","doans buch"}},{q="Wo ist das Buch?",a="Das Buch befindet sich im Scharlachroten Kloster in Tirisfal, wo Arkanist Doan sich jetzt aufhält.",al={"wo ist der foliant","fundort des buches"}},{q="Worum geht es bei der Forschung?",a="Der Gelehrte erforscht die uralten Wildhammer-Runenmeister von Grim Batol.",al={"wildhammer-runenmeister","grim batol abhandlung"}}},fp="8,113,15.121.0,19.112.0,23.62.0,22.97.0,18.84.0,27.76.0"}
P.entries["quest:96821"] = {n="Legging It",s="Die Peons haben ihren Weg nach Süden unterbrochen, weil entlang der Straße Gefahren lauern. Ihre Arbeit ruht, bis der Weg wieder sicher ist.",h="Die Peons haben ihren Weg nach Süden unterbrochen, weil entlang der Straße Gefahren lauern.",kw={"pfad freigemacht","arbeit der horde","legging it","vorarbeiter","peon-arbeit","peons","südlicher pfad"},ang={["faction:Horde"]="Der Bau und die Rohstoffgewinnung der Horde hängen stark von Peons ab, daher müssen ihre Wege sicher bleiben.",["race:Orc"]="Peons verrichten einen Großteil der Arbeit in orkischen Siedlungen. Aufseher verlassen sich auf Krieger, um Bedrohungen auf ihren Wegen zu beseitigen, damit die Arbeit weitergehen kann."},sec={{t="Sicherung der Linie",b="Peons haben ihre zugewiesene Arbeit unerledigt gelassen und ihren Weg nach Süden unterbrochen. Gefahren entlang der Straße haben die Reise zu gefährlich gemacht. Sobald die Bedrohungen zurückgedrängt sind, können die Aufseher ihre Arbeiter wieder an die Arbeit schicken."},{t="Arbeit und Routensicherheit",b="Peons verrichten einen Großteil der schweren Arbeit der Horde, vom Holzfällen und Steinbrechen bis zum Bau von Außenposten. Sie sind im Kampf wenig geübt, daher können Raubtiere oder feindliche Späher entlang der Straße den Nachschub aufhalten. Sichere Wege gewährleisten die Versorgung der Siedlungen und ermöglichen es, die Arbeit fortzusetzen."}},faq={{q="Was ist Legging It?",a="Gefahren entlang der Straße haben die Peons davon abgeschreckt, nach Süden zu reisen. Ihre Aufgaben ruhen, bis der Weg sicher ist.",al={"was ist legging it","questinfos zu legging it","quest legging it"}},{q="Warum hatten die Peons Angst, nach Süden zu reisen?",a="Die Peons fürchten die Gefahren entlang der südlichen Straße. Ohne Schutz oder einen sicheren Weg weigern sie sich, zu ihren Einsatzorten zu reisen, wodurch die Arbeit vor Ort zum Erliegen kommt.",al={"warum hatten peons angst","furcht der peons","warum peons aufhörten zu arbeiten"}},{q="Was wird durch den Abschluss der Aufgabe erreicht?",a="Wenn die südliche Route frei ist und unmittelbare Gefahren zurückgedrängt sind, können Aufseher Peons zum Sammeln von Rohstoffen und zur Arbeit im Gelände schicken.",al={"was nach legging it geschieht","ergebnis von legging it","ergebnis des freimachens des pfades"}},{q="Wer sind die in der Aufgabe erwähnten Peons?",a="Peons sind die Arbeitskräfte der Horde. Sie schlagen Holz, betreiben Bergbau und errichten Befestigungen. Für Siedlungen sind sie unverzichtbar, doch für den Kampf eignen sie sich kaum und ziehen sich bei Gefahr rasch zurück.",al={"wer sind die peons","rolle der peons","was peons tun"}},{q="Wohin reisten die Peons?",a="Die Peons waren auf einem Weg nach Süden zu abgelegenen Arbeitsgebieten und Rohstoffvorkommen unterwegs, die regelmäßige Betreuung erfordern. Die Reise war so gefährlich geworden, dass der gesamte Verkehr zum Erliegen kam.",al={"wohin der pfad führt","südlicher pfad","richtung süden"}},{q="Warum benötigen Peons Abenteurer, um ihre Routen zu sichern?",a="Peons fehlt es an militärischer Ausbildung und Kampfausrüstung, weshalb sie Raubtieren in der Wildnis und feindlichen Streitkräften schutzlos ausgeliefert sind. Aufseher verlassen sich auf erfahrene Abenteurer, um Bedrohungen zu beseitigen und die Wege zu den Arbeitsstätten sicher zu halten.",al={"warum peons schutz brauchen","sicherheit der peons","peons bewachen"}}},fp="10,121,17.210.0,24.276.0,19.112.0,42.162.0,44.139.0,40.185.0,31.177.0,55.199.0"}
P.entries["quest:96822"] = {n="For Honor",s="Durch For Honor leben gefallene Krieger in der Erinnerung weiter. Ihre Opfer bleiben im Gedächtnis jener, die sich an sie erinnern.",h="Durch For Honor leben gefallene Krieger in der Erinnerung weiter.",kw={"gefallene krieger","for honor","ehre","denkmal","quest","gedenken","krieger"},ang={["class:Warrior"]="Als Krieger wisst Ihr um das Gewicht der Opfer auf dem Schlachtfeld. Das Gedenken an gefallene Kämpfer hält ihre Taten lebendig."},sec={{t="Die Pflicht des Gedenkens",b="Wer gefallene Krieger überlebt, trägt die Erinnerung an sie weiter. Derer zu gedenken, die alles gaben, ist eine Pflicht."},{t="Das Vermächtnis bewahren",b="Eure Bemühungen halten die gefallenen Kämpfer in Erinnerung. Jene, die ihrer gedenken, ehren weiterhin ihre Opfer."}},faq={{q="Worum geht es in der Quest For Honor?",a="For Honor fordert Euch auf, gefallener Kämpfer zu gedenken. Eure Bemühungen bewahren ihre Opfer vor dem Vergessen.",al={"was ist for honor","questübersicht for honor"}},{q="Wer sind die Krieger, die beim Abschluss erwähnt werden?",a="Die Krieger sind gefallene Kämpfer, die für ihre Taten geehrt werden. Eure Handlungen bewahren die Erinnerung an sie und ihren geleisteten Dienst.",al={"wer sind die krieger","wessen wird gedacht"}},{q="Warum ist es wichtig, diese Krieger zu ehren?",a="Das Gedenken an gefallene Krieger verleiht ihrem Opfer Würde. Es sorgt dafür, dass ihr Mut weiterhin gewürdigt wird.",al={"warum diese quest erfüllen","for honor bedeutung"}},{q="Wer bittet darum, diese Aufgabe zu erfüllen?",a="Jemand, der gefallener Kameraden gedenken möchte, leitet die Arbeit an. Bei Eurer Rückkehr bestätigt diese Person die Erfüllung und würdigt das Andenken der Krieger.",al={"wer vergibt for honor","questgeber for honor"}},{q="Führt diese Quest zu weiteren Aufgaben?",a="Nichts deutet auf weitere Aufgaben hin. For Honor ehrt gefallene Kämpfer und ihre Opfer.",al={"ist for honor teil einer questreihe","was folgt auf for honor"}},{q="Was bedeutet der Titel For Honor?",a="For Honor benennt die Pflicht, gefallener Soldaten zu gedenken. Ihr Opfer und die Erinnerung an sie auf dem Schlachtfeld lebendig zu halten, ist für jeden Kämpfer eine ernste Pflicht.",al={"was macht es ehrenhaft","bedeutung von for honor"}}},fp="9,117,21.110.0,21.114.0,34.95.0,47.119.0,41.95.0,34.140.0,36.86.0,38.143.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="In Durotar ernähren Kaktusfeigen Orgrimmar und versprechen künftig mehr Nahrung. Sorgsam gesammelt können diese robusten Früchte die Hauptstadt der Horde ernähren und Samen für künftige Ernten liefern.",h="In Durotar ernähren Kaktusfeigen Orgrimmar und versprechen künftig mehr Nahrung.",kw={"kaktusfrucht","durotar","frucht","orgrimmar","kaktusfeige","kaktusfeigen","samen","this fruit could bite back"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass nachhaltige Nahrungsquellen wie robuste Wüstenfrüchte helfen können, Orgrimmar und die wachsende Bevölkerung der Horde zu ernähren.",["profession:Cooking"]="Als Koch könnt Ihr Kaktusfeigen zu Gerichten verarbeiten, und die Früchte können auch die Stadtbewohner versorgen.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, wie widerstandsfähig Wüstenpflanzen sein können und wie viel Mühe es kostet, stachelige Wildfrüchte für den Anbau zu sammeln."},sec={{t="Ernte im Ödland",b="Durotar ist rau und von der Sonne ausgedörrt, sodass herkömmlicher Ackerbau nahezu unmöglich ist. Seine robusten Kaktusfeigen gedeihen im trockenen Boden, weshalb die Bewohner sie sammeln, um Orgrimmar mit Nahrung zu versorgen. Ihre schützenden Stacheln erfordern Vorsicht, und ihre Früchte liefern benötigte Nahrung."},{t="Anbau und Versorgung",b="Kaktusfeigen ernähren die Menschen schon jetzt und können auch in den kommenden Jahren zur Nahrungsversorgung beitragen. Ihr Fruchtfleisch wird zu Gerichten verarbeitet, während ihre Samen sorgfältig für die Aussaat aufbewahrt werden. Ziel ist es, diese widerstandsfähige Nutzpflanze rund um Orgrimmar anzubauen und so direkt vor den Festungsmauern eine dauerhafte Nahrungsquelle zu schaffen."}},faq={{q="Was ist This Fruit Could Bite Back?",a="Ihr sammelt wilde Kaktusfeigen in Durotar zum Kochen und bewahrt ihre Samen auf, um sie im trockenen Land rund um Orgrimmar auszusäen.",al={"was ist this fruit could bite back","this fruit could bite back quest","zurückbeißende frucht quest"}},{q="Warum werden Kaktusfeigen gesammelt?",a="Kaktusfeigen liefern Nahrung für örtliche Mahlzeiten, und ihre Samen werden für die Aussaat aufbewahrt. Ziel ist es, sie im trockenen Land rund um Orgrimmar anzubauen.",al={"warum kaktusfeigen sammeln","zweck der kaktusfeige","wozu dienen kaktusfeigen"}},{q="Wo sollen die Samen ausgesät werden?",a="Die Samen sollen im gesamten Umland von Orgrimmar ausgesät werden, wo sie helfen können, eine widerstandsfähige Nahrungsgrundlage im kargen Wüstenboden zu schaffen.",al={"wo kaktusfeigen anbauen","kaktusfeigen aussaat orgrimmar"}},{q="Wer möchte diese Früchte sammeln lassen?",a="Ein Einheimischer möchte mit der Ernte die örtlichen Nahrungsvorräte aufstocken, Reisende ernähren und Nutzpflanzen anbauen, die Durotars rauem Wüstenklima gewachsen sind.",al={"wer will die kaktusfeigen","questgeber zurückbeißen"}},{q="Warum „beißt“ die Frucht „zurück“?",a="Kaktusfeigen haben wie andere robuste Wüstenkakteen scharfe Stacheln und Nadeln, weshalb beim Sammeln Vorsicht geboten ist.",al={"warum zurückbeißen","warum beißt die frucht zurück"}},{q="Warum ist es wichtig, Obst rund um Orgrimmar anzubauen?",a="Durotar ist größtenteils trocken und felsig, was herkömmlichen Ackerbau erschwert. Trockenheitsverträgliche Kaktusfeigen könnten dazu beitragen, Orgrimmar dauerhaft mit Nahrung zu versorgen.",al={"fehlt orgrimmar nahrung","orgrimmar landwirtschaft","durotar ackerbau"}}},fp="26,174,26.262.0,26.288.0,35.120.0,37.146.0,32.166.0,32.137.0,31.103.0,49.159.0"}
P.entries["quest:96873"] = {n="A Pain in the Neck",s="Pa'zula bittet Euch, die Bindungsmagie von Anhängern zu entfernen, mit denen Zalazane Trolle auf den Echoinseln kontrolliert. Die Rückstände könnten ihre Geister aus dem Griff des Hexendoktors befreien.",h="Pa'zula bittet Euch, die Bindungsmagie von Anhängern zu entfernen, mit denen Zalazane Trolle auf den...",kw={"ein schmerz im nacken","bindungszauber","die echoinseln","verhexte anhänger","leuchtende rückstände","pa'zula","sen'jin","zalazane"},ang={["profession:Tailoring"]="Als Verzauberer übt Ihr Euer Handwerk, indem Ihr für Pa'zula Bindungsmagie aus Hexed Pendants entfernt."},sec={{t="Pa'zulas Bitte",b="Pa'zula in Sen'jin benötigt die Rückstände von Hexed Pendants. Zalazane nutzt Bindungszauber auf den Anhängern, um seine Gefangenen unter Kontrolle zu halten. Ihr sollt die Magie entfernen und Pa'zula die Rückstände bringen. Die Freiheit der Trolle steht auf dem Spiel."},{t="Die Anhänger",b="Pa'zula sagt, die Bindungszauber hielten die Gedanken der Trolle gefangen, und warnt Euch davor, selbst einen Anhänger zu tragen. Als Ihr mit den Rückständen zurückkehrt, sagt Pa'zula, die Zauber seien entfernt und die Geister der getöteten Trolle könnten ruhen."}},faq={{q="Wer bittet um die Rückstände?",a="Pa'zula in Sen'jin bittet Euch, die Rückstände von Hexed Pendants zu bringen.",al={"wer will rückstände","pa'zulas bitte"}},{q="Was macht Zalazane mit den Anhängern?",a="Zalazane nutzt Bindungszauber auf den Anhängern, um die Gedanken seiner Gefangenen zu kontrollieren.",al={"zalazanes anhänger","verhexte anhänger"}},{q="Wo findet Ihr Hexed Pendants?",a="Trolle auf den Echoinseln tragen Hexed Pendants bei sich.",al={"anhängerfundort","wo anhänger"}},{q="Was sind Leuchtende Rückstände?",a="Leuchtende Rückstände erhält man, indem man die Magie aus Hexed Pendants entfernt.",al={"rückstände von anhängern","leuchtendes zeug"}},{q="Warum will Pa'zula, dass die Anhängermagie entfernt wird?",a="Pa'zula sagt, dass die Entfernung der Bindungszauber den Geistern der getöteten Trolle Ruhe verschafft.",al={"warum anhänger entzaubern","trollgeister befreien"}}},fp="18,175,17.241.0,12.215.1,30.77.0,40.88.0,35.59.0,25.72.0,48.77.0"}
P.entries["quest:96874"] = {n="This Is Spinal Axe",s="Ug’thok in Orgrimmar bittet Euch, Stacheln der riesigen Bestien vom Donnergrat zu sammeln. Er hofft, daraus für Eure Schmiedelektionen einen Axtkopf zu formen.",h="Ug’thok in Orgrimmar bittet Euch, Stacheln der riesigen Bestien vom Donnergrat zu sammeln.",kw={"axtkopf","orgrimmar","grobe schleifsteine","saru","schmiedekunst","donnergrat","ug’thok","verwitterte stacheln"},ang={["profession:Blacksmithing"]="Als Schmiedelehrling helft Ihr Ug’thok, Materialien für einen Axtkopf zu sammeln, den er herzustellen hofft."},sec={{t="Die Idee eines Schmieds",b="Ug’thok bittet Euch, fünf verwitterte Stacheln und fünf grobe Schleifsteine zu bringen. Er glaubt, die Stacheln könnten einen hervorragenden Axtkopf ergeben, obwohl Saru über die Idee lachte."},{t="Zähes Material",b="Die Stacheln sind zäher, als Ug’thok erwartet hatte, was ihre Verarbeitung erschweren könnte. Er will weiter an dem Entwurf arbeiten."}},faq={{q="Wer bittet um die Stacheln?",a="Ug’thok in Orgrimmar bittet Euch, verwitterte Stacheln und grobe Schleifsteine zu sammeln.",al={"wer möchte stacheln","ugthok axt","schmiedelektion"}},{q="Was möchte Ug’thok herstellen?",a="Ug’thok hofft, aus den Stacheln der Bestien einen Axtkopf herzustellen.",al={"stachelaxt","was stellt er her","axtkopf idee"}},{q="Woher stammen die Stacheln?",a="Die verwitterten Stacheln stammen von den riesigen Bestien vom Donnergrat.",al={"wo sind stacheln","donnergrat bestien","stacheln fundort"}},{q="Was braucht Ug’thok noch?",a="Ug’thok bittet neben den Stacheln auch um grobe Schleifsteine.",al={"schleifsteine benötigt","welche materialien","grobe steine"}},{q="Warum möchte Ug’thok die Materialien?",a="Ug’thok möchte im Rahmen Eurer Schmiedelektionen versuchen, aus den Stacheln einen Axtkopf herzustellen.",al={"warum stacheln","wofür sind sie","ugthok materialien"}}},fp="18,154,16.165.0,14.123.1,29.85.0,33.62.0,30.64.0,30.63.0,38.91.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="In ganz Durotar brauchen Orgrimmars Baumeister Häute, um die wachsende Hauptstadt zu stärken. Kamari schickt Euch zum Donnergrat, um Eidechsenbälge und gehärtete leichte Felle zu beschaffen.",h="In ganz Durotar brauchen Orgrimmars Baumeister Häute, um die wachsende Hauptstadt zu stärken.",kw={"beasts of thunder ridge","gehärtetes leichtes fell","durotar","kamari","lederverarbeitung","orgrimmar","peons","raue eidechsenhaut","donnergrat"},ang={["faction:Horde"]="Während die Horde sich in Durotar niederlässt, helfen Vorräte aus der Wildnis dabei, Orgrimmar zu befestigen und zu vergrößern.",["race:Orc"]="Als Orc wisst Ihr, dass Durotars Elemente robuste Materialien erfordern, die von Jägern und Arbeitern gesammelt werden."},sec={{t="Eine wachsende Hauptstadt",b="Orgrimmar wächst weiter, während die Horde sich in Durotar eine Heimat schafft. Neue Behausungen, Werkstätten und Verteidigungsanlagen brauchen Holz, Stein und Tierhäute. Bauholz kommt von weiter her, doch Durotars Wildtiere liefern robuste Häute für die Peons und Baumeister."},{t="Bestien der Schlucht",b="Die Eidechsen des Donnergrats haben zähe Häute, die für tragbare Rüstungen zu dick und steif sind. Fachgerecht gewonnen, kleiden ihre Bälge die Wände und Decken von Orgrimmars Holz- und Steinbauten aus. Dort schützen sie die Innenräume vor der sengenden Sonne und plötzlichen Schluchtwinden."}},faq={{q="Warum braucht Orgrimmar Eidechsenbälge vom Donnergrat?",a="Die Eidechsenbälge vom Donnergrat sind für tragbare Rüstungen zu dick und grob, doch ihre Widerstandsfähigkeit eignet sich gut für den Bau. Orgrimmars Peons kleiden neue Wände und Dächer mit den Bälgen aus, um sie vor den Elementen zu schützen.",al={"wofür sind die häute","warum raue eidechsenhaut","wofür werden häute vom donnergrat verwendet"}},{q="Wer ist Kamari?",a="Kamari ist eine Lederverarbeiterin in Orgrimmar, die die Baumeister und Peons der Stadt mit robusten Bälgen und Häuten versorgt. Die Häute werden für die laufenden Bauarbeiten benötigt.",al={"wer ist kamari","kamari orgrimmar","wer vergibt beasts of thunder ridge"}},{q="Wo liegt der Donnergrat?",a="Der Donnergrat ist eine zerklüftete Schlucht in Durotar, deren Eidechsen dicke Häute haben, die Kamari für Orgrimmars neue Gebäude benötigt.",al={"wo ist der donnergrat","lage des donnergrats","donnergrat durotar"}},{q="Warum werden neben Eidechsenbälgen auch gehärtete leichte Felle verlangt?",a="Kamari verlangt neben den schweren Eidechsenbälgen auch gehärtete leichte Felle, um diese Materialien zu ergänzen. Der Auftrag prüft außerdem Eure allgemeinen Kenntnisse und Fertigkeiten in der Lederverarbeitung.",al={"warum gehärtete leichte felle","wofür sind die gehärteten felle"}},{q="Warum wächst Orgrimmar so schnell?",a="Orgrimmar ist die neu gegründete Hauptstadt der Horde, und die laufenden Bauarbeiten müssen einer wachsenden Zahl von Orcs und ihren Verbündeten Unterkunft schaffen. Dieses Wachstum sorgt für einen ständigen Bedarf an Rohstoffen.",al={"warum baut orgrimmar","orgrimmars erweiterung"}},{q="Lassen sich aus den Eidechsenbälgen vom Donnergrat Rüstungen fertigen?",a="Die Eidechsenbälge vom Donnergrat sind in der Regel zu dick und steif für biegsame Rüstungen. Ihr wichtigster praktischer Nutzen liegt im Bauwesen.",al={"lassen sich eidechsenbälge tragen","ist raue eidechsenhaut rüstung"}}},fp="23,157,17.236.0,20.266.0,56.205.0,14.155.0,31.119.0,60.180.0,38.186.0,59.126.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack ist ein fallengelassener Gegenstand, der in der Wildnis des südlichen Durotar gefunden werden kann und den grob aufgestickten Namen seines Besitzers trägt. Er wurde in aller Eile weggeworfen, als Ukor vor einer furchterregenden Begegnung mit einer riesigen, in dieser Region heimischen Spinne floh.",h="Ukor's Lost Pack ist ein fallengelassener Gegenstand, der in der Wildnis des südlichen Durotar gefunden...",kw={"durotar","horde","verlorener rucksack","suedliches durotar","spinne","ukor","ukor's lost pack"},ang={["faction:Horde"]="Junge Abenteurer der Horde, die durch das südliche Durotar ziehen, helfen häufig Einheimischen wie Ukor und beweisen ihren Wert sowie ihre Zuverlässigkeit, indem sie verlorene persönliche Habseligkeiten vor gefährlichen Wildtieren bergen."},sec={{t="Ein verlorener Besitz",b="Beim Durchqueren der trockenen Wildnis des südlichen Durotar stößt ein Abenteurer auf eine verlassene Reisetasche, auf deren Klappe grob der Name „Ukor“ gestickt ist. Das Überleben in den rauen Gefilden von Durotar lässt wenig Raum für unvorsichtiges Umherstreifen, und das Finden weggeworfener Ausrüstung deutet gewöhnlich auf eine verhängnisvolle Begegnung in der Nähe hin."},{t="Flucht aus der Wildnis",b="Nachdem der Rucksack zu Ukor im südlichen Durotar zurückgebracht wurde, kommt die Geschichte hinter dessen Zurücklassen ans Licht. Ukor ließ die Tasche in Panik fallen, als er von einer gewaltigen, in dieser Region heimischen Spinne überrumpelt wurde, überzeugt davon, seine Vorräte niemals wiederzusehen. Die unversehrte Tasche wiederzuerlangen bringt dem Reisenden aufrichtige Dankbarkeit und Lob ein."}},faq={{q="Wer ist Ukor?",a="Ukor ist ein Bewohner, der im südlichen Durotar lebt. Als er in der trockenen Wildnis mit einer riesigen Spinne konfrontiert wurde, war er gezwungen, seine Habseligkeiten in einem verzweifelten Versuch, sich in Sicherheit zu bringen, zurückzulassen.",al={"wer ist ukor","ukor durotar"}},{q="Warum verlor Ukor seinen Rucksack?",a="Ukor ließ seinen Rucksack fallen, während er vor einer riesigen, in Durotar lauernden Spinne um sein Leben rannte. Er ging davon aus, dass seine Habseligkeiten für immer verloren seien, bis ein Abenteurer die Tasche aufspürte.",al={"warum ging der rucksack verloren","wo verlor ukor den rucksack"}},{q="Wohin muss der Rucksack gebracht werden?",a="Der wiederbeschaffte Rucksack gehört Ukor, der wartend im südlichen Durotar anzutreffen ist, bereit, zurückkehrende Reisende zu begrüßen.",al={"wohin den rucksack zurueckbringen","ukor abgabe"}},{q="Wie wird der Rucksack identifiziert?",a="Der Rucksack lässt sich leicht an Ukors Namen erkennen, der grob auf die Klappe der Tasche gestickt ist.",al={"wie wird der rucksack identifiziert","rucksacknaht"}},{q="Welche Art von Kreatur jagte Ukor?",a="Ukor wurde von einer riesigen Spinne überfallen, die das Gelände des südlichen Durotar durchstreifte, was ihn derart verängstigte, dass er all seine Habseligkeiten fallen ließ und um sein Leben rannte.",al={"spinne in durotar","welche spinne ukor angriff"}},{q="Was passiert, wenn Ihr Ukor den Rucksack zurückbringt?",a="Ukor ist erstaunt und zutiefst dankbar, seine verlorenen Habseligkeiten wiederzusehen, und erklärt den Abenteurer, der seine Tasche wiederbeschafft hat, zu einem wahren Helden.",al={"ukor belohnung","wie reagiert ukor"}}},fp="16,125,16.162.0,17.222.0,12.118.0,27.131.0,37.97.0,27.54.0,34.106.0,46.116.0"}
P.entries["quest:96877"] = {n="Halikors Huf",s="In der Wildnis wird Halikor's Hoof als Beweis für den Triumph eines Jägers nach Orgrimmar getragen. Der gewaltige abgetrennte Huf ehrt den Sieg des Jägers über die furchterregende Eidechse.",h="In der Wildnis wird Halikor's Hoof als Beweis für den Triumph eines Jägers nach Orgrimmar getragen.",kw={"halikor","halikor's hoof","horde","jagd","eidechse","orgrimmar","trophäe"},ang={["class:Hunter"]="Als Jäger den gewaltigen Halikor zu erlegen, zeigt das Geschick des Fährtenlesers und den Nervenkitzel der Jagd.",["faction:Horde"]="Den Beweis für die Niederlage einer mächtigen Bestie nach Orgrimmar zu tragen, ehrt die Traditionen der Horde, die Stärke und Jagdgeschick hochhalten."},sec={{t="Trophäe einer mächtigen Bestie",b="Halikors gewaltige Größe zeigt sich an dem Huf, der seinen Überresten entnommen wurde. Jäger und Krieger in der Wildnis nehmen seit Langem ein Stück einer furchterregenden Bestie an sich, um deren Erlegung zu beweisen. Der Huf lässt keinen Zweifel an der gewaltigen Größe und Stärke der Eidechse."},{t="Beweis für die Hauptstadt",b="Der schwere Huf wird nach Orgrimmar getragen, um der Horde die Niederlage der Bestie zu verkünden. Stärke und das Überleben im Angesicht der unerbittlichen Raubtiere des Landes zählen in dieser Kriegergesellschaft. Das Vorzeigen der Trophäe ehrt den Jäger und versichert der Hauptstadt, dass eine gefährliche Kreatur erlegt wurde."}},faq={{q="Was ist Halikor?",a="Halikor ist eine furchterregende Eidechse von gewaltiger Größe. Jäger nehmen ihren abgetrennten Huf als Beweis dafür an sich, dass die Bestie erlegt wurde.",al={"was ist halikor","wer ist halikor","halikor eidechse"}},{q="Warum muss der Huf nach Orgrimmar gebracht werden?",a="Der Huf wird als Beweis für die Niederlage der Bestie und den Triumph des Jägers nach Orgrimmar getragen.",al={"warum huf nach orgrimmar bringen","halikor huf abliefern","wohin kommt der huf"}},{q="Wie erhält man Halikor's Hoof?",a="Ihr nehmt Halikor's Hoof vom Körper der Eidechse an Euch, nachdem Ihr sie aufgespürt und im Kampf erlegt habt.",al={"wie erhält man halikor's hoof","halikor beute"}},{q="Warum hat eine Eidechse einen Huf?",a="Halikor ist eine mächtige Bestie der Wildnis, und sein gewaltiger Huf beweist, dass Ihr ihn erlegt habt. Niemand hat gesagt, warum er einen Huf hat.",al={"hat halikor hufe","warum hat eine eidechse hufe"}},{q="Wer in Orgrimmar will Halikor's Hoof haben?",a="Ihr tragt den Huf als Beweis für Euren Sieg nach Orgrimmar. Es wird kein bestimmter Jäger oder Amtsträger genannt, der ihn entgegennehmen soll.",al={"wer nimmt halikor's hoof in orgrimmar an","halikor huf orgrimmar abgeben"}},{q="Welche Geschichte steckt hinter der Quest Halikor's Hoof?",a="Die mächtige Eidechse Halikor wird erlegt, und ihr gewaltiger abgetrennter Huf wird nach Orgrimmar getragen. Die Trophäe zeigt das Können des Jägers und überbringt der Horde die Nachricht vom Tod der Bestie.",al={"was ist die quest halikor's hoof","halikor's hoof geschichte"}}},fp="14,166,24.231.0,21.278.0,16.113.0,44.89.0,31.93.0,30.126.0,38.114.0,50.176.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="In Tirisfal jagen zwei Gesandte der Argentumdämmerung Geißelkultisten nahe Unterstadt. Beide sind Verlassene, doch die örtlichen Behörden misstrauen einem bewaffneten neutralen Orden in ihrem Gebiet.",h="In Tirisfal jagen zwei Gesandte der Argentumdämmerung Geißelkultisten nahe Unterstadt.",kw={"argentumdämmerung","gesandter der argentumdämmerung","kultisten","verlassene","geißelkultisten","tirisfal","unterstadt"},ang={["faction:Horde"]="Die Argentumdämmerung ist neutral, doch die Behörden der Horde beobachten ihre eigenständigen Einsätze nahe Unterstadt aufmerksam.",["race:Undead"]="Als Verlassener könnt Ihr sehen, wie andere Untote die Argentumdämmerung Unterstadt vorziehen. Ihre Entscheidung zeigt die geteilten Loyalitäten unter den freien Untoten."},sec={{t="Misstrauischer Empfang",b="Zwei verlassene Gesandte der Argentumdämmerung sind vor Kurzem in Tirisfal eingetroffen. Ihre Ankunft versetzt die örtlichen Behörden in Unruhe. Die Argentumdämmerung bekämpft die Geißel, doch die Verlassenen misstrauen einem bewaffneten neutralen Orden, der ohne Aufsicht in ihrem Gebiet handelt. Selbst ihre gemeinsame Herkunft mindert dieses Misstrauen kaum."},{t="Kultisten vor den Toren",b="Die Gesandten verfolgen Geißelkultisten südöstlich von Unterstadt, nahe den Außenbezirken. Sie wollen die Agenten des Lichkönigs ausmerzen, bevor die Kultisten Fuß fassen. Einer der Gesandten beobachtet ihre Bewegungen von einem Posten nahe den Stadttoren aus."}},faq={{q="Wer sind die Gesandten der Argentumdämmerung?",a="Zwei Gesandte der Argentumdämmerung sind vor Kurzem nach Tirisfal gekommen. Beide sind Verlassene, die sich dem heiligen, neutralen Orden angeschlossen haben, statt allein Unterstadt zu dienen.",al={"wer sind die gesandten","besucher der argentumdämmerung","wer kam nach tirisfal"}},{q="Warum ist die Argentumdämmerung nahe Unterstadt tätig?",a="Die Gesandten verfolgen Geißelkultisten, die nahe den Außenbezirken südöstlich von Unterstadt gesichtet wurden. Die Argentumdämmerung jagt die Überreste der Geißel überall, wo sie auftauchen, selbst nahe großen Siedlungen der Horde.",al={"warum sind sie nahe unterstadt","mission der argentumdämmerung in tirisfal","was tun die gesandten"}},{q="Warum misstrauen die örtlichen Verlassenen den Gesandten?",a="Die örtlichen Verlassenen misstrauen einem bewaffneten neutralen Orden, der ohne Aufsicht in Tirisfal tätig ist. Dieses Misstrauen bleibt bestehen, selbst wenn seine Gesandten ebenfalls Untote sind.",al={"warum unruhe wegen der argentumdämmerung","ist die argentumdämmerung vertrauenswürdig","sicht der verlassenen auf die argentumdämmerung"}},{q="Welche Gefahr geht von den Kultisten aus?",a="Eine Zelle von Geißelkultisten wurde südöstlich nahe den Außenbezirken der Stadt gesichtet, wo sie auf der Lauer liegt. Der Lichkönig bleibt eine Bedrohung für freie Untote, weshalb örtliche Späher und die Argentumdämmerung aufmerksam geworden sind.",al={"kultisten vor unterstadt","geißel in tirisfal","wer sind die kultisten"}},{q="Wohin ist der Gesandte gegangen?",a="Einer der Gesandten hat sich nahe den Eingang von Unterstadt begeben, um Geißelkultisten zu beobachten, die unmittelbar vor den Stadtmauern tätig sind.",al={"wo ist der gesandte zu finden","standort des gesandten","mitglied der argentumdämmerung finden"}},{q="Dienen Verlassene in der Argentumdämmerung?",a="Ja. Die Argentumdämmerung heißt jeden willkommen, der bereit ist, die Geißel zu bekämpfen, auch Untote mit freiem Willen, die sich dieser Sache verschreiben. Der Scharlachrote Kreuzzug tut das nicht.",al={"dürfen verlassene in die argentumdämmerung","untote der argentumdämmerung","können untote der argentumdämmerung beitreten"}}},fp="19,181,12.319.0,21.231.0,30.157.0,52.185.0,46.173.0,41.187.0,26.111.0,41.161.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="Leonid Barthalomew the Revered und Danitha Morr treffen sich wieder, um an die Verteidigung der Unterstadt gegen Naxxramas zu erinnern. Sie sprechen über Garek Bandarion, einen gefallenen untoten Helden, der als Paladin zum Heiligen Licht zurückfand, und über die Verlassenen, die seinen Weg fortsetzen.",h="Leonid Barthalomew the Revered und Danitha Morr treffen sich wieder, um an die Verteidigung der Unterstadt...",kw={"danitha morr","verlassene","garek bandarion","leonid barthalomew","kapelle des hoffnungsvollen lichts","naxxramas","paladin","gerechte sache","geißel","unterstadt"},ang={["class:Paladin"]="Garek Bandarion und Danithas Kohorte stehen für einen seltenen Weg: Verlassene entdecken wieder, wie sie trotz ihres untoten Zustands das Heilige Licht als Paladine wirken können.",["faction:Horde"]="Leonid Barthalomew verbindet die Verteidiger der Unterstadt mit der Argentumdämmerung an der Kapelle des Hoffnungsvollen Lichts in den Plaguelands.",["race:Undead"]="Leonid und Danitha suchen einen Weg zurück zum Licht, doch die meisten Verlassenen bleiben in ihrem Untod dem Heiligen fern oder feindlich gesinnt."},sec={{t="Wiedersehen der Veteranen",b="Leonid Barthalomew the Revered und Danitha Morr treffen sich wieder, nachdem sie gemeinsam Lordaeron verteidigt haben. Sie überlebten den Angriff von Naxxramas auf die Unterstadt, doch viele Kameraden fielen. Nun erinnern sie sich an die Toten und den beschwerlichen Weg der Verlassenen, die das Heilige Licht noch immer verehren."},{t="Das Erbe von Garek Bandarion",b="Leonid und Danitha erinnern sich an Garek Bandarion, den gefallenen Helden, nach dem die Feste benannt wurde. Leonid glaubt, Garek könnte der erste Verlassene gewesen sein, der das Heilige Licht wieder als wahrer Paladin wirkte. Die meisten Verlassenen haben sich vom Licht abgewandt. Danitha und ihre Kohorte halten Gareks Erbe lebendig und erforschen, was ein heiliger Untod ermöglichen könnte."},{t="Rückkehr in die Plaguelands",b="Nach seinem Gespräch mit Danitha bereitet sich Leonid darauf vor, die Feste zu verlassen und den Kampf gegen die Geißel im verheerten Osten wieder aufzunehmen. Er ist an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern stationiert. Dort heißt er tüchtige Abenteurer willkommen, die bereit sind, zu den Waffen zu greifen."}},faq={{q="Wer ist Leonid Barthalomew the Revered?",a="Leonid Barthalomew the Revered ist ein untotes Mitglied der Argentumdämmerung. Er wirkt von der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern aus und hält Kontakt zu ehemaligen Kameraden in Lordaeron, die mit ihm gegen die Geißel kämpften.",al={"wer ist leonid barthalomew","leonid the revered","geschichte von leonid barthalomew"}},{q="Wer ist Danitha Morr?",a="Danitha Morr ist eine Anführerin der Verlassenen, die beim Angriff der Geißel auf die Unterstadt an der Seite von Leonid Barthalomew kämpfte. Sie führt eine Kohorte an, die die Lehren und das heilige Erbe von Garek Bandarion weiterträgt.",al={"wer ist danitha morr","danitha","geschichte von danitha morr"}},{q="Wer war Garek Bandarion?",a="Garek Bandarion war ein Kämpfer der Verlassenen, der bei der Verteidigung der Unterstadt fiel, als Naxxramas angriff. Leonid glaubt, er könnte der erste Verlassene gewesen sein, der das Heilige Licht wieder als Paladin wirkte.",al={"wer ist garek bandarion","geschichte von garek bandarion","nach wem ist die feste benannt"}},{q="Was geschah beim Angriff auf die Unterstadt?",a="Als Naxxramas, eine Nekropole, die Unterstadt angriff, schlossen sich Champions der Verlassenen wie Danitha Morr, Leonid Barthalomew und Garek Bandarion der Verteidigung der Stadt gegen die Geißel an. Sie erlitten schwere Verluste.",al={"angriff von naxxramas auf die unterstadt","verteidigung der unterstadt","angriff der geißel auf die unterstadt"}},{q="Können die Verlassenen als Paladine das Licht wirken?",a="Die meisten Verlassenen lehnen das Licht ab, das untotem Fleisch qualvolle Schmerzen bereitet. Garek Bandarion zeigte, dass ein untoter Krieger das Heilige Licht als Paladin wirken kann. Danithas Kohorte erforscht diese Praxis weiterhin.",al={"können verlassene paladine sein","geschichte untoter paladine","verlassene lichtwirker"}},{q="Wohin geht Leonid Barthalomew danach?",a="Nach seinem Besuch bei seinen Freunden und dem Gespräch mit Danitha Morr plant Leonid, zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zurückzukehren. Die Argentumdämmerung koordiniert dort ihren Kampf gegen die Geißel.",al={"wohin geht leonid","leonid später finden","kapelle des hoffnungsvollen lichts leonid"}}},fp="17,257,19.268.0,29.329.0,25.260.0,38.223.0,20.194.0,24.192.0,49.211.0,45.214.0,44.197.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="In Tirisfal bedrohen lebende Diener der Geißel die Menschen erneut. Indem Ihr Dunkle Neophyten und Dunkle Vollstrecker dezimiert, helft Ihr zu verhindern, dass die Agenten des Lichkönigs jene Verrätereien wiederholen, die Lordaeron zerschmetterten.",h="In Tirisfal bedrohen lebende Diener der Geißel die Menschen erneut.",kw={"kult der verdammten","dunkle vollstrecker","dunkle neophyten","lebende diener","lordaeron","nekromantie","geißel","tirisfal"},ang={["class:Paladin"]="Als Paladin habt Ihr geschworen, den Schatten auszumerzen, der Lordaeron zerbrach. Lebende Kultisten, die sich der Geißel verschrieben haben, sind erklärte Feinde des Lichts.",["class:Priest"]="Als Priester erkennt Ihr, wie der Kult der Verdammten den Glauben verdreht. Seine Mitglieder tauschen heilige Hingabe gegen dunkle Nekromantie ein.",["race:Undead"]="Als Verlassener wisst Ihr, wie lebende Kultisten Lordaeron verwüsteten und Euren Untod herbeiführten. Neue Zellen des Kults in Tirisfal aufzuhalten, hilft, Euer neues Königreich zu sichern."},sec={{t="Sterbliche Agenten der Geißel",b="Die Geißel hat lebende Diener, die dem Lichkönig die Treue schwören. Sie dienen dort, wo die geistlosen Toten es nicht können. In Tirisfal sind die Menschen bereits umherstreifenden Untoten und den unerbittlichen Eiferern des Scharlachroten Kreuzzugs ausgesetzt. Nun zeigen neu entdeckte Zellen Dunkler Neophyten und Dunkler Vollstrecker, dass die Geißel erneut Fuß zu fassen versucht."},{t="Lehren aus dem Untergang",b="Die marschierenden Toten waren nicht die einzige Ursache für Lordaerons Untergang. Nachbarn verrieten Nachbarn, während der Kult der Verdammten Dörfer unterwanderte und Kornspeicher vergiftete. Aus den Schatten heraus halfen sie, das Königreich zu Fall zu bringen. Neue Aktivitäten des Kults in Tirisfal drohen diese Geschichte in den gezeichneten Landen des Nordens zu wiederholen."}},faq={{q="Was ist der Kult der Verdammten?",a="Der Kult der Verdammten besteht aus Sterblichen, die dem Lichkönig und der Geißel freiwillig dienen. Diese lebenden Akolythen verbreiten Seuchen, sabotieren Verteidigungsanlagen und praktizieren aus freien Stücken Nekromantie, statt als geistlose Untote erweckt zu werden.",al={"was ist der kult der verdammten","wer sind die kultisten","wer sind die dunklen neophyten"}},{q="Warum sind Mitglieder des Kults in Tirisfal aktiv?",a="Tirisfal bleibt umkämpft, heimgesucht von geistlosen Untoten, Eiferern des Scharlachroten Kreuzzugs und dem fortbestehenden Einfluss der Geißel. Der Kult arbeitet im Verborgenen, um den örtlichen Widerstand zu untergraben und die finsteren Pläne der Geißel voranzutreiben.",al={"warum sind kultisten in tirisfal","kult in tirisfal"}},{q="Wer sind die Dunklen Neophyten und Dunklen Vollstrecker?",a="Dunkle Neophyten sind neue Eingeweihte, die dunkle Künste und Rituale erlernen. Dunkle Vollstrecker bewachen die Unternehmungen des Kults und setzen Disziplin durch. Gemeinsam bilden sie aktive Zellen in der Region.",al={"wer sind die dunklen vollstrecker","rolle der dunklen neophyten"}},{q="Warum gelten lebende Diener als schlimmer als geistlose Untote?",a="Geistlose Untote handeln aus Instinkt oder auf direkten Befehl, während lebende Kultisten sich bewusst für Verrat entscheiden. Sie können sich unauffällig in die Gesellschaften der Sterblichen einfügen und Siedlungen unterwandern, was sie heimtückischer macht als umherstreifende Ghule oder Skelette.",al={"warum sind lebende kultisten schlimmer","lebende diener der geißel"}},{q="Was meint die Aufgabe damit, Lordaerons Geschichte nicht wiederholen zu lassen?",a="Lordaeron fiel nicht nur durch eine Invasion, sondern auch dadurch, dass der Kult der Verdammten Getreide vergiftete und Mitbürger aus den eigenen Reihen verriet. Wenn Kultisten Fuß fassen, könnte dieselbe Katastrophe folgen.",al={"lordaerons geschichte wiederholen","lordaerons untergang kult"}},{q="In welchem Verhältnis steht der Kult zum Scharlachroten Kreuzzug in Tirisfal?",a="Der Scharlachrote Kreuzzug jagt fanatisch alles, was vom Untod befleckt ist, weshalb die Geißel und der Kult zu seinen Zielen gehören. Ihr Konflikt lässt die örtlichen Bewohner zwischen geistlosen Schrecken, eifernden Kreuzfahrern und heimlich agierenden Kultisten gefangen zurück.",al={"verhältnis zum scharlachroten kreuzzug","kult gegen scharlachroten kreuzzug"}}},fp="22,219,28.323.0,19.316.0,31.229.0,57.215.0,46.182.0,62.226.0,74.194.0,60.224.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="Überall in Tirisfal liegen Kriegsüberreste im Boden verstreut. Naxxramas wurde unter schweren Verlusten für die Verlassenen und die Argentumdämmerung von der Unterstadt vertrieben. Sein zersplitterter nekrotischer Fokussierungskristall bleibt eine Gefahr, und Kultisten der Geißel suchen seine Fragmente wegen der dunklen Magie darin.",h="Überall in Tirisfal liegen Kriegsüberreste im Boden verstreut.",kw={"argentumdämmerung","kultisten","verlassene","naxxramas","nekrotische kristallfragmente","remnants of war","geißel","tirisfal","unterstadt"},ang={["class:Mage"]="Geht als Magier vorsichtig mit den zerbrochenen nekrotischen Kristallen von Naxxramas um. In ihnen steckt noch immer instabile magische Energie.",["class:Priest"]="Als Priester stellt Ihr Euch der unheiligen Verderbnis, die in den Scherben zurückgeblieben ist. Sie droht, das Land weiter zu entweihen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tirisfal vor der zurückgebliebenen Magie der Geißel zu sichern. Ihr schützt die Unterstadt und den Stützpunkt der Horde im Norden Lordaerons.",["race:Undead"]="Als Untoter wisst Ihr, dass Naxxramas die Unterstadt selbst bedrohte. Die Bergung der Fragmente hilft, Euer Volk vor der Macht der Geißel direkt vor seiner Haustür zu schützen."},sec={{t="Der Schatten über der Stadt",b="Naxxramas ragte einst über Tirisfal auf, um die Unterstadt und die Verlassenen auszulöschen. Die Verlassenen und die Argentumdämmerung wehrten die schwebende Festung in einer verzweifelten Verteidigung ab. Beide erlitten schwere Verluste. Während der Schlacht wurde der gewaltige nekrotische Fokussierungskristall auf der Spitze von Naxxramas zerstört, wodurch Fragmente über die Lichtungen verstreut wurden."},{t="Verstreute Nekromantie",b="Naxxramas wurde vertrieben, doch Stücke seines Kristalls liegen noch immer im Boden. Kultisten der Geißel suchen nach den Fragmenten und hoffen, die dunkle Magie zu nutzen, die noch in ihnen steckt. Das Sammeln der Scherben hält diese Macht von der Geißel fern. Doch es wird Jahre dauern, jedes Fragment aus Tirisfal zu entfernen."}},faq={{q="Was sind die nekrotischen Kristallfragmente?",a="Die nekrotischen Kristallfragmente sind Stücke des großen Fokussierungskristalls, der einst auf der Spitze von Naxxramas angebracht war. Der Kristall wurde während des Angriffs auf die Unterstadt zerstört, und seine Scherben gingen über ganz Tirisfal nieder.",al={"was sind nekrotische kristallfragmente","was sind die kristalle","nekrotische kristalle"}},{q="Warum hat Naxxramas die Unterstadt angegriffen?",a="Naxxramas kam nach Tirisfal, um die Unterstadt zu zerstören und die Verlassenen auszulöschen. Die Verlassenen und die Argentumdämmerung wehrten es ab, erlitten dabei jedoch beide schwere Verluste.",al={"warum griff naxxramas an","naxxramas angriff auf unterstadt","was hat naxxramas hier getan"}},{q="Warum sammeln Kultisten der Geißel die Kristallfragmente?",a="Kultisten der Geißel durchsuchen Tirisfal nach den zersplitterten Fragmenten, weil noch immer nekrotische Magie in ihnen steckt. Sie hoffen, diese Macht für die Geißel zurückzugewinnen.",al={"warum wollen kultisten die kristalle","was wollen kultisten mit scherben","kultisten der geißel kristalle"}},{q="Ist der Umgang mit den nekrotischen Kristallen gefährlich?",a="Ja. Obwohl die Fragmente zerbrochen sind und den Großteil ihrer ursprünglichen Ladung verloren haben, bergen sie noch immer instabile nekrotische Energie. Direkter Kontakt ist gefährlich.",al={"ist das berühren der kristalle gefährlich","kristall körperkontakt","können nekrotische kristalle verletzungen verursachen"}},{q="Wer half den Verlassenen, Naxxramas abzuwehren?",a="Die Verlassenen kämpften an der Seite der Argentumdämmerung, um die Unterstadt gegen Naxxramas zu verteidigen. Beide erlitten in der Schlacht schwere Verluste.",al={"wer kämpfte bei naxxramas","wer verteidigte die unterstadt","argentumdämmerung verteidigung der unterstadt"}},{q="Werden jemals alle nekrotischen Kristalle aus Tirisfal entfernt sein?",a="Es wird Jahre dauern, jedes Kristallfragment aus Tirisfal zu entfernen. Der Kristall zersplitterte über den Lichtungen und verstreute seine Scherben weit und breit. Die Bewohner werden sie weiterhin im Boden finden.",al={"wird tirisfal frei von kristallen sein","lassen sich alle fragmente entfernen","verbliebene kristalle in tirisfal"}}},fp="15,287,24.346.0,20.278.0,40.203.0,39.168.0,58.160.0,44.144.0,44.124.0,61.182.0"}
P.entries["quest:96899"] = {n="Die Bandarionfestung",s="In der Bandarionfestung wartet Kommandant Leonid Barthalomew im Westen von Tirisfal auf Reisende. Die Argentumdämmerung hielt die abgelegene Festung einst gegen die Geißel, und nun bewachen Danitha und ihre Paladine deren Mauern.",h="In der Bandarionfestung wartet Kommandant Leonid Barthalomew im Westen von Tirisfal auf Reisende.",kw={"argentumdämmerung","die bandarionfestung","kult der verdammten","danitha","leonid barthalomew","paladin","geißel","tirisfal"},ang={["class:Paladin"]="Als Paladin findet Ihr die Bandarionfestung unter Danithas Obhut vor. Ihre Mitpaladine halten deren Mauern als heilige Bastion gegen die dunklen Mächte in Tirisfal."},sec={{t="Ein Ruf zur Festung",b="Nachdem Ihr der Argentumdämmerung gegen die Umtriebe des Kults der Verdammten geholfen habt, werdet Ihr nach Nordwesten durch Tirisfal geschickt. Kommandant Leonid Barthalomew wartet in der Festung, um mit Euch über den andauernden Kreuzzug des Ordens gegen die Dunkelheit zu sprechen."},{t="Geschichte und Obhut",b="Die Argentumdämmerung nutzte die Festung einst als Ausgangspunkt gegen Vorstöße der Geißel in ganz Tirisfal. Dann richtete der Orden sein Augenmerk auf die Östlichen und Westlichen Pestländer. Die Festung wurde zurückgelassen und begann zu verfallen, bis die Paladin Danitha und ihre Gefährten die Obhut über ihre Mauern übernahmen."},{t="Erinnerungen an einen Freund",b="Leonid Barthalomew erinnert sich an die Schlachten, die von den Zinnen der Festung aus geschlagen wurden. Er ist erleichtert, dass die Festung nicht verwahrlost ist. Danitha benannte sie nach einem gemeinsamen Freund."}},faq={{q="Wer ist Leonid Barthalomew?",a="Leonid Barthalomew befehligt die Argentumdämmerung. Einst nutzte er die Bandarionfestung als Stützpunkt während der Vorstöße der Geißel nach Tirisfal. Nun ist er zurückgekehrt, um Danitha und ihre Paladine zu treffen.",al={"wer ist leonid barthalomew","wo ist leonid barthalomew","leonid bandarionfestung"}},{q="Was ist die Bandarionfestung?",a="Im Westen von Tirisfal liegt die Bandarionfestung, die die Argentumdämmerung einst gegen Angriffe der Geißel hielt. Der Orden zog sich in die Pestländer zurück und ließ die Festung verfallen. Danithas Paladine setzten sie wieder instand und halten sie nun.",al={"was ist die bandarionfestung","bandarionfestung geschichte","wer hält die bandarionfestung"}},{q="Wer ist Danitha?",a="Danitha ist eine Paladin, die mit ihrem Orden die Obhut über die Bandarionfestung übernahm, nachdem sich die Argentumdämmerung nach Osten in die Pestländer zurückgezogen hatte. Sie benannte die Festung nach einem gemeinsamen Freund von ihr und Leonid Barthalomew.",al={"wer ist danitha","danitha paladin","wer leitet die bandarionfestung"}},{q="Warum heißt sie Bandarionfestung?",a="Danitha benannte die Festung nach einem gemeinsamen Freund von ihr und Kommandant Leonid Barthalomew.",al={"warum wurde sie bandarionfestung genannt","wer ist bandarion","bandarion namensbedeutung"}},{q="Warum interessiert sich die Argentumdämmerung für die Bandarionfestung?",a="Die Argentumdämmerung reist zur Bandarionfestung, um sich mit Danithas Paladinen abzustimmen. Gemeinsam schützen sie Tirisfal vor den Streitkräften der Geißel und den Umtrieben des Kults der Verdammten.",al={"warum zur bandarionfestung gehen","argentumdämmerung tirisfal","bandarionfestung argentumdämmerung"}},{q="Warum gab die Argentumdämmerung die Festung einst auf?",a="Die Argentumdämmerung verließ die Bandarionfestung, als sie ihre Hauptstreitkräfte nach Osten verlegte, um die Geißel in den Pestländern zu bekämpfen. Die Festung stand leer, bis Danitha und ihre Paladine sich ihrer annahmen.",al={"was geschah nach dem krieg mit der festung","warum verließ die argentumdämmerung die bandarionfestung"}}},fp="14,214,21.234.0,23.298.0,27.172.1,26.184.0,23.226.0,15.205.0,32.93.0,52.180.0,52.183.0"}
P.entries["quest:96984"] = {n="Heart of Disruption",s="Magus Wordeen Voidglare lässt Euch durch seine Schutzzauber nach Dalaran, um einen Arkanpartikel zu suchen. Er fürchtet, der Fall der Stadt könnte auch für Unterstadt eine Katastrophe bedeuten.",h="Magus Wordeen Voidglare lässt Euch durch seine Schutzzauber nach Dalaran, um einen Arkanpartikel zu suchen.",kw={"arkanpartikel","dalaran","heart of disruption","magus wordeen voidglare","tarrens mühle","unterstadt","violet citadel","schutzzauber"},sec={{t="Ein Schlüssel durch die Schutzzauber",b="Magus Wordeen Voidglare in Tarrens Mühle schickt Euch mit einem Schlüssel nach Dalaran, den er mit Magie erfüllt hat, um seine Schutzzauber zu passieren. Er fürchtet, dass auch Unterstadt bedroht sein wird, wenn die Stadt fällt. Findet den Arkanpartikel und trefft ihn bei der Violet Citadel, wo dies begann; eine Katastrophe zu verhindern, hat Vorrang."}},faq={{q="Wer schickt mich nach Dalaran?",a="Magus Wordeen Voidglare in Tarrens Mühle schickt Euch nach Dalaran, um einen Arkanpartikel zu finden.",al={"wer hat mir das gegeben","wordeen voidglare","wer ist der magus"}},{q="Warum gehe ich nach Dalaran?",a="Ihr werdet ausgesandt, um einen Arkanpartikel zu finden. Wordeen fürchtet, Dalarans Fall könnte Unterstadt mit in den Untergang reißen.",al={"warum dalaran","wonach suche ich","auftrag in dalaran"}},{q="Wie komme ich durch Wordeens Schutzzauber?",a="Wordeen erfüllt Euren Schlüssel mit Magie, damit er seine Schutzzauber passieren kann und Euch Zutritt zur Stadt gewährt.",al={"der schlüssel","schlüssel für dalaran","schutzzauber passieren"}},{q="Wo soll ich Wordeen treffen?",a="Wordeen bittet Euch, ihn bei der Violet Citadel in Dalaran zu treffen, wo dies begann.",al={"den magus treffen","violet citadel","wo ist wordeen"}},{q="Was hat für Wordeen oberste Priorität?",a="Wordeen sagt, eine Katastrophe zu verhindern, hat Vorrang.",al={"katastrophe verhindern","was zählt am meisten","oberste priorität"}}},fp="19,161,23.287.0,24.85.0,26.107.0,34.76.0,28.80.0,33.50.0"}
P.entries["quest:96986"] = {n="The Grave Knight",s="In Tarrens Mühle schickt Melisara Euch gegen Atrexis, der unter Dalaran die Toten erhebt. Sie sieht sein Werk als Affront gegen die Verlassenen.",h="In Tarrens Mühle schickt Melisara Euch gegen Atrexis, der unter Dalaran die Toten erhebt.",kw={"atrexis","dalaran","verlassene","grave knight","melisara","nekromant","tarrens mühle","armee von untoten"},ang={["faction:Alliance"]="Melisara kümmert das Schicksal Dalarans wenig, als sie Euch gegen Atrexis schickt.",["race:Undead"]="Als Untoter wisst Ihr, dass Melisara Atrexis einen Verräter an den Verlassenen nennt. Sie sagt, seine Armee von Untoten widerspreche dem, wofür die Verlassenen stehen."},sec={{t="Melisaras Auftrag",b="Melisara nennt Atrexis einen Verräter an den Verlassenen. Unter Dalaran stellt er eine Armee von Untoten auf. Sie bittet Euch, ihn zu besiegen, obwohl sie das Schicksal der Magierstadt wenig kümmert. Niemand ist außerhalb der Reichweite der Dunklen Fürstin."}},faq={{q="Wer ist der Grave Knight?",a="Atrexis ist ein Nekromant in Dalaran, den Melisara den Grave Knight nennt.",al={"atrexis","atrexis grave knight","wer ist der grave knight"}},{q="Wer hat mich gegen Atrexis geschickt?",a="Melisara in Tarrens Mühle bittet Euch, Atrexis zu besiegen.",al={"wer gab die quest zum grave knight","melisara atrexis","wer will atrexis tot sehen"}},{q="Warum will Melisara Atrexis besiegt sehen?",a="Melisara nennt Atrexis einen Verräter an den Verlassenen, weil er unter Dalaran eine Armee von Untoten aufstellt.",al={"warum atrexis töten","warum grave knight","verlassene grund atrexis"}},{q="Wo ist Atrexis?",a="Atrexis ist in Dalaran.",al={"atrexis aufenthaltsort","grave knight aufenthaltsort","wo ist der grave knight"}}},fp="16,135,17.210.0,24.74.0,26.51.0,40.98.0,17.34.0"}
P.entries["quest:96987"] = {n="Opportunistic Education",s="Rexxie Copperclutch bittet Euch, einen Folianten aus Dalarans Bibliothek zu holen, während die Magier beschäftigt sind. Sie hofft, das Buch zu verkaufen und den Gewinn mit Euch zu teilen.",h="Rexxie Copperclutch bittet Euch, einen Folianten aus Dalarans Bibliothek zu holen, während die Magier...",kw={"dalaran","founding of dalaran","library","magier","opportunistic education","rexxie copperclutch","foliant","untoter"},ang={["race:Undead"]="Als Untoten bezeichnet Rexxie Euch als gleichgesinnt und heißt Euch bei ihrem Vorhaben willkommen."},sec={{t="Ein Buch für Rexxie",b="Rexxie Copperclutch nahe dem Kanaleingang sieht eine Gelegenheit, aus Dalarans Bibliothek Gewinn zu schlagen. Während die Magier beschäftigt sind, bittet sie Euch, ihr den Folianten namens Founding of Dalaran zu bringen. Sie bietet an, den Verkaufserlös mit Euch zu teilen."},{t="Der Wert des Buches",b="Rexxie hält das Buch, das Ihr zurückbringt, für wenig wertvoll. Sie überlegt, es mit Goldspray aufzuhübschen und zu behaupten, es habe einem Erzmagier gehört."}},faq={{q="Wer bittet um das Buch?",a="Rexxie Copperclutch nahe Dalarans Kanaleingang bittet Euch, ihr einen Folianten aus der Bibliothek der Stadt zu bringen.",al={"wer will den folianten","rexxie copperclutch","wer ist rexxie"}},{q="Welches Buch will Rexxie?",a="Rexxie bittet um Founding of Dalaran.",al={"welches buch","founding of dalaran","name des folianten"}},{q="Warum will Rexxie den Folianten?",a="Rexxie hofft, den Folianten zu verkaufen und den Gewinn mit Euch zu teilen.",al={"warum das buch stehlen","wozu dient das buch"}},{q="Woher soll das Buch kommen?",a="Rexxie bittet Euch, Founding of Dalaran in Dalaran zu finden.",al={"woher den folianten bekommen","dalarans bibliothek","fundort des buches"}},{q="Was ist mit Dalarans Magiern los?",a="Rexxie sagt, die Magier seien beschäftigt, während sie Euch bittet, nach einem Buch zu suchen.",al={"magier beschäftigt","warum opportunistisch","dalarans magier"}},{q="Was hält Rexxie von dem Buch, das Ihr bringt?",a="Rexxie hält das Buch für wenig wertvoll und überlegt, es mit Gold zu besprühen, damit es wertvoll wirkt.",al={"ist das buch wertvoll","was geschieht mit dem folianten","rexxies reaktion"}}},fp="23,157,17.231.0,18.142.1,27.109.0,28.36.0,30.60.0,40.67.0,41.73.0,45.103.0"}
P.entries["quest:96988"] = {n="Source of Power",s="In Dalaran haben sich abtrünnige Konstrukte gegen ihre Schöpfer gewandt, und Doktor Martin Felben sieht eine Chance für die Verlassenen. Er will ihre Arkankerne für seine Arbeit in Unterstadt und hofft, die Aufmerksamkeit der Dunklen Fürstin zu erregen.",h="In Dalaran haben sich abtrünnige Konstrukte gegen ihre Schöpfer gewandt, und Doktor Martin Felben sieht eine...",kw={"abscheulichkeiten","arkankonstrukte","gesprungener wächterkern","dalaran","doktor martin felben","königliche apothekervereinigung","source of power","sylvanas windläufer","unterstadt"},ang={["class:Mage"]="Magier mögen eine düstere Ironie darin sehen, dass Dalarans Konstrukte sich gegen ihre Meister wenden, während ihre arkanen Energiequellen für grausige Experimente in Unterstadt geplündert werden.",["faction:Horde"]="Abenteurer der Horde in Lordaeron unterstützen die Bemühungen der Verlassenen, sich fortschrittliche Kriegsmittel gegen ihre Rivalen zu sichern, während Dalaran durch seine abtrünnigen Schöpfungen gelähmt ist.",["profession:Engineering"]="Ingenieure wissen die Handwerkskunst hinter Dalarans autonomen Schildwachen zu schätzen, selbst wenn deren empfindliche Arkankerne herausgerissen werden, um entsetzliche Abscheulichkeiten aus der Fleischformung anzutreiben.",["race:Undead"]="Die Verlassenen sind auf die rücksichtslosen Erfindungen der Königlichen Apothekervereinigung angewiesen, um in Lordaeron zu überleben. Wer Doktor Felben hilft, bringt die arkane Fleischformungsforschung der Fraktion unter den Augen der Dunklen Fürstin voran."},sec={{t="Eine günstige Gelegenheit",b="Dalarans abtrünnige Arkankonstrukte belagern die Magier, und die Verlassenen wollen die Unruhen in der Stadt nur allzu gern ausnutzen. Doktor Martin Felben, ein Apotheker in Unterstadt, will die Kerne bergen, die die Schildwachen antreiben, statt den belagerten Zauberern zu helfen. Dalaran hütet seine magischen Forschungen seit langem, doch seine verwundbaren Schildwachen bieten opportunistischen Forschern nun eine Gelegenheit."},{t="Ehrgeiz in der Apothekervereinigung",b="Doktor Felben will mit den gesprungenen Wächterkernen sein Ansehen innerhalb der Königlichen Apothekervereinigung steigern. Er hofft, Abscheulichkeiten der Verlassenen mit unbeständiger Konstruktmagie aus Dalaran zu erfüllen und eine verheerende Armee arkanbetriebener Fleischbestien aufzustellen. Ein solcher Durchbruch, glaubt er, würde ihm die ungeteilte Aufmerksamkeit von Fürstin Sylvanas Windläufer sichern und sein alchemistisches Genie beweisen. Er hofft auf einen Aufstieg in der Vereinigung, in der rücksichtslose Schläue und wirkungsvolle Ergebnisse über Überleben und Rang entscheiden."}},faq={{q="Wer vergibt die Quest Source of Power?",a="Doktor Martin Felben vergibt sie. Er ist ein Apotheker in Unterstadt, der Hauptstadt der Verlassenen, und will der Königlichen Apothekervereinigung und Fürstin Sylvanas Windläufer durch neue Kriegsmonstrositäten sein alchemistisches Talent beweisen.",al={"wer vergibt source of power","source of power questgeber","martin felben quest"}},{q="Was geschieht während dieser Quest in Dalaran?",a="Dalaran wird von seinen eigenen Arkankonstrukten belagert, die sich gegen ihre Schöpfer gewandt haben. Die Kämpfe bieten Außenstehenden eine Gelegenheit, in die Stadt einzudringen und die magischen Bauteile zu bergen, die die abtrünnigen Schildwachen antreiben.",al={"was geschah in dalaran","dalaran unter belagerung","warum greifen konstrukte dalaran an"}},{q="Warum will Doktor Felben die Konstruktkerne?",a="Doktor Felben will die Arkanenergie in Dalarans Wächterkernen nutzen, um Abscheulichkeiten der Verlassenen zu verstärken. Indem er arkane Maschinen mit Fleischformung verbindet, hofft er, eine Armee arkanbetriebener Abscheulichkeiten zu erschaffen und Fürstin Sylvanas Windläufer seine alchemistische Meisterschaft zu beweisen.",al={"warum wächterkerne sammeln","wofür braucht felben kerne","felbens plan für wächterkerne"}},{q="Was sind die Ziele von Source of Power?",a="Ihr werdet nach Dalaran geschickt, um Euch den abtrünnigen Konstrukten zu stellen und sechs gesprungene Wächterkerne zu sammeln. Dann bringt Ihr sie zu Doktor Martin Felben in Unterstadt für seine laufenden Experimente.",al={"source of power ziele","wie viele kerne werden benötigt","was für source of power sammeln"}},{q="Welches Ziel verfolgt Doktor Felben innerhalb der Königlichen Apothekervereinigung?",a="Doktor Martin Felben strebt nach Anerkennung und einem raschen Aufstieg unter den Verlassenen. Er hofft, dass eine schlagkräftige Streitmacht arkanerfüllter Abscheulichkeiten Fürstin Sylvanas Windläufer so sehr beeindruckt, dass sie ihn zum Oberhaupt der Königlichen Apothekervereinigung ernennt.",al={"felbens ziel in der apothekervereinigung","wer führt die königliche apothekervereinigung","felben anerkennung der dunklen fürstin"}},{q="Warum bergen die Verlassenen Dalarans Technologie?",a="Die Königliche Apothekervereinigung und die Verlassenen suchen nach unkonventionellen Waffen und Energiequellen, um ihr Überleben in Lordaeron zu sichern. Während Dalarans Verteidigung von innen heraus zusammenbricht, können Apotheker der Verlassenen seine ausgefeilten arkanen Bauteile an sich nehmen, ohne offiziell einen offenen Krieg gegen die Magier zu führen.",al={"warum wollen die verlassenen dalarans magie","unterstadt dalaran konstrukte","interesse der verlassenen an dalaran"}},{q="Wo findet man die gesprungenen Wächterkerne?",a="Gesprungene Wächterkerne stammen von abtrünnigen Konstrukten, die Dalaran belagern. Ihr sammelt sie von den feindseligen verzauberten Wächtern überall in der Stadt für Doktor Felbens Forschung in Unterstadt.",al={"wo gesprungene wächterkerne finden","gesprungener wächterkern fundort","dalaran wächterkerne beute"}}},fp="15,210,24.393.0,34.472.0,36.238.0,47.222.0,48.276.0,44.181.0,65.242.0,53.298.0,41.186.0"}
P.entries["quest:97"] = {n="Die Legende von Stalvan",s="In Dunkelhain ordnet Amtmann Daltry die geborgene Handschrift Stalvan Dunstmantel zu. Sein Bericht bestätigt den Verdacht der Nachtwache.",h="In Dunkelhain ordnet Amtmann Daltry die geborgene Handschrift Stalvan Dunstmantel zu.",kw={"althea schwarzhaupt","amtmann daltry","dunkelhain","dämmerwald","handschrift","dunstmantel","night watch","stalvan"},ang={["faction:Alliance"]="Für Ermittler der Allianz zeigt Stalvans Spur, wie Dunkelhains schwer geprüfte Anführer und umherziehende Abenteurer zusammenarbeiten müssen, um die südlichen Gebiete zu sichern.",["race:Human"]="Als Mensch seht Ihr den Verfall Eurer Gesellschaft an angesehenen Hauslehrern und ländlichen Städten, die aus der Zivilisation in Wahnsinn und Isolation abgleiten."},sec={{t="Übereinstimmung in den Akten",b="Zurück im Rathaus von Dunkelhain vergleicht Amtmann Daltry die blutbefleckte Tagebuchseite mit Unterschriften im Stadtregister. Die Handschrift stimmt genau mit der von Stalvan Dunstmantel überein. Nachdem die Spur durch Gutshöfe, Gasthäuser und städtische Archive der Menschenkönigreiche führte, hat die Nachtwache nun den Beweis, dass die Gefahr ganz nahe ist."},{t="Der Verdacht der Night Watch",b="Kommandantin Althea Schwarzhaupt hat Stalvan von Anfang an gefürchtet. Der Dämmerwald ist bereits wilden Worgen, skelettartigen Untoten und lauernden Nekromanten ausgesetzt. Eine weitere Gefahr kann sie nicht ignorieren: einen Mörder unbekannten Aufenthalts in den Wäldern. Daltrys Bestätigung bringt die Nachtwache auf den Weg, Stalvan zu finden und ihm ein für alle Mal Einhalt zu gebieten."}},faq={{q="Was hat Amtmann Daltry herausgefunden?",a="Amtmann Daltry verglich die blutbefleckte Tagebuchseite mit Unterschriften im Stadtregister von Dunkelhain. Die Handschrift stimmte genau mit der von Stalvan Dunstmantel überein, wie Kommandantin Schwarzhaupt vermutet hatte.",al={"was hat daltry gefunden","daltry übereinstimmende handschrift","stalvan handschrift beweis"}},{q="Warum ist Stalvan für Kommandantin Althea Schwarzhaupt so wichtig?",a="Kommandantin Althea Schwarzhaupt führt die Nachtwache an, die bedrängte Miliz von Dunkelhain. Da das Land bereits von Schrecken bedroht wird, kann sie eine gewalttätige, undurchsichtige Gestalt mit düsterer Vergangenheit nicht frei und unauffindbar im Dämmerwald umherstreifen lassen.",al={"warum ist althea das wichtig","schwarzhaupt untersuchung","night watch stalvan"}},{q="Wo findet dieser Schritt statt?",a="Dieser Schritt findet vollständig in Dunkelhain statt. Amtmann Daltry befindet sich im Rathaus, während Kommandantin Althea Schwarzhaupt in der Nähe auf den zentralen Straßen der Stadt patrouilliert.",al={"wo ist diese quest","quest ort","dunkelhain stalvan abgeben"}},{q="Was geschieht nach der Meldung über die übereinstimmende Handschrift?",a="Nachdem Amtmann Daltry die Übereinstimmung bestätigt hat, richtet sich die Untersuchung auf die Suche nach Stalvans Aufenthaltsort in der heimgesuchten Wildnis des Dämmerwalds.",al={"wie weiter stalvan","nach daltrys schriftvergleich","nächster schritt stalvan questreihe"}},{q="Wer war Stalvan Dunstmantel ursprünglich?",a="Stalvan Dunstmantel unterrichtete einst an der Schule in Mondbruch und gab später den Kindern der Familie Flintridge Privatunterricht. Seine Briefe und Tagebuchseiten führen von Mondbruch und Goldhain zurück in den Dämmerwald, wo er als gefährlicher Einsiedler in den Wäldern lebt.",al={"wer ist stalvan","stalvan hintergrund","stalvan dunstmantel geschichte"}},{q="Warum war eine Untersuchung der Handschrift nötig?",a="Die Ereignisse und Anschuldigungen um Stalvan erstrecken sich über Mondbruch und Goldhain, weshalb die amtlichen Aufzeichnungen verstreut sind. Das Stadtregister von Dunkelhain enthält überprüfte örtliche Schriftproben, die jene auswärtigen Hinweise zweifelsfrei mit genau diesem Mann verbinden können.",al={"warum handschrift vergleichen","warum prüfte daltry die schrift","stalvans identität beweisen"}}},fx={cc1b58e5={q="Warum ist Amtmann Daltry so sehr darauf bedacht, dass Ihr Kommandant Schwarzhaupt Bericht erstattet?",a="Amtmann Daltry ist ein Stadtarchivar, kein Offizier der The Nachtwache, und die Bestätigung, dass die Handschrift von Stalvan Dunstmantel stammt, validiert Kommandant Schwarzhaupts schwerwiegende Verdachtsmomente. Daltry erkennt, dass eine offizielle Morduntersuchung sofortige bewaffnete Autorität erfordert, weshalb es dringend ist, dass Althea unverzüglich einen definitiven Beweis erhält.",al={"warum will daltry das","daltrys beweggrund","warum althea berichten"}}},fp="21,137,22.323.0,28.315.1,31.183.0,63.224.0,32.159.0,51.128.0,38.255.0,39.225.0"}
P.entries["quest:970"] = {n="Der Turm von Althalaxx",s="Bei Maestras Posten schickt Euch Delgren der Läuterer nach Süden, um den Cult of the Dark Strand aufzuhalten. Seine Bedrohung reicht vom Turm von Althalaxx bis ins Eschental, und Ihr sollt einen Leuchtenden Seelenedelstein aus den Ruinen von Ordil'Aran bergen.",h="Bei Maestras Posten schickt Euch Delgren der Läuterer nach Süden, um den Cult of the Dark Strand aufzuhalten.",kw={"althalaxx","eschental","dark strand","dunkelküste","delgren","delgren der läuterer","leuchtender seelenedelstein","maestras posten","ordil'aran"},ang={["class:Paladin"]="Als Paladin tilgt Ihr unheilige Verderbnis, indem Ihr dunkle Seelengefäße zerstört und die Kultisten bekämpft, die sie verderben.",["class:Priest"]="Als Priester untersucht Ihr ein dunkles Seelengefäß, um der Verderbnis entgegenzutreten und gequälte Seelen zu trösten.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr Außenposten an der Dunkelküste und im Eschental, die nördliche Grenze vor dunklen Magieanwendern zu schützen, die Reisende der Allianz bedrohen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie der Cult of the Dark Strand alte Ruinen wie Ordil'Aran entweiht und die nördlichen Wälder verdirbt. Ihn zu vertreiben, ist dringend geboten."},sec={{t="Ein Hilferuf über die Grenze",b="Berichte vom Turm von Althalaxx an der nördlichen Dunkelküste haben Euch nach Süden zu Delgren dem Läuterer bei Maestras Posten geführt. Er bekämpft den Cult of the Dark Strand schon lange, doch nun dringt der Kult in die uralten Elfenwälder des Eschentals vor. Sein Einfluss erstreckt sich über beide Gebiete, daher will Delgren die Quelle seiner Zauberei angreifen."},{t="Die Geheimnisse von Ordil'Aran",b="Nordöstlich von Maestras Posten sind die Ruinen von Ordil'Aran von Dark Strand-Kultisten überrannt. Delgren zufolge tragen ihre Agenten leuchtende Seelenedelsteine bei sich, Gefäße mit einer Verzauberung, die die Macht des Kults aufrechterhält. Macht in den Ruinen Jagd auf sie und bergt einen Edelstein. Delgren kann seine Verzauberung brechen und den Ursprung des Kultritus aufdecken."},{t="Ein gefangener Geist",b="Im Leuchtenden Seelenedelstein ist ein gequälter Geist gebunden. Als seine Schutzzauber brechen, erscheint Sargath. Er ist einer der Elfen von Ameth'Aran, die Athrikus Narassin während der Sundering in Seelenedelsteinen gefangen hat und seitdem langsam aussaugt. Sargath nennt Athrikus' Leutnant, Ilkrud Magthrull. Dessen Foliant könnte verraten, wo die übrigen Seelenedelsteine aufbewahrt werden."}},faq={{q="Wo finde ich den Leuchtenden Seelenedelstein?",a="Mitglieder des Cult of the Dark Strand in den Ruinen von Ordil'Aran nordöstlich von Maestras Posten tragen Leuchtende Seelenedelsteine bei sich. Die Ruinen liegen im Eschental, und Ihr müsst möglicherweise mehrere Kultisten durchsuchen, um einen zu bergen.",al={"seelenedelstein fundort","wo wird seelenedelstein fallen gelassen","dark strand seelenedelstein"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Streiter der Allianz, der bei Maestras Posten im nördlichen Eschental stationiert ist. Er bekämpft die Mächte, die in den Wald eindringen, insbesondere den Cult of the Dark Strand.",al={"delgren","wer ist delgren"}},{q="Was ist der Cult of the Dark Strand?",a="Der Cult of the Dark Strand ist eine Sekte, die im Turm von Althalaxx an der Dunkelküste und in alten Elfenruinen wie Ordil'Aran im Eschental ansässig ist. Ihre Mitglieder praktizieren dunkle Zauberei, Seelenbindung und nekromantische Riten.",al={"dark strand kult","wer sind dark strand"}},{q="Warum schickt mich eine Quest an der Dunkelküste ins Eschental?",a="Der Cult of the Dark Strand reicht vom Turm von Althalaxx an der Dunkelküste bis ins Eschental. Delgren der Läuterer bei Maestras Posten weiß, wie man der seelenbindenden Magie des Kults entgegenwirkt.",al={"warum maestras posten","warum ins eschental gehen"}},{q="Was geschieht, wenn der Seelenedelstein entschlüsselt wird?",a="Delgren will die dunkle Verzauberung auf dem Leuchtenden Seelenedelstein entschlüsseln. Was er dabei entdeckt, zeigt sich, nachdem Ihr ihn zu ihm gebracht habt.",al={"was ist im seelenedelstein","seelenedelstein geist"}},{q="Wo liegt Ordil'Aran?",a="Ordil'Aran ist eine alte Elfenruine nordöstlich von Maestras Posten im nördlichen Eschental. Der Cult of the Dark Strand hat sie überrannt.",al={"ordil'aran fundort","wo ist ordilaran"}}},fx={a63b3648={q="Warum will Delgren der Läuterer, dass dies erledigt wird?",a="Delgren ist in einen Kampf gegen den Kult von Dark Strand verwickelt, der sich nordöstlich von Maestras Post verschanzt hat. Für ihn sind sie ein gefährlicher Dorn, der vollständig herausgerissen werden muss. Die direkten Warnungen im Brief von Balthule Schattenhieb bestätigen, dass ihr korrupter Einfluss eskaliert, und Delgren glaubt, dass das Entschlüsseln der Geheimnisse, die im verzauberten Seelenedelstein gefangen sind, der einzige Weg ist, ihre Macht aufzudecken und zu zerschlagen.",al={"delgrens beweggrund","warum will delgren den seelenedelstein","warum kult von dark strand bekämpfen"}},c112c454={q="Wozu dient der Leuchtende Seelenedelstein?",a="Der Leuchtende Seelenedelstein ist ein dunkles, verzaubertes Artefakt, das vom Kult von Dark Strand in Die Ruinen von Ordil'Aran getragen wird. Delgren glaubt, dass er das Geheimnis der abscheulichen Magie des Kults und der Macht, die sie ausüben, birgt. Indem Ihr den Edelstein zu ihm bringt, ermöglicht Ihr Delgren, die dunklen Verzauberungen zu entziffern, die in den Stein gewebt sind, und die Essenz oder Entität aufzudecken, die darin gefangen ist.",al={"was ist der leuchtende seelenedelstein","zweck des leuchtenden seelenedelsteins","seelenedelstein dark strand"}},d0742ede={q="Gegen wen werdet Ihr in Die Ruinen von Ordil'Aran ausgesandt?",a="Ihr werdet ausgesandt, um den Kult von Dark Strand zu konfrontieren, der die Ruinen von Ordil'Aran nordöstlich von Maestras Post besetzt hält. Kultisten, Fanatiker, Akolythen und geübte Zauberwirker haben sich inmitten der elfischen Ruinen versammelt, um verbotene Riten durchzuführen. Eines ihrer Mitglieder trägt einen verzauberten Seelenedelstein, den Delgren benötigt, um die Geheimnisse des Kults freizuschalten, was erfordert, dass Ihr Euch durch ihre Reihen schneidet, bis das Relikt geborgen ist.",al={"wer ist in ordil'aran","dark strand in ordil'aran","wer hält den seelenedelstein"}}},fp="22,227,24.334.0,25.322.0,16.347.1,37.199.0,28.173.0,36.214.0,49.182.0,45.126.1,28.130.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Im Brachland schickt Gur'ak Reisende auf die Jagd nach einem kolossalen Quilboar namens Chol'aruk the Ravener. Er glaubt den Erzählungen und bittet sie, mit dessen Kopf zurückzukehren.",h="Im Brachland schickt Gur'ak Reisende auf die Jagd nach einem kolossalen Quilboar namens Chol'aruk the Ravener.",kw={"brachland","chol'aruk","cholaruk","gur'ak","gurak","quilboar","razormane","der ravener","dornenhügel"},ang={["class:Hunter"]="Als Jäger braucht Ihr scharfe Instinkte und Vorbereitung auf eine furchterregende Beute, um eine Bestie aufzuspüren, die angeblich fünfmal so groß wie ein gewöhnlicher Quilboar ist.",["class:Warrior"]="Als Krieger steht Ihr einer brutalen Kreatur mit unstillbarem Blutdurst gegenüber. Seid bereit, ihrer überwältigenden körperlichen Raserei standzuhalten.",["faction:Horde"]="Gur'ak, ein Orc, ruft Reisende der Horde mit dem Schlachtruf „Blut und Donner“ dazu auf, eine gefährliche Bedrohung im Brachland zu jagen."},sec={{t="Die Legende vom Ravener",b="Die Razormane-Quilboar flüstern von Chol'aruk, einem gewaltigen Schrecken, den sie „The Ravener“ nennen. Sie sagen, er hause tief in einer Höhle am Dornenhügel, nordöstlich der örtlichen Pfade. Ihren Berichten zufolge ist er etwa fünfmal so groß wie ein gewöhnlicher Quilboar und von unstillbarem Blutdurst getrieben. Viele tun die Erzählungen als übertriebene Lagerfeuergeschichten ab. Gur'ak weiß es aus früheren Kämpfen mit ähnlichen Bestien besser."},{t="Gur'aks Warnung",b="Gur'ak weiß, dass eine Bestie dieser Größe eine echte Gefahr darstellt. Er weist fähige Reisende an, Chol'aruk zu seinem Bau am Dornenhügel zu verfolgen, seiner Bedrohung ein Ende zu setzen und seinen Kopf als Beweis zurückzubringen. Der Ravener soll wild und kolossal sein. Gur'ak warnt, dass nur gut vorbereitete Gruppen die Höhle betreten sollten, um ihm entgegenzutreten."}},faq={{q="Wer ist Chol'aruk the Ravener?",a="Die Razormane beschreiben Chol'aruk als einen gewaltigen Quilboar, der als „The Ravener“ bekannt ist. Sie sagen, er sei etwa fünfmal so groß wie ein gewöhnlicher Quilboar, dürste endlos nach Blut und hause tief in einer Höhle im Brachland.",al={"wer ist cholaruk","was ist cholaruk","der ravener"}},{q="Wo ist Chol'aruk zu finden?",a="Chol'aruk haust tief in einer Höhle am Dornenhügel, nordöstlich von Gur'aks Lager im Brachland. Reisende müssen die Höhlen des Dornenhügels betreten, um ihn zu erreichen.",al={"wo ist cholaruk","cholaruk fundort","wo ist die höhle am dornenhügel"}},{q="Wer vergibt die Jagd auf Chol'aruk?",a="Gur'ak, ein Orc im Brachland, schickt Reisende auf die Jagd nach Chol'aruk. Er glaubt den Gerüchten, weil er schon ähnlichen Bestien gegenübergestanden hat.",al={"wer vergibt die cholaruk-quest","wer ist gurak","gurak brachland"}},{q="Warum jagt Gur'ak Chol'aruk?",a="Gur'ak will Chol'aruk vernichtet sehen, weil er die Gegend terrorisiert. Er verlangt den abgetrennten Kopf der Bestie als Beweis dafür, dass der Ravener gefallen ist.",al={"warum cholaruk töten","grund für cholaruks kopfgeld"}},{q="Sollte ich Chol'aruk allein bekämpfen?",a="Gur'ak warnt Reisende davor, Chol'aruk allein entgegenzutreten. Seine angebliche Größe und sein Blutdurst machen ihn zu einem furchterregenden Gegner, weshalb Gur'ak eine vorbereitete Jagdgruppe verlangt.",al={"cholaruk allein besiegen","ist cholaruk schwer","gruppe für cholaruk mitbringen"}},{q="Welche Verbindung besteht zwischen Chol'aruk und den Razormane-Quilboar?",a="Die Razormane-Quilboar sprechen voller Furcht von Chol'aruk und nennen ihn „The Ravener“. Die Razormane sind ein Quilboar-Stamm, der in Teilen des Brachlands lebt, und Quilboar sind im zentralen Kalimdor beheimatete, keilerartige Humanoide.",al={"was sind quilboar","razormane cholaruk","warum fürchten die razormane ihn"}}},fp="21,155,25.395.0,16.307.0,29.209.0,29.149.0,34.130.0,32.141.0,31.151.0,68.209.0"}
P.entries["quest:97005"] = {n="Chol'aruk the Ravener",s="Auf dem Dornenhügel im Brachland haust Chol'aruk the Ravener in einer Höhle. Bainham verlangt seinen abgetrennten Kopf, um Kameraden zu rächen, die Bestien wie ihm zum Opfer fielen.",h="Auf dem Dornenhügel im Brachland haust Chol'aruk the Ravener in einer Höhle.",kw={"abscheulichkeit","bainham","brachland","chol'aruk","borstennacken","der ravener","dornenhügel"},ang={["class:Hunter"]="Als Jäger wird es Euer Können und Euren Mut prüfen, ein Raubtier aufzuspüren, das Gerüchten zufolge Krieger in voller Rüstung im Ganzen verschlingt.",["class:Warrior"]="Als Krieger könnt Ihr Bainhams Ruf folgen, indem Ihr Euch einem gewaltigen Schrecken in seinem unterirdischen Unterschlupf stellt und gefallene Kameraden rächt.",["faction:Horde"]="Ungehindert umherstreifende Monster auf den Hochplateaus bedrohen Reisende und Karawanen, die das Brachland durchqueren. Diese Bestie zu erschlagen würde helfen, die Region zu schützen."},sec={{t="Schrecken des Dornenhügels",b="Nordwestlich von Bainhams Lager erhebt sich der Dornenhügel über die Savanne des Brachlands. Die Borstennackenstämme kämpfen seit Langem um sein Plateau. Nun soll in einer seiner Höhlen eine monströse Abscheulichkeit lauern. Die Borstennacken nennen sie Chol'aruk oder den Ravener. Manche Reisende bezweifeln die Geschichte, dass sie einen gerüsteten Ork im Ganzen verschlingen kann. Wer das Blutbad gesehen hat, weiß, dass die Gefahr wirklich besteht."},{t="Eine beglichene Rechnung",b="Bainham weiß, dass Chol'aruk keine Lagerfeuergeschichte ist. Er hat ähnliche Schrecken bekämpft und trägt Narben von diesen Begegnungen. Seine Kameraden fielen solchen Bestien zum Opfer, und er trauert noch immer um sie. Er fürchtet, dass die Abscheulichkeit jeden bedroht, der die Savanne durchquert. Bainham bittet erfahrene Recken, den Dornenhügel zu erklimmen, den unterirdischen Unterschlupf zu betreten, Chol'aruk zu erschlagen und seinen gewaltigen Kopf zurückzubringen."}},faq={{q="Was für eine Kreatur ist Chol'aruk?",a="Chol'aruk ist eine monströse Abscheulichkeit in einer Höhle auf dem Dornenhügel. Gerüchten zufolge kann sie einen ausgewachsenen Ork im Ganzen verschlingen, und die Borstennacken nennen sie den Ravener.",al={"was ist cholaruk","cholaruk monsterart","wer ist der ravener"}},{q="Wo liegt Chol'aruks Unterschlupf?",a="Chol'aruk haust in einer Höhle auf dem Hochplateau des Dornenhügels im Nordwesten des Brachlands.",al={"wo ist cholaruk","cholaruk fundort","dornenhügel höhle"}},{q="Wer ist Bainham und warum will er Chol'aruks Tod?",a="Bainham lebt im Brachland und hat Bestien wie Chol'aruk bekämpft. Er will seinen Tod, um die Gefährten zu rächen, die er an solche Abscheulichkeiten verlor.",al={"wer vergibt cholaruks quest","warum cholaruk töten","bainhams geschichte"}},{q="Was bedeutet „der Ravener“?",a="Die Stacheleber der Borstennacken nennen Chol'aruk den Ravener, einen Namen, der mit seiner unersättlichen Natur zusammenhängt. Gerüchten zufolge verschlingt er ausgewachsene Krieger im Ganzen.",al={"bedeutung von cholaruk","warum ravener genannt","borstennacken cholaruk"}},{q="Verehren oder fürchten die Stacheleber der Borstennacken Chol'aruk?",a="Niemand weiß, ob die Stacheleber der Borstennacken Chol'aruk fürchten oder verehren. Sie nennen ihn Chol'aruk oder den Ravener, doch mehr ist über ihre Haltung zu der Abscheulichkeit in der Höhle des Dornenhügels nicht bekannt.",al={"mögen stacheleber cholaruk","borstennacken und cholaruk"}},{q="Welcher Beweis ist nötig, um Chol'aruks Tod zu bestätigen?",a="Bainham bittet Euch, Chol'aruks abgetrennten Kopf als Beweis für seinen Tod zurückzubringen.",al={"cholaruk quest abgeben","was muss bainham gebracht werden"}}},fp="21,141,20.371.0,15.372.0,35.145.0,34.81.0,51.134.0,29.135.0,52.198.0,52.78.0"}
P.entries["quest:97048"] = {n="Returning to Port",s="Ein geretteter Koch bittet Euch, mit Captain Aransas in Beutebucht zu sprechen. Seine Rückkehr ist der Kapitänin wichtig, denn sie hat ein Mitglied ihrer Mannschaft verloren.",h="Ein geretteter Koch bittet Euch, mit Captain Aransas in Beutebucht zu sprechen.",kw={"beutebucht","captain aransas","koch","mannschaft","kurzens truppenlager","mathers","rückkehr in den hafen"},sec={{t="Zurück zur Kapitänin",b="Captain Aransas wartet in Beutebucht, wo Ihr den Koch zu ihrem Schiff zurückbringt. Er verspricht, bei seiner Rückkehr gut von Euch zu sprechen, und sagt, die Kapitänin werde sich freuen, ihn wieder bei sich zu haben. Sie heißt Euch willkommen und hört, was Mathers über Eure Flucht aus Kurzens Truppenlager erzählt hat."},{t="Der Dank der Kapitänin",b="Captain Aransas weiß, dass Mathers' Geschichte von waghalsigen Schwertkämpfen erfunden ist; sie sagt, der Koch sei nur dafür geeignet, ein Küchenmesser zu führen. Trotzdem dankt sie Euch dafür, dass Ihr eines ihrer Mannschaftsmitglieder gerettet habt. Ein guter Koch ist an Bord ihres Schiffs kostbar."}},faq={{q="Wer ist Captain Aransas?",a="Captain Aransas befehligt das Schiff, zu dem Ihr ihren Koch in Beutebucht zurückbringt.",al={"captain aransas","aransas"}},{q="Wer ist Mathers?",a="Mathers ist der Koch von Captain Aransas und ein Mitglied ihrer Mannschaft.",al={"mathers","koch mathers"}},{q="Wo finde ich Captain Aransas?",a="Captain Aransas ist in Beutebucht.",al={"aufenthaltsort von aransas","kapitänin in beutebucht"}},{q="Warum dankt mir die Kapitänin?",a="Sie dankt Euch dafür, dass Ihr ein Mitglied ihrer Mannschaft gerettet habt.",al={"grund für den dank","koch gerettet"}},{q="Was hat Mathers über die Flucht erzählt?",a="Mathers erzählte Captain Aransas, dass Ihr beide gemeinsam aus Kurzens Truppenlager ausgebrochen seid.",al={"mathers' geschichte","was erzählte er aransas"}}},fp="17,137,19.272.0,20.212.1,23.76.0,15.58.0,32.32.0,30.47.0,38.85.0"}
P.entries["quest:971"] = {n="Wissen in der Tiefe",s="In Eisenschmiede schickt Gerrig Knochengriff Euch über das Meer, um ein uraltes Manuskript zu suchen. Er will das Manuskript von Lorgalis aus den versunkenen Ruinen der Tiefschwarzen Grotte im Eschental.",h="In Eisenschmiede schickt Gerrig Knochengriff Euch über das Meer, um ein uraltes Manuskript zu suchen.",kw={"eschental","tiefschwarze grotte","forlorn cavern","gerrig knochengriff","eisenschmiede","wissen in der tiefe","manuskript von lorgalis"},ang={["class:Warlock"]="In Eisenschmiedes Forlorn Cavern arbeitet Knochengriff mit Hexenmeistern zusammen, die sich dort verbergen. Er teilt ihren Hunger nach verbotenen Texten, die die Ebenen beugen.",["faction:Alliance"]="Einem Gelehrten der Allianz zu helfen, scheint harmlos, doch Knochengriffs Beweggründe und zwielichtige Gefährten deuten auf finsterere Pläne innerhalb der Mauern Eisenschmiedes hin.",["race:NightElf"]="Das Manuskript liegt in der Tiefschwarzen Grotte, einem versunkenen Nachtelfenheiligtum, das heute von Kultisten und anderen Eindringlingen besetzt ist."},sec={{t="Ein Gelehrter im Schatten",b="In Eisenschmiedes Forlorn Cavern sammelt Gerrig Knochengriff uralte Texte. Seine Interessen reichen über gewöhnliche Geschichtswerke und städtische Aufzeichnungen hinaus. Er sucht vergessenes Wissen, das Pforten öffnen und „Jene, die schlafen“ erwecken kann.\n\nKnochengriff spricht davon, die „Endtage“ zu überleben. Solche Worte lassen ihn entweder wie einen eigenwilligen Gelehrten wirken oder wie einen Anhänger von Mächten, die im Schatten schlummern."},{t="Die versunkene Ruine von Lorgalis",b="Knochengriff schickt Euch an die schattigen Gestade des Eschentals, wo das Nachtelfenheiligtum der Tiefschwarzen Grotte versunken liegt. Bevor die Große Zerschlagung Kalimdor auseinanderriss, sammelten nachtelfische Gelehrte in Küstentempeln umfangreiches magisches Wissen.\n\nHeute streifen Naga, Satyren und Kultisten des Schattenhammers durch die überfluteten Hallen. In ihrer Mitte liegt das Manuskript von Lorgalis, verbotenes Wissen, das in einer Pitted Iron Chest verwahrt wird."},{t="Brüder und Schwestern",b="Als Gerrig Knochengriff das durchnässte Manuskript erhält, bringt er es nicht in Eisenschmiedes Hall of Explorers. Er freut sich darüber, dass Abschriften angefertigt und mit seinen geheimnisvollen „Brüdern und Schwestern“ geteilt werden.\n\nEr dankt dem Abenteurer der Allianz, der es geborgen hat, doch seine Treue gilt einer verborgenen Sekte, die das Wissen für womöglich weltverändernde Riten nutzen will. Knochengriff steht mit dem Schattenhammer in Verbindung, dessen Anhänger nach verbotenem Wissen über die Alten Götter suchen."}},faq={{q="Wer vergibt die Quest Wissen in der Tiefe?",a="Gerrig Knochengriff erteilt den Auftrag. Er ist ein Zwerg, der nach Wissen sucht und in Forlorn Cavern in Eisenschmiede lebt.",al={"questgeber","wo gibt es die quest","wer startet wissen in der tiefe"}},{q="Was ist das Manuskript von Lorgalis?",a="Das Manuskript von Lorgalis ist ein Text, den Gerrig Knochengriff aus der Tiefschwarzen Grotte bergen lassen will. Es liegt in einer Pitted Iron Chest inmitten der überfluteten Ruinen.",al={"was ist das manuskript von lorgalis","wissen über lorgalis","welches buch wird gesucht"}},{q="Wo befindet sich das Manuskript von Lorgalis?",a="Das Manuskript von Lorgalis liegt tief in der Tiefschwarzen Grotte, am Zoramstrand an der nordwestlichen Küste des Eschentals in Kalimdor.",al={"fundort des manuskripts von lorgalis","wo ist das buch in bfd","bfd buchfundort"}},{q="Wer sind „Jene, die schlafen“, von denen Gerrig Knochengriff spricht?",a="Mit „Jene, die schlafen“ meint Knochengriff die schlummernden Mächte, die in dem verbotenen Wissen beschrieben werden, das er sammelt.",al={"jene, die schlafen","von wem spricht knochengriff","was verehrt gerrig"}},{q="Wer sind die „Brüder und Schwestern“, mit denen Gerrig das Manuskript teilen will?",a="Knochengriffs Gefährten teilen sein Interesse an verbotenem Wissen. Die Bergung des Manuskripts kann mehr darüber enthüllen, wem er dient.",al={"gerrigs brüder und schwestern","für wen arbeitet gerrig","knochengriffs fraktion"}},{q="Warum schickt eine Quest in Eisenschmiede Spieler bis ins Eschental?",a="Eisenschmiedes Forlorn Cavern zieht nicht zugelassene Magieanwender, Hexenmeister und Schurken an, die nach Geheimnissen suchen, die dem Licht verborgen bleiben. Knochengriff sammelt altes, mächtiges Wissen, und das gesuchte Manuskript von Lorgalis soll unter der Tiefschwarzen Grotte im Eschental liegen, der einstigen Heimat längst verstorbener Elfen mit großem Wissen.",al={"warum ins eschental reisen","quest von eisenschmiede nach bfd","reise nach blackfathom"}}},fx={["32faf93b"]={q="Warum will Gerrig Knochengriff das Manuskript von Lorgalis?",a="Gerrig Knochengriff sammelt uralte, mächtige Texte, die in der Lage sind, vergessene Tore zu öffnen und Jene, die schlafen, zu erwecken. Er glaubt, dass das Manuskript von Lorgalis längst verlorene Geheimnisse der alten Nachtelfen aus der Tiefschwarzen Grotte enthält, und er beabsichtigt, ihr dunkles Wissen zu kopieren und unter seinen geheimnisvollen Brüdern und Schwestern vor den kommenden letzten Tagen zu verbreiten.",al={"gerrig knochengriffs beweggrund","warum will gerrig das manuskript","grund für gerrig knochengriffs quest"}}},fp="22,175,24.364.0,27.407.0,20.458.1,43.110.0,32.145.0,41.129.0,55.102.0,77.123.1,68.305.0"}
P.entries["quest:97130"] = {n="Ancient Gurubashi Secrets",s="Lan'dalock und ein Gefährte bitten Euch, ein Götzenbild aus einer uralten Gurubashi-Ruine zu bergen, die vor Kurzem vor der Küste des Schlingendorntals aus dem Meer aufgetaucht ist. Der Ort könnte wertvolle Hinweise auf die Blutmagie der Gurubashi bergen.",h="Lan'dalock und ein Gefährte bitten Euch, ein Götzenbild aus einer uralten Gurubashi-Ruine zu bergen, die vor...",kw={"ancient gurubashi idol","geheimnisse der uralten gurubashi","blutmagie","drowned city","gurubashi","lan'dalock","die südlichen meere","schlingendorntal","hexendoktoren"},sec={{t="Eine Ruine erhebt sich",b="Lan'dalock und ein Gefährte haben über eine seltsame Veränderung in den südlichen Meeren gesprochen. Vor der Küste des Schlingendorntals ist eine uralte Gurubashi-Ruine aufgetaucht. Ihre plötzliche Rückkehr weckt das Interesse jener, die sich mit der Vergangenheit befassen."},{t="Ein Idol der Gurubashi",b="Die Drowned City birgt Artefakte von großem archäologischem Wert. Lan'dalock sucht ein Idol, das einst bestimmten Gurubashi-Hexendoktoren als Fokus für Blutmagie diente. Ihr sollt eines zur Untersuchung zurückbringen."}},faq={{q="Wer will das Idol?",a="Lan'dalock und ein Gefährte suchen in der Drowned City nach einem Ancient Gurubashi Idol.",al={"wer hat mich geschickt","lan'dalocks idol","wer will es"}},{q="Wo ist die Gurubashi-Ruine aufgetaucht?",a="Die uralte Gurubashi-Ruine ist vor der Küste des Schlingendorntals in den südlichen Meeren aufgetaucht.",al={"wo ist die drowned city","fundort der ruine","gurubashi-stadt"}},{q="Warum wollen sie ein Idol?",a="Bestimmte uralte Gurubashi-Hexendoktoren verwendeten Idole als Fokus für Blutmagie, und Lan'dalock möchte eines untersuchen.",al={"warum das idol","zweck des idols","wofür ist es"}},{q="Was ist die Drowned City?",a="Sie ist eine uralte Gurubashi-Ruine, die vor der Küste des Schlingendorntals aufgetaucht ist.",al={"drowned city","versunkene gurubashi-ruinen","uralte ruinen"}}},fp="25,179,12.220.0,24.204.0,19.80.0,36.90.0,25.114.0,25.81.0"}
P.entries["quest:97196"] = {n="The Coldbringer's Eye",s="Ein Diener des Lich King beobachtet Euch durch das Coldbringer’s Eye aus den Hügeln der Klingenhauer. Ihr sollt die Kugel bergen, damit verdeckte Agenten der Geißel auf Kalimdor gejagt werden können.",h="Ein Diener des Lich King beobachtet Euch durch das Coldbringer’s Eye aus den Hügeln der Klingenhauer.",kw={"amnennar","coldbringer","coldbringers auge","death's head quilboar","lich king","hügel der klingenhauer","geißel","wahrsagekugel"},sec={{t="Eine Kugel im Versteck",b="Eine Wahrsagekugel erlaubt Amnennar the Coldbringer, seine Diener anderswo zu beobachten und zu lenken. Er haust tief in den Hügeln der Klingenhauer, dem Versteck der Death's Head quilboar. Ihr sollt das Coldbringer's Eye bergen, das bei der Jagd auf die verdeckten Agenten der Geißel auf Kalimdor helfen könnte."}},faq={{q="Wer ist Amnennar the Coldbringer?",a="Amnennar the Coldbringer ist ein Diener des Lich King, der in den Hügeln der Klingenhauer haust.",al={"amnennar","coldbringer wer"}},{q="Was ist das Coldbringer's Eye?",a="Das Coldbringer's Eye ist eine Wahrsagekugel, mit der Amnennar seine Diener anderswo beobachtet und lenkt.",al={"coldbringers auge","die augenkugel"}},{q="Wo ist das Coldbringer's Eye?",a="Das Coldbringer's Eye befindet sich in den Hügeln der Klingenhauer, in Amnennar the Coldbringer's Versteck.",al={"wo ist das auge","kugel hügel der klingenhauer"}},{q="Warum wird die Kugel gesucht?",a="Die Kugel könnte dabei helfen, verdeckte Agenten der Geißel auf Kalimdor zu jagen und die von ihnen ausgehende Bedrohung zu beenden.",al={"warum das auge holen","agenten der geißel"}}},fp="21,172,18.262.0,32.84.0,30.97.0,31.79.0,22.94.0"}
P.entries["quest:972"] = {n="Wassersapta",s="Am Ufer bei Islen Wasserdeuter erhält ein junger Schamane der Horde Wassersapta für eine Reise über das große Meer. Die Prüfung führt vom Brachland in den Silberwald, wo eine Quelle verdorben wurde.",h="Am Ufer bei Islen Wasserdeuter erhält ein junger Schamane der Horde Wassersapta für eine Reise über das große...",kw={"call of water","islen wasserdeuter","schamanenprüfung","silberwald","brachland","totemquest","wassersapta"},ang={["class:Shaman"]="Als Schamane macht Ihr mit Wassersapta einen entscheidenden Schritt in Euren elementaren Prüfungen. Sie öffnet Euch die Augen für die Geisterwelt, bevor Ihr die Macht über Euer heilendes Wassertotem erlangt.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie diese Prüfung Eingeweihte von Kalimdors sonnengebleichten Ebenen in Lordaerons heimgesuchte Wälder führt."},sec={{t="Eine Vision des Wassers",b="Unter Schamanen der Horde ist eine Sapta ein Trank, der die Sinne für die Geister der Welt öffnet. Gewöhnlichen Augen mag ein Bach ruhig und ein Teich still erscheinen. Trinkt Ihr eine Sapta, teilt sich der Schleier der stofflichen Welt. Dann werden die Elementare sichtbar, die im Wasser wohnen."},{t="Der Weg zum Silberwald",b="Nachdem der Schamane seine Hingabe an die Geister bewiesen hat, gibt Islen Wasserdeuter ihm den Trank. Sie lebt allein am kargen Ufer südlich von Ratschet. Dann schickt sie den Eingeweihten über das große Meer, von Kalimdors trockenen Tälern in den Silberwald. Dort vergiftet eine elementare Verderbnis die Bäche Lordaerons, und der Schamane muss sich ihr stellen."}},faq={{q="Was ist Wassersapta?",a="Eine Sapta ist ein zeremonieller Trank, den schamanische Lehrmeister zubereiten. Sie schärft den Geisterblick, sodass Schamanen Elementare sehen und mit ihnen sprechen können, die sterblichen Augen verborgen bleiben.",al={"was ist sapta","wassersapta bedeutung","was bewirkt sapta"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Meisterschamanin, die allein an der Ostküste des Brachlands lebt, südlich der Händlerküste. Sie führt junge Schamanen der Horde auf dem beschwerlichen Weg, mit dem Element Wasser in Verbindung zu treten und es zu binden.",al={"islen wasserdeuter hintergrundgeschichte","wer ist islen"}},{q="Warum muss der Schamane in den Silberwald reisen?",a="Die Wasserelementare im Silberwald leiden unter einem weitverbreiteten Übel. Um ihre Einweihung abzuschließen, tragen Schamanen die Sapta über das Meer, sehen eine verdorbene Wasserquelle mit eigenen Augen und reinigen sie dann von ihrer Verderbnis.",al={"warum silberwald","warum in die östlichen königreiche reisen"}},{q="Was geschieht nach dem Trinken der Sapta?",a="Nach dem Trinken der Sapta können Schamanen die verdorbenen Wasserelementare in den verseuchten Tümpeln des Silberwalds sehen. Dieser Anblick ermöglicht es ihnen, sich dem Ursprung der Verderbnis zu stellen.",al={"sapta trinken","sapta wirkung"}},{q="Müssen alle Schamanen der Horde diese Prüfung ablegen?",a="Ja. Schamanen der Orcs, Tauren und Trolle folgen alle dem Call of Water und erhalten die Sapta als Übergangsritus, bevor sie sich ihr Wassertotem verdienen.",al={"wer nimmt diese quest an","ist das eine klassenquest"}},{q="Wo im Silberwald liegt der verdorbene Tümpel?",a="Die verdorbene Quelle liegt an der Küste des Silberwalds, westlich des Grabmals.",al={"silberwald tümpel fundort","wo ist der wassertümpel"}}},fx={c8d11240={q="Warum schickt Euch Islen Wasserdeuter in den Silberwald?",a="Islen Wasserdeuter versucht, Euch durch Euren spirituellen Ritus zu führen und Euch dabei zu helfen, Euch auf die elementaren Kräfte des Wassers einzustimmen. Um die Gemeinschaft mit den Geistern des Wassers zu verdienen und den Call of Water zu vollenden, müsst Ihr Euch dem Makel stellen und ihn reinigen, der die Wasserwege der Welt plagt. Sie hat Euch mit einer vorbereiteten Water Sapta betraut, damit Ihr verborgene elementare Verderbnis aus erster Hand wahrnehmen und Eure Hingabe als aufstrebender Schamane beweisen könnt.",al={"warum will islen das","islen wasserdeuters beweggrund","warum korrumpiertes wasser reinigen"}}},fp="11,195,17.259.0,22.331.0,22.160.0,23.207.0,48.216.0,38.157.0,44.138.0,50.78.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Bei Philmor's Favor ist eine heikle Lieferung für das Gatehouse in Sturmwind bestimmt. Da Dockarbeiter fehlen, bringen Reisende sie zu einem Lagerraumeingang über Trias' Cheese im Handelsdistrikt.",h="Bei Philmor's Favor ist eine heikle Lieferung für das Gatehouse in Sturmwind bestimmt.",kw={"elaine","gatehouse","gatehouse-lieferung","philmor","philmor's favor","sturmwind","der handelsdistrikt","trias' cheese"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, die Lieferungen durch Sturmwinds Handelsdistrikt in Gang zu halten, während Dockarbeiter fehlen."},sec={{t="Angespannte Logistik in Sturmwind",b="Sturmwinds Frachtführern fehlen Dockarbeiter, und die üblichen Frachtpläne geraten unter Druck. Sie verlassen sich auf vertrauenswürdige Reisende, die empfindliche Kisten ins Handelsviertel der Stadt bringen und die Lieferungen in Gang halten."},{t="Diskrete Lieferungen bei Trias' Cheese",b="Die Lieferung für das Gatehouse hat ein ungewöhnliches Ziel. Bringt die Kiste in den zweiten Stock von Trias' Cheese im Handelsdistrikt, wo ein verborgener Eingang in einen Lagerraum führt. Vorräte und zeremonielle Geschenke für die Offiziere der Wache gelangen dort hindurch, fernab neugieriger Blicke."}},faq={{q="Wer braucht Hilfe bei dieser Lieferung?",a="Sturmwinds Frachtführer brauchen Hilfe, um trotz fehlender Dockarbeiter die Frachtpläne einzuhalten.",al={"wer vergibt philmor's favor","philmor questgeber"}},{q="Wohin soll die Lieferung gebracht werden?",a="Bringt die Lieferung zum Lagerraumeingang des Gatehouse im zweiten Stock von Trias' Cheese in Sturmwinds Handelsdistrikt.",al={"wohin das paket bringen","trias cheese lieferung","wo ist der gatehouse-eingang"}},{q="Wer nimmt die Lieferung entgegen?",a="Elaine, die Inhaberin von Trias' Cheese, kümmert sich um diskrete Fracht für den nahe gelegenen Lagerraum des Gatehouse.",al={"wer ist elaine","elaine trias cheese"}},{q="Was enthält die Lieferung für das Gatehouse?",a="Die Lieferung enthält empfindliche Waren für das Gatehouse. Die örtlichen Frachtführer behandeln Lieferungen diskret, die mit zeremoniellen Überraschungen für die Offiziere der Wache zusammenhängen.",al={"was ist im paket","gatehouse lieferungsinhalt"}},{q="Warum führt der Zugang zu einem Militärlagerraum durch einen Käseladen?",a="Trias' Cheese verfügt im Obergeschoss über einen Zugang zum Lagerraum des Gatehouse, durch den Fracht diskret und ohne den militärischen Haupteingang passieren kann.",al={"warum trias cheese gatehouse","geheimer eingang trias cheese"}},{q="Warum fehlen Dockarbeiter?",a="Die Hafen- und Frachtarbeiter sind die ganze Woche über unterbesetzt, weshalb die Logistikkoordinatoren auf Reisende angewiesen sind, um Liefertermine einzuhalten.",al={"warum fehlen dockarbeiter","sturmwind dockarbeitermangel"}}},fp="15,191,31.219.0,36.281.0,34.99.0,34.121.0,26.99.0,38.147.0,59.142.0,34.141.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="In Sturmwind führt Gatehouse Goods von Trias' Cheese zum benachbarten Torhaus. Die Lieferung wird über die Ladentreppe zu einem Treppenabsatz im gemeinsamen Stockwerk gebracht, wo Wachen sie vor dem Lagerraum abholen können. Gemeinsam genutzte Räumlichkeiten verbinden die Geschäfte und Verteidigungsanlagen der Stadt.",h="In Sturmwind führt Gatehouse Goods von Trias' Cheese zum benachbarten Torhaus.",kw={"lieferung","elling trias","gatehouse goods","torhauslieferung","lagerraum","sturmwind","trias cheese"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie Ihr Euch bei Trias' Cheese leise bewegt, und bemerkt Einzelheiten wie Türen, die sich nach innen öffnen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr mit diskreten Lieferungen bei Trias' Cheese, Waren zwischen den Ladenbesitzern von Sturmwind und dem benachbarten Torhaus zu transportieren."},sec={{t="Gemeinsame Räume und Stockwerke",b="Kuriere tragen eine Lieferung für das Torhaus die Treppe im Inneren von Trias' Cheese hinauf. Der Käseladen ist ein eigenständiges Geschäft mit eigenem Warenbestand, doch sein Gebäude teilt sich ein Stockwerk mit dem benachbarten Torhaus. Vom oberen Treppenabsatz aus können Kuriere Vorräte zwischen den beiden Räumlichkeiten transportieren, ohne die davorliegenden Prachtstraßen zu benutzen."},{t="Ein praktischer Ablageort",b="Die Kiste wird vor der Tür des Lagerraums abgestellt, statt hineingetragen zu werden. Die Torhauswachen halten nach Lieferungen Ausschau und sorgen dafür, dass jemand jedes Paket bei der Rückkehr auf seinen Posten abholt. Die Tür öffnet sich nach innen, sodass eine Kiste davor weder den Eingang versperrt noch jemanden im Inneren behindert."}},faq={{q="Was ist Gatehouse Goods?",a="Gatehouse Goods ist ein Lieferauftrag in Sturmwind zwischen Trias' Cheese und dem benachbarten Torhaus. Ein Kurier trägt die Lieferung die Treppe hinauf und stellt sie vor der Tür des Torhauslagerraums ab.",al={"was ist gatehouse goods","gatehouse goods quest"}},{q="Wohin soll die Lieferung gebracht werden?",a="Die Lieferung wird die Treppe im Inneren von Trias' Cheese hinaufgetragen. Obwohl der Laden ein eigenständiges Geschäft ist, teilt sich sein Gebäude ein Stockwerk mit dem Torhaus, und die Kiste wird vor dem Lagerraum abgestellt.",al={"trias cheese torhaus","wohin geht die lieferung"}},{q="Warum wird die Kiste vor der Tür abgestellt, statt hineingetragen zu werden?",a="Der Kurier wird angewiesen, die Kiste vor dem Lagerraum abzustellen. Die Torhauswachen halten nach Lieferungen Ausschau und sorgen dafür, dass jemand sie bei der Rückkehr auf seinen Posten hineinträgt.",al={"warum nicht drinnen abliefern","wer holt die kiste ab"}},{q="Warum öffnet sich die Tür des Lagerraums nach innen?",a="Die Tür des Lagerraums öffnet sich nach innen, damit draußen abgestellte Waren weder den Eingang versperren noch Personen im Inneren behindern.",al={"nach innen öffnende tür trias","scharnier der lagerraumtür"}},{q="Gehört Trias' Cheese zum Torhaus?",a="Nein. Trias' Cheese ist ein eigenständiges Geschäft mit eigenem Warenbestand, teilt sich jedoch ein Stockwerk mit dem Torhaus.",al={"gehört trias cheese zum torhaus","trias cheese warenbestand"}},{q="Wer beaufsichtigt die Warenlieferung?",a="Die Verantwortlichen vor Ort organisieren die Lieferung und erwarten professionellen Respekt und Diskretion. Nach einer erfolgreichen Übergabe, bei der die Türschwelle frei bleibt, erkennen sie die Arbeit zuverlässiger Kuriere an.",al={"wer vergibt gatehouse goods","wer nimmt die lieferung an"}}},fp="15,269,33.307.0,20.281.0,24.184.0,47.186.0,65.171.0,40.106.0,47.109.0,39.181.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="Nahe Sen'jin bedroht die Bloodtalon Matriarch Tierführer, die nach ihren Jungen suchen. Ihr Rudel wird für Schnelligkeit und Schläue geschätzt, doch erwachsene Tiere widersetzen sich der Zähmung. Die Dunkelspeer wollen ihr Gelege sichern und aus den Eiern treue Gefährten aufziehen.",h="Nahe Sen'jin bedroht die Bloodtalon Matriarch Tierführer, die nach ihren Jungen suchen.",kw={"bloodtalon","dunkelspeer","matriarchin","raptor","raptoreneier","raptoren","sen'jin","senjin","reittiere der trolle"},ang={["class:Hunter"]="Als Jäger wisst Ihr, wie schwer es ist, ein erfahrenes, erwachsenes Wildtier zu zähmen. Ein Raubtier von Geburt an aufzuziehen, kann eine wahre Bindung schaffen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass das Aufziehen heimischer Raubtiere zu treuen Verbündeten die Siedlung der Dunkelspeer schützt und die Präsenz der Horde an Durotars Küste stärkt.",["race:Troll"]="Als Dunkelspeertroll wisst Ihr, dass die Tierführer in Sen'jin Raptoren als wendige Gefährten und Kriegsreittiere schätzen. Die Bloodtalon-Linie wird für Schläue und Schnelligkeit geschätzt."},sec={{t="Die Bloodtalon-Blutlinie",b="Entlang der Küste von Durotar werden Bloodtalon-Raptoren für Schnelligkeit und Schläue geschätzt. Tierführer in Sen'jin schätzen diese Eigenschaften an zuverlässigen Reittieren und Gefährten für die Dunkelspeer vom Darkspear tribe. Doch ausgewachsene Raptoren besitzen sture, gewalttätige Instinkte. Einmal ausgewachsen, lassen sich wilde Tiere kaum noch zähmen."},{t="Die Blutlinie bewahren",b="Wiederholte Versuche, die Matriarchin einzufangen und abzurichten, haben sie nur noch aggressiver gemacht. Nun bedroht sie das umliegende Gebiet. Die Trolle wollen ihren Stamm schützen und ihre Blutlinie bewahren. Sie müssen die gefährliche Mutter bezwingen und ihr Gelege retten, damit die nächste Generation aus den Eiern zu treuen Verbündeten herangezogen werden kann."}},faq={{q="Wer ist die Bloodtalon Matriarch?",a="Die Bloodtalon Matriarch ist ein wildes, ausgewachsenes Raptorenweibchen, dessen Rudel für Schnelligkeit und Schläue bekannt ist. Versuche, sie einzufangen und abzurichten, scheiterten, da der Umgang mit ihr zu gefährlich wurde. Die Dunkelspeertrolle wollen ihre Eier sichern.",al={"wer ist bloodtalon matriarch","bloodtalon raptorenmatriarchin","raptorenmatriarchin"}},{q="Warum muss die Bloodtalon Matriarch bezwungen werden?",a="Die Matriarchin ist zu einer Gefahr für das umliegende Gebiet geworden, und erwachsene Raptoren lassen sich nur schwer zähmen. Indem die Tierführer in Sen'jin sie bezwingen und ihr Gelege sichern, können sie den Stamm schützen und ihre Blutlinie bewahren.",al={"warum matriarchin töten","warum eier sichern","warum die matriarchin jagen"}},{q="Warum wird die Matriarchin nicht stattdessen gezähmt?",a="Ausgewachsene Raptoren besitzen sture, gewalttätige Instinkte und lassen sich nahezu unmöglich zähmen. Tierführer können stattdessen die Jungen aus den Eiern zu treuen Gefährten aufziehen.",al={"lassen sich erwachsene raptoren zähmen","erwachsenen raptor abrichten"}},{q="Was geschieht mit den Nachkommen der Matriarchin?",a="Das sichergestellte Gelege wird nach Sen'jin gebracht, wo die Eier ausgebrütet und die Jungen aufgezogen werden. Die Trolle wollen die jungen Raptoren von klein auf zu zuverlässigen Verbündeten und Reittieren für den Stamm abrichten.",al={"was geschieht mit den eiern","junge der matriarchin","raptoren in senjin"}},{q="Wo spielt sich diese Quest ab?",a="Die Arbeit konzentriert sich auf die Umgebung von Sen'jin an der Küste von Durotar. Dort wollen Tierführer treue Raptoren für die Dunkelspeer vom Darkspear tribe aufziehen.",al={"wo wird diese quest abgegeben","senjin raptorenquest"}},{q="Was macht das Bloodtalon-Rudel besonders?",a="Das Bloodtalon-Rudel wird für Schnelligkeit und Schläue geschätzt. Diese Eigenschaften machen seine Jungen zu begehrten Gefährten und Reittieren, während sich ausgewachsene Raptoren der Zähmung widersetzen.",al={"eigenschaften der bloodtalon-raptoren","warum bloodtalon-raptoren"}}},fp="20,247,22.284.0,24.325.0,32.216.0,48.223.0,35.154.0,46.178.0,29.131.0,39.156.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="Die Dunkelspeer suchen nach Forgotten Loa Idols, damit ihre heiligen Riten fortbestehen können. Die Relikte bewahren das Band des Stammes zu seinen Schutzgeistern.",h="Die Dunkelspeer suchen nach Forgotten Loa Idols, damit ihre heiligen Riten fortbestehen können.",kw={"dunkelspeer","forgotten loa idols","idole","loa","ehrfurcht","rituale","geister","troll"},ang={["class:Priest"]="Als Trollpriester nutzt Ihr Rituale und heilige Gegenstände Eurer Ahnen, um spirituelle Macht zu kanalisieren und die Loa zu ehren.",["class:Shaman"]="Als Trollschamane ruft Ihr die Kräfte der Elemente an und ehrt dabei die wilden Götter und angestammten Loa, von denen das Überleben Eures Stammes abhängt.",["faction:Horde"]="Als Mitglied der Horde gehört Ihr einer Fraktion an, zu deren Gründungsmitgliedern die Dunkelspeer zählen. Ihren heiligen Ältesten beim Erhalt lebenswichtiger religiöser Artefakte zu helfen, stärkt den Zusammenhalt des Stammes.",["race:Troll"]="Als Troll der Dunkelspeer steht die Zwiesprache mit den Loa im Mittelpunkt Eures spirituellen Lebens. Verlorene Idole ermöglichen die Fortführung lebenswichtiger Rituale und helfen, dem Stamm das Wohlwollen der Geister zu erhalten."},sec={{t="Heilige Überreste der Loa",b="Die Dunkelspeer ehren die Loa durch heilige Riten. Diese urtümlichen Tiergeister und wilden Götter gehören zum angestammten Erbe der Trolle. Die verlorenen Idole werden für Zeremonien zu ihren Ehren benötigt. Ohne sie können spirituelle Anführer die Riten nicht vollziehen, die den Stamm im Einklang mit seinen göttlichen Wächtern halten."},{t="Das Band der Dunkelspeer",b="Die Dunkelspeer begegnen den Loa mit Respekt und demütiger Ehrfurcht. Andere feindselige Trollfraktionen in ganz Azeroth bringen Blutopfer dar oder versuchen, Geister mit Gewalt zu beherrschen. Die Gunst ihrer Schutzgeister zu verlieren, wäre für die Dunkelspeer eine schwere Katastrophe. Deshalb ist die Wiederbeschaffung der Idole für den Erhalt des Stammes lebenswichtig."}},faq={{q="Welchem Zweck dient Forgotten Loa Idols?",a="Die Dunkelspeer brauchen die verschwundenen heiligen Idole, damit sie ihre Stammesrituale wieder aufnehmen und ihre wilden Geister ehren können.",al={"forgotten loa idols","worum geht es bei dieser quest","was ist forgotten loa idols"}},{q="Was sind Loa?",a="Die Loa sind mächtige, uralte Naturgeister und Tiergottheiten, die von Trollen verehrt werden. Trolle ehren sie mit Opfergaben, Gebeten und rituellen Zeremonien und bitten dabei um Schutz, Gunst und spirituelle Führung.",al={"was sind loa","trollgötter","wer sind die loa"}},{q="Wie betrachten die Dunkelspeer ihre Loa im Vergleich zu anderen Trollstämmen?",a="Die Dunkelspeer begegnen den Loa mit tiefer Ehrfurcht, gegenseitigem Respekt und einem Gefühl spiritueller Pflicht. Sie glauben, dass ihr Überleben davon abhängt, die Gunst der Geister zu bewahren.",al={"beziehung zwischen dunkelspeer und loa","warum loa verehren","loa anderer stämme"}},{q="Warum werden die Idole für Stammesrituale benötigt?",a="Die Idole sind heilige Gegenstände, die für Stammesriten benötigt werden. Ohne sie können Älteste und spirituelle Anführer nicht auf die gebotene Weise mit ihren Schutzgeistern in Verbindung treten und sie ehren.",al={"warum werden idole gebraucht","zweck der loa-idole","warum sind idole wichtig"}},{q="Warum ist es für die Dunkelspeer so lebenswichtig, die Gunst der Loa zu bewahren?",a="Die Dunkelspeer fürchten, ohne die gebotenen Riten und Opfergaben die Gunst und den Schutz der Loa zu verlieren, wodurch der Stamm in einer gefährlichen Welt verwundbar wäre.",al={"was geschieht ohne rückgabe","in ungnade fallen","gunst der loa für die dunkelspeer"}},{q="Wer verlangt die Rückgabe der Forgotten Loa Idols?",a="Ein spiritueller Führer der Dunkelspeer sucht die Idole zurückzuerlangen und will unbedingt die gemeinsamen Zeremonien wieder aufnehmen und den Segen der angestammten Schutzgeister des Stammes sichern.",al={"wer vergibt forgotten loa idols","questgeber","wer bittet um idole"}}},fp="19,142,26.307.0,18.305.0,43.117.0,13.198.0,67.163.0,44.157.0,57.159.0,48.157.0"}
P.entries["quest:97234"] = {n="Reading Room",s="In Roys Buchclub tauschen Mitglieder ältere Literatur gegen neuere Werke aus der Bibliothek von Sturmwind. Eingepackte Bücher vermitteln den Austausch zwischen dem Club und dem Bibliothekar.",h="In Roys Buchclub tauschen Mitglieder ältere Literatur gegen neuere Werke aus der Bibliothek von Sturmwind.",kw={"bücher","legenden","bibliothekar","reading room","roys buchclub","stormwind library","wälzer"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr die Royal Library in Burg Sturmwind besuchen. Bürgerlicher und wissenschaftlicher Austausch trägt dazu bei, das geistige Leben der Stadt zu erhalten."},sec={{t="Literarische Bestrebungen in Sturmwind",b="Roys Buchclub versammelt Leser in Sturmwind, um klassische Legenden und provokante Schriften zu besprechen. Damit diese Gespräche lebendig bleiben, wechseln die Mitglieder ihre Lektüre. Sie tauschen ältere oder weniger beliebte Werke gegen neuere Bände aus der Bibliothek der Stadt."},{t="Austausch mit der Library",b="Roys Buchclub unterhält eine bewährte Leihvereinbarung mit der Bibliothek von Sturmwind. Roy verpackt die zurückgegebenen Bücher des Clubs auf unverwechselbare Weise, und Ihr bringt sie zum Bibliothekar. Im Gegenzug erhält der Club eine neue Liste moderner Wälzer."}},faq={{q="Worum geht es bei der Quest Reading Room?",a="Roys Buchclub tauscht ältere Bücher gegen moderne Wälzer aus der Bibliothek von Sturmwind. Ihr bringt ein eingepacktes Bündel weniger beliebter Werke zum Austausch in die Bibliothek.",al={"reading room quest","was ist reading room","reading room geschichte"}},{q="Wer ist Roy?",a="Roy leitet einen Leseclub, dessen Mitglieder Legenden und Literatur besprechen. Er vereinbart mit der Bibliothek von Sturmwind einen regelmäßigen Wechsel der Lektüre und gibt geliehene Bücher in tadellosem Zustand zurück.",al={"wer ist roy","roys buchclub","leiter des buchclubs"}},{q="Wohin werden die Bücher gebracht?",a="Die Bücher gehen an die Bibliothek in Sturmwind. Der Bibliothekar erkennt die unverwechselbare Verpackung von Roys Buchclub und nimmt die Bücher im Austausch gegen moderne Schriften an.",al={"wohin gehen die bücher","bücherabgabe bibliothek sturmwind","eingepackte lektüre abliefern"}},{q="Warum werden die Bücher ausgetauscht?",a="Der Club tauscht im Rahmen seiner Leihvereinbarung mit der Stadtbibliothek weniger beliebte Bücher gegen modernere Werke, die zum Nachdenken anregen.",al={"warum bücher tauschen","warum wälzer zurückgeben","lektüre austauschen"}},{q="Wie steht der Bibliothekar von Sturmwind zum Buchclub?",a="Der Bibliothekar von Sturmwind ist mit der Vereinbarung zufrieden. Roys Buchclub gibt geliehene Bücher in ausgezeichnetem Zustand zurück und behandelt jeden Text sorgsam, selbst wenn sein Thema provokant ist.",al={"was denkt der bibliothekar","ist der buchclub erlaubt","vereinbarung mit der bibliothek"}},{q="Welche Erfrischungen des Clubs werden erwähnt?",a="Der Club bietet Besuchern und Helfern, die beim Bücheraustausch zwischen dem Lesetreff und dem Stadtarchiv helfen, kostenlose Erfrischungen an.",al={"kostenlose erfrischungen im club","clubvorteile","welche erfrischungen"}}},fp="12,163,30.238.0,20.236.0,31.161.0,11.185.0,32.154.0,34.135.0,52.182.0,41.136.0"}
P.entries["quest:97236"] = {n="Fangzahn von Githyiss",s="Nahe Aldrassil bringt die Jagd auf Githyiss ein seltenes Exemplar in die Zuflucht. Gelehrte können den Reißzahn der Riesenspinne untersuchen und nach Raubtieren im Laubschattental Ausschau halten.",h="Nahe Aldrassil bringt die Jagd auf Githyiss ein seltenes Exemplar in die Zuflucht.",kw={"aldrassil","fang of githyiss","githyiss","laubschattental","spinne","spinnenforschung","teldrassil"},ang={["class:Druid"]="Als Druide wacht Ihr über Teldrassils natürliches Gleichgewicht, indem Ihr ungewöhnliche Raubtiere und übergroße Spinnen in der umliegenden Wildnis untersucht.",["faction:Alliance"]="Als Abenteurer der Allianz helft Ihr Forschern und jungen Rekruten in ganz Teldrassil, mehr über die gefährliche Tierwelt nahe Aldrassil zu erfahren.",["race:NightElf"]="Als junger nachtelfischer Abenteurer im Laubschattental helft Ihr, Teldrassil zu verteidigen, indem Ihr Euch gefährlichen Kreaturen stellt und Aldrassils Forscher unterstützt."},sec={{t="Ein monströses Exemplar",b="Githyiss bedroht Reisende in der Wildnis des Laubschattentals. Der Reißzahn der Riesenspinne ist sowohl als Gefahr als auch als untersuchenswertes Exemplar von Bedeutung. Kundschafter tragen ihn durch das Unterholz zur Zuflucht unter dem großen Baum."},{t="Forschung in Aldrassil",b="In Aldrassil beobachten Naturforscher und Gelehrte der Nachtelfen die Tierwelt auf dem Waldboden. Ein frischer, unversehrter Reißzahn einer Spinne von Githyiss' Größe kann ihnen Aufschluss über die Spinnentiere unter Teldrassils Blätterdach geben. Die Forscher begrüßen den Fund bei ihren Studien über die aggressiven Kreaturen der Lichtung."}},faq={{q="Was ist der Fang of Githyiss?",a="Der Reißzahn ist ein frisches Exemplar von der großen Spinne Githyiss. Seine Größe bietet Forschern seltenes Material, um räuberische Spinnentiere nahe Aldrassil zu untersuchen.",al={"was ist fang of githyiss","githyiss reißzahn quest","fang of githyiss gegenstand"}},{q="Wer oder was ist Githyiss?",a="Githyiss ist eine große, gefährliche Spinne, die durch die Wälder nahe Aldrassil im Laubschattental streift. Ihre Größe bedroht Reisende und weckt das Interesse der örtlichen Naturforscher.",al={"wer ist githyiss","githyiss spinne","wo ist githyiss"}},{q="Wer möchte den Fang of Githyiss haben?",a="Ein Gelehrter in Aldrassil, der Spinnen erforscht, möchte den Reißzahn haben. Frische Exemplare helfen Forschern, mehr über die örtlichen Spinnentiere zu erfahren.",al={"wer gibt fang of githyiss ab","wohin den reißzahn bringen","spinnenforscher aldrassil"}},{q="Wo liegt Aldrassil?",a="Aldrassil ist der große Ast und die zentrale Zuflucht des Laubschattentals, in der Krone des Weltbaums Teldrassil. Junge Nachtelfen üben dort und finden Schutz.",al={"wo liegt aldrassil","aldrassil standort"}},{q="Warum untersuchen die Gelehrten in Aldrassil Spinnenreißzähne?",a="Aldrassils Gelehrte und Naturforscher untersuchen örtliche Spinnen, um die Ökologie des Laubschattentals zu verstehen und die aggressiven, übergroßen Bestien unter Teldrassils Blätterdach zu beobachten.",al={"warum werden in aldrassil spinnen erforscht","warum spinnenreißzähne untersuchen"}},{q="Können Spieler der Horde den Fang of Githyiss abgeben?",a="Nein. Das Laubschattental, die Startenklave der Nachtelfen auf Teldrassil, steht Abenteurern der Allianz offen, die ihre Reise in Aldrassil beginnen.",al={"ist diese quest nur für die allianz","kann die horde fang of githyiss erledigen"}}},fp="16,158,20.218.0,21.285.0,29.145.0,24.165.0,31.125.0,19.157.0,52.169.0,47.133.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="In Sturmwind schickt Roy Lewells einen Boten los, um Bücher für eine Lesegruppe im Park zu holen.",h="In Sturmwind schickt Roy Lewells einen Boten los, um Bücher für eine Lesegruppe im Park zu holen.",kw={"buchklub","kurier","library","park","roy lewells","shelf picked","sturmwind"},ang={["faction:Alliance"]="Kurieraufträge zwischen Sturmwinds Bibliotheken und örtlichen Treffpunkten gehören zum Alltag in der Hauptstadt, selbst inmitten größerer Spannungen im Königreich."},sec={{t="Ein Auftrag zwischen Regalen",b="Roy Lewells hat eine Nachricht geschickt und um mehrere Bücher aus der Bibliothek von Sturmwind gebeten. Der Bibliothekar prüft die Liste und bestätigt, dass jeder Titel vorrätig ist. Die Bücher warten darauf, dass Ihr sie findet und aus den Regalen nehmt. Der Bibliothekar bleibt am Schreibtisch, um die Bestandsaufzeichnungen zu führen."},{t="Der Leseklub im Keller",b="Roy Lewells' Nachricht macht Euch zum offiziellen Kurier, sodass Ihr nicht für die Rückgabe der ausgeliehenen Bücher verantwortlich seid. Diese Pflicht liegt bei Lewells' Einrichtung. Sobald Ihr die Bände in den Park bringt, bereitet Roy sie für lebhafte Diskussionen nach Feierabend in einem Keller vor. Die Bücher haben einen exotischen Geruch."}},faq={{q="Wer vergibt die Quest Shelf Picked?",a="Ein Bibliothekar, der die Bibliothek von Sturmwind beaufsichtigt, gibt Euch den Auftrag, nachdem er Roy Lewells' Nachricht erhalten hat. Der Bibliothekar bestätigt, dass die gewünschten Bücher vorrätig sind, und bittet Euch, sie aus den Regalen zu holen.",al={"wer vergibt shelf picked","shelf picked questgeber","wo beginnt shelf picked"}},{q="Wer ist Roy Lewells?",a="Roy Lewells organisiert eine örtliche Lesegruppe im Park von Sturmwind. Er schickt Kuriere los, um Bücher aus der Bibliothek für die Diskussionen der Gruppe nach Feierabend in einem Keller zu holen.",al={"wer ist roy lewells","roy lewells park","wer ist lewells"}},{q="Wo werden die Bücher eingesammelt?",a="Die Bücher werden in einer Bibliothek in Sturmwind eingesammelt. Der Bibliothekar führt die Bestandsaufzeichnungen, während Ihr in den Regalen nach den von Roy Lewells gewünschten Titeln sucht.",al={"welche bibliothek ist das","wo werden die bücher geholt","welche bibliothek shelf picked"}},{q="Warum braucht Roy Lewells diese Bücher?",a="Roy Lewells braucht die Bücher für einen zwanglosen Buchklub, dessen Mitglieder sich nach Feierabend zu lebhaften Diskussionen in einem Keller versammeln.",al={"warum bücher für lewells holen","was ist lewells' buchklub","buchklub nach feierabend im keller"}},{q="Seid Ihr für die Rückgabe der ausgeliehenen Bücher verantwortlich?",a="Nein. Mit Roy Lewells' Nachricht handelt Ihr als offizieller Kurier. Seine Einrichtung ist für die Rückgabe der ausgeliehenen Bücher verantwortlich.",al={"verantwortung für die bücherrückgabe","wer gibt die bücher aus shelf picked zurück","verantwortung für die rückgabe von bibliotheksbüchern"}},{q="Wohin bringt Ihr die Bücher, nachdem Ihr sie geholt habt?",a="Ihr bringt die eingesammelten Bücher zu Roy Lewells im Park von Sturmwind.",al={"wo wird shelf picked abgegeben","wo ist roy lewells zu finden","shelf picked abgabe"}}},fp="12,89,24.274.0,23.294.0,33.201.0,19.175.0,42.154.0,38.122.0,53.127.0,44.65.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="In Yelmak's Alchemy and Potions im Tal der Ehre in Orgrimmar nehmen die Spannungen zu. Meisteralchemist Yelmak hofft, mit einer beruhigenden Mischung aus heimischen Wasserpflanzen die ungeschickten Frustausbrüche und den sturen Stolz seines Lehrlings Whuut zu dämpfen.",h="In Yelmak's Alchemy and Potions im Tal der Ehre in Orgrimmar nehmen die Spannungen zu.",kw={"alchemie","rohrkolben","kor'geld","orgrimmar","speergras","tal der ehre","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Spannungen im Tal der Ehre in Orgrimmar und im dortigen Alchemiehandwerk abzubauen.",["profession:Herbalism"]="Als Kräuterkundiger sammelt Ihr frische Rohrkolben und frisches Speergras entlang der Wasserläufe von Orgrimmar. Heimische Pflanzen lassen sich für Mixturen und Kräutersude verwenden."},sec={{t="Ärger im Labor",b="In Yelmak's Alchemy and Potions sorgt der Stolz des jungen Lehrlings Whuut für Ärger. Statt um Hilfe zu bitten, wenn er überfordert ist, zerstört er aus Frust die Ausrüstung des Ladens. Meisteralchemist Yelmak will den Jüngling beruhigen, ohne sein empfindliches Ego zu verletzen, und ersinnt deshalb ein besänftigendes Gebräu."},{t="Beruhigende heimische Pflanzen",b="Das Rezept verlangt frische Rohrkolben und frisches Speergras aus den Wasserläufen, die sich durch das Tal der Ehre schlängeln. Kor'geld kann den Laden nicht verlassen, ohne den misstrauischen Lehrling aufmerksam zu machen, also muss jemand die Pflanzen unauffällig sammeln. Die Pflanzenmischung soll Whuuts Verhalten mäßigen und den Frieden im Alchemieladen wiederherstellen."}},faq={{q="Wer vergibt die Quest Yelmak's Medley?",a="Kor'geld vergibt die Aufgabe im Auftrag des Meisteralchemisten des Ladens. Er ist in Yelmak's Alchemy and Potions im Tal der Ehre in Orgrimmar zu finden.",al={"wer vergibt yelmak's medley","questgeber yelmak's medley"}},{q="Wer ist Whuut?",a="Whuut ist ein angehender Mischer, der bei Yelmak im Tal der Ehre lernt. Sein sturer Stolz treibt ihn dazu, Ausrüstung zu zerstören, statt zuzugeben, dass er Anleitung oder Hilfe braucht.",al={"wer ist whuut","yelmaks lehrling","whuut orgrimmar"}},{q="Welchen Zweck hat die selbstgebraute Mischung?",a="Die selbstgebraute Mischung soll Yelmaks stolzen Lehrling besänftigen und seine schlechte Laune mildern. Dafür werden frische Schnittlinge von Rohrkolben und Speergras verwendet.",al={"was ist das rezept für yelmak's medley","was will yelmak brauen"}},{q="Wo werden die Zutaten gesammelt?",a="Wilde Rohrkolben und wildes Speergras wachsen entlang der Süßwasserbäche und Teiche im Tal der Ehre in Orgrimmar.",al={"wo findet man rohrkolben und speergras","schnittlinge im tal der ehre"}},{q="Warum sammelt Kor'geld die Schnittlinge nicht selbst?",a="Kor'geld kann Yelmak's Alchemy and Potions nicht verlassen, ohne dass Whuut merkt, dass die Ladenbelegschaft auf sein schwieriges Temperament Rücksicht nimmt.",al={"warum braucht korgeld hilfe","warum kann korgeld keine pflanzen sammeln"}},{q="Wo befindet sich Yelmak's Alchemy and Potions?",a="Yelmak's Alchemy and Potions liegt im Tal der Ehre, einem östlichen Viertel von Orgrimmar. Seine Wasserläufe ziehen sich zwischen Kriegerkasernen und Handwerksläden hindurch.",al={"wo ist yelmak's alchemy and potions","yelmaks laden standort"}}},fp="15,228,25.302.0,20.325.0,37.142.0,13.167.0,46.140.0,35.117.0,52.131.0,46.149.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="Im Himmelswall tragen Initianden die Torch of Dormant Flame zu Olariaan Swiftburn, um unterwiesen zu werden. Der Schrein liegt im Böenbeerentiefland.",h="Im Himmelswall tragen Initianden die Torch of Dormant Flame zu Olariaan Swiftburn, um unterwiesen zu werden.",kw={"call of fire","elementarebene","böenbeerentiefland","olariaan swiftburn","shen'dorei","shrine of flames","der himmelswall","torch of dormant flame","valanaar","windformer"},ang={["class:Shaman"]="Den Elementen zu lauschen, ist grundlegend für die schamanische Ausbildung. Selbst im Himmelswall erfordert das Zwiegespräch mit dem Feuer hingebungsvolle Anleitung und Ehrfurcht vor den Ahnen.",["race:Skyborne"]="Obwohl Ihr in den Winden des Himmelswalls beheimatet seid, wisst Ihr ebenso wie die Windformer, dass Gleichgewicht bedeutet, alle vier urtümlichen Elemente zu ehren."},sec={{t="Stimmen über die Elementarebene",b="Der Himmelswall gehört den Luftelementaren, doch seine Strömungen reichen bis in die übrige Elementarebene. Geister der Erde, des Wassers und des Feuers sprechen weiterhin zu jenen, die sie hören können. Manche Windformer sind für diese anderen Kräfte besonders empfänglich. Olariaan Swiftburn, ein Shen'dorei in ihren Reihen, ist tief auf das Feuer eingestimmt."},{t="Der Shrine of Flames",b="Initianden bringen die Torch of Dormant Flame ins Böenbeerentiefland. Weit draußen am Inselrand, westlich von Valanaar, steht der Shrine of Flames, das Zuhause von Olariaan Swiftburn. Olariaan nimmt die schlummernde Flamme entgegen und bietet wissbegierigen Schülern an, inmitten der aufgewühlten Strömungen des Luftreichs dem fordernden Ruf des Feuers folgen zu lernen."}},faq={{q="Wer ist Olariaan Swiftburn?",a="Olariaan Swiftburn ist ein Shen'dorei-Windformer, der tief auf das Feuer eingestimmt ist. Olariaan lebt am Shrine of Flames, am Rand des Böenbeerentieflands westlich von Valanaar.",al={"wer vergibt call of fire","zu wem die fackel bringen","olariaan swiftburn"}},{q="Wo liegt der Shrine of Flames?",a="Der Shrine of Flames liegt im Böenbeerentiefland des Himmelswalls. Er steht am Rand der schwebenden Insellandschaft, direkt westlich von Valanaar.",al={"wo liegt shrine of flames","lage des böenbeerentieflands","wie olariaan finden"}},{q="Warum wird im Himmelswall das Feuer erforscht?",a="Der Himmelswall gehört der Luft, bleibt jedoch Teil der größeren Elementarebene. Die Geister aller vier Elemente sprechen dort weiterhin zu jenen, die feinfühlig genug sind, ihnen zu lauschen.",al={"warum feuer im himmelswall","elementarebene feuer","ist der himmelswall nicht nur luft"}},{q="Was ist die Torch of Dormant Flame?",a="Die Torch of Dormant Flame ist ein elementarer Fokus, der zu Olariaan Swiftburn getragen wird. Ein Initiand bringt sie dorthin, um im Zwiegespräch mit dem Feuer unterwiesen zu werden.",al={"was ist die schlummernde flamme","torch of dormant flame","welchen gegenstand tragen"}},{q="Wer sind die Windformer?",a="Die Windformer üben sich darin, die elementaren Kräfte im Himmelswall zu lenken und zu formen. Zu ihren Reihen zählen Angehörige verschiedener Herkunft, darunter die Shen'dorei.",al={"wer sind die windformer","windformer fraktion"}},{q="Wozu führt diese Quest?",a="Olariaan Swiftburn lehrt Schüler, dem Ruf des Feuers zu folgen. Die urtümlichen Kräfte in der fordernden Domäne des Himmelswalls zu meistern, verlangt große Ausdauer.",al={"was lehrt olariaan","feuerausbildung im himmelswall"}}},fp="12,133,33.297.0,20.312.0,26.163.0,30.145.0,37.152.0,35.145.0,24.146.0,29.142.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="Die Windformer schicken Euch auf die Jagd nach einem Verräter, der Macht seinem Orden vorzog. Skypriest Faladiel ist ins Böenbeerentiefland geflohen, und sie brauchen sein Herz für ein Ritual.",h="Die Windformer schicken Euch auf die Jagd nach einem Verräter, der Macht seinem Orden vorzog.",kw={"al'aketh","call of fire","faladiel","faladiels herz","böenbeerentiefland","schrein von akir","skypriest faladiel","valanaar","windformer"},ang={["class:Priest"]="Als Priester erkennt Ihr Faladiels Fall womöglich darin, dass er sich vom Anrufen der Flamme abwandte, um Mitglieder seines eigenen Ordens zu verraten und zu ermorden.",["class:Shaman"]="Als Schamane, der mit Feuer und Elementarriten vertraut ist, erkennt Ihr womöglich die urtümliche Natur dieses Handelns: die Essenz eines Verräters den Flammen darzubringen, um ihre heilige Macht zu verstärken."},sec={{t="Ein Verräter unter den Flammen",b="Die Windformer schicken Euch auf die Jagd nach Skypriest Faladiel, der einst zu ihnen gehörte. Er verließ den Orden, um sich den Al'Aketh anzuschließen, und tauschte seine Berufung als Rufer der Flamme gegen Macht ein. Er verriet seine früheren Brüder und Schwestern, und ihr Blut klebt an seinen Händen. Nun schicken die Windformer Euch, um ihr Urteil zu vollstrecken."},{t="Abrechnung im Tiefland",b="Faladiel versteckt sich auf einem Bauernhof im Böenbeerentiefland, nordöstlich hinter Valanaar und knapp südlich des Schreins von Akir. Die Windformer wollen mehr als Rache. Sie brauchen sein Herz für ein bevorstehendes Ritual. Sie glauben, dass das Herz eines Verräters ihren heiligen Flammen unvergleichliche Intensität verleihen wird."},{t="Blut mit Blut vergolten",b="Die Windformer halten an ihrem Glaubenssatz fest: Blut muss mit Blut vergolten werden. Faladiels Herz ist nur ein Teil dessen, was ihr zeremonielles Feuer nähren muss, bevor ihre Riten abgeschlossen werden können."}},faq={{q="Wer ist Skypriest Faladiel?",a="Skypriest Faladiel war einst ein hingebungsvoller Rufer der Flamme und ein Mitglied der Windformer. Er schloss sich den Al'Aketh an, um Macht zu erlangen, verriet seine früheren Brüder und Schwestern und befleckte seine Hände mit ihrem Blut.",al={"wer ist faladiel","faladiels vorgeschichte","skypriest faladiel hintergrund"}},{q="Warum wollen die Windformer Faladiel töten lassen?",a="Faladiel verriet die Windformer für Macht und ermordete seine früheren Brüder und Schwestern. Ihr Glaubenssatz verlangt, Blut mit Blut zu vergelten, und so fordern sie seine Hinrichtung als Vergeltung.",al={"warum faladiel töten","warum wollen die windformer faladiels tod","faladiels verrat"}},{q="Warum brauchen die Windformer Faladiels Herz?",a="Die Windformer brauchen Faladiels Herz für ein Ritual. Sie glauben, dass das Herz eines Verräters ihre Flammen heißer und mit größerer Intensität brennen lässt.",al={"warum faladiels herz","wofür ist das herz","ritualreagenz herz"}},{q="Wo ist Skypriest Faladiel zu finden?",a="Skypriest Faladiel versteckt sich auf einem Bauernhof im Böenbeerentiefland, nordöstlich hinter Valanaar und knapp südlich des Schreins von Akir.",al={"wo ist faladiel","skypriest faladiel aufenthaltsort","faladiel finden"}},{q="Wie lautet der Glaubenssatz der Windformer?",a="Der Glaubenssatz der Windformer besagt, dass Blut mit Blut vergolten werden muss. Sie rufen die Flamme an und vollziehen heilige Elementarrituale.",al={"wer sind die windformer","glaubenssatz der windformer","windformer fraktion"}},{q="Welche Verbindung haben die Al'Aketh zu dieser Mission?",a="Zu den Al'Aketh gehören Mitglieder, die frühere Treuebindungen und ihre Ehre gegen persönliche Macht eingetauscht haben. Skypriest Faladiel ist eines dieser Mitglieder.",al={"was sind die alaketh","faladiel alaketh","alaketh verräter"}}},fp="12,165,25.301.0,25.282.0,21.176.1,26.207.0,44.181.0,45.145.0,38.123.0,37.122.0,50.127.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="Im Shen'darhochland schickt Euch Olariaan Swiftburn zu Kuramaa, einem uralten Waldgeist. Flammen können seinen Schutz durchdringen, und seine hölzerne Maske wird im Böenbeerentiefland benötigt, um eine ewige Flamme zu entzünden und mit Feuergeistern Zwiesprache zu halten.",h="Im Shen'darhochland schickt Euch Olariaan Swiftburn zu Kuramaa, einem uralten Waldgeist.",kw={"anchor pylon","call of fire","waldgeist","böenbeerentiefland","kuramaa","kuramaas maske","olariaan swiftburn","shen'darhochland"},ang={["class:Mage"]="Als Magier stellt Ihr fest, dass Kuramaa den meisten Formen der Magie widersteht. Nur Feuermagie kann den Geist bezwingen.",["class:Shaman"]="Als Schamane tretet Ihr einem Geist des Hochlands mit Flammen entgegen und sammelt Macht, um mit Feuergeistern Zwiesprache zu halten."},sec={{t="Der Geist des Hochlands",b="Die Menschen im Shen'darhochland erzählen von Kuramaa, einem uralten Waldgeist, der in einem verdrehten Baumstumpf haust. Der Stumpf steht auf einem Hügel nahe dem regionalen Anchor Pylon. Schlagt mit bloßer Faust gegen die Rinde, und Kuramaa kommt hervor, um gegen Euch zu kämpfen."},{t="Feuer und Holz",b="Kuramaas natürliche Schutzzauber wehren die meiste arkane und göttliche Magie ab. Nur sengende Flammen durchdringen seine uralte Rinde und bringen ihn zu Fall. Besiegt den Geist, und seine hölzerne Maske gehört Euch, ein Artefakt von großer Macht. Doch Kuramaa ist ewig. Wird er erneut gerufen, nimmt er wieder Gestalt an."},{t="Die ewige Flamme",b="Im Böenbeerentiefland wartet Olariaan Swiftburn auf Kuramaas Maske. Das verzauberte Relikt wird benötigt, um eine ewige Flamme zu entzünden und mit den Geistern des Feuers Zwiesprache zu halten. Der Sieg über Naturgeister des Hochlands ebnet im Ritual den Weg zu uralter Zwiesprache mit den Elementen."}},faq={{q="Wer ist Kuramaa?",a="Kuramaa ist ein uralter Waldgeist, der im Shen'darhochland haust. Einheimische sagen, er lebe in einem verdrehten Baumstumpf auf einem Hügel nahe dem Highlands Anchor Pylon.",al={"wer ist kuramaa","kuramaa hintergrundgeschichte","was ist kuramaa"}},{q="Wer ist Olariaan Swiftburn?",a="Olariaan Swiftburn ist ein Ritualist im Böenbeerentiefland, der Euch aussendet, um Kuramaa entgegenzutreten. Olariaan benötigt die hölzerne Maske des Geistes für ein heiliges Feuerritual.",al={"wer vergibt call of fire","wer ist olariaan swiftburn","wo call of fire abgeben"}},{q="Wie ruft Ihr Kuramaa herbei?",a="Kuramaa haust in einem verdrehten Baumstumpf auf einem Hügel nahe dem Anchor Pylon im Shen'darhochland. Schlagt mit der Faust gegen die Rinde des Stumpfs, und der Geist kommt zum Kampf hervor.",al={"wie kuramaa herbeirufen","wo ist kuramaas baumstumpf","waldgeist herbeirufen"}},{q="Wogegen ist Kuramaa im Kampf verwundbar?",a="Kuramaa widersteht den meisten Formen der Magie. Nur Flammen können seinen Schutz durchdringen und den uralten Waldgeist zu Fall bringen.",al={"kuramaa schwächen","wie kuramaa besiegen","kuramaa magieimmun"}},{q="Warum benötigt Olariaan Swiftburn Kuramaas Maske?",a="Olariaan Swiftburn benötigt Kuramaas mächtige hölzerne Maske, um eine ewige Flamme zu entzünden und mit Feuergeistern Zwiesprache zu halten.",al={"warum kuramaas maske sammeln","was bewirkt die maske","kuramaas maske zweck"}},{q="Wird Kuramaa durch eine Niederlage endgültig vernichtet?",a="Nein. Kuramaa ist ewig. Sein Geist besteht weiter, nachdem seine körperliche Gestalt besiegt wurde, und nimmt erneut Gestalt an, wenn er gerufen wird.",al={"ist kuramaa tot","habe ich kuramaa getötet","kuramaa wiedererscheinen hintergrundgeschichte"}}},fp="12,243,27.254.0,13.259.0,17.259.1,15.169.0,26.161.0,26.171.0,40.113.0,48.113.0,47.113.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="In Orgrimmar sorgt sich Thatog, dass sein junger Sohn Migi Mahlzeiten auslässt, um zu spielen. Er bittet Euch, Mittagessen von Borstans Kochfeuer zu holen und Migi hinter Grommash Hold zu finden.",h="In Orgrimmar sorgt sich Thatog, dass sein junger Sohn Migi Mahlzeiten auslässt, um zu spielen.",kw={"borstan","borstans kochfeuer","grommash hold","mittagessen liefern","meal appeal","migi","orgrimmar","thatog"},ang={["faction:Horde"]="Orgrimmars Alltag bringt auch Sorgen jenseits von Krieg und Verteidigung mit sich. Thatog sorgt sich darum, dass Kinder wie Migi genug zu essen bekommen, während sie durch das Tal der Stärke rennen.",["race:Orc"]="Als Orc wisst Ihr, wie sich Eltern wie Thatog sorgen, wenn ihre Kinder Mahlzeiten vernachlässigen, um in den Straßen von Durotars Hauptstadt zu spielen."},sec={{t="Elternpflichten in Orgrimmar",b="Thatogs tägliche Pflichten halten ihn an seinem Posten in Orgrimmar. Er hat wenig Zeit, auf Migi, seinen lebhaften jungen Sohn, aufzupassen. Von morgens bis zur Dämmerung flitzt Migi mit seinen Freunden durch die Stadt. Oft ignoriert er seinen Hunger, bis er ausgehungert nach Hause kommt."},{t="Lieferung hinter Grommash Hold",b="Thatog lässt bei Borstans Kochfeuer ein warmes Mittagessen für Migi vorbereiten und bittet Euch, es ihm zu bringen. Migi spielt lieber weiter, als zum Essen eine Pause einzulegen. Also bringt Ihr die Mahlzeit zum Hof hinter Grommash Hold, wo Migi und die Kinder aus der Nachbarschaft spielen."}},faq={{q="Wer ist Thatog?",a="Thatog ist ein Orc und Vater in Orgrimmar, dessen tägliche Pflichten ihn daran hindern, auf seinen jungen Sohn Migi aufzupassen. Er sorgt sich, dass Migi Mahlzeiten auslässt, um mit Freunden zu spielen, und bittet Euch, das Mittagessen des Jungen abzuholen und ihm zu bringen.",al={"wer ist thatog","questgeber thatog","thatog orgrimmar"}},{q="Wo ist Migi zu finden?",a="Migi verbringt seine Tage damit, mit Freunden in Orgrimmar zu spielen. Laut Thatog könnt Ihr die Kinder hinter Grommash Hold finden.",al={"wo ist migi","migi aufenthaltsort","migi finden"}},{q="Was ist Borstans Kochfeuer?",a="Borstans Kochfeuer ist ein Ort in Orgrimmar, an dem es Essen gibt. Thatog bittet Euch, dort das für Migi vorbereitete Mittagessen abzuholen und es ihm zu bringen.",al={"wo ist borstans kochfeuer","borstans kochfeuer standort","borstan mittagessen"}},{q="Warum vergisst Migi zu essen?",a="Migi ist so ins Spielen mit Freunden hinter Grommash Hold vertieft, dass er das Essen vernachlässigt. Oft kommt er am Ende des Tages hungrig nach Hause.",al={"warum lässt migi das mittagessen aus","migi ausgehungert","warum isst migi nicht"}},{q="Wer ist Migi?",a="Migi ist Thatogs junger Sohn. Er verbringt seine Zeit damit, mit Freunden in Orgrimmar zu spielen, statt nach Hause zu kommen oder seine vorbereiteten Mahlzeiten abzuholen.",al={"wer ist migi","migi orckind","thatogs sohn"}},{q="Was ist das Ziel von Meal Appeal?",a="Ihr holt Migis Mittagessen bei Borstans Kochfeuer ab und bringt es ihm hinter Grommash Hold, damit er beim Spielen essen kann.",al={"meal appeal questziel","was ist bei meal appeal zu tun","meal appeal aufgabe"}}},fp="11,160,28.244.0,24.234.0,14.203.0,24.115.0,26.132.0,28.130.0,12.137.0,37.121.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="In Orgrimmar sorgen sich Migis Eltern, dass er vor lauter Spielen zu wenig isst. Borstan von Borstan's Meats bereitet abwechslungsreiche Mittagessen mit einem Geschmack zu, den Migi liebt, damit er und seine Freunde zum Essen innehalten.",h="In Orgrimmar sorgen sich Migis Eltern, dass er vor lauter Spielen zu wenig isst.",kw={"borstan","borstan's meats","favorite food","grommash hold","schweinebauch","mittagessen","migi","orgrimmar","süße glasur"},ang={["faction:Horde"]="Dies zeigt den Alltag in Orgrimmar, wo Handwerker und Familien sich um die Kinder der Hauptstadt kümmern und dafür sorgen, dass sie genug zu essen haben.",["profession:Cooking"]="In Orgrimmar verarbeitet Borstan knusprige Grieben von geräuchertem Schweinebauch zu einer schmackhaften Würze für die täglichen Mahlzeiten."},sec={{t="Appetit aufs Spielen",b="Hinter Grommash Hold verbringen der junge Migi und seine Freunde ihre Nachmittage mit Spielen auf Orgrimmars staubigen Pfaden. Seine Eltern sorgen sich, dass er oft seine Mahlzeiten vernachlässigt und nicht genug isst. Deshalb bitten sie Borstan's Meats, täglich Lunchpakete zuzubereiten. Sie bestehen darauf, dass Borstan die Mahlzeiten variiert, in der Hoffnung, dass Migi mehr als nur ein Lieblingsgericht zu schätzen lernt."},{t="Der Kompromiss mit süßer Glasur",b="Migi liebt Sandwiches mit süß glasiertem Schweinebauch und kommt zum Mittagessen, wenn ihr süßer Duft die Räucherei erfüllt. Borstan findet einen Weg, dem Wunsch seiner Eltern nachzukommen und zugleich dafür zu sorgen, dass Migi genug isst. Er zerbröselt die übrig gebliebenen knusprigen, glasierten Grieben zu einer herzhaften Würze, die sich über jedes Gericht streuen lässt. Hinter Grommash Hold bringt diese Würze Migi und seine Gefährten dazu, ihr Spiel zu unterbrechen und gemeinsam zu Mittag zu essen."}},faq={{q="Wer ist Migi?",a="Migi ist ein junger Bewohner von Orgrimmar, der hinter Grommash Hold mit Freunden spielt. Seine Eltern sorgen sich, dass er vor lauter Spielen nicht genug isst, und lassen deshalb täglich Mittagessen von Borstan's Meats zubereiten.",al={"migi orgrimmar","wer ist das kind hinter grommash hold","migi mittagessen"}},{q="Wer vergibt die Quest Favorite Food?",a="Borstan von Borstan's Meats vergibt sie in Orgrimmar. Er bereitet eine abwechslungsreiche Mahlzeit zu, nachdem er erfahren hat, dass Migis Eltern sich um die Essgewohnheiten des Jungen sorgen.",al={"favorite food questgeber","wer vergibt favorite food","borstan favorite food"}},{q="Wo ist Migi zu finden?",a="Migi ist hinter Grommash Hold in Orgrimmar zu finden, wo er mit anderen Kindern aus der Gegend spielt. Sie sind oft auf der Straße zur Festung unterwegs und erkennen Borstans tägliche Mahlzeiten an ihrem Duft.",al={"migi aufenthaltsort","wo ist migi","wo migis mittagessen abliefern","migi in orgrimmar finden"}},{q="Was ist Migis Lieblingsessen?",a="Migi liebt das Sandwich mit süß glasiertem Schweinebauch, das im Räucherofen von Borstan's Meats zubereitet wird. Wenn der Räucherofen in Betrieb ist, lockt ihn sein Duft zum Mittagessen hinter Grommash Hold.",al={"was isst migi gern","migis lieblingsessen","süß glasierter schweinebauch migi"}},{q="Warum wünschen sich Migis Eltern unterschiedliche Mahlzeiten?",a="Migis Eltern bitten Borstan, seine Mahlzeiten zu variieren, damit ihr Sohn mehr als nur ein Gericht zu schätzen lernt. Sie möchten, dass er genug isst, ohne sich allein auf süß glasiertes Schweinefleisch zu verlassen.",al={"warum migis mittagessen variieren","wunsch von migis eltern","warum nicht täglich süß glasierte sandwiches"}},{q="Wie bringt Borstan Migi dazu, unterschiedliche Speisen zu essen?",a="Borstan zerbröselt übrig gebliebene knusprige, glasierte Grieben zu einer Würze für verschiedene Gerichte. Der vertraute Geschmack der süßen Glasur hilft Migi, die abwechslungsreichen Mahlzeiten zu genießen.",al={"borstans trick","wie bringt borstan migi zum essen","brösel mit süßer glasur"}},{q="Was ist Borstan's Meats?",a="Borstan's Meats ist eine Räucherei und Metzgerei in Orgrimmar. Borstan räuchert Schweinebauchsandwiches und bereitet Lunchpakete für die Stadtbewohner zu, darunter auch Jugendliche aus der Nachbarschaft.",al={"borstan's meats orgrimmar","wo ist borstan's meats","was ist borstan"}}},fp="13,185,20.349.0,25.403.0,12.215.0,34.147.0,24.188.0,29.167.0,46.167.0,49.153.0,24.171.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="Wrongly Blamed, Justly Corrected handelt von wachsenden Spannungen zwischen Horde und Allianz an der Ostküste, nachdem eine Taverne am Wegesrand zerstört wurde. Der Vorfall warnt die Streitkräfte der Allianz, während offenbleibt, wer eine lebenswichtige zivile Handelsroute bedroht hat.",h="Wrongly Blamed, Justly Corrected handelt von wachsenden Spannungen zwischen Horde und Allianz an der...",kw={"warnung an die allianz","zivile reiseroute","ostküste","handel der horde","taverne","gebietskonflikt","wrongly blamed, justly corrected"},ang={["faction:Alliance"]="Der Ausgang warnt die Allianz vor weiterer Präsenz und weiteren Provokationen an der Ostküste.",["faction:Horde"]="Der Ausgang ist ein Sieg der Horde und eine Warnung vor Vorstößen der Allianz. Er weckt außerdem Sorge um den Schutz der Handelsrouten und zivilen Straßen, auf die die Horde angewiesen ist."},sec={{t="Spannungen an der Küste",b="An der Ostküste greifen Scharmützel zwischen Horde und Allianz auf umkämpftes Gebiet über. Dann wird eine Taverne an einer wichtigen Durchgangsstraße zerstört. Gewöhnliche Reisende sind nun Gefahren ausgesetzt, und die Stabilität der Region steht auf dem Spiel."},{t="Zweifel und Störungen",b="Die örtlichen Anführer bezweifeln, dass Streitkräfte der Horde die Taverne zerstört haben, obwohl der Verdacht zuerst auf die Horde fiel. Zivilisten und Händler sind auf diese Straße angewiesen, um Waren zu transportieren, daher hat die Horde Grund, sie offen zu halten. Die Anführer fordern eine genauere Untersuchung darüber, wer die Taverne zerstört hat."},{t="Eine Warnung an die Allianz",b="Die Angelegenheit endet mit einem Sieg für die Streitkräfte der Horde in der Gegend, obwohl Fragen zur Taverne offenbleiben. Der Ausgang warnt die Allianz, dass jeder Vorstoß in das Gebiet der Horde entlang der Küste auf sofortigen Widerstand stoßen wird."}},faq={{q="Worum geht es in Wrongly Blamed, Justly Corrected?",a="Wrongly Blamed, Justly Corrected handelt von wachsenden Spannungen zwischen Horde und Allianz an der Ostküste, nachdem eine Taverne am Wegesrand an einer lebenswichtigen Handelsroute zerstört wurde.",al={"worum geht es in dieser quest","wrongly blamed justly corrected hintergrundgeschichte","was geschah in wrongly blamed"}},{q="Hat die Horde die Taverne zerstört?",a="Die Anführer der Horde bezweifeln, dass ihre Streitkräfte die Taverne zerstört haben. Die Zivilisten der Horde sind für Handel und alltägliche Reisen auf die Route angewiesen, daher schadet die Zerstörung ihren Interessen.",al={"hat die horde die taverne zerstört","wer hat die taverne niedergebrannt","wer hat die taverne zerstört"}},{q="Warum ist die zerstörte Taverne für die Horde von Bedeutung?",a="Die Taverne liegt an einer wichtigen Straße, die von zivilen Reisenden und Händlern genutzt wird. Ihre Zerstörung beeinträchtigt den Handel und das Reisen, weshalb die Straße für die Horde Anlass zur Sorge ist.",al={"warum ist die route an der taverne wichtig","warum ist die taverne wichtig"}},{q="Was hat die Spannungen an der Ostküste ausgelöst?",a="Die Ursache der Spannungen ist unklar. Die Spannungen zwischen Horde und Allianz an der Ostküste nehmen zu, und der Konflikt hat das Gebiet der Horde erreicht.",al={"warum gibt es kämpfe an der ostküste","konflikt an der ostküste"}},{q="Welche Botschaft sendet dieser Ausgang an die Allianz?",a="Der Ausgang warnt die Allianz, dass Vorstöße in das Gebiet der Horde entlang der Küste auf Widerstand stoßen werden.",al={"was hat die horde erreicht","warum eine warnung an die allianz"}},{q="Wird die Zerstörung der Taverne weiter untersucht?",a="Die Anführer der Horde wollen genauer untersuchen, wer die Taverne zerstört hat. Ihre Zerstörung bedroht den zivilen Reiseverkehr, und die Umstände bleiben verdächtig.",al={"was soll untersucht werden","wird die taverne untersucht"}}},fp="32,254,21.212.0,20.248.1,25.211.0,47.160.0,33.171.0,50.162.0,42.162.0,52.105.0,61.139.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="In Ratschet liegt Wrenix' Maschine in Einzelteilen, nachdem die Piraten sie auseinandergenommen haben. Er schickte sie gegen die Plünderer, nachdem fünf oder sechs Mercenaries nicht lebend zurückgekehrt waren. Nun liegen ihre verstreuten Teile im oberen Lager der Piraten.",h="In Ratschet liegt Wrenix' Maschine in Einzelteilen, nachdem die Piraten sie auseinandergenommen haben.",kw={"komplizierte teile","maschine","parts and pieces","pirat","piraten","ratschet","krummsäbel","oberes piratenlager","wrenix der jämmerliche"},ang={["profession:Engineering"]="Ingenieuren mag die Ironie auffallen, dass Piraten eine ausgefeilte Maschine auseinandernehmen. Wrenix' verstreute Teile zeigen, wie gefährlich es ist, einen automatisierten Prototyp ohne physische Schutzvorrichtungen in ein feindliches Lager zu schicken."},sec={{t="Eine mechanische Lösung",b="Piraten an der Küste südlich von Ratschet machen den Bewohnern und Händlern der Stadt zu schaffen. Wrenix der Jämmerliche wollte sie aufhalten, ohne weitere Münzen für angeheuerte Kämpfer auszugeben. Fünf oder sechs Mercenaries waren bereits gegen die Piraten ausgezogen und nicht lebend zurückgekehrt.\n\nAlso schickte Wrenix eine automatisierte Maschine los, um sich allein um das Lager zu kümmern. Er hoffte, das Gerät könne den Plünderern entgegentreten, ohne eine weitere lebende Seele in Gefahr zu bringen."},{t="Krummsäbel und Schraubenzieher",b="Die Piraten südlich von Ratschet erwiesen sich als einfallsreich. Sie benutzten ihre gebogenen Krummsäbel als behelfsmäßige Schraubenzieher und zerlegten Wrenix' Maschine, bevor er ihr den Rückzugsbefehl in Richtung Stadt schicken konnte.\n\nIhre empfindlichen Bauteile liegen nun verstreut in ihrem oberen Lager. Wrenix braucht jemanden, der sich hineinschleicht und fünf Handvoll der komplizierten Teile aus dem Dreck aufsammelt."}},faq={{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist ein exzentrischer Tüftler in der Hafenstadt Ratschet. Nachdem fünf oder sechs Mercenaries nicht lebend von den Piraten südlich der Stadt zurückgekehrt waren, schickte er eine automatisierte Maschine gegen sie. Die Piraten zerlegten sie, und ihre Teile liegen verstreut in ihrem oberen Lager.",al={"wer ist wrenix","wrenix der jämmerliche lore","ratschet wrenix"}},{q="Was geschah mit den früheren Mercenaries, die Wrenix angeheuert hatte?",a="Wrenix heuerte fünf oder sechs Mercenaries an, um sich um die Piraten südlich von Ratschet zu kümmern. Keiner kehrte lebend zurück, also wandte er sich stattdessen einer Maschine zu.",al={"wrenix frühere mercenaries","was geschah mit den anderen abenteurern","wen schickte wrenix zuerst"}},{q="Warum schickte Wrenix eine Maschine gegen die Piraten?",a="Wrenix schickte eine Maschine los, weil fünf oder sechs angeheuerte Mercenaries nicht lebend zurückgekehrt waren. Er hoffte, ein automatisiertes Gerät könne den Piraten entgegentreten, ohne eine weitere lebende Seele in Gefahr zu bringen.",al={"warum eine maschine schicken","wrenix roboterplan","warum nutzte wrenix eine vorrichtung"}},{q="Wie haben die Piraten Wrenix' Maschine zerlegt?",a="Die Piraten benutzten ihre gebogenen Krummsäbel als behelfsmäßige Schraubenzieher, um Wrenix' Maschine auseinanderzuhebeln. Sie verstreuten ihre Bauteile in ihrem Lager und zerlegten das Gerät bis auf sein Gestell, bevor Wrenix ihr den Rückzugsbefehl in Richtung Ratschet schicken konnte.",al={"wie wurde die maschine zerstört","wie zerlegten piraten den roboter","piraten krummsäbel schraubenzieher"}},{q="Wo befinden sich die komplizierten Teile?",a="Die komplizierten Teile liegen auf dem Boden im oberen Lager der Piraten an der Küste südlich von Ratschet verstreut. Sie ließen die Stücke dort zurück, nachdem sie Wrenix' Maschine auseinandergenommen hatten. Fünf Handvoll müssen eingesammelt werden.",al={"wo sind die teile","oberes piratenlager ort","handvoll komplizierter teile fundort"}},{q="Warum hält Wrenix diesen Bergungsauftrag für sicherer?",a="Wrenix glaubt, dass das Einsammeln verstreuter Teile sicherer ist, als Mercenaries auszusenden, um die Piraten zu beseitigen. Die früheren Mercenaries kehrten nicht lebend zurück; für diese Arbeit muss jemand sich ins obere Lager schleichen und fünf Handvoll Bauteile aus dem Dreck sammeln.",al={"ist parts and pieces sicher","warum glaubt wrenix dass ihr überlebt","wrenix überlebenschancen"}},{q="Wofür werden die komplizierten Teile benötigt?",a="Die komplizierten Teile sind Stücke von Wrenix' automatisierter Maschine. Er braucht sie zurück, damit seine Ingenieursarbeit und die Materialien nicht völlig verschwendet sind.",al={"was sind komplizierte teile","warum braucht wrenix die teile","was macht wrenix mit den teilen"}}},fp="16,217,21.426.0,26.363.0,27.277.0,54.135.0,51.180.0,47.262.0,40.206.0,56.254.0,42.154.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="Im Himmelswall stellen sich Initianden der Prüfung der Windformer und streben nach einem Feuertotem. Sie beschwören Geister der Flamme, tragen die Eternal Flame nach Valanaar und entzünden dort die Feuerschale.",h="Im Himmelswall stellen sich Initianden der Prüfung der Windformer und streben nach einem Feuertotem.",kw={"call of fire","eternal flame","feuertotem","firelands","olariaan","der himmelswall","valanaar","windformer"},ang={["class:Shaman"]="Als Schamane durchlauft Ihr diesen Initiationsritus und erhaltet ein Feuertotem, wenn Ihr ihn abschließt. Das Totem verleiht Euch die Herrschaft über das Feuer.",["race:Skyborne"]="Als Skyborne folgt Ihr einer schamanischen Tradition, in der die Windformer des Himmelswalls Initianden dabei anleiten, die Elementarebenen zu ehren."},sec={{t="Das Ritual der Flamme",b="Olariaan von den Windformern führt Initianden durch eine heilige Prüfung im Himmelswall. Sie versammeln sich am Brazier of Offering und rufen Geister der Flamme aus den Firelands herbei. Sind ihre Opfergaben würdig, entzünden die Geister den Altar mit der Eternal Flame. Ein würdiger Initiand darf diese Flamme dann an sich nehmen."},{t="Die Reise nach Valanaar",b="Die Eternal Flame muss mit einer Fackel eingefangen und durch den Himmelswall nach Valanaar getragen werden. In diesem Elementarreich schwindet ihre Macht aus den Firelands in der wirbelnden Luft. Der Initiand muss den Brazier of Eternal Flames erreichen, bevor die Fackel erlischt."},{t="Das Feuertotem",b="Wenn ein Initiand die Feuerschale bei Valanaar neu entfacht, verleihen ihm die Windformer ein Feuertotem. Es würdigt seine Disziplin und seinen Respekt vor den Elementen. Die Ältesten lehren, dass elementare Macht jenen dient, die sie respektieren, aber jene verzehrt, die dies nicht tun."}},faq={{q="Was ist Call of Fire?",a="Call of Fire schickt einen angehenden Schamanen aus, um Geister der Flamme zu beschwören und die Eternal Flame einzufangen. Sie nach Valanaar zu tragen, beweist den Respekt des Initianden vor der Elementarebene und bringt ihm ein Feuertotem ein.",al={"was ist call of fire","call of fire quest","worum geht es in dieser quest"}},{q="Wer ist Olariaan?",a="Olariaan leitet die Zeremonie am Brazier of Offering. Er legt Materialien auf den Altar und ruft die Geister der Flamme herbei, um die Eternal Flame zu entzünden.",al={"wer ist olariaan","olariaans rolle","wer beginnt das ritual"}},{q="Was ist die Eternal Flame?",a="Die Eternal Flame stammt von Geistern der Flamme, die beim Ritual der Windformer aus den Firelands herbeigerufen werden. Initianden fangen sie mit einer Fackel ein und entzünden damit den Brazier of Eternal Flames in Valanaar.",al={"was ist die eternal flame","eternal flame himmelswall"}},{q="Warum muss die Flamme schnell nach Valanaar getragen werden?",a="Die Flamme stammt aus den Firelands, und ihre Hitze schwindet rasch in der Luft des Himmelswalls. Initianden eilen, damit die Fackel brennt, bis sie Valanaar erreichen.",al={"warum verflüchtigt sich die eternal flame","warum nach valanaar eilen","flammen der firelands himmelswall"}},{q="Wer sind die Windformer?",a="Die Windformer sind ein Orden im Himmelswall, der Initianden durch elementare Prüfungen führt. Sie ehren das Gleichgewicht und die Macht der Elementarebenen und wachen über die Vergabe von Totems.",al={"wer sind die windformer","windformer fraktion"}},{q="Was ist die Belohnung für das Bestehen der Prüfung?",a="Ein Initiand, der das Ritual vollendet und die Feuerschale in Valanaar neu entfacht, erhält ein Feuertotem, einen Fokus zum Kanalisieren feuriger Elementarmacht.",al={"call of fire belohnung","feuertotem belohnung","was erhält man durch call of fire"}}},fp="12,164,19.298.0,23.246.0,14.247.0,25.197.0,16.148.0,26.201.0,50.148.0,24.178.0,44.140.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="Ein Paket vom Nistgipfel liegt neben einem städtischen Briefkasten, bestimmt für Eisenschmiede. Als dringend für Eldrun Stormbreaker gekennzeichnet, wartet es noch immer auf seine Zustellung.",h="Ein Paket vom Nistgipfel liegt neben einem städtischen Briefkasten, bestimmt für Eisenschmiede.",kw={"nistgipfel","eldrun stormbreaker","eisenschmiede","briefkasten","verlegtes paket","dringende lieferung","wildhammer","your package has arrived"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass zuverlässige Nachrichtenverbindungen zwischen dem Hinterland und Eisenschmiede für die Interessen der Allianz in Khaz Modan und den nördlichen Gebieten wichtig sind.",["race:Dwarf"]="Als Zwerg kennt Ihr die Bande zwischen den Bronzebeards von Eisenschmiede und ihren Wildhammer-Vettern auf dem Nistgipfel. Dieses Paket sicher zu seinem Empfänger zu bringen, ehrt diese Bande."},sec={{t="Fehlgeleitete Fracht",b="Mehrere Pakete liegen verlassen neben einem städtischen Briefkasten. Sie wurden dort zurückgelassen, statt an ihre Bestimmungsorte gebracht zu werden. Ein dringendes Paket kam vom Nistgipfel, der Bergfestung der Wildhammer-Zwerge im Hinterland. Lieferungen zwischen weit entfernten Außenposten in Khaz Modan und Lordaeron können fehlgehen. Ein aufmerksamer Passant kann ein fehlgeleitetes Paket weitertragen."},{t="Ein Paket für Eldrun Stormbreaker",b="Das Paket ist an Eldrun Stormbreaker in Eisenschmiede adressiert. Sein Dringlichkeitsvermerk kennzeichnet die Sendung als wichtig genug, um ohne Verzögerung vom Hinterland in die Hauptstadt der Zwerge zu gelangen. Die Kiste muss Eldrun noch erreichen, bevor sie gestohlen oder vergessen wird."}},faq={{q="Was ist das Paket, das am Briefkasten gefunden wurde?",a="Es ist ein dringendes Paket vom Nistgipfel im Hinterland, adressiert an Eldrun Stormbreaker in Eisenschmiede. Es wurde mit mehreren anderen Paketen neben einem Briefkasten zurückgelassen, statt sein Ziel zu erreichen.",al={"was ist das paket","verlegtes paket","was lag am briefkasten","briefkastenpaket"}},{q="Wer ist Eldrun Stormbreaker?",a="Eldrun Stormbreaker ist der namentlich genannte Empfänger des fehlgeleiteten Pakets in Eisenschmiede. Das Etikett nennt Eldruns Namen und kennzeichnet das Paket als dringend, verrät aber kaum mehr, bis es seinen Empfänger erreicht.",al={"wer ist eldrun stormbreaker","eldrun stormbreaker","wer bekommt das paket","paketempfaenger"}},{q="Von wo wurde das Paket abgeschickt?",a="Das Paket kam vom Nistgipfel, der Siedlung und Festung des Wildhammer-Klans in den Bergen des Hinterlands. Es war für Eisenschmiede bestimmt, bevor es unterwegs bei einem Briefkasten abhandenkam.",al={"woher kam das paket","herkunft des pakets","von wo wurde es verschickt","nistgipfel lieferung"}},{q="Warum wurde das Paket als dringend gekennzeichnet?",a="Der Absender kennzeichnete die Kiste als dringend, weil ihr Inhalt oder ihre Ankunftszeit von Bedeutung war. Eine Verzögerung auf der langen Reise vom Nistgipfel nach Eisenschmiede könnte Eldrun Stormbreaker Schwierigkeiten bereiten.",al={"warum ist es dringend","dringende lieferung","was ist im paket","warum dringend"}},{q="Warum blieb das Paket an einem Briefkasten liegen?",a="Mehrere Pakete wurden neben einem Briefkasten zurückgelassen, statt sortiert und zugestellt zu werden. Der Grund ist unbekannt, und die Pakete sind weiterhin am falschen Ort.",al={"warum wurde es zurueckgelassen","warum wurde das paket abgelegt","verlorene post","verlegte pakete"}},{q="Wohin muss dieses Paket geliefert werden?",a="Das Paket ist für Eisenschmiede bestimmt und an Eldrun Stormbreaker adressiert. Es muss zu Eldrun in die Festungsstadt der Zwerge gebracht werden.",al={"wohin liefere ich es","paketziel","lieferort","zu wem bringe ich das paket"}},{q="Welche Verbindung besteht zwischen Nistgipfel und Eisenschmiede?",a="Der Nistgipfel ist die Heimat der Wildhammer-Zwerge, und Eisenschmiede ist der Sitz des Bronzebeard-Klans. Die Klans haben unterschiedliche Bräuche und Heimstätten, doch Briefverkehr, Handel und verwandtschaftliche Bande verbinden das Hinterland mit der Großen Schmiede unter dem Berg.",al={"nistgipfel und eisenschmiede","handel zwischen wildhammer und bronzebeart","verbindung eisenschmiede nistgipfel","warum post von nistgipfel schicken"}}},fp="24,144,17.359.0,32.258.0,41.199.0,27.195.0,31.198.0,33.183.0,46.149.0,45.138.0,56.245.0"}
P.entries["quest:97265"] = {n="Hate the Hatefury",s="Aka'rai in Schattenflucht bittet Euch, die Hatefury-Satyrn in Sargeron anzugreifen. Sein Groll rührt von einem Handel her, der ihn nach Rache dürsten lässt.",h="Aka'rai in Schattenflucht bittet Euch, die Hatefury-Satyrn in Sargeron anzugreifen.",kw={"aka'rai","desolace","hate the hatefury","hatefury","sargeron","satyr","schattenflucht","seelenstein"},sec={{t="Aka'rais Groll",b="Aka'rai spricht von einem Handel mit einem Satyr, der ihm Macht und Wissen versprach. Er sagt, die Hatefury hätten ihn verstoßen und ihm weniger gelassen, als er zuvor besaß. Nun bittet er Euch, ihr Lager nordöstlich von Schattenflucht in Sargeron anzugreifen. Ihr Blut ist der Preis, den er für seine Rache fordert."},{t="Der Bluthandel",b="Nach den Kämpfen sagt Aka'rai, einer der Hatefury sei Eurem Angriff entkommen. Er bezeichnet diesen Satyr als denjenigen, der mit ihm an einem Ritual teilnahm, bei dem Blut vergossen wurde. Der Satyr besitzt Aka'rais Seelenstein, weshalb Aka'rai fürchtet, Schattenflucht zu verlassen, solange dieser in seinen Händen bleibt. Fürs Erste, sagt er, ist Eure Arbeit getan."}},faq={{q="Wer bittet um Hilfe?",a="Aka'rai in Schattenflucht bittet Euch, die Hatefury-Satyrn in Sargeron anzugreifen.",al={"wer ist aka'rai","aka rai","hatefury auftraggeber"}},{q="Warum will Aka'rai die Hatefury angreifen lassen?",a="Aka'rai sagt, die Hatefury hätten ihn nach einem Handel verstoßen, der Macht und Wissen versprach.",al={"warum hatefury","aka'rais rache","satyr groll"}},{q="Wo sind die Hatefury?",a="Das Lager der Hatefury liegt in Sargeron in Desolace, nordöstlich von Schattenflucht.",al={"hatefury standort","sargeron satyrn","wo ist das lager"}},{q="Was wollte Aka'rai durch den Handel erhalten?",a="Aka'rai sagt, der Handel habe Macht, Wissen jenseits gewöhnlicher Folianten und einen eifrigen Diener versprochen.",al={"aka'rais handel","satyr handel","handel um macht"}}},fp="17,149,19.285.0,17.298.1,23.80.0,44.91.0,23.78.0,29.94.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="Yelmak schickt Euch mit einem Tonikum zu Whuut, dessen Eifer seine Sorgfalt überholt hat. Sein Lehrling greift nach seltenen Kräutern, bevor er lernt, was gewöhnliche Pflanzen bewirken können.",h="Yelmak schickt Euch mit einem Tonikum zu Whuut, dessen Eifer seine Sorgfalt überholt hat.",kw={"alchemie","schwarzer lotus","rohrkolben","kräuterkunde","bergsilberweisling","trank","speergras","whuut","yelmak"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr von Yelmaks Geduld und seinem Einfallsreichtum im Umgang mit einheimischen Zutaten aus Kalimdor lernen.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass es ebenso wichtig ist, die Eigenschaften alltäglicher Pflanzen wie Speergras und Rohrkolben kennenzulernen, wie nach seltenen Blüten zu suchen."},sec={{t="Das eifrige Wunderkind",b="Whuut hat ein Talent für Alchemie, und der Umgang mit dem Rührstab liegt ihm im Blut. Doch seine Ungeduld verleitet ihn dazu, die seltensten Reagenzien des Ladens aufzubrauchen, bevor er die Grundlagen beherrscht. Er greift nach legendären Pflanzen, bevor er lernt, wie gewöhnliche Kräuter aufeinander abgestimmt werden müssen, und behandelt die Alchemie wie ein Wettrennen."},{t="Eine Lektion in einer Phiole",b="Yelmak begegnet der Hast seines Lehrlings mit einer Lektion in einer Phiole. Mit einer schnellen Methode braut er ein verfeinertes Tonikum aus gewöhnlichem Speergras und Rohrkolben. Whuut träumt gerade von Schwarzem Lotus und Bergsilberweisling, als das Tonikum in seine Hände gelangt. Seine einfachen Zutaten zeigen, wie viel Können, Geduld und Respekt vor alltäglichen Pflanzen bewirken können."}},faq={{q="Wer ist Whuut?",a="Whuut ist Yelmaks junger Lehrling und ein begabter Alchemist. Voller Eifer, mit seltenen Kräutern zu experimentieren, überspringt er die Grundlagen des Handwerks.",al={"wer ist whuut","whuuts hintergrundgeschichte","über whuut"}},{q="Wer ist Yelmak?",a="Yelmak ist ein erfahrener Alchemist, der Whuut im Laden anleitet. Er sorgt sich, dass der junge Alchemist kostbare Vorräte verschwendet.",al={"wer vergibt diese quest","yelmaks rolle","wer ist yelmak"}},{q="Warum schickt Yelmak Euch mit einem Trank zu Whuut?",a="Yelmak schickt Euch mit einem Tonikum los, um Whuut Geduld und Respekt vor den Grundlagen zu lehren. Er hat es aus Speergras und Rohrkolben gebraut, gewöhnlichen Pflanzen, die Whuut bisher übersehen hat.",al={"was ist yelmaks lektion","warum schickt yelmak den trank","sinn der quest"}},{q="Welche Zutaten hat Yelmak für seinen Trank verwendet?",a="Yelmak hat Speergras und Rohrkolben verwendet, um das Tonikum zu brauen. Seine sorgfältige Methode macht diese gewöhnlichen Pflanzen nützlich.",al={"was ist im trank","reagenzien für yelmaks trank","zutaten für ein schnelles tonikum"}},{q="Mit welchen seltenen Reagenzien wollte Whuut arbeiten?",a="Whuut griff nach Schwarzem Lotus und Bergsilberweisling. Er hatte alltägliche Zutaten zugunsten dieser seltenen Pflanzen übergangen.",al={"was hat whuut gebraut","seltene kräuter die whuut will","welche reagenzien hat whuut verwendet"}},{q="Lernt Whuut seine Lektion?",a="Nachdem Whuut das Tonikum gekostet und das Rezept gehört hat, ist er überrascht, dass gewöhnliche Pflanzen solch einen Trank ergeben können. Er gibt zu, dass Yelmak recht hat, und nimmt sich vor, die alltäglichen Pflanzen genauer zu beachten, die er zuvor abgetan hat.",al={"ändert whuut seine meinung","whuuts reaktion auf den trank","ausgang von whuut's the rush"}}},fp="16,161,17.283.0,18.341.0,13.140.0,14.131.0,49.165.0,46.106.0,50.130.0,28.213.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="In ihrem Lager in den nordwestlichen Hügeln werden Grund and Gozwin von einem Schneeleoparden angegriffen. Grund vertreibt ihn mit seiner Schrotflinte, doch Gozwin verliert im Durcheinander sein Mechanikerlogbuch.",h="In ihrem Lager in den nordwestlichen Hügeln werden Grund and Gozwin von einem Schneeleoparden angegriffen.",kw={"zwerg","gnom ingenieur","gozwin","grund","mecha-walker","mechanikerlogbuch","schneeleopardenpirscher"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, warum Gozwin sich um die Baupläne und Notizen in seinem Mechanikerlogbuch sorgt.",["race:Dwarf"]="Als Zwerg erkennt Ihr vielleicht, wie schnell Grund seinen gnomischen Gefährten verteidigt.",["race:Gnome"]="Als Gnom versteht Ihr vielleicht Gozwins Sorge um die verlorenen Baupläne für seinen Mecha-Walker."},sec={{t="Ein Hinterhalt am Feuer",b="Ihr schlagt mit Grund and Gozwin für den Abend ein Lager in den verschneiten Hügeln auf. Als Grund sich umdreht, um ein Wildschwein über dem Feuer zuzubereiten, springt ein Schneeleopard aus dem Gebüsch und packt Gozwin mit seinen Kiefern. Grund greift nach seiner Schrotflinte und schießt über den Kopf der Bestie hinweg. Erschrocken lässt der Leopard Gozwin los und flieht in die kalten Felsen."},{t="Die verlorene Arbeit eines Tüftlers",b="Gozwin entkommt mit tiefen Kratzern, doch bei dem Angriff werden die Habseligkeiten im Lager verstreut. Im Durcheinander verliert er sein geschätztes Mechanikerlogbuch, das Baupläne für seinen Mecha-Walker enthält. Der mitgenommene Gnom fürchtet, jemand könnte seine Ingenieursgeheimnisse entdecken. Er findet keine Ruhe, bis Ihr die Hügel nordwestlich des Lagers nach dem Logbuch und dem umherstreifenden Leoparden durchsucht."}},faq={{q="Wer sind Grund and Gozwin?",a="Grund ist ein Zwerg, und Gozwin ist sein gnomischer Gefährte und ein Ingenieur. Ein Schneeleopard greift an, als sie in den verschneiten Hügeln lagern, verwundet Gozwin und verstreut ihre Habseligkeiten.",al={"wer sind grund and gozwin","grund gozwin"}},{q="Was hat Gozwin im Lager angegriffen?",a="Ein Schneeleopard springt aus dem Gebüsch und packt Gozwin mit seinen Kiefern, während Grund ein Wildschwein über dem Feuer zubereitet. Grund schießt mit seiner Schrotflinte über den Kopf der Bestie hinweg und vertreibt sie damit.",al={"was hat gozwin angegriffen","wer hat gozwin angegriffen"}},{q="Warum ist Gozwins Mechanikerlogbuch so wichtig für ihn?",a="Gozwins Mechanikerlogbuch enthält technische Baupläne für seinen Mecha-Walker. Er fürchtet, jemand könnte seine Ingenieursgeheimnisse entdecken, wenn das Logbuch gefunden wird.",al={"warum ist das logbuch wichtig","mechanikerlogbuch gozwin"}},{q="Wie schwer wurde Gozwin bei dem Angriff verletzt?",a="Gozwin entkommt mit tiefen Kratzern, nachdem Grund mit seiner Schrotflinte schießt und den Leoparden verscheucht. Der mitgenommene Gnom sorgt sich um sein verlorenes Logbuch.",al={"geht es gozwin gut","hat gozwin überlebt"}},{q="Wo befindet sich das Lager von Grund and Gozwin?",a="Ihr Lager liegt in den verschneiten Hügeln im Nordwesten. Ihr werdet gebeten, dort nach dem verlorenen Logbuch und dem umherstreifenden Leoparden zu suchen.",al={"wo ist das lager","grund lager standort"}},{q="Was geschah mit der Mahlzeit, die Grund zubereitete?",a="Der Leopard flieht, nachdem Grund mit seiner Schrotflinte schießt. Der Schneeleopard hat das Wildschwein gefressen, das Grund zubereitete.",al={"was geschah mit dem wildschweinbraten","leopard frisst wildschwein"}}},fp="16,180,21.316.0,22.332.0,25.181.0,29.176.0,51.147.0,40.146.0,41.123.0,46.110.0"}
P.entries["quest:97279"] = {n="Wayward Weapons",s="Im Tal der Prüfungen schickt Gornek Neuankömmlinge los, um Waffen für das Lager zu bergen. Junge Krieger treffen weiter ein, um der Horde zu dienen, und Kzan Dornenhieb muss alte Waffen wieder einsatzbereit machen.",h="Im Tal der Prüfungen schickt Gornek Neuankömmlinge los, um Waffen für das Lager zu bergen.",kw={"durotar","gornek","kzan dornenhieb","rekruten","bergen","the den","übungswaffen","das tal der prüfungen"},ang={["class:Warrior"]="Als Krieger lernt Ihr, Eure Waffen zu achten. Waffen zu bergen, die gescheiterte Rekruten zurückgelassen haben, verlangt Disziplin und Eigenständigkeit, noch bevor der Kampf beginnt.",["faction:Horde"]="Als Mitglied der Horde behauptet Ihr Euch in Durotar durch Zähigkeit und Einfallsreichtum und rettet selbst Waffen, die Unwürdige wegwerfen.",["profession:Blacksmithing"]="In Durotar zählt jedes Stück Metall. Als Schmied bergt Ihr zerstörte Ausrüstung und arbeitet ramponierte Klingen zu Kriegswerkzeug um."},sec={{t="Waffen für den Nachwuchs",b="Junge Rekruten stehen in Durotars roten Ödlanden vor harten Prüfungen. Viele kommen, um ihre Klingen dem Kriegshäuptling zu weihen, sodass dem Lager die Waffen ausgehen. Waffenschmied Kzan Dornenhieb hat Mühe, die Nachfrage zu decken. Für Unvorbereitete können schon die ersten Lektionen mit Tod oder Demütigung enden."},{t="Eine Prüfung des Einfallsreichtums",b="Vorarbeiter Gornek macht aus dem Mangel eine praktische Prüfung. Er schickt Neuankömmlinge los, um verlassene Klingen und stumpfe Übungswaffen zu bergen, die gefallene oder geflohene Rekruten zurückgelassen haben. Kzan kann die geborgenen Waffen für die nächste Welle reparieren und härten. Die Rekruten lernen, dass das Überleben in der Horde neben dem Schwingen von Stahl auch das Sammeln zurückgelassener Ausrüstung verlangt."}},faq={{q="Warum liegen hier so viele verlassene Übungswaffen herum?",a="Manchen Rekruten fehlt die Stärke oder Entschlossenheit, die die Horde verlangt. Unachtsame oder verängstigte Neuankömmlinge lassen ihre Ausrüstung zurück, während andere den örtlichen Ebern und Skorpiden erliegen, sodass ihre ausgegebenen Waffen im Staub verstreut liegen.",al={"warum liegen waffen auf dem boden","verlassene waffen durotar","waffen gescheiterter rekruten"}},{q="Wer ist Kzan Dornenhieb?",a="Kzan Dornenhieb ist der Waffenschmied im Den im Tal der Prüfungen. Er stattet neue Rekruten aus, repariert ramponierte Übungsausrüstung und hält die Waffenvorräte der Horde in diesem Tal für die ersten Prüfungen instand.",al={"kzan dornenhieb hintergrund","wer ist kzan","waffenschmied kzan"}},{q="Wer vergibt diese Aufgabe?",a="Gornek, der Vorarbeiter vor dem Den, schickt neue Rekruten zur Unterstützung los. Er beobachtet eintreffende Anwärter, beurteilt ihre grundlegende Eignung und teilt ihnen dringend anstehende Aufgaben auf dem Prüfungsgelände zu.",al={"wer vergibt wayward weapons","gornek quest"}},{q="Was wird Kzan mit diesen geborgenen Waffen tun?",a="Kzan repariert und schärft die ramponierten Übungswaffen und setzt sie wieder instand. Da Rohstoffe in Durotar knapp sind und ständig Rekruten eintreffen, verwendet er geborgenes Eisen und Holz erneut, um die nächste Welle auszubilden.",al={"was geschieht mit den übungswaffen","waffen reparieren kzan"}},{q="Wo findet diese Quest statt?",a="Ihr befindet Euch im Tal der Prüfungen, einer abgelegenen Schlucht im Süden Durotars, wo junge Orcs und Dunkelspeertrolle ihren Weg als Krieger der Horde beginnen.",al={"tal der prüfungen lage","wo ist wayward weapons"}},{q="Warum schmiedet die Horde nicht einfach ganz neue Waffen?",a="Durotar ist rau und trocken, mit wenigen leicht zugänglichen Eisenvorkommen, und die junge Horde kann sich keine Verschwendung leisten. Übungsklingen gescheiterter Rekruten erneut zu verwenden, spart Rohmetall für die Fronttruppen.",al={"warum waffen bergen","durotar metallmangel"}}},fx={c966be67={q="Warum will Gornek, dass die verlassenen Waffen gesammelt werden?",a="Ein frischer Zustrom von Rekruten in Das Tal der Prüfungen hat die Waffenkammer des Lagers belastet. Der Waffenschmied Kzan geht die Übungsausrüstung aus, und Gornek muss die Vorräte am Laufen halten, um die nächste Welle auszubilden. Euch zu bitten, das Gelände abzusuchen, löst den Mangel und lässt Gornek gleichzeitig Eure Sorgfalt und Eure Überlebensfähigkeiten im Tal testen.",al={"gorneks beweggrund","warum will gornek waffen","warum verlassene übungswaffen sammeln"}},["42aac14b"]={q="Wozu dient die Abandoned Training Weapon?",a="Diese groben Klingen und Knüppel wurden von früheren Rekruten getragen, die sich als unwürdig erwiesen oder starben, bevor sie ihre Prüfungen beendeten. Im Schmutz verstreut, sind sie immer noch robust genug, um restauriert zu werden. Sobald Ihr sie zu Kzan Dornenhieb bringt, repariert und schärft er sie, damit zukünftige Rekruten Ausrüstung haben, mit der sie kämpfen können.",al={"nutzen der verlassenen übungswaffen","wofür sind die verlassenen waffen gut","zweck der verlassenen übungswaffen"}},["056af0db"]={q="Warum schickt Gornek einen Rekruten anstatt Wachen?",a="Die Prüfungsgründe existieren, um fähige Krieger von den Schwachen zu trennen. Erfahrene Wachen loszuschicken, um hinter gescheiterten Rekruten aufzuräumen, verschwendet Veteranen-Arbeitskraft, während Euch zu schicken einen doppelten Zweck erfüllt: Ihr stählt Euch bei der Jagd auf Eber in der Wildnis, während Ihr beweist, dass Ihr Befehle befolgen und die Notwendigkeiten des Lagers aufrechterhalten könnt.",al={"warum keine wachen schicken","warum ich gornek","warum rekruten für waffen schicken"}}},fp="15,190,20.275.0,25.331.0,62.212.0,23.198.0,21.185.0,46.191.0,33.153.0,54.192.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="In Durotar hat die Dull Stormy Orb Rezlaks Aufmerksamkeit erregt. Der Goblintüftler sieht Grund, das Relikt zu untersuchen, das den Harpyien der Dustwind aus der Staubwindklamm abgenommen wurde.",h="In Durotar hat die Dull Stormy Orb Rezlaks Aufmerksamkeit erregt.",kw={"a simmering storm","staubwindklamm","dull stormy orb","durotar","dustwind","gazlowe","harpyie","rezlak"},ang={["class:Shaman"]="Als Schamane erkennt Ihr in dem elektrischen Miniatursturm ein Abbild ursprünglicher Elementarkräfte. Sein grobes Gefäß wirft Fragen über die Methoden der Harpyien auf.",["faction:Horde"]="Als Abenteurer der Horde helft Ihr Rezlak, geheimnisvolle magische Artefakte sicherzustellen, die feindseligen Harpyien abgenommen wurden, welche Durotars Schluchten bedrohen.",["profession:Engineering"]="Als Ingenieur teilt Ihr Rezlaks Interesse an seltsamen Kuriositäten, die unregelmäßige elektrische Funken versprühen und in deren Innerem Nebel wirbelt."},sec={{t="Ein Funke im Staub",b="Reisende, die sich mit den Harpyien der Dustwind in der Staubwindklamm anlegen, finden womöglich die Dull Stormy Orb unter ihren seltsamen Schmuckstücken. Ihre abgenutzte Oberfläche gibt ein stetiges elektrisches Vibrieren ab. Dunkler Nebel wirbelt im Inneren, hin und wieder von grellen Funken durchzuckt. Das Relikt zeigt, dass die Harpyien mit Sturmmagie umgegangen sind."},{t="Goblinische Neugier",b="Rezlak wartet am Eingang der Staubwindklamm, wo die Kugel sein Interesse geweckt hat. Ihre Entdeckung erinnert ihn an einen Rat seines Arbeitgebers, Chefingenieur Gazlowe aus Ratschet. Was die Harpyien mit dem Miniatursturm vorhatten, bleibt unbekannt. Nun ist die Kugel in Goblinhänden."}},faq={{q="Was ist die Dull Stormy Orb?",a="Die Dull Stormy Orb ist eine magische Kuriosität, die einer Harpyie in Durotar abgenommen wurde. Ihre matte Oberfläche verbirgt ein leises elektrisches Summen, wirbelnden dunklen Nebel und gelegentliche Funken.",al={"was ist dull stormy orb","stormy orb","kugel von harpyien"}},{q="Wer will die Dull Stormy Orb?",a="Rezlak will die Dull Stormy Orb. Er ist ein Goblinspäher, der unmittelbar vor der Staubwindklamm in Durotar stationiert ist und ein Auge für seltsame Kuriositäten und Bergungsgut hat.",al={"wer nimmt dull stormy orb","stormy orb abgeben","wohin mit der kugel"}},{q="Warum hatten die Harpyien diese Kugel?",a="Welchen Zweck die Kugel für die Harpyien erfüllte, ist unbekannt. Die Harpyien der Dustwind aus der Staubwindklamm nutzten sie, um elektrische und stürmische Elementarkräfte zu kanalisieren oder einzuschließen.",al={"was machten harpyien mit der kugel","warum haben harpyien eine sturmkugel","zweck der harpyienkugel"}},{q="Wer ist Rezlak?",a="Rezlak ist ein Goblinagent nahe der Staubwindklamm im nördlichen Durotar. Er steht mit dem Steamwheedle Cartel und Chefingenieur Gazlowe aus Ratschet in Verbindung.",al={"wer ist rezlak","rezlak durotar","goblin nahe der staubwindklamm"}},{q="Wo liegt die Staubwindklamm?",a="Die Staubwindklamm ist ein zerklüftetes Schluchtensystem im nördlichen Durotar. Feindselige Harpyien der Dustwind treiben dort ihr Unwesen, belästigen Reisende und stören den örtlichen Handel sowie die Siedlungen.",al={"wo liegt die staubwindklamm","lage der staubwindklamm","harpyienschlucht durotar"}},{q="Was hält Rezlak von der Kugel?",a="Die Kugel erinnert Rezlak an Lehren und Bemerkungen seines Chefs, Chefingenieur Gazlowe, über seltsame Kuriositäten, die sich als gewinnbringend erweisen könnten.",al={"was sagt rezlak über gazlowe","verbindung zwischen rezlak und gazlowe"}}},fp="17,168,19.298.0,16.275.0,28.168.0,30.155.0,34.160.0,14.155.0,25.162.0,34.143.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Nahe der Staubwindklamm sucht Rezlak nach einem Weg, seine Karawane vor Harpyien zu schützen. Er hofft, eine entladene Kugel mit den elektrischen Organen von Durotars Donnerechsen aufzuladen.",h="Nahe der Staubwindklamm sucht Rezlak nach einem Weg, seine Karawane vor Harpyien zu schützen.",kw={"geladene organe","staubwindklamm","durotar","gazlowe","harpyien","kugel","rezlak","stormy potential","donnerechse"},ang={["faction:Horde"]="Rezlaks Arbeit stärkt den Stützpunkt der Horde und erleichtert Reisen durch Durotar, wo marodierende Harpyien aus der Staubwindklamm Reisende und Nachschubkarawanen bedrohen.",["profession:Engineering"]="Inaktive Geräte mit Organen von Donnerechsen zu betreiben, zeugt vom Einfallsreichtum der Goblins, auch wenn es dabei kaum Sicherheitsspielraum gibt."},sec={{t="Die Gelegenheit ergreifen",b="Nahe der Staubwindklamm in Durotar bedrohen Harpyien Rezlaks Karawane, und eine intakte magische Kugel hat ihre Kraft verloren. Gazlowe, Ratschets Chefingenieur, riet Rezlak einst, Gelegenheiten zu ergreifen, wenn sie sich bieten. Nun plant der Goblin, die inaktive Kugel aufzuladen und beide Probleme auf einmal zu lösen."},{t="Die Kraft des Sturms",b="Rezlak braucht starke Elektrizität, um seine entladene Kugel wieder aufzuladen. Donnerechsen leben in der Schlucht westlich der Staubwindklamm, und ihre Organe erzeugen und leiten tödliche Blitze. Er bittet Euch, ihm diese geladenen Organe zu bringen. Rezlak hofft, ihren unberechenbaren Strom in die Kugel zu leiten und seine Nachschubwagen vor Überfällen der Harpyien zu schützen."}},faq={{q="Wer vergibt die Quest Stormy Potential?",a="Rezlak, ein Goblinhändler und Tüftler nahe der Staubwindklamm in Durotar, bittet Euch um Hilfe. Gazlowe, Ratschets Chefingenieur, lehrte ihn, Gelegenheiten zu ergreifen, und Rezlak hofft, eine entladene Kugel mit der Ladung in den elektrischen Organen einheimischer Tiere wieder aufzuladen.",al={"wer vergibt stormy potential","wo ist rezlak","rezlak questgeber"}},{q="Was versucht Rezlak mit den Organen aufzuladen?",a="Rezlak hofft, eine intakte Kugel aufzuladen, die all ihre Kraft verloren hat. Er plant, die Organe von Donnerechsen zu nutzen, um seine Karawane vor den Harpyien zu schützen, die die Gegend heimsuchen.",al={"was lädt rezlak auf","warum organe von donnerechsen benötigt","rezlak kugel zweck"}},{q="Wo sind die Donnerechsen zu finden?",a="Donnerechsen leben in einer Schlucht westlich von Rezlaks Standort nahe der Staubwindklamm in Durotar. Ihr könnt ihm ihre elektrischen Organe bringen.",al={"wo donnerechsen finden","donnerechsen fundort durotar","wo sind die organe"}},{q="Warum ist es gefährlich, Donnerechsen ihre Organe zu entnehmen?",a="Donnerechsen sind gefährlich, weil sie Blitze entfesseln. Ihre elektrischen Entladungen können Reisenden eine schmerzhafte Lektion erteilen, die sie womöglich nur einmal erleben.",al={"warum erzeugen donnerechsen blitze","nutzen donnerechsen blitze"}},{q="Warum fürchtet Rezlak die Harpyien?",a="Harpyien aus der Staubwindklamm haben Rezlaks Karawane überfallen. Er hofft, dass die aufgeladene Kugel sie abschreckt oder als Waffe gegen weitere Angriffe auf seine Warenlieferungen dient.",al={"warum braucht rezlak schutz","wer hat rezlak angegriffen","harpyien überfall auf karawane"}},{q="Welche Verbindung hat Rezlak zu Gazlowe?",a="Rezlak sieht in Gazlowe, Ratschets Chefingenieur, einen Mentor und ein geschäftliches Vorbild. Gazlowes Rat, Gelegenheiten zu ergreifen, leitet Rezlaks Plan für die Kugel.",al={"wer ist gazlowe für rezlak","rezlak gazlowe rat"}}},fp="16,171,19.284.0,20.331.0,37.253.0,48.158.0,36.141.0,45.155.0,33.159.0,39.160.0"}
P.entries["quest:97286"] = {n="Research Access",s="Euer Handeln hat Euch einen Platz in der Library eingebracht. Ihre Türen stehen Euch für Euer Studium offen.",h="Euer Handeln hat Euch einen Platz in der Library eingebracht.",kw={"zugang","wissen","library","research access","achtung","studium"},sec={{t="Zugang zur Library",b="Ihr habt Euch Zugang zur Library für Euer Studium verdient. Ihre Türen stehen Euch offen."}},faq={{q="Warum darf ich die Library betreten?",a="Euer Handeln hat Achtung vor Wissen gezeigt, daher steht Euch die Library für Euer Studium offen.",al={"zugang zur library","warum library offen","studium in der library"}},{q="Was bietet mir die Library?",a="Die Library steht Euch für Euer Studium offen.",al={"library wofür","zugang zum studium","was kann ich tun"}},{q="Was hat mein Handeln gezeigt?",a="Euer Handeln hat Achtung vor Wissen gezeigt.",al={"wissen achten","warum aufgenommen","was habe ich bewiesen"}}},fp="15,87,14.82.0,28.83.0,31.35.0,25.42.0"}
P.entries["quest:97287"] = {n="Shrewd Negotiations",s="Nach Eurer Infiltration der Magierstadt schickt Euch Magus Wordeen Voidglare nach Dalaran. Bringt den Arkanpartikel zu Archmage Celindra; Wordeen glaubt, dass die Kirin Tor alles geben werden, um ihn zurückzubekommen.",h="Nach Eurer Infiltration der Magierstadt schickt Euch Magus Wordeen Voidglare nach Dalaran.",kw={"alteracgebirge","arkanpartikel","archmage celindra","dalaran","kirin tor","shrewd negotiations","wordeen voidglare"},sec={{t="Zeit zu verhandeln",b="Magus Wordeen Voidglare sagt, dass kein Orden auf Azeroth den Kirin Tor im arkanen Wissen gleichkommt. Selbst sein brillantes Werk verblasst neben ihrer uralten Weisheit. Er glaubt, dass die Horde Zugang zu ihrem exklusiven Orden erhalten sollte. Deshalb schickt er Euch mit dem Arkanpartikel, den Ihr erbeutet habt, zu Archmage Celindra in Dalaran. Wordeen glaubt, dass die Kirin Tor alles geben werden, um ihn zurückzubekommen."}},faq={{q="Wer schickt Euch zu Verhandlungen mit Dalaran?",a="Magus Wordeen Voidglare schickt Euch nach Eurer Infiltration der Stadt nach Dalaran.",al={"wer vergibt shrewd negotiations","wordeen voidglare","questgeber shrewd negotiations"}},{q="Mit wem sollt Ihr sprechen?",a="Ihr werdet zu Archmage Celindra in Dalaran geschickt, um mit ihr zu sprechen.",al={"mit wem sprechen","celindra standort","wo ist celindra"}},{q="Welches Druckmittel führt Ihr mit Euch?",a="Ihr tragt den Arkanpartikel bei Euch, den Ihr erbeutet habt. Wordeen glaubt, dass die Kirin Tor alles geben werden, um ihn zurückzubekommen.",al={"was ist der arkanpartikel","verhandlungspfand","arkanpartikel"}},{q="Warum will Wordeen Voidglare mit Dalaran verhandeln?",a="Wordeen sagt, dass kein Ort auf Azeroth den Kirin Tor im arkanen Wissen gleichkommt. Er glaubt, dass die Horde Zugang zu ihrem exklusiven Orden erhalten sollte.",al={"warum mit den kirin tor verhandeln","wordeens beweggrund","warum dalaran"}}},fp="19,198,17.359.0,40.81.0,31.56.0,27.104.0,53.141.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="Der Kopf einer gefallenen Monstrosität setzt Unending Torment in Gang. Seine wiederholten Nähte deuten auf gezielte finstere Experimente in der Hauptstadt der Verlassenen hin, und Ihr bringt ihn zu Apothekermeister Faranell in Unterstadt.",h="Der Kopf einer gefallenen Monstrosität setzt Unending Torment in Gang.",kw={"monströser kopf","monstrosität","das apothekarium","dunkle fürstin","apothekermeister faranell","königliche apothekervereinigung","sylvanas windläufer","unterstadt","unending torment"},ang={["faction:Horde"]="Abenteurer der Horde, die den Kopf sehen, erhalten einen Einblick in die wiederholte Wiederbelebung und Fleischformung der Verlassenen. Diese Methoden funktionieren, können aber Gefährten verstören, die sich stärker der Ehre verpflichtet fühlen.",["race:Undead"]="Für die Verlassenen zeigt der Kopf, wie wiederholte Reparaturen ein untotes Konstrukt schwächen. Er ist eine düstere Erinnerung an die uneingeschränkte Macht ihrer Königin und den makabren Einfallsreichtum der Königlichen Apothekervereinigung."},sec={{t="Eine lose Naht",b="Als die hoch aufragende Monstrosität im Kampf fällt, stürzt ihr Kopf von ihren Schultern. Der Hals wurde viele Male abgetrennt, genäht, abgerissen und wieder befestigt. Jede Reparatur machte die Naht brüchiger, bis der Kopf kaum noch an den Schultern hing.\n\nEin derart hartnäckiges Flickwerk ist selbst für untote Konstrukte ungewöhnlich. Die wiederholte Zerstörung und das erneute Zusammensetzen lassen vermuten, dass diese Monstrosität immer wieder neu aufgebaut wurde. Gewöhnliche Aasfresser konnten ihre Machart nicht erklären. Nur die geschickten Fleischformer von Unterstadt konnten die Herkunft der Kreatur bestimmen."},{t="Der Scherz der Dunklen Fürstin",b="Im Apothekarium erkennt Apothekermeister Faranell, Anführer der Königlichen Apothekervereinigung, den abgetrennten Kopf sofort. Er sieht dessen wiederholtes Zusammensetzen als absichtlichen, grausamen Scherz von Fürstin Sylvanas Windläufer, nicht als ein Versehen der Nekromantie.\n\nNur die Dunkle Fürstin und ihr innerer Zirkel wissen, welches Vergehen der Kreatur diese entwürdigende Strafe eingebracht hat. Faranell nimmt den zerschundenen Kopf voller Freude an, überzeugt, dass die Königliche Apothekervereinigung ihn für ihre laufenden alchemistischen und nekromantischen Vorhaben nutzen kann."}},faq={{q="Was ist der Monströse Kopf?",a="Der Monströse Kopf ist der abgetrennte Kopf eines einzigartigen Konstrukts, der sich löst, wenn die Kreatur besiegt wird. Sein Hals trägt die Narben wiederholter Befestigungen, und jede Reparatur schwächte das Fleisch und die Nähte. Ihr bringt ihn zur Untersuchung zu Apothekermeister Faranell in Unterstadt.",al={"monströser kopf hintergrund","was ist der monströse kopf","monstrositätenkopf questgegenstand"}},{q="Warum wurde der Kopf so oft wieder befestigt?",a="Der Kopf wurde nach jedem Sturz oder Verlust wieder angenäht, damit das Konstrukt zusammengesetzt werden konnte, um weiter zu dienen oder zu leiden. Sein zunehmend brüchiger Hals gab schließlich erneut nach.",al={"warum kopf wieder befestigt","warum wurde der kopf wieder angenäht","unending torment kopf nähte"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Königliche Apothekervereinigung im Apothekarium von Unterstadt. Unter der Herrschaft von Königin Sylvanas Windläufer beaufsichtigt er die Apotheker der Verlassenen, die Gifte, Seuchen und anatomische Veränderungen erforschen. Seine Vertrautheit mit den Projekten der Dunklen Fürstin lässt ihn die Herkunft des genähten Kopfes sofort erkennen.",al={"wer ist faranell","apothekermeister faranell hintergrund","faranell unterstadt"}},{q="Warum betrachtet Sylvanas dies als grausamen Scherz?",a="Die Grausamkeit liegt im endlosen Kreislauf selbst. Jedes Mal, wenn die Kreatur fällt, wird sie schlampig zusammengenäht, um erneut zu dienen oder zu leiden, und jede Reparatur schwächt sie weiter. So bestraft die Dunkle Fürstin ihre Feinde. Faranell verrät nicht, wer die Kreatur einst war oder was sie getan hat, um dies zu verdienen.",al={"sylvanas scherz","warum scherz der dunklen fürstin","grausamer scherz der dunklen fürstin"}},{q="Was wird Faranell mit dem Kopf tun?",a="Faranell verwertet regelmäßig nekromantische Überreste, Fleisch und biologische Kuriositäten, um Mixturen, Seuchen und Verstärkungen für Konstrukte für die anhaltenden Konflikte der Verlassenen zu entwickeln. Er nimmt den Kopf für die alchemistische und nekromantische Arbeit der Vereinigung an.",al={"was geschieht mit dem kopf","faranells verwendung für den kopf","was werden die apotheker damit tun"}},{q="Wo gebt Ihr die Quest Unending Torment ab?",a="Bringt den Monströsen Kopf zu Apothekermeister Faranell im Apothekarium, im südlichen Viertel von Unterstadt. Er ist von brodelnden Bottichen, Gehilfen und Versuchspersonen umgeben, während er die Forschung der Vereinigung beaufsichtigt.",al={"wo unending torment abgeben","unending torment abgabe","wer nimmt den monströsen kopf"}},{q="Können Spieler der Allianz diese Quest abgeben?",a="Die Lieferung führt Euch zu Apothekermeister Faranell im Apothekarium von Unterstadt, weshalb sie für Abenteurer der Horde gedacht ist. Abenteurer der Allianz, die sich ihm nähern, müssten beim Betreten der Festung der Verlassenen mit feindseligen Wachen von Unterstadt und dem Tod durch die Verlassenen rechnen.",al={"ist unending torment nur für die horde","allianz unending torment","kann die allianz unending torment machen"}}},fp="16,224,14.544.0,20.519.1,28.279.0,47.183.0,34.337.0,45.303.0,36.253.0,48.218.0,40.281.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="In Unterstadt bereiten sich die Verlassenen darauf vor, einen gefallenen Kommandanten der Allianz zu verhören. Sie wollen Grand Marshal Othmar Garithos einen neuen Körper geben und erfahren, was er mit ins Grab nahm.",h="In Unterstadt bereiten sich die Verlassenen darauf vor, einen gefallenen Kommandanten der Allianz zu verhören.",kw={"monstrosität","verlassene","garithos","grand marshal","kopf des barons","othmar","sylvanas","unterstadt","unending torment"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr das grausame Schicksal von Grand Marshal Garithos, einem Anführer der Allianz, der sich in Lordaeron der Banshee Queen widersetzte.",["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Royal Apothecary Society in Unterstadt Experimente zur Wiederbelebung durchführt. Die Arbeit zeigt die dunkle Kunst der Verlassenen und ihre Rache an ehemaligen Unterdrückern.",["race:Undead"]="Als Verlassene seht Ihr, wie die Überreste von Grand Marshal Garithos in Experimenten verwendet werden, die an Fürstin Sylvanas' Eroberung Lordaerons erinnern."},sec={{t="Eine Trophäe der Eroberung",b="Tief in Unterstadt nähen Praktiker der Verlassenen Monstrositäten aus weggeworfenen Teilen der Toten zusammen. Unter den konservierten Schädeln liegt einer mit einer bitteren Geschichte: der abgetrennte Kopf von Grand Marshal Othmar Garithos. Er führte die überlebenden Streitkräfte der Allianz durch Lordaeron, bis die Dunkle Fürstin ihn tötete."},{t="Geheimnisse des Grabes",b="Die Verlassenen wollen Garithos verhören, seinen Kopf nicht als Trophäe behalten. Ihre Nekromanten bereiten einen zusammengeflickten Monstrositätenkörper als seinen neuen Wirt vor, um Geheimnisse der Allianz zu enthüllen, die in seinem Schädel eingeschlossen sind. Als sie den Kopf zu dem leblosen Konstrukt bringen, erwacht die Monstrosität unter Qualen und durchlebt ihre grausamen letzten Augenblicke erneut."}},faq={{q="Wer war Othmar?",a="Othmar war Grand Marshal Othmar Garithos, ein berüchtigter Kommandant, der nach dem Dritten Krieg die verbliebenen Truppen der Allianz in Lordaeron anführte. Nichtmenschen verachteten ihn. Apothekermeister Faranell sagt, die Dunkle Fürstin habe das Vergnügen gehabt, ihn eigenhändig zu erledigen.",al={"wer ist othmar","othmars identität","wer war othmar"}},{q="Warum beleben die Verlassenen Othmars Überreste wieder?",a="Die Verlassenen hoffen, Garithos Geheimnisse zu entreißen, die er mit ins Grab genommen hat. Sie legen seinen konservierten Kopf neben einen vorbereiteten Monstrositätenwirt, um seinen wiederbelebten Überresten Informationen zu entlocken.",al={"warum othmar wiederbeleben","zweck der wiederbelebung des kopfes","welche geheimnisse hat othmar"}},{q="Wie starb Othmar?",a="Apothekermeister Faranell sagt, Fürstin Sylvanas Windläufer, die Dunkle Fürstin, habe das Vergnügen gehabt, Grand Marshal Garithos eigenhändig zu töten.",al={"wer tötete othmar","wie starb othmar","othmars tod"}},{q="Warum heißt der Questgegenstand Kopf des Barons?",a="The Baron ist der Name der hoch aufragenden Monstrosität in den Ruinen von Lordaeron. Ihr Kopf gehörte einst Grand Marshal Garithos, wie Faranell enthüllt.",al={"kopf des barons othmar","warum heißt er kopf des barons"}},{q="Wo befindet sich Othmars neuer Körper?",a="Die kopflose Monstrosität, die Othmars Kopf erhalten soll, wird in einer angrenzenden Kammer in Unterstadt aufbewahrt. Praktiker der Verlassenen warten auf ihre Wiederbelebung.",al={"wo ist othmars körper","monstrosität standort unterstadt"}},{q="Was geschieht, wenn das Konstrukt erwacht?",a="Als der Kopf neben das zusammengesetzte Konstrukt gelegt wird, erwacht sein zusammengenähtes Fleisch mit heftigen Zuckungen zum Leben. Die Überreste geraten in Panik, als sie den Schrecken von Garithos' letzten Augenblicken am Leben erneut durchleben.",al={"was geschieht wenn der körper erwacht","reaktion bei abschluss othmar"}}},fp="16,179,20.297.0,20.320.1,15.239.0,50.182.0,19.132.0,51.144.0,35.155.0,40.179.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="In Unterstadt widersetzt sich ein trotziges Subjekt den Forderungen der Königlichen Apothekervereinigung. Apothekermeister Faranell begrüßt die Nachricht, begierig darauf, einen schwierigen Gefangenen zu brechen.",h="In Unterstadt widersetzt sich ein trotziges Subjekt den Forderungen der Königlichen Apothekervereinigung.",kw={"abscheulichkeit","das apothekarium","faranell","verlassene","apothekermeister faranell","königliche apothekervereinigung","unterstadt","unending torment"},ang={["faction:Horde"]="Als Champion der Horde in Lordaeron erlebt Ihr die Rücksichtslosigkeit Eurer verbündeten Verlassenen. Faranells Freude daran, störrische Gefangene zu brechen, offenbart den düsteren Pragmatismus Unterstadts.",["race:Undead"]="Als Verlassener wisst Ihr, dass die Lebenden Euch womöglich eine Abscheulichkeit nennen. Indem Ihr Apothekermeister Faranell helft, unterstützt Ihr die finstere Arbeit der Königlichen Apothekervereinigung."},sec={{t="Trotz in den Schatten",b="Ein Subjekt unter der Beobachtung der Königlichen Apothekervereinigung verachtet Euch. Der Gefangene nennt Euch eine Abscheulichkeit und weigert sich zu helfen. Solcher Hass ist den Verlassenen vertraut, denn viele Lebende und Gefangene schrecken vor Lordaerons Untoten zurück."},{t="Faranells Ehrgeiz",b="Ihr meldet die Weigerung des Subjekts Apothekermeister Faranell in Unterstadt. Das Oberhaupt der Königlichen Apothekervereinigung begrüßt die Nachricht mit boshafter Freude. Für ihn macht der Widerstand das Subjekt zu einer Herausforderung, geeignet für die grausamen Experimente des Apothekariums."}},faq={{q="Was ist Unending Torment?",a="Unending Torment schickt Euch zu einem trotzigen Subjekt, das mit der Königlichen Apothekervereinigung in Verbindung steht. Der Gefangene oder das feindselige Wesen nennt Euch eine Abscheulichkeit und verweigert jede Hilfe, also meldet Ihr diesen Fehlschlag Apothekermeister Faranell in Unterstadt.",al={"unending torment quest","was ist unending torment","unending torment hintergrundgeschichte"}},{q="Wer vergibt die Quest Unending Torment?",a="Ein trotziges Subjekt weist Euer Ansinnen zurück und nennt Euch eine Abscheulichkeit. Der Gefangene bleibt im Gespräch namenlos und schickt Euch mit Euren Erkenntnissen zur Führung der Königlichen Apothekervereinigung zurück.",al={"wer startet unending torment","unending torment questgeber","wo gibt es unending torment"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Königliche Apothekervereinigung im Apothekarium, unter den Ruinen von Lordaeron in Unterstadt. Er beaufsichtigt Alchemisten und Forscher der Verlassenen, die Seuchen, Mixturen und Gifte entwickeln, um die Verlassenen zu verteidigen und ihre Feinde in ganz Azeroth zu vernichten.",al={"wer ist faranell","apothekermeister faranell","apotheker faranell rolle"}},{q="Warum nennt der Sprecher den Spieler eine Abscheulichkeit?",a="Der Gefangene nennt Euch aus Abscheu vor den Untoten und ihren Handlangern eine Abscheulichkeit. Viele Lebende und Feinde der Verlassenen teilen dieses Entsetzen vor den wandelnden Toten in Unterstadt.",al={"warum abscheulichkeit","wer nennt den spieler abscheulichkeit","warum ist der gefangene wütend"}},{q="Wo müsst Ihr nach Abschluss der Aufgabe Bericht erstatten?",a="Meldet die Weigerung des Subjekts direkt Apothekermeister Faranell in Unterstadt. Tief im Apothekarium umgeben ihn Forscherkollegen, während sie tödliche Mixturen für Fürstin Sylvanas Windläufer und die Verlassenen herstellen.",al={"wo unending torment abgeben","unending torment abgeben","wem bei unending torment bericht erstatten"}},{q="Wie reagiert Apothekermeister Faranell auf den Trotz des Subjekts?",a="Apothekermeister Faranell freut sich über die hartnäckige Weigerung des Subjekts. Er begrüßt die verfahrene Lage als unterhaltsame Herausforderung und genießt es, schwierige Subjekte mit den rücksichtslosen Methoden der Königlichen Apothekervereinigung zu prüfen.",al={"faranells reaktion","was sagt faranell","wird faranell wütend"}}},fp="16,165,23.236.0,19.258.0,25.241.0,37.198.0,34.290.0,52.188.0,48.222.0,68.219.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="In der Unterstadt braut Apothekermeister Faranell einen Trank, der einen Gefangenen an den Willen der Dark Lady binden soll. Zur Vollendung braucht er tödliche Reagenzien aus der gesamten Hauptstadt der Verlassenen.",h="In der Unterstadt braut Apothekermeister Faranell einen Trank, der einen Gefangenen an den Willen der Dark...",kw={"das apothekarium","blisterweed","essenz der pein","faranell","apothekermeister faranell","tawny grisette","toxic skullcap","unterstadt","unending torment"},ang={["class:Rogue"]="Die Aufgabe führt Euch ins Rogues' Quarter, um Essenz der Pein zu kaufen, ein wirksames Reagenz, das Gifthersteller und Assassinen schätzen.",["faction:Horde"]="Die Royal Apothecary Society braut weiterhin tief unter Lordaerons Ruinen finstere Mixturen und erprobt die Grenzen alchemistischer Unterwerfung.",["profession:Herbalism"]="Das Sammeln von Blisterweed bei den Kräuterkundelehrern des Apothekariums zeigt, wie sich gewöhnliche Pflanzenkunde mit der finsteren alchemistischen Arbeit der Royal Apothecary Society überschneidet.",["race:Undead"]="Für die Verlassenen gehört alchemistische Folter, die wiederbelebte Überreste an den Dienst der Dark Lady bindet, zum Alltag im Apothekarium."},sec={{t="Den Willen binden",b="Tief im Apothekarium der Unterstadt führt Apothekermeister Faranell Experimente durch, um die Verlassenen zu stärken. Er hat den abgetrennten Kopf eines geschundenen Gefangenen wieder befestigt. Nun braucht er eine besondere alchemistische Mischung, um den verbliebenen Widerstand der Kreatur zu brechen und ihren Willen an Fürstin Sylvanas Windläufer zu binden."},{t="Reagenzien der Apotheker",b="Faranell schickt seinen Agenten durch die Unterstadt, um wirksame Zutaten für sein Gebräu zu sammeln. Ein Toxic Skullcap stammt von Tawny Grisette im Trade Quarter. Blisterweed haben die nahegelegenen Kräuterkundelehrer, die ihm etwas schulden, und ein Gifthändler im Rogues' Quarter verkauft Essenz der Pein."},{t="Das Meisterwerk",b="Mit den Zutaten in Händen ist Faranell grimmig zufrieden mit dem Meisterwerk, das er gleich erschaffen wird. Er freut sich darauf, das Gebräu an ihrem „ehrenwerten Gast“ zu erproben. Er vertraut darauf, dass der qualvolle Trank die verbliebene Großspurigkeit des Gefangenen bricht und die verirrte Kreatur gehorsam in den Dienst der Dark Lady zurückführt."}},faq={{q="Wer bietet die Quest Unending Torment an?",a="Apothekermeister Faranell bietet sie an. Er leitet die Royal Apothecary Society und ist im Apothekarium in der Unterstadt zu finden.",al={"wer vergibt unending torment","questgeber unending torment","unending torment beginn"}},{q="Welche Reagenzien werden für Faranells Gebräu benötigt?",a="Faranell braucht drei Zutaten: ein Toxic Skullcap von Tawny Grisette im Trade Quarter, Blisterweed aus der Nähe der Kräuterkundelehrer im Apothekarium und Essenz der Pein von einem Gifthändler im Rogues' Quarter.",al={"welche zutaten werden benötigt","unending torment gegenstände","welche reagenzien braucht faranell"}},{q="An wem experimentiert Apothekermeister Faranell?",a="Faranell experimentiert an einem Gefangenen gegen dessen Willen, dessen abgetrennter Kopf gerade wieder befestigt wurde. Spöttisch nennt er ihn ein „verlorenes Schaf“ und einen „ehrenwerten Gast“ und will die trotzige Großspurigkeit brechen, an der er nach schweren Prügeln festhält.",al={"wer ist die bestie","wer ist das verlorene schaf das faranell erwähnt","wer wird gefoltert"}},{q="Was ist das Ziel von Faranells Trank?",a="Faranells Trank soll das Versuchsobjekt geistig brechen und an den Willen von Fürstin Sylvanas Windläufer binden. Sie ist die Dark Lady der Verlassenen.",al={"warum diesen trank brauen","zweck des tranks für unending torment","was bewirkt das gebräu"}},{q="Wo können Spieler Tawny Grisette finden?",a="Tawny Grisette befindet sich im Trade Quarter der Unterstadt, wo sie Spezialwaren anbietet, darunter das Toxic Skullcap, das die Apotheker benötigen.",al={"wo ist tawny grisette","toxic skullcap händler","fräulein grisette finden"}},{q="Wo befindet sich Blisterweed?",a="Blisterweed wächst im Apothekarium nahe den Kräuterkundelehrern der Unterstadt, den Alliestars. Faranell sagt, sie schuldeten ihm einen Gefallen, also dürfen Abenteurer nehmen, was benötigt wird.",al={"wo ist blisterweed zu finden","alliestaers kräuterkunde","kräuterkundelehrer undrecity blisterweed"}}},fp="16,175,16.305.0,19.289.0,15.316.1,38.134.0,51.224.0,51.231.0,38.142.0,38.138.0,33.171.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Apothekermeister Faranell setzt unter Unterstadt eine Bestrafung in Gang. Im Apothekarium setzt die Royal Apothecary Society Hissing Serum gegen Othmars Überreste ein und strebt nach dauerhafter Vergeltung für Verbrechen gegen die Dunkle Fürstin.",h="Apothekermeister Faranell setzt unter Unterstadt eine Bestrafung in Gang.",kw={"das apothekarium","dunkle fürstin","garithos","hissing serum","apothekermeister faranell","othmar","unterstadt","unending torment"},ang={["faction:Horde"]="Indem Ihr Faranell in Unterstadt helft, beteiligt Ihr Euch an den harten Methoden der Verlassenen gegen jene, die sich ihnen und der Banshee Queen widersetzt haben.",["race:Undead"]="Apothekermeister Faranell leitet die Royal Apothecary Society in Unterstadt. Für die Verlassenen steht die Bestrafung von Feinden der Dunklen Fürstin wie Garithos im Mittelpunkt ihrer Vergeltung."},sec={{t="Vergeltung der Apotheker",b="Im Apothekarium von Unterstadt führt Apothekermeister Faranell grausame Experimente an den Feinden der Verlassenen durch. Er hat Hissing Serum vorbereitet, eine ätzende Substanz, die endlos auf einen Gefangenen unter einer alchemistischen Vorrichtung tropfen soll."},{t="Garithos’ Schicksal",b="Grand Marshal Garithos liegt als Othmar unter Faranells Apparatur, seine Überreste in einem aufgehängten Gestell fixiert. Faranell hält chemische Qualen für eine angemessene Strafe für Verbrechen gegen die Dunkle Fürstin. Das Serum rinnt über Othmars Körper und lässt sein Fleisch zur Strafe und zu Forschungszwecken sieden."}},faq={{q="Wer ist Othmar?",a="Othmar ist Grand Marshal Othmar Garithos, der ehemalige menschliche Befehlshaber, der während der Rückeroberung Lordaerons ein brüchiges Bündnis mit Sylvanas Windläufer schloss. Die Verlassenen verrieten und töteten ihn. Apothekermeister Faranell hält nun seine Überreste für fortgesetzte Folter und Experimente fest.",al={"wer ist othmar","was ist othmar","othmar garithos"}},{q="Warum wird Othmar gefoltert?",a="Othmar Garithos half Sylvanas Windläufer, Capital City von den Schreckenslords zurückzuerobern. Doch er verachtete alle Nichtmenschen und wollte ganz Lordaeron für die Menschheit beanspruchen. Die Verlassenen halten ihn der Verbrechen gegen die Dunkle Fürstin für schuldig und chemische Qualen für eine angemessene Strafe für seine Arroganz und Taten.",al={"warum wird othmar gefoltert","was hat othmar getan","verbrechen gegen sylvanas"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Royal Apothecary Society im Apothekarium von Unterstadt. Er beaufsichtigt die Herstellung von Seren, Giften und Seuchen und leitet das Vorgehen gegen Othmar.",al={"faranells rolle","wer vergibt unending torment","apotheker faranell"}},{q="Was bewirkt Hissing Serum?",a="Hissing Serum ist ein alchemistisches Gebräu von Apothekermeister Faranell. Es lässt Fleisch sieden und verursacht unerträgliche Schmerzen, während es aus einer Apparatur über Othmars aufgehängtem Körper fließt.",al={"was ist hissing serum","wirkung des serums","faranells serum"}},{q="Ist Othmar lebendig oder untot?",a="Othmar ist untot. Die Dunkle Fürstin erschlug Garithos selbst, und sein Kopf wurde mit dem Körper einer Monstrosität verbunden, der zuckend zum Leben erwacht. Faranell nennt ihn ihren „neuen Gast“ und will ihn unter dem tropfenden Serum weiter leiden lassen.",al={"othmar tot oder lebendig","lebt garithos","othmars zustand"}},{q="Was hat Faranell als Nächstes mit Othmar vor?",a="Apothekermeister Faranell will Othmars Fleisch unter der tropfenden Apparatur weiter sieden lassen und ihn genau beobachten. Er sagt, er habe umfangreiche Pläne für Othmars Zukunft, in der weitere Experimente und Vergeltung auf ihn warten.",al={"faranells zukunftspläne","was geschieht als nächstes mit othmar","othmars zukunft"}}},fp="16,237,22.247.0,20.274.1,14.280.0,30.290.0,34.193.0,31.175.0,26.236.0,47.226.0"}
P.entries["quest:973"] = {n="Der Turm von Althalaxx",s="Am Turm von Althalaxx führen finstere Kultisten Delgren den Läuterer auf die Spur von Ilkrud Magthrull. Er schickt Euch südwärts durch die Dunkelküste ins Eschental, um den Orc-Hexenmeister am Schrein des Sengenden Feuers zu töten und seinen Folianten zu bergen.",h="Am Turm von Althalaxx führen finstere Kultisten Delgren den Läuterer auf die Spur von Ilkrud Magthrull.",kw={"althalaxx","eschental","delgren","schrein des sengenden feuers","ilkrud","maestra","magthrull","foliant","hexenmeister"},ang={["class:Paladin"]="Als Paladin kämpft Ihr an der Seite von Delgren dem Läuterer gegen Teufelsbeschwörer und nehmt ihre verderbten Folianten an Euch. Ihr folgt dem Ruf des Heiligen Lichts im Kampf gegen dämonische Verderbnis.",["class:Warlock"]="Als Hexenmeister stellt Ihr Euch Ilkrud Magthrull, der wie Ihr die dunklen Künste ausübt. Er bewacht seine unheiligen Schriften mit beschworenen Sukkubi und Leerwandlern.",["faction:Alliance"]="Als Abenteurer der Allianz reist Ihr von der Dunkelküste in die dämonisch verseuchten Gebiete des Eschentals, um Euch einer wachsenden Bedrohung zu stellen.",["race:NightElf"]="Als Nachtelf verteidigt Ihr die uralten Wälder des Eschentals gegen die Schändung am Schrein des Sengenden Feuers, indem Ihr Ilkrud niederstreckt."},sec={{t="Eine Jagd ins Eschental",b="Delgren der Läuterer verfolgt die Spur der finsteren Kultisten am Turm von Althalaxx bis zu Ilkrud Magthrull, einem Orc-Hexenmeister. Ilkrud wirkt vom Schrein des Sengenden Feuers im südwestlichen Eschental aus. Delgren fürchtet, seine Magie könnte sich in den Elfenwäldern ausbreiten, und schickt Euch deshalb los, den Hexenmeister zu töten und seinen Folianten zu nehmen. Er hofft, dessen Inhalt werde die Pläne seines Meisters enthüllen."},{t="Das Versteck des Hexenmeisters",b="Am Schrein des Sengenden Feuers umgibt sich Ilkrud mit einem beschworenen Sukkubus und wachenden Teufelstötern. Rote Säulen markieren den felsigen Aufstieg zum Schrein. Sobald Ilkrud tot ist, kann Delgren seinen Folianten studieren. Das darin enthaltene Wissen und die Befehle stehen mit den Ritualen bei Althalaxx in Verbindung."}},faq={{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Streiter der Allianz in Maestras Posten, einem Außenposten der Nachtelfen an der Grenze zwischen Dunkelküste und Eschental. Er leitet den Kampf gegen dämonische Verderbnis und Kultisten in der Region.",al={"delgren","delgrens geschichte","wer startet die quest"}},{q="Wer ist Ilkrud Magthrull?",a="Ilkrud Magthrull ist ein Orc-Hexenmeister, der sein Versteck am Schrein des Sengenden Feuers im südwestlichen Eschental eingerichtet hat. Delgren hielt ihn zunächst für ein geringfügiges Ärgernis, doch seine Verbindungen zu den finsteren Riten am Turm von Althalaxx machen ihn zu einem entscheidenden Ziel.",al={"ilkrud","wer ist ilkrud magthrull","orc-hexenmeister eschental"}},{q="Wo liegt der Schrein des Sengenden Feuers?",a="Der Schrein des Sengenden Feuers liegt im südwestlichen Eschental, südlich des Schreins von Aessina und westlich von Astranaar. Dämonen hausen in der verderbten Enklave, und zwei rote Säulen flankieren den Weg zu Ilkruds Altar.",al={"schrein des sengenden feuers standort","wo ist ilkrud","wie erreicht man ilkrud"}},{q="Warum braucht Delgren Ilkrud Magskluves Foliant?",a="Ilkruds Foliant enthält seine finsteren Rituale und Nachrichten. Delgren hofft, sie zu entschlüsseln und das Komplott aufzudecken, das den Hexenmeister mit den Kultisten rund um den Turm von Althalaxx verbindet.",al={"warum der foliant","was steht in ilkruds folianten","zweck des folianten"}},{q="Wie verbindet diese Quest die Dunkelküste mit dem Eschental?",a="Die Untersuchung beginnt am Turm von Althalaxx an der nördlichen Küste der Dunkelküste. Während sich das Geheimnis vertieft, führt das Netzwerk der Kultisten südwärts durch die Dunkelküste in die umkämpften Wälder des Eschentals.",al={"quest von der dunkelküste ins eschental","zusammenhang der althalaxx-questreihe"}},{q="Was geschieht nach der Bergung des Folianten?",a="Delgren studiert den Folianten, um die Pläne hinter den Kultisten am Turm von Althalaxx aufzudecken. Seine Erkenntnisse führen zu den letzten Konfrontationen der Questreihe.",al={"nächste quest","was folgt auf althalaxx fünf"}}},fx={b25de95c={q="Warum will Delgren der Läuterer, dass dies erledigt wird?",a="Delgren der Läuterer widmet sich der Ausrottung dämonischer Verderbnis in der Region. Während er Ilkrud Magthrull früher für kaum mehr als ein geringfügiges Ärgernis hielt, machen ihn die finsteren Forschungen des Hexenmeisters und seine aktive Präsenz am korrumpierten Schrein des Sengenden Feuers zu einer wachsenden Bedrohung, die Delgren nicht länger ignorieren kann.",al={"delgrens beweggrund","warum ilkrud magthrull töten","delgren der läuterers ziel"}}},fp="22,205,21.347.0,18.253.1,28.204.0,24.236.0,38.193.0,46.176.0,51.193.0,39.154.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="Hinter Grommash Hold schaffen Thra und Freunde Platz für Spiele in Orgrimmar. Sie brauchen glatte Felsbrocken als Stühle und Tische.",h="Hinter Grommash Hold schaffen Thra und Freunde Platz für Spiele in Orgrimmar.",kw={"durotar","grommash hold","orcs","orgrimmar","rocks to rests","glatte felsblöcke","tabletop","thra"},ang={["faction:Horde"]="Jungen Orcs hinter der Festung des Kriegshäuptlings zu helfen, zeigt, wie wichtig Gemeinschaft und Alltag in Orgrimmar sind, selbst in einer Kriegergesellschaft.",["race:Orc"]="Orc-Jugendliche, die hinter Grommash Hold Spiele erfinden, zeigen, wie die nächste Generation im Herzen von Durotar aufwächst."},sec={{t="Eine ruhige Ecke von Orgrimmar",b="Junge Orcs versammeln sich auf einer gerodeten Fläche hinter Grommash Hold in Orgrimmar. Dort können sie fern der Festungswachen spielen. Der freie Boden eignet sich für ihre Miniaturfiguren, doch ohne Möbel sitzen sie im Staub."},{t="Behelfsmäßiges Mobiliar",b="Thra bemerkt Euch im Vorbeigehen und bittet Euch, acht mittelgroße, glatte Felsbrocken zur freien Fläche zu bringen. Ihre flachen Seiten eignen sich als stabile Stühle und niedrige Tische. Dann können die Jugendlichen ihre Spiele aufbauen, ohne im Staub zu sitzen."}},faq={{q="Wer vergibt die Quest Rocks to Rests?",a="Thra ist ein junger Orc, der mit Freunden auf der freien Fläche hinter Grommash Hold in Orgrimmar spielt. Thra ist aufmerksam und verspielt und bittet Passanten, den Spielbereich zu verbessern.",al={"wer vergibt rocks to rests","thra orgrimmar","wer ist thra"}},{q="Wo findet diese Quest statt?",a="Die freie Fläche liegt direkt hinter Grommash Hold, dem Sitz von Kriegshäuptling Thrall im Tal der Weisheit von Orgrimmar. Die Kinder versammeln sich auf diesem vergleichsweise freien Fleck Erde, abseits des regen Verkehrs vor der Festung.",al={"wo ist rocks to rests","thra aufenthaltsort","wo hinter grommash hold"}},{q="Warum benötigt Thra glatte Felsblöcke?",a="Thra und die anderen Jugendlichen brauchen glatte, mittelgroße Felsen als Stühle und Tische. Ohne Möbel sitzen sie im Staub, während sie ihre Miniaturspiele aufbauen und spielen.",al={"warum steine","wozu glatte felsblöcke","warum felsblöcke"}},{q="Welches Spiel wird hinter Grommash Hold gespielt?",a="Thra und die anderen Jugendlichen spielen ein ungezwungenes Brettspiel mit kleinen Figuren, die auf dem Boden verteilt sind. Die glatten Felsbrocken bieten ihnen stabile Plätze für ihre Figuren und bequeme Sitzgelegenheiten.",al={"welches spiel spielen sie","thra spiel orgrimmar","figuren hinter grommash hold"}},{q="Beinhaltet Rocks to Rests Kämpfe?",a="Nein. Dies ist ein friedliches Vorhaben ohne Kämpfe oder militärische Prüfung. Ihr nutzt Eure Stärke, um schwere Felsbrocken zum Spielplatz der Kinder zu schleppen.",al={"ist rocks to rests gefährlich","kampf rocks to rests"}},{q="Was machen die Kinder mit den Felsblöcken, sobald diese abgeliefert wurden?",a="Nachdem Ihr die acht glatten Felsbrocken abgeliefert habt, rücken Thra und die Kinder sie auf der freien Fläche zurecht. Ihre flachen Seiten dienen als Sitze und Tische für die Figuren ihres Brettspiels.",al={"was passiert nach rocks to rests","was macht thra mit steinen"}}},fp="14,127,27.214.0,19.223.0,35.178.0,33.204.0,35.171.0,47.202.0,37.145.0,57.176.0"}
P.entries["quest:97328"] = {n="Anything of Value",s="Ein Zeppelinabsturz im Schlingendorntal hinterlässt Spuren, die auf eine geplünderte Lieferung hindeuten. Ihr zerrissenes Etikett weist noch immer auf Beutebucht hin.",h="Ein Zeppelinabsturz im Schlingendorntal hinterlässt Spuren, die auf eine geplünderte Lieferung hindeuten.",kw={"etwas von wert","beutebucht","absturz","fußspuren","lieferung","gestohlene vorräte","zeppelin","zul'kunda"},sec={{t="Ein zerrissenes Etikett",b="Im Schlingendorntal finden sich zwischen den Trümmern des Absturzes Spuren einer geplünderten Vorratslieferung. Ihre Etiketten sind zerfetzt, doch eines trägt noch immer das Wort Beutebucht. Zweizehige Fußspuren und Vertiefungen im Boden führen zu den Ruinen von Zul'Kunda im Nordwesten."}},faq={{q="Was ist mit der Lieferung geschehen?",a="Die Vorräte wurden geplündert und die Versandetiketten zerrissen.",al={"gestohlene lieferung","zeppelinladung","was wurde geplündert"}},{q="Wohin führten die Fußspuren?",a="Die Fußspuren und Vertiefungen führen zu den Ruinen von Zul'Kunda im Nordwesten.",al={"zweizehige spuren","wo ist die fährte","fußspuren"}},{q="Was steht auf dem erhaltenen Etikett?",a="Auf einem zerrissenen Etikett steht noch immer das Wort Beutebucht.",al={"etikett beutebucht","zerrissenes versandetikett","wohin sollte es gehen"}},{q="Wer braucht die geborgenen Lieferungen?",a="Die Lieferungen sollen jemandem in Beutebucht zurückgebracht werden.",al={"wer will die ladung","wohin damit","lieferung zurückbringen"}}},fp="17,128,12.249.0,30.69.0,30.78.0,34.47.0,34.57.0"}
P.entries["quest:97329"] = {n="Where's the Key?",s="Zimmix Sputterspark sitzt in einem Käfig, nachdem sein Zeppelin nahe Beutebucht abgeschossen wurde. Er bittet Euch, ihm einen Schlüssel zu bringen, den Trolle bei Zul'Kunda bewachen.",h="Zimmix Sputterspark sitzt in einem Käfig, nachdem sein Zeppelin nahe Beutebucht abgeschossen wurde.",kw={"beutebucht","käfig","primitive key","trolle","wo ist der schlüssel","zeppelin","zimmix sputterspark","zul'kunda"},sec={{t="Ein Absturz nahe Beutebucht",b="Zimmix Sputterspark ruft Euch aus seinem Käfig nahe Beutebucht zu sich. Er hatte vereinbart, dass die Bucht ihren Zeppelinturm für schnellere Lieferungen nutzen würde, doch die erste Route endete damit, dass sein Fluggerät im Osten abgeschossen wurde. Er überlebte den Absturz und erwachte dann, als man ihn fortschleifte und unter Trollen einsperrte. Nun bittet er Euch, ihm den Primitive Key zu bringen, den Trolle bei den Ruinen von Zul'Kunda im Schlingendorntal bewachen."},{t="Der Schlüssel",b="Am Käfig stürzt sich Zimmix auf den Schlüssel, als Ihr ihn zurückbringt. Wiederholt versucht er, ihn Euch zu entreißen, und besteht darauf, dass Ihr ihn ihm aushändigt."}},faq={{q="Wer sitzt im Käfig?",a="Zimmix Sputterspark sitzt in einem Käfig nahe Beutebucht, nachdem sein Zeppelin abgeschossen wurde.",al={"wer ist zimmix","eingesperrter gnom","zimix"}},{q="Was geschah mit Zimmix' Zeppelin?",a="Zimmix sagt, sein Zeppelin sei auf seiner ersten Lieferroute im Osten abgeschossen worden.",al={"warum stürzte er ab","zeppelinabsturz","was geschah mit zimmix"}},{q="Warum sitzt Zimmix in einem Käfig?",a="Nachdem er den Absturz überlebt hatte, erwachte Zimmix, als man ihn an den Ohren fortschleifte, und fand sich in einem Käfig unter Trollen wieder.",al={"warum eingesperrt","trollkäfig","wie wurde er gefangen"}},{q="Welchen Schlüssel will Zimmix?",a="Zimmix bittet Euch, ihm den Primitive Key zu bringen, den Trolle bei den Ruinen von Zul'Kunda im Schlingendorntal bewachen.",al={"welcher schlüssel","primitive key","schlüssel für zimmix"}},{q="Wo ist der Primitive Key?",a="Der Primitive Key wird von Trollen bei den Ruinen von Zul'Kunda im Schlingendorntal bewacht.",al={"wo ist der schlüssel","zul'kunda-schlüssel","fundort des schlüssels"}},{q="Was tut Zimmix, wenn Ihr den Schlüssel bringt?",a="Zimmix stürzt sich auf den Schlüssel und versucht wiederholt, ihn Euch zu entreißen.",al={"schlüsselübergabe","zimmix schnappt sich den schlüssel","was geschieht mit dem schlüssel"}}},fp="16,149,22.406.0,7.142.0,27.89.0,35.79.0,24.126.0,26.110.0,27.84.0,43.71.0"}
P.entries["quest:97331"] = {n="Zimmix's Great Escape",s="Zimmix Sputterspark bittet Euch, ihn aus den Ruinen von Zul'Kunda zu eskortieren. Er fürchtet, die Trolle könnten ihn erneut fangen, und Werftmeister Lozgil in Beutebucht soll von der Rettung erfahren.",h="Zimmix Sputterspark bittet Euch, ihn aus den Ruinen von Zul'Kunda zu eskortieren.",kw={"beutebucht","große flucht","schlüssel","ruinen von zul'kunda","trolle","werftmeister lozgil","zimmix","zimmix sputterspark"},sec={{t="Die Bitte eines Goblins",b="In den Ruinen von Zul'Kunda bittet Zimmix Sputterspark Euch, Wache zu halten, während er aufbricht. Er sagt, die Trolle hätten ihn bereits einmal gefangen, und fürchtet, dass sie es wieder tun könnten. Ihr habt ihre Reihen bereits genug geschwächt, um den Schlüssel zu beschaffen, den er brauchte. Nun bittet Zimmix Euch um Hilfe, damit er in Sicherheit gelangt. Werftmeister Lozgil in Beutebucht wartet auf Nachricht von der Rettung."}},faq={{q="Wer ist Zimmix?",a="Zimmix Sputterspark ist ein Goblin, der Euch bittet, ihn aus den Ruinen von Zul'Kunda zu eskortieren.",al={"zimmix","wer ist zimmix","zimmix sputterspark"}},{q="Warum möchte Zimmix eskortiert werden?",a="Zimmix fürchtet, dass die Trolle ihn erneut fangen könnten, nachdem sie ihn zuvor schon einmal gefangen hatten.",al={"warum zimmix eskortieren","zimmix hat angst","trolle haben ihn gefangen"}},{q="Von wo eskortiert Ihr Zimmix?",a="Ihr eskortiert Zimmix fort von den Ruinen von Zul'Kunda.",al={"wo ist zimmix","zul'kunda","zimmix standort"}},{q="Wer soll von der Rettung erfahren?",a="Werftmeister Lozgil in Beutebucht soll von Zimmix' erfolgreicher Rettung erfahren.",al={"wem bescheid sagen","lozgil","rettungsbericht"}},{q="Welchen Schlüssel brauchte Zimmix?",a="Zimmix sagt, dass er einen Schlüssel brauchte und dass Ihr die Trolle genug geschwächt habt, um ihn zu beschaffen.",al={"zimmix schlüssel","warum den schlüssel holen","schlüssel für zimmix"}}},fp="21,174,15.336.0,14.87.0,31.78.0,36.58.0,33.73.0,25.79.0"}
P.entries["quest:97332"] = {n="Twice Misplaced Trust",s="Ein Goblin bittet Euch, ein dringendes Paket zu Hafenmeister Whizzbuzz am Hafen von Powderfuse zu bringen. Er vertraut Euch, nachdem Ihr verlorene Fracht und einen gefangenen Goblin gerettet habt.",h="Ein Goblin bittet Euch, ein dringendes Paket zu Hafenmeister Whizzbuzz am Hafen von Powderfuse zu bringen.",kw={"goblin-kurier","lozgil","hafen von powderfuse","flusslande","zweimal fehlgeleitetes vertrauen","zweimal umgeleitetes paket","whizzbuzz","zimmix"},sec={{t="Ein Kurier wird gebraucht",b="Der Goblin muss noch eine Lieferung erledigen, vertraut Zimmix damit aber nicht. Vor Zimmix wird kein anderer Kurier verfügbar sein, also bittet er Euch, das Paket zu Hafenmeister Whizzbuzz am Hafen von Powderfuse zu bringen. Ihr habt bereits verlorene Fracht und einen gefangenen Goblin gerettet und Euch damit das Vertrauen des Absenders verdient."},{t="Am Hafen von Powderfuse",b="Whizzbuzz öffnet die Kiste und ist überrascht, dass Lozgil endlich das Erwartete geschickt hat. Ein harscher Brief und ein bezahlter Kurier, der ihm drohte, hatten Lozgil unter Druck gesetzt. Whizzbuzz fragt sich, ob ein Schiffskapitän gefangen genommen wurde oder ein Zeppelin abgestürzt ist, merkt dann aber an, dass der Hafen keinen Zeppelinturm hat."}},faq={{q="Wer bittet mich, das Paket auszuliefern?",a="Ein Goblin bittet Euch, das Paket zu Hafenmeister Whizzbuzz am Hafen von Powderfuse zu bringen.",al={"wer braucht eine lieferung","goblin-absender","wer hat mich geschickt"}},{q="Warum vertraut der Goblin mir?",a="Ihr habt verlorene Fracht und einen gefangenen Goblin gerettet, deshalb hält Euch der Absender für vertrauenswürdig.",al={"warum ich","warum vertraut er mir","grund für das vertrauen"}},{q="Warum lässt er Zimmix das Paket nicht ausliefern?",a="Der Absender vertraut Zimmix diese Lieferung nicht an.",al={"warum nicht zimmix","lieferung durch zimmix","nicht zimmix"}},{q="Wohin soll das Paket?",a="Das Paket ist für Hafenmeister Whizzbuzz am Hafen von Powderfuse in den Flusslanden bestimmt.",al={"paket-ziel","wohin liefern","hafen von powderfuse"}},{q="Wer ist Lozgil?",a="Whizzbuzz schreibt Lozgil zu, das Paket endlich geschickt zu haben.",al={"lozgils paket","wer ist lozgil","lozgil"}},{q="Warum ist Whizzbuzz überrascht?",a="Whizzbuzz ist überrascht, als er in die Kiste späht und sieht, dass Lozgil endlich das Erwartete geschickt hat.",al={"whizzbuzz' reaktion","überraschung in der kiste","was ist in der kiste"}}},fp="21,155,16.304.0,18.301.1,35.83.0,29.91.0,31.52.0,26.85.0,14.69.0,27.110.0"}
P.entries["quest:97386"] = {n="The Offense of Grom'gol",s="Kommandant Aggro'gosh bittet Euch um Hilfe für das Basislager Grom'gol, nachdem ein Späher Oger in einer Höhle im Osten entdeckt hat. Die Siedlung wurde bereits von ihnen angegriffen, und die Gefahr besteht weiter.",h="Kommandant Aggro'gosh bittet Euch um Hilfe für das Basislager Grom'gol, nachdem ein Späher Oger in einer...",kw={"aggro'gosh","basislager","grom'gol","mosh'ogg","oger","späher"},sec={{t="Der Bericht eines Spähers",b="Nachdem Ihr geholfen habt, das Basislager Grom'gol zu verteidigen und die Oger in der Nähe zurückzudrängen, schickt Kommandant Aggro'gosh einen Späher los, um nach weiteren zu suchen. Der Späher entdeckt Oger, die in einer Höhle weit im Osten hausen. Aggro'gosh bittet Euch, gegen den Mosh'Ogg Ogre Mount vorzugehen, damit die Siedlung nicht länger von ihnen bedroht wird."}},faq={{q="Wer bittet um Hilfe gegen die Oger?",a="Kommandant Aggro'gosh vom Basislager Grom'gol bittet Euch, Euch um die Oger zu kümmern.",al={"wer gibt diesen auftrag","aggro'gosh bittet"}},{q="Wo hat der Späher die Oger entdeckt?",a="Der Späher entdeckt sie in einer Höhle weit im Osten, am Mosh'Ogg Ogre Mount.",al={"wo ist die ogerhöhle","wo sind sie"}},{q="Warum macht Aggro'gosh sich Sorgen wegen der Oger?",a="Grom'gol musste sich bereits mit Ogern in der Nähe auseinandersetzen, und der Späher entdeckt weitere, die in einer Höhle im Osten hausen.",al={"warum gegen oger kämpfen","bedrohung durch oger"}},{q="Was ist zuvor geschehen?",a="Ihr habt geholfen, Grom'gol zu verteidigen und die Oger in der Nähe zurückzudrängen, bevor der Späher nach weiteren gesucht hat.",al={"vorheriger schritt","verteidigung von grom'gol"}}},fp="23,177,16.292.0,36.75.0,35.75.0,44.97.0,26.94.0"}
P.entries["quest:97453"] = {n="Weed Whacked",s="Gemmil bittet Euch, Euch um die Carnivorous Weeds südlich von Grom'gol zu kümmern. Sie haben Gemmil beim Pflanzensammeln erschreckt, und die Sicherheit des Lagers steht auf dem Spiel.",h="Gemmil bittet Euch, Euch um die Carnivorous Weeds südlich von Grom'gol zu kümmern.",kw={"alchemist","carnivorous weeds","gemmil","grom'gol","kräuterkunde","dschungel","weed whacked"},ang={["profession:Herbalism"]="Als Schüler der Kräuterkunde könnt Ihr Gemmils Wunsch verstehen, Pflanzen zu erforschen und Alchemist zu werden."},sec={{t="Ein erschrockener Schüler",b="Gemmil sammelte Pflanzen vor den Toren des Dschungellagers, als riesige Unkräuter auftauchten und den jungen Schüler anspuckten. Gemmil entkam unverletzt, kann nun aber nicht mehr außerhalb des Lagers spielen. Ihr sollt das Gebiet südlich von Grom'gol sichern und dann mit Gemmils Mutter sprechen."}},faq={{q="Wer ist Gemmil?",a="Gemmil ist ein junger Schüler der Kräuterkunde, der hofft, Alchemist zu werden.",al={"gemmil wer","wer ist gemmil"}},{q="Was ist Gemmil passiert?",a="Beim Pflanzensammeln vor den Toren wurde Gemmil von riesigen Unkräutern erschreckt, die Gemmil anspuckten. Gemmil entkam unverletzt.",al={"gemmil angegriffen","spuckende unkräuter"}},{q="Wo sind die Carnivorous Weeds?",a="Die Carnivorous Weeds sind südlich von Grom'gol.",al={"unkraut fundort","wo unkräuter"}},{q="Warum kann Gemmil nicht außerhalb des Lagers spielen?",a="Gemmils Eltern lassen Gemmil nicht mehr außerhalb des Lagers spielen, seit die Unkräuter Gemmil erschreckt haben.",al={"gemmil kann nicht spielen","warum nicht draußen"}},{q="Mit wem sollt Ihr sprechen, nachdem Ihr das Gebiet gesichert habt?",a="Nachdem Ihr das Gebiet südlich von Grom'gol gesichert habt, sollt Ihr Gemmils Mutter informieren.",al={"gemmils mama informieren","gemmils mutter"}}},fp="12,173,20.274.0,14.72.0,24.121.0,32.44.0,35.90.0,53.86.0"}
P.entries["quest:97485"] = {n="Traditions of the Bluff",s="Eine Tradition der Tauren verlangt, dass Ihr von Jägers Rise aus Räucherwerk verstreut. Die Gabe kann Earthmother, einer Jagd, einem Anlass oder der Suche nach Führung gelten.",h="Eine Tradition der Tauren verlangt, dass Ihr von Jägers Rise aus Räucherwerk verstreut.",kw={"ahnen","zedernzweige","zeremonieller feuerstein","earthmother","jägers rise","räucherwerk","tradition der tauren","traditionen der anhöhe"},ang={["race:Tauren"]="Als Tauren ehrt Ihr eine Tradition, die Earthmother anrufen oder Führung bei Euren Ahnen suchen kann."},sec={{t="Räucherwerk für die Winde",b="Ein Tauren auf Jägers Rise bittet Euch, eine Tradition zu ehren und Räucherwerk in die Winde zu streuen. Ihr sammelt Kräuter, Zedernzweige, Sehnenfaden sowie zeremoniellen Feuerstein und Zunder bei den genannten Lieferanten. Am Zeremonienplatz fügt Ihr sie zusammen und verstreut das Räucherwerk von der nach Süden gerichteten Klippe aus."},{t="Viele Anlässe",b="Räucherwerk kann verstreut werden, um Earthmother um Schutz für jemanden zu bitten, eine Jagd zu segnen, einen Anlass zu würdigen oder Führung bei den Ahnen zu suchen. Die Handlung ist ehrfürchtig, muss jedoch keinem einheitlichen Zeremoniell folgen. Verschiedene Stämme befolgen unterschiedliche überlieferte Schritte."}},faq={{q="Welche Tradition gibt es auf Jägers Rise?",a="Die Tradition besteht darin, von der nach Süden gerichteten Klippe von Jägers Rise aus Räucherwerk in die Winde zu streuen.",al={"räucherwerktradition","räucherwerk verstreuen","räucherwerk auf der anhöhe"}},{q="Welchem Zweck kann die Räucherwerkgabe dienen?",a="Sie kann Earthmother bitten, über jemanden zu wachen, eine Jagd zu segnen, einen Anlass zu feiern oder Führung durch die Ahnen zu gewähren.",al={"warum räucherwerk","räucherwerk wofür","die jagd segnen"}},{q="Was brauche ich, um das Räucherwerk herzustellen?",a="Die Bestandteile sind Kräuter, Zedernzweige, Sehnenfaden sowie zeremonieller Feuerstein und Zunder.",al={"räucherwerkzutaten","welche bestandteile","kräuter zeder faden feuerstein"}},{q="Wo liegt der Zeremonienplatz?",a="Der Zeremonienplatz liegt auf der nach Süden gerichteten Klippe von Jägers Rise.",al={"wo räucherwerk verstreuen","lage des zeremonienplatzes","südklippe"}},{q="Pflegen alle Stämme die Tradition auf dieselbe Weise?",a="Nein. Verschiedene Stämme können unterschiedliche überlieferte Schritte befolgen, und die Handlung ist nicht streng zeremoniell.",al={"unterschiedliche stammesbräuche","gleiche zeremonie","räucherwerkschritte"}}},fp="23,155,20.290.0,14.259.0,41.96.0,37.124.0,35.85.0,29.68.0,49.101.0"}
P.entries["quest:97530"] = {n="Dunemaul Dues",s="Sicherheitschef Bilgewhizzle vom Dampfdruckpier will ein glänzendes Armreif nahe dem Dunemaul-Ogerlager zurückholen lassen. Es ging verloren, als eine Händlerkarawane Fracht abwarf, um die Oger abzulenken.",h="Sicherheitschef Bilgewhizzle vom Dampfdruckpier will ein glänzendes Armreif nahe dem Dunemaul-Ogerlager...",kw={"armreif","bilgewhizzle","karawane","dunemaul dues","dunemaul-oger","verlorene fracht","dampfdruckpier"},sec={{t="Verlorene Fracht",b="Eine Karawane verlor Fracht nahe dem Dunemaul-Ogerlager, nachdem die Oger sie angegriffen hatten. Sicherheitschef Bilgewhizzle vom Dampfdruckpier bittet Euch, ein besonders glänzendes Armreif zurückzuholen. Die Händler setzen ihn wegen ihrer entgangenen Gewinne unter Druck, und er bietet Euch eine angemessene Belohnung."}},faq={{q="Wer will den Armreif zurück?",a="Sicherheitschef Bilgewhizzle vom Dampfdruckpier möchte, dass Ihr das glänzende Armreif zurückholt.",al={"wer hat mich geschickt","bilgewhizzles armreif","wer will es"}},{q="Wo ging das Armreif verloren?",a="Das Armreif ging nahe dem Dunemaul-Ogerlager verloren.",al={"wo ist das armreif","fundort des armreifs","wo verloren"}},{q="Wie verlor die Karawane ihre Fracht?",a="Die Karawane nahm eine falsche Abzweigung durch die Wüste und wurde von Dunemaul-Ogern angegriffen. Ihre Leute warfen Fracht über Bord, um sie abzulenken.",al={"was geschah mit der karawane","dunemaul-karawane","warum ging die fracht verloren"}},{q="Warum möchte Bilgewhizzle es zurückholen lassen?",a="Die Händler setzen Bilgewhizzle wegen der Gewinne unter Druck, die ihnen mit ihrer Fracht entgangen sind.",al={"warum das armreif finden","entgangene gewinne","ärger mit den händlern"}},{q="Nach was für einem Armreif sucht Bilgewhizzle?",a="Bilgewhizzle bittet um ein besonders glänzendes Armreif.",al={"glänzendes armreif","welches armreif","armreif-quest"}}},fp="13,183,10.277.0,26.87.0,26.52.0,35.135.0,40.79.0,48.59.0"}
P.entries["quest:97534"] = {n="Gritty Business",s="Quinn in Gadgetzan bietet Euch einen Anteil am Erlös für Schrott aus Maschinen in der Wüste. Sie will die Teile an Schrotthändler verkaufen.",h="Quinn in Gadgetzan bietet Euch einen Anteil am Erlös für Schrott aus Maschinen in der Wüste.",kw={"desert debris","brennstoffzelle","gadgetzan","gritty business","schrotthändler","maschinen","quinn","schrott"},sec={{t="Ein Anteil am Schrott",b="Quinn hat in Gadgetzan Silber für Euch bereitliegen und will dort alles sortieren und verkaufen, was Ihr zurückbringt. Die Wüstenmaschinen verlieren Teile, die Technikfreaks vielleicht als Brennstoffzellenmaterial schätzen. Quinn möchte, dass Ihr ihr sieben Stück Desert Debris bringt, und verspricht Euch einen Anteil am Erlös aus dem Verkauf."}},faq={{q="Wer bittet um den Schrott?",a="Quinn in Gadgetzan bittet Euch, Desert Debris von Maschinen in der Wüste zu bergen.",al={"wer will schrott","quinn schrott","auftraggeber für schrott"}},{q="Was möchte Quinn zurückhaben?",a="Quinn möchte sieben Stück Desert Debris.",al={"welche teile","schrottstücke","gritty business gegenstände"}},{q="Warum möchte Quinn die Maschinenteile?",a="Quinn will den Schrott an Schrotthändler verkaufen, die die Teile vielleicht als Brennstoffzellenmaterial verwenden.",al={"warum schrott","wofür ist das","grund für schrott"}},{q="Was bietet Quinn im Gegenzug?",a="Quinn verspricht Euch einen Anteil am Erlös aus dem Verkauf des Schrotts.",al={"was bekomme ich","quinns angebot","gritty business belohnung"}},{q="Wo finde ich Quinn?",a="Quinn ist in Gadgetzan.",al={"quinns ort","wo ist quinn","auftraggeber in gadgetzan"}}},fp="15,126,22.280.0,29.86.0,38.42.0,38.87.0,32.64.0,22.22.0"}
P.entries["quest:97538"] = {n="Pigments for Paints",s="Tah Winterhoof braucht rotes Pigment für seine Farben, und Ihr könnt ihm helfen, seinen Vorrat aufzufüllen. Der Farbstoff stammt aus Mirkkrautsamenkapseln, die im Mirkfallonsee im Steinkrallengebirge gesammelt werden.",h="Tah Winterhoof braucht rotes Pigment für seine Farben, und Ihr könnt ihm helfen, seinen Vorrat aufzufüllen.",kw={"mirkfallonsee","mirkkraut","mirkkrautsamenkapseln","pigments for paints","rotes pigment","steinkrallengebirge","tah winterhoof","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde kennt Ihr die Verbindungen zwischen Donnerfels und den zerklüfteten Pässen des Steinkrallengebirges.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass neben Heilkräutern auch Wasserpflanzen wie Mirkkraut nützliche Pigmente liefern können. Die Gewässer des Mirkfallonsees sind gefährlich.",["race:Tauren"]="Als Tauren könnt Ihr sehen, wie die Handwerker von Donnerfels natürliche Pflanzen zur Herstellung traditioneller Pigmente und Farbstoffe nutzen."},sec={{t="Der Bedarf eines Handwerkers",b="Tah Winterhoof ist das rote Pigment ausgegangen, und er kann seine Arbeit nicht fortsetzen. Er lebt in Donnerfels, und seine Wanderjahre liegen hinter ihm. Deshalb bittet er Euch, die lange Reise nach Norden ins Steinkrallengebirge anzutreten und mehr Farbstoff zu sammeln."},{t="Die Gewässer des Mirkfallonsees",b="Der Mirkfallonsee liegt in einem Gebirgspass im Steinkrallengebirge. Unter seiner Wasseroberfläche wächst Mirkkraut, dessen Samenkapseln sich nach der Ernte und dem Trocknen rot färben. Sammelt dreißig Kapseln, und Tah hat das Rohmaterial, das er braucht, um seine Arbeit wieder aufzunehmen."}},faq={{q="Wer vergibt die Quest Pigments for Paints?",a="Tah Winterhoof bittet in Donnerfels um Hilfe. Seine Wanderjahre liegen hinter ihm, deshalb braucht er jemanden Jüngeren, der Materialien für sein Handwerk sammelt.",al={"wer vergibt pigments for paints","questgeber für pigments","tah winterhoof standort"}},{q="Wo sind Mirkkrautsamenkapseln zu finden?",a="Mirkkraut wächst im Wasser des Mirkfallonsees, eines großen, runden Sees in einem Gebirgspass im Steinkrallengebirge.",al={"wo mirkkrautsamenkapseln finden","mirkkraut fundort","wo ist der mirkfallonsee"}},{q="Warum braucht Tah Winterhoof Mirkkraut?",a="Tah Winterhoof ist das rote Pigment für seine Kunstwerke ausgegangen. Getrocknete Mirkkrautsamenkapseln färben sich rot und liefern Farbstoff für seine Farben.",al={"warum mirkkraut sammeln","wofür wird mirkkraut verwendet","warum rotes pigment"}},{q="Wie viele Mirkkrautsamenkapseln werden benötigt?",a="Tah Winterhoof braucht dreißig Mirkkrautsamenkapseln aus dem Mirkfallonsee, um seinen Vorrat an rotem Pigment aufzufüllen.",al={"wie viele kapseln benötigt","mirkkraut anzahl"}},{q="Was ist Mirkkraut?",a="Mirkkraut ist eine Wasserpflanze, die im Mirkfallonsee im Steinkrallengebirge wächst. Seine Kapseln werden beim Trocknen zu rotem Pigment.",al={"was für eine pflanze ist mirkkraut","mirkkraut einzelheiten"}},{q="Wo befindet sich Tah Winterhoof?",a="Tah Winterhoof lebt hoch oben in der Hochebenenstadt Donnerfels in Mulgore, wo er seinem Handwerk nachgeht und traditionelle Farben herstellt.",al={"wo ist tah winterhoof","tah winterhoof donnerfels"}}},fp="19,175,17.239.0,24.243.0,40.144.0,30.116.0,38.119.0,34.92.0,17.118.0,32.130.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="In Hammerfall setzt Doktor Gregory Victor auf Spinnenseide, da die Vorräte der Krankenstation schwinden. Die Belagerungsschäden bleiben unrepariert, und die Wachen und Arbeiter des Außenpostens brauchen weiterhin Versorgung.",h="In Hammerfall setzt Doktor Gregory Victor auf Spinnenseide, da die Vorräte der Krankenstation schwinden.",kw={"arathihochland","doktor gregory victor","feldnähte","hammerfall","lazarett","silky sutures","spinnenseide","chirurgische spinnenseide"},ang={["faction:Horde"]="Hammerfall ist ein wichtiger Stützpunkt der Horde im Arathihochland. Doktor Victors Arbeit hält seine Verteidiger gesund und bereit, die Stellung der Fraktion dort zu schützen.",["race:Undead"]="Als Untoter bringt Ihr das pragmatische, nüchterne medizinische Wissen der Verlassenen nach Hammerfall und nutzt Ressourcen aus dem Hochland, um die Klinik am Laufen zu halten."},sec={{t="Der zerfallende Außenposten",b="Hammerfall hält sich im Arathihochland, doch Belagerungsschäden zeichnen noch immer seine Verteidigungsanlagen. Doktor Gregory Victor, der Arzt des Außenpostens, sieht in der Vernachlässigung offizielle Politik. Mit wenig Unterstützung und bröckelnden Befestigungen um sich herum hält er die Krankenstation am Laufen. Ihre Versorgung hilft Arbeitern und Wachposten, auf den Beinen und kampfbereit zu bleiben."},{t="Behelfsmäßige medizinische Vorräte",b="In Hammerfall werden die medizinischen Vorräte knapp, also sucht Doktor Victor nach einer anderen Möglichkeit, Wunden zu nähen. Zähe Spinnenseide aus dem Hochland lässt sich zu widerstandsfähigen Nähfäden zwirnen, wenn Verbände und gewöhnlicher Faden knapp sind. Victor scherzt, eine Infektion sei die geringste Sorge eines verwundeten Soldaten. Die Seide liefert der Krankenstation Faden, um Verteidiger in feindlichem Gebiet zusammenzuflicken."},{t="Galgenhumor in Hammerfall",b="Doktor Gregory Victor begrüßt Reisende mit trockenen Scherzen über düstere Prognosen und Nähte aus Spinnenseide. Sein Humor verbirgt die harte Wirklichkeit einer Frontklinik, während Hammerfall weiterhin isoliert ist. Regelmäßige Hilfe ist im Hochland selten, und Reisende können helfen, die Klinik mit Vorräten zu versorgen. Victor setzt auf improvisierte Heilmittel und Entschlossenheit, um die Verwundeten zu versorgen, während der Außenposten um ihn herum verfällt."}},faq={{q="Wer ist Doktor Gregory Victor?",a="Doktor Gregory Victor leitet Hammerfalls Krankenstation als Sanitätsoffizier und Unfallchirurg. Er behandelt verwundete Wachen und Arbeiter mit unverblümter Art und beißendem Witz. Trotz Engpässen und unreparierten Belagerungsschäden hält er die Station in Betrieb.",al={"wer ist victor","gregory victor lore","hammerfall arzt"}},{q="Warum benötigt Doktor Victor Spinnenseide?",a="Doktor Victor braucht Spinnenseide, weil Hammerfalls Krankenstation kaum noch gewöhnliche Vorräte hat. Er zwirnt starke Spinnenseide aus dem Hochland zu Nähfäden, um Wunden zu schließen, wenn geeigneter Faden fehlt.",al={"warum spinnenseide","nutzung von chirurgischer spinnenseide","spinnenseidennaht"}},{q="In welchem Zustand befindet sich Hammerfall während dieser Quest?",a="Hammerfall zeigt deutliche Spuren von Vernachlässigung und Belastung. Seine Belagerungsschäden bleiben unrepariert, und Doktor Victor sieht in dieser Vernachlässigung offizielle Politik. Mit wenig Hilfe und knappen Vorräten müssen Wachen, Arbeiter und medizinisches Personal zurechtkommen.",al={"hammerfall status","warum ist hammerfall beschädigt","zustand von hammerfall"}},{q="Woher stammen die Spinnen für diese Quest?",a="Die Spinnen durchstreifen die Wildnis des Arathihochlands rund um Hammerfall. Sie müssen auf den Ebenen des Hochlands gejagt werden, um Seide für Doktor Victors Nähfäden zu sammeln, und anschließend zur Klinik gebracht werden.",al={"arathispinnen","wo man spinnenseide findet","fundort von chirurgischer spinnenseide"}},{q="Warum äußert sich Doktor Victor sarkastisch über Infektionen?",a="Doktor Victor scherzt, eine Infektion sei die geringste Sorge eines verwundeten Soldaten, wenn er ihn mit Spinnenseide näht. Sein schwarzer Humor spiegelt die Anforderungen der Versorgung an der Front wider, wo das Stillen von Blutungen und die Behandlung schwerer Wunden Vorrang vor sterilen Bedingungen haben.",al={"arzt humor","spinnenseide infektion","victor witze"}},{q="Warum sind die Vorräte in Hammerfall so knapp?",a="Hammerfall liegt isoliert in einem umkämpften Teil des Arathihochlands und ist feindlichen Bedrohungen ausgesetzt. Verstärkung und Nachschub treffen selten ein, sodass es der Garnison und der Krankenstation an Materialien, Werkzeugen und medizinischen Vorräten mangelt.",al={"warum keine vorräte","hammerfall versorgungsengpass","fehlende hilfe hammerfall"}},{q="Wen behandelt das Lazarett in Hammerfall?",a="Doktor Gregory Victors Krankenstation behandelt die in Hammerfall stationierten Arbeiter und Wachen. Sie gesund zu halten hilft dem Außenposten, trotz Gefahren und Schäden an den Bauten befestigt und funktionsfähig zu bleiben.",al={"wen behandelt victor","hammerfall patienten","klinikpatienten"}}},fp="13,181,21.353.0,26.364.0,27.407.0,29.245.0,40.200.0,50.227.0,46.198.0,47.257.0,41.226.0,43.198.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="In Tirisfal sammeln die Verlassenen Häute, um ihre Körper zusammenzuhalten. Shelene Rhobart bittet Euch, Dunkelhundfelle, Nachtsaugerflügelmembranen und Murlochaut zu bringen.",h="In Tirisfal sammeln die Verlassenen Häute, um ihre Körper zusammenzuhalten.",kw={"dunkelhundfell","nachtsaugerflügel","hides for the forsaken","shelene rhobart","tirisfal","ersatzgewebe für untote","vile fin-murloc"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr mit Euren Nähten Membranen von Wildtieren an verwesenden Körpern befestigen und Kleidungsstücke herstellen.",["race:Undead"]="Als Untoter tragt Ihr die Bürden des Daseins als Verlassener. Euren Körper zusammenzuhalten erfordert ständige Arbeit und aufgesammeltes Ersatzgewebe, keine natürliche Heilung."},sec={{t="Der Preis des Untodes",b="Das Fleisch der Verlassenen kann sich nicht selbst heilen. Wenn sie verwundet werden, fault die Wunde und bleibt offen. Deshalb nähen sie lebendes Gewebe über ihre Verletzungen, um ihre Gestalt zusammenzuhalten und ihre Leichen funktionsfähig zu halten."},{t="Besondere Materialien",b="Jede Art von Material flickt einen anderen Teil des Körpers. Dickes Dunkelhundfell hält über großflächigen Wunden fest zusammen. Nachtsaugerflügelmembranen sind dünn und biegsam, sodass sie Gesichter und Finger bedecken, ohne sie zu versteifen. Die Haut der Vile Fin-Murlocs kleidet innere Membranen und empfindliche Stellen wie Wangen und Münder aus."}},faq={{q="Warum brauchen die Verlassenen Tierhäute?",a="Die Haut der Verlassenen kann nach einer Verletzung weder heilen noch nachwachsen. Sie nehmen Häute und Membranen von lebenden Kreaturen, um Wunden zu bedecken und den Verfall zu verlangsamen.",al={"warum verlassene häute brauchen","hintergründe zur heilung von untoten","heilen untote"}},{q="Wer ist Shelene Rhobart?",a="Shelene Rhobart ist eine Lederverarbeiterin der Verlassenen in Tirisfal. Sie sammelt Häute und andere Materialien, damit die Verwundeten ihre verrottenden Körper flicken können.",al={"shelene rhobart","wer ist shelene"}},{q="Warum werden gerade Nachtsaugerflügelmembranen benötigt?",a="Nachtsaugerflügelmembranen sind dünn und geschmeidig. Sie bedecken empfindliche Stellen wie Gesichter und Finger, ohne die Haut zu dick oder steif zu machen.",al={"verwendung von nachtsaugerflügeln","warum nachtsaugerflügelmembranen"}},{q="Wofür wird Murlochaut verwendet?",a="Die Haut der Vile Fin-Murlocs kleidet innere Membranen und empfindliche Oberflächen aus, darunter die Innenseiten von Wangen und Mündern.",al={"warum murlochaut","murlochaut untote"}},{q="Wo sind diese Materialien zu finden?",a="Dunkelhunde, Nachtsauger und Vile Fin-Murlocs streifen durch Tirisfal. Dunkelhunde und Nachtsauger suchen die Wälder und Straßenränder heim, während sich Vile Fin-Murlocs an der Nordküste und an Wasserläufen im Landesinneren sammeln.",al={"woher häute bekommen","wildtiere in tirisfal"}},{q="Ist die Verwendung von Tierhäuten bei den Verlassenen üblich?",a="Ja. Die Verlassenen sind auf tierisches Gewebe und aufgesammelte Überreste angewiesen, um weiterzubestehen. Ohne Ersatzfleisch und Häute können Wunden Knochen, Organe und Muskeln freilegen.",al={"verwenden alle verlassenen häute","fleischformung der verlassenen"}}},fx={["84f1a52c"]={q="Wofür wird das Darkhound Hide verwendet?",a="Das Fleisch von Untoten heilt nicht auf natürliche Weise von Verletzungen, was die Verlassenen dazu zwingt, ihre Körper mit geernteten Tierfellen zu flicken. Während empfindliches Gewebe dünne Membranen erfordert, dienen dickere und härtere Felle wie das Darkhound Hide als dauerhafte Transplantate für breite, stark beanspruchte Oberflächen am Körper, die eine zähe, widerstandsfähige Ersatzhaut erfordern.",al={"nutzen von darkhound hide","warum darkhound hide","darkhound hide verlassene"}}},fp="22,159,20.196.0,21.301.0,38.139.0,23.147.0,51.140.0,29.108.0,32.196.0,46.166.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="In Unterstadt tanzt WRIGGLE. mit Reisenden, ermüdet dann und braucht besondere Pampe, um sich zu erholen. Nach dem Füttern folgt er einem neuen Freund.",h="In Unterstadt tanzt WRIGGLE.",kw={"canals","leicht erregbarer schleim","nahrhafte schleimpampe","schleim","pampe","unterstadt","wriggle"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr bei den örtlichen Händlern in den Kanälen von Unterstadt, der Hauptstadt der Verlassenen, die besondere Pampe erwerben.",["race:Undead"]="Als Verlassene kennt Ihr die giftigen Abwässer und die belebten Schleime in den Kanälen von Unterstadt gut. Ein Schleimbegleiter fühlt sich bei Euch zu Hause."},sec={{t="Ein tanzender Schleim",b="In Unterstadt tanzt WRIGGLE. mit freundlichen Reisenden. Der kleine Schleim ist anfangs voller Energie, ermüdet aber bald und braucht Nahrung, um wieder zu Kräften zu kommen."},{t="Nahrung aus den Canals",b="Ihr könnt Nahrhafte Schleimpampe in den ranzigen Kanälen von Unterstadt kaufen. WRIGGLE. nimmt den üblen Leckerbissen auf und gewinnt seine Energie zurück. Dann freundet er sich mit demjenigen an, der ihn gefüttert hat, und ist bereit, seinem neuen Freund zu folgen."}},faq={{q="Was ist WRIGGLE.?",a="Ihr freundet Euch mit WRIGGLE. an, indem Ihr mit dem lebhaften kleinen Schleim tanzt. Er braucht besondere Nahrung, um seine Energie aufrechtzuerhalten.",al={"wriggle quest","was ist wriggle","schleim tanzquest"}},{q="Wo findet Ihr Nahrhafte Schleimpampe?",a="Ein Händler verkauft Nahrhafte Schleimpampe in den Kanälen von Unterstadt, wo alchemistische Abfälle und Abwässer häufig vorkommen.",al={"wo pampe bekommen","nahrhafte schleimpampe händler","schleim füttern unterstadt"}},{q="Wie erregt Ihr die Aufmerksamkeit des Schleims, wenn er müde wirkt?",a="Tanzt mit dem müden oder abgelenkten Schleim, und er ahmt Eure verspielten Bewegungen nach.",al={"wie schleimaufmerksamkeit erregen","müder schleim","schleim wriggle wecken"}},{q="Warum ernährt sich der Schleim von Pampe?",a="Schleime nehmen alchemistischen Schlick und Pampe aus ihrer Umgebung auf, um stark zu bleiben und nach Anstrengungen wieder zu Kräften zu kommen.",al={"warum frisst schleim pampe","was fressen schleime"}},{q="Was geschieht, sobald der Schleim gefüttert ist?",a="Sobald er seine bevorzugte Pampe gefressen hat, freundet sich der neu belebte Schleim mit Euch an und versucht, Euch zu folgen.",al={"folgt der schleim","schleimbegleiter","wriggle belohnung"}},{q="Können Spieler der Allianz die Pampe leicht beschaffen?",a="Reisende der Allianz begeben sich beim Betreten von Unterstadt in große Gefahr. Händler in den Kanälen der Hauptstadt der Verlassenen verkaufen die Pampe.",al={"kann die allianz wriggle machen","allianz schleimpampe"}}},fp="8,133,15.156.0,26.198.0,17.107.0,42.107.0,57.80.0,34.103.0,35.92.0,46.118.0"}
P.entries["quest:976"] = {n="Nachschub für Auberdine",s="Feero Eisenhand bringt Proviant und Nachrichten von Maestras Posten nach Auberdine, und die Straße nach Norden braucht Wachen. Unruhen nahe dem Turm von Althalaxx und feindliche Infiltratoren machen die Reise unsicher.",h="Feero Eisenhand bringt Proviant und Nachrichten von Maestras Posten nach Auberdine, und die Straße nach...",kw={"eschental","auberdine","balizar the umbrage","dunkelküste","delgren der läuterer","feero eisenhand","maestras posten","sentinel starbreeze","turm von althalaxx"},ang={["faction:Alliance"]="Indem Ihr diese Route bewacht, helft Ihr, die Außenposten des Eschentals mit Auberdine verbunden zu halten und den zerbrechlichen Halt der Allianz im nördlichen Kalimdor zu bewahren.",["race:Human"]="Als Mensch seht Ihr, wie Feero Eisenhand die Bereitschaft Eures Volkes zeigt, verbündete Kaldorei in fremden, gefährlichen uralten Wäldern zu unterstützen.",["race:NightElf"]="Die Vorräte und Nachrichten, die Ihr nach Norden geleitet, helfen den Sentinels in Auberdine gegen die wachsende Dunkelheit an der Dunkelküste und entlang der Grenze des Eschentals."},sec={{t="Gefährlicher Weg nach Norden",b="Maestras Posten liegt an der westlichen Grenze des Eschentals, zwischen dem Wald und der Dunkelküste. Nach Untersuchungen finsterer Aktivitäten nahe dem Turm von Althalaxx schickt Delgren der Läuterer Vorräte und Aufklärungsberichte an Sentinel Starbreeze in Auberdine. Der Außenposten vertraut bewaffnetem Geleit mehr als einzelnen Kurieren, deshalb reist Feero Eisenhand mit Wachen über die Waldstraße."},{t="Schatten am Wegesrand",b="Feero Eisenhands Reise nach Norden führt ihn durch Wälder, in denen Hinterhalte seine Lieferung bedrohen. Kultisten des Dark Strand wollen Berichte über ihre dämonischen Rituale unterdrücken. Späher der Verlassenen schleichen durchs Unterholz, und Balizar the Umbrage, Aligar the Tormentor und Caedakar the Vicious versuchen jeweils, die Karawane vor der Grenze niederzumachen."}},faq={{q="Wer ist Feero Eisenhand?",a="Feero Eisenhand ist ein menschlicher Kurier bei Maestras Posten im westlichen Eschental. Delgren der Läuterer vertraut ihm Nachrichten und Vorräte für Auberdine an, und Feero reist nicht ohne fähige Leibwächter.",al={"feero","feero eisenhand hintergrund","wer ist der zwerg bei der eskorte"}},{q="Warum braucht Auberdine diese Vorräte?",a="Die Dunkelküste und das nördliche Eschental sind wachsender Verderbnis und Bedrohungen durch dämonische Kultisten nahe dem Turm von Althalaxx ausgesetzt. Die nachtelfischen Sentinels in Auberdine unter der örtlichen Führung von Sentinel Starbreeze brauchen Proviant und aktuelle Aufklärungsberichte, um die Küste zu verteidigen.",al={"warum vorräte nach auberdine schicken","auberdine vorräte","sentinel starbreeze"}},{q="Wer greift Feero unterwegs an?",a="Feero warnt, dass gefährliche Feinde durch den Wald streifen, und bittet um Wachen. Wer sie sind, wird während der Eskorte klar.",al={"wer überfällt feero","feeros angreifer","wer greift unterwegs an"}},{q="Welche Verbindung besteht zum Turm von Althalaxx?",a="Delgren der Läuterer leitet die Bemühungen, die dunklen Rituale der Kultisten am Turm von Althalaxx aufzudecken und zu stören. Diese Eskorte geht aus jener Untersuchung hervor und bringt Aufklärungsberichte und Unterstützung zur Führung der Nachtelfen in Auberdine.",al={"althalaxx verbindung","turm von althalaxx","delgren verbindung"}},{q="Bei wem erstatte ich Bericht, nachdem ich Feero beschützt habe?",a="Nachdem Ihr Feero sicher durch die Hinterhalte im Eschental geführt habt, erstattet Delgren dem Läuterer bei Maestras Posten Bericht und bestätigt die erfolgreiche Lieferung.",al={"nachschub für auberdine abgeben","wohin nach feeros eskorte","quest abgeben"}}},fx={["1813fb85"]={q="Warum möchte Feero Eisenhand diese Vorräte ausliefern?",a="Delgren der Läuterer beauftragte Feero damit, wichtige Vorräte und lebenswichtige Nachrichten nach Norden an Sentinel Starbreeze in Auberdine zu liefern. Dunkle Mächte und Kultisten, die mit finsteren Plänen infiziert sind, operieren im gesamten westlichen Eschental, und Feero weiß, dass es für die Verteidigung der Allianz verheerend sein könnte, wenn diese sensiblen Kommunikationen oder Proviante in feindliche Hände fallen würden.",al={"feero eisenhands beweggrund","warum braucht feero hilfe","warum vorräte nach auberdine"}},affb8fb0={q="Warum bittet Feero Eisenhand Euch um Schutz anstatt die Wachen des Postens?",a="Feero reist nur ungern allein, während er wichtige Vorräte und Nachrichten durch das gefährliche Eschental trägt. Er bittet um Leibwächter, um der Lieferung zu helfen, Auberdine sicher zu erreichen.",al={"warum ich feero","warum braucht feero geleitschutz","warum geht feero nicht allein"}}},fp="21,199,21.359.0,23.343.1,22.201.0,39.255.0,33.117.0,49.232.0,41.145.0"}
P.entries["quest:97663"] = {n="Supplies and Studies",s="In Kargath sollt Ihr für Mus'hale gestohlene Vorräte bergen und Steingravuren im Staubbecken abreiben. Die Gravuren sind das Studienmaterial, das Mus'hale bei einem Angriff naher Oger verlor.",h="In Kargath sollt Ihr für Mus'hale gestohlene Vorräte bergen und Steingravuren im Staubbecken abreiben.",kw={"das staubbecken","kargath","mushale","oger","abreibungen","gestohlene vorräte","steingravuren"},sec={{t="Verlorene Materialien",b="Mus'hale erholt sich im Gasthaus von Kargath, nachdem nahe Oger den Gelehrten im Staubbecken überwältigt hatten. Vor dem Angriff hatte Mus'hale ungewöhnliche Felsen mit Gravuren gefunden und Abreibungen davon zum Studieren angefertigt. Nun sind der Rucksack und diese Aufzeichnungen verschwunden, daher sollt Ihr im Osten suchen und neue Abreibungen der Gravuren anfertigen."}},faq={{q="Wer ist Mus'hale?",a="Mus'hale ist ein Gelehrter, der gravierte Felsen im Staubbecken gefunden und Abreibungen davon zum Studieren angefertigt hat.",al={"mushale","wer ist mushale","hintergrund zu mushale"}},{q="Was ist mit Mus'hales Vorräten geschehen?",a="Nahe Oger griffen Mus'hale im Staubbecken an, und Mus'hale erwachte ohne den Rucksack unter der Obhut des Gastwirts.",al={"gestohlene vorräte","wo ist mushales rucksack","oger stahlen den rucksack"}},{q="Was soll ich für Mus'hale finden?",a="Mus'hale bittet Euch, im Osten nach dem gestohlenen Rucksack zu suchen und Abreibungen der nahen Steingravuren anzufertigen.",al={"quest vorräte und studien","wonach soll ich suchen","abreibungen finden"}},{q="Wo sind die gravierten Felsen?",a="Die ungewöhnlichen gravierten Felsen befinden sich im Staubbecken.",al={"gravuren im staubbecken","wo sind die felsen","steingravuren"}},{q="Wohin soll ich zurückkehren, um Mus'hale aufzusuchen?",a="Mus'hale ist in Kargath und erholt sich unter der Obhut des Gastwirts.",al={"zu mushale zurückkehren","wo ist mushale","gasthaus von kargath"}}},fp="20,186,14.307.0,16.88.0,37.110.0,35.100.0,28.45.0,30.62.0"}
P.entries["quest:97884"] = {n="Armory of Sunnyglade",s="Jemand bittet Euch, einen Schmiedekunst-Folianten aus Sonnengrund in den Flusslanden zu bergen. Sein Titel verbindet ihn mit der Familie Tremayne.",h="Jemand bittet Euch, einen Schmiedekunst-Folianten aus Sonnengrund in den Flusslanden zu bergen.",kw={"rüstkammer von sonnengrund","schmiedetechniken","flusslande","sonnengrund","foliant","familie tremayne"},sec={{t="Ein Familienfoliant",b="In Sonnengrund, in den Flusslanden, bittet man Euch, ein Buch über die Schmiedetechniken der Familie Tremayne zu bergen. Im Mittelpunkt steht der Foliant selbst; wo er sich in Sonnengrund befindet, ist weiterhin die entscheidende Frage."}},faq={{q="Wonach suche ich?",a="Ihr sucht den Folianten über die Schmiedetechniken der Familie Tremayne.",al={"welcher folianten","schmiedebuch","tremayne-foliant"}},{q="Wo ist der Foliant?",a="Der Foliant wird in Sonnengrund, in den Flusslanden, gesucht.",al={"wo zu finden","foliant sonnengrund","standort der rüstkammer"}},{q="Wer ist die Familie Tremayne?",a="Der Titel ordnet die Schmiedetechniken der Familie Tremayne zu.",al={"familie tremayne","wer sind die tremaynes"}}},fp="20,126,13.218.0,22.73.0,18.53.0,27.75.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="In Unterstadt trägt ein Kurier Alessandros Gebräu über den Schleimkanal, bevor es verdirbt. Die Lieferung muss das Apothekarium rechtzeitig erreichen.",h="In Unterstadt trägt ein Kurier Alessandros Gebräu über den Schleimkanal, bevor es verdirbt.",kw={"alessandro","das apothekarium","doctor martin felben","prompt potion runner","royal apothecary society","schleimkanal","unterstadt","instabiler trank"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Verlassenen bei gefährlichen alchemistischen Arbeiten in Unterstadt helfen, wo Reisende giftige Schleimkanäle überqueren müssen.",["race:Undead"]="Als Untoter wisst Ihr, dass brüchige Gelenke und verfallende Knie wichtige Laborarbeiten der Royal Apothecary Society behindern können."},sec={{t="Ein Wettlauf gegen Verfall",b="Alessandro braucht einen schnellen Kurier in den unterirdischen Gängen von Unterstadt. Der Alchemist der Verlassenen hat ein instabiles Gebräu hergestellt, das bald verderben wird. Seine untoten Gelenke sind zu gebrechlich, um den giftigen Schleimkanal zu überqueren, also bringt Ihr es unversehrt hinüber, bevor es zu nutzlosem Schlamm wird."},{t="Die Anforderungen des Apothekariums",b="Doctor Martin Felben wartet im Apothekarium auf das Gebräu, das er für seine laufenden Forschungen braucht. Er sagt, die sechs Tränke, die Alessandro zuvor geschickt hat, seien unterwegs instabil geworden. Eine rechtzeitige Lieferung lässt den Doktor seine düsteren Experimente ohne Unterbrechung fortsetzen. Das instabile Gebräu und Alessandros gebrechliche Gelenke zeigen die Gefahren der Alchemie der Verlassenen und des Untods."}},faq={{q="Wer vergibt diese Quest?",a="Alessandro in Unterstadt braucht Euch, um die Lieferung zu überbringen. Seine untoten Knie springen heraus und klappern, wenn er zu rennen versucht, deshalb kann er nicht selbst über den Schleimkanal eilen.",al={"wer vergibt prompt potion runner","wer startet prompt potion runner","wer ist alessandro"}},{q="Wohin muss der Trank gebracht werden?",a="Bringt den Trank zu Doctor Martin Felben ins Apothekarium in Unterstadt, wo er alchemistische Experimente durchführt.",al={"wohin muss der trank","wer ist doctor martin felben","prompt potion runner abgeben"}},{q="Warum gibt es ein Zeitlimit für die Lieferung?",a="Das Gebräu ist instabil und nur sehr kurz haltbar. Bringt es schnell über den Kanal, sonst wird es instabil und unbrauchbar.",al={"warum zeitlimit","haltbarkeit des instabilen tranks","warum eilen"}},{q="Sind andere Lieferversuche gescheitert?",a="Doctor Martin Felben sagt, die sechs Tränke, die Alessandro zuvor zu schicken versuchte, seien instabil geworden, bevor sie das Apothekarium erreichten.",al={"sind andere kuriere gescheitert","alessandros frühere versuche","wie viele tränke wurden unbrauchbar"}},{q="Warum kann Alessandro den Trank nicht selbst liefern?",a="Alessandro sagt, seine Knie klappern und springen heraus, sobald er zu rennen versucht. Diese Folgen des Untods hindern ihn daran, die Lieferung selbst eilig zu überbringen.",al={"warum kann alessandro nicht selbst liefern","alessandros knie"}},{q="Was sind Doctor Felbens Experimente?",a="Doctor Martin Felben ist ein Apotheker, der im Apothekarium Experimente durchführt. Die genaue Formel bleibt im Dunkeln, und er nimmt seine Forschungen wieder auf, sobald die stabile Mischung eintrifft.",al={"was macht doctor felben","wofür wird der trank verwendet"}}},fp="20,141,20.272.0,26.371.0,21.164.0,33.115.0,26.136.0,36.129.0,48.139.0,37.179.0"}
P.entries["quest:97894"] = {n="Business in Auberdine",s="In Sturmwind wartet Borgus Steelhand auf Nachricht von seinem Bruder Gorbold in Auberdine. Ihr erreicht Gorbold, indem Ihr vom Hafen von Sturmwind nach Westen ins nördliche Kalimdor segelt.",h="In Sturmwind wartet Borgus Steelhand auf Nachricht von seinem Bruder Gorbold in Auberdine.",kw={"auberdine","borgus steelhand","business in auberdine","dunkelküste","gorbold stahlhand","händler","steelhand","hafen von sturmwind"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr direkt zwischen dem Hafen von Sturmwind und Auberdine segeln und so das Menschenkönigreich mit den Ländern der Kaldorei im nördlichen Kalimdor verbinden.",["race:Dwarf"]="Als Zwerg könnt Ihr Zwergenhändler wie die Mitglieder der Familie Steelhand weit jenseits der Berge von Khaz Modan handeln sehen, selbst in den stillen, schattigen Siedlungen der Nachtelfen."},sec={{t="Ein Zwerg fern der Heimat",b="Gorbold überquerte das große Meer, um einen Händlerstand in Auberdine zu betreiben. Er hoffte, mit der Versorgung von Schiffen, die die Dunkelküste anlaufen, Gewinn zu machen. Seit Wochen fehlt jede Nachricht, und Borgus sorgt sich um seinen Bruder, der so weit von Eisenschmiede und Sturmwind entfernt ist."},{t="Die Hafenüberfahrt",b="Die Überfahrt nach Kalimdor führte einst über den Hafen von Menethil oder neutrale Goblinhäfen wie Beutebucht. Borgus schickt Euch zu dem Schiff am südlichsten Steg im Hafen von Sturmwind. Seine direkte Überfahrt endet an Auberdines langen Holzpiers."}},faq={{q="Wer ist Borgus Steelhand?",a="Borgus Steelhand ist ein Zwergenhändler in Sturmwind. Seine Familie ist für fairen Handel bekannt, und er sucht Reisende, die seinem Bruder Gorbold jenseits des Meeres Nachricht bringen.",al={"borgus steelhand","wer vergibt business in auberdine","borgus"}},{q="Wo befindet sich Gorbold Stahlhand?",a="Gorbold Stahlhand ist in Auberdine, der wichtigsten Hafensiedlung der Dunkelküste an Kalimdors Nordwestküste. Er arbeitet an einem Händlerstand, der ankommende Schiffe versorgt.",al={"wo ist gorbold","gorbold stahlhand finden","gorbold standort"}},{q="Wie erreicht Ihr Auberdine von Sturmwind aus?",a="Ein Schiff fährt vom südlichsten Steg im Hafen von Sturmwind über das große Meer zu Auberdines Anlegestellen an der Dunkelküste.",al={"schiff nach auberdine","wie von sturmwind zur dunkelküste gelangen","schiff von sturmwind nach auberdine"}},{q="Warum sorgt sich Borgus um seinen Bruder?",a="Gorbold brach vor Wochen auf, um an einem Händlerstand in Auberdine zu arbeiten und mit der Versorgung von Schiffen Gewinn zu machen. Er hat keine Nachricht nach Hause geschickt, deshalb bittet Borgus Reisende, herauszufinden, wie es ihm geht.",al={"warum nach gorbold sehen","was ist mit gorbold passiert"}},{q="Was für eine Siedlung ist Auberdine?",a="Auberdine ist eine Küstensiedlung an der Dunkelküste, die hauptsächlich von Nachtelfen erbaut wurde und bewohnt wird. Sie ist der wichtigste Schifffahrtsknotenpunkt und Fährhafen der Allianz zwischen dem nördlichen Kalimdor und Teldrassil.",al={"was ist auberdine","auberdine ort"}},{q="Wofür ist die Familie Steelhand bekannt?",a="Die Familie Steelhand ist für ihren Handel bekannt und behauptet, Reisenden und Hafenarbeitern faire Geschäfte anzubieten.",al={"familie steelhand","steelhands"}}},fp="21,164,21.234.0,18.230.0,24.166.0,35.156.0,42.116.0,40.175.0,37.190.0,39.100.0"}
P.entries["quest:97899"] = {n="Camping 101: Alchemy",s="Ein Alchemist in Orgrimmar kann lernen, einen Manabrunnen für ein Lager herzustellen. Er bietet Heilern und Zauberwirkern einen erfrischenden Trunk, doch zum Aufstellen braucht es ein Lagerfeuer.",h="Ein Alchemist in Orgrimmar kann lernen, einen Manabrunnen für ein Lager herzustellen.",kw={"alchemist","alchemie","lagerfeuer","lagern","heiler","manabrunnen","orgrimmar","zauberwirker","whuut"},sec={{t="Ein Brunnen fürs Lager",b="Jemand in Orgrimmar bittet Euch, mit Whuut zu sprechen, sobald Ihr Euer Geschick in der Alchemie bewiesen habt. Whuut kann Euch beibringen, einen Manabrunnen herzustellen, einen Lagergegenstand, der Heiler und Zauberwirker auf der Suche nach Erfrischung anzieht. Um in der Wildnis ein Lager aufzuschlagen, braucht Ihr außerdem ein Lagerfeuer. Ein Kochkunstlehrer kann Euch beibringen, wie Ihr eines entfacht."}},faq={{q="Wer kann mir beibringen, einen Manabrunnen herzustellen?",a="Whuut in Orgrimmar kann Euch beibringen, einen Manabrunnen herzustellen, sobald Ihr Euer Können in der Alchemie bewiesen habt.",al={"manabrunnen lehrer","whuut alchemie","wer ist whuut"}},{q="Was bewirkt ein Manabrunnen?",a="Ein Manabrunnen ist ein Lagergegenstand, der Heilern und Zauberwirkern einen erfrischenden Trunk bietet.",al={"manabrunnen verwendung","was ist ein manabrunnen","lager mana"}},{q="Kann ich in der Stadt ein Lager aufschlagen?",a="Die meisten Leute mögen keine Lager mitten in der Stadt, daher verweist Euch der Abschlusstext in die Wildnis, um Euren Manabrunnen auszuprobieren.",al={"lager in orgrimmar","manabrunnen stadt","lagern in der stadt"}},{q="Was brauche ich sonst noch für ein Lager?",a="Ein Lagerfeuer wird als Grundlage für ein Lager benötigt. Ein Kochkunstlehrer kann Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","lager aufschlagen","feuer fürs lager"}}},fp="20,165,15.310.0,37.97.0,25.89.0,26.146.0,31.89.0"}
P.entries["quest:97900"] = {n="Camping 101: Blacksmithing",s="In Klingenhügel kann Dwukk Euch ein Lagerhandwerk passend zu Euren Schmiedekunstfertigkeiten beibringen. Mit einem Schleifstein können Kämpfer in der Nähe ihre Waffen schärfen.",h="In Klingenhügel kann Dwukk Euch ein Lagerhandwerk passend zu Euren Schmiedekunstfertigkeiten beibringen.",kw={"schmiedekunst","lagerfeuer","lagern","dwukk","klingenhügel","schurken","schleifstein","waffen"},ang={["class:Rogue"]="Als Schurke könnt Ihr Eure Waffen an einem Schleifstein schärfen, der in einem Lager in der Nähe aufgestellt ist.",["profession:Blacksmithing"]="Als Schmied könnt Ihr von Dwukk lernen, einen Schleifstein für ein Lager in der Wildnis herzustellen."},sec={{t="Ein Lagerhandwerk",b="Dwukk bringt Euch bei, einen Schleifstein herzustellen, sobald Ihr Euch in der Schmiedekunst bewährt habt. Stellt ihn in einem Lager in der Wildnis auf, wo Kämpfer und Schurken in der Nähe ihre Waffen schärfen können.\n\nUm Euer Lager aufzuschlagen, braucht Ihr ein Lagerfeuer. Köche können Euch beibringen, wie Ihr eines macht."}},faq={{q="Wer bringt mir bei, einen Schleifstein herzustellen?",a="Dwukk in Klingenhügel bringt Euch bei, einen Schleifstein herzustellen, sobald Ihr Euch in der Schmiedekunst bewährt habt.",al={"schleifstein lehrer","dwukk schmiedekunst","wer lehrt lagerhandwerk für schmiede"}},{q="Was bewirkt der Schleifstein?",a="Kämpfer und Schurken in der Nähe können einen Schleifstein in Eurem Lager nutzen, um ihre Waffen zu schärfen.",al={"schleifstein benutzen","wozu dient der schleifstein","waffen im lager schärfen"}},{q="Wo kann ich mein Lager ausprobieren?",a="Probiert Euer Lager in der Wildnis aus. Lager sollten nicht mitten im Ort aufgeschlagen werden.",al={"wo lager aufschlagen","lagerplatz","lager im ort"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Um Euer Lager aufzuschlagen, braucht Ihr ein Lagerfeuer, und Köche können Euch beibringen, wie Ihr eines macht.",al={"lagerfeuer nötig","wie lager aufschlagen","feuer fürs lager"}}},fp="26,153,12.250.0,42.97.0,34.89.0,28.86.0,21.85.0"}
P.entries["quest:97901"] = {n="Camping 101: Enchanting",s="Ihr könnt eine Verzauberte Laute herstellen, aber die Stadtbewohner mögen keine Lager in Stadtzentren. Um in der Wildnis ein Lager aufzuschlagen, braucht Ihr ein Feuer.",h="Ihr könnt eine Verzauberte Laute herstellen, aber die Stadtbewohner mögen keine Lager in Stadtzentren.",kw={"lagerfeuer","lagern","kochen","verzauberte laute","feuer","wildnis"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, ein Feuer als Grundlage für ein Lager zu entfachen."},sec={{t="Zuerst ein Lagerfeuer",b="Ein Lagerfeuer bildet die Grundlage für Euer Lager. Die meisten Köche können Euch zeigen, wie Ihr eines entfacht, also sucht einen Kochkunstlehrer auf, wenn Ihr die Grundlagen noch nicht gelernt habt."}},faq={{q="Was kann ich herstellen?",a="Ihr könnt eine Verzauberte Laute herstellen.",al={"verzauberte laute","laute herstellen","laute fürs lager"}},{q="Wo kann ich sie ausprobieren?",a="Ihr müsst in die Wildnis gehen, um sie auszuprobieren. Die meisten Leute mögen keine Lager in Stadtzentren.",al={"wo lagern","lagerplatz","laute ausprobieren"}},{q="Warum brauche ich ein Lagerfeuer?",a="Euer Lager beginnt mit einem Lagerfeuer.",al={"lagerfeuer nötig","lagerfeuer","feuer fürs lager"}},{q="Wer kann mir beibringen, ein Feuer zu entfachen?",a="Die meisten Köche können Euch beibringen, ein Feuer zu entfachen. Fragt einen Kochkunstlehrer, wenn Ihr die Grundlagen noch nicht gelernt habt.",al={"feuermachen lernen","kochkunstlehrer","lagerfeuer entfachen"}}},fp="23,127,16.148.0,17.32.0,23.93.0,25.33.0,32.98.0"}
P.entries["quest:97902"] = {n="Camping 101: Engineering",s="Ein Lehrer verweist Euch an Mukdrak in Klingenhügel, der Euch nach einem Beweis Eurer Ingenieurskunst beibringen kann, einen Materialbot herzustellen. Der Bot hilft dabei, ein Lager mit Materialien für Zauber zu versorgen.",h="Ein Lehrer verweist Euch an Mukdrak in Klingenhügel, der Euch nach einem Beweis Eurer Ingenieurskunst...",kw={"lager","lagerfeuer","camping 101","ingenieurskunst","mukdrak","klingenhügel","materialbot"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr lernen, einen Materialbot für Euer Lager herzustellen, nachdem Ihr Euer Können unter Beweis gestellt habt."},sec={{t="Ein Bot fürs Lager",b="Ein Ingenieur kann bei Mukdrak in Klingenhügel lernen, einen Materialbot herzustellen, sobald Ihr Euer Können unter Beweis stellt. Der Automat hilft dabei, Euch und Eure Verbündeten mit Materialien zu versorgen, die für Zauber benötigt werden. Um ihn im Lager auszuprobieren, begebt Euch in die Wildnis; die Stadtbewohner dulden keine Lager mitten in der Stadt."},{t="Das Feuer vorbereiten",b="Ein Lager benötigt außerdem ein Lagerfeuer, bevor es aufgeschlagen werden kann. Die meisten Köche können Euch beibringen, eines zu entfachen, also könnt Ihr jemanden aufsuchen, der Köche ausbildet, wenn Ihr die Grundlagen lernen müsst."}},faq={{q="Wer bringt mir bei, einen Materialbot herzustellen?",a="Mukdrak in Klingenhügel kann Euch beibringen, einen Materialbot herzustellen, nachdem Ihr Euer Können in der Ingenieurskunst unter Beweis gestellt habt.",al={"mukdrak bot","wer lehrt materialbot","materialbot lehrer"}},{q="Was macht der Materialbot?",a="Der Materialbot hilft dabei, Euch und Eure Verbündeten mit Materialien zu versorgen, die für Zauber benötigt werden.",al={"was macht bot","materialbot verwendung","bot fürs lager"}},{q="Wo sollte ich mein Lager aufschlagen?",a="Der Abschlusstext rät dazu, sich in die Wildnis zu begeben, um den Bot auszuprobieren, da die meisten Leute Lager mitten in der Stadt nicht mögen.",al={"lager wo","lagerplatz","wo bot testen"}},{q="Was brauche ich noch, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Die meisten Köche können Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","lager aufschlagen","feuer fürs lager"}},{q="Wer kann mir die Grundlagen des Lagerfeuermachens beibringen?",a="Jemand, der Köche ausbildet, kann Euch die Grundlagen des Lagerfeuermachens beibringen.",al={"lagerfeuer lehrer","feuermachen lernen","kochfeuer"}}},fp="24,189,14.300.0,14.164.0,37.101.0,29.91.0,30.131.0,43.84.0,49.71.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="In Rawrks Lager in Klingenhügel lernen kundige Reisende, eine Verbandtasche für die Wildnis herzustellen. Die Lektion behandelt die Wahl des Lagerplatzes und die Bedeutung eines Feuers.",h="In Rawrks Lager in Klingenhügel lernen kundige Reisende, eine Verbandtasche für die Wildnis herzustellen.",kw={"lagerfeuer","camping 101","durotar","verbandtasche","rawrk","klingenhügel","überleben","wildnislager"},ang={["faction:Horde"]="Als Reisende der Horde könnt Ihr diese Ausbildung in Klingenhügel in Durotar erhalten, um Euch in Kalimdors rauen Grenzgebieten selbst zu versorgen.",["profession:Cooking"]="Da Ihr Cooking beherrscht, wisst Ihr, dass zum Lagerbau Feuer gehört. Rawrk sagt, ein richtiges Lager brauche ein Feuer, und das Feuermachen lehren Kochlehrer."},sec={{t="Überleben an der Grenze",b="Rawrk in Klingenhügel lehrt kundige Reisende, eine Verbandtasche herzustellen. Damit könnt Ihr Wunden fernab von Apothekern oder Krankenstationen versorgen, wo Hilfe womöglich schwer zu finden ist."},{t="Die Kunst des Lagerfeuers",b="Rawrk warnt Euch davor, mitten in Klingenhügel oder einer anderen Siedlung ein Zelt aufzuschlagen. Sucht stattdessen einen offenen Platz in der Wildnis. Ein Lager braucht auch ein Feuer, das Euch durch die Nacht hilft. Lernt bei einem Kochlehrer die Grundlagen des Feuermachens, bevor Ihr aufbrecht."}},faq={{q="Wer ist Rawrk und wo ist er zu finden?",a="Rawrk lehrt in Klingenhügel in Durotar, wie man ein Lager zum Überleben errichtet. Er zeigt kundigen Reisenden, wie sie Verbandtaschen für die Wildnis herstellen.",al={"wer lehrt camping erste hilfe","wo ist rawrk","camping 101 lehrer"}},{q="Was ist erforderlich, bevor man ein Wildnislager aufschlägt?",a="Wählt einen offenen Platz in der Wildnis und entfacht ein ordentliches Lagerfeuer. Rawrk warnt davor, innerhalb der Ortsgrenzen zu lagern, und rät Euch, zuerst bei einem Kochlehrer das Feuermachen zu lernen.",al={"was brauche ich zum campen","wie man ein lager aufschlägt","lagerfeuer anforderung camping"}},{q="Können Lager innerhalb von Städten oder Siedlungen aufgeschlagen werden?",a="Nein. Die Bewohner haben etwas gegen Zelte mitten in ihren Siedlungen, also sucht für Euer Lager einen offenen Platz in der Wildnis.",al={"kann ich in klingenhügel campen","campen in städten","wo kann ich mein lager aufschlagen"}},{q="Was lernen Abenteurer durch diese Ausbildung herzustellen?",a="In der Ausbildung lernt Ihr, eine eigene Verbandtasche herzustellen, um auf Reisen durch die Wildnis Wunden zu versorgen.",al={"camping 101 first aid belohnung","welchen gegenstand lehrt dies","verbandtasche herstellung"}},{q="Warum empfiehlt Rawrk, Kochen zu lernen?",a="Ein richtiges Lager braucht ein Feuer. Kochlehrer vermitteln die Grundlagen des Feuermachens, daher empfiehlt Rawrk, vor Eurem Aufbruch bei einem von ihnen zu lernen.",al={"warum brauche ich kochen zum campen","kochen lagerfeuer camping"}},{q="Welche Voraussetzungen sind erforderlich, bevor man dieses Handwerk erlernt?",a="Ihr müsst Grundkenntnisse in der Wundversorgung und im Überleben nachweisen, bevor Rawrk Euch lehrt, eine Verbandtasche für unterwegs herzustellen.",al={"voraussetzungen für camping 101 first aid","benötigte fertigkeit für camping erste hilfe"}}},fp="22,154,24.169.0,23.254.0,35.130.0,53.177.0,49.108.0,51.100.0,42.129.0,57.121.0"}
P.entries["quest:97904"] = {n="Camping 101: Fishing",s="In Eurem Lager kann Angeln Euch und Euren Gefährten Behaglichkeit schenken. Nahe Sen'jin kann Lau'Tiki Euch beibringen, ein Fischglas herzustellen.",h="In Eurem Lager kann Angeln Euch und Euren Gefährten Behaglichkeit schenken.",kw={"lagerausstattung","lagern","fischglas","angler","angeln","lau'tiki","sen'jin"},ang={["profession:Cooking"]="Als Angler könnt Ihr lernen, ein Fischglas für Euer Lager herzustellen, sobald Ihr Euch beim Angeln bewährt habt."},sec={{t="Behaglichkeit im Lager",b="Sobald Ihr Euch beim Angeln bewährt habt, sprecht mit Lau'Tiki nahe Sen'jin. Lau'Tiki kann Euch beibringen, ein Fischglas herzustellen, eine Lagerausstattung, die Euch und Euren Mitabenteurern Freude bereiten soll. Ein glücklicheres Lager, so hofft der Schenkende, sorgt für stärkere Kämpfer."}},faq={{q="Was kann Angeln für mein Lager tun?",a="Eure Angelfertigkeit kann Euch helfen, die Herstellung eines Fischglases für Euer Lager zu erlernen.",al={"angelgegenstand fürs lager","lagern angeln"}},{q="Wer bringt mir bei, ein Fischglas herzustellen?",a="Lau'Tiki nahe Sen'jin kann Euch beibringen, ein Fischglas herzustellen, sobald Ihr Euch beim Angeln bewährt habt.",al={"fischglas lehrer","lau'tiki angeln"}},{q="Wozu dient das Fischglas?",a="Das Fischglas ist eine Lagerausstattung, die Euch und Euren Mitabenteurern Freude bereiten soll.",al={"fischglas verwendung","lager fischausstattung"}},{q="Wo finde ich Lau'Tiki?",a="Lau'Tiki befindet sich nahe Sen'jin.",al={"lau'tiki standort","sen'jin angeln"}}},fp="20,133,14.259.0,32.72.0,35.101.0,26.89.0,26.33.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="In Camping 101: Herbalism lernt Ihr, Räucherkerzen aus wilden Pflanzen herzustellen. Doch zunächst braucht ein ordentliches Lager ein Feuer, und Euer Lagerplatz gehört in die Wildnis außerhalb der Stadt.",h="In Camping 101: Herbalism lernt Ihr, Räucherkerzen aus wilden Pflanzen herzustellen.",kw={"lager","lagerfeuer","lagern","kochen","kräuterkunde","räucherkerze","wildnis"},ang={["profession:Cooking"]="Als Koch lernt Ihr, das Lagerfeuer zu entfachen, das die Mitte jedes Lagers bildet.",["profession:Herbalism"]="Als Kräuterkundiger lernt Ihr, aus gesammelten Pflanzen Räucherkerzen für Lager in der Wildnis herzustellen."},sec={{t="Duftendes Handwerk der Wildnis",b="Mit Kräuterkunde könnt Ihr gesammelte Pflanzen zu Räucherkerzen verarbeiten, die unterwegs für Behaglichkeit sorgen. Stadtbewohner missbilligen Zelte auf den Straßen der Stadt, daher sind diese Kerzen für Lager außerhalb bewachter Siedlungen gedacht."},{t="Das Herz des Lagers",b="Ein Lagerfeuer gehört in die Mitte jedes Lagers. Entfacht eines, bevor Ihr eine Räucherkerze verwendet. Kräuterkundige sorgen für den duftenden Rauch, während Kochlehrer im ganzen Land Reisenden die Grundlagen des Feuermachens beibringen."}},faq={{q="Was ist eine Räucherkerze?",a="Kräuterkundige stellen Räucherkerzen aus wilden Pflanzen her. Zündet eine in einem Lager in der Wildnis neben einem Lagerfeuer an.",al={"was ist eine räucherkerze","räucherkerze verwenden","lagergegenstand kräuterkunde"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Ihr könnt in der freien Wildnis ein Lager aufschlagen. Stadtbewohner wehren sich gegen Zelte, die sich auf den Durchgangsstraßen der Stadt ausbreiten.",al={"wo ein lager aufschlagen","lagern in der stadt möglich","lagern in städten"}},{q="Warum braucht Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ein Lager braucht ein Lagerfeuer in seiner Mitte. Kochlehrer in ganz Azeroth vermitteln grundlegende Techniken des Feuermachens.",al={"wie ein lagerfeuer entfachen","lagerfeuer für lager nötig","koch lagerfeuer lagern"}},{q="Wer lehrt das Entfachen eines Lagerfeuers?",a="Kochlehrer bringen Euch bei, ein einfaches Lagerfeuer zu entfachen. Lernt die Grundlagen des Kochens, bevor Ihr in die Wildnis aufbrecht.",al={"wer lehrt lagerfeuer","feuermachen lernen","kochlehrer feuer"}},{q="Was hat Kräuterkunde mit dem Lagern zu tun?",a="Kräuterkunde liefert die Pflanzen und Harze für Räucherkerzen. In der Wildnis gesammelt, bringen sie wohltuende Düfte in Euer Lager.",al={"verbindung zwischen kräuterkunde und lagern","warum kräuterkunde zum lagern","was liefert kräuterkunde für lager"}},{q="Braucht Ihr ein Lagerfeuer, um eine Räucherkerze zu verwenden?",a="Ein Lager braucht ein ordentliches Lagerfeuer. Entfacht eines, bevor Ihr es Euch gemütlich macht und eine Räucherkerze verwendet.",al={"räucherkerze ohne feuer anzünden möglich","räucherkerze lagerfeuer voraussetzung"}}},fp="22,177,26.201.0,25.216.0,26.103.0,28.103.0,44.107.0,35.114.0,36.131.0,48.86.0"}
P.entries["quest:97906"] = {n="Camping 101: Leatherworking",s="In Orgrimmar kann Karolek Euch lehren, ein Zelt für Lederverarbeiter herzustellen, sobald Ihr Euer berufliches Können bewiesen habt. Ein Zelt bietet auf Euren Reisen Schutz, doch um ein Lager aufzuschlagen, braucht Ihr auch ein Lagerfeuer.",h="In Orgrimmar kann Karolek Euch lehren, ein Zelt für Lederverarbeiter herzustellen, sobald Ihr Euer...",kw={"lagerfeuer","grundlagen des lagerns","lagergegenstand","kochkunst","karolek","lederverarbeitung","orgrimmar","zelt"},ang={["profession:Cooking"]="Als Koch könnt Ihr lernen, das Lagerfeuer zu entzünden, das ein Lager vollständig macht."},sec={{t="Ein Platz fürs Lager",b="Ein Lederverarbeiter in Orgrimmar verweist Euch an Karolek, der Euch lehren kann, ein Zelt für Eure Reisen herzustellen. Es spendet an heißen Tagen Schatten und schützt vor Regen, sodass Ihr unterwegs einen Platz zum Ausruhen habt. Sobald Ihr Euer Können in der Lederverarbeitung bewiesen habt, kann Karolek Euch lehren, diesen Lagergegenstand herzustellen."},{t="Zuerst das Lagerfeuer",b="Euer Zelt ist bereit, doch erst ein Lagerfeuer macht das Lager vollständig. Köche können Euch lehren, eines zu entzünden, und ein Kochkunstlehrer kann Euch die Grundlagen zeigen. Um Euer Zelt auszuprobieren, verlasst das Stadtzentrum und schlagt es in der Wildnis auf."}},faq={{q="Wer kann mich lehren, ein Zelt für Lederverarbeiter herzustellen?",a="Karolek in Orgrimmar kann Euch lehren, ein Zelt herzustellen, nachdem Ihr Euer Können in der Lederverarbeitung bewiesen habt.",al={"zeltlehrer","wer lehrt zelte für lederverarbeiter","karolek zelt"}},{q="Was bringt das Zelt?",a="Das Zelt schützt Euch vor Regen, spendet an heißen Tagen Schatten und bietet Euch auf Euren Reisen einen Platz zum Ausruhen.",al={"wozu dient das zelt","lagergegenstand lederverarbeitung","zelt benutzen"}},{q="Kann ich mein Zelt in der Stadt aufschlagen?",a="Der Abschlusstext besagt, dass die meisten Leute Zelte im Stadtzentrum nicht mögen, weshalb Ihr zum Ausprobieren in die Wildnis gehen müsst.",al={"zelt in der stadt","wo lagern","lagerplatz"}},{q="Was brauche ich noch, um ein Lager aufzuschlagen?",a="Ihr braucht neben einem Zelt auch ein Lagerfeuer. Köche können Euch lehren, ein Feuer zu entzünden.",al={"lagerfeuer benötigt","wie lagerfeuer machen","was vervollständigt ein lager"}},{q="Wer kann mich die Grundlagen der Kochkunst lehren?",a="Jemand, der Köche ausbildet, kann Euch die Grundlagen der Kochkunst lehren.",al={"kochkunstlehrer","kochkunst lernen","lagerfeuerlehrer"}}},fp="27,201,15.299.0,14.210.0,50.96.0,22.103.0,29.141.0,36.74.0,39.71.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="In Durotar können erfahrene Bergleute lernen, einen Lodestone für Lager in der Wildnis zu schmieden. Krunn in Klingenhügel lehrt dieses Handwerk.",h="In Durotar können erfahrene Bergleute lernen, einen Lodestone für Lager in der Wildnis zu schmieden.",kw={"lager","lagerfeuer","camping 101: mining","kochkunst","durotar","krunn","lodestone","bergbau","klingenhügel"},ang={["faction:Horde"]="Als Bergmann der Horde auf Reisen durch Durotar könnt Ihr Krunn in Klingenhügel besuchen, um zu lernen, Lodestones für Eure Expeditionen herzustellen.",["profession:Cooking"]="Als Koch könnt Ihr bei Kochkunstlehrern lernen, das einfache Lagerfeuer im Herzen eines Lagerplatzes in der Wildnis zu entfachen.",["profession:Mining"]="Als Bergmann könnt Ihr Rohmineralien zutage fördern und Feldausrüstung wie einen Lodestone herstellen, um Eure Verbündeten im Lager zu unterstützen."},sec={{t="Das Lager der Bergleute",b="Bergbau liefert Materialien für Reisen und das Überleben in der Wildnis. Mit Geschick im Umgang mit Spitzhacke und Erz könnt Ihr lernen, Ausrüstung für einen Lagerplatz herzustellen. In Durotar lehrt Krunn in Klingenhügel erfahrene Bergleute, einen Lodestone für ihre Reisen zu schmieden."},{t="Kameradschaft am Lagerfeuer",b="In einem Lager in der Wildnis verleiht ein Lodestone den versammelten Kämpfern größere Stärke im Kampf. Stellt ihn neben das Lagerfeuer, und Kämpfer, die sich auf Waffengewalt verlassen, erhalten rund um die Flammen einen Vorteil. Stadtbewohner missbilligen Zelte auf öffentlichen Plätzen, also braucht Ihr die freie Wildnis, um Euer Handwerk einzusetzen."},{t="Feuer und Lagerkunst",b="Ein robuster Lodestone braucht ein Feuer im Herzen des Lagers. Ihr benötigt ein einfaches Lagerfeuer, bevor Ihr einen Rastplatz einrichtet. Wenn Ihr nicht wisst, wie man eines entfacht, sucht einen Kochkunstlehrer auf. Kochkunst vermittelt die Grundlagen für Wärme und Verpflegung auf Expeditionen jenseits der Stadtmauern."}},faq={{q="Was ist Camping 101: Mining?",a="Erfahrene Bergleute können Krunn in Klingenhügel aufsuchen und lernen, einen Lodestone für einen Lagerplatz herzustellen.",al={"was ist camping 101: mining","lager bergbau quest","bergbau lodestone quest"}},{q="Wer ist Krunn?",a="Krunn bildet erfahrene Bergleute in Klingenhügel in Durotar aus. Sobald sie genügend Können beweisen, lehrt er sie, Lagergegenstände wie den Lodestone herzustellen.",al={"wer ist krunn","wo ist krunn","klingenhügel lehrer"}},{q="Wozu dient ein Lodestone?",a="Bergleute stellen Lodestones her, um sie neben einem Lagerfeuer in der Wildnis aufzustellen. Kämpfer, die körperliche Angriffe einsetzen und sich darum versammeln, erhalten größere Kampfkraft.",al={"was bewirkt ein lodestone","lodestone vorteil","warum lodestone herstellen"}},{q="Könnt Ihr innerhalb von Klingenhügel ein Lager aufschlagen?",a="Nein. Bewohner und Siedlungsbehörden missbilligen Lager in bewohnten Straßen. Begebt Euch in die umliegende Wildnis, um ein Lager aufzuschlagen und Euren Lodestone aufzustellen.",al={"lager in der stadt möglich","warum kein lager in klingenhügel","lager innerhalb von städten"}},{q="Warum braucht Ihr ein Lagerfeuer, bevor Ihr ein Lager aufschlagt?",a="Ein Lagerfeuer bildet den Mittelpunkt eines funktionierenden Lagerplatzes. Kochkunstlehrer bringen Euch bei, ein einfaches Feuer zu entfachen, und Kochkunst hilft Euch, Euch auf Lager in der Wildnis vorzubereiten.",al={"ist ein lagerfeuer nötig","wie ein lager aufschlagen","feuer als voraussetzung fürs lagern"}},{q="Wer kann lernen, einen Lodestone herzustellen?",a="Bergleute, die genügend Können beweisen, können bei Krunn in Klingenhügel lernen, einen Lodestone herzustellen.",al={"wer kann lodestones herstellen","kann jeder einen lodestone herstellen"}}},fp="19,119,16.226.0,20.272.0,19.265.0,28.90.0,13.141.0,29.129.0,38.154.0,50.156.0,35.85.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="In Orgrimmar werden neue Kürschner zu Thuwd geschickt, um das Lagerhandwerk zu erlernen. Ihr fertigt einen Lagerstuhl aus Häuten und Fellen und tragt ihn dann hinaus ins offene Gelände jenseits der Stadt.",h="In Orgrimmar werden neue Kürschner zu Thuwd geschickt, um das Lagerhandwerk zu erlernen.",kw={"lagerstuhl","lagerfeuer","lagern","camping 101: skinning","orgrimmar","kürschnerei","thuwd"},ang={["faction:Horde"]="Thuwd bildet Kürschner in Orgrimmar aus, sodass Abenteurer der Horde aus Durotar dieses Wildnishandwerk dort erlernen können.",["profession:Cooking"]="Ein richtiger Lagerplatz braucht sowohl einen Sitzplatz als auch Wärme. Als neuer Kürschner solltet Ihr die Grundlagen des Kochens studieren und lernen, ein Lagerfeuer zu entfachen."},sec={{t="Komfort in der Wildnis",b="In Orgrimmar lehrt Thuwd fähige Kürschner, aus gegerbten Häuten einen Lagerstuhl zu fertigen. Die Felle und Häute erlegter Bestien dienen nicht nur der Rüstungsherstellung. Ein Kürschner kann sie auch in der Wildnis nutzen."},{t="Regeln für unterwegs",b="Thuwd warnt, dass Wachen und Stadtbewohner Lager an belebten Straßen der Stadt ungern sehen. Ein Stuhl gehört ins offene Gelände, fernab der Siedlungsmauern. Ein richtiger Lagerplatz braucht auch ein wärmendes Lagerfeuer. Köche in ganz Kalimdor lehren die Grundlagen dafür."}},faq={{q="Wer lehrt Kürschner, Lagerausrüstung herzustellen?",a="In Orgrimmar lehrt Thuwd Kürschner, Lagerausrüstung herzustellen. Kürschner sprechen mit ihm, nachdem sie grundlegendes Geschick in ihrem Handwerk bewiesen haben.",al={"wer vergibt camping 101: skinning","mit wem in orgrimmar sprechen","wer ist thuwd"}},{q="Welchen Gegenstand fürs Lager können Kürschner herstellen?",a="Kürschner können aus den Häuten und Fellen erlegter Bestien einen Lagerstuhl fertigen. Er bietet ihnen einen bequemen Sitzplatz, wenn sie sich in der Wildnis ausruhen.",al={"was stellen kürschner fürs lager her","kürschnerei lagerhandwerk","lagerstuhl kürschnerei"}},{q="Kann man einen Lagerstuhl innerhalb einer Stadt aufstellen?",a="Stadtbewohner und Wachen sehen Lagerausrüstung in der Stadt ungern. Reist durch die Siedlungstore hinaus in die Wildnis, um Euer Lager aufzuschlagen und Euren Stuhl aufzustellen.",al={"in orgrimmar lagern möglich","lager in der stadt","wo lager aufschlagen"}},{q="Was braucht ein Lager außerdem, um vollständig zu sein?",a="Ein richtiger Lagerplatz braucht ein Feuer für Wärme, Licht und zum Kochen. Fragt einen Kochlehrer, wie Ihr ein einfaches Lagerfeuer entfacht, bevor Ihr Euer Lager aufschlagt.",al={"warum lagerfeuer nötig","voraussetzungen fürs lager","wie lager aufschlagen"}},{q="Warum sollte ein Abenteurer einen Lagerstuhl herstellen?",a="Ein bequemer Stuhl bietet Euch zwischen Jagden einen Ruheplatz, an dem Ihr Euch vor dem nächsten Scharmützel von der Reise erholen könnt.",al={"nutzen der kürschnerei beim lagern","warum im lagerstuhl ausruhen","vorteile des lagerstuhls"}},{q="Wann lehrt Thuwd das Muster für den Lagerstuhl?",a="Thuwd gibt das Muster für den Lagerstuhl weiter, nachdem Kürschner grundlegendes Geschick beim Gewinnen von Fellen und Häuten erlegter Bestien bewiesen haben.",al={"wann lagerstuhl erlernbar","camping 101 voraussetzungen","benötigte kürschnereifertigkeit"}}},fp="21,166,19.192.0,18.238.0,44.126.0,37.131.0,42.151.0,41.144.0,44.112.0,45.118.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="Thundris Windwirker sendet Nachricht aus Auberdine nach Sturmwind. Er will die Arbeit der Siedlung und seine Heimat über die Dunkelküste hinaus bekannt machen.",h="Thundris Windwirker sendet Nachricht aus Auberdine nach Sturmwind.",kw={"ameth'aran","auberdine","baros alexston","bashal'aran","dunkelküste","darnassus","expanding horizons","hafen","sturmwind","thundris windweaver"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, welche Arbeit nötig ist, um Völker auf zwei Kontinenten in einer Fraktion zu vereinen.",["race:Human"]="Als Mensch seht Ihr den Einfluss des wiederaufgebauten Königreichs wachsen, wenn Ihr mit dem Siegel einer Kaldorei-Siedlung nach Sturmwind zurückkehrt.",["race:NightElf"]="Für die Kaldorei beendet die Öffnung der Seewege zu den Östlichen Königreichen zehntausend Jahre der Abgeschiedenheit und verbindet Euer Volk mit der menschlichen Zivilisation."},sec={{t="Brücke zwischen zwei Hemisphären",b="Auberdines Seeweg verbindet die Dunkelküste nun direkt mit Sturmwind. Die Anführer wollen die Schifffahrtsroute sichern und die Küstensiedlung enger mit der Allianz verbinden. Die nahen Ruinenstädte Ameth'Aran und Bashal'Aran ziehen seit Langem mehr Aufmerksamkeit auf sich als Auberdine und seine lebenden Bewohner."},{t="Ein Schreiben an den Stadtarchitekten",b="Baros Alexston beaufsichtigt Sturmwinds Bauwesen und Infrastruktur. Zu seinen Aufgaben gehören öffentliche Bauvorhaben und Logistik. Thundris Windweavers Brief überquert das große Meer und erreicht den Beamten, der für die Bauangelegenheiten der Menschenhauptstadt zuständig ist."}},faq={{q="Wer schickt Euch auf diese Quest?",a="Thundris Windwirker, ein einflussreicher Nachtelf in Auberdine, bittet Euch, seinen Brief zu überbringen. Er findet, dass Darnassus und die Verbündeten jenseits des Ozeans die Siedlung übersehen, und sucht eine formelle Verbindung zum Menschenkönigreich.",al={"questgeber expanding horizons","wer vergibt expanding horizons","thundris quest"}},{q="Wer ist Baros Alexston?",a="Baros Alexston ist Sturmwinds Stadtarchitekt. Als angesehener Stadtplaner kannte er Edwin van Cleef schon in jungen Jahren. Er beaufsichtigt das Bauwesen und die Bauverwaltung in der gesamten Hauptstadt.",al={"baros alexston hintergrundgeschichte","wer ist baros","stadtarchitekt sturmwind"}},{q="Warum sucht Auberdine Kontakt zu Sturmwind?",a="Auberdine will seinen Hafen als Zugang für Versorgungsgüter, Handel und Reisen innerhalb der Allianz bekannt machen. Die Anführer hoffen, dass die neuen Seewege zwischen der Dunkelküste und den Östlichen Königreichen die wirtschaftlichen und logistischen Beziehungen zum Menschenkönigreich stärken.",al={"warum brief nach sturmwind schicken","verbindung auberdine sturmwind","warum menschen kontaktieren"}},{q="Wie reist man zwischen Auberdine und Sturmwind?",a="Ein Schiff fährt nun von Auberdine über das große Meer zum Hafen von Sturmwind. Es bringt Versorgungsgüter und Leben an Auberdines Küste.",al={"schiff nach sturmwind","wie von auberdine nach sturmwind gelangen"}},{q="Was sind Ameth'Aran und Bashal'Aran?",a="Ameth'Aran und Bashal'Aran waren wohlhabende Städte der Highborne an der uralten Dunkelküste. Die Great Sundering zerriss den Kontinent vor zehntausend Jahren. Heute liegen die Städte als heimgesuchte Ruinen da und nehmen in der Geschichte der Kaldorei mehr Raum ein als bewohnte Dörfer wie Auberdine.",al={"ameth aran hintergrundgeschichte","bashal aran","uralte städte der dunkelküste"}},{q="Warum geht dieser Brief an einen Architekten statt an König Anduin oder Bolvar?",a="Thundris Windwirker nennt keinen Grund für seine Wahl. Er bittet Euch, den Brief zu Baros Alexston, Sturmwinds Stadtarchitekten, zu bringen, damit Auberdines Arbeit Anerkennung findet.",al={"warum baros alexston","warum nicht bolvar","warum nicht hochlord bolvar"}}},fp="18,127,24.291.0,31.231.0,28.209.0,22.198.0,43.238.0,53.126.0,36.258.0,66.168.0"}
P.entries["quest:97915"] = {n="Camping 101: Alchemy",s="Ein Alchemist kann bei Alchemist Mallory nahe Sturmwind lernen, einen Manabrunnen herzustellen. Er bietet Heilern und Zauberwirkern im Lager einen erfrischenden Schluck.",h="Ein Alchemist kann bei Alchemist Mallory nahe Sturmwind lernen, einen Manabrunnen herzustellen.",kw={"alchemist","alchemist mallory","alchemie","lager","lagerfeuer","lagern","wald von elwynn","heiler","manabrunnen","zauberwirker","sturmwind"},sec={{t="Ein Lager für Gebräue",b="Ein Alchemist kann Alchemist Mallory nahe Sturmwind im Wald von Elwynn bitten, ihm ein Lagerhandwerk beizubringen. Ihr müsst Euer Können unter Beweis stellen, bevor Ihr lernt, einen Manabrunnen herzustellen. Heiler und Zauberwirker können für einen erfrischenden Schluck ins Lager kommen."},{t="Ein Lager aufschlagen",b="Sobald Ihr das Handwerk beherrscht, könnt Ihr Euren eigenen Manabrunnen herstellen. Lager gehören in die Wildnis, und Ihr braucht ein Lagerfeuer, bevor Ihr eines aufschlagt. Jemand, der Köche ausbildet, kann Euch die Grundlagen des Feuermachens beibringen."}},faq={{q="Wer lehrt Alchemisten, einen Manabrunnen herzustellen?",a="Alchemist Mallory lehrt das Handwerk nahe Sturmwind im Wald von Elwynn, sobald Ihr Euer Können unter Beweis gestellt habt.",al={"manabrunnen lehrer","alchemie lagerhandwerk","mallory alchemie"}},{q="Wozu dient ein Manabrunnen?",a="Ein Manabrunnen bietet Heilern und Zauberwirkern im Lager einen erfrischenden Schluck.",al={"manabrunnen verwendung","was bewirkt ein manabrunnen","alchemie lagergegenstand"}},{q="Wo kann ich Alchemist Mallory finden?",a="Alchemist Mallory befindet sich nahe Sturmwind im Wald von Elwynn.",al={"mallory standort","wo ist mallory","alchemielehrer elwynn"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Jemand, der Köche ausbildet, kann Euch beibringen, wie man ein Feuer macht.",al={"lagerfeuer benötigt","wie ein lager aufschlagen","lagergrundlagen"}},{q="Wo sollte ich meinen Manabrunnen ausprobieren?",a="Probiert ihn in der Wildnis aus, denn die meisten Leute mögen keine Lager mitten in der Stadt.",al={"manabrunnen lagern","lager in der stadt","wo manabrunnen ausprobieren"}}},fp="20,144,16.246.0,15.204.0,43.115.0,24.70.0,35.53.0,38.105.0,36.86.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="In Goldhain lehrt Schmied Argus erfahrene Metallarbeiter, sich auf die Arbeit in der Wildnis vorzubereiten. Sie lernen, einen tragbaren Schleifstein zu schmieden und mit einem ordentlichen Feuer im offenen Gelände ein Lager aufzuschlagen.",h="In Goldhain lehrt Schmied Argus erfahrene Metallarbeiter, sich auf die Arbeit in der Wildnis vorzubereiten.",kw={"schmiedekunst","lagerfeuer","lagern","camping 101","wald von elwynn","goldhain","schleifstein","schmied argus"},ang={["faction:Alliance"]="Handwerker der Allianz, die in Goldhain ihre ersten Schritte machen, können Schmied Argus fragen, wie sie sich auf lange Reisen jenseits der Stadt vorbereiten.",["profession:Blacksmithing"]="Schmiede, die im Wald von Elwynn ihr Handwerk erlernen, können einen Schleifstein schmieden, um im Feld Ausrüstung instand zu halten und Klingen zu schärfen.",["profession:Cooking"]="Ein ordentlicher Lagerplatz braucht ein verlässliches Feuer, daher ergänzt eine grundlegende Kochausbildung die Metallbearbeitung in der Wildnis gut."},sec={{t="Schmieden für unterwegs",b="Schmied Argus aus Goldhain zeigt erfahrenen Metallarbeitern, wie sie ihr Handwerk auch fern der städtischen Ambosse ausüben können. Wer für diese Arbeit bereit ist, kann lernen, einen Schleifstein zu schmieden, um Klingen auf langen Reisen scharf zu halten."},{t="Leben im Feld",b="Feldausrüstung allein macht noch kein ordentliches Lager aus. Die Bewohner von Goldhain sehen Lager innerhalb von Siedlungen nicht gern, daher müssen Handwerker ins offene Grenzland ziehen, um ihre Ausrüstung zu nutzen. Ein Lager in der Wildnis braucht auch ein wärmendes Feuer. Besucht einen örtlichen Koch, um die Grundlagen des Feuermachens zu erlernen."}},faq={{q="Was ist Camping 101: Blacksmithing?",a="Schmied Argus lehrt erfahrene Schmiede, einen tragbaren Schleifstein für den Einsatz in der Wildnis zu schmieden.",al={"was bewirkt diese quest","camping 101 blacksmithing zweck","was lernt man"}},{q="Wer ist Schmied Argus?",a="Schmied Argus ist der Schmied und Lehrer in Goldhain im Wald von Elwynn. Er lehrt vielversprechende Schmiede die Grundlagen der Metallbearbeitung und des Lagerhandwerks.",al={"wer ist schmied argus","goldhain schmiedekunstlehrer","argus goldhain"}},{q="Was ist ein Schleifstein?",a="Ein Schleifstein ist ein Ausrüstungsstück fürs Lager, das Schmiede herstellen können, um Werkzeuge und Waffen fern der städtischen Schmieden zu schärfen.",al={"was ist ein schleifstein","lager schleifstein","schmied lagergegenstand"}},{q="Könnt Ihr innerhalb der Stadt ein Lager aufschlagen?",a="Die Bewohner sehen Lager in besiedelten Orten wie Goldhain nicht gern. Schmiede müssen in die Wildnis ziehen, um ihre Ausrüstung aufzustellen.",al={"lagern in goldhain möglich","zelt in der stadt aufschlagen","wo kann man lagern"}},{q="Warum braucht Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ein Lagerfeuer vervollständigt ein Lager in der Wildnis. Schmiede können einen Kochlehrer aufsuchen, um vor dem Aufbruch die Grundlagen des Feuermachens zu erlernen.",al={"kochen fürs lagern nötig","lagerfeuer fürs lager","wie schlägt man ein lager auf"}},{q="Wann könnt Ihr dieses Lagerhandwerk erlernen?",a="Schmied Argus lehrt dieses Lagerhandwerk Schmieden mit ausreichendem Können.",al={"camping 101 voraussetzungen","erforderliche schmiedefertigkeit"}}},fp="26,188,21.201.0,17.265.0,35.103.0,19.143.0,27.115.0,32.120.0,40.126.0,38.76.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="In Sturmwind lehrt Betty Quin Verzauberer, ein wenig Magie ans Lagerfeuer zu bringen. Mit einer Verzauberten Laute können sie die Stimmung heben und Reisenden helfen, unterwegs zur Ruhe zu kommen.",h="In Sturmwind lehrt Betty Quin Verzauberer, ein wenig Magie ans Lagerfeuer zu bringen.",kw={"betty quin","lager","camping 101","camping 101: enchanting","verzauberte laute","verzauberkunst","sturmwind"},ang={["faction:Alliance"]="Verzauberer der Allianz, die durch ihre Lande reisen, können Betty Quin in Sturmwind aufsuchen, um Unterricht im Lagerhandwerk zu erhalten."},sec={{t="Magie auf dem Weg",b="Lange Wege durch Azeroth verlangen mehr als Stahl und Proviant. Auch in der Wildnis zählen Behaglichkeit und gute Stimmung. Verzauberer setzen ihr Handwerk im Lager ein und füllen ruhige Stunden mit Musik und Erholung, bevor der nächste Wegabschnitt beginnt."},{t="Auf der Suche nach Betty Quin",b="Betty Quin in Sturmwind lehrt Verzauberer, besondere Gegenstände für den Lagerplatz herzustellen. Sobald sie ihr Können in der Verzauberkunst bewiesen haben, kann sie ihnen beibringen, eine Verzauberte Laute herzustellen. Deren Zauber heben die Stimmung am Lagerfeuer."}},faq={{q="Was ist Camping 101: Enchanting?",a="Bei Betty Quin in Sturmwind können Verzauberer lernen, magische Vorräte fürs Lager herzustellen. Sie unterrichtet jene, die ihr Handwerk verfeinert haben.",al={"was ist camping 101 enchanting","camping 101 verzauberer","verzauberkunst lager quest"}},{q="Wer ist Betty Quin?",a="Betty Quin lehrt geübte Verzauberer in Sturmwind, magische Gegenstände für unterwegs und für die Freizeit herzustellen.",al={"wer ist betty quin","sturmwind verzauberkunstlehrerin betty","wo ist betty quin"}},{q="Was ist eine Verzauberte Laute?",a="Eine Verzauberte Laute ist ein magisches Instrument, das im Lager für Musik sorgt und die Stimmung hebt. Sie hilft Reisenden, den Strapazen des Weges zu begegnen.",al={"was bewirkt die verzauberte laute","warum eine verzauberte laute herstellen","verzauberte laute zweck"}},{q="Warum werden Verzauberer im Lager geschätzt?",a="Verzauberer bringen Magie ins Lager und machen Ruhepausen zu einer Gelegenheit, sich vor einer beschwerlichen Reise auszuruhen, vorzubereiten und etwas Musik zu genießen.",al={"warum verzauberer im lager","verzauberer nutzen im lager"}},{q="Wohin muss ich gehen, um diese Aufgabe abzuschließen?",a="Sucht Betty Quin in Sturmwind, der Hauptstadt des Königreichs Sturmwind.",al={"wo camping 101 enchanting abgeben","betty quin standort"}},{q="Welches Können ist nötig, um Verzauberungsrezepte fürs Lager zu erlernen?",a="Betty Quin lehrt Verzauberer, die solides Können in der Verzauberkunst bewiesen haben, das Lagerhandwerk, darunter auch die Herstellung einer Verzauberten Laute.",al={"camping 101 enchanting voraussetzungen","wann verzauberte laute erlernen"}}},fp="23,171,18.231.0,18.216.0,32.130.0,18.106.0,26.142.0,40.118.0,36.70.0,57.125.0"}
P.entries["quest:97919"] = {n="Camping 101: First Aid",s="Im Gasthaus \"Zur Höhle des Löwen\" zeigt Michelle Belle Euch, wie Ihr Verbandtaschen fürs Zelten vorbereitet. Ihr braucht genügend Fertigkeit in Erster Hilfe, um zu lernen, wie Ihr diese Vorräte für den bevorstehenden Weg zusammenstellt.",h="Im Gasthaus \"Zur Höhle des Löwen\" zeigt Michelle Belle Euch, wie Ihr Verbandtaschen fürs Zelten vorbereitet.",kw={"verbände","lagerausrüstung","grundlagen des zeltens","wald von elwynn","erste hilfe","goldhain","michelle belle","überleben"},ang={["class:Rogue"]="Als Schurke, der fernab jeder Hilfe im Verborgenen arbeitet, seid Ihr auf Feldmedizin angewiesen, um blutende Wunden zu verbinden, bevor Ihr Euer nächstes Ziel verfolgt.",["class:Warrior"]="Als Krieger habt Ihr keine eigenen Heilzauber, daher verlasst Ihr Euch auf Verbände und Feldausrüstung, um lange Feldzüge in der Wildnis durchzustehen.",["faction:Alliance"]="Goldhain ist ein Wegkreuz für Reisende der Allianz, die von Nordhain nach Elwynn unterwegs sind."},sec={{t="Feldmedizin auf Reisen",b="Auf Reisen durch Elwynn könnt Ihr verwundet werden, weit entfernt von einem Heiler im Ort oder einem Gasthaus. Erste Hilfe ermöglicht Euch, Eure Verletzungen zu versorgen, ohne auf andere angewiesen zu sein. Verbände helfen bei Blutungen und Verletzungen, ohne arkane Rituale oder heilige Gebete."},{t="Vorräte für den Lagerplatz",b="Im Gasthaus \"Zur Höhle des Löwen\" in Goldhain lehrt Michelle Belle geübte Anwender, Verbandtaschen zusammenzustellen. Haltet medizinische Vorräte im Lager bereit, damit eine erschöpfte Gruppe Verletzungen behandeln und wieder zu Kräften kommen kann, bevor sie den bevorstehenden Gefahren begegnet."}},faq={{q="Was ist der Zweck dieser Quest?",a="Abenteurer mit Grundkenntnissen in Erster Hilfe suchen Michelle Belle in Goldhain auf. Sie lehrt sie, eine Verbandtasche herzustellen und ein Wildnislager mit medizinischen Vorräten auszustatten.",al={"zelten erste hilfe zweck","was bewirkt diese quest","warum grundlagen des zeltens erste hilfe"}},{q="Mit wem muss ich in Goldhain sprechen?",a="Sprecht mit Michelle Belle, einer Lehrerin für Erste Hilfe in Goldhain. Sobald Ihr genügend Fertigkeit nachweist, lehrt sie Euch, wie Ihr Lagervorräte für die Feldmedizin herstellt.",al={"wer ist michelle belle","lehrer fürs zelten goldhain","erste hilfe lagerlehrer"}},{q="Warum ist Erste Hilfe für Reisende wichtig?",a="Erste Hilfe hilft Reisenden, Verletzungen durch Wildtiere, Banditen und raues Wetter zu versorgen. Jeder kann Wunden verbinden und sich zwischen Scharmützeln erholen, mit oder ohne göttliche oder arkane Magie.",al={"warum erste hilfe lernen","ist erste hilfe nützlich","erste hilfe hintergrund"}},{q="Wo liegt Goldhain?",a="Goldhain ist das wichtigste Dorf im Wald von Elwynn und liegt unmittelbar südlich von Sturmwind an der Haupthandelsstraße. Es ist ein zentraler Anlaufpunkt für Vorräte und örtliche Lehrer, mit Erholung im Gasthaus \"Zur Höhle des Löwen\".",al={"wo ist goldhain","goldhain lage","wie michelle belle finden"}},{q="Brauche ich eine vorherige Ausbildung, um diese Aufgabe abzuschließen?",a="Ja. Michelle Belle verlangt von Euch einen Nachweis Eurer Fertigkeit in Erster Hilfe, bevor sie Euch lehrt, Lagerausrüstung herzustellen.",al={"voraussetzungen grundlagen des zeltens","benötigte erste-hilfe-fertigkeit","voraussetzungen"}},{q="Wie passt eine Verbandtasche zum Zelten?",a="Ein Lagerplatz in der Wildnis bietet einen sicheren Ort zur Erholung. Eine Verbandtasche hält Verbände und Heilmittel griffbereit, um fernab der Heiler in den Ortschaften Leben zu retten.",al={"verbandtasche im lager verwenden","zeltausrüstung erste hilfe","warum eine verbandtasche herstellen"}}},fp="22,181,26.227.0,25.224.0,34.158.0,41.153.0,41.178.0,27.185.0,47.99.0,42.155.0"}
P.entries["quest:97920"] = {n="Camping 101: Fishing",s="Lee Brown lehrt neue Angler bei Goldhain, wie sie ihre Angelfertigkeit im Lager nutzen können. Mit einfachen Fängen und grundlegenden Materialien können sie nützliche Ergänzungen für einen Lagerplatz herstellen.",h="Lee Brown lehrt neue Angler bei Goldhain, wie sie ihre Angelfertigkeit im Lager nutzen können.",kw={"lagerhandwerk","camping 101: fishing","kristallsee","wald von elwynn","fischglas","goldhain","lee brown"},ang={["faction:Alliance"]="Als menschlicher Reisender am Anfang Eures Weges im Wald von Elwynn könnt Ihr an den vertrauten Gewässern von Goldhain lernen, Euch in der Wildnis selbst zu versorgen."},sec={{t="Lagerhandwerk für Angler",b="Angeln kann Euch unterwegs ernähren und das Lager behaglicher machen. Ein Fischglas hebt die Stimmung müder Reisender zwischen ihren Ausflügen. Ein klarer Verstand und gute Laune helfen dabei, starke Kämpfer hervorzubringen."},{t="Lee Browns Fachwissen",b="Lee Brown wartet an den Gewässern vor Goldhain auf Fischer, die ihr Handwerk erweitern möchten. Zeigt ihm Euer Können mit Rute und Schnur, und er kann Euch lehren, nützliche Ergänzungen fürs Lager herzustellen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Lee Brown bei Goldhain weist angehenden Fischern den Weg. Nachdem Ihr grundlegendes Können beim Angeln bewiesen habt, lehrt er Euch, Lagergegenstände wie ein Fischglas für Lagerplätze am Wegesrand herzustellen.",al={"warum beim zelten angeln","was bringt grundlagen des zeltens","zweck der quest"}},{q="Wer ist Lee Brown?",a="Lee Brown ist ein Angellehrer am Kristallsee, gleich vor Goldhain im Wald von Elwynn. Er lehrt das Angeln und zeigt Fischern, wie sie Gegenstände fürs Lager herstellen können.",al={"wo ist lee brown","wer lehrt angeln fürs zelten","lee brown"}},{q="Was bewirkt ein Fischglas auf einem Lagerplatz?",a="Ein Fischglas bringt Behaglichkeit und Freude auf einen Lagerplatz. Eine angenehme Umgebung hebt die Moral und hilft Abenteurern, sich den Herausforderungen der Wildnis gewachsen und gut vorbereitet zu fühlen.",al={"fischglas wirkung","was bewirkt ein fischglas","warum ein fischglas herstellen"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung findet im Wald von Elwynn statt, an den Gewässern rund um Goldhain, wo sich einheimische Angler versammeln.",al={"quest ort","wohin gehen","zeltlehrer elwynn"}},{q="Brauche ich bereits Angelfertigkeiten, um dies abzuschließen?",a="Ja. Lee Brown unterrichtet Reisende, die das Auswerfen der Angel geübt und grundlegendes Können beim Angeln bewiesen haben.",al={"benötigte angelfertigkeit","angeln erforderlich","benötigtes können"}},{q="Ist Zelten im Kampf nützlich?",a="Ja. Ein gepflegtes Lager bietet Behaglichkeit, die körperliche und geistige Kampfbereitschaft, Widerstandskraft und Kampfkraft eines Abenteurers im Gelände verbessert.",al={"hilft zelten im kampf","zelten stärkungszauber","warum zelten"}}},fp="20,179,21.187.0,21.190.0,34.169.0,17.154.0,40.155.0,36.105.0,50.93.0,29.154.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Im Wald von Elwynn lehrt Herbalist Pomeroy geübte Sammler, für neue Annehmlichkeiten im Lager zu sorgen. Sie lernen, Räucherkerzen herzustellen, deren Duft die Stimmung von Zauberwirkern hebt, die in der Wildnis rasten.",h="Im Wald von Elwynn lehrt Herbalist Pomeroy geübte Sammler, für neue Annehmlichkeiten im Lager zu sorgen.",kw={"lager","camping 101","lagerplatz","wald von elwynn","heiler","kräuterkunde","kräuterkundige pomeroy","räucherkerze","zauberwirker"},ang={["class:Mage"]="Als Magier könnt Ihr von einem kräuterkundigen Gefährten profitieren, der Räucherkerzen für das Lager herstellt.",["class:Priest"]="Als Priester könnt Ihr auf Reisen durch die Wildnis in der Nähe einer Räucherkerze rasten und aus ihrem Duft neuen Mut schöpfen.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr im Wald von Elwynn bei Herbalist Pomeroy Unterricht suchen.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr Euer Pflanzenwissen nutzen, um Räucherkerzen herzustellen, die Euren Reisegefährten im Lager Wohlbehagen schenken."},sec={{t="Botanische Nützlichkeiten für unterwegs",b="Die Kunst eines Kräuterkundigen kann einer Reisegruppe auf vielfältigere Weise helfen als durch das Brauen stärkender Tränke oder den Verkauf von Blumen. Mit Geschick beim Sammeln könnt Ihr Euren Gefährten helfen, in der Wildnis durchzuhalten. Ein Lager braucht mehr als ein Feuer und eine trockene Schlafrolle. Müde Reisende brauchen auch Annehmlichkeiten, die ihren Geist wach halten. Manche Pflanzen verströmen Düfte, die einen müden Geist erfrischen, sodass Kräuterkundige eine Gruppe fernab der Zivilisation unterstützen können."},{t="Die Führung von Kräuterkundiger Pomeroy",b="Im Wald von Elwynn lehrt Herbalist Pomeroy geübte Sammler, aus heimischen Pflanzen Lagerbedarf herzustellen. Sie zeigt ihnen, wie sie eine Räucherkerze formen und Kräuter auch jenseits alchemistischer Fläschchen nutzen können. Wird sie im Lager entzündet, beruhigt ihr Duft müde Reisende und hebt die Stimmung von Gefährten, die auf Mana angewiesen sind. Dank Pomeroys Lehren können Kräuterkundige Gruppen auf Reisen durch die Wildnis Annehmlichkeiten bieten."}},faq={{q="Was ist Camping 101: Herbalism?",a="Geübte Kräuterkundige können lernen, Räucherkerzen für Lagerplätze herzustellen. Herbalist Pomeroy lehrt dieses Handwerk im Wald von Elwynn.",al={"camping 101 herbalism quest","kräuterkunde camping quest","was ist camping 101 herbalism"}},{q="Wer lehrt das Campingrezept für Kräuterkundige?",a="Herbalist Pomeroy lehrt geübte Sammler im Wald von Elwynn, Räucherkerzen aus heimischen Pflanzen herzustellen.",al={"wer lehrt kräuterkunde camping","camping 101 lehrer","wo ist kräuterkundige pomeroy","kräuterkundige pomeroy aufenthaltsort"}},{q="Welchen Gegenstand lernen Kräuterkundige durch diese Quest herzustellen?",a="Kräuterkundige lernen, eine Räucherkerze herzustellen. Ihr Duft beruhigt Reisende und hebt die Stimmung von Gefährten, die auf Mana angewiesen sind, während sie in der Wildnis rasten.",al={"was stellen kräuterkundige fürs camping her","kräuterkunde lagergegenstand","räucherkerze kräuterkunde","was lehrt camping 101"}},{q="Was sind die Voraussetzungen, um Camping 101: Herbalism zu beginnen?",a="Ihr braucht Geschick in der Kräuterkunde und beim Sammeln, bevor Herbalist Pomeroy Euch das Lagerhandwerk beibringt.",al={"camping 101 herbalism voraussetzungen","wann kann man camping 101 herbalism annehmen","benötigte kräuterkundefertigkeit für camping 101"}},{q="Warum sind Räucherkerzen für Abenteurergruppen nützlich?",a="Räucherkerzen beruhigen Reisende und heben die Stimmung von Gefährten, die auf Mana angewiesen sind, während sie in der Wildnis rasten.",al={"was bewirkt die räucherkerze","warum eine räucherkerze herstellen","vorteile der räucherkerze","kräuterkunde räucherkerze nutzung"}},{q="Wo findet diese Quest statt?",a="Ihr reist in den Wald von Elwynn, um Herbalist Pomeroy zu treffen und die Herstellung von Lagerbedarf zu erlernen.",al={"camping 101 herbalism zone","wo gibt man camping 101 herbalism ab","wald von elwynn kräuterkunde quest"}},{q="Können Nicht-Kräuterkundige die Räucherkerze herstellen?",a="Nein. Die Herstellung einer Räucherkerze erfordert Kräuterkunde und Wissen über Wildpflanzen und duftende Materialien, das Herbalist Pomeroy vermittelt.",al={"kann jeder eine räucherkerze herstellen","ist die räucherkerze nur für kräuterkundige","braucht man kräuterkunde für die räucherkerze"}}},fp="22,192,32.406.0,33.393.0,31.122.0,46.103.0,55.155.0,58.93.0,55.111.0,33.90.0,44.133.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="In Goldhain lehrt Adele Fielder Lederverarbeiter, ein Zelt für Reisen über den Ort hinaus herzustellen. Es schützt Reisende vor rauem Wetter und bietet ihnen einen Ruheplatz, wenn sie in der Wildnis lagern.",h="In Goldhain lehrt Adele Fielder Lederverarbeiter, ein Zelt für Reisen über den Ort hinaus herzustellen.",kw={"adele fielder","lagerfeuer","zelten","wald von elwynn","goldhain","lederverarbeitung","zelt","überleben in der wildnis"},ang={["faction:Alliance"]="In Goldhain führt diese Ausbildung Lederverarbeiter der Allianz an praktische Überlebensfertigkeiten für Reisen durch Azeroth heran.",["profession:Cooking"]="Adele Fielder sagt, dass ein Lagerplatz in der Wildnis ein Lagerfeuer braucht, und legt Euch nahe, Kochkunst zu erlernen, damit Ihr eines entfachen könnt."},sec={{t="Schutz für unterwegs",b="Jenseits der Tore von Goldhain ist ein Unterschlupf ebenso wichtig wie eine Rüstung. Im Wald von Elwynn können Lederverarbeiter Adele Fielder aufsuchen, um mehr als einfache Gürtel und Tuniken zu erlernen. Nachdem sie ihr Geschick mit Leder und Nadel bewiesen haben, lehrt Adele sie, ein strapazierfähiges Zelt für lange Überlandreisen herzustellen. Es ist dafür gemacht, rauem Wetter standzuhalten."},{t="Die Grundlagen des Lagerbaus",b="Ein fertiges Zelt überdacht einen Lagerplatz und schützt vor den Elementen. Es hält Reisende unter sengender Sonne kühl, bei peitschendem Regen trocken und zwischen gefährlichen Begegnungen ausgeruht.\n\nDie Bewohner von Goldhain und die Stadtwachen dulden keine Lagerplätze auf den Straßen des Ortes, also müsst Ihr zum Lagern in die offene Wildnis hinausziehen. Adele erinnert Wanderer auch daran, dass ein ordentliches Lager ein Lagerfeuer braucht. Ein Kochkunstlehrer kann Euch beibringen, eines zu entfachen."}},faq={{q="Wer lehrt Lederverarbeiter, Zelte herzustellen?",a="Adele Fielder lehrt Lederverarbeiter in Goldhain im Wald von Elwynn, robuste Zelte herzustellen, nachdem sie ihr handwerkliches Können bewiesen haben.",al={"wer lehrt zeltherstellung","adele fielder standort","lehrer für lederverarbeitungszelte"}},{q="Welchem Zweck dient ein selbst hergestelltes Zelt?",a="Ein selbst hergestelltes Zelt schützt Reisende vor rauem Wetter und hält sie an schwülen Tagen kühl und bei starkem Regen trocken. Es bietet Abenteurern auch einen Ruheplatz in der Wildnis.",al={"warum ein zelt herstellen","was bewirkt ein zelt","vorteile eines zeltes"}},{q="Könnt Ihr innerhalb einer Stadt ein Zelt aufschlagen?",a="Ihr könnt auf Straßen oder Plätzen im Ortskern kein Zelt aufschlagen. Bringt Eure Ausrüstung in die Wildnis, um ein Lager aufzuschlagen.",al={"zelt in der stadt aufschlagen","wo ein zelt benutzen","zelt in stormwind oder goldhain"}},{q="Was braucht ein vollständiges Lager neben einem Zelt noch?",a="Adele Fielder sagt, dass ein Lager neben einem Zelt auch ein Lagerfeuer braucht, das in der Wildnis Wärme spendet und praktische Zwecke erfüllt.",al={"was braucht ein lager sonst noch","lagerfeuer für zelt erforderlich","lagerplatz vervollständigen"}},{q="Wo können Reisende lernen, ein Lagerfeuer zu entfachen?",a="Kochkunstlehrer und örtliche Köche vermitteln die Grundlagen des Entfachens eines Lagerfeuers. Lernt von ihnen, damit Ihr überall auf Euren Wanderungen ein zuverlässiges Feuer entfachen könnt.",al={"wer lehrt lagerfeuer","lagerfeuer entfachen lernen","feuer fürs lager"}},{q="Wann kann ein Lederverarbeiter lernen, ein Lagerzelt herzustellen?",a="Ein Lederverarbeiter muss zuerst sein handwerkliches Können beweisen, bevor Adele Fielder ihn die Zeltherstellung lehrt.",al={"fertigkeitsanforderungen für zelte","wie das zel rezept erhalten","wann ein zelt herstellen"}}},fp="27,196,25.319.0,27.420.0,46.127.0,39.163.0,35.107.0,56.103.0,47.142.0,55.91.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="In Sturmwind lehrt Gelman Stonehand Bergleute, einen Magnetstein für Lager in der Wildnis zu formen. Neben einem Lagerfeuer stärkt er die dort versammelten Kämpfer.",h="In Sturmwind lehrt Gelman Stonehand Bergleute, einen Magnetstein für Lager in der Wildnis zu formen.",kw={"lagerfeuer","camping 101: mining","lagerplatz","gelman stonehand","magnetstein","bergbau","sturmwind","wildnis"},ang={["faction:Alliance"]="Als Handwerker der Allianz könnt Ihr bei Gelman Stonehand in Sturmwind lernen, Erdkunst in praktische Werkzeuge für den Einsatz im Gelände umzusetzen.",["profession:Cooking"]="Als Koch könnt Ihr lernen, ein Lagerfeuer zu unterhalten, die Grundlage für spezialisierte Lagerausrüstung.",["profession:Mining"]="Als Bergmann könnt Ihr einen Magnetstein formen, um Euren Lagerplatz in der Wildnis zu stärken und Verbündeten zu helfen, die neben Euch rasten."},sec={{t="Die resonante Kraft der Erde",b="Bergleute in Sturmwind können den natürlichen Magnetismus der Erde in einem Magnetstein bündeln. Am Lagerplatz einer Expedition stärkt er die Kampfkraft der dort Versammelten. Gelman Stonehand, Sturmwinds Bergbaulehrer, lehrt dieses Handwerk Schürfer, die ihr Geschick mit der Spitzhacke beweisen."},{t="Wildnislager und Lagerfeuer",b="Ein Magnetstein gehört in die Wildnis, fern vom Kathedralenplatz und dem Handelsdistrikt. Die Stadtbewohner missbilligen es, wenn Reisende innerhalb der Stadtgrenzen lagern, also müssen Pioniere in die Wildnis ziehen, um ihr Lager aufzuschlagen. Der Stein braucht auch ein Lagerfeuer. Köche im ganzen Reich lehren diese grundlegende Fertigkeit für das Leben in der Wildnis."}},faq={{q="Was ist Camping 101: Mining?",a="Gelman Stonehand lehrt Bergleute in Sturmwind, einen Magnetstein für einen Lagerplatz in der Wildnis herzustellen. Ihr müsst Euer Können im Bergbau beweisen, um dieses Handwerk zu erlernen.",al={"was ist camping 101: mining","questziel","was ist zu tun"}},{q="Wer lehrt den Bauplan für den Magnetstein?",a="Gelman Stonehand ist ein Bergbaulehrer in Sturmwind. Er lehrt ausreichend geübte Bergleute, einen Magnetstein für Expeditionen in die Wildnis herzustellen.",al={"wer lehrt magnetstein","wo ist gelman stonehand","stonehand standort"}},{q="Was bewirkt ein Magnetstein?",a="Ein Magnetstein an einem Lagerplatz in der Wildnis stärkt Krieger und andere Kämpfer, die sich um dessen Lagerfeuer versammeln.",al={"was bewirkt magnetstein","magnetstein stärkungszauber","warum magnetstein herstellen"}},{q="Kann ich innerhalb von Sturmwind ein Lager aufschlagen?",a="Sturmwinds Stadtbewohner missbilligen Lager auf den Plätzen und Straßen der Stadt. Begebt Euch vor die Tore der Siedlung, um Euer Lager aufzuschlagen und Euren Magnetstein in der Wildnis aufzustellen.",al={"lagern in der stadt erlaubt","wo lager aufschlagen","lagerbeschränkungen"}},{q="Warum brauche ich ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ein Lagerfeuer ist die Grundlage eines Lagerplatzes, und spezialisierte Ausrüstung wie ein Magnetstein ist ohne eines nutzlos. Köche lehren Reisende, mit Holz und Feuerstein Feuer zu entfachen.",al={"kochkunst zum lagern nötig","wie lager aufschlagen","lagerfeuer voraussetzung"}},{q="Wer profitiert am meisten davon, sich um einen Magnetstein zu versammeln?",a="Jeder, der mit Klinge, Axt oder Hammer kämpft, kann von einem Magnetstein profitieren. Kämpfer suchen seine zusätzliche Stärke, während sie vor einer gefährlichen Schlacht an den Flammen rasten.",al={"wer profitiert vom magnetstein","magnetstein für nahkämpfer","magnetstein klassen"}}},fp="19,152,26.291.0,30.285.0,28.145.0,36.132.0,25.110.0,35.156.0,40.163.0,52.164.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Im Wald von Elwynn lernen Kürschner Camping 101: Skinning bei Helene Peltskinner in Goldhain. Sie lehrt sie, aus erbeuteten Bälgen einen Lagerstuhl für die Rast fernab bewohnter Städte zu fertigen.",h="Im Wald von Elwynn lernen Kürschner Camping 101: Skinning bei Helene Peltskinner in Goldhain.",kw={"lagerstuhl","lagerfeuer","camping 101: skinning","goldhain","helene peltskinner","kürschnerei","lagern in der wildnis"},ang={["faction:Alliance"]="Sucht als Kürschner der Allianz bei einem Besuch im Wald von Elwynn Helene Peltskinner in Goldhain auf, um dieses Wildnishandwerk zu erlernen.",["profession:Cooking"]="Wendet Euch als Kürschner, der lernt, ein Lager im Freien aufzuschlagen, an einen Koch. Ein Lagerplatz braucht ein einfaches Lagerfeuer zum Wärmen und Zubereiten von Mahlzeiten."},sec={{t="Annehmlichkeiten in der Wildnis",b="Ihr könnt aus Bälgen von Wildtieren einen Lagerstuhl für die Rast in der Wildnis fertigen. In Goldhain lehrt Helene Peltskinner geübte Kürschner, diesen Sitz für Reisende auf langen Reisen durch gefährliche Lande herzustellen."},{t="Regeln am Lagerplatz",b="Bringt Eure Ausrüstung in die Wildnis, bevor Ihr ein Lager aufschlagt, denn Stadtbewohner haben oft etwas gegen Lager auf dem Marktplatz. Ein Lager im Freien braucht auch ein Lagerfeuer. Viele Kürschner erlernen grundlegende Kochkünste, um das Feuermachen zu meistern."}},faq={{q="Was ist Camping 101: Skinning?",a="In Goldhain lehrt Helene Peltskinner geübte Kürschner, aus erbeuteten Bälgen einen Lagerstuhl herzustellen.",al={"was ist camping 101: skinning","was bewirkt diese quest","kürschnerei lagerstuhl quest"}},{q="Wer lehrt Kürschner, einen Lagerstuhl herzustellen?",a="Helene Peltskinner lehrt geübte Kürschner in Goldhain, einen Lagerstuhl herzustellen.",al={"wer lehrt die herstellung von lagerstühlen","helene peltskinner standort","wo camping 101: skinning abgeben"}},{q="Wozu dient die Herstellung eines Lagerstuhls?",a="Ein Lagerstuhl bietet Reisenden einen Sitzplatz, auf dem sie sich während ihrer Reisen durch die Wildnis ausruhen können.",al={"was bewirkt ein lagerstuhl","warum einen lagerstuhl herstellen","lagerstuhl zweck"}},{q="Wo können Abenteurer ihr Lager aufschlagen?",a="Stadtbewohner sehen Lager mitten in Siedlungen meist ungern, also schlagt Euer Lager in der Wildnis auf.",al={"lagern in der stadt erlaubt","wo lagerstuhl aufstellen","lagern in goldhain"}},{q="Was wird außerdem für einen vollständigen Lagerplatz benötigt?",a="Ein Lagerplatz braucht ein einfaches Lagerfeuer. Wenn Ihr nicht wisst, wie Ihr eines entfacht, lernt die Kochkunst bei einem Koch vor Ort.",al={"was wird für ein lager benötigt","ist ein feuer zum lagern nötig","lagerfeuer voraussetzung"}},{q="Wer kann dieses Lagerhandwerk erlernen?",a="Kürschner, die geübt darin sind, Bälge von Wildtieren zu gewinnen, können dieses Handwerk erlernen und diese Bälge in der Wildnis praktisch nutzen.",al={"wer kann die herstellung von lagerstühlen erlernen","auch ohne kürschnerei möglich","kürschnerei voraussetzung fürs lagern"}}},fp="21,184,29.212.0,21.213.0,30.103.0,47.81.0,45.83.0,34.107.0,51.110.0,44.122.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="Im Wald von Elwynn werden erfahrene Stoffwirker zu Eldrin im Holzfällerlager des Osttals geschickt. Er lehrt sie, ein Fraktionsbanner zu weben, das Reisende inspiriert und die Moral in Wildnislagern stärkt.",h="Im Wald von Elwynn werden erfahrene Stoffwirker zu Eldrin im Holzfällerlager des Osttals geschickt.",kw={"banner","camping","camping 101","holzfällerlager des osttals","eldrin","wald von elwynn","fraktionsbanner","schneiderei"},ang={["faction:Alliance"]="Abenteurer der Allianz werden zu Eldrin im Holzfällerlager des Osttals im Wald von Elwynn geschickt, um zu lernen, ein Fraktionsbanner zu nähen.",["profession:Tailoring"]="Schneider können ein Fraktionsbanner weben, um auf langen Expeditionen Reisende zu inspirieren und die Moral im Lager zu stärken."},sec={{t="Webers Aufgabe in der Wildnis",b="Eldrin, ein Handwerker im Holzfällerlager des Osttals im östlichen Wald von Elwynn, unterweist erfahrene Schneider. Die Schneiderei stellt Kleidung und Taschen her, kann aber auch eine Reise unterstützen. Wer sein Geschick mit Faden und Webstuhl bewiesen hat, kann lernen, Lagerzubehör für Reisen durch die Wildnis herzustellen."},{t="Banner für die Moral",b="Das Fraktionsbanner ist das wichtigste Werkstück, dessen Herstellung Eldrin lehrt. Es steht neben dem Feuer eines Reisenden, wo sein Emblem auf gefährlichen Reisen und im Kampf Mut machen kann. Ein Banner im Lager bietet müden Reisenden ein vertrautes Zeichen der Entschlossenheit und hilft ihnen, ihren Weg durch feindliche Lande fortzusetzen."}},faq={{q="Welchen Zweck hat Camping 101: Tailoring?",a="Eldrin im Holzfällerlager des Osttals im Wald von Elwynn lehrt erfahrene Schneider, ein Fraktionsbanner herzustellen. Das Banner inspiriert Reisende und stärkt die Moral im Lager.",al={"was ist camping 101 tailoring","schneiderei lagergegenstand quest","wie bekommt man ein lagerbanner"}},{q="Wer ist Eldrin und wo ist er zu finden?",a="Eldrin ist ein Handwerker im Holzfällerlager des Osttals im östlichen Wald von Elwynn. Er lehrt erfahrene Schneider, Fraktionsbanner für Lager herzustellen.",al={"wer ist eldrin","wo ist eldrin","eldrin standort"}},{q="Was bewirkt das Fraktionsbanner in einem Lager?",a="Ein Fraktionsbanner inspiriert Reisende und stärkt die Moral im Lager. Sein Emblem schenkt müden Reisenden Entschlossenheit auf ihrem Weg durch feindliche Lande.",al={"was bewirkt das schneidereibanner","fraktionsbanner lager","warum ein fraktionsbanner herstellen"}},{q="Welche Voraussetzungen müssen erfüllt sein, um das Handwerk bei Eldrin zu erlernen?",a="Schneider müssen zunächst ihr Können beweisen, bevor Eldrin sie das Handwerk lehrt. Sie brauchen geübte Hände im Umgang mit der Nadel, um das Banner zu weben und zusammenzunähen.",al={"welche fertigkeit ist nötig","campingbanner voraussetzungen","kann jeder schneider ein banner herstellen"}},{q="Wo liegt das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt in den östlichen Wäldern des Waldes von Elwynn, an der Straße zum Rotkammgebirge. An diesem Knotenpunkt der Holzfällerei kommen örtliche Handwerker und Arbeiter zusammen.",al={"wo ist das holzfällerlager des osttals","holzfällerlager des osttals elwynn"}},{q="Ist diese Aufgabe ausschließlich für Schneider der Allianz bestimmt?",a="Eldrin befindet sich im Herzen des Waldes von Elwynn, im Gebiet der Allianz. Die dortige Unterweisung richtet sich an Handwerker aus den östlichen Siedlungen, die der Allianz angehören.",al={"kann die horde diese quest machen","ist das nur für die allianz"}}},fp="22,192,30.298.0,17.274.0,46.159.0,40.138.0,43.143.0,60.135.0,43.170.0,43.153.0"}
P.entries["quest:97926"] = {n="Making Do",s="Auberdine wartet auf Nachricht aus Sturmwind, doch Hilfe bleibt aus. In Making Do gelangt Alexstons Antwort über das Meer zu Elder Thundris Windwirker.",h="Auberdine wartet auf Nachricht aus Sturmwind, doch Hilfe bleibt aus.",kw={"alexston","alexstons antwort","auberdine","kassen","dunkelküste","making do","sturmwind","thundris windweaver"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie die Entfernung und Sturmwinds knappe Kassen Auberdine ohne finanzielle Unterstützung lassen.",["race:Human"]="Als Mensch seht Ihr, wie Sturmwinds erschöpfte Kassen und die Not in seinen Landen das Königreich daran hindern, Hilfe nach Übersee zu finanzieren.",["race:NightElf"]="Als Nachtelf seht Ihr, dass weder Eure menschlichen Verbündeten jenseits des Meeres noch das nahe Darnassus Auberdine bei seinen örtlichen Schwierigkeiten helfen."},sec={{t="Ein Kurier über das Meer",b="Ihr bringt Alexstons Antwort über das Meer zu Elder Thundris Windwirker in Auberdine. Der Brief bringt weder Truppen noch Hilfsgüter. Sturmwinds Vertreter erklärt, dass die Schatzkammer des Königreichs beinahe leer ist. Die verbliebenen Mittel müssen für die eigenen notleidenden Gebiete reichen."},{t="Dem eigenen Schicksal überlassen",b="Thundris Windwirker nimmt die Antwort mit Bedauern entgegen und dankt Euch für die lange Reise. Sturmwind kann nicht helfen, und auch Darnassus hat keine Hilfe angeboten. Auberdine und seine Bewohner müssen sich auf sich selbst verlassen. Ihr Schicksal liegt in ihren eigenen Händen."}},faq={{q="Was ist die Quest Making Do?",a="Ihr bringt Baros Alexstons Antwort aus Sturmwind über das Meer zu Elder Thundris Windwirker in Auberdine. Sturmwind kann es sich nicht leisten, Hilfe an die Dunkelküste zu schicken.",al={"was ist making do","making do quest","auberdine sturmwind quest"}},{q="Warum verweigert Sturmwind Auberdine die Hilfe?",a="Sturmwinds Kassen sind stark erschöpft, und die verbliebenen Mittel reichen kaum für die eigenen Lande. Das Königreich kann es sich nicht leisten, Auberdine zu helfen.",al={"warum hat sturmwind abgelehnt","sturmwinds kassen knapp","warum hilft sturmwind auberdine nicht"}},{q="Wie reagiert Thundris Windwirker auf die Nachricht?",a="Thundris Windwirker nimmt den Brief mit Trauer entgegen und akzeptiert, dass Auberdine auf sich allein gestellt ist. Weder Sturmwind noch Darnassus leisten Unterstützung.",al={"thundris reaktion auf sturmwind","wie reagiert thundris"}},{q="Wer hat Alexstons Antwort geschickt?",a="Baros Alexston hat die Antwort aus Sturmwind geschickt. Er bekundet sein Mitgefühl für Auberdine und erklärt zugleich, dass sich das Königreich keine Hilfe leisten kann.",al={"wer ist alexston","alexstons antwort absender"}},{q="Hilft Darnassus Auberdine?",a="Thundris Windwirker sagt, dass weder Sturmwind noch Darnassus Auberdine geholfen haben. Die Siedlung muss sich auf sich selbst verlassen.",al={"darnassus hilfe für auberdine","warum hat darnassus nicht geholfen"}},{q="Wo wird Alexstons Antwort überbracht?",a="Alexstons Antwort wird Thundris Windwirker in Auberdine überbracht, der Hafenstadt an der Dunkelküste.",al={"wo endet diese quest","making do abgabeort"}}},fp="9,142,24.276.0,22.238.1,28.155.0,43.153.0,47.154.0,26.138.0,31.114.0,36.102.0"}
P.entries["quest:97927"] = {n="Camping 101: Alchemy",s="Kray in Donnerfels kann Euch lehren, einen Manabrunnen für Euer Alchemistenlager herzustellen. Der Brunnen lockt Heiler und Zauberwirker an, die Erfrischung suchen.",h="Kray in Donnerfels kann Euch lehren, einen Manabrunnen für Euer Alchemistenlager herzustellen.",kw={"alchemist","alchemie","lagerfeuer","lagern","heiler","kray","manabrunnen","zauberwirker","donnerfels"},sec={{t="Ein Brunnen fürs Lager",b="Ein Alchemist kann bei Kray in Donnerfels lernen, einen Manabrunnen herzustellen. Ihr habt Euer Können bewiesen, und Kray kann Euch die Herstellung dieses Lagergegenstands beibringen. Heiler und Zauberwirker werden für einen erfrischenden Schluck kommen. Um in der Wildnis ein Lager aufzuschlagen, braucht Ihr außerdem ein Lagerfeuer, dessen Entfachen Euch ein Koch beibringen kann."}},faq={{q="Wer lehrt mich, einen Manabrunnen herzustellen?",a="Kray in Donnerfels kann Euch lehren, einen Manabrunnen herzustellen, sobald Ihr Euer Können in der Alchemie bewiesen habt.",al={"manabrunnen lehrer","wer ist kray","kray alchemie"}},{q="Wozu dient ein Manabrunnen?",a="Ein Manabrunnen ist ein Lagergegenstand, den Alchemisten herstellen können. Heiler und Zauberwirker kommen zu ihm, um sich zu erfrischen.",al={"manabrunnen verwendung","was bewirkt der brunnen","alchemie lagergegenstand"}},{q="Wo lerne ich, diesen Lagergegenstand herzustellen?",a="Ihr sprecht mit Kray in Donnerfels, um die Herstellung des Manabrunnens zu erlernen.",al={"wo ist kray","donnerfels alchemie","manabrunnen standort"}},{q="Was brauche ich noch, um ein Lager aufzuschlagen?",a="Ein Lager braucht ein Lagerfeuer, bevor es aufgeschlagen werden kann. Ein Koch kann Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","wie ein lager aufschlagen","feuer fürs lager"}},{q="Kann ich den Manabrunnen in der Stadt ausprobieren?",a="Die Abschlussanweisungen besagen, dass die meisten Leute Lager mitten in der Stadt nicht mögen, also müsst Ihr zum Ausprobieren in die Wildnis gehen.",al={"lager in der stadt","wo manabrunnen ausprobieren","manabrunnen testen"}}},fp="20,144,15.311.0,36.100.0,24.99.0,36.66.0,35.82.0,33.138.0"}
P.entries["quest:97928"] = {n="Camping 101: Blacksmithing",s="Ihr seid bereit, einen Schleifstein herzustellen und ihn in der Wildnis auszuprobieren. Zuerst braucht Ihr ein Lagerfeuer, um ein Lager aufzuschlagen.",h="Ihr seid bereit, einen Schleifstein herzustellen und ihn in der Wildnis auszuprobieren.",kw={"schmiedekunst","lagerfeuer","lagern","koch","schleifstein","wildnis"},ang={["profession:Blacksmithing"]="Ihr könnt jetzt einen Schleifstein herstellen, um ihn in der Wildnis zu benutzen.",["profession:Cooking"]="Ein Koch kann Euch beibringen, wie Ihr ein Lagerfeuer macht."},sec={{t="Bereit fürs Lager",b="Ihr könnt jetzt einen Schleifstein herstellen. Nehmt ihn zum Ausprobieren mit in die Wildnis, wo Ihr fern vom Ortskern ein Lager aufschlagen könnt. Bringt ein Lagerfeuer mit. Ein Koch kann Euch beibringen, wie Ihr eines macht."}},faq={{q="Was kann ich jetzt herstellen?",a="Ihr könnt jetzt Euren eigenen Schleifstein herstellen.",al={"schleifstein","schmiedekunst herstellen","was stelle ich her"}},{q="Wo kann ich den Schleifstein ausprobieren?",a="Ihr könnt ihn in der Wildnis ausprobieren, wo sich fern vom Ortskern Lager aufschlagen lassen.",al={"wo ausprobieren","schleifstein standort","wo lagern"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr ein Lager aufschlagen könnt.",al={"lagerfeuer benötigt","wie ein lager aufschlagen","grundlagen des lagerns"}},{q="Wer kann mir beibringen, ein Lagerfeuer zu machen?",a="Ein Koch kann Euch beibringen, ein Lagerfeuer zu machen.",al={"lagerfeuer lernen","wer lehrt feuermachen","kochfeuer"}}},fp="26,119,13.198.0,21.44.0,37.89.0,38.47.0,36.40.0"}
P.entries["quest:97931"] = {n="Camping 101: First Aid",s="Ihr seid bereit, eine Verbandtasche herzustellen, und braucht nun einen Ort, um sie auszuprobieren.",h="Ihr seid bereit, eine Verbandtasche herzustellen, und braucht nun einen Ort, um sie auszuprobieren.",kw={"lagerfeuer","lagern","kochen","erste hilfe","verbandtasche","wildnis"},sec={{t="Ein Platz zum Lagern",b="Ihr könnt die Tasche herstellen, aber die meisten Leute würden lieber nicht mitten in der Stadt lagern. Nehmt sie also mit in die Wildnis. Bevor Ihr Euer Lager aufschlagt, braucht Ihr ein Lagerfeuer. Die meisten Köche können Euch beibringen, wie Ihr eines macht."}},faq={{q="Wo kann ich die Verbandtasche ausprobieren?",a="Probiert die Verbandtasche in der Wildnis aus, wo sich die Leute seltener an einem Lager stören.",al={"wo tasche ausprobieren","verbandtasche ort"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr ein Lager aufschlagen könnt.",al={"lagerfeuer benötigt","was zum lagern"}},{q="Wer kann mir beibringen, ein Lagerfeuer zu machen?",a="Die meisten Köche können Euch beibringen, wie Ihr ein Lagerfeuer macht.",al={"lagerfeuer machen","lagerfeuer lehrer"}}},fp="22,74,15.205.0,34.90.0,38.47.0,36.48.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="In Mulgore können Angler mit ihrem Handwerk Lager in der Wildnis behaglicher machen. Zeigt Uthan Stillwater im Dorf der Bluthufe Euer Können mit Rute und Rolle, und er lehrt Euch, ein Fischglas für Reisende herzustellen, die draußen rasten.",h="In Mulgore können Angler mit ihrem Handwerk Lager in der Wildnis behaglicher machen.",kw={"dorf der bluthufe","lagerfeuer","lagern","camping 101: fishing","fischglas","angeln","mulgore","uthan stillwater"},ang={["faction:Horde"]="Als Angler der Horde auf Reisen durch Mulgore könnt Ihr bei Uthan Stillwater im Dorf der Bluthufe lernen, Einrichtungsgegenstände für das Lager herzustellen.",["profession:Cooking"]="Ein ordentlicher Lagerplatz braucht ein Lagerfeuer. Grundkenntnisse der Kochkunst ergänzen das Lager eines Fischers in der Wildnis auf natürliche Weise."},sec={{t="Angeln in der Wildnis",b="Angler, die durch Mulgore reisen, können ihren ruhigen Zeitvertreib im Lager nützlich einsetzen. Wenn Ihr Euer Können mit Rute und Rolle bewiesen habt, sucht Uthan Stillwater im Dorf der Bluthufe auf. Er lehrt geschickte Fischer, ein Fischglas herzustellen, das einem Lagerplatz etwas Behaglichkeit verleiht."},{t="Annehmlichkeiten im Lager",b="Ein Fischglas bringt ein wenig Freude auf eine beschwerliche Reise. Seine ruhige Ausstrahlung macht einen Rastplatz in der Wildnis angenehmer und hebt die Stimmung derer, die sich dort versammeln. Bessere Stimmung bedeutet schärfere Instinkte und größere Widerstandskraft im Kampf."},{t="Lagerfeuer und freies Land",b="Ein Lagerplatz gehört ins freie Land, nicht in eine Siedlung wie das Dorf der Bluthufe. Das Fischglas lässt sich nur in der Wildnis ausprobieren. Ein Lager braucht auch ein ordentliches Feuer, also sucht einen Kochkunstlehrer auf, um die Grundlagen des Feuermachens zu erlernen, bevor Ihr eines aufschlagt."}},faq={{q="Was bewirkt das Fischglas auf einem Lagerplatz?",a="Ein Fischglas ist ein von geschickten Fischern hergestellter Einrichtungsgegenstand für das Lager. Es bringt Reisenden, die in der Wildnis rasten, Behaglichkeit und Freude, hebt ihre Stimmung und hilft ihnen, im Kampf wachsam zu bleiben.",al={"fischglas lager","was bewirkt das fischglas","fischglas nutzen"}},{q="Wer lehrt das Rezept für das Fischglas?",a="Uthan Stillwater lehrt dieses Handwerk im Dorf der Bluthufe in Mulgore. Er unterrichtet Angler, die bereits ihr Können beim Angeln bewiesen haben.",al={"wo fischglas erlernen","wer lehrt fischglas","uthan stillwater fundort"}},{q="Warum könnt Ihr innerhalb einer Siedlung kein Lager aufschlagen?",a="Siedlungen wie das Dorf der Bluthufe erlauben Reisenden nicht, im Ort Lager aufzuschlagen. Schlagt Euer Lager stattdessen in der offenen Wildnis auf.",al={"lager im ort","warum kein lager im dorf der bluthufe","lagern in städten"}},{q="Was wird noch benötigt, um ein Lager aufzuschlagen?",a="Ein ordentlicher Lagerplatz braucht ein Lagerfeuer. Wenn Ihr nicht wisst, wie Ihr eines entzündet, sucht einen Kochkunstlehrer auf, um die Grundlagen des Feuermachens zu erlernen.",al={"lagerfeuer voraussetzung fürs lagern","feuer fürs lager nötig","grundlagen des lagerns feuer"}},{q="Welche Voraussetzungen müsst Ihr erfüllen, bevor Ihr die Herstellung des Fischglases erlernen könnt?",a="Ihr müsst Euer Können beim Angeln beweisen, bevor Uthan Stillwater Euch lehrt, Einrichtungsgegenstände für das Lager herzustellen. Wenn Ihr noch Angelanfänger seid, verbringt zunächst Zeit am Wasser, um Euer Handwerk zu verfeinern.",al={"angelkönnen fürs lagern","wann ist das fischglas erhältlich","camping 101: fishing voraussetzungen"}},{q="Warum sollte ein Abenteurer beim Lagern ein Fischglas dabeihaben wollen?",a="Ein Fischglas bringt einen Hauch von Heimat in ein hartes, ermüdendes Leben auf Reisen. Am Feuer einen Fisch zu beobachten, kann Freude bereiten und die Stimmung eines Abenteurers heben.",al={"warum fischglas zum lagern mitbringen","lager fischglas hintergrund"}}},fp="20,218,19.257.0,16.237.0,25.248.0,42.185.0,33.128.0,45.124.0,39.128.0,59.169.0,55.146.0"}
P.entries["quest:97933"] = {n="Camping 101: Herbalism",s="Komin Winterhoof in Donnerfels kann Euch lehren, eine Räucherkerze für Euer Lager herzustellen. Kräuterkunde eröffnet Euch den Weg zu einem nützlichen Hilfsmittel für Heiler und Zauberwirker.",h="Komin Winterhoof in Donnerfels kann Euch lehren, eine Räucherkerze für Euer Lager herzustellen.",kw={"lagerfeuer","lagern","grundlagen des lagerns","kräuterkunde","räucherkerze","komin winterhoof","donnerfels"},ang={["profession:Cooking"]="Als Koch könnt Ihr die Grundlagen des Entzündens eines Lagerfeuers vermitteln, das für ein Lager benötigt wird.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr dank Eurer Fertigkeit lernen, eine Räucherkerze fürs Lager herzustellen."},sec={{t="Eine Kerze fürs Lager",b="Ein Lehrer in Donnerfels bittet Euch, Eure Kräuterkundekenntnisse einzusetzen, um ein Lagerhandwerk zu erlernen. Die Räucherkerze kann die Willenskraft von Heilern und Zauberwirkern stärken. Ihr geht mit dem Wissen, wie Ihr eine herstellt, doch zum Ausprobieren braucht Ihr ein Lager außerhalb der Stadt und ein Lagerfeuer dazu."}},faq={{q="Wer lehrt das Lagerhandwerk?",a="Komin Winterhoof in Donnerfels lehrt Euch, eine Räucherkerze herzustellen.",al={"lagern kräuterkundelehrer","wer lehrt räucherkerze"}},{q="Was hat Kräuterkunde mit dem Lagern zu tun?",a="Wenn Ihr Eure Fertigkeit in Kräuterkunde unter Beweis stellt, könnt Ihr lernen, eine Räucherkerze für Euer Lager herzustellen.",al={"kräuterkunde lagergegenstand","kräuterkunde lagern"}},{q="Wozu dient eine Räucherkerze?",a="Eine Räucherkerze kann die Willenskraft von Heilern und Zauberwirkern stärken.",al={"räucherkerze verwendung","lagerkerze"}},{q="Wo kann ich die Kerze ausprobieren?",a="Ihr müsst in die Wildnis ziehen, um sie auszuprobieren, denn die meisten Leute mögen keine Lager mitten in der Stadt.",al={"wo räucherkerze ausprobieren","lager in der stadt"}},{q="Brauche ich noch etwas für das Lager?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Die meisten Köche können Euch beibringen, eines zu entzünden.",al={"lagerfeuer benötigt","was noch fürs lager"}}},fp="22,165,17.285.0,27.73.0,44.89.0,30.68.0,27.109.0,33.86.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="Im Dorf der Bluthufe lernen Lederverarbeiter, ein Zelt als Schutz für unterwegs zu fertigen. Chaw Stronghide lehrt dieses Handwerk jene, die bereit sind, schwerere Häute und robuste Nähte zu verarbeiten.",h="Im Dorf der Bluthufe lernen Lederverarbeiter, ein Zelt als Schutz für unterwegs zu fertigen.",kw={"dorf der bluthufe","lagerfeuer","camping 101","chaw stronghide","lederverarbeitung","mulgore","unterschlupf","zelt"},ang={["faction:Horde"]="Reisende der Horde, die Kalimdors weite, trockene Landstriche durchqueren, verlassen sich fernab befestigter Stützpunkte auf robuste Lagerausrüstung.",["profession:Cooking"]="Kochkunstlehrer zeigen Reisenden, wie sie ein ordentliches Lagerfeuer entfachen, das den warmen Lagerplatz um ein Lederzelt vervollständigt.",["race:Tauren"]="Tragbare Unterkünfte aus Leder zu fertigen, entspricht den nomadischen Traditionen der Taurenstämme und ihrem überlieferten Wissen vom Überleben in der Wildnis von Mulg ores Ebenen."},sec={{t="Schutz in den offenen Ebenen",b="Überall in Kalimdor können Lederverarbeiter, die ein stabiles Zelt nähen können, Schutz vor der Mittagssonne und dem Regen der Prärie finden. Ein Zelt bietet müden Reisenden auch einen Ort zum Rasten und Erholen, bevor sie erneut die offenen Ebenen durchqueren."},{t="Das Handwerk von Chaw Stronghide",b="Im Dorf der Bluthufe in Mulgore unterrichtet Chaw Stronghide Lederverarbeiter, die mit schwereren Häuten und robusten Nähten umgehen können. Sobald sie ihr Können beweisen, zeigt er ihnen, wie sie ein haltbares Zelt für Reisen fernab der Zivilisation fertigen."},{t="Lager in der Wildnis",b="Wählt Euren Lagerplatz mit Bedacht und Rücksicht auf die örtlichen Siedlungen. Dorfbewohner sehen es ungern, wenn Reisende an zentralen Wegen und Durchgangsstraßen lagern, also bringt Euer Zelt ins wilde Grenzland. Ein ordentliches Lager braucht auch ein Feuer. Fragt einen erfahrenen Koch, wie Ihr eines entfacht."}},faq={{q="Was lernen Lederverarbeiter bei dieser Quest?",a="Lederverarbeiter lernen, ein Zelt für ihre Reisen zu fertigen. Es schützt sie vor rauem Wetter und bietet ihnen einen Rastplatz in der Wildnis.",al={"lederverarbeitung zelt quest","was lehrt camping 101","lederverarbeitung lagergegenstand"}},{q="Wer lehrt Lederverarbeiter, Lagerzelte zu fertigen?",a="Chaw Stronghide lehrt im Dorf der Bluthufe in Mulgore die Zeltherstellung. Er gibt dieses Handwerk weiter, sobald ein Lederverarbeiter beweist, dass er mit schwereren Häuten und robusten Nähten umgehen kann.",al={"wer lehrt zeltherstellung","chaw stronghide zelt","lederverarbeitung zeltlehrer"}},{q="Wo können Reisende ihre Lagerzelte aufschlagen?",a="Schlagt Euer Lager in der offenen Wildnis auf, fernab bewohnter Siedlungen. Stadtbewohner und Dorfälteste dulden keine privaten Unterkünfte auf Stadtplätzen oder an Straßen.",al={"wo zelt aufschlagen","lagern in der stadt erlaubt","zeltplatzierung"}},{q="Warum braucht man neben einem Zelt auch ein Lagerfeuer?",a="Ein Lagerfeuer bringt Wärme und Schutz in ein Lager in der Wildnis. Sucht einen erfahrenen Koch auf, um zu lernen, wie Ihr eines entfacht, bevor Ihr in die Wildnis aufbrecht.",al={"warum ein lagerfeuer nötig ist","kochkunst lagerfeuer zelt","zelt und feuer"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen von Mulgore, südlich von Donnerfels am Ufer des Stonebullsees. Die Taurensiedlung dient Jägern, Sammlern und Handwerkern und bietet Reisenden, die die Ebenen erkunden, Ausbildung, Handelswaren und Orientierung.",al={"wo liegt das dorf der bluthufe","dorf der bluthufe lage","chaw stronghide finden"}},{q="Braucht Ihr Kochkenntnisse, um einen ordentlichen Lagerplatz zu unterhalten?",a="Kochkenntnisse sind nicht nötig, um ein Lederzelt zu nähen, doch Köche lehren Reisende, Lagerfeuer zu entfachen. Ein Feuer vervollständigt ein Lager im Freien, wärmt die Nachtluft und ermöglicht Reisenden, auf langen Reisen Essen zuzubereiten.",al={"kochkunst zum lagern nötig","kochkunst nötig","lagerfeuer kochkunst grundlagen"}},{q="Welche Vorteile bietet ein Lagerzelt Reisenden?",a="Ein Zelt schützt Reisende vor starker Hitze und heftigem Regen. Wer darin rastet, bleibt bei der Erkundung ferner Gebiete erfrischt und wachsam.",al={"vorteile eines lagerzelts","warum ein zelt fertigen","was bewirkt ein zelt"}}},fp="27,181,28.219.0,28.228.0,17.253.0,42.140.0,51.167.0,44.162.0,42.141.0,35.247.0,56.202.0,53.147.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="In Donnerfels können Bergleute lernen, ihr Handwerk in der Wildnis einzusetzen. Brek Steinhuf lehrt sie, einen Magnetstein zu formen, der jenen Kraft verleiht, die an einem Lagerfeuer rasten.",h="In Donnerfels können Bergleute lernen, ihr Handwerk in der Wildnis einzusetzen.",kw={"brek steinhuf","lager","lagerfeuer","camping 101: mining","magnetstein","bergbau","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr jenen, die an Eurem Lagerfeuer rasten, die Kraft eines Magnetsteins für bevorstehende Kämpfe verleihen.",["profession:Mining"]="Als Bergmann könnt Ihr Euer Sammelhandwerk in der Wildnis einsetzen, indem Ihr einen Magnetstein für ein Expeditionslager anfertigt.",["race:Tauren"]="Als Tauren könnt Ihr von Brek Steinhuf auf den Tafelbergen von Donnerfels lernen und dabei auf das Wissen der Tauren über Stein und die Bearbeitung der Erde zurückgreifen."},sec={{t="Ehrliche Arbeit im Erdreich",b="Dem Bergbau mag der Glanz hoher Arkanmagie fehlen, doch ist er eine ehrliche Arbeit, die überall auf Azeroth zu finden ist. Bergleute gewinnen nützliche Mineralien und dichtes Gestein aus tiefen Felswänden. Aus diesen Materialien entstehen Waffen und Rüstungen, und nun erfüllen sie auch draußen einen Zweck. Ein Bergmann kann Stein zu robusten Werkzeugen für ein Lager in der Wildnis formen."},{t="Der Magnetstein von Donnerfels",b="Brek Steinhuf in Donnerfels lehrt Bergleute, ihr Handwerk in der Wildnis einzusetzen. Sobald sie Geschick mit der Spitzhacke beweisen, lehrt er sie, einen Lagermagnetstein zu formen. Neben einem offenen Feuer verleiht der Stein jenen, die sich darauf vorbereiten, eine Klinge zu führen, Lebenskraft und einen Vorteil im Kampf."}},faq={{q="Was bewirkt der Magnetstein an einem Lagerplatz?",a="Ein Magnetstein neben einem Lagerfeuer verleiht den dort Versammelten Lebenskraft und Kampfstärke.",al={"magnetstein lagervorteil","magnetstein bonus","was bewirkt der magnetstein"}},{q="Wer ist Brek Steinhuf?",a="Brek Steinhuf lebt in Donnerfels, der Hauptstadt der Tauren. Er lehrt geübte Bergleute, aus Stein und Erz Werkzeuge fürs Lager herzustellen.",al={"brek steinhuf standort","wo ist brek steinhuf","wer lehrt bergbau-lagergegenstand"}},{q="Wann kann ein Bergmann lernen, einen Magnetstein herzustellen?",a="Ein Bergmann muss zunächst Geschick in seinem Handwerk beweisen, bevor Brek Steinhuf ihn lehrt, einen Magnetstein zu formen.",al={"wann magnetstein erlernbar","bergbaubreitung magnetstein"}},{q="Wer profitiert am meisten vom Magnetstein eines Bergmanns?",a="Jeder, der sich darauf vorbereitet, eine Waffe zu führen, kann beim Rasten neben dem Magnetstein von dessen Kraft profitieren.",al={"wer profitiert vom magnetstein","ist der magnetstein für den nahkampf"}},{q="Wie hängt Bergbau mit dem Errichten eines Lagerplatzes zusammen?",a="Bergbau liefert Metall für Schmelzer und Schmiede und ermöglicht Reisenden, Steinwerkzeuge wie Magnetsteine zu formen, um ein Lager in der Wildnis zu stärken.",al={"warum bergbau fürs lagern","wie hilft bergbau dem lager"}},{q="Welchen Zweck hat Camping 101: Mining?",a="In Donnerfels können angehende Bergleute von Brek Steinhuf lernen, Werkzeuge für das Überleben in der Wildnis herzustellen.",al={"camping 101: mining überblick","was ist camping 101: mining"}}},fp="19,171,25.301.0,30.269.0,42.90.0,22.126.0,48.106.0,43.101.0,49.137.0,43.109.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="In Mulgore lernen Kürschner, einen Lagerstuhl für die Rast in der Wildnis herzustellen. Yonn Deepcut lehrt das Handwerk im Dorf der Bluthufe, wo sich erfahrene Balgsammler auf Lager jenseits der Siedlungen vorbereiten.",h="In Mulgore lernen Kürschner, einen Lagerstuhl für die Rast in der Wildnis herzustellen.",kw={"dorf der bluthufe","lagerstuhl","lagerfeuer","camping 101","camping 101: skinning","mulgore","kürschnerei","yonn deepcut"},ang={["faction:Horde"]="Als Kürschner der Horde in Mulgore könnt Ihr das Dorf der Bluthufe besuchen und lernen, aus den gesammelten Bälgen Lagerausrüstung herzustellen.",["profession:Cooking"]="Als Koch könnt Ihr bei Kochkunstlehrern lernen, ein Lagerfeuer für Euer Lager zu entfachen.",["race:Tauren"]="Als Taurenkürschner könnt Ihr bei Yonn Deepcut im Herzen Mulg ores lernen, aus Bestienbälgen Stühle für die Rast in der Wildnis herzustellen."},sec={{t="Bälge der Wildnis",b="Erlegte Bestien liefern Bälge und Pelze, die Kürschner zu nützlicher Ausrüstung verarbeiten können. Aus Leder werden Rüstungen, und Tierhäute können auch Annehmlichkeiten für die Wildnis bieten. Nach langen Wochen auf Reisen durch ungezähmte Lande können Reisende auf Ausrüstung aus diesen Bälgen rasten und im Kampf wachsam bleiben."},{t="Unterricht im Dorf der Bluthufe",b="In Mulgore besuchen Kürschner das Dorf der Bluthufe, um mit Yonn Deepcut zu sprechen. Sobald sie zeigen, dass sie Bestien häuten können, lehrt Yonn sie, einen Lagerstuhl zusammenzunähen. Städte und Dörfer sehen es nicht gern, wenn Reisende auf ihren Straßen Zelte aufschlagen, daher sind die Stühle für die Wildnis gedacht. Ein Lagerfeuer vervollständigt das Lager, und örtliche Köche lehren, wie man eines entfacht."}},faq={{q="Was ist Camping 101: Skinning?",a="In Mulgore lehrt Yonn Deepcut Kürschner im Dorf der Bluthufe, einen Lagerstuhl herzustellen. Zuerst zeigen sie, dass sie Bestien häuten können.",al={"was ist camping 101: skinning","camping kürschnerei quest","was bewirkt diese quest"}},{q="Wer lehrt das Rezept für den Lagerstuhl?",a="Yonn Deepcut lehrt Kürschner im Dorf der Bluthufe in Mulgore, einen Lagerstuhl herzustellen, nachdem sie ihr Können beim Häuten von Bestien bewiesen haben.",al={"wer lehrt lagerstuhl","ansprechpartner für camping kürschnerei","wo ist yonn deepcut"}},{q="Wozu dient ein Lagerstuhl?",a="Ein Lagerstuhl bietet Euch einen bequemen Rastplatz, wenn Ihr in der Wildnis lagert. Das Sitzen hilft Euch, wieder zu Kräften zu kommen und kampfbereit zu bleiben.",al={"was bewirkt ein lagerstuhl","lagerstuhl verwendung","warum einen lagerstuhl herstellen"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Schlagt Euer Lager in der Wildnis auf. Die Bewohner sehen es nicht gern, wenn Reisende in Siedlungen Zelte aufschlagen.",al={"wo ein lager aufschlagen","lagern in der stadt möglich","lagerstuhl in der stadt"}},{q="Was wird noch benötigt, um ein Lager aufzuschlagen?",a="Ein Lager braucht auch ein Lagerfeuer. Örtliche Köche und Kochkunstlehrer lehren Euch, wie Ihr eines entfacht.",al={"was wird noch fürs lager benötigt","lagerfeuer benötigt","feuer zum lagern nötig"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt in Mulgore. Die Taurensiedlung beherbergt Handwerker, darunter auch Kürschnereilehrer.",al={"wo ist das dorf der bluthufe","dorf der bluthufe lage"}}},fp="21,192,17.269.0,28.353.0,30.131.0,34.137.0,30.139.0,28.98.0,39.90.0,35.110.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="In Dolanaar lehrt Cyndra Kindwhisper Alchemisten, wie sie einen Lagerplatz versorgen. Ihr Unterricht verbindet Tränkebrauen mit dem Überleben in der Wildnis und zeigt, wie man einen Manabrunnen für reisende Heiler und Zauberwirker errichtet.",h="In Dolanaar lehrt Cyndra Kindwhisper Alchemisten, wie sie einen Lagerplatz versorgen.",kw={"alchemie","lager","camping 101","camping 101: alchemy","cyndra kindwhisper","dolanaar","manabrunnen","teldrassil"},ang={["faction:Alliance"]="Alchemisten der Allianz, die durch Teldrassil reisen, werden nach Dolanaar geschickt, um magisches Lagerhandwerk für das Überleben in der Wildnis zu erlernen.",["race:NightElf"]="Als nachtelfischer Kräuterkundiger oder Alchemist in Dolanaar könnt Ihr naturverbundene Pflanzenkunde mit Lagerhandwerk verbinden, um Zauberwirker in der Wildnis zu unterstützen."},sec={{t="Lagerhandwerk für Alchemisten",b="Alchemisten lernen, ihr Handwerk auch fern der Werkbank auszuüben. Cyndra Kindwhisper zeigt ihnen, wie sie nützliche Lagereinrichtungen herstellen, die eine Reisegruppe auf langen Wegen durch die Wildnis versorgen können."},{t="Der Manabrunnen von Dolanaar",b="In Dolanaar können Alchemisten, die die Grundlagen beherrschen, Cyndra Kindwhisper aufsuchen. Sie lehrt sie, im Lager einen Manabrunnen zu errichten. Seine erfrischende Magie hilft Heilern und Zauberwirkern, ihr Mana fern von Tavernen und Siedlungen wieder aufzufüllen."}},faq={{q="Was ist Camping 101: Alchemy?",a="Camping 101: Alchemy lehrt angehende Alchemisten in Dolanaar, ihr Handwerk im Lager einzusetzen. Sie lernen, mit ihren Fertigkeiten im Tränkebrauen nützliche Einrichtungen für die Wildnis herzustellen.",al={"was ist camping 101 alchemy","camping 101 alchemy quest","alchemie lagerquest"}},{q="Wer lehrt diese Lagerfertigkeit?",a="Cyndra Kindwhisper unterrichtet Alchemisten in Dolanaar, der Nachtelfensiedlung auf Teldrassil. Sie unterweist jene, die Geschick beim Brauen und beim Herstellen spezieller Lagergegenstände bewiesen haben.",al={"wer ist cyndra kindwhisper","cyndra kindwhisper standort","wo ist cyndra kindwhisper"}},{q="Was ist ein Manabrunnen?",a="Ein Manabrunnen ist eine Lagereinrichtung eines Alchemisten. Er bietet Zauberwirkern und Heilern arkane Erfrischung, wenn sie unterwegs ihre Reserven wieder auffüllen müssen.",al={"was bewirkt ein manabrunnen","manabrunnen lagergegenstand","manabrunnen hintergrundgeschichte"}},{q="Wohin führt Euch diese Quest?",a="Ihr reist nach Dolanaar, einem Nachtelfendorf im Herzen Teldrassils. Es ist eine Anlaufstelle für junge Abenteurer und Handwerkslehrer, die das Laubschattental verlassen.",al={"wo ist dolanaar","wie gelangt man nach dolanaar","dolanaar standort"}},{q="Wem nützt die Lagereinrichtung eines Alchemisten?",a="Reisende Heiler und Zauberwirker profitieren am meisten von Manabrunnen. Die erfrischenden Quellen helfen ihnen, auf beschwerlichen Reisen fern der Städte ihre Reserven wieder aufzufüllen.",al={"wer profitiert von manabrunnen","wer nutzt manabrunnen","manabrunnen zauberwirker"}},{q="Was ist erforderlich, bevor man lernt, einen Manabrunnen herzustellen?",a="Alchemisten müssen zunächst grundlegende Fertigkeiten im Brauen und in der Trankherstellung beweisen. Dann lehrt Cyndra Kindwhisper sie, Lagereinrichtungen wie einen Manabrunnen zu errichten.",al={"wann lässt sich der manabrunnen erlernen","camping 101 voraussetzungen","benötigte fertigkeiten"}}},fp="20,198,26.192.0,25.227.0,29.165.0,31.182.0,20.155.0,31.144.0,51.140.0,54.154.0"}
P.entries["quest:97940"] = {n="Camping 101: Enchanting",s="Ein Ratgeber auf der Lichtung des Orakels verweist Euch auf Verzauberkunst fürs Lager. Eine Verzauberte Laute kann bei einem Aufenthalt in der Wildnis für Unterhaltung sorgen.",h="Ein Ratgeber auf der Lichtung des Orakels verweist Euch auf Verzauberkunst fürs Lager.",kw={"alanna raveneye","handwerk fürs lager","lagern","verzauberte laute","verzauberkunst","die lichtung des orakels","teldrassil"},ang={["profession:Tailoring"]="Als Verzauberer könnt Ihr lernen, eine Verzauberte Laute für Euer Lager herzustellen, nachdem Ihr Euer Können unter Beweis gestellt habt."},sec={{t="Handwerk fürs Lager",b="Ein Verzauberer kann etwas Nützliches für Euer Lager herstellen, und Ihr werdet zu Alanna Raveneye auf der Lichtung des Orakels geschickt. Sie kann Euch beibringen, eine Verzauberte Laute herzustellen, sobald Ihr Euer Können unter Beweis gestellt habt. Sie soll in Euren Ruhepausen für Unterhaltung sorgen, bevor Ihr wieder aufbrecht."}},faq={{q="Wer kann mir beibringen, eine Verzauberte Laute herzustellen?",a="Alanna Raveneye auf der Lichtung des Orakels kann Euch beibringen, eine Verzauberte Laute herzustellen, sobald Ihr Euer Können unter Beweis gestellt habt.",al={"alanna raveneye","wer lehrt laute","lautenlehrer"}},{q="Wozu dient die Verzauberte Laute?",a="Die Verzauberte Laute ist ein Handwerksstück fürs Lager, das in Ruhepausen in der Wildnis für Unterhaltung sorgen soll.",al={"zweck der laute","laute fürs lager","warum verzauberte laute"}},{q="Warum sind Verzauberer in Lagern willkommen?",a="Verzauberer können Dinge verbessern, deshalb sind sie in Lagern in der Wildnis willkommen.",al={"verzauberer beim lagern","verzauberkunst im lager","lagern und verzauberkunst"}},{q="Wo lerne ich, dieses Handwerksstück fürs Lager herzustellen?",a="Ihr könnt von Alanna Raveneye auf der Lichtung des Orakels in Teldrassil lernen.",al={"lehrer auf der lichtung des orakels","wo ist alanna","verzauberkunst ort"}}},fp="23,152,12.295.0,36.123.0,31.97.0,36.76.0,36.69.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="In Dolanaar lernen Reisende, eine Verbandtasche für ihr Lager zusammenzustellen. Byancie lehrt, wie man fernab der Heiler in den Städten Wunden versorgt und einen Lagerplatz findet.",h="In Dolanaar lernen Reisende, eine Verbandtasche für ihr Lager zusammenzustellen.",kw={"byancie","lagerfeuer","lagern","dolanaar","feldsanitäter","erste hilfe","verbandtasche","jäger"},ang={["class:Hunter"]="Als Jäger könnt Ihr Überlebenskunst in der Wildnis mit Erster Hilfe verbinden, um Verletzungen fernab der Zivilisation und der Heiler in den Städten zu versorgen.",["profession:Cooking"]="Als Koch könnt Ihr neben der Zubereitung stärkender Nahrung auch den Umgang mit Feuer erlernen, das Euch im Lager Wärme spendet."},sec={{t="Feldmedizin in der Wildnis",b="In der Wildnis drohen Tierbisse und Schnittwunden durch scharfkantiges Gelände. Waldläufer und andere Reisende sind womöglich weit von der Stadt und ihren medizinischen Vorräten entfernt. Eine Verbandtasche lässt sie kleinere Wunden in einem Lager am Wegesrand versorgen, bevor diese unter freiem Himmel bedrohlich werden."},{t="Unterricht in Dolanaar",b="In Dolanaar lehrt Byancie Reisende mit Triagekenntnissen, medizinische Vorräte für unwegsame Pfade zu packen. Die Bewohner dulden keine Zelte und verstreuten Vorräte im Zentrum einer Siedlung. Reisende müssen sich in den Wald begeben, bevor sie ihr Lager aufschlagen."},{t="Die Feuerstelle des Lagers",b="Ein funktionierendes Lager beginnt mit einer offenen Flamme. Entzündet ein Lagerfeuer, bevor Ihr Verbandtaschen oder Schlafzeug ausbreitet; es spendet Wärme und Schutz. Ein Feuer zu entfachen und zu unterhalten, ist grundlegend für das Überleben in der Wildnis. Ausbilder empfehlen, einen Koch um Unterricht im Feuerentzünden zu bitten, bevor Ihr ein Lager in der Wildnis unterhaltet."}},faq={{q="Wer ist Byancie?",a="Byancie unterrichtet in Dolanaar, einer Siedlung auf Teldrassil. Sie zeigt Reisenden mit medizinischen Kenntnissen, wie man Verbandtaschen für Lager in der Wildnis zusammenstellt.",al={"wer ist byancie","byancies standort","wo ist byancie"}},{q="Was ist eine Verbandtasche fürs Lager?",a="Eine Verbandtasche fürs Lager ist eine medizinische Ausrüstung, die Abenteurer mit Ausbildung in Erster Hilfe herstellen. In einem errichteten Lager bietet sie ihnen einen Platz, um Wunden zu versorgen und im Feld Heilung zu leisten.",al={"was ist eine verbandtasche fürs lager","wie funktioniert eine verbandtasche","verbandtasche fürs lager"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Schlagt Euer Lager in der offenen Wildnis auf, abseits der Ortsgrenzen. Bewohner und Wachen dulden keine vorübergehenden Lager in Siedlungszentren oder auf Stadtplätzen.",al={"lagern in der stadt erlaubt","warum außerhalb der stadt lagern","lagerregeln"}},{q="Warum braucht ein Lager ein Lagerfeuer?",a="Ein Lagerfeuer spendet einem Lager in der Wildnis Wärme, Licht und Sicherheit. Köche und Kochkunstlehrer können Euch beibringen, eines zu entzünden.",al={"warum braucht man ein lagerfeuer","kochen lagerfeuer lager","lagerfeuer als voraussetzung"}},{q="Warum gilt Erste Hilfe für Jäger als zweckmäßig?",a="Jäger reisen oft allein durch abgelegene Wildnis, fernab von Heilern und Templern. Erste Hilfe lässt sie Verletzungen versorgen, während sie Wild aufspüren oder einen Hinterhalt überleben.",al={"warum erste hilfe für jäger","heilung für jäger"}},{q="Wie lernt Ihr, eine Verbandtasche fürs Lager herzustellen?",a="Zeigt grundlegende Kenntnisse in Erster Hilfe und bittet dann Byancie in Dolanaar, Euch das Zusammenstellen einer Verbandtasche fürs Lager beizubringen.",al={"wie bekommt man eine verbandtasche","verbandtaschen herstellen lernen"}}},fp="22,148,27.249.0,19.239.0,22.284.0,15.151.0,32.180.0,28.150.0,38.116.0,50.152.0,50.113.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="In Darnassus werden Angler zu Astaia geschickt, um zu lernen, wie ein Fischglas ein Lager in der Wildnis verschönert. Das Handwerk belohnt geübte Angler mit einem Hauch von Gemütlichkeit für das Leben im Freien.",h="In Darnassus werden Angler zu Astaia geschickt, um zu lernen, wie ein Fischglas ein Lager in der Wildnis...",kw={"astaia","lagerfeuer","lagern","camping 101: fishing","lagerplatz","darnassus","fischglas","angeln"},ang={["faction:Alliance"]="Als Angler der Allianz könnt Ihr Astaia in Darnassus aufsuchen, um die Herstellung von Lagergegenständen zu erlernen.",["profession:Cooking"]="Als Koch hilft Euch Eure Grundausbildung, das Lagerfeuer zu entfachen, das jedes Lager braucht."},sec={{t="Gemütlichkeit am Lagerplatz",b="Angler, die Kalimdor durchqueren, können die ruhigen Stunden am Wasser nutzen. In Darnassus lehrt Astaia erfahrene Angler, ihre Fänge und ihr Können in Annehmlichkeiten für den Lagerplatz zu verwandeln. Dazu gehört ein Fischglas, das im Lager aufgestellt wird und müden Reisenden Freude bringt."},{t="Notwendiges für die Wildnis",b="Ein Lager in der Wildnis braucht mehr als Angelzeug. Ihr könnt es nicht in einem belebten Stadtzentrum oder Stadtviertel aufschlagen, also müsst Ihr offenes Gelände finden. Jedes Lager braucht auch ein wärmendes Feuer. Sucht einen örtlichen Kochkunstlehrer auf, um die Grundlagen des Feuermachens zu erlernen, bevor Ihr Euch für die Nacht niederlasst."}},faq={{q="Wer lehrt Euch, Lagergegenstände für Angler herzustellen?",a="Astaia in Darnassus lehrt erfahrene Angler, ein dekoratives Fischglas fürs Lager herzustellen, sobald sie ihr Können im Angeln unter Beweis stellen.",al={"wer lehrt lagerhandwerk für angler","wo ist astaia","fischglas lehrer"}},{q="Welchen Zweck erfüllt ein Fischglas im Lager?",a="Ein Fischglas bringt rastenden Abenteurern Gemütlichkeit und Freude. Ein zufriedener, gut ausgeruhter Camper kämpft auf Reisen im Freien mit neuer Kraft.",al={"was bewirkt ein fischglas","fischglas im lager nutzen","fischglas lagereinrichtung"}},{q="Könnt Ihr innerhalb von Darnassus oder anderen Städten ein Lager aufschlagen?",a="Ihr könnt kein Lager im Herzen einer Siedlung oder im Stadtzentrum aufschlagen. Begebt Euch in die Wildnis, um ein Lager aufzuschlagen und Einrichtungsgegenstände wie ein Fischglas aufzustellen.",al={"lager in darnassus aufschlagen","wo lager aufschlagen","lagern in städten"}},{q="Was ist vor dem Aufschlagen eines Lagers erforderlich?",a="Ein einfaches Lagerfeuer ist für einen Lagerplatz erforderlich. Sucht einen Kochkunstlehrer auf, um zu lernen, wie Ihr eines entfacht, bevor Ihr ein Lager in der Wildnis errichtet.",al={"was braucht ein lager","wie ein lager aufschlagen","lagerfeuer erforderlich"}},{q="Braucht Ihr Angelfertigkeit, um die Herstellung eines Fischglases zu erlernen?",a="Ja. Ein Abenteurer muss zuerst sein Können im Angeln unter Beweis stellen, um das Handwerk von Astaia zu erlernen.",al={"angelkönnen fürs lagern","wann fischglas erlernen"}},{q="Warum schlagen Abenteurer Lager in der Wildnis auf?",a="Ein Lager bietet Reisenden im Freien einen Ort zum Ausruhen und stärkende Annehmlichkeiten wie ein Fischglas, damit sie in der Wildnis ausgeruht und leistungsfähig bleiben.",al={"warum lager aufschlagen wow forever","vorteile des lagerns"}}},fp="20,180,23.262.0,22.270.0,55.129.0,44.133.0,55.148.0,42.134.0,60.96.0,44.157.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="In Dolanaar lernen Kräuterkundige, aus gesammelten Pflanzen Lagerbedarf herzustellen. Malorne Bladeleaf lehrt geübte Sammler, Räucherkerzen herzustellen, die Heiler und Zauberwirker am Lagerfeuer stärken.",h="In Dolanaar lernen Kräuterkundige, aus gesammelten Pflanzen Lagerbedarf herzustellen.",kw={"camping","camping 101: herbalism","dolanaar","kräuterkunde","räucherkerze","malorne bladeleaf","teldrassil"},ang={["faction:Alliance"]="Als Kräuterkundiger der Allianz nahe Teldrassil könnt Ihr in Dolanaar von einheimischen Nachtelfen Fertigkeiten für das Leben in der Wildnis erlernen.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr gesammelte Pflanzen sowohl für die Alchemie als auch zum Überleben in der Wildnis nutzen und daraus Lagerbedarf wie Räucherkerzen herstellen.",["race:NightElf"]="Als Nachtelf teilt Ihr eine Tradition des Wissens um die stärkenden Eigenschaften der Kräuter der Natur, die in Siedlungen wie Dolanaar gelehrt wird."},sec={{t="Mehr als Blumenpflücken",b="Kräuterkunde kann Reisenden mehr bieten als das Sammeln von Blumen zum Verkauf oder für Alchemisten. In der Wildnis lassen sich geerntete Pflanzen zu nützlicher Lagerausrüstung verarbeiten. Wenn Ihr Eure gesammelten Pflanzen für das Überleben aufbereitet, können sie Euch auf längeren Reisen durch die Wildnis unterstützen."},{t="Dolanaars beruhigende Flamme",b="In Dolanaar lehrt Malorne Bladeleaf geübte Kräuterkundige, eine Räucherkerze herzustellen. Ihre beruhigende Flamme schafft einen Ort der Sammlung und Zuversicht rund um das Lagerfeuer. Heiler und Zauberwirker schätzen ihre belebende Wirkung, während sie zwischen Gefahren ihre magischen Energien wiederherstellen."}},faq={{q="Welchen Zweck hat diese Quest?",a="Geübte Kräuterkundige reisen zu Malorne Bladeleaf in Dolanaar, um zu lernen, wie sie aus gesammelten Pflanzen Lagerbedarf herstellen.",al={"was ist camping 101 herbalism","camping kräuterkunde quest"}},{q="Was bewirkt eine Räucherkerze im Lager?",a="Eine Räucherkerze hebt die Stimmung und schafft eine beruhigende Atmosphäre rund um das Lagerfeuer, die die Konzentration fördert.",al={"was bewirkt eine räucherkerze","räucherkerze nutzen"}},{q="Wer ist Malorne Bladeleaf?",a="Malorne Bladeleaf lehrt geübte Kräuterkundige in Dolanaar, Lagerbedarf herzustellen, darunter Räucherkerzen.",al={"wer lehrt die herstellung von räucherkerzen","wer ist malorne bladeleaf","bladeleaf dolanaar"}},{q="Wohin führt Euch diese Quest?",a="Ihr reist nach Dolanaar, einer Nachtelfensiedlung auf Teldrassil und einem Knotenpunkt für Reisende, Ausbilder und Handwerker des Waldes.",al={"wo ist dolanaar","dolanaar lage"}},{q="Warum sind Räucherkerzen für Magiekundige nützlich?",a="Eine Räucherkerze schafft einen friedlichen Ort der Sammlung, an dem Heiler und Zauberwirker auf Wildnisreisen ihren Geist und ihre magische Kraft erneuern können.",al={"wer profitiert von räucherkerzen","ist die räucherkerze für zauberwirker"}},{q="Welche Voraussetzung müsst Ihr erfüllen, bevor Malorne Bladeleaf Euch unterrichtet?",a="Ihr braucht genügend praktische Erfahrung in der Kräuterkunde, bevor Malorne Bladeleaf Euch lehrt, Lagerbedarf herzustellen.",al={"wann ist die herstellung von räucherkerzen erlernbar","kräuterkunde fertigkeitsvoraussetzung camping"}}},fp="22,203,25.245.0,30.276.0,34.112.0,42.93.0,25.106.0,31.118.0,46.155.0,57.107.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="Auf Teldrassil können Lederverarbeiter lernen, einen Unterschlupf für unterwegs herzustellen. Sucht Nadyia Maneweaver an der Straße zwischen Dolanaar und Darnassus auf, wo sie lehrt, Zelte zu fertigen, die Reisende trocken und kühl halten.",h="Auf Teldrassil können Lederverarbeiter lernen, einen Unterschlupf für unterwegs herzustellen.",kw={"lagerfeuer","zelten","darnassus","dolanaar","lederverarbeitung","nadyia maneweaver","zelt","wildnis"},ang={["class:Rogue"]="Als Schurke seid Ihr in der Wildnis auf Ruhe und Schutz angewiesen, um wachsam zu bleiben. Ein Lederzelt kann Euch helfen, beides zu finden.",["profession:Cooking"]="Für ein richtiges Lager braucht Ihr ein wärmendes Lagerfeuer. Kochkunstlehrer im ganzen Land zeigen Euch, wie Ihr eines entfacht."},sec={{t="Schutz in der Wildnis",b="Überall in Kalimdor kann unter freiem Himmel raues Wetter drohen. Geschickte Lederverarbeiter lernen, Häute und Pelze zu robusten Unterkünften zu verarbeiten, die Reisenden einen sicheren Rastplatz bieten, wohin der Weg auch führt. Ein Zelt ermöglicht Wanderern, fernab der Gasthäuser die nötige Ruhe zu finden."},{t="Die Straße von Dolanaar",b="Nadyia Maneweaver unterrichtet geübte Lederverarbeiter an der Waldstraße zwischen Dolanaar und Darnassus. Sie zeigt ihnen, wie man ein robustes Zelt für unterwegs näht. Zu einem richtigen Lager gehört neben dem Zelt ein Lagerfeuer, und Köche lehren diese Kunst. Schlagt den Unterschlupf in der freien Wildnis auf, abseits der Straßen in den Ortschaften."}},faq={{q="Wer lehrt diese Lagerfertigkeit?",a="Nadyia Maneweaver lehrt die Lagerfertigkeit an der Straße von Dolanaar nach Darnassus auf Teldrassil.",al={"wer vergibt camping 101 leatherworking","wer lehrt camping 101","nadyia maneweaver"}},{q="Was lernen Lederverarbeiter durch diese Quest?",a="Lederverarbeiter lernen, ein Zelt herzustellen, das Reisende bei Hitze kühl und bei Regen trocken hält.",al={"was lehrt camping 101","zeltrezept","was lernt man bei camping 101"}},{q="Wo könnt Ihr ein Lagerzelt aufschlagen?",a="Schlagt Zelte in der freien Wildnis auf, außerhalb von Siedlungen und Stadtzentren.",al={"wo kann man ein zelt aufschlagen","kann man in der stadt ein zelt aufschlagen","zelten in städten"}},{q="Was braucht Ihr außerdem, um ein Lager aufzuschlagen?",a="Ein Lager braucht neben einem Zelt auch ein brennendes Lagerfeuer. Kochkunstlehrer lehren die Kunst, eines zu entfachen.",al={"was braucht man für einen lagerplatz","lagerfeuer als voraussetzung","braucht man ein lagerfeuer für ein zelt"}},{q="Warum ist ein Zelt für Reisende nützlich?",a="Ein Zelt schützt Reisende vor dem Wetter und bietet ihnen Ruhe, damit sie fernab der Gasthäuser wachsam bleiben.",al={"warum ein zelt bauen","erholungsvorteil durch ein zelt","warum ein lager aufschlagen"}},{q="Wo befindet sich Nadyia Maneweaver?",a="Nadyia Maneweaver befindet sich an der Hauptstraße von Dolanaar nach Darnassus, der Hauptstadt der Nachtelfen.",al={"wo ist nadyia maneweaver","nadyias standort","lehrer an der straße nach darnassus"}}},fp="27,210,25.256.0,22.297.0,31.104.0,45.97.0,32.73.0,39.94.0,42.102.0,35.95.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="Ihr werdet nach Auberdine geschickt, um eine neue Anwendung des Bergbaus kennenzulernen. Dort lehrt Kurdram Stonehammer erfahrene Bergleute, einen Magnetstein herzustellen, der Verbündete stärkt, die sich um ein Lagerfeuer versammeln.",h="Ihr werdet nach Auberdine geschickt, um eine neue Anwendung des Bergbaus kennenzulernen.",kw={"auberdine","lagerhandwerk","lagerfeuer","camping 101: mining","dunkelküste","kurdram stonehammer","magnetstein","bergbau"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Kurdram Stonehammer in Auberdine an der Dunkelküste finden. Er lehrt jene das Lagerhandwerk, die durch den Norden Kalimdors reisen.",["profession:Mining"]="Als Bergmann könnt Ihr groben Stein zu einem Lager-Magnetstein formen, der Reisenden unterwegs hilft und Kämpfer an vorderster Front stärkt."},sec={{t="Die praktische Kunst von Erde und Stein",b="Bergbau dient mehr als nur dem Verhütten von Barren und dem Schmieden von Rüstungen. Erfahrene Prospektoren formen rohe Erde und magnetisches Erz zu Campingausrüstung, damit Reisende gut befestigte Feuerstellen in der Wildnis errichten können. Diese Einführung zeigt Bergleuten eine praktische Anwendung ihres Handwerks."},{t="Ein Lehrmeister in Auberdine",b="In Auberdine, der Küstenstadt an der Dunkelküste, suchen vielversprechende Bergleute Kurdram Stonehammer auf. Sobald ein Bergmann Hingabe und Können beweist, lehrt Kurdram ihn die Herstellung eines Lager-Magnetsteins. Neben einem Feuer stärkt der Stein die kriegerischen Gefährten, die sich in der Nähe versammeln."}},faq={{q="Was ist Camping 101: Mining?",a="Ihr werdet nach Auberdine geschickt, um Kurdram Stonehammer zu finden. Sobald Ihr Euer Können im Bergbau beweist, lehrt er Euch, einen Magnetstein herzustellen, der ein Lager stärkt.",al={"was ist diese quest","camping 101: mining ziel","was tun bei camping bergbau"}},{q="Wer ist Kurdram Stonehammer?",a="Kurdram Stonehammer ist ein Handwerker in Auberdine an der Dunkelküste. Er lehrt qualifizierte Bergleute, Campingausrüstung herzustellen, darunter auch Magnetsteine.",al={"wer ist kurdram stonehammer","bergbaulehrer auberdine","kurdram stonehammer standort"}},{q="Was ist ein Lager-Magnetstein?",a="Bergleute stellen einen Lager-Magnetstein her, um ihn neben einem Lagerfeuer aufzustellen. Er stärkt Kämpfer, die sich in der Nähe versammeln und körperliche Angriffe einsetzen.",al={"was bewirkt ein magnetstein","lager-magnetstein wirkung","camping oomph stärkungszauber"}},{q="Wo findet diese Quest statt?",a="Auberdine ist ein Küstenhafen an der Dunkelküste, ein Hafen der Allianz und ein Knotenpunkt im Norden Kalimdors. Kurdram Stonehammer lebt dort und lehrt Bergleute das Lagerhandwerk.",al={"wo ist auberdine","auberdine standort","wie nach auberdine gelangen"}},{q="Wer profitiert von einem Lager-Magnetstein?",a="Nahkämpfer schätzen einen Lager-Magnetstein besonders. Seine Kraft verleiht Reisenden, die sich um das Feuer versammeln, mehr Stärke im Kampf.",al={"wer profitiert vom magnetstein","ist ein magnetstein gut für krieger","lager-magnetstein stärkungszauber ziel"}},{q="Wann könnt Ihr lernen, den Magnetstein herzustellen?",a="Kurdram Stonehammer lehrt Euch die Herstellung von Magnetsteinen, sobald Ihr genügend Können im Bergbau beweist.",al={"wann magnetsteinherstellung erlernen","bergbaufertigkeit für lager-magnetstein","fertigkeitsvoraussetzung"}}},fp="19,180,36.263.0,21.270.0,28.148.0,27.146.0,25.105.0,33.159.0,35.134.0,42.88.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="Draußen in der Wildnis lernt Ihr, einen Lagerstuhl herzustellen und einen Lagerplatz vorzubereiten. Ihr braucht Häute, freies Gelände fern der Stadt und ein Lagerfeuer.",h="Draußen in der Wildnis lernt Ihr, einen Lagerstuhl herzustellen und einen Lagerplatz vorzubereiten.",kw={"lagerstuhl","lagerfeuer","camping 101","camping 101: skinning","kochen","kürschnerei","wildnis"},ang={["profession:Cooking"]="Lernt die Grundlagen des Kochens bei einem Kochlehrer. Zu wissen, wie man ein Lagerfeuer entfacht, ist unerlässlich, wenn Ihr in der Wildnis einen Lagerplatz einrichtet."},sec={{t="Annehmlichkeiten für unterwegs",b="Unterwegs gesammelte Häute lassen sich gut nutzen. Mit den nötigen Materialien lernt Ihr, einen tragbaren Lagerstuhl für Reisen durch Azeroth herzustellen. Stadtbewohner haben etwas dagegen, wenn Reisende mitten in der Stadt ihr Lager aufschlagen, also übt dieses Handwerk draußen in der freien Wildnis aus."},{t="Das unverzichtbare Lagerfeuer",b="Ein Lagerfeuer ist das Erste, was ein Lagerplatz in der Wildnis braucht. Seine Flammen spenden Wärme und Schutz vor den Elementen. Wenn Ihr die Grundlagen des Kochens noch nicht beherrscht, sucht einen Kochlehrer auf, um zu lernen, wie Ihr unterwegs ein Feuer entfacht."}},faq={{q="Was lernt Ihr in Camping 101: Skinning?",a="Ihr lernt, einen tragbaren Lagerstuhl herzustellen, um Euch in der Wildnis auszuruhen.",al={"was bekomme ich","was bringt camping 101","lagerstuhl herstellen"}},{q="Könnt Ihr in der Stadt ein Lager aufschlagen?",a="Stadtbewohner haben im Allgemeinen etwas gegen Lager auf Stadtplätzen und in den Straßen. Begebt Euch in die Wildnis, um Euer Lager aufzuschlagen.",al={"kann ich in der stadt lagern","zelt in stormwind aufschlagen","lagern in städten"}},{q="Braucht Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ja. Ein Lagerplatz braucht ein brennendes Lagerfeuer. Kochlehrer in ganz Azeroth können Euch beibringen, eines zu entfachen.",al={"feuer fürs lager nötig","wie lagerfeuer entfachen","feuer für lagerstuhl"}},{q="Wo könnt Ihr lernen, ein Lagerfeuer zu entfachen?",a="Kochlehrer können Euch beibringen, Speisen zuzubereiten und mit Feuerstein und Holz ein einfaches Lagerfeuer zu entfachen.",al={"wer lehrt lagerfeuer","lehrer für kochfeuer","wo kochfeuer lernen"}},{q="Warum müsst Ihr in die Wildnis ziehen, um ein Lager aufzuschlagen?",a="Auf freiem Gelände in der Wildnis könnt Ihr Euer Lager aufschlagen, ohne Stadtbewohner zu stören oder örtliche Straßen und Siedlungen zu versperren.",al={"warum wildnis nötig","wo kann ich den lagerstuhl benutzen","wo lager aufschlagen"}},{q="Was hat Kürschnerei mit der Herstellung eines Lagerstuhls zu tun?",a="Kürschner verarbeiten Häute und Leder, die sie von Wildtieren gewinnen. Diese Materialien eignen sich für tragbare Sitzgelegenheiten im Freien wie einen Lagerstuhl.",al={"zusammenhang kürschnerei und lagern","warum kürschnerei für stuhl","kürschnerei lagerstuhl"}}},fp="21,132,21.243.0,22.217.0,45.70.0,30.105.0,36.98.0,43.95.0,53.124.0,48.118.0"}
P.entries["quest:97950"] = {n="Camping 101: Tailoring",s="Ein Schneider kann lernen, ein Rallying Banner für ein Lager herzustellen. Trianna in Darnassus lehrt Euch das Schnittmuster, sobald Ihr Euer Können in der Schneiderei bewiesen habt.",h="Ein Schneider kann lernen, ein Rallying Banner für ein Lager herzustellen.",kw={"lagerfeuer","lagern","darnassus","fraktionsbanner","rallying banner","schneiderei","trianna"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr lernen, ein Rallying Banner für Euer Lager herzustellen, nachdem Ihr Euer handwerkliches Können bewiesen habt."},sec={{t="Ein Banner fürs Lager",b="Jemand, der die Schneiderei schätzt, verweist Euch an Trianna in Darnassus. Sie kann Euch lehren, ein Fraktionsbanner für Euer Lager herzustellen, sobald Ihr Eure Fertigkeit in der Schneiderei bewiesen habt. Ein Banner kann auf dem Schlachtfeld Inspiration und Moral stärken, und ein geschickter Schneider kann lernen, eines herzustellen."},{t="Ein Lager aufschlagen",b="Mit Triannas Unterweisung könnt Ihr ein Rallying Banner herstellen. Sucht Euch zum Ausprobieren einen Ort in der Wildnis, denn die meisten Leute mögen keine Lager mitten in der Stadt. Bringt auch ein Lagerfeuer mit; ein Koch kann Euch beibringen, wie Ihr eines entfacht."}},faq={{q="Wer lehrt Schneider, ein Lagerbanner herzustellen?",a="Trianna in Darnassus kann Euch lehren, ein Fraktionsbanner für Euer Lager herzustellen, nachdem Ihr Eure Fertigkeit in der Schneiderei bewiesen habt.",al={"schneider banner lehrer","trianna schneiderei","lagerbanner lehrer"}},{q="Was kann ein Schneider für ein Lager herstellen?",a="Ein geschickter Schneider kann lernen, ein Rallying Banner für ein Lager herzustellen.",al={"schneider lagergegenstand","schneiderei lager herstellen","welches banner schneiderei"}},{q="Warum ein Rallying Banner herstellen?",a="Ein inspirierendes Banner kann Euch helfen, voller Tatkraft zu bleiben, und Inspiration und Moral sind auf dem Schlachtfeld wichtig.",al={"banner zweck","rallying banner warum","banner moral"}},{q="Wo kann ich meine Lagerausstattung ausprobieren?",a="Zum Abschluss wird geraten, das Banner in der Wildnis auszuprobieren, denn die meisten Leute mögen keine Lager mitten in der Stadt.",al={"wo banner ausprobieren","lagerplatz","banner testort"}},{q="Brauche ich ein Lagerfeuer?",a="Ein Lager braucht ein Lagerfeuer, und die meisten Köche können Euch beibringen, eines zu entfachen.",al={"lagerfeuer fürs lager","feuer nötig","wie lagerfeuer entfachen"}}},fp="22,137,17.279.0,15.217.0,36.115.0,34.65.0,27.104.0,31.114.0,21.66.0"}
P.entries["quest:97951"] = {n="Camping 101: Alchemy",s="In Eurem Lager können Alchemisten lernen, einen Manabrunnen herzustellen. Carolai Anise in Brill lehrt Euch die Herstellung, sobald Ihr Eure Fertigkeit in Alchemie bewiesen habt.",h="In Eurem Lager können Alchemisten lernen, einen Manabrunnen herzustellen.",kw={"alchemist","alchemie","brill","lager","lagerfeuer","zelten für anfänger","carolai anise","manabrunnen"},sec={{t="Ein Lager für Gebräue",b="Carolai Anise in Brill lehrt Alchemisten, einen Manabrunnen für ihr Lager herzustellen. Sobald Ihr die Herstellung beherrscht, könnt Ihr in der Wildnis ein Lager aufschlagen. Zuerst braucht Ihr ein Lagerfeuer, und Köche können Euch beibringen, wie Ihr eines entfacht."}},faq={{q="Wer lehrt mich, einen Manabrunnen herzustellen?",a="Carolai Anise in Brill kann Euch beibringen, einen Manabrunnen herzustellen, sobald Ihr Eure Fertigkeit in Alchemie bewiesen habt.",al={"manabrunnen lehrer","wer lehrt manabrunnen","carolai anise alchemie"}},{q="Wozu dient ein Manabrunnen?",a="Ein Manabrunnen ist ein Lagergegenstand, den Ihr als Alchemist herstellen könnt. Sein erfrischender Geschmack zieht Heiler und Zauberwirker an.",al={"manabrunnen verwendung","was bewirkt ein manabrunnen","mana lagergegenstand"}},{q="Wo kann ich lernen, einen Manabrunnen herzustellen?",a="Carolai Anise in Brill kann Euch beibringen, einen Manabrunnen herzustellen.",al={"manabrunnen standort","brill alchemielehrer","wo ist carolai"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt. Die meisten Köche können Euch beibringen, wie Ihr eines entfacht.",al={"lagerfeuer benötigt","wie lager aufschlagen","lager grundlagen"}}},fp="20,135,16.203.0,36.95.0,24.120.0,38.57.0,38.85.0"}
P.entries["quest:97952"] = {n="Camping 101: Blacksmithing",s="Ein Schmied kann lernen, einen Schleifstein für das Lager herzustellen. Basil Frye in Unterstadt kann es Euch beibringen, sobald Ihr Euer Können unter Beweis gestellt habt.",h="Ein Schmied kann lernen, einen Schleifstein für das Lager herzustellen.",kw={"basil frye","schmiedekunst","lager","schurke","schleifstein","unterstadt","krieger"},ang={["class:Rogue"]="Mit einem Schleifstein im Lager könnt Ihr Eure Waffe schärfen.",["class:Warrior"]="Mit einem Schleifstein im Lager könnt Ihr Eure Waffe schärfen.",["profession:Blacksmithing"]="Als Schmied könnt Ihr lernen, einen Schleifstein für das Lager herzustellen."},sec={{t="Das Lager eines Schmieds",b="Jemand bittet Euch, mit Basil Frye in Unterstadt über einen Lagergegenstand für Eure Schmiedekunst zu sprechen. Ihr müsst Euer Können unter Beweis stellen, bevor er Euch beibringt, einen Schleifstein herzustellen. Im Lager können Krieger und Schurken in der Nähe damit ihre Waffen schärfen."}},faq={{q="Was kann Basil Frye mir beibringen?",a="Basil Frye kann Euch beibringen, einen Schleifstein für das Lager herzustellen, sobald Ihr Euer Können in der Schmiedekunst unter Beweis gestellt habt.",al={"basil frye schmiedekunst","schleifstein","lager schmied gegenstand"}},{q="Was bewirkt ein Schleifstein?",a="Ein Schleifstein in Eurem Lager ermöglicht es Kriegern und Schurken in der Nähe, ihre Waffen zu schärfen.",al={"was bewirkt der schleifstein","waffen schärfen","schleifstein verwendung"}},{q="Wo finde ich Basil Frye?",a="Basil Frye ist in Unterstadt.",al={"basil standort","wo ist basil","basil frye unterstadt"}}},fp="26,152,14.264.0,29.119.0,32.83.0,27.27.0"}
P.entries["quest:97953"] = {n="Camping 101: Enchanting",s="In Brill lehrt Vance Undergloom Verzauberer, eine Verzauberte Laute fürs Lager herzustellen. Stellt zuerst Eure Fertigkeiten unter Beweis.",h="In Brill lehrt Vance Undergloom Verzauberer, eine Verzauberte Laute fürs Lager herzustellen.",kw={"brill","lager","camping grundlagen","verzauberte laute","verzauberer","verzauberkunst","vance undergloom"},ang={["profession:Tailoring"]="Als Verzauberer könnt Ihr lernen, eine Verzauberte Laute fürs Lager herzustellen, nachdem Ihr Eure Fertigkeiten unter Beweis gestellt habt."},sec={{t="Ein Begleiter fürs Lager",b="In einem Lager in der Wildnis können Verzauberer lernen, eine Verzauberte Laute herzustellen. Nehmt sie mit, damit sie Euch die Zeit fernab des Pfades mit Unterhaltung vertreibt."}},faq={{q="Was kann ich herzustellen lernen?",a="Ihr könnt lernen, eine Verzauberte Laute für Euer Lager herzustellen.",al={"verzauberte laute","lagergegenstand verzauberkunst","was lehrt vance"}},{q="Wer bringt mir etwas über die Laute bei?",a="Vance Undergloom in Brill kann Euch beibringen, eine Verzauberte Laute herzustellen.",al={"wer ist vance","vance undergloom","lautenlehrer"}},{q="Wo finde ich Vance Undergloom?",a="Vance Undergloom ist in Brill.",al={"wo ist vance","vance standort","brill verzauberer"}},{q="Was brauche ich, bevor ich mit Vance spreche?",a="Stellt Eure Fertigkeiten unter Beweis, bevor Ihr lernt, den Lagergegenstand herzustellen.",al={"fertigkeitsanforderung","fertigkeiten unter beweis stellen","verzauberkunst voraussetzung"}},{q="Warum eine Verzauberte Laute ins Lager mitbringen?",a="Die Verzauberte Laute sorgt während Eurer Zeit im Lager für Unterhaltung.",al={"laute zweck","unterhaltung im lager","warum verzauberte laute"}}},fp="23,120,16.147.0,26.55.0,30.67.0,33.29.0,42.74.0,36.61.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="Camping 101: First Aid hilft Heilern in Wildnislagern, sich auf Verletzungen vorzubereiten. In Brill lehrt Nurse Neela erfahrene Heilkundige, eine Verbandtasche zur Wundversorgung fernab besiedelter Gebiete herzustellen.",h="Camping 101: First Aid hilft Heilern in Wildnislagern, sich auf Verletzungen vorzubereiten.",kw={"brill","lagerfeuer","lagern","camping 101","erste hilfe","verbandtasche","nurse neela","tirisfal"},ang={["faction:Horde"]="Nurse Neela unterrichtet in Brill, der Stadt der Verlassenen in Tirisfal, und bietet Reisenden der Horde damit eine örtliche Anlaufstelle für Unterweisung.",["profession:Cooking"]="Kochlehrer bringen Euch bei, ein einfaches Lagerfeuer zu errichten. Ihr braucht eines, bevor Ihr einen Lagerplatz in der Wildnis einrichtet oder medizinische Einrichtungen hinzufügt.",["race:Undead"]="Als Untoter könnt Ihr Euch an Nurse Neela in Brill wenden, um Eure medizinischen Fähigkeiten an das Überleben in Lordaerons verwüsteten Landen anzupassen."},sec={{t="Medizin im Feld",b="Jenseits bewachter Siedlungen bringen Bestien und rivalisierende Fraktionen Reisende in Gefahr. Wer in Erster Hilfe ausgebildet ist, kann lernen, eine Verbandtasche für ein Wildnislager zusammenzustellen. Damit können Reisende fernab besiedelter Gebiete Wunden versorgen."},{t="Unterweisung in Brill",b="In Brill lehrt Nurse Neela Reisende, ihre medizinischen Fähigkeiten im Lager einzusetzen. Wer sich im Verbinden und Behandeln auskennt, kann lernen, eine tragbare Verbandtasche herzustellen. Zunächst brauchen Reisende einen Platz in der Wildnis und ein einfaches Lagerfeuer. Kochlehrer können ihnen beibringen, wie man eines errichtet."}},faq={{q="Wer ist Nurse Neela?",a="Nurse Neela praktiziert Medizin in Brill, der Stadt der Verlassenen in Tirisfal. Sie lehrt erfahrene Kundige der Ersten Hilfe, Taschen für Wildnislager herzustellen.",al={"wer ist nurse neela","wo ist nurse neela","nurse neela standort"}},{q="Wozu dient eine Verbandtasche im Lager?",a="Eine Verbandtasche ist ein Lagerzubehör, das von Kundigen der Ersten Hilfe hergestellt wird. An einem Lagerplatz in der Wildnis bietet sie Reisenden alles Nötige, um Verletzungen zu behandeln.",al={"was ist eine verbandtasche","verbandtasche zweck","lager verbandtasche"}},{q="Warum braucht Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ein Lagerfeuer muss vorhanden sein, bevor Ihr weitere Lagereinrichtungen aufstellen könnt, darunter Verbandtaschen. Kochlehrer und Köche bringen Euch bei, ein einfaches Lagerfeuer zu errichten.",al={"warum lagerfeuer nötig","wie lagerfeuer errichten","kochen lagerfeuer lager"}},{q="Könnt Ihr innerhalb einer Stadt ein Lager aufschlagen?",a="Ihr müsst in der offenen Wildnis lagern. Stadtbewohner und örtliche Behörden haben in der Regel etwas gegen Zelte und Feuer mitten auf den Straßen der Stadt.",al={"lagern in der stadt erlaubt","lagern in brill","warum in der wildnis lagern"}},{q="Wer lehrt die Herstellung der Verbandtasche?",a="Nurse Neela in Brill lehrt geeignete Reisende, eine Verbandtasche herzustellen, sobald sie über ausreichende Fertigkeiten in Erster Hilfe verfügen.",al={"wer lehrt erste hilfe beim lagern","lehrer erste hilfe beim lagern","verbandtasche lehrer"}},{q="Was ist das Ziel von Camping 101: First Aid?",a="Nurse Neela in Brill lehrt Euch, mit Euren feldmedizinischen Fähigkeiten medizinische Vorräte für Lager im Freien vorzubereiten.",al={"was ist camping 101: first aid","camping 101 quest"}}},fp="22,199,21.228.0,20.283.0,19.157.0,39.145.0,42.162.0,36.144.0,42.110.0,43.113.0"}
P.entries["quest:97956"] = {n="Camping 101: Fishing",s="In Brill hofft jemand, dass Eure Angelfertigkeit Freude ins Lager bringt. Clyde Kellen kann Euch beibringen, dafür ein Fischglas herzustellen.",h="In Brill hofft jemand, dass Eure Angelfertigkeit Freude ins Lager bringt.",kw={"brill","lager","grundlagen des campens","clyde kellen","fischglas","angeln"},ang={["profession:Cooking"]="Als Angler könnt Ihr Eure Angelfertigkeit nutzen, um ein Fischglas für Euer Lager herzustellen."},sec={{t="Ein Andenken fürs Lager",b="Euer Angeln könnte das Lagerleben fröhlicher machen. Sobald Ihr Euer Können bewiesen habt, sprecht mit Clyde Kellen in Brill. Er kann Euch beibringen, ein Fischglas für das Lager herzustellen.\n\nDer Auftraggeber glaubt, dass fröhliche Abenteurer stärker kämpfen. Er hofft, dass das Fischglas Euch und den anderen Freude bereitet."}},faq={{q="Was soll ich tun?",a="Beweist Eure Angelfertigkeit und sprecht dann mit Clyde Kellen in Brill. Er kann Euch beibringen, ein Fischglas für Euer Lager herzustellen.",al={"was tun","angelaufgabe fürs lager"}},{q="Wer ist Clyde Kellen?",a="Clyde Kellen ist in Brill und kann Euch beibringen, ein Fischglas für Euer Lager herzustellen.",al={"wer ist clyde","clyde kellen"}},{q="Wozu dient das Fischglas?",a="Das Fischglas soll Euch und den anderen Abenteurern im Lager Freude bereiten.",al={"zweck des fischglases","fischglas fürs lager"}},{q="Warum könnte Angeln dem Lager helfen?",a="Eure Angelfertigkeit kann Euch helfen, ein Fischglas herzustellen. Der Auftraggeber hofft, dass es die Abenteurer aufheitert.",al={"wie hilft angeln","warum angeln fürs lager"}}},fp="20,122,15.273.0,28.115.0,20.76.0,25.76.0,32.95.0"}
P.entries["quest:97957"] = {n="Camping 101: Herbalism",s="In Tirisfal schickt Eleanor Shackleton angehende Kräuterkundige zu Faruza in Brill, um ein nützliches Handwerk zu lernen. Räucherkerzen helfen Zauberwirkenden, sich in Lagern in der Wildnis zu erholen.",h="In Tirisfal schickt Eleanor Shackleton angehende Kräuterkundige zu Faruza in Brill, um ein nützliches...",kw={"brill","zelten","eleanor shackleton","faruza","kräuterkunde","räucherkerze","tirisfal"},ang={["class:Mage"]="Als Magier wisst Ihr Kräuterkundige zu schätzen, die Räucherkerzen herstellen. Ihr wohltuender Rauch hilft fernab von Gasthäusern, geistige Sammlung und Zuversicht wiederzufinden.",["profession:Herbalism"]="Kräuterkundige können Reisegruppen helfen, indem sie duftende Räucherkerzen für deren Lager herstellen. Außerdem brauen sie Tränke und sammeln Stängel.",["race:Undead"]="Als Reisende der Verlassenen aus Todesend und Brill könnt Ihr von Faruza lernen, Tirisfals verdorrte Pflanzen praktisch zu nutzen."},sec={{t="Pflanzen fürs Lager",b="Die Kräuterkunde liefert Alchemisten ihre ersten Materialien. Auch Reisende verlassen sich auf gesammelte Wurzeln und Blüten. In allen Regionen lehren Meisterkräuterkundige die Sammler, Räucherkerzen herzustellen. In Tirisfal schickt Eleanor Shackleton vielversprechende Sammler zu Faruza in Brill, sobald sie grundlegende Fertigkeiten vorweisen."},{t="Nahrung für den Geist",b="Lange Reisen zehren an Zauberwirkenden und Spiritualisten. Räucherkerzen verströmen erholsame Düfte, die das Gemüt aufheitern und müde Geister beruhigen. Sammler arbeiten getrocknete Pflanzen in die Kerzen ein und helfen damit Heilern und Magiern, deren magische Reserven unterwegs schwinden."}},faq={{q="Welchen Zweck hat diese Quest?",a="Kräuterkundige verbessern ihre Fertigkeit, damit ein Lehrer ihnen die Herstellung von Räucherkerzen beibringen kann. Die Kerzen helfen Zauberwirkenden, während sie in Lagern in der Wildnis rasten.",al={"warum zelten mit kräuterkunde","was bringen grundlagen des zeltens","grundlagen des zeltens kräuterkunde ziel"}},{q="Wer bietet diese Quest in Tirisfal an?",a="Eleanor Shackleton leitet Kräuterkundige in Tirisfal an und verweist sie an Faruza in Brill.",al={"wer gibt grundlagen des zeltens kräuterkunde tirisfal","eleanor shackleton quest"}},{q="Was bewirkt eine Räucherkerze?",a="Räucherkerzen heitern das Gemüt auf und helfen Heilern und Magieanwendern, beim Rasten im Freien ihre geistige Sammlung wiederzufinden.",al={"räucherkerze wirkung","wozu dienen räucherkerzen"}},{q="Wer lehrt das Rezept für Räucherkerzen?",a="Örtliche Kräuterkundelehrer bringen das Rezept Kräuterkundigen mit ausreichender Fertigkeit bei. In Tirisfal lehrt Faruza in Brill. Jandi lehrt in Orgrimmar, Reyna Stonebranch in Eisenschmiede und Malorne Bladeleaf in Dolanaar.",al={"wer lehrt zelten mit kräuterkunde","wo grundlagen des zeltens kräuterkunde abgeben"}},{q="Können Angehörige anderer Fraktionen und Völker diese Quest annehmen?",a="Ja. Überall in Kalimdor und den Östlichen Königreichen geben Wegweiser und Lehrer Kräuterkundigen dieselbe Unterweisung, die Eleanor Shackleton und Faruza Reisenden in Tirisfal anbieten.",al={"grundlagen des zeltens nur für horde","allianz grundlagen des zeltens kräuterkunde"}},{q="Welche Fertigkeit ist erforderlich, um die Ausbildung abzuschließen?",a="Kräuterkundige benötigen eine Fertigkeit von zwanzig, bevor ein Lehrer ihnen das Kerzenrezept beibringt.",al={"wie viel kräuterkunde nötig","grundlagen des zeltens fertigkeitsstufe"}}},fp="22,157,18.293.0,23.259.0,34.148.0,41.95.0,31.116.0,38.206.0,56.168.0,58.85.0"}
P.entries["quest:97958"] = {n="Camping 101: Leatherworking",s="Shelene Rhobart kann Euch den Zeltbau lehren, sobald Ihr Euer Können in der Lederverarbeitung beweist. Ein Zelt bietet Euch auf Reisen Schutz vor Hitze und Regen.",h="Shelene Rhobart kann Euch den Zeltbau lehren, sobald Ihr Euer Können in der Lederverarbeitung beweist.",kw={"brill","lagerzelt","lagerfeuer","lagern","kochkunst","lederverarbeitung","shelene rhobart","zelt","unterstadt"},ang={["profession:Cooking"]="Als Koch könnt Ihr Reisende lehren, das Lagerfeuer zu entzünden, das ein Lager vollständig macht."},sec={{t="Ein Zelt vom Lederverarbeiter",b="Ein Lederverarbeitungslehrer verweist Euch an Shelene Rhobart, die sich an der Straße von Brill nach Unterstadt aufhält. Sie kann Euch lehren, einen Gegenstand fürs Lager herzustellen, sobald Ihr Euer handwerkliches Können beweist. Ein Zelt hält Euch an heißen Tagen kühl und bei Regen trocken und bietet Euch auf Reisen Ruhe."},{t="Ein Platz fürs Lager",b="Euer Zelt ist für die Wildnis gedacht, denn die meisten Leute mögen keine Zelte mitten in der Stadt. Ein Lagerfeuer macht ein Lager vollständig, und Köche können Euch lehren, eines zu entzünden. Wenn Ihr die Grundlagen der Kochkunst lernen müsst, sucht jemanden auf, der Euch darin unterrichten kann."}},faq={{q="Wer kann mich lehren, ein Zelt herzustellen?",a="Shelene Rhobart kann Euch lehren, mit Lederverarbeitung einen Gegenstand fürs Lager herzustellen.",al={"zeltlehrer","wer lehrt zeltbau","shelene zelt"}},{q="Wo ist Shelene Rhobart?",a="Shelene Rhobart hält sich an der Straße von Brill nach Unterstadt auf.",al={"shelene aufenthaltsort","wo ist shelene","straße nach unterstadt"}},{q="Was bringt das Zelt?",a="Das Zelt hält Euch an heißen Tagen kühl und bei Regen trocken, damit Ihr Euch auf Reisen ausruhen könnt.",al={"zeltnutzung","wozu dient das zelt","campingzelt"}},{q="Wo sollte ich das Zelt aufstellen?",a="Das Zelt ist für die Wildnis gedacht; die meisten Leute mögen keine Zelte mitten in der Stadt.",al={"wo lagern","zelt in der stadt","lagerplatz"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Ein Lagerfeuer macht ein Lager vollständig, und Köche können Euch lehren, eines zu entzünden.",al={"lagerfeuer","feuer fürs lager nötig","feuer im lager"}},{q="Wie lerne ich, ein Lagerfeuer zu entzünden?",a="Die meisten Köche können Euch lehren, ein Feuer zu entzünden. Wenn Ihr die Grundlagen der Kochkunst lernen müsst, sucht jemanden auf, der Euch darin unterrichten kann.",al={"feuermachen lernen","kochkunstlehrer","ein lagerfeuer entzünden"}}},fp="27,140,22.273.0,15.243.0,32.73.0,25.55.0,22.96.0,31.99.0,21.74.0,34.107.0"}
P.entries["quest:97959"] = {n="Camping 101: Mining",s="Ihr könnt nun einen Lodestone herstellen und Euch darauf vorbereiten, in der Wildnis zu lagern.",h="Ihr könnt nun einen Lodestone herstellen und Euch darauf vorbereiten, in der Wildnis zu lagern.",kw={"lagerfeuer","lagern","koch","lodestone","bergbau","wildnis"},sec={{t="Ein Platz zum Lagern",b="Ihr könnt nun Euren eigenen Lodestone herstellen. Probiert ihn in der Wildnis aus, wo sich die Leute seltener an einem Lager stören. Bevor Ihr beginnt, braucht Ihr außerdem ein Lagerfeuer. Ein Koch kann Euch beibringen, wie Ihr eines macht."}},faq={{q="Was kann ich jetzt herstellen?",a="Von nun an könnt Ihr selbst einen Lodestone herstellen.",al={"lodestone rezept","lodestone herstellen"}},{q="Wo sollte ich den Lodestone ausprobieren?",a="Begebt Euch in die Wildnis, um ihn auszuprobieren; die meisten Leute möchten keine Lager mitten in der Stadt.",al={"wo lagern","lodestone ausprobieren"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt.",al={"lagerfeuer benötigt","lager aufschlagen"}},{q="Wer kann mir beibringen, ein Lagerfeuer zu machen?",a="Ein Koch kann Euch beibringen, ein Lagerfeuer zu machen.",al={"lagerfeuer erlernen","wer lehrt feuermachen"}}},fp="19,67,15.193.0,20.47.0,33.86.0,38.46.0,36.40.0"}
P.entries["quest:97960"] = {n="Camping 101: Skinning",s="In Tirisfal schickt Camping 101: Skinning neue Kürschner los, um ein nützliches Handwerk zu erlernen. Sie lernen, aus erbeuteten Häuten einen Lagerstuhl herzustellen und wo sie in ganz Azeroth Lehrer finden.",h="In Tirisfal schickt Camping 101: Skinning neue Kürschner los, um ein nützliches Handwerk zu erlernen.",kw={"brill","lagerstuhl","zelten","eleanor shackleton","rand rhobart","kürschnerei","tirisfal","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr jeden Teil eines erlegten Tieres nutzen und auf dem beschwerlichen Weg nichts verschwenden.",["race:Undead"]="Als Untoter mögt Ihr von sterblicher Erschöpfung frei sein, doch ein funktionierendes Lager ist weiterhin nützlich, während Ihr die verseuchten Tiere von Tirisfal jagt."},sec={{t="Komfort in der Wildnis",b="Eine scharfe Klinge allein bringt Euch nicht durch die Wildnis. Ihr braucht auch eine Möglichkeit, Euch zwischen den Prüfungen auszuruhen. Unterwegs können Kürschner die Grundlagen erlernen und aus behandelten Fellen einen Stuhl fürs Lager herstellen. Er bietet müden Reisenden einen Platz zur Erholung, bevor die Gefahr erneut ruft."},{t="Das Handwerk meistern",b="Junge Kürschner der Verlassenen in Tirisfal werden zu Rand Rhobart geschickt, sobald sie eine erste Grundfertigkeit erlangt haben. Er arbeitet an der Straße zwischen Brill und den Ruinen der Hauptstadt von Unterstadt. Rhobart lehrt praktische Methoden, um aus grobem Leder eine Sitzgelegenheit fürs Lager herzustellen. Kürschnermeister in den Gebieten der Horde und der Allianz lehren dasselbe Handwerk."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Lektion schickt neue Kürschner zu einem Handwerkslehrer, der ihnen beibringt, aus erbeuteten Tierpelzen einen Lagerstuhl herzustellen.",al={"was bewirkt camping 101 skinning","warum camping 101 skinning machen","camping 101 belohnung"}},{q="Wer bietet diese Ausbildung in Tirisfal an?",a="Eleanor Shackleton erteilt die Lektion in Tirisfal und verweist neue Kürschner an Rand Rhobart, an der Straße zwischen Brill und Unterstadt.",al={"wer gibt die quest in tirisfal","eleanor shackleton quest"}},{q="Welche Fertigkeitsstufe ist für diese Aufgabe erforderlich?",a="Ihr benötigt eine Kürschnereifertigkeit von mindestens zwanzig, bevor Euch ein Lehrer beibringt, Lagerausrüstung herzustellen.",al={"welche kürschnereistufe ist nötig","camping 101 skinning voraussetzungen","benötigte kürschnereifertigkeit"}},{q="Wo ist Rand Rhobart zu finden?",a="Rand Rhobart arbeitet an der Hauptstraße, die von Brill nach Süden zum Eingang von Unterstadt in Tirisfal führt.",al={"rand rhobart fundort","wo ist rand rhobart","rand rhobart tirisfal"}},{q="Können Angehörige anderer Fraktionen diese Technik erlernen?",a="Ja. Verlassene lernen bei Rand Rhobart, während andere Ausbilder Kürschner in Goldhain, Eisenschmiede, Dolanaar, Orgrimmar, im Dorf der Bluthufe und in Shen'dar unterrichten.",al={"ist das nur für die horde","kann die allianz camping 101 skinning machen","allianz kürschnerei lagerstuhl"}},{q="Warum ist es nützlich, einen Lagerstuhl herzustellen?",a="Ein Lagerstuhl bietet Euch einen bequemen Platz, um in der Wildnis zu sitzen und wieder zu Kräften zu kommen. Ruht Euch dort aus, und Ihr könnt für die bevorstehenden Kämpfe wachsam bleiben.",al={"was bewirkt ein lagerstuhl","warum einen lagerstuhl herstellen"}}},fp="21,181,20.264.0,19.348.0,34.115.0,44.143.0,51.100.0,32.112.0,51.164.0,36.146.0"}
P.entries["quest:97961"] = {n="Camping 101: Tailoring",s="Ein Schneiderlehrer kann Euch zeigen, wie Ihr ein Fraktionsbanner für Euer Lager herstellt. Bowen Brisboise lehrt Euch das Handwerk, sobald Ihr Euer Können bewiesen habt.",h="Ein Schneiderlehrer kann Euch zeigen, wie Ihr ein Fraktionsbanner für Euer Lager herstellt.",kw={"bowen brisboise","brill","lagerfeuer","lagern","todesend","fraktionsbanner","rallying banner","schneiderei"},sec={{t="Ein Banner fürs Lager",b="Ein Schneiderlehrer verweist Euch an Bowen Brisboise an der Straße von Todesend nach Brill. Beweist ihm Euer Können, dann kann er Euch zeigen, wie Ihr ein Fraktionsbanner für Euer Lager herstellt. Ein Banner kann Euch helfen, draußen den Mut zu bewahren."},{t="Ein Lager aufschlagen",b="Bowen Brisboise lehrt Euch, ein Rallying Banner herzustellen. Um es auszuprobieren, müsst Ihr Euer Lager in der Wildnis aufschlagen, denn die meisten Leute mögen keine Lager in der Stadt. Ihr braucht außerdem ein Lagerfeuer, und ein Koch kann Euch zeigen, wie Ihr eines entzündet."}},faq={{q="Wer lehrt Schneiderarbeiten fürs Lager?",a="Bowen Brisboise kann Euch lehren, ein Fraktionsbanner herzustellen, sobald Ihr Euer Können in der Schneiderei bewiesen habt.",al={"wer ist bowen","bowen brisboise","schneiderlehrer"}},{q="Wo finde ich Bowen Brisboise?",a="Bowen Brisboise befindet sich an der Straße von Todesend nach Brill.",al={"wo ist bowen","bowens standort","straße nach brill"}},{q="Was lässt sich mit Schneiderei für ein Lager herstellen?",a="In der Schneiderei könnt Ihr lernen, ein Fraktionsbanner für Euer Lager herzustellen.",al={"lagergegenstand aus schneiderei","banner herstellen","lagerbanner"}},{q="Wie heißt das Banner?",a="Das Banner, dessen Herstellung Ihr lernt, heißt Rallying Banner.",al={"rallying banner","name des banners","welches banner"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt, und ein Koch kann Euch zeigen, wie Ihr eines entzündet.",al={"lagerfeuer nötig","feuer fürs lager","lager aufschlagen"}}},fp="22,137,17.225.0,15.211.1,34.92.0,33.56.0,35.63.0,26.58.0,21.86.0"}
P.entries["quest:97963"] = {n="Camping 101: Alchemy",s="Nyassa Swiftdraught in Shen'dar kann Euch lehren, einen Manabrunnen herzustellen, sobald Ihr Euer Können in Alchemie bewiesen habt. Der Brunnen lockt Heiler und Zauberwirker zur Erfrischung in ein Lager.",h="Nyassa Swiftdraught in Shen'dar kann Euch lehren, einen Manabrunnen herzustellen, sobald Ihr Euer Können in...",kw={"alchemie","lagerfeuer","lagern","heiler","manabrunnen","nyassa swiftdraught","shen'dar","zauberwirker"},ang={["profession:Cooking"]="Ein Koch kann Euch beibringen, das Lagerfeuer zu entfachen, das Ihr zum Aufschlagen Eures Lagers braucht."},sec={{t="Ein Lager für Alchemisten",b="Ein Alchemist kann bei Nyassa Swiftdraught in Shen'dar lernen, einen Manabrunnen herzustellen, sobald Ihr Eure Fertigkeit unter Beweis gestellt habt. Heiler und Zauberwirker werden von seinem erfrischenden Getränk angelockt. Um ihn im Lager auszuprobieren, braucht Ihr zuerst ein Lagerfeuer; ein Koch kann Euch beibringen, wie Ihr eines entfacht."}},faq={{q="Was kann Nyassa mich lehren?",a="Nyassa Swiftdraught in Shen'dar kann Euch lehren, einen Manabrunnen herzustellen, sobald Ihr Euer Können in Alchemie bewiesen habt.",al={"nyassa alchemie","manabrunnen lehrer","lagern alchemie"}},{q="Was bewirkt ein Manabrunnen?",a="Ein Manabrunnen lockt Heiler und Zauberwirker für ein erfrischendes Getränk in Euer Lager.",al={"manabrunnen verwendung","wozu dient ein manabrunnen","manabrunnen"}},{q="Wo lerne ich, einen Manabrunnen herzustellen?",a="Nyassa Swiftdraught lehrt das Rezept in Shen'dar.",al={"wo ist nyassa","shen'dar alchemie","manabrunnen standort"}},{q="Was brauche ich, bevor ich ein Lager aufschlage?",a="Ihr braucht ein Lagerfeuer, um Euer Lager aufzuschlagen. Ein Koch kann Euch beibringen, eines zu entfachen.",al={"lagerfeuer benötigt","wie lager aufschlagen","lagern alchemie voraussetzungen"}}},fp="20,173,21.279.0,25.118.0,25.79.0,37.59.0,38.73.0"}
P.entries["quest:97964"] = {n="Camping 101: Blacksmithing",s="Als Schmied könnt Ihr lernen, einen Schleifstein für Euer Lager herzustellen. Aedi Thriceforged in Shen'dar kann es Euch beibringen, sobald Ihr Euer Können bewiesen habt.",h="Als Schmied könnt Ihr lernen, einen Schleifstein für Euer Lager herzustellen.",kw={"aedi thriceforged","schmiedekunst","camping 101","schurke","schleifstein","shen'dar","krieger"},ang={["class:Rogue"]="Als Schurke in der Nähe könnt Ihr Eure Waffe an einem Schleifstein schärfen, der in einem Lager aufgestellt ist.",["class:Warrior"]="Als Krieger in der Nähe könnt Ihr Eure Waffe an einem Schleifstein schärfen, der in einem Lager aufgestellt ist.",["profession:Blacksmithing"]="Als Schmied könnt Ihr lernen, einen Schleifstein für Euer Lager herzustellen."},sec={{t="Aedis Lektion",b="Mit einem Schleifstein können Krieger und Schurken in der Nähe ihre Waffen in Eurem Lager schärfen. In Shen'dar kann Aedi Thriceforged Euch die Herstellung beibringen, sobald Ihr Euer Können in der Schmiedekunst bewiesen habt."}},faq={{q="Wer bringt mir bei, einen Schleifstein herzustellen?",a="Aedi Thriceforged in Shen'dar kann Euch beibringen, einen Schleifstein herzustellen, sobald Ihr Euer Können in der Schmiedekunst bewiesen habt.",al={"schleifstein lehrer","wer ist aedi","aedi schmiedekunst"}},{q="Was bewirkt ein Schleifstein?",a="Mit einem Schleifstein in Eurem Lager können Krieger und Schurken in der Nähe ihre Waffen schärfen.",al={"schleifstein verwendung","waffen schärfen","schärfding im lager"}},{q="Wo finde ich Aedi Thriceforged?",a="Aedi Thriceforged ist in Shen'dar.",al={"aedi standort","wo ist aedi","aedi shen'dar"}}},fp="26,165,13.196.0,42.129.0,32.84.0,34.41.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="In Shen'dar sucht Ihr Versorgung für Verletzungen fernab der Zivilisation. Naleeia Tattermend lehrt geübte Anwender, medizinische Ausrüstung für ein Lager in der Wildnis zusammenzustellen.",h="In Shen'dar sucht Ihr Versorgung für Verletzungen fernab der Zivilisation.",kw={"verbände","zelten","camping 101: first aid","first aid","verbandtasche","naleeia tattermend","shen'dar","überleben in der wildnis"},sec={{t="Heilung in der Wildnis",b="Eine Reise durch Azeroth kann Gewalt, wilde Bestien und Gefahren der Landschaft mit sich bringen. Mit First Aid könnt Ihr Schnittwunden und Knochenbrüche verbinden, ohne Euch allein auf Zauberkunst zu verlassen. Eine Verbandtasche in einem Wildnislager bietet Euch einen Ort, um Verletzungen zu versorgen und Gefährten bei der Genesung zu helfen. Danach könnt Ihr Euch auf die Weiterreise vorbereiten."},{t="Die Lehrmeisterin von Shen'dar",b="In Shen'dar lehrt Naleeia Tattermend Anwender, haltbare medizinische Vorräte für einen Lagerplatz herzustellen. Sie gibt ihre Techniken weiter, nachdem Ihr gezeigt habt, dass Ihr die Grundlagen der medizinischen Versorgung beherrscht."}},faq={{q="Mit wem muss ich für diese Quest sprechen?",a="Sprecht mit Naleeia Tattermend in Shen'dar. Sie weiß, wie man medizinische Vorräte für Wildnislager herstellt.",al={"mit wem sprechen zelten first aid","wo ist naleeia tattermend","camping 101: first aid abgeben"}},{q="Wo liegt Shen'dar?",a="Shen'dar liegt auf der Insel Zephras, wo Naleeia Tattermend lebt. Anwender reisen dorthin, um sich nach dem Verfeinern ihrer Fertigkeiten in First Aid für die Wildnis weiterbilden zu lassen.",al={"wo liegt shen'dar","shen'dar lage","shen'dar first aid"}},{q="Wozu dient es, eine Verbandtasche für das Lager herzustellen?",a="Ihr lernt, eine Verbandtasche für den Lagerplatz eines Abenteurers herzustellen. Vorräte, die im Lager bereitliegen, ermöglichen es Euch, Verletzungen zwischen den Reisen zu behandeln. Sie können über Leben und Tod entscheiden.",al={"was bringt first aid beim zelten","verbandtasche lager","warum verbandtasche herstellen"}},{q="Wann lehrt mich Naleeia Tattermend, die Tasche herzustellen?",a="Naleeia Tattermend unterrichtet Euch, nachdem Ihr genügend Können in First Aid bewiesen habt. Übt das Verbinden und Behandeln, bevor Ihr Taschen für den Einsatz im Gelände herstellt.",al={"wann lässt sich die verbandtasche erlernen","naleeia tattermend voraussetzung","camping 101: first aid voraussetzung"}},{q="Warum gilt First Aid als ehrenhaft und zugleich praktisch?",a="Wunden und körperliche Verletzungen bedrohen Reisende in ganz Azeroth. Verbände und medizinische Versorgung ermöglichen Reisenden jeder Disziplin, ihre eigenen Wunden zu versorgen und Gefährten zu stabilisieren, ohne sich allein auf Magie zu verlassen.",al={"warum ist first aid wichtig","first aid hintergrundgeschichte","ist first aid nützlich"}},{q="Kann jeder Abenteurer eine Verbandtasche für das Lager herstellen?",a="Jeder Abenteurer, der First Aid erlernt und sein Können beweist, kann bei Naleeia Tattermend in Shen'dar lernen, eine Verbandtasche für das Lager herzustellen.",al={"kann jeder diese tasche erlernen","wer kann verbandtasche fürs lager herstellen"}}},fp="22,166,25.300.0,30.185.0,43.112.0,34.164.0,57.180.0,55.131.0,57.199.0,49.147.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Ihr lernt, wie Angeln Lager in der Wildnis einladender machen kann. In Shen'dar können geschickte Angler Fenn Fairweather bitten, ihnen die Herstellung eines Fischglases beizubringen.",h="Ihr lernt, wie Angeln Lager in der Wildnis einladender machen kann.",kw={"lagern","camping 101: fishing","fenn fairweather","fischglas","angeln","shen'dar"},sec={{t="Behaglichkeit am Herd",b="Ein Lager in der Wildnis braucht neben scharfen Klingen und robuster Rüstung auch Behaglichkeit. Gute Stimmung hilft Gefährten, die Strapazen des Lebens im Feld zu ertragen. Angeln liefert Proviant, und geschickte Angler können mit ihrem Handwerk einen Lagerplatz verbessern. Mit lebenden Fischen und einem passenden Einrichtungsgegenstand kann ein Reisender sein Lager einladender gestalten."},{t="Der Handwerker von Shen'dar",b="In Shen'dar teilt Fenn Fairweather Angelgeheimnisse mit erfahrenen Anglern, die sich mit Rute und Rolle in Geduld geübt haben. Angler mit genügend Geschick können lernen, ein Fischglas herzustellen, einen einfachen Einrichtungsgegenstand, der müden Gefährten Freude und Erholung bringt. Gute Stimmung in der Wildnis hilft einer Gruppe, konzentriert und entschlossen zu bleiben, wenn Gefahr naht."}},faq={{q="Wer lehrt die Herstellung eines Fischglases fürs Lager?",a="Fenn Fairweather lehrt in Shen'dar die Herstellung eines Fischglases. Beweist genügend Geschick beim Angeln, und Fenn kann Euch beibringen, eines fürs Lager herzustellen.",al={"wer gibt fischglas","wo ist fenn fairweather","fischglas lehrmeister"}},{q="Welchen Zweck erfüllt ein Fischglas im Lager?",a="Ein Fischglas ist ein dekorativer Einrichtungsgegenstand, der Euch und Euren Gefährten im Lager Behaglichkeit und Freude bringt. Ein gepflegtes Lager und gute Stimmung helfen Euch, im Feld wachsam und auf Gefahren vorbereitet zu bleiben.",al={"was bewirkt fischglas","fischglas stärkungszauber","lagern fischglas effekt"}},{q="Wo liegt Shen'dar?",a="Shen'dar ist ein Treffpunkt für Handwerker und Lehrmeister, darunter Fenn Fairweather. Angler gehen dorthin, um praktische Lagerhandwerke zu erlernen, die ihren Fertigkeiten entsprechen.",al={"wo liegt shen'dar","shen'dar standort"}},{q="Welche Fertigkeit ist erforderlich, um dieses Lagerhandwerk zu erlernen?",a="Ihr müsst grundlegendes Geschick als Angler beweisen, bevor Ihr dieses Handwerk erlernen könnt. Sobald Eure Angelfertigkeit gut geschult ist, können Lehrmeister in Shen'dar Euch beibringen, Lagereinrichtung wie das Fischglas herzustellen.",al={"lagern angeln voraussetzungen","wann ist fischglas erlernbar","lagern angeln einstieg"}},{q="Warum ist Angeln für das Lagern in der Wildnis wichtig?",a="Angeln liefert Nahrung, und die Geduld und der scharfe Blick eines Anglers können auch das Lagerleben verbessern. Ein frischer Fang, der in einem handgefertigten Glas zur Schau steht, spendet Ruhe und hebt die Stimmung auf langen Reisen durch die Wildnis.",al={"warum angeln fürs lagern","nutzen des angelns im lager"}},{q="Wer ist Fenn Fairweather?",a="Fenn Fairweather ist Handwerker und Lehrmeister in Shen'dar. Fenn kennt die praktischen Annehmlichkeiten des Lebens in der Wildnis und lehrt geschickte Angler die Herstellung von Lagereinrichtung.",al={"wer ist fenn fairweather","fenn fairweather hintergrundgeschichte"}}},fp="20,167,22.316.0,23.331.0,40.140.0,44.190.0,26.172.0,51.193.0,47.194.0,24.171.0"}
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="An Lagern entlang des Weges weist Camping 101: Herbalism Sammlern den Weg zu Ausbildern, die sie lehren, Räucherkerzen herzustellen. Kräuterkundige nutzen gesammelte Pflanzen, um Zauberwirkern und Heilern auf langen Reisen Linderung zu verschaffen.",h="An Lagern entlang des Weges weist Camping 101: Herbalism Sammlern den Weg zu Ausbildern, die sie lehren...",kw={"lager","lagern","camping 101: herbalism","heiler","kräuterkunde","kräuter","räucherkerze","zauberwirker"},ang={["class:Mage"]="Zauberwirker, die ihre Konzentration im Kampf aufbrauchen, schätzen Räucherwerk im Lager, dessen beruhigender Duft ihren Geist erholt und die arkane Regeneration unterstützt.",["class:Priest"]="Im Lager entzündete Räucherkerzen heben den Mut und füllen zwischen Scharmützeln die geistigen Reserven heiliger Heiler wieder auf.",["profession:Herbalism"]="Das Sammeln von Pflanzen in der Wildnis liefert die aromatischen Kräuter, die für Räucherwerk im Lager benötigt werden. Damit dient diese Arbeit sowohl dem Überleben als auch der Alchemie."},sec={{t="Wildpflanzen am Wegesrand",b="Reisende können Wurzeln und Blütenblätter auch anders nutzen, als frische Stängel zu verkaufen oder Tränke zu brauen. Sammler treffen auf Ausbilder, die sie lehren, Räucherkerzen aus aromatischen Wildpflanzen herzustellen. Diese Kerzen unterstützen Gefährten unterwegs."},{t="Den Geist beruhigen",b="Lange Reisen durch feindliches Gebiet zehren an Heilern und Zauberwirkern. An einem genutzten Lagerplatz verströmt eine Räucherkerze einen beruhigenden, belebenden Duft, der ihren Mut hebt und ihnen hilft, Klarheit und Kraft zurückzugewinnen, bevor erneut Gefahr ruft. Wer Magie wirkt oder Verwundete versorgt, schätzt diese Linderung besonders."}},faq={{q="Was ist Camping 101: Herbalism?",a="Camping 101: Herbalism bringt geübte Kräutersammler mit Ausbildern zusammen, die sie lehren, Räucherkerzen für Lager in der Wildnis herzustellen.",al={"was ist camping 101 herbalism","camping 101 herbalism quest","kräuterkunde lagerquest"}},{q="Wozu dient eine Räucherkerze?",a="Eine Räucherkerze wird aus gesammelten Pflanzen hergestellt und an einem Lagerplatz entzündet. Ihr beruhigender, belebender Duft hebt den Mut rastender Gefährten und gewährt Heilern und Zauberwirkern eine wohltuende Stärkung.",al={"was bewirkt eine räucherkerze","räucherkerze wirkung im lager","warum räucherkerzen herstellen"}},{q="Wer lehrt die Herstellung einer Räucherkerze?",a="Euer Ausbilder hängt davon ab, wo Ihr beginnt: Reyna Stonebranch in Eisenschmiede, Malorne Bladeleaf in Dolanaar, Herbalist Pomeroy im Wald von Elwynn, Jandi in Orgrimmar, Faruza in Brill, Komin Winterhoof in Donnerfels oder Syriel Nightrain in Valanaar.",al={"wer lehrt räucherkerzen","räucherkerze lehrer","wo räucherkerzen lernen"}},{q="Warum sind Räucherkerzen für Magiewirker besonders nützlich?",a="Zauber zu wirken und Wunden zu versorgen, zehrt an körperlicher Energie und geistiger Konzentration. Der beruhigende Rauch einer Räucherkerze hilft, beides wiederherzustellen, hält den Mut hoch und Zauberwirker kampfbereit.",al={"warum brauchen zauberwirker räucherwerk","räucherkerze heiler","räucherkerze magiewirker"}},{q="Müsst Ihr kräuterkundig sein, um diese Quest anzunehmen?",a="Diese Unterweisung richtet sich an jene, die im Sammeln von Pflanzen und Kräutern geübt sind. Sie lehrt, aromatische Wildpflanzen zu finden und zu nutzen.",al={"kann jeder räucherkerzen lernen","kräuterkunde für camping 101 herbalism nötig","kräuterkunde voraussetzung lagerkerze"}},{q="Wie hängt Kräuterkunde mit dem Lagern zusammen?",a="Gesammelte Pflanzen lassen sich im Lager auch anders nutzen, als Gebräue und Salben herzustellen. Aus ihnen lässt sich Räucherwerk herstellen, das müde Gefährten erfrischt.",al={"ist kräuterkunde nur für tränke","verwendung von kräutern beim lagern","kräuterkunde lagergegenstände"}}},fp="22,250,25.277.0,19.349.0,31.149.0,30.230.0,46.255.0,63.226.0,58.156.0,49.177.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Die Reisen eines Lederverarbeiters führen zu Unterricht im Bau einer Unterkunft für die Wildnis. In Shen'dar lehrt Indari Sunseam geübte Handwerker, Zelte zu nähen, die Reisende schützen und ihnen auf langen Reisen Erholung bieten.",h="Die Reisen eines Lederverarbeiters führen zu Unterricht im Bau einer Unterkunft für die Wildnis.",kw={"campingzelt","lagerfeuer","camping","kochen","indari sunseam","lederverarbeitung","shen'dar","zelt","wildnis"},ang={["profession:Cooking"]="Ein Zelt allein macht noch kein vollständiges Lager aus. Ihr müsst auch die Grundlagen des Lagerfeuermachens erlernen, üblicherweise bei einem Kochlehrer."},sec={{t="Unterkunft auf Reisen",b="Reisende Lederverarbeiter brauchen robuste Ausrüstung aus Haut und Pelz. Sobald sie das Handwerk erlernt haben, werden sie zu Indari Sunseam in Shen'dar geschickt. Dort lehrt sie sie, ein ordentliches Campingzelt herzustellen. Es hält Reisende bei starkem Regen trocken und unter sengender Sonne kühl und hilft ihnen, sich auf langen Reisen auszuruhen."},{t="Lagerplätze in der Wildnis",b="Die Stadtbewohner beschweren sich, wenn einfache Lager ihre Straßen verstellen, also schlagt Ihr Euer Zelt in der Wildnis auf. Ein Lagerplatz braucht mehr als eine Unterkunft; er braucht auch ein wärmendes Lagerfeuer. Sucht einen örtlichen Koch auf, um die Grundlagen des Feuermachens zu erlernen, bevor Ihr aufbrecht."}},faq={{q="Wer lehrt Lederverarbeiter, ein Zelt herzustellen?",a="Indari Sunseam in Shen'dar lehrt geübte Lederverarbeiter, Campingzelte herzustellen.",al={"wer lehrt zelte für lederverarbeiter","campingzelt lehrer","wo ist indari sunseam"}},{q="Wozu dient die Herstellung eines Zeltes?",a="Ein gut gefertigtes Zelt schützt Reisende vor starkem Regen und sengender Hitze und hilft ihnen, sich auszuruhen und unterwegs wachsam zu bleiben.",al={"was bewirkt ein zelt","zweck eines zeltes","vorteile eines zeltes"}},{q="Wo kann ein Campingzelt aufgeschlagen werden?",a="Ihr schlagt ein Zelt in der Wildnis auf, fern der Stadtzentren, wo die Einheimischen sich an Lagern stören.",al={"kann man ein zelt in der stadt aufschlagen","wo zelt benutzen","lagerregeln"}},{q="Was wird noch benötigt, um ein ordentliches Lager aufzuschlagen?",a="Ein ordentliches Lager braucht auch ein Lagerfeuer. Ein Kochlehrer kann Euch beibringen, ein einfaches Feuer zu entfachen.",al={"braucht man ein feuer","voraussetzungen für ein lager","was braucht ein lager noch"}},{q="Wann bringt Indari Sunseam Euch das Zeltmuster bei?",a="Indari Sunseam bringt Euch das Zeltmuster bei, nachdem Ihr Euch in der Lederverarbeitung geübt und Euer Können in diesem Handwerk bewiesen habt.",al={"wann kann man zeltbau lernen","voraussetzungen für ein zelt","lederverarbeitung zelt voraussetzungen"}},{q="Was ist Shen'dar?",a="Shen'dar ist der Ort, an dem Indari Sunseam lebt und arbeitet und Reisende lehrt, Campingausrüstung herzustellen.",al={"wo ist shen'dar","shen'dar lage","indari sunseam ort"}}},fp="27,216,19.306.0,20.227.0,47.88.0,39.114.0,36.88.0,43.91.0,52.115.0,25.103.0"}
P.entries["quest:97970"] = {n="Camping 101: Mining",s="Ein Bergbaulehrer in Shen'dar kann Euch lehren, einen Lodestone für Euer Lager herzustellen. Er verleiht allen, die sich um das Feuer versammeln, zusätzliche Stärke im Kampf.",h="Ein Bergbaulehrer in Shen'dar kann Euch lehren, einen Lodestone für Euer Lager herzustellen.",kw={"lager","lagerfeuer","camping 101","lodestone","messana crestwind","bergbau","shen'dar"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, das Lagerfeuer zu entzünden, das sie zum Aufschlagen eines Lagers brauchen.",["profession:Mining"]="Als Bergmann könnt Ihr Messana Crestwind Euer Können beweisen und lernen, einen Lodestone für Euer Lager herzustellen."},sec={{t="Das Handwerk eines Bergmanns",b="Bergbau bietet ehrliche Arbeit, und bei Messana Crestwind in Shen'dar könnt Ihr ein Handwerk für Euer Lager erlernen. Sobald Ihr Euer Können im Bergbau bewiesen habt, kann sie Euch lehren, einen Lodestone herzustellen. Wer sich um Euer Feuer versammelt, kann daraus zusätzliche Stärke schöpfen, sodass dieses Handwerk Schwertkämpfer in Euer Lager locken könnte."},{t="Ein Platz fürs Lager",b="Habt Ihr das Handwerk erlernt, könnt Ihr Euren eigenen Lodestone herstellen. Im Ortskern sind Lager unerwünscht, also nehmt ihn mit in die Wildnis, um ihn auszuprobieren. Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt, und ein Koch kann Euch lehren, eines zu entzünden."}},faq={{q="Wer lehrt mich, einen Lodestone herzustellen?",a="Messana Crestwind in Shen'dar kann Euch lehren, einen Lodestone herzustellen, nachdem Ihr Euer Können im Bergbau bewiesen habt.",al={"lodestone lehrer","wer lehrt bergbauhandwerk fürs lager"}},{q="Was bewirkt ein Lodestone?",a="Er verleiht allen, die sich um Euer Lagerfeuer versammeln, zusätzliche Stärke im Kampf.",al={"lodestone verwendung","wozu dient lodestone"}},{q="Wo kann ich meinen Lodestone ausprobieren?",a="Ihr könnt ihn in der Wildnis ausprobieren; im Ortskern sind Lager unerwünscht.",al={"wo lodestone ausprobieren","lodestone lager"}},{q="Brauche ich ein Lagerfeuer?",a="Ja. Ihr braucht ein Lagerfeuer, bevor Ihr Euer Lager aufschlagt, und ein Koch kann Euch lehren, eines zu entzünden.",al={"lagerfeuer benötigt","wie lager aufschlagen"}},{q="Was brauche ich, bevor Messana mich unterrichtet?",a="Ihr müsst Euer Können im Bergbau beweisen, bevor Messana Crestwind Euch lehren kann, einen Lodestone herzustellen.",al={"können im bergbau","wie lodestone erlernen"}}},fp="19,155,15.305.0,15.229.0,35.110.0,25.70.0,30.77.0,21.86.0,41.99.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="In Shen'dar zeigt Mendalass Tattermend Kürschnern, wie sie sich auf die Rast in der Wildnis vorbereiten. Die Lektion verbindet Kürschnerei mit Überleben und einem Sitzplatz im Lager.",h="In Shen'dar zeigt Mendalass Tattermend Kürschnern, wie sie sich auf die Rast in der Wildnis vorbereiten.",kw={"lagerstuhl","lagerfeuer","camping 101","häute","mendalass tattermend","shen'dar","kürschnerei","wildnis"},ang={["profession:Cooking"]="Kochen und Überleben in der Wildnis gehen Hand in Hand. Ein Lagerplatz braucht ein Lagerfeuer, dessen Entzünden traditionell von Kochlehrern gelehrt wird."},sec={{t="Komfort in der Wildnis",b="Ihr könnt aus den Häuten erlegter Bestien mehr als nur Rüstung fertigen. Mendalass Tattermend zeigt Euch, wie Ihr einen tragbaren Lagerstuhl herstellt, damit Ihr in der Wildnis rasten und vor dem Kampf neue Kräfte sammeln könnt."},{t="Die Lehren von Shen'dar",b="In Shen'dar lehrt Mendalass Tattermend erfahrene Kürschner, aus gesammelten Pelzen stabile Sitzgelegenheiten herzustellen. Städte verbieten Lager innerhalb ihrer Grenzen. Ein Lagerplatz braucht auch ein Lagerfeuer, dessen Entzünden traditionell von örtlichen Kochlehrern gelehrt wird."}},faq={{q="Worum geht es in Camping 101: Skinning?",a="In Shen'dar lehrt Mendalass Tattermend Kürschner, aus erbeuteten Häuten einen Lagerstuhl herzustellen. Er bietet Euch einen Platz zum Ausruhen, wenn Ihr in der Wildnis lagert.",al={"worum geht es in dieser quest","camping 101 zweck","warum diese quest machen"}},{q="Wer ist Mendalass Tattermend?",a="Mendalass Tattermend ist ein Kürschnerlehrer in Shen'dar. Der Lehrer zeigt geübten Kürschnern, wie sie aus erbeuteten Häuten Sitzgelegenheiten für unterwegs herstellen.",al={"wer ist mendalass","wer lehrt lagerstuhl","mendalass tattermend"}},{q="Wo ist Mendalass Tattermend zu finden?",a="Mendalass Tattermend befindet sich in Shen'dar, wo Kürschner ihr Können beweisen und lernen können, Lagerausrüstung herzustellen.",al={"wo ist mendalass","wo ist shen'dar","wo diese quest abgeben"}},{q="Welchen Gegenstand lernt Ihr in dieser Quest herzustellen?",a="Kürschner lernen, aus den Häuten erlegter Bestien einen Lagerstuhl herzustellen. Er bietet Euch einen Platz zum Ausruhen in der Wildnis.",al={"was stellen kürschner her","lagerstuhl rezept","welchen gegenstand gibt es"}},{q="Könnt Ihr innerhalb einer Stadt ein Lager aufschlagen?",a="Nein. Städte verbieten Lager innerhalb ihrer Grenzen, daher gehören Lager und Stühle in die Wildnis.",al={"lagern in der stadt erlaubt","wo lager aufschlagen","wo lagerstuhl benutzen"}},{q="Was braucht Ihr noch für ein richtiges Lager?",a="Ein richtiger Lagerplatz braucht ein Lagerfeuer. Kochlehrer vermitteln traditionell die Grundlagen des Feuerentzündens.",al={"was fehlt noch fürs lager","lagerfeuer benötigt","voraussetzungen fürs lager"}}},fp="21,162,20.195.0,33.244.0,36.158.0,28.147.0,40.109.0,44.118.0,34.89.0,44.101.0"}
P.entries["quest:97972"] = {n="Camping 101: Tailoring",s="Ein Schneider kann lernen, ein Fraktionsbanner für Euer Lager herzustellen. Ihr müsst Euer Können in der Schneiderei beweisen, bevor Taleen Shimmerthread Euch unterrichten kann.",h="Ein Schneider kann lernen, ein Fraktionsbanner für Euer Lager herzustellen.",kw={"zelten","fraktionsbanner","beruf","shen'dar","schneiderei","taleen shimmerthread"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr lernen, ein Fraktionsbanner für Euer Lager herzustellen, nachdem Ihr Euer Können in Eurem Handwerk bewiesen habt."},sec={{t="Ein Banner fürs Lager",b="In Shen'dar findet Ihr jemanden, der Euch beibringen kann, ein Fraktionsbanner herzustellen. Taleen Shimmerthread kann Euch zeigen, wie Ihr diesen Lagergegenstand fertigt, sobald Ihr Euer Können in der Schneiderei bewiesen habt. Ein inspirierendes Banner kann Euch helfen, auf dem Schlachtfeld voller Tatkraft zu bleiben."}},faq={{q="Wer kann mir beibringen, ein Fraktionsbanner herzustellen?",a="Taleen Shimmerthread in Shen'dar kann Euch beibringen, ein Fraktionsbanner für Euer Lager herzustellen, sobald Ihr Euer Können in der Schneiderei beweist.",al={"bannerlehrer","wer lehrt banner schneidern","taleen banner"}},{q="Wozu dient das Fraktionsbanner?",a="Das Fraktionsbanner ist ein Lagergegenstand. Ein inspirierendes Banner kann Euch helfen, auf dem Schlachtfeld voller Tatkraft zu bleiben.",al={"banner zweck","warum ein banner herstellen","lagerbanner"}},{q="Was brauche ich, bevor Taleen mich unterrichten kann?",a="Ihr müsst Euer Können in der Schneiderei beweisen, bevor Taleen Shimmerthread Euch beibringen kann, das Fraktionsbanner herzustellen.",al={"schneiderei voraussetzung","welches können für banner","banner fertigkeit"}}},fp="22,143,17.250.0,42.134.0,31.109.0,42.112.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="In Shen'dar können Schneider lernen, ein Fraktionsbanner für Lager in der Wildnis herzustellen. Das Banner hebt die Stimmung und hilft, die Moral aufrechtzuerhalten.",h="In Shen'dar können Schneider lernen, ein Fraktionsbanner für Lager in der Wildnis herzustellen.",kw={"lagerbanner","camping","camping 101: tailoring","fraktionsbanner","shen'dar","schneiderei","taleen shimmerthread","handwerksberuf"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr Fraktionsbanner herstellen, die die Moral im Lager heben und Verbündeten im Feld neue Kraft geben."},sec={{t="Der Beitrag des Weavers zum Lager",b="Ein Lagerplatz in der Wildnis erfordert mehr als warme Kleidung. Ein gut gefertigtes Banner kann einem Lager ein gemeinsames Ziel geben, weshalb Stoffarbeiter ermutigt werden, ihr Handwerk über Kleidung und Taschen hinaus auszuüben. Mit weiterführender Unterweisung werden Ballen gewebten Stoffs zu einem Zeichen der Einigkeit und Standhaftigkeit."},{t="Unterweisung in Shen'dar",b="In Shen'dar unterrichtet Taleen Shimmerthread Schneider mit ausreichendem Können in der Herstellung von Campingausrüstung. Sie zeigt ihnen, wie man ein Fraktionsbanner fertigt. Sorgfältig genäht und im Lager aufgestellt, sammelt es Verbündete um sich und hilft ihnen, angesichts der bevorstehenden Prüfungen guten Mutes zu bleiben."}},faq={{q="Was ist Camping 101: Tailoring?",a="In Shen'dar können vielversprechende Schneider Unterweisung im Handwerk für die Wildnis erhalten. Beweist Ihr genügend Können in der Schneiderei, könnt Ihr lernen, ein Fraktionsbanner für einen Lagerplatz in der Wildnis herzustellen.",al={"was ist diese quest","camping 101: tailoring quest","schneiderei campingbanner"}},{q="Wer ist Taleen Shimmerthread?",a="Taleen Shimmerthread ist eine geschickte Schneiderin in Shen'dar. Sie lehrt Handwerker mit ausreichendem Können, Campinggegenstände herzustellen, darunter Banner, die die Stimmung im Lager heben.",al={"taleen shimmerthread","wer lehrt die herstellung von schneidereibannern","wo ist taleen shimmerthread"}},{q="Wo liegt Shen'dar?",a="In Shen'dar lebt Taleen Shimmerthread. Schneider reisen dorthin, um zu lernen, wie sie mit ihrem Stoffhandwerk Campingausrüstung herstellen können.",al={"wo liegt shen'dar","shen'dar standort"}},{q="Welchen Campinggegenstand können Schneider herstellen lernen?",a="Schneider können lernen, ein Fraktionsbanner für das Lager herzustellen. Wird eines aufgestellt, spendet seine Gegenwart den dort Rastenden Inspiration.",al={"fraktionsbanner camping","was stellt die schneiderei fürs lager her","schneiderei lagergegenstand"}},{q="Welche Voraussetzungen gelten, um die Herstellung des Campingbanners zu erlernen?",a="Ihr müsst Können in der Schneiderei beweisen, bevor Taleen Shimmerthread in Shen'dar Euch lehrt, ein Fraktionsbanner für das Lager herzustellen.",al={"wie die herstellung eines fraktionsbanners erlernen","schneiderei voraussetzungen campingbanner"}},{q="Warum sind Fraktionsbanner im Lager wertvoll?",a="Fraktionsbanner heben die Stimmung und erhalten die Moral während eines Feldzugs aufrecht. Schneider nähen sie als belebenden Mittelpunkt für Abenteurer auf beschwerlichen Reisen.",al={"warum ein fraktionsbanner herstellen","campingbanner moral"}}},fp="22,136,33.268.0,31.258.0,31.176.0,28.160.0,26.138.0,45.114.0,54.133.0,41.149.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Im Laubschattental sucht Tarindrella nach dem Grund für die plötzliche Feindseligkeit der Gnarlpine. Ihre geschnitzten Totems könnten verraten, warum sie sich gegen ihre langjährigen Nachtelfenverbündeten wandten.",h="Im Laubschattental sucht Tarindrella nach dem Grund für die plötzliche Feindseligkeit der Gnarlpine.",kw={"furbolg","gnarlpine","grell","grellkin","nature's call","albträume","laubschattental","tarindrella","teldrassil","totem"},ang={["class:Druid"]="Als Druide seid Ihr auf das Gleichgewicht der Natur und die geistige Verderbnis eingestimmt, die Kalimdors Geschöpfe befällt. Vom Albtraum berührte Furbolgtotems geben Anlass zur Sorge.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Teldrassils Äste zu schützen und Euren neuen Nachtelfenverbündeten festen Halt auf Kalimdor zu sichern.",["race:NightElf"]="Für Euch als Nachtelf ist der Wandel der Gnarlpine von langjährigen Gefährten zu Feindseligkeit und Wahnsinn eine persönliche Tragödie für Teldrassils Verteidiger."},sec={{t="Nachforschungen im Tal",b="Die Dryade Tarindrella bittet Euch, Lager entlang der Westgrenze des Laubschattentals zu durchsuchen. Die Gnarlpine-Furbolgs verließen sie in großer Eile, und sie kann nicht glauben, dass sie Jahrhunderte der Freundschaft mit den Nachtelfen grundlos aufgeben würden. Bringt unversehrte gravierte Totems zurück. Ihre Schnitzereien könnten verraten, was sich verändert hat."},{t="Der Schatten und der Albtraum",b="Die Totems der Gnarlpine erzählen von Albträumen über einen herannahenden Schatten, der ihren Stamm auslöschen würde. Angst wuchs zu blinder Wut und verzerrte ihren Geist. Schließlich sahen sie in ihren langjährigen elfischen Nachbarn genau jenen Schatten, den sie fürchteten. Tarindrella hofft, dass ihre Geschichte Licht auf das tiefere Unheil wirft, das sich durch Teldrassil schleicht."}},faq={{q="Wer vergibt die Quest Nature's Call?",a="Tarindrella, eine Dryade, wacht über das Laubschattental in Teldrassil. Die plötzliche Feindseligkeit der Gnarlpine-Furbolgs beunruhigt sie, und sie bittet Euch, Relikte aus ihren Lagern zu bergen und den Grund ihres Wahnsinns zu suchen.",al={"wer vergibt nature's call","wer ist tarindrella","tarindrella aufenthaltsort"}},{q="Warum wurden die Gnarlpine-Furbolgs feindselig?",a="Die Gnarlpine-Furbolgs litten unter Albträumen von einem drohenden Schatten, der sie zu vernichten drohte. Ihre Furcht wandelte sich in Verfolgungswahn und Raserei, bis sie ihre langjährigen Nachtelfenverbündeten als Feinde sahen.",al={"warum griffen die gnarlpine an","warum sind die gnarlpine wahnsinnig","was geschah mit den gnarlpine-furbolgs"}},{q="Wo befinden sich die Totems der Gnarlpine?",a="Kleinere Totems der Gnarlpine liegen in verlassenen Furbolglagern am Westrand des Tals. Grell und grellkin, die die Ruinen durchwühlen, haben einige davon in der Umgebung verstreut.",al={"wo sind die totems der gnarlpine","totems der gnarlpine finden","standort der gnarlpine-lager"}},{q="Warum können Spieler die größeren Totems in den Lagern nicht einsammeln?",a="Tarindrella rät Euch, die größeren Totems in den Lagern zu lassen. Sie sagt, dass sie als Dryade mit solch sperrigen Schnitzereien nichts anzufangen wüsste, und bevorzugt kleinere gravierte Totems, die sich tragen lassen.",al={"warum große totems liegen lassen","lassen sich große totems plündern","großes gnarlpine-totem"}},{q="Wer sind die Gnarlpine-Furbolgs?",a="Die Gnarlpine sind ein in Teldrassil heimischer Furbolgstamm. Sie lebten friedlich an der Seite der Nachtelfen, doch schleichende Albträume haben sie jüngst in angriffslustige Feinde verwandelt.",al={"wer sind die gnarlpine","geschichte der gnarlpine","sind die gnarlpine böse"}},{q="Was ist der große Schatten, den die Totems erwähnen?",a="Die Totems sprechen von einem unsichtbaren Great Shadow, der die Träume der Furbolgs heimsucht. Sein Ursprung bleibt unbekannt, und Tarindrella hofft, dass ihr Schicksal hilft, die weitreichende Verderbnis aufzudecken, die Teldrassil befällt.",al={"welcher schatten der gnarlpine","was ist der schatten in teldrassil","albträume in teldrassil"}}},fp="13,165,22.302.0,28.327.1,34.198.0,44.192.0,39.181.0,57.209.0,30.176.0,49.198.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="Unter Teldrassil beginnen junge Nachtelfen einen Ritus, der sie lehrt, Elunes Gaben zu erkennen. Nach der langen Wache suchen sie Führung in ihrem Glanz und Zuflucht in ihrem Schatten.",h="Unter Teldrassil beginnen junge Nachtelfen einen Ritus, der sie lehrt, Elunes Gaben zu erkennen.",kw={"elune","goddess provides","hyjal","kaldorei","lange wache","mutter mond","shadowmeld","teldrassil"},ang={["class:Priest"]="Als Priester der Kaldorei widmet Ihr Euch Mutter Mond und kanalisiert Elunes Gnade als führenden Glanz und göttlichen Schutz.",["faction:Alliance"]="Nach der Schlacht am Hyjal beendeten die Nachtelfen ihre lange Abgeschiedenheit und traten der Allianz bei. Ihr stellt die Mondkräfte Eures Volkes in den Dienst der gemeinsamen Verteidigung.",["race:NightElf"]="Als Nachtelf erbt Ihr Elunes Gaben: Mondlicht, das verborgene Pfade enthüllt, und Schatten, die Eure Anwesenheit verbergen."},sec={{t="Eine Wache endet",b="Jahrtausendelang nach der Zerschlagung hielten sich die Kaldorei von anderen Völkern fern. Während der langen Wache wachten sie über Kalimdor und beschützten die heiligen Gipfel des Hyjal. Der Dritte Krieg brachte Verheerung, und die Verteidigung des Weltbaums beendete ihre uralte Abgeschiedenheit.\n\nNun leben die Nachtelfen unter Teldrassils Zweigen und stehen einer ungewohnten Welt gegenüber. Sie knüpfen Verbindungen über den Ozean hinweg, um Verbündete zu gewinnen und ihren Platz unter Azeroths Völkern einzunehmen."},{t="Gaben von Mutter Mond",b="Elune, die Mutter Mond, bleibt das Herzstück des Glaubens der Kaldorei, obwohl die Nachtelfen nun in einer neuen Heimat leben und neue Bande knüpfen. Von klein auf lernen sie, ihre Gaben anzurufen. Ihr Glanz lenkt ihre Schläge und lässt sie ihr Ziel klarer erkennen. Ihr Schatten verbirgt sie vor den Blicken ihrer Feinde.\n\nDiese ererbten Gaben verbinden die Kaldorei mit ihrer Göttin und bereiten sie auf Gefahren jenseits des Großen Baumes vor."}},faq={{q="Was ist The Goddess Provides?",a="Junge Nachtelfen lernen in einem Ritus unter Teldrassils Zweigen, Elunes Gaben zu erkennen und unter Beweis zu stellen.",al={"was ist the goddess provides","the goddess provides quest"}},{q="Wer ist die Göttin, auf die sich diese Quest bezieht?",a="Die Göttin ist Elune, die von den Kaldorei Mutter Mond genannt wird. Sie steht im Mittelpunkt der Kultur und des spirituellen Lebens der Nachtelfen, die glauben, dass sie ihren Kindern Schutz, Klarheit und Heimlichkeit gewährt.",al={"wer ist die göttin","wer ist mutter mond","göttin der nachtelfen"}},{q="Welche Gaben gewährt Elune den Kaldorei?",a="Elune gewährt Glanz, der die Schläge eines Kriegers lenkt, und die Macht, mit den umgebenden Schatten zu verschmelzen.",al={"welche gaben gewährt elune","elune volksfähigkeiten","elunes kräfte"}},{q="Was war die lange Wache?",a="Die lange Wache umfasste jene Jahrtausende, in denen die Nachtelfen in Abgeschiedenheit über Kalimdor wachten. Sie endete, nachdem sie den Hyjal gegen die Brennende Legion verteidigt hatten, und die Kaldorei öffneten daraufhin ihre Grenzen.",al={"was war die lange wache","warum endete die lange wache"}},{q="Warum sind die Nachtelfen der Allianz beigetreten?",a="Nach der Verteidigung des Hyjal beendeten die Nachtelfen ihre lange Abgeschiedenheit und beschlossen, Bande mit den sterblichen Völkern jenseits des Meeres zu knüpfen. Sie schlossen sich der Großen Allianz an, um ihr gemeinsames Überleben zu sichern und Kameradschaft zu finden.",al={"warum traten die nachtelfen der allianz bei","kaldorei allianz"}},{q="Wo findet diese Unterweisung statt?",a="Teldrassil ist ein Großer Baum vor Kalimdors Nordküste. Nach dem Dritten Krieg wurden seine schützenden Zweige zur neuen Heimat und Zuflucht der Nachtelfen.",al={"wo ist teldrassil","was ist teldrassil"}}},fp="20,177,17.451.0,24.405.0,29.113.0,44.188.0,46.104.0,24.206.0,45.197.0,39.151.0"}
P.entries["quest:97985"] = {n="Thundering Hearts",s="In Tausend Nadeln sucht der Forscher Stormhearts gewaltiges Herz für die Arbeit an einer Monstrosität.",h="In Tausend Nadeln sucht der Forscher Stormhearts gewaltiges Herz für die Arbeit an einer Monstrosität.",kw={"monstrosität","erschaffung","herz","stormheart","tausend nadeln","donnerechse","thundering hearts"},sec={{t="Ein großes Herz",b="Ein Forscher, der die Erschaffung von Monstrositäten untersucht, glaubt, dass die Arbeit ein gewaltiges Herz erfordert. Stormheart, eine Donnerechse, die angeblich am Schluchtrand in Tausend Nadeln patrouilliert, scheint groß genug zu sein. Doch Stormheart ist nicht zahm."},{t="Das Herz",b="Stormhearts Herz gibt noch immer elektrische Impulse ab. Der Forscher sagt, es scheine der in den Aufzeichnungen angegebenen Größe zu entsprechen und werde der Monstrosität hinzugefügt."}},faq={{q="Wer will Stormhearts Herz?",a="Ein Forscher, der die Erschaffung von Monstrositäten untersucht, will Stormhearts Herz für eine Monstrosität.",al={"wer braucht das herz","monstrositätenforscher","wer hat mich geschickt"}},{q="Wo ist Stormheart?",a="Stormheart patrouilliert am Schluchtrand in Tausend Nadeln.",al={"stormheart fundort","wo ist die donnerechse","stormheart wo"}},{q="Was ist Stormheart?",a="Stormheart ist eine Donnerechse von beeindruckender Größe.",al={"stormheart kreatur","große echse","donnerechse"}},{q="Warum wird ein Herz benötigt?",a="Laut den Aufzeichnungen des Forschers erfordert die Erschaffung einer Monstrosität ein gewaltiges Herz.",al={"warum ein herz","monstrositätenherz","wofür ist das herz"}},{q="Was weiß der Forscher über das Herz?",a="Der Forscher sagt, das Herz gebe noch immer elektrische Impulse ab und scheine der in den Aufzeichnungen angegebenen Größe zu entsprechen.",al={"herz details","elektrisches herz","was ist daran besonders"}}},fp="17,98,13.218.0,9.163.1,31.89.0,20.61.0,19.50.0,22.75.0,46.115.0"}
P.entries["quest:98"] = {n="The Legend of Stalvan",s="Madame Evas düstere Vorahnung deutet auf eine Bedrohung für Dunkelhain hin: Stalvan Dunstmantel, ein Mörder mit einem Familienring. Ihr sollt ihn zur Strecke bringen und ihr den Ring bringen.",h="Madame Evas düstere Vorahnung deutet auf eine Bedrohung für Dunkelhain hin: Stalvan Dunstmantel, ein Mörder...",kw={"anwesen","dunkelhain","dämmerwald","familienring","madame eva","stalvan","stalvan dunstmantel"},sec={{t="Eine Bedrohung für Dunkelhain",b="Madame Evas Vorahnung hat Euch zu Stalvan Dunstmantel geführt, dessen Verbrechen Dunkelhain in Angst versetzt haben. Angeblich bedroht er die Stadt von seinem Anwesen nördlich davon aus. Ihr sollt dieser Gefahr ein Ende setzen und Madame Eva seinen Familienring bringen."}},faq={{q="Wer ist Stalvan Dunstmantel?",a="Stalvan Dunstmantel wird als Mörder beschrieben, der für viele Verbrechen verantwortlich ist und Dunkelhain bedroht.",al={"stalvan","wer ist stalvan","stalvans hintergrund"}},{q="Warum schickt Madame Eva mich hinter Stalvan her?",a="Madame Evas Vorahnung führte dazu, dass Stalvans Bedrohung für Dunkelhain aufgedeckt wurde.",al={"warum stalvan","eva stalvan","warum stalvan töten"}},{q="Wo steht Stalvans Anwesen?",a="Stalvans Anwesen liegt direkt nördlich von Dunkelhain.",al={"stalvans anwesen","wo ist stalvan","standort des anwesens"}},{q="Was soll ich Madame Eva zurückbringen?",a="Sie bittet Euch, ihr Stalvans Familienring zu zeigen.",al={"familienring","stalvans ring","was eva bringen"}},{q="Was geschah, nachdem Stalvan getötet wurde?",a="Madame Eva sagt, Stalvan sei tot und der Dämmerwald von seinem Blutdurst befreit.",al={"stalvans ende","ist stalvan tot","was geschah mit stalvan"}},{q="Warum ist Madame Eva froh?",a="Nach Stalvans Tod spürte sie, wie Hoffnung sich im verseuchten Wald ausbreitete, auch wenn sie um seine Opfer trauert.",al={"eva froh","warum ist eva froh","madame evas reaktion"}}},fp="21,167,21.254.0,26.100.0,42.84.0,27.45.0,42.47.0,39.80.0,23.108.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Im Hain der Uralten entsendet Arbal Verteidiger gegen die Stormscale-Naga in den Ruinen im Nordosten. Diese verfluchten ehemaligen Hochgeborenen bedrohen die umliegenden Wälder, während ihre Zahl wächst.",h="Im Hain der Uralten entsendet Arbal Verteidiger gegen die Stormscale-Naga in den Ruinen im Nordosten.",kw={"arbal","der hain der uralten","hochgeborene","myrmidon","naga","zauberin","stormscale","swelling forces","schattenhammerkult"},ang={["faction:Alliance"]="Die Streitkräfte der Allianz, die die heiligen Wälder rund um die Dunkelküste und den Hain der Uralten verteidigen, stehen einer koordinierten Front aus Naga und Schattenhammerkult gegenüber.",["race:NightElf"]="Die Naga in diesen Ruinen waren einst Hochgeborene und mit den Nachtelfen verwandt. Ihre Rückkehr, um an der Seite finsterer Kultisten die uralten Wälder zu entweihen und zu plündern, ist ein bitterer Verrat."},sec={{t="Schlangen in der versunkenen Stadt",b="Arbal beobachtet die Ruinen im Nordosten vom Hain der Uralten aus mit großer Sorge. Verfluchte Hochgeborene sind zu den schlangenartigen Naga des Stormscale-Stammes geworden. Sie besetzen nun die Überreste ihrer alten Zivilisation, und ihre wachsende Armee könnte sich über die Ruinen hinaus in den umliegenden Wald ausbreiten. Arbal entsendet Verteidiger dorthin, um ihre Zahl zu verringern, bevor es dazu kommt."},{t="Ein unheiliger Bund",b="Arbal warnt, dass die Stormscale-Naga dem Schattenhammerkult helfen. Diese ehemaligen Hochgeborenen entweihen und plündern nun die Wälder, die ihnen einst Zuflucht boten, und dienen dabei finsteren Meistern. Für Arbal ist das unverzeihlich. Ihre Zahl muss eingedämmt werden, bevor der Kult und seine schlangenartigen Verbündeten ihren Griff um das Land verstärken."}},faq={{q="Wer vergibt die Quest Swelling Forces?",a="Arbal erteilt den Auftrag im Hain der Uralten und entsendet Verteidiger gegen die feindlichen Naga, die sich in den Ruinen im Nordosten sammeln.",al={"wer vergibt swelling forces","arbal questgeber","wo ist arbal"}},{q="Warum werden die Naga in dieser Quest angegriffen?",a="Die Stormscale-Naga haben die nahe gelegenen Ruinen besetzt und bedrohen die umliegenden Wälder. Sie helfen außerdem dem Schattenhammerkult und bringen Gewalt über das Land, das einst ihre Heimat war.",al={"warum naga töten","naga in den ruinen","bedrohung durch stormscale"}},{q="Welche Verbindung besteht zwischen den Naga und den Ruinen?",a="Die Naga waren einst hochgeborene Elfen des alten Kalimdor, die durch einen schrecklichen Fluch verwandelt wurden. Einst lebten sie in diesen Städten und sind nun als Schlangen zurückgekehrt, die nach Eroberung und Verwüstung trachten.",al={"wer sind die stormscale-naga","ursprung der naga","verfluchte hochgeborene"}},{q="Welche Verbindung besteht zwischen den Naga und dem Schattenhammerkult?",a="Die Stormscale-Naga unterstützen den Schattenhammerkult. Arbal warnt, dass ihr Bündnis den uralten Wäldern weitere Verwüstung droht.",al={"schattenhammerkult naga","warum arbeiten naga mit dem kult zusammen"}},{q="Wo sammeln sich die Streitkräfte der Stormscale?",a="Die Streitkräfte der Stormscale sammeln sich in Ruinen nordöstlich des Hains der Uralten. Verteidiger werden dorthin entsandt, um ihre wachsende Zahl einzudämmen.",al={"wo sind die ruinen","wo stormscale finden"}},{q="Warum hält Arbal die Taten der Naga für unverzeihlich?",a="Arbal hält es für unverzeihlich, dass die Naga auf Befehl eines dunklen Meisters ihre uralte Heimat plündern. Ihr einstiger Adel als Hochgeborene ist Grausamkeit und finsteren Bündnissen gewichen.",al={"warum hasst arbal naga","unverzeihlich arbal"}}},fp="15,191,27.366.0,18.316.1,36.132.0,46.182.0,54.180.0,55.141.0,38.133.0,56.181.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="Auf der Späherkuppe führt Journey to Sentinel Hill Reisende der Allianz in Westfalls geplagtes Ackerland. Die örtlichen Befehlshaber haben Sturmwind monatelang vergeblich um Hilfe angefleht und setzen nun jeden hilfsbereiten Reisenden an die Arbeit.",h="Auf der Späherkuppe führt Journey to Sentinel Hill Reisende der Allianz in Westfalls geplagtes Ackerland.",kw={"journey to sentinel hill","peoples militia","späherkuppe","dünner elf","sturmwind","westfall"},ang={["faction:Alliance"]="Westfall braucht Hilfe, doch Sturmwind lässt seine Befehlshaber auf Soldaten warten. Sie sind auf alle Freiwilligen angewiesen, die eintreffen.",["race:NightElf"]="Auf der Späherkuppe mag der Befehlshaber im Grenzland murren, dass Sturmwind einen dünnen Elfen statt erfahrener Infanterie geschickt hat. Der Außenposten braucht jede Hilfe, die er bekommen kann."},sec={{t="Ankunft im Grenzland",b="In Westfall erreicht Ihr die Späherkuppe, den Außenposten, der das umliegende Ackerland bewacht. Seiner Garnison fehlen Soldaten, und der königliche Hof übersieht sie. Wenn Reisende Hilfe anbieten, fragt der örtliche Befehlshaber kaum nach ihrem Stand. Jede helfende Hand ist willkommen."},{t="Bitten an Sturmwind",b="Seit Monaten bitten die Anführer auf der Späherkuppe Sturmwind um Soldaten, um Westfall gegen herannahende Bedrohungen zu verteidigen. Ohne Verstärkung nehmen die örtlichen Befehlshaber jeden auf, der eintrifft. Ein Befehlshaber erwartete eine Armee und bekam stattdessen einen dünnen Elfen. In Westfall können Bettler nicht wählerisch sein."}},faq={{q="Was ist Journey to Sentinel Hill zur Späherkuppe?",a="Journey to Sentinel Hill führt Reisende der Allianz nach Westfall, wo die Verteidiger auf der Späherkuppe Sturmwind um Hilfe gebeten haben, ohne genügend Soldaten zu erhalten.",al={"was ist journey to sentinel hill","journey to sentinel hill quest","späherkuppe quest"}},{q="Warum bittet die Späherkuppe um Hilfe?",a="Die Anführer auf der Späherkuppe bitten Sturmwind seit Monaten um Soldaten, um den Schwierigkeiten in Westfall zu begegnen. Ohne Verstärkung sind sie auf alle Reisenden angewiesen, die eintreffen.",al={"wer fleht sturmwind um hilfe an","garnison der späherkuppe","warum die späherkuppe hilfe braucht"}},{q="Warum erwähnt der Questtext einen dünnen Elfen?",a="Der Befehlshaber erwartete nach monatelangen Bitten Hilfe aus Sturmwind, bekam aber stattdessen einen dünnen Elfen. Bettler können nicht wählerisch sein, also setzt der Befehlshaber den Neuankömmling an die Arbeit.",al={"zitat dünner elf","warum dünner elf","späherkuppe bemerkung über elfen"}},{q="Warum hat Sturmwind keine angemessene Verstärkung geschickt?",a="Die Späherkuppe hat Sturmwind monatelang um Hilfe gebeten, doch königliche Unterstützung ist ausgeblieben. Die örtlichen Befehlshaber sind auf Freiwillige angewiesen.",al={"warum hilft sturmwind westfall nicht","sturmwind vernachlässigt westfall","sturmwinds hilfe für westfall"}},{q="Was ist die Späherkuppe?",a="Die Späherkuppe ist ein militärischer Außenposten, der Westfalls Ackerland bewacht. Sie bildet die wichtigste Verteidigung gegen die Gesetzlosigkeit der Region, Defias-Banditen und Gnolle.",al={"wo ist die späherkuppe","was ist die späherkuppe","lage der späherkuppe"}},{q="Was geschieht nach der Ankunft auf der Späherkuppe?",a="Wenn Ihr Euch auf der Späherkuppe meldet, setzen Euch die örtlichen Verteidiger sofort an die Arbeit. Ihr helft dabei, den vielen Bedrohungen in Westfalls Ebenen und Ackerland entgegenzutreten.",al={"was in westfall zu tun ist","nächste quests in westfall","was nach der ankunft in westfall geschieht"}}},fp="24,224,23.270.0,18.284.0,33.163.0,37.169.0,45.167.0,48.129.0,22.155.0,42.151.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Ein Neuankömmling von der Elementarebene wird zum Wegekreuz im Brachland geschickt. Dort bittet Thork um Hilfe, während die Horde den Gefahren von Kalimdors Grenzland trotzt.",h="Ein Neuankömmling von der Elementarebene wird zum Wegekreuz im Brachland geschickt.",kw={"brachland","das wegekreuz","elementarebene","horde","journey to the crossroads","thork"},ang={["faction:Horde"]="Eure Reise führt Euch ins raue Grenzland der Horde in Kalimdor, wo Ihr Euch in ihrem Dienst beweisen sollt.",["race:Skyborne"]="Ihr seid von der Elementarebene nach Azeroth gekommen. Die Konflikte der Sterblichen mögen neben dem, was Ihr kennt, unbedeutend erscheinen, doch die Gefahren für die Horde sind real, und Ihr sollt Euch in ihrem Dienst bewähren."},sec={{t="Ein Ruf ins Grenzland",b="Ihr seid von der Elementarebene nach Azeroth gekommen. Die Konflikte der Sterblichen mögen neben dem, was Ihr kennt, unbedeutend erscheinen, doch die Horde steht vor eigenen Gefahren. Der Dienst im Grenzland bietet Euch die Gelegenheit, mächtig zu werden und zugleich dem Reich beizustehen."},{t="Das Wegekreuz Kalimdors",b="Das Brachland liegt im Südwesten, und inmitten seiner weiten, sonnenverbrannten Ebenen steht das Wegekreuz. Dieser Außenposten der Horde ist ein wichtiger Knotenpunkt, doch Gefahren bedrängen seine Verteidiger von allen Seiten. Meldet Euch bei Thork und helft bei der Verteidigung der Siedlung."}},faq={{q="Wer ist Thork?",a="Thork ist ein Befehlshaber der Horde, der am Wegekreuz im Brachland stationiert ist. Er leitet die örtliche Verteidigung und weist Neuankömmlinge an, gegen Bedrohungen für die Siedlung und das Umland vorzugehen.",al={"wer ist thork","anführer des wegekreuzes","wo ist thork"}},{q="Was ist das Wegekreuz?",a="Das Wegekreuz ist ein Außenposten und Handelszentrum der Horde, an dem sich wichtige Wege im Brachland kreuzen. Feindselige Wildtiere, Zentaurenstämme und plündernde Stacheleber bedrohen die Siedlung, weshalb ihre Verteidiger Hilfe bei der Sicherung der Nachschubwege brauchen.",al={"was ist das wegekreuz","wegekreuz brachland","warum zum wegekreuz"}},{q="Wo liegt das Brachland?",a="Das Brachland ist eine weite, trockene Savanne im Herzen Kalimdors, südwestlich von Durotar. Es verbindet die Gebiete der Horde auf dem gesamten Kontinent.",al={"wo liegt das brachland","lage des brachlands"}},{q="Warum erwähnt die Quest die Elementarebene?",a="Der Reisende ist vor Kurzem von der Elementarebene nach Azeroth gekommen. Die dortigen Konflikte mögen gewaltig erscheinen, doch die Gefahren für die Welt der Sterblichen und die Horde sind unmittelbar und schwerwiegend.",al={"ankunft von der elementarebene","warum elementarebene","reise von der elementarebene"}},{q="Was soll Journey to the Crossroads am Wegekreuz bewirken?",a="Ihr werdet zum Wegekreuz geschickt, um Euch bei Thork zu melden. Dort könnt Ihr die Horde an vorderster Front unterstützen und durch ehrenvollen Dienst mächtig werden.",al={"zweck der quest zum wegekreuz","warum zum wegekreuz geschickt"}},{q="Welchen Gefahren sind die Bewohner des Wegekreuzes ausgesetzt?",a="Das Brachland ist ständigen Angriffen durch heimische Raubtiere, umherziehende Zentauren, Stacheleberkrieger und die vorrückende Allianz ausgesetzt. Seine Außenposten brauchen fähige Verteidiger, um standzuhalten.",al={"welche gefahren im brachland","bedrohungen im brachland"}}},fp="25,173,22.236.0,26.230.0,13.182.0,23.225.0,30.131.0,47.173.0,49.147.0,52.182.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="Nahe Auberdine überfällt Jai'vhanel Reisende auf den Küstenstraßen. Der Dorfrat von Auberdine hat ein Kopfgeld für ihren Tod nahe den Ruinen von Ameth'Aran ausgesetzt, und der Beweis soll Schildwache Glynda Nal'Shea gebracht werden.",h="Nahe Auberdine überfällt Jai'vhanel Reisende auf den Küstenstraßen.",kw={"ameth'aran","auberdine","schwarze eule","dunkelküste","glynda nal'shea","jai'vhanel","schwertfeder","wanted: jai'vhanel"},ang={["class:Druid"]="Als Nachtelfendruide beobachtet Ihr die Tierwelt der Dunkelküste genau. Jai'vhanels plötzlicher Wahnsinn und ihre Angriffslust beunruhigen jeden, dem die Wälder am Herzen liegen.",["class:Hunter"]="Als Jäger kennt Ihr Schwertfeder als wilde schwarze Eule nahe den Bergen der Dunkelküste. Ihr Jagdverhalten ist gefährlich unberechenbar geworden.",["faction:Alliance"]="Als Abenteurer der Allianz helft Ihr dem Dorfrat von Auberdine und den Schildwachen der Nachtelfen, die Küstenstraßen der Dunkelküste vor wahnsinnigen Raubtieren zu schützen."},sec={{t="Eine Bedrohung auf der Straße",b="Auf den Küstenstraßen der Dunkelküste nahe Auberdine droht Reisenden Gefahr durch eine wahnsinnige Eule. Jai'vhanel, die hier als Schwertfeder bekannt ist, hat sich gegen alle gewandt, die vorbeikommen. Sie überfällt Reisende und Kuriere nahe der Siedlung und macht die Straßen unsicher."},{t="Das Kopfgeld des Rates",b="Der Dorfrat von Auberdine bietet ein Kopfgeld, um die Straßen sicherer zu machen. Jai'vhanel jagt nördlich der Ruinen von Ameth'Aran, am Fuß der Berge entlang. Bringt Schildwache Glynda Nal'Shea in Auberdine eine ihrer schwarzen Federn als Beweis für ihren Tod, um die Belohnung zu erhalten."}},faq={{q="Wer ist Jai'vhanel?",a="Jai'vhanel, auch Schwertfeder genannt, ist eine große Eule mit schwarzen Federn. Sie ist in den Wäldern der Dunkelküste heimisch und durch Wahnsinn gegenüber Reisenden feindselig geworden.",al={"wer ist jaivhanel","was ist jaivhanel","wer ist schwertfeder"}},{q="Warum ist ein Kopfgeld auf Jai'vhanel ausgesetzt?",a="Der Dorfrat von Auberdine hat ein Kopfgeld ausgesetzt, weil Jai'vhanel wahnsinnig geworden ist und Reisende auf der Hauptstraße nahe Auberdine angreift und gefährdet.",al={"warum jaivhanel töten","warum gibt es ein kopfgeld auf jaivhanel","warum wird die eule angegriffen"}},{q="Wo ist Jai'vhanel zu finden?",a="Jai'vhanel streift nördlich der Ruinen von Ameth'Aran an der Dunkelküste umher, nahe dem Fuß der östlichen Berge.",al={"wo ist jaivhanel","jaivhanel fundort","wo ist schwertfeder zu finden"}},{q="Wer hat das Kopfgeld auf Jai'vhanel ausgesetzt?",a="Der Dorfrat von Auberdine hat das Kopfgeld ausgesetzt. Er kümmert sich um die Sicherheit und das Wohlergehen von Auberdine sowie um die Sicherheit der umliegenden Straßen.",al={"wer hat das kopfgeld ausgesetzt","wer will jaivhanel tot sehen"}},{q="Wer erhält die Belohnung für Jai'vhanel?",a="Bringt Schildwache Glynda Nal'Shea in Auberdine eine von Jai'vhanels schwarzen Federn als Beweis für ihren Tod.",al={"wer nimmt den todesbeweis entgegen","wo jaivhanels feder abgeben","glynda nalshea kopfgeld"}},{q="Welcher Beweis wird benötigt, um das Kopfgeld zu erhalten?",a="Eine von Jai'vhanels schwarzen Federn beweist, dass sie getötet wurde.",al={"was gilt als todesbeweis für jaivhanel","welcher gegenstand beweist jaivhanels tod"}}},fp="18,212,20.238.0,20.265.0,18.151.0,36.156.0,30.104.0,36.134.0,39.103.0,41.61.0"}
P.entries["quest:98027"] = {n="Gleaming Crescent Necklace",s="Eine glänzende Halbmondhalskette trägt eine Inschrift, die sie mit Maliynn in Astranaar verbindet. Ihr könnt das Andenken seiner Besitzerin zurückbringen.",h="Eine glänzende Halbmondhalskette trägt eine Inschrift, die sie mit Maliynn in Astranaar verbindet.",kw={"alor'lormah","astranaar","halbmondhalskette","gleaming crescent necklace","maliynn","symbol der nachtelfen","silberne halskette"},ang={["race:NightElf"]="Als Nachtelf erkennt Ihr die Halbmondform vielleicht unter den Symbolen wieder, die Ihr gesehen habt."},sec={{t="Die Inschrift",b="Ihr untersucht eine silberne Halskette in Form einer Mondsichel. Ihre Form erinnert an andere Symbole der Nachtelfen, die Ihr gesehen habt, und auf ihrer Rückseite steht: „Alor'lormah, Maliynn.“ Der Name verweist auf Maliynn in Astranaar, wo die Halskette ihre Besitzerin finden könnte."},{t="Maliynns Andenken",b="Maliynn in Astranaar erkennt die Halskette als ihre eigene wieder. Sie verlor sie, als sie Vorräte zu einem Außenposten brachte, und suchte dann entlang der Straße, bevor sie aufgab. Ihre verstorbenen Eltern hatten sie ihr geschenkt, und es bedeutet ihr viel, sie zurückzubekommen."}},faq={{q="Wem gehört die Halskette?",a="Die Inschrift trägt Maliynns Namen, und in Astranaar erkennt sie die Halskette als ihre eigene wieder.",al={"wem gehört sie","besitzerin der halskette","maliynn halskette"}},{q="Wie sieht die Halskette aus?",a="Es ist eine silberne Halskette in Form einer kleinen Mondsichel.",al={"halbmondhalskette","welche form hat sie","silberne halskette"}},{q="Was steht auf der Halskette?",a="Die Inschrift lautet: „Alor'lormah, Maliynn.“",al={"inschrift der halskette","was steht darauf","alor'lormah"}},{q="Wohin kann ich die Halskette bringen?",a="Bringt die Crescent Necklace zu Maliynn in Astranaar.",al={"wohin bringen","maliynn aufenthaltsort","astranaar halskette"}},{q="Warum ist die Halskette Maliynn wichtig?",a="Sie war ein Geschenk ihrer verstorbenen Eltern.",al={"warum ist sie wichtig","maliynns andenken","geschenk der eltern"}},{q="Wie hat Maliynn sie verloren?",a="Maliynn verlor sie, als sie Vorräte zu einem ihrer Außenposten brachte. Sie suchte entlang der Straße, bevor sie aufgab.",al={"wie halskette verloren","wo hat sie sie verloren","lost necklace"}}},fp="26,127,15.263.0,18.218.1,32.91.0,33.58.0,32.49.0,31.52.0,40.36.0,24.111.0"}
P.entries["quest:98028"] = {n="Baron Marinous",s="Onu will erfahren, was mit einer Wasserkugel geschah, die ein Elementarwächter hinterlassen hat. Ihr bringt sie ihm im Hain der Uralten, wo er ein beunruhigendes Zeichen erkennt.",h="Onu will erfahren, was mit einer Wasserkugel geschah, die ein Elementarwächter hinterlassen hat.",kw={"baron marinous","clouded water globe","dunkelküste","elementarwächter","der hain der uralten","mathystra","naga","onu"},sec={{t="Onus Rat",b="Onu im Hain der Uralten benötigt die Clouded Water Globe. Der Elementarwächter ist besiegt, doch die Kugel bleibt getrübt, und was auch immer dem Wächter und den von ihm bewachten Ruinen widerfuhr, könnte noch immer wirken. Ihr bringt sie zu Onu, der am ehesten mehr darüber wissen dürfte."},{t="Onus Sorge",b="Im Hain der Uralten reagiert Onu überrascht auf die Kugel und fragt sich, ob es in Mathystra Treppen gibt, die hinabführen. Er sagt, er müsse sich mit den anderen beraten. Er ist froh, dass Ihr dies vor den Naga oder ihren Kultverbündeten entdeckt habt, und merkt an, dass der Sieg über den Elementarwächter keine geringe Leistung war."}},faq={{q="Wer ist Onu?",a="Onu ist der Ancient of Lore im Hain der Uralten in Dunkelküste.",al={"onu","onu hintergrund","ancient of lore"}},{q="Was ist die Clouded Water Globe?",a="Sie ist alles, was von einem mächtigen Elementar übrig ist, eine Wasserkugel, die von einer unbekannten Substanz getrübt wird.",al={"getrübte kugel","wasserkugel","kugel vom elementar"}},{q="Warum wirkt die Kugel getrübt?",a="Eine unbekannte Substanz trübt die Kugel und scheint jeden Blick in ihr Inneres zu verhindern.",al={"was ist in der kugel","getrübtes wasser","warum kein blick ins innere"}},{q="Wohin bringe ich die Kugel?",a="Bringt die Clouded Water Globe zu Onu im Hain der Uralten in Dunkelküste.",al={"wo ist onu","standort des hains","kugel bringen"}},{q="Was ist mit dem Elementarwächter geschehen?",a="Der Elementarwächter wurde besiegt, und die Kugel ist alles, was von ihm übrig ist.",al={"schicksal des elementars","wächter tot","was geschah mit dem wächter"}},{q="Was sagt Onu über die Naga?",a="Onu sagt, es sei gut, dass die Kugel vor den Naga oder ihren Kultverbündeten entdeckt wurde.",al={"naga und kugel","kultverbündete","warum vor den naga"}}},fp="14,168,13.268.0,13.304.1,11.69.0,32.97.0,32.85.0,26.79.0,40.82.0,33.81.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="Thundris hört einen beunruhigenden Bericht und untersucht die ihm vorgelegte Entdeckung. Ihr Zeichen führt dazu, dass das Relikt zur Untersuchung nach Darnassus geschickt wird.",h="Thundris hört einen beunruhigenden Bericht und untersucht die ihm vorgelegte Entdeckung.",kw={"uraltes böses","ande'thoras-ethil","darnassus","zeichen eines uralten bösen","nachtelf","thundris"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr beunruhigende Entdeckungen den Obrigkeiten der Nachtelfen vorlegen, damit darnassische Gelehrte gefährliche Relikte untersuchen und sicher verwahren können.",["race:NightElf"]="Als Nachtelf erlebt Ihr, wie Darnassus sofort auf eine Entdeckung reagiert, die von uralter Verderbnis gezeichnet ist."},sec={{t="Ein beunruhigender Bericht",b="Ihr bringt eine beunruhigende Entdeckung zu Thundris und sucht seinen Rat. Er hört Euren Bericht an und untersucht, was Ihr mitgebracht habt. Dann verstummt er, denn die Zeichen vor ihm sind zu finster, um sie abzutun."},{t="Das Zeichen uralten Übels",b="Thundris erkennt an der Entdeckung das Zeichen eines uralten Bösen. Er weiß, dass die Gefahr über ein örtliches Missgeschick hinausgeht, und schickt das Relikt deshalb sofort nach Darnassus. Die Gelehrten und Priester der Hauptstadt werden es untersuchen und sicher verwahren."}},faq={{q="Wer ist am Abschluss dieser Quest beteiligt?",a="Thundris hört den beunruhigenden Bericht des Abenteurers an und untersucht den vorgelegten Gegenstand oder Beweis. Er bereitet ihn für den Transport vor.",al={"wer vergibt it's all fun and games until","thundris quest","bei wem it's all fun and games until abgeben"}},{q="Warum wird der Gegenstand nach Darnassus geschickt?",a="Thundris erkennt das Zeichen eines uralten Bösen und sagt, dass der Fund sofort zur Untersuchung nach Darnassus gebracht wird.",al={"warum nach darnassus schicken","untersuchung in darnassus","uraltes böses darnassus"}},{q="Was ist das uralte Böse, auf das Thundris verweist?",a="Thundris erwähnt das Zeichen eines uralten Bösen, nennt aber vor einer genaueren Untersuchung in der Hauptstadt der Nachtelfen keine Einzelheiten zu dessen Ursprung.",al={"was ist das uralte böse","zeichen uralten übels bedeutung"}},{q="Was bedeutet 'Ande'thoras-ethil'?",a="„Ande'thoras-ethil“ ist eine darnassische Wendung, die Thundris zum Abschluss seines Gesprächs mit Euch spricht, nachdem er die Überführung des Fundes nach Darnassus angekündigt hat.",al={"bedeutung von ande'thoras-ethil","andethoras ethil nachtelfische wendung","darnassischer abschiedsgruß thundris"}},{q="Was geschieht nach Abschluss der Quest?",a="Nachdem Thundris das Zeichen uralter Verderbnis erkannt hat, bereitet er das Relikt für den sofortigen Transport nach Darnassus vor, wo Gelehrte es untersuchen können.",al={"was geschieht nach it's all fun and games until","nächste quest nach fun and games","to darnassus folgequest"}},{q="Welche Fraktion führt diese Untersuchung durch?",a="Die Führung von Darnassus und Nachtelfen wie Thundris kümmern sich um die Angelegenheit und tragen Bedrohungen den Obrigkeiten der Nachtelfen vor.",al={"ist it's all fun and games nur für die allianz","wer kann it's all fun and games until machen"}}},fp="31,128,18.198.0,24.226.1,41.123.0,42.108.0,48.130.0,35.145.0,40.146.0,41.129.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="In Darnassus wendet sich Fandral Hirschhaupt nach einem gescheiterten Ritual ab und schickt dessen Gefäß fort. Er bittet Euch, es zur Entsorgung zu Priesterin Lariia im Tempel des Mondes zu bringen.",h="In Darnassus wendet sich Fandral Hirschhaupt nach einem gescheiterten Ritual ab und schickt dessen Gefäß fort.",kw={"zirkel des cenarius","crown of the earth","darnassus","ausgelaugtes gefäß","elune","fandral hirschhaupt","lariia","malfurion","tempel des mondes"},ang={["class:Druid"]="Fandral spricht Euch als Druiden an. Er begegnet dem Scheitern des Rituals mit knapper Ungeduld und schickt Euch dann fort.",["faction:Alliance"]="Darnassus ist die wichtigste Stadt der Allianz auf Kalimdor. Während Malfurion Sturmgrimm abwesend ist, herrscht in der Stadt eine unterschwellige Spannung in der Führung.",["race:NightElf"]="In Darnassus trifft Fandral Hirschhaupts schroffe Autorität auf die geduldige Hingabe der Sisterhood of Elune im Tempel des Mondes."},sec={{t="Fandrals Frustration",b="Erzdruide Fandral Hirschhaupt führt die Nachtelfen, während Malfurion Sturmgrimm abwesend ist. Auf der Suche nach Antworten spricht er einen Zauber mit heiligem Wasser in einem Fläschchen. Das Ritual bringt keine Antwort, und Fandrals Zorn wächst. Überzeugt, dass das Wasser nutzlos ist, schickt er Euch mit scharfen Worten fort und nach Süden zum Tempel des Mondes, wo die Priesterinnen das Gefäß entsorgen können."},{t="Die verbliebenen Tropfen",b="Priesterin Lariia bittet Euch, Fandrals schroffe Art und die Last, die er trägt, nachzusehen. Als sie das Fläschchen untersucht, findet sie noch einige Tropfen Wasser darin. Vielleicht ist Fandrals Magie nicht fehlgeschlagen; vielleicht wurde das Gefäß nie geleert."}},faq={{q="Wer vergibt die Quest Crown of the Earth?",a="Erzdruide Fandral Hirschhaupt erteilt Euch den Auftrag in Darnassus. Während Malfurion Sturmgrimm abwesend ist, beaufsichtigt Fandral den Zirkel des Cenarius. Nachdem ein Zauber mit heiligem Wasser keine Antworten bringt, schickt er Euch frustriert fort.",al={"wer startet crown of the earth","questgeber für crown of the earth","fandral-quest"}},{q="Wohin bringt Ihr das Ausgelaugte Gefäß?",a="Ihr bringt das Ausgelaugte Gefäß zu Priesterin Lariia im Tempel des Mondes im Süden von Darnassus. Fandral erwartet, dass die Priesterinnen Elunes das Gefäß entsorgen, von dem er glaubt, dass es keinen Nutzen mehr hat.",al={"wohin mit ausgelaugtem gefäß","abgabe ausgelaugtes gefäß","wo ist lariia"}},{q="Warum ist Fandral Hirschhaupt so frustriert?",a="Fandral Hirschhaupt trägt die Last, die Nachtelfen zu führen und den Zirkel des Cenarius zu leiten, während Malfurion Sturmgrimm fort ist. Als sein Zauber nichts bewirkt, lassen ihn Frustration und Stolz um sich schlagen, und er schickt Euch fort, bevor er das Scheitern genauer untersucht.",al={"warum ist fandral wütend","fandrals verhalten","warum ist fandral ungeduldig"}},{q="Warum schlug Fandrals Beschwörung fehl?",a="Fandral glaubt, das Wasser habe keine nützliche Kraft, doch Priesterin Lariia findet noch einige Tropfen, die im Gefäß haften. Vielleicht scheiterte das Ritual, weil das Gefäß nicht vollständig geleert worden war.",al={"warum schlug die beschwörung fehl","hat fandrals ritual funktioniert","fehlgeschlagene beschwörung"}},{q="Wo ist Malfurion während dieser Quest?",a="Malfurion Sturmgrimm ist nicht in Darnassus. Erzdruide Fandral Hirschhaupt führt die Nachtelfen und leitet in seiner Abwesenheit den Zirkel des Cenarius, eine schwere Last, die Fandrals Zorn und Ungeduld bei Rückschlägen nährt.",al={"wo ist malfurion","warum ist malfurion abwesend","status von malfurion"}},{q="Wer ist Priestess Lariia?",a="Priesterin Lariia dient Elune im Tempel des Mondes in Darnassus. Sie nimmt das Gefäß mit Mitgefühl für Fandrals Bürden entgegen und bemerkt, dass noch Wasser darin ist.",al={"wer ist lariia","wissen über priesterin lariia","lariia tempel des mondes"}}},fp="18,166,21.381.0,19.245.1,39.223.0,37.198.0,38.263.0,35.189.0,37.215.0,24.170.0"}
P.entries["quest:98059"] = {n="Hillsbrad's Hoard",s="Eine Kompanie bittet Euch, eine versiegelte Anfrage zum Rathaus von Hillsbrad zu bringen. Der Rat hat dem neuen Magistrat nicht geantwortet, und die Kompanie möchte einen kleinen Zug.",h="Eine Kompanie bittet Euch, eine versiegelte Anfrage zum Rathaus von Hillsbrad zu bringen.",kw={"buchhaltungstisch","rat","hillsbrad","schatz von hillsbrad","magistrat","zug","versiegelte anfrage der kompanie","belagerungsballisten","rathaus"},sec={{t="Eine versiegelte Anfrage",b="Die Kompanie gibt Euch einen Brief für den Buchhaltungstisch im Rathaus von Hillsbrad. Der Rat hat auf die Briefe des neuen Magistrats nicht geantwortet, und der Bericht eines Händlers hat die Sorge der Kompanie verstärkt. Hinter den Mauern der Stadt stehen mehrere Belagerungsballisten in makellosem Zustand. Vorerst bittet die Kompanie um einen kleinen Zug und ersucht Euch, ihre Anfrage ins Rathaus zu bringen."},{t="Die Antwort der Kompanie",b="Die Kompanie nimmt Eure Hilfe an, obwohl Ihr keiner ihrer Soldaten seid. Der Brief soll eine Antwort von Hillsbrads Rat erwirken. Sollte das Schweigen anhalten, warnt die Kompanie, dass ihre nächste Nachricht weniger höflich ausfallen könnte, und hält Euch für künftige Angelegenheiten mit Zivilisten in Reserve."}},faq={{q="Wer gibt mir den Brief?",a="Eine Kompanie gibt Euch die versiegelte Anfrage für das Rathaus von Hillsbrad.",al={"wer hat diesen brief geschickt","wer gibt die anfrage der kompanie"}},{q="Warum hat der Rat nicht geantwortet?",a="Die Kompanie sagt, dass Hillsbrads Rat nicht auf die Briefe des neuen Magistrats geantwortet hat.",al={"warum keine antwort","schweigen des rats von hillsbrad"}},{q="Was will die Kompanie von Hillsbrad?",a="Die Kompanie bittet Hillsbrad um einen kleinen Zug.",al={"worum bitten sie","anfrage nach kleinem zug"}},{q="Was hat der Händler berichtet?",a="Ein vorbeikommender Händler berichtete von mehreren Belagerungsballisten in makellosem Zustand in einem abgeschotteten Gelände.",al={"händlerbericht","was ist im gelände"}},{q="Wohin gehört die versiegelte Anfrage?",a="Legt die versiegelte Anfrage auf den Buchhaltungstisch im Rathaus von Hillsbrad.",al={"wohin mit dem brief","buchhaltungstisch"}}},fp="17,160,16.369.0,19.279.1,24.65.0,32.83.0,42.52.0,29.103.0,33.79.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="In Darnassus werden gereinigte Mondbrunnenüberreste zu Hohepriesterin Tyrande Wisperwind gebracht. Die Begegnung findet im Tempel des Mondes statt, wo die heilige Bedeutung des Wassers auf die Spannungen zwischen Tyrande und Erzdruide Fandral Hirschhaupt trifft.",h="In Darnassus werden gereinigte Mondbrunnenüberreste zu Hohepriesterin Tyrande Wisperwind gebracht.",kw={"crown of the earth","darnassus","elune","fandral hirschhaupt","malfurion","mondbrunnenüberreste","tempel des mondes","tyrande wisperwind"},ang={["class:Druid"]="Als Druide hört Ihr Tyrandes scharfe Worte über Erzdruide Fandral Hirschhaupt, die die wachsenden Reibungen im Zirkel des Cenarius während Malfurions Abwesenheit zeigen.",["class:Priest"]="Als Priester dient Ihr Hohepriesterin Tyrande Wisperwind, deren Geistliche die Gesellschaft der Nachtelfen mitführen und mitregieren.",["faction:Alliance"]="Als Verbündeter begegnet Ihr der Anführerin von Darnassus und erhaltet Einblick in die politischen Spannungen in einer der wichtigsten Hauptstädte der Allianz.",["race:NightElf"]="Als Nachtelf tragt Ihr heiliges Mondbrunnenwasser zu einer Begegnung, die die Spaltung der Führung der Kaldorei zwischen Tyrandes Priesterschaft und Fandrals Druiden zeigt."},sec={{t="Audienz bei der Hohepriesterin",b="Sobald die heiligen Mondbrunnenüberreste gesammelt sind, gießt Ihr das gesegnete Wasser in ein zeremonielles Gefäß und tragt es zu Tyrande Wisperwind. Die Hohepriesterin von Elune hält hoch oben im Tempel des Mondes in Darnassus Audienz. Sie wacht über die Stadt und spendet allen, die eintreten, das Licht ihrer Göttin. Heiliges Wasser in ihre Obhut zu geben, ist eine Ehre und ein Akt der Hingabe an Elune."},{t="Spannungen in der Führung",b="Tyrande dankt Euch von Herzen für die Rettung des gesegneten Wassers. Dann wenden sich ihre Gedanken den Spannungen zu, die Darnassus im Griff haben. In Malfurion Sturmgrimms Abwesenheit hat Erzdruide Fandral Hirschhaupt die Leitung der druidischen Angelegenheiten übernommen. Doch Tyrande stellt klar, dass die Führung der Kaldorei allein ihre Bürde ist. Sie mahnt zu Respekt vor Hirschhaupts Stellung, doch der Austausch offenbart heftige Reibungen zwischen der Sisterhood of Elune und dem Zirkel des Cenarius."}},faq={{q="Was ist Crown of the Earth?",a="In Darnassus tragt Ihr Mondbrunnenüberreste in einem zeremoniellen Gefäß zu Hohepriesterin Tyrande Wisperwind im Tempel des Mondes. Die Begegnung führt Euch vor die oberste Anführerin der Nachtelfen.",al={"was ist crown of the earth","crown of the earth quest","quest crown of the earth"}},{q="Wer ist Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin von Elune und die politische Anführerin der Nachtelfen. Von der oberen Ebene des Tempels des Mondes aus wacht sie über Darnassus und trägt die Bürde, ihr Volk durch unruhige Zeiten zu führen.",al={"wer ist tyrande wisperwind","wo ist tyrande","hohepriesterin tyrande"}},{q="Warum werden die Mondbrunnenüberreste zu Tyrande gebracht?",a="Die Mondbrunnenüberreste sind heiliges, von Elune gesegnetes Wasser. Ihr füllt sie in ein zeremonielles Gefäß und bringt sie zu Tyrande, die sie im Namen der Göttin entgegennimmt und bewahrt.",al={"warum mondbrunnenüberreste zu tyrande bringen","was sind mondbrunnenüberreste","heiliges wasser darnassus"}},{q="Worum geht es im Streit zwischen Tyrande und Fandral Hirschhaupt?",a="In Malfurion Sturmgrimms Abwesenheit führt Erzdruide Fandral Hirschhaupt die Druiden an. Tyrande besteht darauf, dass die Regierung von Darnassus und die Führung der Kaldorei allein ihre Verantwortung bleiben, und duldet nicht, dass druidische Autorität Elunes Priesterschaft in den Schatten stellt.",al={"tyrande fandral spannungen","warum mag tyrande hirschhaupt nicht","fandral gegen tyrande"}},{q="Wo ist Malfurion während dieser Quest?",a="Malfurion Sturmgrimm ist nicht in Darnassus und hinterlässt eine Führungslücke unter den Druiden. Erzdruide Fandral Hirschhaupt ist eingesprungen, um sie zu füllen, was die politischen Spannungen mit Tyrande verschärft.",al={"wo ist malfurion","was ist mit malfurion geschehen","malfurions abwesenheit"}},{q="Wo ist der Tempel des Mondes?",a="Der Tempel des Mondes steht im Herzen von Darnassus. Er ist das wichtigste Heiligtum der Sisterhood of Elune, und Tyrande hält auf der oberen Ebene über dem Hauptraum des Heiligtums Audienz.",al={"tempel des mondes standort","wo ist der tempel des mondes","wo tyrande finden"}}},fp="18,247,32.385.0,22.423.1,27.198.0,27.228.0,49.181.0,57.244.0,37.193.0,32.185.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="In Darnassus lässt Sentinel Dalia Sunblade Eulen wachen, während sich Unruhe über Teldrassil ausbreitet. Ihre Posten schützen die Stadt und lassen den Schildwachen Zeit, zu Elune zu beten.",h="In Darnassus lässt Sentinel Dalia Sunblade Eulen wachen, während sich Unruhe über Teldrassil ausbreitet.",kw={"burg cenarius","craftsman terrace","dalia sunblade","darnassus","elune","eyes of the sentinels","mondfeder","schildwacheneulen","teldrassil","tempel des mondes"},ang={["class:Hunter"]="Spähereulen spiegeln das traditionelle Geschick der Nachtelfen in der Aufklärung wider. Abgerichtete Tiere und himmlische gefiederte Wächter erweitern die Sinne einer Jägerin.",["class:Priest"]="Waffen allein können die Kaldorei nicht schützen. Regelmäßige Gebete und Elunes spirituelle Gaben sind für den Schutz durch die Schildwachen unerlässlich.",["faction:Alliance"]="Die Bewachung von Darnassus schützt die Hauptstadt der Nachtelfen und stärkt den wichtigsten Stützpunkt der Allianz im nördlichen Kalimdor.",["race:NightElf"]="Die Schildwachen sind das traditionelle stehende Heer und die Wächterinnen der Nachtelfen. Sie vereinen kriegerisches Können mit Elunes Segen und wachsamen Augen."},sec={{t="Hingabe und Verteidigung",b="Am Tempel des Mondes wacht Sentinel Dalia Sunblade über Darnassus. Generalin Shandris Mondfeder hat verfügt, dass jeder Krieger Kampfkönnen mit Hingabe an Elune verbinden muss. Deshalb lässt Dalia Schildwacheneulen an wichtigen Orten der Stadt wachen. Ihre täglichen Dienste lassen den Schildwachen Zeit für Gebet und Besinnung vor der Mondgöttin, während Darnassus bewacht bleibt."},{t="Wacht über Darnassus",b="Unruhe breitet sich über Teldrassil aus, und die Schildwachen werden wachsamer. Schildwacheneulen beziehen Posten am nördlichen Eingang zu den Tiefen unter der Burg Cenarius, an der Bank auf dem Stadtplatz, am Gasthaus auf der Craftsman's Terrace und an den Haupttoren der Stadt. Örtliche Stadtwachen helfen dabei, sie zu platzieren. Von diesen Posten aus wachen die Eulen über jene, die durch die Straßen des Großen Baumes ziehen."}},faq={{q="Was ist Eyes of the Sentinels?",a="Sentinel Dalia Sunblade leitet die Platzierung von Schildwacheneulen an wichtigen Punkten in ganz Darnassus. Ihre Wacht hilft den Schildwachen, die Stadt vor drohenden Gefahren zu schützen.",al={"eyes of the sentinels quest","was ist eyes of the sentinels","eyes of the sentinels überblick"}},{q="Wer ist Sentinel Dalia Sunblade?",a="Sentinel Dalia Sunblade ist eine Wächterin der Kaldorei am Tempel des Mondes in Darnassus. Sie beaufsichtigt die örtliche Verteidigung und sorgt dafür, dass wachsame Eulen wichtige Verkehrswege bewachen.",al={"wer ist dalia sunblade","dalia sunblade hintergrundgeschichte","sentinel dalia sunblade"}},{q="Warum werden Schildwacheneulen in ganz Darnassus platziert?",a="Die Schildwacheneulen wachen über Darnassus als Ausguck aus der Luft und als göttliche Späher, die Elune gewährt. Sie überwachen wichtige Versammlungsorte und Engpässe der Verkehrswege.",al={"warum schildwacheneulen platzieren","was tun schildwacheneulen","zweck der schildwacheneulen"}},{q="Wo werden die Schildwacheneulen platziert?",a="Die Schildwacheneulen werden am nördlichen Eingang zu den Tiefen unter der Burg Cenarius, an der Darnassus Bank im Stadtzentrum, am Gasthaus auf der Craftsman's Terrace und an den Stadttoren stationiert.",al={"standorte für eulen","wohin kommen die eulen","eyes of the sentinels standorte"}},{q="Warum sind die Schildwachen in Teldrassil in höchster Alarmbereitschaft?",a="Sentinel Dalia Sunblade sagt, dass auf ganz Teldrassil, dem Weltbaum, etwas nicht zu stimmen scheint. Deshalb verstärken die Schildwachen ihre Wacht und halten sich für ungesehene Gefahren bereit.",al={"warum sind die schildwachen besorgt","was stimmt mit teldrassil nicht","etwas stimmt in teldrassil nicht"}},{q="Welche Rolle spielt Generalin Mondfeder bei den täglichen Pflichten der Schildwachen?",a="Generalin Shandris Mondfeder befehligt die Schildwachen und sorgt dafür, dass ihre Jägerinnen kriegerische Pflichten mit täglicher Hingabe und Gebeten an Elune verbinden.",al={"rolle von generalin mondfeder","shandris mondfeder schildwachen","mondfeders gebetsregel"}}},fp="21,165,20.384.0,20.363.0,30.164.0,31.167.0,52.151.0,35.181.0,50.158.0,71.144.0"}
P.entries["quest:98069"] = {n="Stolen Freewind Supplies",s="Am Freiwindposten braucht Jandia die von den Harpyien gestohlenen Vorräte zurück. Noch hat der Posten genug, doch ohne eine weitere Lieferung werden die Vorräte bald knapp.",h="Am Freiwindposten braucht Jandia die von den Harpyien gestohlenen Vorräte zurück.",kw={"karawane","höhle","klippe","freiwindposten","harpyien","jandia","stolen freewind supplies","vorräte"},sec={{t="Die verloren gegangene Lieferung",b="Die Harpyien überfielen die letzte Karawane auf dem Weg zum Freiwindposten. Jandia sagt, der Posten komme vorerst zurecht, doch ohne Nachschub werden seine Vorräte nicht lange reichen. Der Unterschlupf der Harpyien liegt westlich des Postens, am Fuß der Klippen und in einer Höhle darüber."}},faq={{q="Wer braucht die Vorräte?",a="Jandia am Freiwindposten braucht die gestohlenen Vorräte zurück.",al={"wer bat um vorräte","jandia vorräte","freewind vorräte"}},{q="Wer hat die Vorräte der Karawane gestohlen?",a="Harpyien griffen die letzte Karawane an, die Vorräte zum Freiwindposten brachte.",al={"wer hat sie gestohlen","harpyien vorräte","was haben harpyien gestohlen"}},{q="Wo ist der Unterschlupf der Harpyien?",a="Der Unterschlupf der Harpyien liegt westlich des Freiwindpostens, am Fuß der Klippen und in einer Höhle darüber.",al={"wo sind harpyien","harpyienhöhle","harpyien im westen"}},{q="Warum braucht Jandia sie zurück?",a="Der Freiwindposten hat vorerst genug Vorräte, doch ohne eine weitere Lieferung werden sie bald knapp.",al={"warum vorräte zurückholen","freewind vorräte werden knapp","warum sind vorräte wichtig"}},{q="Was sollt Ihr für Jandia zurückholen?",a="Jandia bittet Euch, acht gestohlene Vorräte für den Freiwindposten zurückzuholen.",al={"wie viele vorräte","gestohlene waren","was soll mitgebracht werden"}}},fp="24,147,20.239.0,23.60.0,32.69.0,24.87.0,31.95.0,36.67.0"}
P.entries["quest:98070"] = {n="Stop the Screeching",s="In der Kreischenden Schlucht überfallen Harpyien Versorgungskarawanen auf dem Weg zum Freiwindposten. Ihre Angriffe könnten die Karawanen daran hindern, dorthin zu reisen.",h="In der Kreischenden Schlucht überfallen Harpyien Versorgungskarawanen auf dem Weg zum Freiwindposten.",kw={"karawane","freiwindposten","harpyie","schurkenfeder","kreischende schlucht","kreischende harpyie","stop the screeching","vorräte","windrufer"},sec={{t="Karawanen in Gefahr",b="Ein Lieferant fürchtet, dass die Harpyienangriffe Karawanen daran hindern werden, zum Freiwindposten zu reisen. Ihr sollt Kreischende Harpyien, Kreischende Schurkenfederharpyien und Kreischende Windrufer töten. Bis dahin bleiben Karawanen, die sich in die Schlucht wagen, in Gefahr."},{t="Nachricht an die Lieferanten",b="Nachdem die Harpyien beseitigt sind, wird der Lieferant diejenigen benachrichtigen, die Waren zum Freiwindposten liefern. Dann sind die Karawanen auf ihren Reisen einer Gefahr weniger ausgesetzt."}},faq={{q="Warum werden die Karawanen angegriffen?",a="Harpyien in der Kreischenden Schlucht haben die letzten Versorgungskarawanen überfallen, die dort hindurchreisten.",al={"harpyien greifen karawanen an","warum harpyien angreifen","karawanenprobleme"}},{q="Was steht auf dem Spiel, wenn die Angriffe weitergehen?",a="Der Lieferant fürchtet, dass sich keine Karawanen mehr zum Freiwindposten wagen werden, wenn die Angriffe weitergehen.",al={"warum karawanen schützen","versorgung des freiwindpostens","karawanen bleiben aus"}},{q="Welche Harpyien sind beteiligt?",a="Bei den Harpyien handelt es sich um Kreischende Harpyien, Kreischende Schurkenfederharpyien und Kreischende Windrufer.",al={"harpyienarten","kreischende harpyien","schurkenfeder windrufer"}},{q="Wo sind die Harpyien?",a="Die Harpyien leben in der Kreischenden Schlucht.",al={"aufenthaltsort der harpyien","harpyien der kreischenden schlucht","wo ist die kreischende schlucht"}}},fp="19,137,16.250.0,17.163.1,36.89.0,40.89.0,27.96.0,22.38.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="In Hillsbrad bringt Ihr Fallrook Varietal nach Dun Garok, wo die Brausippe ihn gegen Homebrew Hops tauscht. Sie vermisst die Weingärten der Familie Fallrook, und in den Kellern lagern noch Kisten mit Wein.",h="In Hillsbrad bringt Ihr Fallrook Varietal nach Dun Garok, wo die Brausippe ihn gegen Homebrew Hops tauscht.",kw={"brausippe","dun garok","fallrook","fallrook varietal","hillsbrad","homebrew hops","hopfen","wein"},sec={{t="Ein Geschmack der Vergangenheit",b="Fallrook-Wein wartet noch immer in den Kellern, doch die meisten der besten abgefüllten Jahrgänge der Familie sind längst aufgebraucht. Die Brausippe von Dun Garok vermisst jene Weingärten, also wurde ein Handel vereinbart."},{t="Der Tausch in Dun Garok",b="Ihr tragt eine Kiste nach Südosten nach Dun Garok. Die Brausippe versammelt sich neben der Feuerstelle am Fuße ihrer Festung. Im Gegenzug bringt Ihr einen Sack ihres Homebrew Hops zurück."}},faq={{q="Was wird bei diesem Handel getauscht?",a="Eine Kiste Fallrook Varietal gelangt aus den Kellern zur Brausippe von Dun Garok, im Tausch gegen einen Sack ihres Homebrew Hops.",al={"was wird geliefert","brewer's trade gegenstände","fallrook-wein"}},{q="Wohin muss der Wein in Dun Garok gebracht werden?",a="Ihr gebt den Wein bei der Brausippe neben der Feuerstelle ab, wo sie sich am Fuße ihrer Festung versammelt.",al={"wo ist die feuerstelle","dun garok abgabeort","wo wein abgeben"}},{q="Wo liegt Dun Garok?",a="Dun Garok liegt im Südosten des Vorgebirges des Hügellands.",al={"dun garok lage","wo ist dun garok"}},{q="Wer war die Familie Fallrook?",a="Die Fallrooks waren eine Familie, deren Weingärten vermisst werden. Die meisten ihrer besten abgefüllten Jahrgänge sind längst getrunken, doch in den Kellern lagern noch Kisten ihres Weins.",al={"familie fallrook","fallrook weingärten"}}},fp="14,183,19.181.0,25.165.0,38.126.0,44.103.0,27.55.0,23.166.0"}
P.entries["quest:98072"] = {n="Crocs of the Sky",s="James fragt, ob Ihr die Schuppen habt, und lobt dann Euer Können. Er bietet Euch Arbeit an, falls Ihr das Abenteurerleben hinter Euch lasst.",h="James fragt, ob Ihr die Schuppen habt, und lobt dann Euer Können.",kw={"abenteurerleben","crocs of the sky","james","schuppen","arbeit"},sec={{t="James' Angebot",b="James nennt Euch ein Naturtalent und lädt Euch ein zurückzukehren, falls Ihr eine Pause vom Abenteurerleben einlegt. Er scherzt, dass Ihr bis dahin vielleicht älter seid."}},faq={{q="Wer fragt nach den Schuppen?",a="James fragt, ob Ihr die Schuppen habt.",al={"wer will die schuppen","schuppen für james"}},{q="Was hält James von mir?",a="James hält Euch für ein Naturtalent.",al={"mag james mich","james meinung"}},{q="Was bietet James an?",a="James bietet Euch Arbeit an, falls Ihr eine Pause vom Abenteurerleben einlegt.",al={"james arbeit","arbeitsangebot"}}},fp="16,111,13.131.0,31.39.0,28.38.0,22.59.0"}
P.entries["quest:98093"] = {n="Field to Clear",s="Sulhasa sitzt nahe Camp Taurajo auf einem Baum fest. Stormhide lizards und Hecklefang Stalkers versperren ihr den Heimweg. Sie bittet Euch, das Gebiet zu säubern, damit sie sicher hinunterklettern kann.",h="Sulhasa sitzt nahe Camp Taurajo auf einem Baum fest.",kw={"camp taurajo","goldene straße","hecklefang stalkers","südliches brachland","stormhide lizards","festsitzend","sulhasa","baum"},sec={{t="Ein versperrter Heimweg",b="Sulhasa sitzt oberhalb der Felder fest, nachdem sie von Camp Taurajo aus die goldene Straße entlanggegangen war. Hyänen begannen, sie zu umkreisen, und Stormhide lizards versperrten ihr den Rückweg. Nun drängen sich Hecklefang Stalkers und Stormhide lizards in der Gegend und hindern sie daran, nach Hause zu gehen. Sie braucht einen sicheren Weg vom Baum hinunter."}},faq={{q="Warum sitzt Sulhasa auf einem Baum?",a="Sulhasa kletterte auf einen Baum, als Hyänen sie umkreisten und Stormhide lizards ihr den Rückweg nach Camp Taurajo versperrten.",al={"sulhasa auf einem baum","warum sitzt sie fest","frau auf einem baum"}},{q="Wer ist Sulhasa?",a="Sulhasa ist eine Reisende aus Camp Taurajo, die nahe der goldenen Straße auf einem Baum festsitzt.",al={"wer ist sulhasa","wer sitzt auf dem baum","gestrandete frau"}},{q="Was versperrt Sulhasa den Heimweg?",a="Stormhide lizards und Hecklefang Stalkers drängen sich in der Gegend um Sulhasa.",al={"was versperrt ihr den weg","stormhide und hecklefang","warum kann sie nicht gehen"}},{q="Wo war Sulhasa unterwegs?",a="Sulhasa ging von Camp Taurajo aus die goldene Straße entlang, bevor sie festsitzen blieb.",al={"sulhasas weg","weg entlang der goldenen straße","wohin war sie unterwegs"}},{q="Was braucht Sulhasa?",a="Sulhasa braucht ein freies Gebiet ohne Stormhide lizards und Hecklefang Stalkers, damit sie sicher hinunterklettern kann.",al={"sulhasa helfen","was möchte sie","das gebiet säubern"}}},fp="14,179,18.309.0,28.106.0,15.87.0,36.79.0,26.81.0,23.97.0"}
P.entries["quest:98094"] = {n="Scout Support",s="Südlich von Tarrens Mühle bringt Ihr neue Befehle von Hochexekutorin Darthalia zu Deathstalker Masoj. Die Verlassenen treiben ihren Plan voran, diese Lande unter ihre Kontrolle zu bringen.",h="Südlich von Tarrens Mühle bringt Ihr neue Befehle von Hochexekutorin Darthalia zu Deathstalker Masoj.",kw={"deathstalker masoj","dun garok","verlassene","vorgeschobene späher","hochexekutorin darthalia","nethander-siedlung","scout support","tarrens mühle","aktualisierte befehle"},sec={{t="Befehle für Masoj",b="Hochexekutorin Darthalia vertraut Euch eine Nachricht für die vorgeschobenen Späher an. Sie gibt Euch aktualisierte Befehle für Deathstalker Masoj, der auf einer Anhöhe nördlich der Nethander-Siedlung und außerhalb von Dun Garok wartet. Der Plan der Verlassenen, diese Lande unter ihre Kontrolle zu bringen, wird weiterverfolgt, und Masoj wartet auf Eure Lieferung."}},faq={{q="Wer hat mir die Befehle gegeben?",a="Hochexekutorin Darthalia hat Euch aktualisierte Befehle für Deathstalker Masoj gegeben.",al={"wer hat mich geschickt","darthalias befehle","auftraggeber"}},{q="Wer ist Deathstalker Masoj?",a="Deathstalker Masoj ist ein vorgeschobener Späher, der außerhalb von Dun Garok, nördlich der Nethander-Siedlung, stationiert ist.",al={"masoj wer","wer ist masoj","masoj"}},{q="Wo finde ich Masoj?",a="Masoj wartet südlich von Tarrens Mühle auf einer Anhöhe nördlich der Nethander-Siedlung und außerhalb von Dun Garok.",al={"masojs standort","wo ist masoj","südlich von tarrens mühle"}},{q="Was bringe ich Masoj?",a="Ihr bringt Deathstalker Masoj aktualisierte Befehle.",al={"was abliefern","befehle für masoj","das paket"}},{q="Warum überbringe ich Befehle?",a="Eure Lieferung unterstützt den Plan der Verlassenen, diese Lande unter ihre Kontrolle zu bringen.",al={"warum masoj","was ist der plan","plan der verlassenen"}}},fp="13,164,16.293.0,23.71.0,26.87.0,22.96.0,28.48.0,27.72.0"}
P.entries["quest:98095"] = {n="Valuable Vantages",s="Im Vorgebirge des Hügellands braucht Todespirscher Masoj Euch, um drei Signalmarkierungen wiederherzustellen. Fledermausreiter nutzen diese Punkte, um strategische Truppen zu ihren Absetzorten zu führen.",h="Im Vorgebirge des Hügellands braucht Todespirscher Masoj Euch, um drei Signalmarkierungen wiederherzustellen.",kw={"apothekerphiolen","fledermausreiter","todespirscher masoj","dun garok","dunholde keep","klippenkamm","vorgebirge des hügellands","signalfeuer","valuable vantages"},sec={{t="Drei Gipfel",b="Ihr bringt Apothekerphiolen zu drei hoch gelegenen Orten: den Hügeln neben Dun Garok, dem Plateau über Dunholde Keep und dem Klippenkamm über Hillsbrad. Ihre Dämpfe locken Fledermäuse zu den Markierungen zurück. Dann kann Masojs Oberkommando seine Truppen durch das Vorgebirge führen."},{t="Masojs Befehle",b="Masoj bittet Euch, nach zerdrückten, leeren Phiolen zu suchen und die Markierungen an allen drei Orten zu erneuern. Er sagt, diese Arbeit diene Plänen, die unter dem Banner der Todespirscher vorangetrieben werden."}},faq={{q="Wer bittet mich, die Phiolen zu platzieren?",a="Todespirscher Masoj bittet Euch, die Signalmarkierungen im Vorgebirge des Hügellands wiederherzustellen.",al={"wer vergab valuable vantages","masoj phiolen","wer ist masoj"}},{q="Warum werden die Signalmarkierungen gebraucht?",a="Fledermausreiter nutzen die Signalpunkte, um strategische Truppen zu Absetzorten zu führen.",al={"warum brauchen fledermäuse markierungen","fledermaussignale","wozu dienen die signalfeuer"}},{q="Wo platziere ich die Phiolen?",a="Platziert die Phiolen auf den Hügeln neben Dun Garok, dem Plateau über Dunholde Keep und dem Klippenkamm über Hillsbrad.",al={"phiolenstandorte","wo sind die gipfel","drei phiolenstellen"}},{q="Was bewirken die Dämpfe der Phiolen?",a="Die Dämpfe locken Fledermäuse zu den gewünschten Absetzorten zurück.",al={"was bewirken phiolen","fledermausduft","zweck der phiolen"}}},fp="17,169,11.261.0,14.164.0,36.86.0,35.80.0,27.119.0,27.57.0"}
P.entries["quest:981"] = {n="Der Turm von Althalaxx",s="Im Schatten des Turms wurde der Cult of the Dark Strand zerschlagen. Die Siegesnachricht gelangt nach Süden zu Delgren dem Läuterer im Eschental und beendet den Feldzug gegen den Kult in der Dunkelküste.",h="Im Schatten des Turms wurde der Cult of the Dark Strand zerschlagen.",kw={"althalaxx","eschental","balthule","kult","dark strand","dunkelküste","delgren","maestras posten"},ang={["class:Paladin"]="Als Paladin hat der Bericht an Delgren den Läuterer für Euch eine besondere Bedeutung. Ihr teilt seine heilige Mission, die Welt von dämonischer Verderbnis und finsteren Kulten zu reinigen.",["faction:Alliance"]="Die Niederlage des Kults sichert die Überlandstraße zwischen der Dunkelküste und dem Eschental. Kundschafter der Allianz und Reisende können sie ohne Furcht vor dämonischen Hinterhalten passieren.",["race:NightElf"]="Als Nachtelf seht Ihr, wie die Säuberung des Turms von Althalaxx einen üblen Makel von den uralten Ruinen der Highborne tilgt, die Eure heiligen Küstenwälder durchziehen."},sec={{t="Eine Bedrohung gebannt",b="Wochenlang hielt der Cult of the Dark Strand den Turm von Althalaxx im Norden der Dunkelküste besetzt. Seine Bewegungen zu verfolgen, Informationen zu sammeln und ihn in heftigen Scharmützeln zu bekämpfen, machte seine Arbeit zunichte. Die Zauberer des Kults sind erschlagen, und seine dunklen Rituale sind gebrochen. Die unmittelbare Gefahr einer dämonischen Unterwanderung der Dunkelküste ist vorüber."},{t="Bericht an Maestras Posten",b="Nach dem Tod des Kultführers schickt Balthule Schattenhieb Euch nach Süden zu Maestras Posten unter dem Blätterdach des Eschentals. Delgren der Läuterer wartet dort. Als ergebener Krieger des Heiligen Lichts leitete er den Kampf gegen die finsteren Besatzer des Turms. Euer Bericht vom Zusammenbruch des Kults beruhigt die Verteidiger der Region. Delgren gewährt Euch seinen bleibenden Segen und seine Dankbarkeit."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr reist aus der Nähe des Turms von Althalaxx zu Maestras Posten im Eschental und berichtet Delgren dem Läuterer von Eurem Sieg. Euer Bericht beendet den langen Feldzug gegen den Kult im Turm.",al={"turm von althalaxx ziel","turm von althalaxx abgeben","wo quest 981 abgeben"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Streiter der Allianz, der an Maestras Posten im nördlichen Eschental stationiert ist. Er wirkt mit dem Heiligen Licht und widmet sich im gesamten nördlichen Kalimdor der Läuterung von Verderbnis und dem Kampf gegen dämonische Bedrohungen wie den Cult of the Dark Strand.",al={"wer ist delgren","delgren hintergrundgeschichte","delgren der läuterer"}},{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist ein Agent der Allianz nahe dem Turm von Althalaxx in der Dunkelküste. Er arbeitet mit Delgren zusammen, beobachtet die Bewegungen des Kults und leitet Abenteurer an, während sie den Geheimbund von innen zerschlagen.",al={"balthule","balthule hintergrundgeschichte","wer ist balthule schattenhieb"}},{q="Was tat der Cult of the Dark Strand im Turm?",a="Der Cult of the Dark Strand besetzte die uralten Ruinen des Turms von Althalaxx, um dunkle Rituale durchzuführen, dämonische Wesen zu beschwören und seinen Einfluss über die Küstengebiete der Dunkelküste auszudehnen.",al={"cult of the dark strand","was geschah bei althalaxx","turm von althalaxx hintergrundgeschichte"}},{q="Wo liegt Maestras Posten?",a="Maestras Posten ist ein Außenposten der Allianz im nordwestlichen Eschental, an der Hauptstraße unmittelbar südlich des Grenzübergangs zur Dunkelküste.",al={"maestras posten standort","wo ist maestras posten","delgren standort"}},{q="Ist der Cult of the Dark Strand vollständig vernichtet?",a="Die Führung des Kults am Turm von Althalaxx wurde hingerichtet, und sein zentrales Ritual ist gebrochen. Versprengte Kultisten und Überreste suchen noch immer abgelegene Winkel Kalimdors heim, doch die organisierte Bedrohung durch den Kult in der Dunkelküste wurde zerschlagen.",al={"ist der kult verschwunden","dark strand vernichtet","haben wir den kult getötet"}}},fx={b456cfd7={q="Warum will Balthule Schattenhieb, dass dies erledigt wird?",a="Da der Kult von Dark Strand zerschlagen und seine Führung gebrochen ist, möchte Balthule, dass Ihr die Nachricht vom Sieg zurück zu Delgren der Läuterer tragt. Delgren initiierte den Feldzug gegen die Kultisten, die im Turm lauerten, und Balthule glaubt, dass Eure Bemühungen angemessene Anerkennung und die versprochene Belohnung des Paladins verdienen.",al={"warum schickt ihr mich zurück zu delgren","balthules beweggrund","warum delgren berichten"}}},fp="22,192,16.329.0,24.372.0,31.186.0,28.248.0,29.205.0,56.189.0,32.129.0,52.239.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="In Tausend Nadeln hofft Kristy Grant, ihren Schwestern in Sturmwind Pesterhidebälge zu schicken. Sie können die Bälge zu Kleidung und Waren verarbeiten, während Kristy sich beim Sammeln auf Reisende verlässt.",h="In Tausend Nadeln hofft Kristy Grant, ihren Schwestern in Sturmwind Pesterhidebälge zu schicken.",kw={"fell","jagd","hyäne","kristy grant","bälge","pesterhide","sturmwind","tausend nadeln"},ang={["faction:Alliance"]="Kristys Bemühungen, ihre Handwerkerfamilie in Sturmwind zu versorgen, zeigen, wie Untertanen der Allianz auf der Suche nach seltenen Materialien tief nach Kalimdor vordringen.",["profession:Tailoring"]="Handwerker, die Stoffe und Zierpelze verarbeiten, können den Plan von Kristys Schwestern würdigen, Bälge wilder Tiere aus Kalimdor zu feiner Kleidung zu verarbeiten.",["race:Human"]="Kristy Grant zeigt den Unternehmergeist der Menschen von Sturmwind, die das Meer überqueren und dabei enge Bande zu ihren Verwandten in der Heimat bewahren."},sec={{t="Ein schwesterlicher Wunsch",b="Als Kristy Grant den Schluchtgrund von Tausend Nadeln durchquert, fallen ihr die Pesterhidehyänen ins Auge. Ihre Bälge sind in den Östlichen Königreichen kaum bekannt, und sie hofft, einige nach Hause zu ihren Schwestern in Sturmwind zu schicken. Geschickte Hände in ihrer Familie können die Bälge zu feiner Kleidung und Waren verarbeiten."},{t="Jäger der Salzebenen und Schluchten",b="Kristy Grant versteht sich auf Handwerk und Handel, hat aber keine Kampferfahrung. Pesterhidehyänen durchstreifen in bösartigen Rudeln das Land unterhalb der Tafelberge, weshalb es gefährlich ist, ihre Bälge allein zu sammeln. Sie verlässt sich auf erfahrene Reisende, die ihr fünf unversehrte Bälge bringen, damit ihre Schwestern daheim sie verarbeiten können."}},faq={{q="Wer ist Kristy Grant?",a="Kristy Grant ist eine Reisende aus Sturmwind, die Kalimdor durchquert. Sie hat keine Kampferfahrung, aber einen scharfen Blick für wertvolle Materialien und bittet fähige Reisende, Waren wie Hyänenbälge für sie zu sammeln.",al={"kristy grant hintergrund","wer vergibt pristine pesterhide pelts","wer ist kristy grant"}},{q="Was sind Pesterhidehyänen?",a="Pesterhidehyänen sind wilde Raubtiere, die in Tausend Nadeln heimisch sind. Sie jagen und suchen in Rudeln auf dem Schluchtgrund und in den staubigen Weiten nach Aas, und ihr auffälliges Fell zieht Reisende an, die Bälge und Pelze verarbeiten.",al={"pesterhidehyäne","hyänen in tausend nadeln","was sind pesterhidehyänen"}},{q="Warum will Kristy Grant die Bälge?",a="Kristy Grant möchte makellose Bälge von Pesterhidehyänen über das Meer zu ihren Schwestern in Sturmwind schicken. Sie bewundert ihre Farbe und vertraut darauf, dass ihre Schwestern die Pelze zu feinen Waren verarbeiten.",al={"warum pesterhidebälge sammeln","zweck der pesterhidebälge","was macht kristy mit den bälgen"}},{q="Wohin gelangen die Bälge?",a="Die Bälge sind für Sturmwind in den Östlichen Königreichen bestimmt. Kristy plant, sie über das große Meer zu ihren Schwestern zu schicken, die Materialien verarbeiten können, die in Elwynn oder im Rotkammgebirge selten vorkommen.",al={"wohin werden die bälge geschickt","bälge sturmwind","wer bekommt die hyänenbälge"}},{q="Warum kann Kristy die Hyänen nicht selbst jagen?",a="Kristy Grant hat keine Kampferfahrung, und die wilden Tiere von Tausend Nadeln sind gefährlich. Sie verlässt sich auf geschickte Reisende, um die Hyänen zu jagen, statt inmitten ihrer Rudel Verletzungen oder den Tod zu riskieren.",al={"warum kann kristy nicht kämpfen","kristy grant kampf","warum braucht kristy hilfe"}},{q="Was macht diese Bälge makellos?",a="Die Bälge müssen unversehrt sein, damit Kristys Schwestern ihre Farbe und Beschaffenheit für feine Kleidung nutzen können. Eine sorgfältige Jagd bewahrt die besten Bälge.",al={"makellose bälge bedeutung","warum makellose bälge","makellose pesterhidebälge qualität"}}},fp="25,191,19.290.0,37.280.0,20.213.0,27.221.0,37.183.0,26.185.0,41.198.0,32.139.0"}
P.entries["quest:98156"] = {n="Packaged Pristine Pelts",s="Eine Reisende bittet Euch, makellose Felle zu ihren Schwestern nach Sturmwind zu bringen. Die Lieferung kann sie erreichen, bevor sie selbst nach Hause zurückkehrt.",h="Eine Reisende bittet Euch, makellose Felle zu ihren Schwestern nach Sturmwind zu bringen.",kw={"kelly","kimberly grant","paket","park","makellose felle","schwestern","sturmwind"},sec={{t="Eine Lieferung für die Familie",b="Das Paket mit makellosen Fellen ist für Kimberly Grant bestimmt. Sie kann einige Zeit lang nicht nach Hause zurückkehren und erwartet, dass Ihr zuerst Sturmwind erreicht. Ihre Schwestern Kelly und Kimberly findet Ihr normalerweise im Park."}},faq={{q="Wer möchte, dass die Felle geliefert werden?",a="Eine Reisende bittet Euch, die makellosen Felle ihren Schwestern Kelly und Kimberly zu bringen.",al={"wer gab mir felle","geber der felllieferung"}},{q="Wer soll das Paket erhalten?",a="Das Paket soll Kimberly Grant in Sturmwind übergeben werden.",al={"für wen sind die felle","lieferung an kimberly"}},{q="Wo kann ich die Schwestern finden?",a="Kelly und Kimberly sind gewöhnlich im Park von Sturmwind zu finden.",al={"aufenthaltsort von kelly und kimberly","schwestern in sturmwind"}},{q="Warum trage ich die Felle?",a="Die Reisende kann einige Zeit lang nicht nach Sturmwind zurückkehren und bittet Euch, die Felle zu ihren Schwestern zu bringen.",al={"warum felle liefern","grund für das fellpaket"}}},fp="23,128,17.203.0,30.85.0,31.62.0,29.65.0,28.101.0"}
P.entries["quest:98189"] = {n="Return the Statuette",s="Eine Tragödie unterbrach die Lieferung einer Statuette zum Hafen von Menethil. Ihr sollt sie Hauptmann Starkfaust auf Burg Menethil bringen.",h="Eine Tragödie unterbrach die Lieferung einer Statuette zum Hafen von Menethil.",kw={"blind princess","hauptmann starkfaust","hafen von menethil","burg menethil","statuette von menethil","statuette"},sec={{t="Eine unvollendete Lieferung",b="Die Statuette war für den Hafen von Menethil bestimmt, wo Hauptmann Starkfaust auf Burg Menethil ihren Empfang bestätigen sollte. Nun sollt Ihr die Lieferung abschließen."}},faq={{q="Wer soll die Statuette erhalten?",a="Hauptmann Starkfaust auf Burg Menethil soll den Empfang der Statuette von Menethil bestätigen.",al={"wer bekommt die statuette","empfänger der statuette","hauptmann starkfaust lieferung"}},{q="Wohin sollte die Statuette gebracht werden?",a="Die Statuette sollte zum Hafen von Menethil geliefert werden.",al={"wohin soll sie","zielort der statuette","statuette von menethil"}},{q="Wer hatte sie zuvor bei sich?",a="The Blind Princess sollte die Statuette liefern, bevor sich die Tragödie ereignete.",al={"wer hatte die statuette","blind princess statuette","lieferung der statuette"}},{q="Was wird von mir verlangt?",a="Ihr sollt die Statuette von Menethil zu Hauptmann Starkfaust auf Burg Menethil bringen.",al={"was soll ich tun","statuette zurückbringen","statuettenquest"}}},fp="20,134,22.156.0,38.82.0,39.59.0,27.79.0,26.84.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="Im Hafen von Menethil fürchtet die Führung, dass ihre Relikte in feindliche Hände fallen. Sie schickt die Statuette von Menethil zur sicheren Verwahrung zu Hochlord Bolvar Fordragon in Burg Sturmwind.",h="Im Hafen von Menethil fürchtet die Führung, dass ihre Relikte in feindliche Hände fallen.",kw={"bolvar","dragonmaw","fordragon","hafen","menethil","statuette","sturmwind","terenas","sumpfland"},ang={["class:Paladin"]="Als Paladin mag Euch der Name Menethil an den Schirmherrn erinnern, der die Gründung der Ritter der Silbernen Hand unterstützte. Das Relikt zu schützen, ist für einen heiligen Krieger eine ernste Pflicht.",["faction:Alliance"]="Als Mitglied der Allianz ehrt Ihr mit der Übergabe des Relikts die historische nördliche Allianz und bewahrt ihr Symbol vor den Dragonmaw.",["race:Human"]="Als Mensch bewahrt Ihr mit dem Schutz eines Erbstücks der Menethil-Dynastie das stolze, tragische Andenken Lordaerons. Damit bekräftigt Ihr Sturmwinds Pflicht als letztes großes Menschenkönigreich."},sec={{t="Ein gefährdeter Hafen",b="Der Hafen von Menethil verbindet den Norden der Östlichen Königreiche mit dem Süden. Er trägt den Namen des verstorbenen Königs Terenas Menethil II. von Lordaeron. Doch tückische Sümpfe und Feinde umgeben den Hafen. Angesichts wachsender Gefahr fürchtet seine Führung, dass der Außenposten die Relikte des gefallenen nördlichen Königreichs nicht schützen kann."},{t="Die Bedrohung durch Dragonmaw",b="Orcs des Dragonmaw-Klans suchen noch immer das Sumpfland heim. Ihr Klan hat eine finstere Vergangenheit und verschafft sich mit Vorliebe skrupellos Vorteile. Die Verteidiger des Hafens fürchten, dass die Orcs die Statuette von Menethil für ihre Eroberungen an sich reißen werden. Sie könnten sie entweihen oder für ihre eigenen Zwecke nutzen."},{t="Direkt zum Hochlord",b="Der Kurier bringt das Relikt direkt nach Burg Sturmwind und umgeht dabei die üblichen militärischen und bürokratischen Wege. Dort nimmt Hochlord Bolvar Fordragon es als Regent des jungen Königs Anduin Wrynn entgegen. Man vertraut darauf, dass die Führung der Hauptstadt ein Stück von Lordaerons Erbe bewahrt."}},faq={{q="Was ist die Statuette von Menethil?",a="Die Statuette von Menethil ist ein wertvolles Erbstück, das mit Lordaerons Königshaus und König Terenas Menethil II. verbunden ist. Ihre Geschichte verbindet das nördliche Königreich mit der Allianz und macht sie zum Ziel von Plünderern und Feinden.",al={"menethil relikt","was ist die statuette","geschichte der statuette"}},{q="Warum kann die Statuette nicht im Hafen von Menethil bleiben?",a="Der Hafen von Menethil liegt abgeschieden inmitten feindseliger Sümpfe, dark iron dwarves, Murlocs und Orcs. Seine Garnison fürchtet, dass die Siedlung ein so bedeutsames Relikt nicht schützen kann.",al={"warum die statuette verlegen","ist der hafen von menethil unsicher"}},{q="Wer sind die Dragonmaw und warum wollen sie die Statuette?",a="Die Dragonmaw sind Orcs, die sich im Sumpfland verschanzt haben. Die Hafenbeamten fürchten, sie würden selbst unter Verlusten ihrer Krieger ehrwürdige Relikte der Allianz plündern und diese dann entweihen oder missbrauchen.",al={"bedrohung durch dragonmaw","warum wollen orcs die statuette"}},{q="Warum wird das Relikt direkt zu Bolvar Fordragon gebracht?",a="Hochlord Bolvar Fordragon ist Sturmwinds Regent und Beschützer des jungen Königs Anduin. Ihm das Relikt direkt zu übergeben, umgeht Verzögerungen durch die Verwaltung und legt es in die stärksten Hände der Hauptstadt.",al={"warum bolvar","warum die befehlskette umgehen"}},{q="Wo befindet sich Hochlord Bolvar Fordragon?",a="Hochlord Bolvar Fordragon befindet sich im Thronsaal von Burg Sturmwind, an der Seite des Kindkönigs Anduin Wrynn.",al={"bolvars aufenthaltsort","wo ist bolvar"}},{q="Was verbindet den Hafen von Menethil mit König Terenas?",a="Der Hafen von Menethil ehrt König Terenas Menethil II., der Lordaeron führte und die Alliance of Lordaeron während des Zweiten Krieges unterstützte. Er starb während des Dritten Krieges.",al={"warum heißt er hafen von menethil","verbindung zu terenas menethil"}}},fx={ece51c60={q="Warum seid Ihr auserwählt, die Statuette von Menethil nach Sturmwind zu tragen?",a="Der Hafen von Menethil ist isoliert und wird ständig von feindlichen Kräften im Sumpfland bedroht, wodurch seine Garnison bei der Verteidigung des Hafens überlastet ist. Ihr habt Eure Fähigkeiten und Vertrauenswürdigkeit bereits bewiesen, indem Ihr das Erbstück geborgen habt. Einen fähigen, unabhängigen Reisenden damit zu beauftragen vermeidet es, die lokale Verteidigung der Stadt zu schwächen, und hält die Mission diskret, während Ihr Euch durch gefährliches Gebiet bewegt.",al={"warum schickt ihr mich","warum keine wachen schicken","warum statuette überbringen"}}},fp="22,170,19.295.0,20.229.0,24.269.0,31.211.0,48.159.0,46.187.0,51.190.0,43.100.0,49.159.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="Hochlord Bolvar Fordragon schickt ein seltenes Bildnis von König Terenas zur Kathedrale des Lichts. Lord Grayson Schattenbruch wird die Statuette von Menethil sicher verwahren.",h="Hochlord Bolvar Fordragon schickt ein seltenes Bildnis von König Terenas zur Kathedrale des Lichts.",kw={"bolvar","kathedrale","lordaeron","menethil","schattenbruch","statuette","sturmwind","terenas"},ang={["class:Paladin"]="Als Paladin bewahrt Ihr eine Reliquie von König Terenas, die vom Licht berührt ist. Sie ehrt den Herrscher, der einst die Gründung der Ritter der Silbernen Hand genehmigte.",["class:Priest"]="Als Priester könnt Ihr erkennen, wie sich heilige Macht in einem schlichten geschnitzten Bildnis gesammelt hat. Es zeugt von Lordaerons Erbe des Glaubens, selbst nach der Zerstörung der Ländereien des Königreichs.",["faction:Alliance"]="Als Mitglied der Allianz erinnert Ihr Euch an König Terenas Menethil II. als eine tragende Säule bei der Gründung der Alliance of Lordaeron. Jedes mit ihm verbundene Artefakt ist ein geschätztes Zeichen der Einheit und des Gedenkens."},sec={{t="Ein seltenes Andenken",b="König Terenas Menethil II. half während des Zweiten Krieges, die Große Allianz zu formen. Er lebte in tiefer persönlicher Frömmigkeit und genoss zugleich hohes Ansehen unter den Königreichen der Menschheit. Von Natur aus bescheiden, mochte er keine Denkmäler zu seinen Ehren. Nur wenige Bildnisse wurden in Auftrag gegeben, und noch weniger überstanden Lordaerons Untergang und die Verwüstung durch die Geißel."},{t="Von Gnade berührt",b="Hochlord Bolvar Fordragon sieht in der erhaltenen Statuette von Menethil mehr als kunstvolle Schnitzarbeit. Das Heilige Licht hat begonnen, sich in ihr zu sammeln, und verleiht der Figur eine stille spirituelle Präsenz. Bolvar beschließt, dass Burg Sturmwind kein Ort für ein so heiliges Stück ist. Er schickt es quer durch die Stadt zur Kathedrale des Lichts, in die Obhut von Lord Grayson Schattenbruch, der Paladine ausbildet."}},faq={{q="Wer war König Terenas Menethil II.?",a="König Terenas Menethil II. herrschte über das Kingdom of Lordaeron, wo sein Volk ihn liebte. Während des Zweiten Krieges vereinte er die Menschenkönigreiche mit den Zwergen, Gnomen und Hochelfen zur Großen Allianz. Gemeinsam besiegten sie die Orcish Horde. Terenas wurde erschlagen, als sein Reich fiel.",al={"terenas menethil","wer ist terenas","könig von lordaeron"}},{q="Warum sind Statuen von König Terenas so selten?",a="König Terenas war bescheiden und mochte keine prunkvollen Denkmäler zu seinen Ehren. Nur wenige Bildnisse wurden geschaffen, und fast keines überstand die Zerstörung Lordaerons durch die Geißel.",al={"warum gibt es wenige statuen","seltenheit der terenas-statuette","warum so wenige denkmäler"}},{q="Warum erstrahlt die Statuette von Menethil im Licht?",a="Bolvar bemerkt, dass sich das Licht in der Statuette gesammelt hat. Er nennt Terenas einen guten und frommen Mann, erklärt aber nicht, warum dieses Bildnis heilige Macht in sich trägt.",al={"warum trägt die statuette licht","heilige statuette","sich sammelndes licht"}},{q="Wer ist Lord Grayson Schattenbruch?",a="Lord Grayson Schattenbruch ist ein erfahrener menschlicher Paladin der Ritter der Silbernen Hand und ein Meister an der Kathedrale des Lichts. Er ist auf dem Kathedralenplatz stationiert, wo er angehende Paladine ausbildet und sich um die heiligen Angelegenheiten der Gläubigen Sturmwinds kümmert.",al={"wer ist schattenbruch","lord graysons rolle"}},{q="Warum schickt Hochlord Bolvar die Statuette zur Kathedrale?",a="Bolvar ehrt Terenas als Vater der Allianz und glaubt, dass die Statuette in die Kathedrale des Lichts gehört. Da sich heilige Macht in ihr gesammelt hat, vertraut er sie den heiligen Orden an, statt sie unter den Hofbeamten in Burg Sturmwind aufzubewahren.",al={"warum zur kathedrale schicken","warum nicht in burg sturmwind behalten"}},{q="Wo liegt die Kathedrale des Lichts?",a="Die Kathedrale des Lichts beherrscht den Kathedralenplatz im Herzen von Sturmwind, zwischen dem Zwergendistrikt, dem Handelsdistrikt und dem Magierviertel. Sie ist das wichtigste Heiligtum und das Zentrum der Verehrung für die Church of the Holy Light in den südlichen Königreichen.",al={"wo ist die kathedrale des lichts","lage des kathedralenplatzes"}}},fp="22,156,18.328.0,16.369.0,33.285.0,40.164.0,53.156.0,34.250.0,61.248.0,40.251.0"}
P.entries["quest:98197"] = {n="Spoils of War",s="Während die Drachenschinder vorrücken, sucht Valstag Eisenkiefer Holz und Eisen aus dem Hafen von Menethil. Er braucht sie, um die Verteidigung der Stadt zu stärken.",h="Während die Drachenschinder vorrücken, sucht Valstag Eisenkiefer Holz und Eisen aus dem Hafen von Menethil.",kw={"drachenschinder","eisen aus khaz modan","holz aus khaz modan","hafen von menethil","alte horde","spoils of war","verteidigung der stadt","valstag eisenkiefer"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr, die Verteidigung der Stadt gegen die Drachenschinder zu stärken.",["race:Dwarf"]="Als Zwerg wisst Ihr vielleicht, dass die Alte Horde ihre Flotte hier mit Ressourcen baute, die aus Khaz Modan gestohlen worden waren."},sec={{t="Vorräte im Hafen",b="Der Hafen von Menethil diente der Alten Horde einst als Aufmarschgebiet für eine Invasion von Hillsbrad. Die dort gebaute Flotte nutzte Ressourcen, die aus Khaz Modan gestohlen worden waren. Einige Vorräte liegen noch im Hafen, und Valstag bittet Euch, ihm das Holz und Eisen für die Verteidigung der Stadt zu bringen."},{t="Neuer Nachschub",b="Valstag dankt Euch dafür, dass Ihr die Materialien gebracht habt. Mit ihnen muss sich die Stadt nicht allein auf Lieferungen aus Theramore oder Auberdine verlassen."}},faq={{q="Was braucht Valstag aus dem Hafen von Menethil?",a="Valstag bittet Euch, Holz und Eisen aus Khaz Modan aus dem Hafen von Menethil zu bergen.",al={"was braucht er","holz und eisen","hafenvorräte"}},{q="Warum liegen Vorräte aus Khaz Modan im Hafen?",a="Die Alte Horde baute im Hafen von Menethil eine Flotte mit Ressourcen, die aus Khaz Modan gestohlen worden waren.",al={"warum liegt dort holz","eisen aus khaz modan","vorräte der alten horde"}},{q="Wofür werden die Materialien verwendet?",a="Valstag sagt, die Materialien werden helfen, die Verteidigung der Stadt zu stärken, während die Drachenschinder vorrücken.",al={"warum vorräte sammeln","verteidigung","wofür sind sie"}},{q="Wer ist Valstag Eisenkiefer?",a="Valstag Eisenkiefer bittet Euch, Holz und Eisen aus dem Hafen von Menethil zu bergen.",al={"wer ist valstag","valstag","eisenkiefer"}},{q="Wo nutzte die Alte Horde den Hafen von Menethil?",a="Die Alte Horde nutzte den Hafen von Menethil als Aufmarschgebiet für ihre Invasion von Hillsbrad auf dem Seeweg.",al={"hafen der alten horde","geschichte menethils","invasion von hillsbrad"}},{q="Warum begrüßt Valstag diese Vorräte?",a="Dank der Materialien muss sich die Stadt nicht allein auf Lieferungen aus Theramore oder Auberdine verlassen.",al={"warum der dank","lieferungen aus theramore","vorräte aus auberdine"}}},fp="13,133,13.272.0,12.129.1,44.76.0,42.86.0,36.92.0,23.73.0,44.91.0,40.90.0"}
P.entries["quest:982"] = {n="Tiefer Ozean, weites Meer",s="Nördlich von Auberdine liegen zwei Nachtelfenschiffe unter den Wellen. Murlocs überfielen die Silver Dawning und die Nebelschleier bei der Einfahrt in den Hafen, und die überlebenden Besatzungen suchen einen Weg, um ihre verlorenen Kapitäne zu trauern.",h="Nördlich von Auberdine liegen zwei Nachtelfenschiffe unter den Wellen.",kw={"auberdine","dunkelküste","tiefer ozean, weites meer","gorbold stahlhand","schließkassette","nebelschleier","murloc","schiffswrack","silver dawning"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie die trauernde Besatzung die Zusammenarbeit von Zwergen und Nachtelfen auf See entlang der Küste Kalimdors widerspiegelt.",["race:Dwarf"]="Als Zwerg könnt Ihr Gorbold Stahlhands instinktiven Wunsch nachvollziehen, gefallene Kameraden zu ehren und Seeleute in fremden Häfen zu unterstützen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Habseligkeiten der Kapitäne für die Ehre der Ahnen von Bedeutung sind. Sie dienten dem Seehandel Auberdines."},sec={{t="Tragödie vor der Küste",b="Murlocs überwältigten die Silver Dawning und die Nebelschleier, als sie sich Auberdine näherten. Beide Schiffe sanken in den Untiefen nördlich der Siedlung. Ihre überlebenden Besatzungen erreichten das Ufer, doch der Verlust der Schiffe und ihrer Kapitäne lastet noch immer auf dem Hafen."},{t="Verlorene Erinnerungen bergen",b="Gorbold Stahlhand, ein Zwerg in Auberdine, möchte die gefallenen Nachtelfenkapitäne ehren. Murlocs besetzen nun die Unterwasserwracks, doch die Schließkassetten der Kapitäne liegen noch in den überfluteten Frachträumen. Ihre Logbücher und persönlichen Gegenstände könnten den überlebenden Seeleuten helfen, um ihre Befehlshaber zu trauern und deren Geister zur Ruhe zu betten."}},faq={{q="Wo liegen die gesunkenen Schiffe?",a="Beide Wracks liegen unter Wasser vor der Dunkelküste, nördlich der Anlegestellen von Auberdine.",al={"wo liegen die schiffswracks","lage der wracks","wo ist die silver dawning"}},{q="Was geschah mit der Silver Dawning und der Nebelschleier?",a="Murlocs überfielen die Silver Dawning und die Nebelschleier, als sie auf Auberdine zusegelten. Ihre Besatzungen wurden überrannt, beide Kapitäne starben, und die Schiffe sanken auf den Meeresgrund.",al={"wie sind die schiffe gesunken","warum sind die schiffe gesunken","was hat die nebelschleier versenkt"}},{q="Wer ist Gorbold Stahlhand?",a="Gorbold Stahlhand ist ein Zwerg in Auberdine. Er kümmert sich um die überlebenden Seeleute und bittet darum, die Habseligkeiten der gefallenen Kapitäne zu bergen.",al={"wer vergibt tiefer ozean, weites meer","geschichte von gorbold stahlhand"}},{q="Was befindet sich in den Schließkassetten?",a="Die Schließkassetten enthalten die Logbücher und persönlichen Gegenstände der gefallenen Nachtelfenkapitäne, die den Überlebenden der Schiffsunglücke viel bedeuten.",al={"was ist in den schließkassetten","inhalt der kapitänsschließkassetten"}},{q="Warum liegen den Überlebenden diese Gegenstände so am Herzen?",a="Die Kapitäne waren angesehene Seefahrer der Nachtelfen. Ihre Logbücher und Besitztümer spenden den überlebenden Besatzungen Trost und könnten helfen, die Geister der Kapitäne zur Ruhe zu betten.",al={"warum die schließkassetten bergen","warum den kapitänen helfen"}},{q="Welche Kreaturen bewohnen die Schiffswracks jetzt?",a="Murlocs haben die Wracks besetzt, betrachten die Schiffsrümpfe als Trophäen und durchstreifen die umliegenden Gewässer.",al={"was bewacht die schiffe","gegner bei den schiffswracks"}}},fp="20,205,21.245.0,24.307.0,35.71.0,54.167.0,25.141.0,29.126.0,54.150.0,42.102.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="Sylessa Duskwhisper sucht in den Gewässern südlich vom Hafen von Menethil nach Bloom of the Heavens. Die heilige Blume Nord'el ging verloren, als das Nachtelfenschiff Flying Osprey zusammen mit Schiffen der Dritten Flotte der Kul Tiraner Schiffbruch erlitt. Murlocs besetzen nun das Wrack, wo Nord'el zwischen den Trümmern liegt.",h="Sylessa Duskwhisper sucht in den Gewässern südlich vom Hafen von Menethil nach Bloom of the Heavens.",kw={"auberdine","bloom of the heavens","flying osprey","hafen von menethil","hyjal","murlocs","nord'el","sylessa duskwhisper","teldrassil","sumpfland"},ang={["faction:Alliance"]="Für die Allianz segelte die Flying Osprey an der Seite der Dritten Flotte der Kul Tiraner, bevor beide vor dem Hafen von Menethil ein Unglück ereilte.",["profession:Herbalism"]="Als Kräuterkundiger kennt Ihr Nord'el als seltene Nachtelfenblume, die bei Vollmond auf dem Gipfel des Hyjal gepflückt wird, ein bemerkenswertes botanisches Exemplar.",["race:NightElf"]="Als Nachtelf könnt Ihr Nord'el als botanisches Relikt des Hyjal schätzen, das gepflückt wurde, bevor Euer Volk seine Heimat nach Teldrassil verlegte."},sec={{t="Ein Relikt des Hyjal",b="Sylessa Duskwhisper ist aus Auberdine zum Hafen von Menethil gekommen, um Nord'el zu bergen. Die Blume wurde bei Vollmond auf dem Gipfel des Hyjal gepflückt und hat für die Nachtelfen eine tiefe Bedeutung. Jene, die nun in Teldrassil leben, schätzen Relikte ihres angestammten Berges als Erinnerungen an ihr Erbe."},{t="Das Schicksal der Flying Osprey",b="Vor vielen Monden erlitt das Nachtelfenschiff Flying Osprey an der felsigen Küste südlich vom Hafen von Menethil Schiffbruch, während es mit der Dritten Flotte der Kul Tiraner segelte. Sein zerstörter Rumpf ruht im flachen Wasser. Wilde Murlocräuber haben sich im Wrack niedergelassen und verteidigen es gegen jeden, der nach der Fracht der Nachtelfen sucht."}},faq={{q="Was ist Nord'el?",a="Auf Darnassian bedeutet Nord'el Bloom of the Heavens. Nachtelfen pflücken diese heilige Blume, nachdem sie bei Vollmond auf dem Gipfel des Hyjal erblüht ist, ihrer angestammten Bergheimat.",al={"was ist nordel","nordel blume","was ist bloom of the heavens"}},{q="Was war die Flying Osprey?",a="Die Flying Osprey war ein Nachtelfenschiff, das mit der Dritten Flotte der Kul Tiraner segelte. Vor vielen Monden erlitt es an der Küste des Sumpflands unmittelbar südlich vom Hafen von Menethil Schiffbruch, wobei seine Fracht verstreut wurde.",al={"flying osprey schiff","welches schiff erlitt schiffbruch","dritte flotte der kul tiraner sumpfland"}},{q="Wer ist Sylessa Duskwhisper?",a="Sylessa Duskwhisper ist eine Gesandte der Nachtelfen, die aus Auberdine und Teldrassil zum Hafen von Menethil segelte, um die verlorene Blume für ihr Volk zu bergen.",al={"wer ist sylessa duskwhisper","questgeber menethil","nachtelf in menethil"}},{q="Warum ist das Schiffswrack gefährlich?",a="Wilde Murlocräuber besetzen das Wrack an der Küste südlich vom Hafen von Menethil. Sie beanspruchen die Überreste der Flying Osprey für sich und machen die Bergung für Sylessa gefährlich.",al={"warum sind murlocs beim wrack","wer bewacht das wrack","wrackteile südlich von menethil"}},{q="Warum ist Nord'el den Nachtelfen so wichtig?",a="Nachtelfen pflückten Nord'el auf dem Gipfel des Hyjal, ihrer einstigen Heimat, bevor sie Teldrassil gründeten. Ihre heilige Ernte bei Vollmond verleiht der Blume einen hohen kulturellen und emotionalen Wert.",al={"warum ist die blume wichtig","warum will sylessa nordel"}},{q="Wo sind die Wrackteile zu finden?",a="Die Flying Osprey liegt an der felsigen Küste unmittelbar südlich vom Hafen von Menethil im Sumpfland. Feindselige Murlocs besetzen das Wrack.",al={"wo sind die wrackteile","wo ist die blume","schiffswrack fundort sumpfland"}}},fp="20,285,22.299.0,29.295.0,16.175.0,27.182.0,27.145.0,31.155.0,47.190.0,32.122.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="Nach seiner Bergung im Sumpfland ist Nord'el über das große Meer nach Auberdine unterwegs. Für die Nachtelfen, die noch immer den Verlust ihrer Unsterblichkeit betrauern, trägt die Blume Elunes Gnade in sich.",h="Nach seiner Bergung im Sumpfland ist Nord'el über das große Meer nach Auberdine unterwegs.",kw={"auberdine","bloom of the heavens","dunkelküste","darnassus","elune","hafen von menethil","nord'el","sylessa","thundris windweaver","sumpfland"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr vom Hafen von Menethil in den Östlichen Königreichen nach Auberdine und Darnassus im nördlichen Kalimdor übersetzen.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr die Bergung von Nord'el zu schätzen. Diese heilige Blume galt seit Ewigkeiten als verloren und muss in Darnassus kultiviert werden.",["race:NightElf"]="Als Nachtelf könnt Ihr Nord'el als kostbares Überbleibsel von Kalimdors heiligem Erbe betrachten. Sie ist auch ein Zeichen von Elunes Fürsorge, während sich die Kaldorei an den Verlust ihrer Unsterblichkeit gewöhnen."},sec={{t="Eine gefährliche Bergung",b="Im Sumpfland birgt Sylessa trotz eines Angriffs örtlicher Murlocs Nord'el, die legendäre Blume. Von ihrer Flucht erschöpft, vertraut sie Euch die Pflanze für ihre Reise über das große Meer nach Auberdine an. Vom Hafen von Menethil fährt ein Schiff direkt zur Dunkelküste und verbindet die Östlichen Königreiche mit dem nördlichen Kalimdor."},{t="Ein Zeichen von Elune's Grace",b="Als Nord'el Auberdine erreicht, ist der Älteste Thundris Windwirker erstaunt. Er hatte geglaubt, die heilige Blüte sei für immer verschwunden. Die Nachtelfen tragen noch immer die Folgen der Aufgabe ihrer Unsterblichkeit nach der Schlacht um den Hyjal, und Nord'els Überleben erscheint wie ein Segen Elunes. Thundris bereitet vor, die zarte Pflanze nach Darnassus zu schicken, wo sie kultiviert und für künftige Generationen bewahrt werden kann."}},faq={{q="Was ist Nord'el?",a="Nord'el ist eine heilige Blume, die die Nachtelfen lange für verloren hielten. Dass sie nach vielen Jahren noch lebt, ist ein kostbares Zeichen von Elunes Gunst und der Widerstandskraft der Natur.",al={"was ist nord'el","nordel blume","heilige blüte"}},{q="Wer vergibt die Quest Bloom of the Heavens?",a="Sylessa im Sumpfland übergibt Euch Nord'el zum Transport. Sie barg die heilige Blüte trotz eines Hinterhalts und der Verfolgung durch feindselige Murlocs, doch die Strapazen ließen sie zu erschöpft zurück, um selbst zu reisen.",al={"wer vergibt bloom of the heavens","sumpfland questgeber nordel","sylessa sumpfland"}},{q="Wohin muss Nord'el gebracht werden?",a="Bringt Nord'el über das Meer zum Ältesten Thundris Windwirker in Auberdine an der Küste der Dunkelküste. Ein Schiff fährt direkt vom Hafen von Menethil nach Auberdine.",al={"wohin nord'el bringen","thundris windweaver standort","auberdine ablieferung"}},{q="Warum ist Nord'el für die Nachtelfen so bedeutsam?",a="Der Älteste Thundris Windwirker sieht Nord'els Überleben als ein Leuchtfeuer der Hoffnung. Die heilige Blume erinnert an Elunes Gnade und das Durchhaltevermögen der Kaldorei, nachdem sie im Dritten Krieg ihre Unsterblichkeit opferten.",al={"warum ist nord'el für nachtelfen wichtig","nordel hintergrundgeschichte","unsterblichkeit nachtelfen nordel"}},{q="Was geschieht mit der Blume, nachdem sie Auberdine erreicht hat?",a="Nachdem Nord'el Auberdine erreicht hat, veranlasst Thundris Windwirker, dass die Blume ins Landesinnere nach Darnassus gebracht wird. Dort können Botaniker und Priester der Nachtelfen sie pflegen und kultivieren.",al={"was geschieht als nächstes mit nord'el","nord'el darnassus","wohin schickt thundris nord'el"}},{q="Wie reist Ihr vom Hafen von Menethil nach Auberdine?",a="Nehmt das Schiff vom Hafen von Menethil im Sumpfland über das große Meer nach Auberdine an der Dunkelküste.",al={"wie vom sumpfland nach auberdine gelangen","menethil schiff nach auberdine","schiff zur dunkelküste"}}},fp="20,189,20.315.0,23.403.0,16.153.0,41.199.0,40.155.0,49.201.0,56.170.0,52.98.0"}
P.entries["quest:98219"] = {n="The Shamed Lieutenant",s="Ein Sturmwinder Wachmann bittet Euch, nach Leutnant Farren Orinelle in Süderstade zu sehen. Seine Versetzung soll ihm eine Lektion erteilen, doch der Wachmann hofft, dass er sich noch bewähren kann.",h="Ein Sturmwinder Wachmann bittet Euch, nach Leutnant Farren Orinelle in Süderstade zu sehen.",kw={"farren orinelle","vorgebirge des hügellands","leutnant farren","hafen von menethil","süderstade","sturmwinder wachmann","the shamed lieutenant"},ang={["faction:Alliance"]="Als Reisender der Allianz werdet Ihr gebeten, nach einem Sturmwinder Stadtwächter zu sehen, der in Süderstade dient."},sec={{t="Nach dem Rechten sehen",b="Ihr habt die Statuette sicher überbracht. Nun bittet Euch Euer Kontakt, mit Leutnant Farren Orinelle zu sprechen, einem Stadtwächter, der nach Süderstade im Vorgebirge des Hügellands versetzt wurde. Farrens Vater war ein Freund des Wachmanns, der glaubt, Farren könnte Hilfe gebrauchen. Falls Ihr dort vorbeikommt, fährt vom Hafen von Menethil ein Schiff nach Süderstade."}},faq={{q="Mit wem soll ich sprechen?",a="Ihr sollt mit Leutnant Farren Orinelle sprechen, einem Stadtwächter, der nach Süderstade versetzt wurde.",al={"wer ist farren","leutnant farren","farren orinelle"}},{q="Wo ist Leutnant Farren?",a="Leutnant Farren Orinelle ist in Süderstade im Vorgebirge des Hügellands.",al={"wo ist farren","farrens aufenthaltsort","leutnant in süderstade"}},{q="Warum wurde Farren versetzt?",a="Der Wachmann sagt, Farren könne die Lektion gebrauchen, nennt aber keinen weiteren Grund für seine Versetzung.",al={"warum versetzt","farrens strafe","warum ist er in süderstade"}},{q="Woher kennt der Wachmann Farren?",a="Farrens Vater war ein Freund des Wachmanns, der Euch bittet, nach ihm zu sehen.",al={"farrens vater","wer war sein vater","verbindung zum wachmann"}},{q="Wie komme ich nach Süderstade?",a="Ein Schiff vom Hafen von Menethil kann Euch nach Süderstade bringen.",al={"schiff nach süderstade","route von menethil","wie dorthin gelangen"}},{q="Hat schon jemand nach Farren gesehen?",a="Farren sagt, im Vormonat sei ein anderer Sturmwinder Wachmann gekommen, um nach ihm zu sehen.",al={"letzter monat","andere besucher","wer sieht nach farren"}}},fp="21,171,10.331.0,35.94.0,27.68.0,26.93.0,31.71.0,28.55.0,36.76.0"}
P.entries["quest:98221"] = {n="From the Ashes",s="Hauptmann Starkfaust bittet Euch, die erneuten Aktivitäten der Dragonmaw nahe Burg Menethil zu untersuchen. Die Angriffspläne könnten zeigen, wo der Klan zuschlagen will.",h="Hauptmann Starkfaust bittet Euch, die erneuten Aktivitäten der Dragonmaw nahe Burg Menethil zu untersuchen.",kw={"lager der grollhauer","angriffspläne","hauptmann starkfaust","dragonmaw","dun algaz","aus der asche","eisenschmiede","nek'rosh","rote drachen"},ang={["faction:Alliance"]="Als Reisende der Allianz helft Ihr Hauptmann Starkfaust herauszufinden, wo die Dragonmaw zuschlagen wollen.",["race:Dwarf"]="Als Zwerg helft Ihr Hauptmann Starkfaust herauszufinden, wo die Dragonmaw zuschlagen wollen, und seine Sorge reicht bis nach Eisenschmiede."},sec={{t="Pläne im Sumpfland",b="Hauptmann Starkfaust bei Burg Menethil muss wissen, wo der Dragonmaw-Klan zuschlagen wird. Während des Zweiten Kriegs bauten sie hier eine Flotte, um Hillsbrad anzugreifen, doch rote Drachen schlugen sie in die Flucht und trieben die Überlebenden in die Berge. Nun haben die Aktivitäten im Lager der Grollhauer, nordöstlich von Menethil, stark zugenommen. Ihr sollt die Angriffspläne des Klans finden und vernichten."},{t="Ein neuer Schachzug",b="Die Pläne reichen über Dun Algaz hinaus und zielen auch auf Eisenschmiede. Nek'rosh teilt den Ehrgeiz seines Vaters, doch ihm fehlen die versklavten roten Drachen, die Dragonmaw im Zweiten Krieg so gefährlich machten. Hauptmann Starkfaust erkennt in diesem Schachzug die Bedrohung für Eisenschmiede und erwartet, dass Nek'rosh teuer dafür bezahlen wird."}},faq={{q="Wer bittet mich, die Angriffspläne zu finden?",a="Hauptmann Starkfaust bei Burg Menethil bittet Euch, die Angriffspläne des Dragonmaw zu finden und zu vernichten.",al={"wer hat mich geschickt","starkfausts pläne","auftrag des hauptmanns"}},{q="Wo sind die Dragonmaw aktiv?",a="Die Dragonmaw sind im Lager der Grollhauer, nordöstlich von Menethil, aktiver geworden.",al={"lager der dragonmaw","wo sind sie","aktivitäten der grollhauer"}},{q="Warum will Starkfaust die Pläne?",a="Starkfaust will erfahren, wo die Dragonmaw als Nächstes zuschlagen werden.",al={"warum die pläne","was braucht er","wo schlagen sie zu"}},{q="Was geschah mit den Dragonmaw im Zweiten Krieg?",a="Die Dragonmaw bauten hier eine Flotte, um Hillsbrad anzugreifen, doch rote Drachen schlugen sie in die Flucht und ließen Überlebende tief in den Bergen zurück.",al={"geschichte der dragonmaw","rote drachen im krieg","was geschah zuvor"}}},fp="14,143,21.356.0,12.297.1,37.91.0,31.85.0,34.62.0,49.123.0"}
P.entries["quest:98223"] = {n="Old Habits",s="Ein verbranntes Buch der Dragonmaw erreicht Hauptmann Starkfaust im Hafen von Menethil. Seine beschädigten Seiten erwähnen Rituale zur Bindung von Drachen und den Shadow Council.",h="Ein verbranntes Buch der Dragonmaw erreicht Hauptmann Starkfaust im Hafen von Menethil.",kw={"hauptmann starkfaust","demon soul","dragonmaw-clan","hafen von menethil","nek'rosh","old habits","shadow council","zerfleddertes zauberbuch"},sec={{t="Ein beschädigtes Buch",b="Ihr bringt Hauptmann Starkfaust im Hafen von Menethil ein stark verbranntes Buch, das womöglich das Drachenfeuer überstanden hat, das den Dragonmaw-Clan verheerte. Seine wenigen lesbaren Seiten beschreiben Rituale mit der Demon Soul, mit der der Clan Drachen beherrschte. Das Buch ist unvollständig, doch Nek’rosh scheint versucht zu haben, es mit Seiten aus Tierhaut und frischer Tinte zu retten, die den Shadow Council nennt."},{t="Starkfausts Antwort",b="Hauptmann Starkfaust sagt, das Buch müsse vernichtet werden, denn er will nicht riskieren, dass die Orcs es nutzen. Er fürchtet Drachenreiter am Hafen von Menethil, und die Erwähnung des Shadow Council beunruhigt ihn. Er plant, seinen Vorgesetzten Nachricht zu schicken."}},faq={{q="Was steht in dem zerfledderten Zauberbuch?",a="Die erhaltenen Seiten beschreiben Rituale mit der Demon Soul, mit der der Dragonmaw-Clan Drachen beherrschte. Frische Tinte nennt außerdem den Shadow Council.",al={"inhalt des zauberbuchs","welches buch","verbranntes buch"}},{q="Wer hat versucht, das Buch zu retten?",a="Nek’rosh scheint versucht zu haben, das Buch zu retten, indem er Seiten aus Tierhaut einfügte.",al={"wer hat es gerettet","nek'rosh buch","nekrosh"}},{q="Wer möchte das Buch gebracht bekommen?",a="Hauptmann Starkfaust im Hafen von Menethil möchte von dem Buch erfahren.",al={"wohin das zauberbuch bringen","starkfaust buch","was will der hauptmann"}},{q="Warum ist das Buch schwer zu lesen?",a="Das Buch ist stark verbrannt, und nur wenig davon ist noch lesbar.",al={"warum verbranntes buch","buch beschädigt","zauberbuch nicht lesbar"}}},fp="10,142,14.382.0,20.226.1,34.153.0,27.90.0,35.66.0,29.59.0"}
P.entries["quest:98230"] = {n="This Land Was Their Land",s="Howin Kindfeather ist ins Sumpfland zurückgekehrt, wo die Wildhammers einst Grim Batol gründeten. Sucht ihn östlich vom Hafen von Menethil auf; er freut sich über eine helfende Hand.",h="Howin Kindfeather ist ins Sumpfland zurückgekehrt, wo die Wildhammers einst Grim Batol gründeten.",kw={"grim batol","greifen","howin kindfeather","hafen von menethil","this land was their land","war of the three hammers","sumpfland","wildhammer"},ang={["race:Dwarf"]="Als Zwerg begegnet Ihr Howin Kindfeather, einem Wildhammer, der nach dem War of the Three Hammers ins Sumpfland zurückkehrt."},sec={{t="Der Weg nach Osten",b="Der Wildhammer-Zwerg Howin Kindfeather wartet östlich vom Hafen von Menethil an der Straße auf Hilfe. Ihr sucht ihn als einen der ersten Wildhammers auf, die seit langer Zeit zurückgekehrt sind. Er hält sich von der Stadt fern, und Hilfe ist schwer zu finden."},{t="Eine Heimat der Wildhammers",b="Nach dem War of the Three Hammers ließen sich die Wildhammers im Sumpfland nieder und gründeten Grim Batol. Einst flogen Greifen über der Bergfestung und stießen ins Sumpfland hinab, um Fische zu fangen. Dieses Leben währte nicht lange; nun ist Howin zurückgekehrt, weit entfernt von der Stadt."}},faq={{q="Wer ist Howin Kindfeather?",a="Howin Kindfeather ist ein Wildhammer-Zwerg und einer der ersten seines Volkes, die seit langer Zeit zurückgekehrt sind.",al={"howin","wer ist howin","kindfeather"}},{q="Wo kann ich Howin finden?",a="Howin befindet sich östlich vom Hafen von Menethil an der Straße, weit außerhalb der Stadt.",al={"wo ist howin","kindfeather finden","howins standort"}},{q="Warum ist Howin hier draußen?",a="Howin ist einer der ersten Wildhammers, die seit langer Zeit zurückgekehrt sind, und bleibt außerhalb der Stadt für sich.",al={"warum ist howin hier","howin zurück","wildhammer rückkehr"}},{q="Was war Grim Batol?",a="Die Wildhammers gründeten Grim Batol im Sumpfland nach dem War of the Three Hammers.",al={"grim batols geschichte","wildhammer festung","was ist grim batol"}},{q="Was geschah mit der Heimat der Wildhammers?",a="Grim Batol war einst ein wundersamer Ort, an dem Greifen über das Sumpfland flogen, um Fische zu fangen, doch dieses Leben währte nicht lange.",al={"wildhammer heimat","was geschah mit grim batol","greifen sumpfland"}}},fp="24,156,13.222.0,17.252.0,25.93.0,23.67.0,22.94.0,20.86.0,39.123.0"}
P.entries["quest:98233"] = {n="Sword in the Slime",s="Wachmann Jameson bittet Euch, sein Übungsschwert aus einem Schleim westlich der Bucht zu bergen. Er braucht es zurück, bevor sein Sergeant bemerkt, dass es fehlt.",h="Wachmann Jameson bittet Euch, sein Übungsschwert aus einem Schleim westlich der Bucht zu bergen.",kw={"wachmann jameson","jameson","schleim","sergeant","schwert im schleim","übungsschwert"},sec={{t="Ein verlorenes Schwert",b="Jamesons Schwert war schnell verloren, als er versuchte, ohne eigenes Schwert gegen einen Schleim zu kämpfen. Nun sollt Ihr nach der Übungsklinge in einem Schleim westlich der Bucht suchen und sie zurückbringen. Sein Sergeant darf den Verlust nicht entdecken."}},faq={{q="Wer hat das Schwert verloren?",a="Wachmann Jameson verlor sein Übungsschwert, als es in einem Schleim stecken blieb.",al={"wer hat es verloren","jamesons schwert","wessen schwert"}},{q="Wo ist Jamesons Schwert?",a="Jameson glaubt, dass sein Schwert in einem Schleim westlich der Bucht steckt.",al={"wo ist das schwert","schwertfundort","jamesons schwert finden"}},{q="Warum will Jameson das Schwert zurück?",a="Jameson möchte das Schwert zurückhaben, bevor sein Sergeant bemerkt, dass es fehlt.",al={"warum zurückbringen","warum das schwert gebraucht wird","sergeant findet es heraus"}},{q="Was für ein Schwert wird vermisst?",a="Es ist Jamesons Übungsschwert.",al={"welches schwert","übungsklinge","jamesons waffe"}}},fp="18,141,12.226.0,19.70.0,25.63.0,37.76.0,30.31.0"}
P.entries["quest:98240"] = {n="Crimson Crate Delivery",s="Ein Kunde namens Howin Kindfeather hat die roten Welpen bestellt. Ihr sollt seine Kiste vom Hafen von Menethil zu einem Ort abseits der östlichen Straße bringen.",h="Ein Kunde namens Howin Kindfeather hat die roten Welpen bestellt.",kw={"rote kiste","rote welpen","lieferung","greif","howin kindfeather","hafen von menethil","whelgars ausgrabungsstätte"},sec={{t="Ein Kunde wartet",b="Die Bestellung ist für Howin Kindfeather verpackt, dessen Greif einen Brief zum Hafen von Menethil gebracht hat. Ihr sollt ihm die Crimson Crate abseits der Straße östlich der Stadt bringen, etwas hinter Whelgars Ausgrabungsstätte. Howin wartet auf die Lieferung."}},faq={{q="Wer hat die rote Kiste bestellt?",a="Howin Kindfeather hat die roten Welpen bestellt.",al={"wer ist howin","kistenkunde","howins bestellung"}},{q="Wo ist Howin Kindfeather?",a="Howin befindet sich abseits der Straße östlich des Hafens von Menethil, etwas hinter Whelgars Ausgrabungsstätte.",al={"wo ist howin","howins aufenthaltsort","howin finden"}},{q="Was ist in der Kiste?",a="Die Kiste ist für die roten Welpen bestimmt.",al={"kisteninhalt","was ist drin","rote kiste"}},{q="Wie hat Howin die Bestellung aufgegeben?",a="Howin schickte seinen Greif mit einem Brief für die Bestellung zum Hafen von Menethil.",al={"greifenbrief","wie die bestellung ankam","howins brief"}}},fp="22,152,17.241.0,30.58.0,27.89.0,21.36.0,30.72.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="Im Sumpfland sucht Howin Kindfeather Razormaw-Zähne für eine Rüstung aus Drachenwelpenschuppen. Er will daraus Ahlen fertigen, um die Schuppen zum Schutz vor Drachenfeuer zusammenzunähen.",h="Im Sumpfland sucht Howin Kindfeather Razormaw-Zähne für eine Rüstung aus Drachenwelpenschuppen.",kw={"dunkeleisen","dragonmaw","howin kindfeather","raptorgrat","raptoren","razormaw-schneidezähne","razormaw needling","salzgischtschlucht","sumpfland","welpenschuppen"},ang={["faction:Alliance"]="Schutzausrüstung gegen Drachenfeuer hilft der Allianz in ihrem anhaltenden Kampf gegen Drachkin und die Streitkräfte des Dragonmaw-Klans, die die östlichen Sümpfe besetzt halten.",["race:Dwarf"]="Als Zwerg teilt Ihr den bitteren Hass der Wildhammer-Zwerge und der Zwerge von Eisenschmiede auf den Dunkeleisenklan und die Dragonmaw-Orcs. Beide verwüsteten das Sumpfland und Grim Batol."},sec={{t="Werkzeuge der Vergeltung",b="Howin Kindfeather will gegen die Feinde zurückschlagen, die das Sumpfland heimgesucht haben: die Dunkeleisenzwerge, die Dragonmaw-Orcs und die Drakes, die sie in die Schlacht führten. Er fertigt eine Rüstung aus Drachenwelpenschuppen, die vor Drachenfeuer schützen soll. Ihre Häute sind zu zäh, um sie mit gewöhnlichen Werkzeugen zusammenzunähen."},{t="Fangzähne als Nadeln",b="Howin braucht scharfe, robuste Werkzeuge, um die Welpenhaut zu durchstechen. Er setzt auf die Razormaw-Raptoren, die den Raptorgrat im Nordosten und die Salzgischtschlucht im Nordwesten durchstreifen. Aus ihren nadelscharfen Schneidezähnen lassen sich robuste Ahlen fertigen. Diese können Drachenschuppen durchstechen, ohne unter Druck zu zerspringen."}},faq={{q="Wer vergibt die Quest Razormaw Needling?",a="Howin Kindfeather vergibt den Auftrag im Sumpfland. Er hegt einen tiefen Groll gegen die Dunkeleisenzwerge, den Dragonmaw-Klan und die Drakes, auf denen sie ritten. Er will eine Rüstung aus Welpenschuppen fertigen, die Drachenfeuer widerstehen kann.",al={"wer vergibt razormaw needling","wer ist howin kindfeather","questgeber razormaw needling"}},{q="Warum braucht Howin Kindfeather Razormaw-Schneidezähne?",a="Howin fertigt eine schützende Rüstung aus zähen Drachenwelpenschuppen, doch ihre Haut lässt sich nur schwer zusammennähen. Razormaw-Schneidezähne sind scharf und robust genug, um daraus Ahlen zu fertigen, die die Schuppen durchstechen, ohne zu brechen.",al={"warum will howin raptorenzähne","zweck der razormaw-schneidezähne","wofür sind die zähne"}},{q="Wo sind die Razormaw-Raptoren zu finden?",a="Razormaw-Raptoren durchstreifen den Raptorgrat im Nordosten des Sumpflands und die Salzgischtschlucht im Nordwesten, in Richtung Küste.",al={"wo sind razormaw-raptoren zu finden","razormaw-raptoren fundort sumpfland","wo sind die raptoren"}},{q="Was fertigt Howin Kindfeather aus den Welpenschuppen?",a="Howin näht Drachenwelpenschuppen zu schützender Ausrüstung zusammen. Die Schuppen schützen vor feurigem Atem und bieten Schutz vor Drachen und den Drakes des Dragonmaw-Klans.",al={"welche rüstung fertigt howin","welpenschuppenrüstung sumpfland","warum welpenschuppen"}},{q="Warum hasst Howin die Dunkeleisenzwerge und den Dragonmaw-Klan?",a="Howin verabscheut den Dunkeleisenklan und die Dragonmaw-Orcs, die während des Zweiten Krieges rote Drachen versklavten. Beide Fraktionen hinterließen Narben im Sumpfland und in den umliegenden Bergen. Howin will das Gleichgewicht wiederherstellen.",al={"warum hass auf dunkeleisenzwerge und dragonmaw","howins feinde","warum hasst howin dragonmaw"}},{q="Was fertigt Howin aus den Schneidezähnen der Raptoren?",a="Howin verarbeitet die Schneidezähne der Raptoren zu haltbaren Ahlen. Ihre natürliche Verjüngung lässt sie zähe Häute und Leder zum Nähen durchstoßen und Drachenschuppen durchstechen, ohne abzubrechen.",al={"was ist eine ahle","razormaw-ahlen","wie werden raptorenzähne als werkzeuge verwendet"}}},fp="17,157,20.291.0,16.280.0,38.212.0,50.198.0,39.116.0,55.165.0,49.209.0,46.173.0"}
P.entries["quest:98246"] = {n="Trying Times",s="Bevor Howin Kindfeather durch das Sumpfland fliegen kann, braucht Bassbeak eine Mahlzeit. Er sucht ein Dutzend unversehrte Eier der wilden Razormaw-Raptoren.",h="Bevor Howin Kindfeather durch das Sumpfland fliegen kann, braucht Bassbeak eine Mahlzeit.",kw={"bassbeak","greif","howin kindfeather","raptorgrat","razormaw-eier","salzgischtschlucht","trying times","sumpfland"},ang={["faction:Alliance"]="Gesunde Greifen sind für die Reisen und die Nachrichtenübermittlung der Allianz in ganz Khaz Modan wichtig, besonders wenn örtliche Gefahren die Sicherheit der Region bedrohen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass eine schlecht gelaunte Greifin so gefährlich wie ein Feind sein kann. Füttert und versorgt sie vor dem Flug.",["race:Gnome"]="Als Gnom hört Ihr vielleicht, wie Howin die Dotter der Razormaw-Eier mit dem Schädel eines Gnoms vergleicht, einem anschaulichen zwergischen Maß."},sec={{t="Eine hungrige Greifin besänftigen",b="Howin Kindfeather kümmert sich im Sumpfland um Bassbeak. Der Zwerg will mit seiner Greifin erst fliegen, wenn ihr Hunger gestillt ist. Eine hungrige Greifin kann stur und unberechenbar sein. Sie könnte um sich schlagen, also braucht sie vor jedem Flug durch die Sümpfe eine ordentliche Mahlzeit."},{t="Die Gaben der Razormaw",b="Howin sucht bei den Razormaw-Raptoren nach Nahrung für Bassbeak. Ihre Nester liegen auf dem Raptorgrat im Nordosten und in der Salzgischtschlucht im Nordwesten. Die Dotter der Razormaw-Eier sind so groß wie der Kopf eines Gnoms. Howin will Bassbeak mit diesen gehaltvollen Mahlzeiten sättigen, bevor sie sich den Gefahren des Sumpflands stellt."}},faq={{q="Wer ist Howin Kindfeather?",a="Howin Kindfeather ist ein Zwerg, der sich im Sumpfland um seine Greifin Bassbeak kümmert. Er bittet um frische Raptoreneier, um sie zu füttern, bevor er seine Pläne umsetzt.",al={"wer ist howin kindfeather","howin kindfeather sumpfland","questgeber trying times"}},{q="Wer ist Bassbeak?",a="Bassbeak ist Howin Kindfeathers Greifin. Wenn sie hungrig ist, wird sie reizbar und gefährlich, weshalb es unsicher ist, sie zu reiten, bevor sie gefressen hat.",al={"wer ist bassbeak","bassbeak die greifin","howins greifin"}},{q="Warum braucht Howin Raptoreneier?",a="Howin sucht Eier der Razormaw-Raptoren, weil es laut ihm im Sumpfland kaum unverdorbene Nahrung gibt. Ihre großen, nahrhaften Dotter können Bassbeaks Hunger stillen.",al={"warum raptoreneier","warum greifin mit eiern füttern","wofür sind die eier"}},{q="Wo sind Razormaw-Raptoren zu finden?",a="Razormaw-Raptoren leben im Sumpfland auf dem Raptorgrat im Nordosten und in der Salzgischtschlucht im Nordwesten. In ihren Nestern liegen die Eier, die Howin sucht.",al={"wo sind razormaw-raptoren","wo razormaw-eier finden","raptorenfundorte sumpfland"}},{q="Warum müssen die Eier makellos sein?",a="Howin bittet um Eier ohne Risse oder andere Schäden, damit Bassbeak frische, unverdorbene Nahrung statt verdorbener Reste bekommt.",al={"warum müssen eier makellos sein","gesprungene eier trying times"}},{q="Was hat Howin mit Bassbeak vor?",a="Howin hat einen größeren Plan für Bassbeak, doch die Einzelheiten müssen warten, bis sie satt und ruhig genug ist, um inmitten der Gefahren der Region sicher zu fliegen.",al={"was ist howins plan","was planen howin und bassbeak"}}},fp="12,140,26.252.0,19.298.0,25.150.0,16.139.0,32.153.0,36.146.0,35.109.0,43.133.0"}
P.entries["quest:98247"] = {n="Versandetikett",s="Ein beschädigtes Shipping Label führt Euch zum Handelsknotenpunkt der Handelskommission von Azeroth bei Drei Ecken im Rotkammgebirge. Es kennzeichnet eine Vorratskiste als Eigentum der Kommission und zeigt, wo sie zu melden ist.",h="Ein beschädigtes Shipping Label führt Euch zum Handelsknotenpunkt der Handelskommission von Azeroth bei Drei...",kw={"handelskommission von azeroth","kiste","lieferung","merchant's favor","rotkammgebirge","shipping label","drei ecken"},ang={["faction:Alliance"]="Als Reisende der Allianz in den südlichen Gebieten könnt Ihr der Handelskommission von Azeroth helfen, von ihrem Knotenpunkt bei Drei Ecken aus verirrte Fracht zu bergen und Transportwege über Land zu sichern."},sec={{t="Eine verirrte Lieferung",b="Ein beschädigtes Etikett kennzeichnet eine gefüllte Vorratskiste als Fracht der Handelskommission von Azeroth. Bestimmungsort und Empfänger sind abgerissen. Wer die Fracht findet, kann sie zurückbringen oder beim Handelsposten der Kommission im Rotkammgebirge melden. Neben dem förmlichen Text zeigt eine grobe Karte die Straßen zur Kreuzung Drei Ecken."},{t="Der Knotenpunkt der Handelskommission",b="Bei Drei Ecken werben Vertreter der Handelskommission von Azeroth Reisende als unabhängige Kuriere an. Die Kommission verlangt von ihren Frachtführern keine strengen Händlerverträge. Stattdessen betreibt sie ein informelles Netzwerk und gewährt Kurieren Merchant's Favor, wenn sie entlang der Landstraße verschollene Fracht bergen oder aufgegebene Lieferungen abschließen."}},faq={{q="Was ist das Shipping Label?",a="Ein beschädigtes Shipping Label kennzeichnet eine Vorratskiste im Besitz der Handelskommission von Azeroth. Der Name des Empfängers fehlt, doch das Etikett weist den Finder der Kiste an, sich beim Knotenpunkt der Kommission bei Drei Ecken zu melden.",al={"was ist shipping label","shipping label quest","zerrissenes shipping label"}},{q="Was ist die Handelskommission von Azeroth?",a="Die Handelskommission von Azeroth organisiert Logistik, Handel und Frachtverkehr in der gesamten Region. Ihre örtlichen Handelsknotenpunkte bergen verlorene Lieferungen, und ihre umherreisenden Kuriere arbeiten ohne langfristige Verträge.",al={"wer ist aca","handelskommission von azeroth","was ist die handelskommission von azeroth"}},{q="Wo liegt der Handelsknotenpunkt der Handelskommission von Azeroth?",a="Der Handelsknotenpunkt der Handelskommission von Azeroth liegt an der Kreuzung Drei Ecken im Rotkammgebirge. Die Straßen dort verbinden den Wald von Elwynn, den Dämmerwald und Seenhain.",al={"wo ist der aca-handelsknotenpunkt","knotenpunkt drei ecken","wo shipping label abgeben"}},{q="Was ist Merchant's Favor?",a="Merchant's Favor ist ein Wertschein oder Guthaben, das die Handelskommission von Azeroth unabhängigen Kurieren gewährt. Partner können damit an den Posten der Kommission Handelswaren und Logistikdienste erwerben.",al={"was ist merchant's favor","merchant's favor","aca-vergütung"}},{q="Wie wird man Partner der Handelskommission von Azeroth?",a="Ihr braucht weder einen förmlichen Vertrag noch Papierkram oder eine langfristige Verpflichtung, um Partner zu werden. Die Handelskommission von Azeroth bittet Kuriere, fehlgeleitete Lieferungen, auf die sie unterwegs stoßen, zurückzubringen oder abzuschließen.",al={"wie aca-partner werden","aca beitreten","ist ein vertrag nötig"}},{q="Was geschieht nach der Abgabe des Etiketts mit der Kiste?",a="Nachdem Ihr das Etikett abgegeben habt, erkundigen sich die Vertreter am Handelsknotenpunkt nach der Kiste, von der es stammt. Die Rückgabe leerer Versandbehälter oder solcher, deren Lieferung abgeschlossen ist, bleibt für ihren Handelsbetrieb unverzichtbar.",al={"was geschieht mit der kiste","vermisste kiste","wollen sie die kiste"}}},fp="14,206,16.350.0,28.327.0,27.216.0,39.192.0,58.165.0,25.189.0,65.208.0,53.185.0"}
P.entries["quest:98248"] = {n="Versandetikett",s="Ein zerrissenes Frachtmanifest weist Boten zu Versorgung und Logistik Durotar im Brachland. Das Unternehmen ist auf Reisende angewiesen, die verlorene Kisten bergen und Schriftstücke zu seinem Posten westlich des Wegekreuzes zurückbringen, damit Versorgung und Handel im zentralen Kalimdor weiterlaufen.",h="Ein zerrissenes Frachtmanifest weist Boten zu Versorgung und Logistik Durotar im Brachland.",kw={"kiste","das wegekreuz","versorgung und logistik durotar","shipping label","brachland","handelsaußenposten"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr auf Euren Reisen durch das Brachland Versorgung und Logistik Durotar begegnen. Seine Arbeit trägt dazu bei, Handel und Versorgung zwischen Durotar und dem zentralen Kalimdor aufrechtzuerhalten."},sec={{t="Ein verirrtes Frachtmanifest",b="Ein zerrissenes Frachtmanifest ist an einer frisch aufgefüllten Frachtkiste befestigt. Der Name des Empfängers ist durch Abnutzung unleserlich geworden, doch die Kopfzeile nennt Versorgung und Logistik Durotar, ein Frachtunternehmen im Gebiet der Horde. Neben dem Text weist eine grobe Karte Boten den Weg zum Sammelplatz des Unternehmens in den zentralen Ebenen."},{t="Handel im Grenzland",b="Der Aushang heißt Reisende willkommen, die fehlgeleitete Behälter, beschädigte Waren oder Bergungsnachweise zum Handelsaußenposten westlich des Wegekreuzes bringen. Versorgung und Logistik Durotar ist auf unabhängige Frachtführer angewiesen, die verstreute Fracht im gesamten Brachland bergen. Wer hilft, die regionale Versorgung aufrechtzuerhalten, erhält eine Vergütung."}},faq={{q="Was ist das Shipping Label?",a="Das Shipping Label ist ein zerrissenes Dokument an einer frisch aufgefüllten Kiste, mit Rückgabeanweisungen für Versorgung und Logistik Durotar und einer Wegbeschreibung zu dessen Posten nahe dem Wegekreuz.",al={"was ist das shipping label","shipping label quest","zerrissenes shipping label"}},{q="Wohin soll das Etikett gebracht werden?",a="Das Etikett weist Boten zum Handelsknotenpunkt von Versorgung und Logistik Durotar westlich des Wegekreuzes im Brachland.",al={"wohin mit dem shipping label","wer will das shipping label","shipping label abgeben"}},{q="Was ist Versorgung und Logistik Durotar?",a="Versorgung und Logistik Durotar ist ein Frachtunternehmen im Gebiet der Horde. Es übernimmt Frachttransporte, das Einsammeln von Kisten und logistische Unterstützung in ganz Durotar und im Brachland.",al={"was ist versorgung und logistik durotar","außenposten von versorgung und logistik durotar"}},{q="Für wen war die Lieferung ursprünglich bestimmt?",a="Der Name des Empfängers wurde abgerissen, sodass nur die Rückgabeanweisungen und die Herkunftsangaben des Unternehmens auf der Kiste verblieben sind.",al={"für wen war die kiste bestimmt","empfänger der kiste"}},{q="Wo liegt der Handelsaußenposten von Versorgung und Logistik Durotar?",a="Die Wegbeschreibung und die grobe Karte auf dem Etikett verorten den Außenposten westlich des Wegekreuzes im Brachland.",al={"wo ist der handelsaußenposten","versorgung und logistik durotar standort wegekreuz"}},{q="Vergütet Versorgung und Logistik Durotar Reisende für die Rückgabe von Kisten?",a="Ja. Der Aushang verspricht Reisenden eine Vergütung, wenn sie beschädigte Lieferungen, Etiketten oder leere Kisten zum Handelsknotenpunkt bringen.",al={"vergütung für zurückgebrachte kisten","versorgung und logistik durotar vergütung"}}},fp="14,255,18.294.0,17.312.0,27.184.0,36.111.0,37.170.0,45.123.0,64.93.0,76.116.0"}
P.entries["quest:98251"] = {n="Never Coming Back",s="Va'xug Firefure sitzt in einer Schlucht im Eschental fest und bittet Euch, die Wildtiere in der Nähe zu dezimieren. Die verwirrenden Waldwege und Va'xugs unberechenbare Zauber haben Va'xug wütend gemacht.",h="Va'xug Firefure sitzt in einer Schlucht im Eschental fest und bittet Euch, die Wildtiere in der Nähe zu...",kw={"eschental","eschental bär","kräuter","never coming back","schlucht","shadowhorn stag","va'xug firefure","unberechenbare zauber"},sec={{t="Die Falle des Waldes",b="Va'xug Firefure sammelt Kräuter im Eschental, als die Waldwege Va'xug in einer Schlucht stranden lassen. Laut Va'xug werden die eigenen Zauber bei Wut unberechenbar, und die Tiere in der Nähe verschlimmern die Laune nur noch. Va'xug bittet Euch, die Wildtiere ringsum zu dezimieren."},{t="Ein ruhigeres Gemüt",b="Va'xug Firefure dankt Euch, nachdem die Wildtiere in der Nähe dezimiert wurden. Laut Va'xug scheint das geholfen zu haben, doch der Zorn auf den Wald bleibt deutlich spürbar."}},faq={{q="Wer ist Va'xug Firefure?",a="Va'xug Firefure sammelt Kräuter im Eschental, als Va'xug in einer Schlucht festsitzt.",al={"va'xug","firefure","wer ist va'xug"}},{q="Warum ist Va'xug wütend?",a="Va'xug ist wütend, weil die Wege des Eschentals Va'xug in einer Schlucht stranden ließen und die Tiere in der Nähe an den Nerven zerren.",al={"warum wütend","va'xug wütend","hasst eschental"}},{q="Worum bittet mich Va'xug?",a="Va'xug bittet Euch, die Wildtiere in der Nähe zu dezimieren.",al={"was tun","wildtiere dezimieren","tiere töten"}},{q="Warum sind Va'xugs Zauber unberechenbar?",a="Va'xug sagt, dass die eigenen Zauber bei Wut unberechenbar werden und sich anders verhalten.",al={"unberechenbare zauber","magie verhält sich seltsam","zauber anders"}}},fp="17,180,14.258.0,13.152.1,23.85.0,20.114.0,30.44.0,33.82.0"}
P.entries["quest:98252"] = {n="A Void Path",s="Va'xug bittet Euch, sein Eye of Kilrogg aus einer Schlucht zur Straße im Eschental zu führen. Die Vision muss die Straße erreichen, bevor die Verbindung abbricht.",h="Va'xug bittet Euch, sein Eye of Kilrogg aus einer Schlucht zur Straße im Eschental zu führen.",kw={"ein pfad der leere","eschental","verbindung","eye of kilrogg","schlucht","straße","va'xug","voidwalker"},sec={{t="Durch das Auge",b="Va'xug bleibt zurück, um die Orientierung zu behalten, während Ihr das schwebende Auge führt. Wenn Ihr den Weg verliert, kann er Euch hindurch zurückleiten. Er kann die Verbindung nur vier Minuten lang aufrechterhalten, also muss die Vision die Hauptstraße im Eschental erreichen, bevor sie abbricht."},{t="Ein klarer Pfad",b="Das Auge kehrt mit einem Blick auf die Route zurück. Va'xug sagt, die Vision werde ihm helfen, seinen widerspenstigen Voidwalker auf dem Pfad zu führen, wenn er ihn erneut beschwört. Das Eye of Kilrogg beginnt zu verblassen, während sein Dank aus dem Inneren widerhallt."}},faq={{q="Wer bittet mich, das Auge zu führen?",a="Va'xug bittet Euch, sein Eye of Kilrogg aus der Schlucht zur Straße im Eschental zu führen.",al={"wer ist va'xug","va'xugs auge","augenquest"}},{q="Wozu dient das Eye of Kilrogg?",a="Va'xug sagt, seine Vision werde ihm helfen, seinen widerspenstigen Voidwalker auf dem richtigen Pfad zu führen, wenn er ihn erneut beschwört.",al={"wozu dient das auge","eye of kilrogg","schwebendes auge"}},{q="Warum bleibt Va'xug zurück?",a="Va'xug bleibt zurück, damit einer von Euch die Orientierung behält. Wenn Ihr den Weg verliert, kann er Euch durch das Auge zurückleiten.",al={"warum zurückbleiben","va'xug bleibt zurück","orientierung behalten"}},{q="Wie lange kann Va'xug die Verbindung aufrechterhalten?",a="Va'xug kann die Verbindung vier Minuten lang aufrechterhalten.",al={"dauer der verbindung","vier minuten","wie lange das auge"}},{q="Wohin soll ich das Auge führen?",a="Führt das Eye of Kilrogg aus der Schlucht zurück zur Hauptstraße im Eschental.",al={"wohin mit dem auge","straße im eschental","weg aus der schlucht"}}},fp="11,138,15.243.0,12.216.0,34.82.0,31.114.0,28.120.0,37.45.0,29.79.0"}
P.entries["quest:98282"] = {n="Alchemical Hazards",s="Caitlin Grassman im Hafen von Menethil braucht eine intakte Spinnendrüse, um mehr Gegengift herzustellen. Im giftigen Sumpf lässt sich diese Zutat nur schwer gefahrlos beschaffen.",h="Caitlin Grassman im Hafen von Menethil braucht eine intakte Spinnendrüse, um mehr Gegengift herzustellen.",kw={"alchemical hazards","gegengift","caitlin grassman","hafen von menethil","spinnen","thelgenfelsen","unruptured stalker gland","giftdrüse"},sec={{t="Eine unversehrte Drüse",b="Caitlin Grassman im Hafen von Menethil stellt Gegengift her, braucht dafür aber eine Giftdrüse von einer Spinne am Thelgenfelsen. Sie bittet Euch, die Drüse unversehrt zurückzubringen, damit das Gift nicht ausläuft, bevor es sie erreicht."}},faq={{q="Wer braucht die Drüse?",a="Caitlin Grassman im Hafen von Menethil braucht sie, um mehr Gegengift herzustellen.",al={"wer will die drüse","caitlin grassman"}},{q="Woher stammt die Drüse?",a="Caitlin bittet Euch, eine Giftdrüse von einer Spinne am Thelgenfelsen zu beschaffen, weit im Südosten.",al={"wo drüse finden","fundort spinnendrüse"}},{q="Warum muss die Drüse unversehrt bleiben?",a="Caitlin braucht eine unbeschädigte Drüse, damit das Gift nicht ausläuft, bevor Ihr sie zu ihr bringt.",al={"warum unbeschädigt","unversehrte drüse"}},{q="Was stellt Caitlin her?",a="Caitlin braucht die Drüse, um mehr Gegengift herzustellen.",al={"zutaten für gegengift","was braut sie"}}},fp="18,151,13.204.0,20.68.0,31.90.0,38.89.0,23.47.0"}
P.entries["quest:98283"] = {n="Carnage",s="Im Sumpfland bittet Euch Rethiel der Sumpfhüter, Carnage aus seinem Versteck zu locken. Die seuchenbedingte Raserei des Razormaw-Alphas hat die Marschen aus dem Gleichgewicht gebracht.",h="Im Sumpfland bittet Euch Rethiel der Sumpfhüter, Carnage aus seinem Versteck zu locken.",kw={"carnage","loch modan","raptorgrat","razormaw","rethiel der sumpfhüter","rotclaw","der grüne gürtel","sumpfland"},ang={["class:Druid"]="Als Druide teilt Ihr Rethiels Trauer über das gestörte Gleichgewicht des Sumpflands. Krankheit hat Raubtiere wie Carnage zu geistlosen Schreckensgestalten entstellt.",["class:Hunter"]="Als Jäger kennt Ihr die Gefahr, wenn seuchenbedingte Raserei einem Alpharaubtier seine Instinkte raubt. Dann wendet es sich gegen seine eigene Art."},sec={{t="Ein gestörtes Gleichgewicht",b="Die Razormaw-Raptoren hielten einst den Wildwuchs im gesamten Sumpfland in Schach. Nun beherrscht ein blutrünstiger Alpha namens Carnage das Rudel. Er schlachtet hemmungslos und versetzt seine eigene Art in Schrecken. Die Marschen sind in Aufruhr."},{t="Den Alpha hervorlocken",b="Rethiel der Sumpfhüter wacht über den grünen Gürtel und glaubt, dass Verderbnis von Carnage Besitz ergriffen hat. Erkrankte Rotclaw-Bären kamen aus Loch Modan herab. Ihr sammelt ihre bösartigen Eingeweide und legt das widerliche Fleisch in Carnages Höhle unterhalb des Raptorgrats. Der rasende Alpha greift an, und sein Leiden kann ein Ende finden."}},faq={{q="Wer ist Carnage?",a="Carnage ist der monströse Alpha der Razormaw-Raptoren im Sumpfland. Krankheit hat die Bestie in den Wahnsinn getrieben, sodass sie ein Blutbad hinterlässt und ihr eigenes Rudel in Schrecken versetzt.",al={"wer ist carnage","carnage raptor","was ist carnage"}},{q="Wer vergibt die Quest Carnage?",a="Rethiel der Sumpfhüter erteilt den Auftrag. Er wacht über den grünen Gürtel im Sumpfland und will das gestörte natürliche Gleichgewicht der Region wiederherstellen.",al={"wer vergibt die quest carnage","wo die quest carnage abgeben","rethiel sumpfland"}},{q="Warum muss Carnage vernichtet werden?",a="Rethiel will Carnages Tod, weil eine unnatürliche Krankheit die Bestie in den Wahnsinn getrieben hat. Ihr Wahnsinn hat die Hierarchie der Razormaw zerschlagen und das örtliche Ökosystem verwüstet.",al={"warum carnage töten","warum will rethiel carnages tod"}},{q="Wie wird Carnage hervorgelockt?",a="Ihr lockt Carnage hervor, indem Ihr das bösartige Fleisch und die Eingeweide erkrankter Bären in seine Höhle im Nordosten unterhalb des Raptorgrats legt.",al={"wie carnage beschwören","wie carnage hervorlocken","wo ist carnages höhle"}},{q="Was sind die erkrankten Bären, die Rethiel erwähnt?",a="Die erkrankten Bären sind Rotclaw-Bären, die aus Loch Modan herabkamen. Anhaltende Verderbnis hat sie in den Wahnsinn getrieben, und ihr verseuchtes Fleisch lockt den wahnsinnigen Raptorenalpha hervor.",al={"was sind rotclaw-bären","woher kommen die erkrankten bären"}},{q="Welche Rolle erfüllten die Razormaw-Raptoren ursprünglich im Sumpfland?",a="Die Razormaw-Raptoren verhindern normalerweise, dass sich die heimischen Pflanzen und Tiere des Sumpflands übermäßig vermehren. Dadurch helfen sie, das ökologische Gleichgewicht zu bewahren. Carnages Wahnsinn hat diese Aufgabe gestört.",al={"welche rolle spielen die razormaw","warum sind raptoren im sumpfland wichtig"}}},fp="7,161,16.216.0,16.305.0,15.159.0,28.147.0,30.161.0,25.128.0,49.162.0,68.187.0"}
P.entries["quest:98284"] = {n="Camping 101: Enchanting",s="Nasalanna Windsinger in Shen'dar kann Euch lehren, einen Lagergegenstand für Euren Beruf herzustellen. Verzauberer können lernen, eine Verzauberte Laute zur Unterhaltung unterwegs herzustellen.",h="Nasalanna Windsinger in Shen'dar kann Euch lehren, einen Lagergegenstand für Euren Beruf herzustellen.",kw={"lagern grundlagen","lagergegenstand","verzauberte laute","verzauberer","verzauberkunst","nasalanna windsinger","shen'dar"},ang={["profession:Tailoring"]="Als Verzauberer könnt Ihr lernen, eine Verzauberte Laute zur Unterhaltung im Lager herzustellen."},sec={{t="Eine Laute fürs Lager",b="Ein Verzauberer kann ein Lager in der Wildnis bereichern, und Ihr werdet zu Nasalanna Windsinger in Shen'dar geschickt. Sobald Ihr Euer Können unter Beweis gestellt habt, kann Nasalanna Euch lehren, eine Verzauberte Laute herzustellen. Das verzauberte Instrument bietet Unterhaltung während der Rast, bevor Ihr wieder aufbrecht."}},faq={{q="Wer lehrt mich, eine Verzauberte Laute herzustellen?",a="Nasalanna Windsinger in Shen'dar kann Euch lehren, eine Verzauberte Laute herzustellen, sobald Ihr Euer Können unter Beweis gestellt habt.",al={"lehrer für verzauberte laute","wer lehrt laute","nasalanna lagern"}},{q="Wozu dient die Verzauberte Laute?",a="Die Verzauberte Laute sorgt während der Rast im Lager für Unterhaltung.",al={"laute verwendung","laute fürs lager","warum verzauberte laute"}},{q="Warum sind Verzauberer in Lagern willkommen?",a="Verzauberer können Lager in der Wildnis bereichern, unter anderem mit einer Verzauberten Laute zur Unterhaltung.",al={"verzauberer lagern","warum verzauberer willkommen","lagern verzauberkunst"}},{q="Wann kann ich das Lagerhandwerk erlernen?",a="Ihr könnt von Nasalanna Windsinger lernen, nachdem Ihr Euer Können unter Beweis gestellt habt.",al={"wann laute lernen","können unter beweis stellen","lagerhandwerk voraussetzung"}}},fp="23,178,15.304.0,41.128.0,31.68.0,36.103.0,35.87.0"}
P.entries["quest:98285"] = {n="Camping 101: Engineering",s="Der Strange Hermit im Schattenwindwald lehrt Euch, einen Campinggegenstand herzustellen, nachdem Ihr Euer Können als Ingenieur bewiesen habt. Der Reagent Bot ist für den Einsatz in einem Lager in der Wildnis gedacht.",h="Der Strange Hermit im Schattenwindwald lehrt Euch, einen Campinggegenstand herzustellen, nachdem Ihr Euer...",kw={"lagerfeuer","camping 101","kochkunst","ingenieurskunst","reagent bot","schattenwindwald","strange hermit","lager in der wildnis"},ang={["profession:Cooking"]="Als Koch könnt Ihr anderen beibringen, das Lagerfeuer zu entfachen, das zum Aufschlagen eines Lagers benötigt wird.",["profession:Engineering"]="Als Ingenieur könnt Ihr lernen, einen Reagent Bot für ein Lager in der Wildnis herzustellen, nachdem Ihr dem Strange Hermit Euer Können bewiesen habt."},sec={{t="Ein Lager in der Wildnis",b="Der Strange Hermit im Schattenwindwald verlangt einen Nachweis Eurer Ingenieurskunst, bevor er Euch ein Campinghandwerk beibringt. Ingenieure können ihr Handwerk auch allein in der Wildnis nutzen, wo hilfreiche Konstrukte ein Lager vervollständigen können."},{t="Ein Lager aufschlagen",b="Der Strange Hermit lehrt Euch, einen Reagent Bot herzustellen. Um ein Lager aufzuschlagen, braucht Ihr auch ein Lagerfeuer, dessen Entfachen Euch die meisten Köche beibringen können. Der Hermit warnt, dass die Stadtbewohner Lager mitten in der Stadt nicht gern sehen."}},faq={{q="Wer bringt mir das Campinghandwerk bei?",a="Der Strange Hermit im Schattenwindwald bringt Euch das Campinghandwerk bei, nachdem Ihr Eure Ingenieurskunst unter Beweis gestellt habt.",al={"wer ist der hermit","campinglehrer","wo camping mit ingenieurskunst lernen"}},{q="Was hat Ingenieurskunst mit Camping zu tun?",a="Der Hermit sagt, Ingenieure können ihr Handwerk in der Wildnis nutzen und hilfreiche Konstrukte für ein Lager herstellen.",al={"lagergegenstand ingenieurskunst","warum camping als ingenieur","camping 101 ingenieurskunst"}},{q="Was kann ich herstellen?",a="Der Hermit lehrt Euch, einen Reagent Bot herzustellen.",al={"was ist der campinggegenstand","reagent bot","lagergegenstand ingenieurskunst"}},{q="Brauche ich noch etwas für ein Lager?",a="Ihr braucht ein Lagerfeuer, um Euer Lager aufzuschlagen. Die meisten Köche können Euch beibringen, eines zu entfachen.",al={"lagerfeuer nötig","wie lager aufschlagen","campingfeuer"}},{q="Wo sollte ich mein Lager aufschlagen?",a="Der Hermit sagt, die Stadtbewohner sehen Lager im Stadtzentrum nicht gern, also begebt Euch in die Wildnis, um Euer Lager auszuprobieren.",al={"lagerplatz","wo reagent bot testen","camping in der stadt möglich"}}},fp="24,167,17.234.0,15.221.1,33.112.0,46.99.0,17.46.0,35.77.0,27.124.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="In Shen'dar können erfahrene Verzauberer lernen, eine Verzauberte Laute für das Lagerfeuer herzustellen. Nasalanna Windsinger lehrt sie, wie diese Gefährten unterhält und stärkt.",h="In Shen'dar können erfahrene Verzauberer lernen, eine Verzauberte Laute für das Lagerfeuer herzustellen.",kw={"lagerfeuer","lagern","camping 101","verzauberte laute","verzauberkunst","laute","nasalanna windsinger","shen'dar"},sec={{t="Behaglichkeit am Herdfeuer",b="Unterwegs reichen geschärfte Klingen und Rationen allein nicht aus. Reisende brauchen Ruhe und gute Laune, um lange Expeditionen durchzustehen. Verzauberer bringen magische Annehmlichkeiten in die Lager überall in Azeroth und helfen erschöpften Reisenden, Kraft und Zuversicht zu schöpfen, bevor sie auf gefährliche Pfade zurückkehren."},{t="Das Lied von Shen'dar",b="Angehende Verzauberer, die Magie für Lagerplätze erlernen möchten, reisen nach Shen'dar. Dort lehrt Nasalanna Windsinger fähige Zauberweber, eine Verzauberte Laute herzustellen. Zuerst müssen sie ihre Hingabe und ihr Können in der Verzauberkunst beweisen. Dann verrät Nasalanna, wie sie ein Instrument anfertigen, dessen Melodien unter den Sternen neue Zuversicht schenken."}},faq={{q="Wer ist Nasalanna Windsinger?",a="Nasalanna Windsinger lebt in Shen'dar und lehrt erfahrene Verzauberer, besondere Gegenstände für Lager in der Wildnis herzustellen. Wer sein Können beweist, lernt bei ihr, die Verzauberte Laute herzustellen.",al={"wer lehrt die verzauberte laute","wer ist nasalanna windsinger","wo ist nasalanna windsinger"}},{q="Wo liegt Shen'dar?",a="In Shen'dar lebt Nasalanna Windsinger. Verzauberer reisen dorthin, um die Herstellung von Lagerausrüstung wie der Verzauberten Laute zu erlernen, sobald sie ihre grundlegenden Fertigkeiten entwickelt haben.",al={"wo liegt shen'dar","wie findet man shen'dar"}},{q="Was ist eine Verzauberte Laute?",a="Verzauberer stellen die Verzauberte Laute als magisches Instrument für Lager her. Sie unterhält Gefährten am Lagerfeuer und hebt ihre Moral, damit sich Reisende für die vor ihnen liegende Wildnis wappnen können.",al={"was bewirkt die verzauberte laute","warum eine verzauberte laute herstellen","laute fürs lager"}},{q="Welche Voraussetzungen gelten, um das Rezept zu erlernen?",a="Um die Herstellung einer Verzauberten Laute zu erlernen, müsst Ihr Nasalanna Windsinger zuerst Euer Können in der Verzauberkunst beweisen. Diese Lagerverzauberung vertraut sie erfahrenen Verzauberern an.",al={"voraussetzungen für camping 101: enchanting","wann lässt sich die verzauberte laute erlernen"}},{q="Warum sind Verzauberer in Wildnislagern wertvoll?",a="In Wildnislagern bringen Verzauberer magische Annehmlichkeiten, wenn gewöhnliche Vorräte nicht ausreichen. Ihre Verzauberungen helfen Reisenden, sich zu erholen, Unterhaltung zu finden und sich auf Gefahren unterwegs vorzubereiten.",al={"warum wollen lagernde verzauberer dabeihaben","vorteile von verzauberern beim lagern"}},{q="Können andere Berufe Gegenstände für das Lager herstellen?",a="Ja. Handwerker und Sammler verschiedener Fachrichtungen lernen, Werkzeuge für Lagerplätze herzustellen. Verzauberer lernen bei Nasalanna Windsinger in Shen'dar, die Verzauberte Laute herzustellen.",al={"gibt es weitere lagergegenstände","lagerausrüstung aus anderen berufen"}}},fp="23,170,22.284.0,20.330.0,28.190.0,26.185.0,26.202.0,46.172.0,52.188.0,42.179.0"}
P.entries["quest:98291"] = {n="Death to the Dragonmaw",s="In der Zuflucht des Drachenmals bittet Howin Kindfeather Euch, die Reihen der Dragonmaw auszudünnen. Er hofft, Grim Batol zu erreichen und es für die Wildhämmer zurückzuerobern oder mehr darüber zu erfahren.",h="In der Zuflucht des Drachenmals bittet Howin Kindfeather Euch, die Reihen der Dragonmaw auszudünnen.",kw={"dragonmaw infiltrators","dragonmaw-orks","dragonmaw reclaimers","die zuflucht des drachenmals","dragonmaw soulbinders","grim batol","howin kindfeather","wildhämmer"},sec={{t="Die Zuflucht des Drachenmals",b="Dragonmaw-Orks haben sich entlang der Zuflucht versammelt, wo rote Drachen sie schon einmal in die Flucht schlugen. Howin muss ihre Zahl verringern, bevor er sich Grim Batol nähern kann. Er weist Euch nach Osten, die Straße entlang, um sie zu finden."}},faq={{q="Wer ist Howin Kindfeather?",a="Howin Kindfeather hofft, wieder nach Grim Batol zu gelangen und es für die Wildhämmer zurückzuerobern oder zumindest mehr darüber zu erfahren.",al={"wer ist howin","typ namens howin"}},{q="Warum braucht Howin Hilfe?",a="Howin sagt, dass Dragonmaw-Orks durch die Zuflucht des Drachenmals marschieren. Er muss ihre Reihen ausdünnen, bevor er sich Grim Batol nähern kann.",al={"warum howin helfen","was braucht howin"}},{q="Wo sind die Dragonmaw-Orks?",a="Die Dragonmaw-Orks sind entlang der Zuflucht des Drachenmals zu finden. Howin weist Euch nach Osten, die Straße entlang, um sie zu finden.",al={"wo sind dragonmaw","dragonmaw aufenthaltsort"}},{q="Nach wem soll ich suchen?",a="Howin nennt Dragonmaw Reclaimers, Dragonmaw Soulbinders und Dragonmaw Infiltrators.",al={"welche orks","dragonmaw arten"}},{q="Was geschah in der Zuflucht des Drachenmals?",a="Rote Drachen schlugen die Dragonmaw-Orks schon einmal in der Zuflucht des Drachenmals in die Flucht.",al={"dragonmaw geschichte","warum zuflucht"}}},fp="22,166,17.202.0,25.120.0,25.131.0,29.98.0,22.84.0,35.66.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="In der Zuflucht des Drachenmals beschlagnahmt Ihr für Hauptmann Starkfaust dreißig Waffenbündel von feindseligen Orcs. Ihr Verlust hindert den Clan daran, weitere Soldaten für künftige Überfälle auszurüsten. Ihr bringt die Ausrüstung zu Hauptmann Starkfaust in die Burg Menethil und helft damit, den wichtigen Hafen der Region zu schützen.",h="In der Zuflucht des Drachenmals beschlagnahmt Ihr für Hauptmann Starkfaust dreißig Waffenbündel von...",kw={"hauptmann starkfaust","waffen der dragonmaw","clan des drachenmals","die zuflucht des drachenmals","forced disarmament","hafen von menethil","burg menethil","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf den Hafen von Menethil als lebenswichtige Verbindung über das große Meer angewiesen. Die Entwaffnung feindseliger Clans in der Nähe ist ein dringendes Anliegen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Verteidiger aus Eisenschmiede die Garnison der Burg Menethil bilden. Sie sichern die Grenzen von Khaz Modan gegen alte Feinde, die sich in den Marschen verschanzt haben.",["race:Orc"]="Als Orc wisst Ihr, dass die Orcs des Drachenmals ein zersplitterter, uneinsichtiger Überrest der Old Horde sind. Ihre gewaltsame Kriegstreiberei unterscheidet sie von der neuen Führung der Horde in Kalimdor."},sec={{t="Eine Waffenkammer in den Marschen",b="Im Sumpfland hat der Clan des Drachenmals eine beunruhigende Menge an Waffen in der Zuflucht des Drachenmals eingelagert. Bleiben sie dort, könnten sie neue Kriegerscharen für Überfälle auf nahe gelegene Siedlungen ausrüsten. Die Beschlagnahmung der Waffen schwächt die Vorbereitungen der Orcs, bevor ihre Kriegerscharen ins Feld ziehen können."},{t="Den Küstenhafen sichern",b="Der Hafen von Menethil verbindet Khaz Modan und Sturmwind mit dem Meer und ist dadurch ein wichtiger Seehafen. Militärische Aufrüstung in der Nähe bringt ihn in Gefahr. Hauptmann Starkfaust leitet die Hafenverteidigung von der Burg Menethil aus und beobachtet, wie feindselige Clans und Bestien näher rücken. Die Bergung von dreißig Sätzen Waffen der Dragonmaw entzieht den Orcs Waffen und gibt der zwergischen Garnison Aufschluss über deren Einsatzbereitschaft."}},faq={{q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist ein zwergischer Offizier in der Burg Menethil. Er ist für die Verteidigung des Hafens von Menethil und des umliegenden Sumpflands verantwortlich. Während feindselige Bestien, Dark Iron-Saboteure und der Clan des Drachenmals näher rücken, beauftragt er Soldaten und Abenteurer, Bedrohungen einzudämmen, bevor die Versorgungslinien und Hafenanlagen überrannt werden.",al={"starkfaust","wer ist starkfaust","burg menethil hauptmann"}},{q="Warum muss der Clan des Drachenmals entwaffnet werden?",a="Der Clan des Drachenmals sammelt in seiner Zuflucht Waffen, um neue Kämpfer auszurüsten. Ungehindert könnten seine Kriegerscharen die örtlichen Verteidigungskräfte der Allianz überwältigen und den Hafen von Menethil gefährden. Die Beschlagnahmung von dreißig Bündeln behindert ihre Vorbereitungen und hält weitere Orcsoldaten davon ab, ins Feld zu ziehen.",al={"warum waffen des drachenmals beschlagnahmen","waffen der dragonmaw zweck","drachenmal entwaffnen"}},{q="Wo liegt die Zuflucht des Drachenmals?",a="Die Zuflucht des Drachenmals ist ein Lager der Orcs des Drachenmals im Sumpfland, östlich des Hafens von Menethil in Richtung der Berge. Der Clan lagert dort Waffen, sammelt Truppen und führt von dort aus Angriffe auf Reisende in den Marschen durch. Ihr wagt Euch ins Herz des Lagers, um die gehorteten Waffen zu bergen.",al={"zuflucht des drachenmals lage","wo liegt die zuflucht des drachenmals","zuflucht des drachenmals sumpfland"}},{q="Was sind Waffen der Dragonmaw?",a="Waffen der Dragonmaw sind Bündel aus Kriegsgerät, Klingen und Ausrüstung, die der Clan des Drachenmals für seine Krieger geschmiedet oder gestohlen hat. Sie verkörpern die unmittelbar verfügbare militärische Stärke des Clans in der Region. Hauptmann Starkfaust bittet Euch, dreißig Bündel zu beschlagnahmen und zur Begutachtung und Entsorgung in die Burg Menethil zu bringen.",al={"waffen des drachenmals","was sind rüstungsgüter","ausrüstung des drachenmals"}},{q="Gehört der Clan des Drachenmals im Jahr 25 ADP zur Horde?",a="Nein. Der Clan des Drachenmals im Sumpfland ist eine unabhängige, feindselige Fraktion, die Kriegshäuptling Thrall nicht untersteht. Auch nach dem Zweiten Krieg hält der Clan an seinen alten Wegen fest, hasst die Allianz zutiefst und lehnt Friedensangebote ab. Verteidiger der Allianz und unabhängige Reisende betrachten die Orcs des Drachenmals gleichermaßen als tödliche Gegner.",al={"gehört das drachenmal zur horde","clan des drachenmals fraktion","drachenmal thrall"}},{q="Warum sorgt sich die Burg Menethil um den Clan des Drachenmals?",a="Die Burg Menethil ist die Verwaltungs- und Militärfestung, die den Hafen von Menethil schützt, den wichtigsten maritimen Knotenpunkt der Allianz in Khaz Modan. Sumpfbestien und angriffslustige Orcs suchen die Feuchtgebiete rund um den Hafen heim. Hauptmann Starkfaust kann ein schwer bewaffnetes Lager wie die Zuflucht des Drachenmals nahe den Docks und Handelswegen des Königreichs nicht gedeihen lassen.",al={"burg menethil bedrohung durch das drachenmal","warum starkfaust besorgt ist","hafen von menethil verteidigung"}}},fp="18,271,24.276.0,25.378.0,25.349.0,41.274.0,35.290.0,29.311.0,50.325.0,50.342.0"}
P.entries["quest:98297"] = {n="Stopping the Cycle",s="An den Toren des Drachenmals versuchen Hexenmeister, einen roten Drachkin zu versklaven. Howin Kindfeather kehrt mit beunruhigenden Neuigkeiten von einem Testflug zurück, und die Wildhammer werden das nicht noch einmal zulassen.",h="An den Toren des Drachenmals versuchen Hexenmeister, einen roten Drachkin zu versklaven.",kw={"dragonmaw","tore des drachenmals","howin kindfeather","roter drachkin","stopping the cycle","niedergehaltener drachkin","hexenmeister","wildhammer"},sec={{t="An den Toren",b="Howin Kindfeather bittet Euch, Euch dem niedergehaltenen Drachkin an den Toren des Drachenmals zu stellen. Tötet zuerst die Hexenmeister, die ihn niederhalten. Das sollte ihn befreien. Erlöst den Drachkin dann von seinem Leid. Howin erwartet, dass Ihr Freunde mitbringt, denn die Wildhammer werden nicht zulassen, dass die Dragonmaw ihnen im Weg stehen."}},faq={{q="Wer bittet um Hilfe?",a="Howin Kindfeather bittet Euch, die Dragonmaw daran zu hindern, einen roten Drachkin zu versklaven.",al={"wer will das","howins aufgabe"}},{q="Was tun die Dragonmaw?",a="Eine Gruppe von Dragonmaw-Hexenmeistern hält einen roten Drachkin nieder und versucht, ihn zu versklaven.",al={"was tun dragonmaw","warum drachkin niedergehalten"}},{q="Wo ist der Drachkin?",a="Der niedergehaltene Drachkin befindet sich an den Toren des Drachenmals.",al={"drachkin aufenthaltsort","wo niedergehaltener drachkin"}},{q="Worum bittet Howin mich?",a="Howin bittet Euch, die Hexenmeister zu töten, die den Drachkin niederhalten, und ihn dann von seinem Leid zu erlösen.",al={"was tun","kreislauf stoppen"}},{q="Warum sagt Howin, dass die Wildhammer das nicht zulassen dürfen?",a="Howin sagt, dass die Dragonmaw einen roten Drachkin versklaven, und besteht darauf, dass die Wildhammer sie nicht im Weg stehen lassen werden.",al={"warum nicht noch einmal","wildhammer grund"}}},fp="18,188,12.291.0,23.82.0,29.89.0,25.50.0,29.96.0,52.122.0"}
